ALTER PROCEDURE ACCESSORY_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_ASSET DM_ID,
P_AMOUNT DM_DOUBLE,
P_SUM_OF_MONEY DM_DOUBLE,
P_NAME DM_NAME,
P_UNIT DM_UNIT)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY,:P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO ACCESSORIES(COMPANY, ID, ASSET, AMOUNT, SUM_OF_MONEY)
    VALUES(:P_COMPANY, :P_ID, :P_ASSET, :P_AMOUNT, :P_SUM_OF_MONEY);

    UPDATE OR INSERT INTO ACCESSORY_STRINGS(LANGUAGE, COMPANY, ID, NAME, UNIT)
    VALUES(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NAME, :P_UNIT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE ACCESSORY_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ASSET DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE,
NAME DM_NAME,
UNIT DM_UNIT)
AS 
begin
FOR
  SELECT ACCESSORIES.ID, NOTE, ORDINAL, AMOUNT, SUM_OF_MONEY, NAME, UNIT
  FROM ACCESSORIES
  JOIN ACCESSORY_STRINGS ON ACCESSORY_STRINGS.COMPANY = :P_COMPANY AND ACCESSORY_STRINGS.LANGUAGE = :P_LANGUAGE AND ACCESSORY_STRINGS.ID = ACCESSORIES.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ACCESSORY_STRINGS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE ACCESSORIES.COMPANY = :P_COMPANY AND ACCESSORIES.ASSET = :P_ASSET
  INTO :ID, :NOTE, :ORDINAL, :AMOUNT, :SUM_OF_MONEY, :NAME, :UNIT
DO
    SUSPEND;
end ^

ALTER PROCEDURE ACCOUNTING_SETTING_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_BEGINNING_PERIOD DM_ID,
P_MAIN_CURRENCY DM_ID,
P_ON_NOT_EQUAL_VAT DM_ACTION_LEVEL,
P_ON_NOT_EQUAL_SUM DM_ACTION_LEVEL,
P_OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD,
P_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
P_OTHERS DM_OTHER_SETTINGS,
P_APPORTIONMENT_DOCUMENT_TEAM DM_ID,
P_TRANSFER_DOCUMENT_TEAM DM_ID,
P_EXPENSE_DOCUMENT_TEAM DM_ID,
P_PERCENT_DOCUMENT_TEAM DM_ID,
P_DOCUMENT_CODE_CYCLE DM_TIME_TYPE,
P_VAT_DEDUCTION_CYCLE DM_TIME_TYPE,
P_RECORDED_DOCUMENT_CYCLE DM_TIME_TYPE,
P_OUTPUT_INVOICE_SORT_OPTION DM_OUTPUT_INVOICE_SORT_OPTION,
P_LOGO_LOCATION_X DM_INTEGER,
P_LOGO_LOCATION_Y DM_INTEGER)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO ACCOUNTING_SETTINGS(ID, BEGINNING_PERIOD, COMPANY, MAIN_CURRENCY, ON_NOT_EQUAL_VAT, ON_NOT_EQUAL_SUM, OUTPUT_PRICE_METHOD, ACCOUNTING_SYSTEM, OTHERS, APPORTIONMENT_DOCUMENT_TEAM, TRANSFER_DOCUMENT_TEAM, EXPENSE_DOCUMENT_TEAM, PERCENT_DOCUMENT_TEAM, DOCUMENT_CODE_CYCLE, VAT_DEDUCTION_CYCLE, RECORDED_DOCUMENT_CYCLE, OUTPUT_INVOICE_SORT_OPTION, LOGO_LOCATION_X, LOGO_LOCATION_Y)
    VALUES(:P_ID, :P_BEGINNING_PERIOD, :P_COMPANY, :P_MAIN_CURRENCY, :P_ON_NOT_EQUAL_VAT, :P_ON_NOT_EQUAL_SUM, :P_OUTPUT_PRICE_METHOD, :P_ACCOUNTING_SYSTEM, :P_OTHERS, :P_APPORTIONMENT_DOCUMENT_TEAM, :P_TRANSFER_DOCUMENT_TEAM, :P_EXPENSE_DOCUMENT_TEAM, :P_PERCENT_DOCUMENT_TEAM, :P_DOCUMENT_CODE_CYCLE, :P_VAT_DEDUCTION_CYCLE, :P_RECORDED_DOCUMENT_CYCLE, :P_OUTPUT_INVOICE_SORT_OPTION, :P_LOGO_LOCATION_X, :P_LOGO_LOCATION_Y);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE ACCOUNTING_SETTING_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
BEGINNING_PERIOD DM_ID,
MAIN_CURRENCY DM_ID,
ON_NOT_EQUAL_VAT DM_ACTION_LEVEL,
ON_NOT_EQUAL_SUM DM_ACTION_LEVEL,
OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD,
ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
OTHERS DM_OTHER_SETTINGS,
APPORTIONMENT_DOCUMENT_TEAM DM_ID,
TRANSFER_DOCUMENT_TEAM DM_ID,
EXPENSE_DOCUMENT_TEAM DM_ID,
PERCENT_DOCUMENT_TEAM DM_ID,
DOCUMENT_CODE_CYCLE DM_TIME_TYPE,
VAT_DEDUCTION_CYCLE DM_TIME_TYPE,
RECORDED_DOCUMENT_CYCLE DM_TIME_TYPE,
OUTPUT_INVOICE_SORT_OPTION DM_OUTPUT_INVOICE_SORT_OPTION,
LOGO_LOCATION_X DM_INTEGER,
LOGO_LOCATION_Y DM_INTEGER)
AS 
BEGIN
    SELECT ACCOUNTING_SETTINGS.ID, NOTE, ORDINAL, BEGINNING_PERIOD, MAIN_CURRENCY, ON_NOT_EQUAL_VAT, ON_NOT_EQUAL_SUM, OUTPUT_PRICE_METHOD, ACCOUNTING_SYSTEM, OTHERS, APPORTIONMENT_DOCUMENT_TEAM, TRANSFER_DOCUMENT_TEAM, EXPENSE_DOCUMENT_TEAM, PERCENT_DOCUMENT_TEAM, DOCUMENT_CODE_CYCLE, VAT_DEDUCTION_CYCLE, RECORDED_DOCUMENT_CYCLE, OUTPUT_INVOICE_SORT_OPTION, LOGO_LOCATION_X, LOGO_LOCATION_Y
    FROM ACCOUNTING_SETTINGS
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ACCOUNTING_SETTINGS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :ID, :NOTE, :ORDINAL, :BEGINNING_PERIOD, :MAIN_CURRENCY, :ON_NOT_EQUAL_VAT, :ON_NOT_EQUAL_SUM, :OUTPUT_PRICE_METHOD, :ACCOUNTING_SYSTEM, :OTHERS, :APPORTIONMENT_DOCUMENT_TEAM, :TRANSFER_DOCUMENT_TEAM, :EXPENSE_DOCUMENT_TEAM, :PERCENT_DOCUMENT_TEAM, :DOCUMENT_CODE_CYCLE, :VAT_DEDUCTION_CYCLE, :RECORDED_DOCUMENT_CYCLE, :OUTPUT_INVOICE_SORT_OPTION, :LOGO_LOCATION_X, :LOGO_LOCATION_Y;

    SUSPEND;
END ^

ALTER PROCEDURE ACCOUNTING_SETTING_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID)
RETURNS (MAIN_CURRENCY DM_ID,
ON_NOT_EQUAL_VAT DM_ACTION_LEVEL,
ON_NOT_EQUAL_SUM DM_ACTION_LEVEL,
OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD,
OTHERS DM_OTHER_SETTINGS,
MAX_OBJECT DM_SMALLINT,
SHOW_DEBIT_DECREASE DM_BOOL,
SHOW_CREDIT_DECREASE DM_BOOL,
ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
EMPLOYEE DM_ID,
LOGO_LOCATION_X DM_INTEGER,
LOGO_LOCATION_Y DM_INTEGER,
OUTPUT_INVOICE_SORT_OPTION DM_OUTPUT_INVOICE_SORT_OPTION)
AS 
BEGIN
    SELECT MAIN_CURRENCY, ON_NOT_EQUAL_VAT, ON_NOT_EQUAL_SUM, OUTPUT_PRICE_METHOD, ACCOUNTING_SYSTEM, OTHERS, LOGO_LOCATION_X, LOGO_LOCATION_Y,
        OUTPUT_INVOICE_SORT_OPTION
    FROM ACCOUNTING_SETTINGS
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ACCOUNTING_SETTINGS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :MAIN_CURRENCY, :ON_NOT_EQUAL_VAT, :ON_NOT_EQUAL_SUM, :OUTPUT_PRICE_METHOD, :ACCOUNTING_SYSTEM, :OTHERS, :LOGO_LOCATION_X, :LOGO_LOCATION_Y,
        :OUTPUT_INVOICE_SORT_OPTION;

    
    IF(EXISTS(SELECT ATOM_TYPE_2 FROM ACCOUNTS WHERE COMPANY = :P_COMPANY AND ATOM_TYPE_2 IS NOT NULL))THEN
        MAX_OBJECT = 2;
    ELSE IF(EXISTS(SELECT ATOM_TYPE_1 FROM ACCOUNTS WHERE COMPANY = :P_COMPANY AND ATOM_TYPE_1 IS NOT NULL))THEN
        MAX_OBJECT = 1;
    ELSE IF(EXISTS(SELECT ATOM_TYPE_0 FROM ACCOUNTS WHERE COMPANY = :P_COMPANY AND ATOM_TYPE_0 IS NOT NULL))THEN
        MAX_OBJECT = 0;
    ELSE
        MAX_OBJECT = NULL;

    IF(EXISTS(SELECT ACCOUNT_TYPES FROM ACCOUNTS WHERE COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 417792) <> 0))THEN
        SHOW_DEBIT_DECREASE = 1;
    ELSE
        SHOW_DEBIT_DECREASE = 0;

    IF(EXISTS(SELECT ACCOUNT_TYPES FROM ACCOUNTS WHERE COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 1671168) <> 0))THEN
        SHOW_CREDIT_DECREASE = 1;
    ELSE
        SHOW_CREDIT_DECREASE = 0;

    SELECT FIRST 1 ID
    FROM EMPLOYEES
    WHERE EMPLOYEES.COMPANY = :P_COMPANY AND EMPLOYEES.USER_ACCOUNT = :P_USER_ACCOUNT
    INTO :EMPLOYEE;

    SUSPEND;
END ^

ALTER PROCEDURE ACCOUNT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_SMALLINT,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_ENGLISH_NAME DM_NAME,
P_ATOM_TYPE_0 DM_ID,
P_ATOM_TYPE_1 DM_ID,
P_ATOM_TYPE_2 DM_ID,
P_MUST_HAVE_OBJECT DM_MUST_HAVE_OBJECTS,
P_DEFAULT_OBJECT_0 DM_ID,
P_DEFAULT_OBJECT_1 DM_ID,
P_DEFAULT_OBJECT_2 DM_ID,
P_RELATED_OBJECTS DM_RELATED_OBJECTS,
P_ACCOUNT_TYPES DM_ACCOUNT_TYPES,
P_CASH_ACTION_LEVEL DM_ACTION_LEVEL,
P_INVENTORY_ACTION_LEVEL DM_ACTION_LEVEL,
P_BALANCE_TYPE DM_BALANCE_TYPE,
P_OBJECT_TYPE DM_ID)
AS 
DECLARE VARIABLE PARENT_CODE DM_CODE;
DECLARE VARIABLE TEMP_CODE DM_CODE;
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
DECLARE VARIABLE ALLOW_IU DM_BOOL;
BEGIN
    ALLOW_IU = 1;

    IF(P_PARENT IS NULL)THEN
    BEGIN
        SELECT FIRST 1 CODE
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.ID <> :P_ID AND :P_CODE <> ATOMS.CODE AND (:P_CODE STARTING WITH ATOMS.CODE )
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID <> :P_ID
        INTO :PARENT_CODE;

        IF(PARENT_CODE IS NOT NULL)THEN
        BEGIN
            ALLOW_IU = 0;

            SELECT TITLE || '\$' || CONTENT
            FROM MESSAGES
            WHERE ID = 8 AND LANGUAGE = :P_LANGUAGE
            INTO :MESSAGE_CONTENT;

            EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || P_CODE || ' - ' || PARENT_CODE  || ')';
        END
    END
    ELSE 
    BEGIN
        SELECT CODE
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_PARENT
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_PARENT
        INTO :PARENT_CODE;

        IF(P_CODE STARTING WITH PARENT_CODE)THEN 
        BEGIN
            
            
            SELECT FIRST 1 CODE
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.ID <> :P_ID AND ATOMS.ID <> :P_PARENT AND :P_CODE <> ATOMS.CODE AND :P_CODE STARTING WITH ATOMS.CODE AND ATOMS.CODE STARTING WITH :PARENT_CODE
            WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID <> :P_ID AND ACCOUNTS.ID <> :P_PARENT
            INTO :TEMP_CODE;

            IF(TEMP_CODE IS NOT NULL)THEN
            BEGIN
                ALLOW_IU = 0;

                SELECT TITLE || '\$' || CONTENT
                FROM MESSAGES
                WHERE ID = 8 AND LANGUAGE = :P_LANGUAGE
                INTO :MESSAGE_CONTENT;

                EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || P_CODE || ' - ' || TEMP_CODE  || ')';
            END
            ELSE
            IF(EXISTS (SELECT ACCOUNT FROM CREDIT_DEBIT WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND ACCOUNT = :P_PARENT))THEN 
            BEGIN
                ALLOW_IU = 0;

                SELECT TITLE || '\$' || CONTENT
                FROM MESSAGES
                WHERE ID = 2 AND LANGUAGE = :P_LANGUAGE
                INTO :MESSAGE_CONTENT;

                EXCEPTION EX_GENERAL MESSAGE_CONTENT;
            END
        END
        ELSE
        BEGIN
            ALLOW_IU = 0;

            SELECT TITLE || '\$' || CONTENT
            FROM MESSAGES
            WHERE ID = 1 AND LANGUAGE = :P_LANGUAGE
            INTO :MESSAGE_CONTENT;

            EXCEPTION EX_GENERAL MESSAGE_CONTENT;
        END
    END

    
    IF(P_CODE STARTING WITH '0')THEN 
    BEGIN
        
        IF(EXISTS(  SELECT ACCOUNT
                    FROM CREDIT_DEBIT
                    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY AND ENTRIES.ENTRY_TYPE = 1
                    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND ACCOUNT = :P_ID)
        )THEN
        BEGIN
            ALLOW_IU = 0;

            SELECT TITLE || '\$' || CONTENT
            FROM MESSAGES
            WHERE ID = 4 AND LANGUAGE = :P_LANGUAGE
            INTO :MESSAGE_CONTENT;

            EXCEPTION EX_GENERAL MESSAGE_CONTENT;
        END
    END
    ELSE
    BEGIN
        
        IF(EXISTS(  SELECT ACCOUNT
                    FROM CREDIT_DEBIT
                    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY AND ENTRIES.ENTRY_TYPE = 0
                    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND ACCOUNT = :P_ID)
        )THEN
        BEGIN
            ALLOW_IU = 0;

            SELECT TITLE || '\$' || CONTENT
            FROM MESSAGES
            WHERE ID = 3 AND LANGUAGE = :P_LANGUAGE
            INTO :MESSAGE_CONTENT;

            EXCEPTION EX_GENERAL MESSAGE_CONTENT;
        END
    END

    IF(ALLOW_IU = 1)THEN
    BEGIN
        EXECUTE PROCEDURE ATOM_IU_ENGLISH_NAME(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_ENGLISH_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

        UPDATE OR INSERT INTO ACCOUNTS(ID, COMPANY, MUST_HAVE_OBJECT, ATOM_TYPE_0, ATOM_TYPE_1, ATOM_TYPE_2, DEFAULT_OBJECT_0, DEFAULT_OBJECT_1, DEFAULT_OBJECT_2, RELATED_OBJECTS, ACCOUNT_TYPES, CASH_ACTION_LEVEL, INVENTORY_ACTION_LEVEL, BALANCE_TYPE)
        VALUES(:P_ID, :P_COMPANY, :P_MUST_HAVE_OBJECT, :P_ATOM_TYPE_0, :P_ATOM_TYPE_1, :P_ATOM_TYPE_2, :P_DEFAULT_OBJECT_0, :P_DEFAULT_OBJECT_1, :P_DEFAULT_OBJECT_2, :P_RELATED_OBJECTS, :P_ACCOUNT_TYPES, :P_CASH_ACTION_LEVEL, :P_INVENTORY_ACTION_LEVEL, :P_BALANCE_TYPE);

        WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
    END
END ^

ALTER PROCEDURE ACCOUNT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
HIDE DM_SMALLINT,
NAME DM_NAME,
ENGLISH_NAME DM_NAME,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
ATOM_TYPE_0 DM_ID,
ATOM_TYPE_1 DM_ID,
ATOM_TYPE_2 DM_ID,
MUST_HAVE_OBJECT DM_MUST_HAVE_OBJECTS,
DEFAULT_OBJECT_0 DM_ID,
DEFAULT_OBJECT_1 DM_ID,
DEFAULT_OBJECT_2 DM_ID,
RELATED_OBJECTS DM_RELATED_OBJECTS,
ACCOUNT_TYPES DM_ACCOUNT_TYPES,
CASH_ACTION_LEVEL DM_ACTION_LEVEL,
INVENTORY_ACTION_LEVEL DM_ACTION_LEVEL,
BALANCE_TYPE DM_BALANCE_TYPE)
AS 
BEGIN
FOR
  SELECT ACCOUNTS.ID, ORDINAL, NOTE, CODE, LANGUAGE_ATOM_STRINGS.NAME, ENGLISH_ATOM_STRINGS.NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, MUST_HAVE_OBJECT,
  ATOM_TYPE_0, ATOM_TYPE_1, ATOM_TYPE_2,
  DEFAULT_OBJECT_0, DEFAULT_OBJECT_1, DEFAULT_OBJECT_2, RELATED_OBJECTS, ACCOUNT_TYPES, CASH_ACTION_LEVEL, INVENTORY_ACTION_LEVEL, BALANCE_TYPE
  FROM ACCOUNTS
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
  JOIN ATOM_STRINGS LANGUAGE_ATOM_STRINGS ON LANGUAGE_ATOM_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_ATOM_STRINGS.ID = ACCOUNTS.ID
  LEFT JOIN ATOM_STRINGS ENGLISH_ATOM_STRINGS ON ENGLISH_ATOM_STRINGS.COMPANY = :P_COMPANY AND ENGLISH_ATOM_STRINGS.LANGUAGE = 1 AND ENGLISH_ATOM_STRINGS.ID = ACCOUNTS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ACCOUNTS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = ACCOUNTS.ID
  WHERE ACCOUNTS.COMPANY = :P_COMPANY
  ORDER BY CODE
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :ENGLISH_NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :MUST_HAVE_OBJECT,
  :ATOM_TYPE_0, :ATOM_TYPE_1, :ATOM_TYPE_2,
  :DEFAULT_OBJECT_0, :DEFAULT_OBJECT_1, :DEFAULT_OBJECT_2, :RELATED_OBJECTS, :ACCOUNT_TYPES, :CASH_ACTION_LEVEL, :INVENTORY_ACTION_LEVEL, :BALANCE_TYPE
DO
    SUSPEND;
END ^

ALTER PROCEDURE ACCOUNT_S_ID_COMPLEX (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
ATOM_TYPE_0 DM_ID,
ATOM_TYPE_0_NAME DM_NAME,
RELATED_OBJECTS DM_RELATED_OBJECTS,
ATOM_TYPE_1 DM_ID,
ATOM_TYPE_1_NAME DM_NAME,
ATOM_TYPE_2 DM_ID,
ATOM_TYPE_2_NAME DM_NAME,
MUST_HAVE_OBJECT DM_MUST_HAVE_OBJECTS,
DEFAULT_OBJECT_0 DM_ID,
DEFAULT_OBJECT_0_CODE DM_CODE,
DEFAULT_OBJECT_1 DM_ID,
DEFAULT_OBJECT_1_CODE DM_CODE,
DEFAULT_OBJECT_2 DM_ID,
DEFAULT_OBJECT_2_CODE DM_CODE,
ACCOUNT_TYPES DM_ACCOUNT_TYPES,
CASH_ACTION_LEVEL DM_ACTION_LEVEL,
INVENTORY_ACTION_LEVEL DM_ACTION_LEVEL)
AS 
BEGIN
FOR
  SELECT ACCOUNTS.ID, CODE, MUST_HAVE_OBJECT,
  ATOM_TYPE_0, ATOM_TYPE_1, ATOM_TYPE_2,
  DEFAULT_OBJECT_0, DEFAULT_OBJECT_1, DEFAULT_OBJECT_2,
  RELATED_OBJECTS, ACCOUNT_TYPES, CASH_ACTION_LEVEL, INVENTORY_ACTION_LEVEL
  FROM ACCOUNTS
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = :P_ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = :P_ID
  WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ID
  INTO :ID, :CODE, :MUST_HAVE_OBJECT,
  :ATOM_TYPE_0, :ATOM_TYPE_1, :ATOM_TYPE_2,
  :DEFAULT_OBJECT_0, :DEFAULT_OBJECT_1, :DEFAULT_OBJECT_2,
  :RELATED_OBJECTS, :ACCOUNT_TYPES, :CASH_ACTION_LEVEL, :INVENTORY_ACTION_LEVEL
DO
    IF(ATOM_TYPE_0 IS NULL)THEN
    BEGIN
        ATOM_TYPE_0_NAME = NULL;
    END
    ELSE
        SELECT NAME
        FROM OBJECT_TYPES
        WHERE ID = :ATOM_TYPE_0
        INTO :ATOM_TYPE_0_NAME;

    IF(ATOM_TYPE_1 IS NULL)THEN
    BEGIN
        ATOM_TYPE_1_NAME = NULL;
        RELATED_OBJECTS = 0;
    END
    ELSE
    BEGIN
        IF(RELATED_OBJECTS = 1 AND ATOM_TYPE_0 IS NOT NULL)THEN
        BEGIN
            SELECT IIF(OBJECT_TYPES.RELATED_OBJECT_TYPE = :ATOM_TYPE_0, 1, 0)
            FROM OBJECT_TYPES
            WHERE OBJECT_TYPES.ID = :ATOM_TYPE_1
            INTO :RELATED_OBJECTS;
        END
        ELSE
            RELATED_OBJECTS = 0;

        SELECT NAME
        FROM OBJECT_TYPES
        WHERE ID = :ATOM_TYPE_1
        INTO :ATOM_TYPE_1_NAME;
    END

    IF(ATOM_TYPE_2 IS NULL)THEN
    BEGIN
        ATOM_TYPE_2_NAME = NULL;
    END
    ELSE
        SELECT NAME
        FROM OBJECT_TYPES
        WHERE ID = :ATOM_TYPE_2
        INTO :ATOM_TYPE_2_NAME;

    IF(DEFAULT_OBJECT_0 IS NULL)THEN
        DEFAULT_OBJECT_0_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEFAULT_OBJECT_0
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEFAULT_OBJECT_0
        INTO :DEFAULT_OBJECT_0_CODE;

    IF(DEFAULT_OBJECT_1 IS NULL)THEN
        DEFAULT_OBJECT_1_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEFAULT_OBJECT_1
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEFAULT_OBJECT_1
        INTO :DEFAULT_OBJECT_1_CODE;

    IF(DEFAULT_OBJECT_2 IS NULL)THEN
        DEFAULT_OBJECT_2_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEFAULT_OBJECT_2
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEFAULT_OBJECT_2
        INTO :DEFAULT_OBJECT_2_CODE;

    SUSPEND;
END ^

ALTER PROCEDURE ACCOUNT_S_ID_SIMPLE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME)
AS 
BEGIN
FOR
  SELECT ACCOUNTS.ID, CODE, NAME
  FROM ACCOUNTS
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
  WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ID
  INTO :ID, :CODE, :NAME
DO
    SUSPEND;
END ^

ALTER PROCEDURE ACCOUNT_S_RS_ACCOUNT_TYPES (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
ACCOUNT_TYPES DM_ACCOUNT_TYPES)
AS 
begin
FOR
  SELECT ACCOUNTS.ID, CODE, NAME, ACCOUNT_TYPES
  FROM ACCOUNTS
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ACCOUNTS.ID
  WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 768) <> 0
  INTO :ID, :CODE, :NAME, :ACCOUNT_TYPES
DO
    SUSPEND;
end ^

ALTER PROCEDURE ACCOUNT_S_RS_SIMPLE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ONLY_CHILDREN DM_BOOL,
P_ALL_OFFICIAL_EXTRA DM_SMALLINT,
P_SHOW_OBJECTS DM_BOOL)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME)
AS 
BEGIN
    IF(P_ALL_OFFICIAL_EXTRA = 0)THEN
    BEGIN
        FOR
            SELECT ACCOUNTS.ID, CODE, NAME
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND
            (
                :P_ONLY_CHILDREN = 0 OR
                NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID)
            )
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ACCOUNTS.ID
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            ORDER BY CODE
            INTO :ID, :CODE, :NAME
        DO
            SUSPEND;
    END
    ELSE IF(P_ALL_OFFICIAL_EXTRA = 1)THEN
    BEGIN
        IF(P_SHOW_OBJECTS = 0)THEN
        BEGIN
            FOR
                SELECT ACCOUNTS.ID, CODE, NAME
                FROM ACCOUNTS
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND
                ATOMS.CODE NOT STARTING WITH '0' AND
                (
                    :P_ONLY_CHILDREN = 0 OR
                    NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID)
                )
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ACCOUNTS.ID
                WHERE ACCOUNTS.COMPANY = :P_COMPANY
                ORDER BY CODE
                INTO :ID, :CODE, :NAME
            DO
                SUSPEND;
        END
        ELSE
        BEGIN
            FOR
                SELECT ACCOUNTS.ID, ATOMS.CODE, ATOM_STRINGS.NAME || (IIF(ACCOUNTS.ATOM_TYPE_0 IS NULL, '', ' > ' || OBJECT_TYPES_1.NAME)) || (IIF(ACCOUNTS.ATOM_TYPE_1 IS NULL, '', ' > ' || OBJECT_TYPES_2.NAME))
                FROM ACCOUNTS
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND
                ATOMS.CODE NOT STARTING WITH '0' AND
                (
                    :P_ONLY_CHILDREN = 0 OR
                    NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID)
                )
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ACCOUNTS.ID
                LEFT JOIN OBJECT_TYPES OBJECT_TYPES_1 ON OBJECT_TYPES_1.ID = ACCOUNTS.ATOM_TYPE_0
                LEFT JOIN OBJECT_TYPES OBJECT_TYPES_2 ON OBJECT_TYPES_2.ID = ACCOUNTS.ATOM_TYPE_1
                WHERE ACCOUNTS.COMPANY = :P_COMPANY
                ORDER BY CODE
                INTO :ID, :CODE, :NAME
            DO
                SUSPEND;
        END
    END
    ELSE IF(P_ALL_OFFICIAL_EXTRA = 2)THEN
    BEGIN
        FOR
            SELECT ACCOUNTS.ID, CODE, NAME
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND
                ATOMS.CODE STARTING WITH '0' AND
            (
                :P_ONLY_CHILDREN = 0 OR
                NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID)
            )
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ACCOUNTS.ID
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            ORDER BY CODE
            INTO :ID, :CODE, :NAME
        DO
            SUSPEND;
    END
END ^

ALTER PROCEDURE ACCOUNT_TO_ACCOUNT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FROM_COMPANY DM_ID,
P_FROM_ACCOUNT DM_ID,
P_TO_COMPANY DM_ID,
P_TO_ACCOUNT DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO ACCOUNT_TO_ACCOUNT(ID, FROM_COMPANY, FROM_ACCOUNT, TO_COMPANY, TO_ACCOUNT) VALUES(:P_ID, :P_FROM_COMPANY, :P_FROM_ACCOUNT, :P_TO_COMPANY, :P_TO_ACCOUNT);

    IF(P_TO_ACCOUNT IS NOT NULL)THEN
    BEGIN
        UPDATE ACCOUNTS
        SET ACCOUNTS.ATOM_TYPE_0 = (SELECT SOURCE.ATOM_TYPE_0 FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :P_FROM_ACCOUNT),
        ACCOUNTS.ATOM_TYPE_1 = (SELECT SOURCE.ATOM_TYPE_1 FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :P_FROM_ACCOUNT),
        ACCOUNTS.MUST_HAVE_OBJECT = (SELECT SOURCE.MUST_HAVE_OBJECT FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :P_FROM_ACCOUNT),
        ACCOUNTS.BALANCE_TYPE = (SELECT SOURCE.BALANCE_TYPE FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :P_FROM_ACCOUNT)
        WHERE ACCOUNTS.COMPANY = :P_TO_COMPANY AND ACCOUNTS.ID = :P_TO_ACCOUNT;
    END

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE ACCOUNT_TO_ACCOUNT_S_ER (P_LANGUAGE DM_SMALLINT,
P_FROM_COMPANY DM_ID,
P_TO_COMPANY DM_ID,
P_FROM_PERIOD DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
FROM_COMPANY DM_ID,
FROM_ACCOUNT DM_ID,
TO_COMPANY DM_ID,
TO_ACCOUNT DM_ID)
AS 
declare variable has_value dm_bool;
declare variable FROM_DATE dm_DATE;
declare variable FROM_ACCOUNT_CODE dm_CODE;
BEGIN

    if(not exists(
        SELECT *
        from ACCOUNT_TO_ACCOUNT
        WHERE ACCOUNT_TO_ACCOUNT.TO_COMPANY = :P_TO_COMPANY AND ACCOUNT_TO_ACCOUNT.FROM_COMPANY = :P_FROM_COMPANY
    ))then
    begin
        SELECT PERIODS.BEGINNING_DATE
        FROM PERIODS
        WHERE PERIODS.COMPANY = :P_FROM_COMPANY AND ID = :P_FROM_PERIOD
        INTO :FROM_DATE;
    
        FOR
            SELECT ACCOUNT, ATOMS.CODE
            FROM
            (
                SELECT BALANCES.ACCOUNT
                FROM BALANCES
                WHERE BALANCES.COMPANY = :P_FROM_COMPANY AND BALANCES.PERIOD = :P_FROM_PERIOD

                UNION ALL

                SELECT CREDIT_DEBIT.ACCOUNT
                FROM DOCUMENTS
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_FROM_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_FROM_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
                WHERE DOCUMENTS.COMPANY = :P_FROM_COMPANY AND DOCUMENTS.INPUT_DATE >= :FROM_DATE
                
                UNION ALL 
                
                SELECT ASSETS.ASSET_ACCOUNT AS ACCOUNT
                FROM ASSETS
                WHERE ASSETS.COMPANY = :P_FROM_COMPANY AND ASSETS.ASSET_ACCOUNT IS NOT NULL
                
                UNION ALL 
                
                SELECT ASSETS.DEPRECIATION_ACCOUNT AS ACCOUNT
                FROM ASSETS
                WHERE ASSETS.COMPANY = :P_FROM_COMPANY AND ASSETS.DEPRECIATION_ACCOUNT IS NOT NULL
                
                UNION ALL 
                
                SELECT PREPAID_EXPENSES.ACCOUNT
                FROM PREPAID_EXPENSES
                WHERE PREPAID_EXPENSES.COMPANY = :P_FROM_COMPANY AND PREPAID_EXPENSES.ACCOUNT IS NOT NULL
                
                UNION ALL 
                
                SELECT PREPAID_EXPENSES.ACCOUNT_EXPENSE AS ACCOUNT
                FROM PREPAID_EXPENSES
                WHERE PREPAID_EXPENSES.COMPANY = :P_FROM_COMPANY AND PREPAID_EXPENSES.ACCOUNT_EXPENSE IS NOT NULL
            ) A
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_FROM_COMPANY AND ACCOUNTS.ID = A.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_FROM_COMPANY AND ATOMS.ID = A.ACCOUNT AND ATOMS.CODE NOT STARTING WITH '0'
            GROUP BY ACCOUNT, ATOMS.CODE
            INTO :FROM_ACCOUNT, :FROM_ACCOUNT_CODE
        do
        begin
            TO_ACCOUNT = NULL;
            SELECT ACCOUNTS.ID
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_TO_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :FROM_ACCOUNT_CODE
            WHERE ACCOUNTS.COMPANY = :P_TO_COMPANY AND
                NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_TO_COMPANY AND CHILDREN.PARENT = ATOMS.ID)
            INTO :TO_ACCOUNT;
            EXECUTE PROCEDURE ACCOUNT_TO_ACCOUNT_IU(0, P_TO_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, P_FROM_COMPANY, FROM_ACCOUNT, P_TO_COMPANY, TO_ACCOUNT);
        end    
    end
    FOR
        SELECT ACCOUNT_TO_ACCOUNT.ID, ORDINAL, NOTE, FROM_COMPANY, FROM_ACCOUNT, TO_COMPANY, TO_ACCOUNT
        FROM ACCOUNT_TO_ACCOUNT
        JOIN PROTONS ON PROTONS.COMPANY = :P_TO_COMPANY AND PROTONS.ID = ACCOUNT_TO_ACCOUNT.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_TO_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE ACCOUNT_TO_ACCOUNT.TO_COMPANY = :P_TO_COMPANY AND ACCOUNT_TO_ACCOUNT.FROM_COMPANY = :P_FROM_COMPANY
        INTO :ID, :ORDINAL, :NOTE, :FROM_COMPANY, :FROM_ACCOUNT, :TO_COMPANY, :TO_ACCOUNT
    DO
    begin
        SUSPEND;
    end
END ^

