P_OBJECT2 DM_ID,
P_PERCENT DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO APPORTIONMENT_ACCOUNTS(ID, COMPANY, PERIOD, ASSET, ACCOUNT, PERCENT, OBJECT0, OBJECT1, OBJECT2)
    VALUES(:P_ID, :P_COMPANY, :P_PERIOD, :P_ASSET, :P_ACCOUNT, :P_PERCENT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
