ALTER PROCEDURE APPORTIONMENT_ACCOUNT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ASSET DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
ASSET DM_ID,
ACCOUNT DM_ID,
OBJECT0 DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT1 DM_ID,
OBJECT1_CODE DM_CODE,
OBJECT2 DM_ID,
OBJECT2_CODE DM_CODE,
PERCENT DM_DOUBLE)
AS 
begin
    FOR
        SELECT APPORTIONMENT_ACCOUNTS.ID, NOTE, ORDINAL, ASSET, ACCOUNT, PERCENT,
        OBJECT0, OBJECT1, OBJECT2
        FROM APPORTIONMENT_ACCOUNTS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = APPORTIONMENT_ACCOUNTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE APPORTIONMENT_ACCOUNTS.COMPANY = :P_COMPANY AND APPORTIONMENT_ACCOUNTS.ASSET = :P_ASSET AND APPORTIONMENT_ACCOUNTS.PERIOD = :P_PERIOD
        INTO :ID, :NOTE, :ORDINAL, :ASSET, :ACCOUNT, :PERCENT, :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE;

        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE;

        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
            INTO :OBJECT2_CODE;

        SUSPEND;
    END
end ^

