ALTER PROCEDURE ASSET_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_PLACE_OF_MADE DM_ADDRESS,
P_DEPARTMENT DM_ID,
P_PURPOSE DM_PURPOSE,
P_DATE_OF_RISING DM_DATE,
P_DATE_OF_USING DM_DATE,
P_TOTAL_DEPRECIATION_PERIOD DM_SMALLINT,
P_DEPRECIATION_PERIOD DM_DOUBLE,
P_DEPRECIATION_PERCENT DM_DOUBLE,
P_DEPRECIATION_TIME_TYPE DM_TIME_TYPE,
P_BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER,
P_BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER,
P_DEPRECIATION_METHOD DM_DEPRECIATION_METHOD,
P_DEPRECIATION_ACCOUNT DM_ID,
P_ASSET_ACCOUNT DM_ID,
P_EXPENSE_ACCOUNT DM_ID,
P_YEAR_OF_MADE DM_INTEGER,
P_TRANSFER_REPORT DM_TRANSFER_REPORT,
P_DATE_OF_TRANSFER DM_DATE,
P_DATE_OF_SUSPENDED DM_DATE,
P_CAPACITY DM_CAPACITY,
P_SUSPENDED_REASON DM_SUSPENED_REASON,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO ASSETS(COMPANY, ID, DEPARTMENT, DATE_OF_RISING, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_PERCENT, DEPRECIATION_TIME_TYPE, BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, DEPRECIATION_METHOD, DEPRECIATION_ACCOUNT, ASSET_ACCOUNT, EXPENSE_ACCOUNT, YEAR_OF_MADE, TRANSFER_REPORT, DATE_OF_TRANSFER, DATE_OF_SUSPENDED)
    VALUES(:P_COMPANY, :P_ID, :P_DEPARTMENT, :P_DATE_OF_RISING, :P_DATE_OF_USING, :P_TOTAL_DEPRECIATION_PERIOD, :P_DEPRECIATION_PERIOD, :P_DEPRECIATION_PERCENT, :P_DEPRECIATION_TIME_TYPE, :P_BEGINNING_DEPRECIATION_VALUE1, :P_BEGINNING_DEPRECIATION_VALUE2, :P_DEPRECIATION_METHOD, :P_DEPRECIATION_ACCOUNT, :P_ASSET_ACCOUNT, :P_EXPENSE_ACCOUNT, :P_YEAR_OF_MADE, :P_TRANSFER_REPORT, :P_DATE_OF_TRANSFER, :P_DATE_OF_SUSPENDED);

    UPDATE OR INSERT INTO ASSET_STRINGS(COMPANY, ID, LANGUAGE, PLACE_OF_MADE, PURPOSE, CAPACITY, SUSPENDED_REASON)
