    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE ASSET_S_DEPRECIATION (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (ID DM_ID,
DEPRECIATION_DATE DM_DATE,
REMAINING_DEPRECIATION_PERIOD DM_DOUBLE)
AS 
DECLARE VARIABLE DEPRECIATION_PERIOD DM_DOUBLE;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE1 DM_SMALLINT;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE2 DM_SMALLINT;
DECLARE VARIABLE BEGINNING_DATE_OF_PERIOD DM_DATE;
DECLARE VARIABLE ENDING_DATE_OF_PERIOD DM_DATE;
DECLARE VARIABLE ASSET_ACCOUNT DM_ID;
BEGIN
    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD;

    FOR
        SELECT ASSETS.ID, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE,
        BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2,
        ASSET_ACCOUNT
        FROM ASSETS
        WHERE ASSETS.COMPANY = :P_COMPANY
        INTO :ID, :DEPRECIATION_PERIOD, :DEPRECIATION_TIME_TYPE, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2,
        :ASSET_ACCOUNT
    DO
    BEGIN
        IF(DEPRECIATION_TIME_TYPE = 2)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_MONTH_OF_PERIOD, REMAINING_MONTHS
                FROM INT_MONTH_DIFF_ASSET(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
            BEGIN
                IF(EXISTS(
                SELECT *
                FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :ASSET_ACCOUNT, :ID, :DEPRECIATION_DATE)
                WHERE INT_SD_1_TK_1_DT0_CN.DEBIT > 0
                ))THEN
                    SUSPEND;
            END
        END
        ELSE
        IF(DEPRECIATION_TIME_TYPE = 3)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_QUARTER, REMAINING_QUARTERS
                FROM INT_QUARTER_DIFF_ASSET(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                IF(EXISTS(
                SELECT *
                FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :ASSET_ACCOUNT, :ID, :DEPRECIATION_DATE)
                WHERE INT_SD_1_TK_1_DT0_CN.DEBIT > 0
                ))THEN
                    SUSPEND;
        END
        ELSE IF(DEPRECIATION_TIME_TYPE = 4)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_HALF_YEAR, REMAINING_HALF_YEARS
                FROM INT_HALF_YEAR_DIFF_ASSET(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                IF(EXISTS(
                SELECT *
                FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :ASSET_ACCOUNT, :ID, :DEPRECIATION_DATE)
                WHERE INT_SD_1_TK_1_DT0_CN.DEBIT > 0
                ))THEN
                    SUSPEND;
        END
        ELSE IF(DEPRECIATION_TIME_TYPE = 5)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_YEAR, REMAINING_YEARS
                FROM INT_YEAR_DIFF_ASSET(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                IF(EXISTS(
                SELECT *
                FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :ASSET_ACCOUNT, :ID, :DEPRECIATION_DATE)
                WHERE INT_SD_1_TK_1_DT0_CN.DEBIT > 0
                ))THEN
                    SUSPEND;
        END
    END
END ^

ALTER PROCEDURE ASSET_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
PLACE_OF_MADE DM_ADDRESS,
DEPARTMENT DM_ID,
PURPOSE DM_PURPOSE,
DATE_OF_RISING DM_DATE,
DATE_OF_USING DM_DATE,
TOTAL_DEPRECIATION_PERIOD DM_SMALLINT,
DEPRECIATION_PERIOD DM_DOUBLE,
DEPRECIATION_PERCENT DM_DOUBLE,
DEPRECIATION_TIME_TYPE DM_TIME_TYPE,
BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER,
BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER,
DEPRECIATION_METHOD DM_DEPRECIATION_METHOD,
DEPRECIATION_ACCOUNT DM_ID,
ASSET_ACCOUNT DM_ID,
EXPENSE_ACCOUNT DM_ID,
YEAR_OF_MADE DM_INTEGER,
TRANSFER_REPORT DM_TRANSFER_REPORT,
DATE_OF_TRANSFER DM_DATE,
DATE_OF_SUSPENDED DM_DATE,
CAPACITY DM_CAPACITY,
SUSPENDED_REASON DM_SUSPENED_REASON)
AS 
BEGIN
    FOR
        SELECT ASSETS.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, PLACE_OF_MADE,
        DEPARTMENT, PURPOSE, DATE_OF_RISING, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_PERCENT, DEPRECIATION_TIME_TYPE,
        BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, DEPRECIATION_METHOD, DEPRECIATION_ACCOUNT,
        ASSET_ACCOUNT, EXPENSE_ACCOUNT, YEAR_OF_MADE, TRANSFER_REPORT, DATE_OF_TRANSFER, DATE_OF_SUSPENDED, CAPACITY, SUSPENDED_REASON
        FROM ASSETS
        JOIN ASSET_STRINGS ON ASSET_STRINGS.COMPANY = :P_COMPANY AND ASSET_STRINGS.LANGUAGE = :P_LANGUAGE AND ASSET_STRINGS.ID = ASSETS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSETS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE ASSETS.COMPANY = :P_COMPANY
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :PLACE_OF_MADE,
        :DEPARTMENT, :PURPOSE, :DATE_OF_RISING, :DATE_OF_USING, :TOTAL_DEPRECIATION_PERIOD, :DEPRECIATION_PERIOD, :DEPRECIATION_PERCENT, :DEPRECIATION_TIME_TYPE,
        :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_METHOD, :DEPRECIATION_ACCOUNT,
        :ASSET_ACCOUNT, :EXPENSE_ACCOUNT, :YEAR_OF_MADE, :TRANSFER_REPORT, :DATE_OF_TRANSFER, :DATE_OF_SUSPENDED, :CAPACITY, :SUSPENDED_REASON
    DO
        SUSPEND;
END ^

ALTER PROCEDURE ASSET_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_GENERATE_ACCOUNT DM_BOOL = 1)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
ASSET_ACCOUNT_CODE DM_CODE,
DEPRECIATION_ACCOUNT_CODE DM_CODE,
IS_DEFINED DM_BOOL)
AS 
DECLARE VARIABLE EXPENSE_ACCOUNT DM_ID;
BEGIN
    FOR
        SELECT ASSET_S_DEPRECIATION.ID, ASSET_ATOMS.CODE, NAME, ASSET_ACCOUNT_ATOMS.CODE, DEPRECIATION_ACCOUNT_ATOMS.CODE
        FROM ASSET_S_DEPRECIATION(:P_LANGUAGE, :P_COMPANY, :P_PERIOD)
        JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = ASSET_S_DEPRECIATION.ID
        JOIN ATOMS ASSET_ATOMS ON ASSET_ATOMS.COMPANY = :P_COMPANY AND ASSET_ATOMS.ID = ASSETS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ASSET_ATOMS.ID
        JOIN ACCOUNTS ASSET_ACCOUNTS ON ASSET_ACCOUNTS.COMPANY = :P_COMPANY AND ASSET_ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
        JOIN ATOMS ASSET_ACCOUNT_ATOMS ON ASSET_ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ASSET_ACCOUNT_ATOMS.ID = ASSET_ACCOUNTS.ID
        JOIN ACCOUNTS DEPRECIATION_ACCOUNTS ON DEPRECIATION_ACCOUNTS.COMPANY = :P_COMPANY AND DEPRECIATION_ACCOUNTS.ID = ASSETS.DEPRECIATION_ACCOUNT
        JOIN ATOMS DEPRECIATION_ACCOUNT_ATOMS ON DEPRECIATION_ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND DEPRECIATION_ACCOUNT_ATOMS.ID = DEPRECIATION_ACCOUNTS.ID
        GROUP BY ID, ASSET_ATOMS.CODE, NAME, ASSET_ACCOUNT_ATOMS.CODE, DEPRECIATION_ACCOUNT_ATOMS.CODE
        INTO :ID, :CODE, :NAME, :ASSET_ACCOUNT_CODE, :DEPRECIATION_ACCOUNT_CODE
    DO
    BEGIN
        IF(EXISTS (
            SELECT *
            FROM APPORTIONMENT_ACCOUNTS
            WHERE APPORTIONMENT_ACCOUNTS.COMPANY = :P_COMPANY AND APPORTIONMENT_ACCOUNTS.ASSET = :ID AND APPORTIONMENT_ACCOUNTS.PERIOD = :P_PERIOD)
        )
        THEN
            IS_DEFINED = 1;
        ELSE
        BEGIN
            IS_DEFINED = 0;

            
            IF(P_GENERATE_ACCOUNT = 1)THEN
            BEGIN
                SELECT EXPENSE_ACCOUNT
                FROM ASSETS
                JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = EXPENSE_ACCOUNT
                AND ACCOUNTS.ATOM_TYPE_0 IS NULL
                AND ACCOUNTS.ATOM_TYPE_1 IS NULL
                AND ACCOUNTS.ATOM_TYPE_2 IS NULL
                WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = :ID
                INTO :EXPENSE_ACCOUNT;

                IF(EXPENSE_ACCOUNT IS NOT NULL)THEN
                BEGIN
                    EXECUTE PROCEDURE APPORTIONMENT_ACCOUNT_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_PERIOD, :ID, :EXPENSE_ACCOUNT, NULL, NULL, NULL, 1);
                    IS_DEFINED = 1;
                END
            END
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE ASSET_TEAM_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
