ALTER PROCEDURE ASSET_TEAM_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID)
AS 
BEGIN
  FOR
  SELECT ASSET_TEAMS.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
  FROM ASSET_TEAMS
  JOIN TEAMS ON TEAMS.COMPANY = :P_COMPANY AND TEAMS.ID = ASSET_TEAMS.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSET_TEAMS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE ASSET_TEAMS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
  DO
    SUSPEND;
END ^

