ALTER PROCEDURE ATOM_IU_LANGUAGE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO ATOMS(COMPANY, OBJECT_TYPE, ID, CODE, HIDE, PARENT, TEAM, RELATED_OBJECT)
    VALUES(:P_COMPANY, :P_OBJECT_TYPE, :P_ID, :P_CODE, :P_HIDE, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT);

    UPDATE OR INSERT INTO ATOM_STRINGS(ID, NAME, LANGUAGE, COMPANY)
    VALUES(:P_ID, :P_NAME, :P_LANGUAGE, :P_COMPANY);

    IF(NOT EXISTS (SELECT ID FROM ATOM_STRINGS WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = (1 - :P_LANGUAGE) AND ATOM_STRINGS.ID = :P_ID))THEN
    BEGIN
        UPDATE OR INSERT INTO ATOM_STRINGS(ID, NAME, LANGUAGE, COMPANY)
        VALUES(:P_ID, :P_NAME, 1 - :P_LANGUAGE, :P_COMPANY);
    END
END ^

ALTER PROCEDURE ATOM_S_DESCRIPTION (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_OBJECT_TYPE DM_ID,
P_INPUT_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_ENTRY DM_ID,
P_ACCOUNT DM_ID)
RETURNS (DESCRIPTION DM_DESCRIPTION,
UNIT DM_UNIT)
AS 
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE WAREHOUSE_CODE DM_CODE;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE DEBIT DM_DOUBLE;
DECLARE VARIABLE CREDIT DM_DOUBLE;
BEGIN
    IF(P_OBJECT_TYPE IS NULL)THEN
    BEGIN
        SELECT FIRST 1 CODE || ': ' || NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ID
        INTO :DESCRIPTION;
    END
    
    ELSE IF(P_OBJECT_TYPE = 54)THEN
    BEGIN
        SELECT CODE || ': ' || NAME, GOODS_STRINGS.UNIT
        FROM GOODS
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :P_ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.ID = :P_ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        WHERE GOODS.COMPANY = :P_COMPANY AND GOODS.ID = :P_ID
        INTO :DESCRIPTION, :UNIT;

        IF(UNIT IS NOT NULL AND UNIT <> '')THEN
            DESCRIPTION = DESCRIPTION || ' - ' || UNIT;

        SELECT FIRST 1 ID, DOCUMENT
        FROM ENTRIES
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.REVENUE_ENTRY = :P_ENTRY
        INTO :P_ENTRY, :P_DOCUMENT;

        IF(P_INPUT_DATE IS NOT NULL)THEN
        BEGIN
            FOR
                SELECT ACCOUNTS.ID, ATOMS.CODE
                FROM ACCOUNTS
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH '15'
                WHERE ACCOUNTS.COMPANY = :P_COMPANY
                INTO :ACCOUNT, :ACCOUNT_CODE
            DO
            BEGIN
                FOR
                    SELECT WAREHOUSES.ID, ATOMS.CODE
                    FROM WAREHOUSES
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = WAREHOUSES.ID
                    WHERE WAREHOUSES.COMPANY = :P_COMPANY
                    INTO :WAREHOUSE, :WAREHOUSE_CODE
                DO
                BEGIN
                    SELECT AMOUNT, PRICE
                    FROM CMD_GET_PRICE(:P_COMPANY, :ACCOUNT, :P_ID, :WAREHOUSE, :P_INPUT_DATE, :P_DOCUMENT, :P_ENTRY)
                    INTO :AMOUNT, :PRICE;

                    IF(AMOUNT > 0 OR PRICE <> 0)THEN
                        DESCRIPTION = DESCRIPTION || '(TK:' || ACCOUNT_CODE || ',Kho:' || WAREHOUSE_CODE || ',SL:' || ROUND(AMOUNT, 2) || ',DG:' || ROUND(PRICE, 2) || ')';
                END
            END
        END
    END
    ELSE
    BEGIN
        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        WHERE ATOMS.COMPANY = :P_COMPANY AND OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.ID = :P_ID
        INTO :CODE, :NAME;

        IF(P_OBJECT_TYPE = 36)THEN 
        BEGIN
            SELECT :NAME || IIF(CUSTOMERS.TAX_CODE IS NULL OR CUSTOMERS.TAX_CODE = '', '', ' - ' || CUSTOMERS.TAX_CODE)
            FROM CUSTOMERS
            WHERE CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = :P_ID
            INTO :NAME;
        END

        DEBIT = 0;
        CREDIT = 0;

        IF(P_OBJECT_TYPE = 10)THEN 
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_CN(:P_COMPANY,  :P_ID, :P_INPUT_DATE)
            INTO :DEBIT, :CREDIT;
        END
        ELSE IF(P_ACCOUNT IS NOT NULL)THEN
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY,  :P_ACCOUNT, :P_ID, :P_INPUT_DATE)
            INTO :DEBIT, :CREDIT;
        END

        IF(DEBIT = 0 AND CREDIT = 0)THEN
            DESCRIPTION = CODE || ': ' || NAME;
        ELSE IF(DEBIT > CREDIT)THEN
            DESCRIPTION = CODE || '(SD NO: ' || ROUND(DEBIT, 0) || ')' || ': ' || NAME;
        ELSE
            DESCRIPTION = CODE || '(SD CO: ' || ROUND(CREDIT, 0) || ')' || ': ' || NAME;
    END

    SUSPEND;
END ^

ALTER PROCEDURE ATOM_S_R_CN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_HIDE DM_BOOL,
P_OBJECT_TYPE DM_ID,
P_RELATED_OBJECT DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
TEAM_NAME DM_NAME)
AS 
BEGIN
    IF(P_OBJECT_TYPE = 0)THEN
    BEGIN
        FOR
            SELECT OBJECT_TYPES.ID, NULL, NAME, NULL
            FROM OBJECT_TYPES
            WHERE BIN_AND(OBJECT_TYPE, 2) = 2 
            ORDER BY NAME
            INTO :ID, :CODE, :NAME, :TEAM_NAME
        DO
            SUSPEND;
    END
    ELSE
    BEGIN
        IF(P_COMPANY IS NULL)THEN
        BEGIN
            FOR
            SELECT ATOMS.ID, CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.ID = ATOMS.ID AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE
            LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.ID = ATOMS.TEAM AND TEAM_STRINGS.LANGUAGE = :P_LANGUAGE
            WHERE OBJECT_TYPE = :P_OBJECT_TYPE AND (:P_HIDE IS NULL OR HIDE = :P_HIDE) AND ((:P_RELATED_OBJECT IS NULL) OR (ATOMS.RELATED_OBJECT = :P_RELATED_OBJECT))
            ORDER BY CODE
            INTO :ID, :CODE, :NAME, :TEAM_NAME
            DO
                SUSPEND;
        END
        ELSE
        BEGIN
            FOR
                SELECT ATOMS.ID, CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
                FROM ATOMS
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
                LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.COMPANY = :P_COMPANY AND TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_STRINGS.ID = ATOMS.TEAM
                WHERE ATOMS.COMPANY = :P_COMPANY AND (:P_HIDE IS NULL OR HIDE = :P_HIDE) AND OBJECT_TYPE = :P_OBJECT_TYPE AND ((:P_RELATED_OBJECT IS NULL) OR (ATOMS.RELATED_OBJECT = :P_RELATED_OBJECT))
                ORDER BY CODE
                INTO :ID, :CODE, :NAME, :TEAM_NAME
            DO
                SUSPEND;
        END
    END
END ^

ALTER PROCEDURE ATOM_S_R_CN_CODE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_CODE DM_CODE,
P_OBJECT_TYPE DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
TEAM_NAME DM_NAME)
AS 
BEGIN
    IF(P_COMPANY IS NULL)THEN
    BEGIN
        SELECT ATOMS.ID, CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_STRINGS.ID = ATOMS.TEAM
        WHERE OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.CODE = :P_CODE
        ORDER BY CODE
        INTO :ID, :CODE, :NAME, :TEAM_NAME;
    END
    ELSE
    BEGIN
        SELECT ATOMS.ID, CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.COMPANY = :P_COMPANY AND TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_STRINGS.ID = ATOMS.TEAM
        WHERE ATOMS.COMPANY = :P_COMPANY AND OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.CODE = :P_CODE
        ORDER BY CODE
        INTO :ID, :CODE, :NAME, :TEAM_NAME;
    END

    IF(ID IS NOT NULL)THEN
        SUSPEND;
END ^

ALTER PROCEDURE ATOM_S_R_CN_I (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_OBJECT_TYPE DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
TEAM_NAME DM_NAME)
AS 
BEGIN
