    BEGIN
        SELECT OBJECT_TYPES.ID, NULL, NAME, NULL
        FROM OBJECT_TYPES
        WHERE ID = :P_ID
        ORDER BY NAME
        INTO :ID, :CODE, :NAME, :TEAM_NAME;
    END
    ELSE
    IF(P_COMPANY IS NULL)THEN
    BEGIN
        SELECT ATOMS.ID,CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_STRINGS.ID = ATOMS.TEAM
        WHERE OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.ID = :P_ID
        ORDER BY CODE
        INTO :ID, :CODE, :NAME, :TEAM_NAME;
    END
    ELSE
    IF(p_object_type IS NULL)THEN
    BEGIN
        SELECT ATOMS.ID,CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.COMPANY = :P_COMPANY AND TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_STRINGS.ID = ATOMS.TEAM
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ID
        ORDER BY CODE
        INTO :ID, :CODE, :NAME, :TEAM_NAME;
    END
    ELSE
    BEGIN
        SELECT ATOMS.ID,CODE, ATOM_STRINGS.NAME, TEAM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        LEFT JOIN ATOM_STRINGS TEAM_STRINGS ON TEAM_STRINGS.COMPANY = :P_COMPANY AND TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_STRINGS.ID = ATOMS.TEAM
        WHERE ATOMS.COMPANY = :P_COMPANY AND OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.ID = :P_ID
        ORDER BY CODE
        INTO :ID, :CODE, :NAME, :TEAM_NAME;
    END

    IF(ID IS NOT NULL)THEN
        SUSPEND;
END ^

ALTER PROCEDURE BALANCE_D (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
BEGIN
    DELETE FROM BALANCES
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID;

    WHEN ANY DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = SQLCODE AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || SQLCODE || ')';
    END
END ^

ALTER PROCEDURE BALANCE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_PERIOD DM_ID,
P_ACCOUNT DM_ID,
P_CURRENCY DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_AMOUNT DM_DOUBLE,
P_PRICE DM_DOUBLE,
P_FOREIGN_CREDIT DM_DOUBLE,
P_FOREIGN_DEBIT DM_DOUBLE,
P_OFFICIAL_CREDIT DM_DOUBLE,
P_OFFICIAL_DEBIT DM_DOUBLE)
AS 
BEGIN
    UPDATE OR INSERT INTO BALANCES(COMPANY, ID, PERIOD, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, FOREIGN_CREDIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, OFFICIAL_DEBIT, ORDINAL, NOTE)
    VALUES(:P_COMPANY, :P_ID, :P_PERIOD, :P_ACCOUNT, :P_CURRENCY, :P_EXCHANGE_RATE, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_AMOUNT, :P_PRICE, :P_FOREIGN_CREDIT, :P_OFFICIAL_CREDIT, :P_FOREIGN_DEBIT, :P_OFFICIAL_DEBIT, :P_ORDINAL, :P_NOTE);

    
END ^

ALTER PROCEDURE BALANCE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
PERIOD DM_ID,
ACCOUNT DM_ID,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
OBJECT0 DM_ID,
OBJECT1 DM_ID,
OBJECT2 DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT1_CODE DM_CODE,
OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_CREDIT DM_DOUBLE,
FOREIGN_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;
    
    FOR
        SELECT BALANCES.ID, NOTE, ORDINAL, PERIOD, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, FOREIGN_CREDIT, FOREIGN_DEBIT, OFFICIAL_CREDIT, OFFICIAL_DEBIT
        FROM BALANCES
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BALANCES.ACCOUNT AND ((:P_ACCOUNT IS NULL) OR (ATOMS.CODE STARTING WITH :ACCOUNT_CODE))
        WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD
        INTO :ID, :NOTE, :ORDINAL, :PERIOD, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :AMOUNT, :PRICE, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT
    DO
    BEGIN
        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE;
    
        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE;
    
        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
            INTO :OBJECT2_CODE;
    
        SUSPEND;
    END
END ^

ALTER PROCEDURE BANK_ACCOUNT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_BANK_NAME DM_NAME,
P_BRANCH_NAME DM_NAME,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO BANK_ACCOUNTS(COMPANY, ID) VALUES(:P_COMPANY, :P_ID);

    UPDATE OR INSERT INTO BANK_ACCOUNT_STRINGS(COMPANY, ID, LANGUAGE, BANK_NAME, BRANCH_NAME) VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_BANK_NAME, :P_BRANCH_NAME);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE BANK_ACCOUNT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
BANK_NAME DM_NAME,
BRANCH_NAME DM_NAME)
AS 
BEGIN
  FOR
  SELECT BANK_ACCOUNTS.ID, ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, BANK_NAME, BRANCH_NAME
  FROM BANK_ACCOUNTS
  JOIN BANK_ACCOUNT_STRINGS ON BANK_ACCOUNT_STRINGS.COMPANY = :P_COMPANY AND BANK_ACCOUNT_STRINGS.LANGUAGE = :P_LANGUAGE AND BANK_ACCOUNT_STRINGS.ID = BANK_ACCOUNTS.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BANK_ACCOUNTS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE BANK_ACCOUNTS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :BANK_NAME, :BRANCH_NAME
  DO
    SUSPEND;
END ^

ALTER PROCEDURE BAO_CAO_TAI_CHINH_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_DATE_SELECTION_TYPE DM_SELECTION_TYPES,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE,
P_SIGNED_DATE DM_DATE,
P_DIRECTOR DM_PERSON_NAME)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO BAO_CAO_TAI_CHINH(ID, COMPANY, DATE_SELECTION_TYPE, FROM_DATE, TO_DATE,
    SIGNED_DATE,
    DIRECTOR)
    VALUES(:P_ID, :P_COMPANY, :P_DATE_SELECTION_TYPE, :P_FROM_DATE, :P_TO_DATE,
    :P_SIGNED_DATE,
    :P_DIRECTOR);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE BAO_CAO_TAI_CHINH_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE_SELECTION_TYPE DM_SELECTION_TYPES,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE,
P_IS_STORED DM_BOOL)
RETURNS (TAX_CODE DM_TAX_CODE,
ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
SIGNED_DATE DM_DATE,
DIRECTOR DM_PERSON_NAME)
AS 
DECLARE VARIABLE COMPANY_DIRECTOR DM_PERSON_NAME;
BEGIN
    SELECT DIRECTOR,
        IIF(TAX_CODE_1 IS NULL, '', TAX_CODE_1) ||
        IIF(TAX_CODE_2 IS NULL, '', TAX_CODE_2) ||
        IIF(TAX_CODE_3 IS NULL, '', TAX_CODE_3) ||
        IIF(TAX_CODE_4 IS NULL, '', TAX_CODE_4) ||
        IIF(TAX_CODE_5 IS NULL, '', TAX_CODE_5) ||
        IIF(TAX_CODE_6 IS NULL, '', TAX_CODE_6) ||
        IIF(TAX_CODE_7 IS NULL, '', TAX_CODE_7) ||
        IIF(TAX_CODE_8 IS NULL, '', TAX_CODE_8) ||
        IIF(TAX_CODE_9 IS NULL, '', TAX_CODE_9) ||
        IIF(TAX_CODE_10 IS NULL, '', TAX_CODE_10) ||
        IIF(TAX_CODE_11 IS NULL, '', TAX_CODE_11) ||
        IIF(TAX_CODE_12 IS NULL, '', TAX_CODE_12) ||
        IIF(TAX_CODE_13 IS NULL, '', TAX_CODE_13)
    FROM COMPANIES
    JOIN COMPANY_STRINGS ON COMPANY_STRINGS.LANGUAGE = :P_LANGUAGE AND COMPANY_STRINGS.ID = :P_COMPANY
    WHERE COMPANIES.ID = :P_COMPANY
    INTO :COMPANY_DIRECTOR, :TAX_CODE;

    SELECT BAO_CAO_TAI_CHINH.ID, NOTE, ORDINAL,
    SIGNED_DATE,
    DIRECTOR
    FROM BAO_CAO_TAI_CHINH
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = BAO_CAO_TAI_CHINH.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE BAO_CAO_TAI_CHINH.COMPANY = :P_COMPANY AND BAO_CAO_TAI_CHINH.DATE_SELECTION_TYPE = :P_DATE_SELECTION_TYPE AND BAO_CAO_TAI_CHINH.FROM_DATE = :P_FROM_DATE AND BAO_CAO_TAI_CHINH.TO_DATE = :P_TO_DATE
    INTO :ID, :NOTE, :ORDINAL,
    :SIGNED_DATE,
    :DIRECTOR;

    IF(ID IS NULL OR P_IS_STORED = 0)THEN
    BEGIN
        IF(ID IS NULL)THEN
            ID = GEN_ID(UNIVERSE, 1);

        ORDINAL = 0;
        SIGNED_DATE = CURRENT_DATE;
        DIRECTOR = COMPANY_DIRECTOR;
    END

    SUSPEND;
END ^

ALTER PROCEDURE BEGINNING_DOCUMENT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_PERIOD DM_ID,
P_INPUT_DATE DM_DATE,
P_CODE DM_DOCUMENT_CODE,
P_CONTENT DM_CONTENT,
P_ACCOUNT DM_ID,
P_CURRENCY DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_FOREIGN_CREDIT DM_DOUBLE,
P_FOREIGN_DEBIT DM_DOUBLE,
P_OFFICIAL_CREDIT DM_DOUBLE,
