    UPDATE OR INSERT INTO BEGINNING_DOCUMENTS(COMPANY, ID, PERIOD, INPUT_DATE, CODE, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, FOREIGN_CREDIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, OFFICIAL_DEBIT)
    VALUES(:P_COMPANY, :P_ID, :P_PERIOD, :P_INPUT_DATE, :P_CODE, :P_ACCOUNT, :P_CURRENCY, :P_EXCHANGE_RATE, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_FOREIGN_CREDIT, :P_OFFICIAL_CREDIT, :P_FOREIGN_DEBIT, :P_OFFICIAL_DEBIT);

    
    UPDATE OR INSERT INTO DOCUMENT_BALANCES(ID, COMPANY, INCREASE_DOCUMENT, PERIOD, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, OFFICIAL_DEBIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, FOREIGN_CREDIT)
    VALUES(:P_ID, :P_COMPANY, :P_ID, :P_PERIOD, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_OFFICIAL_DEBIT, :P_OFFICIAL_CREDIT, :P_FOREIGN_DEBIT, :P_FOREIGN_CREDIT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE BEGINNING_DOCUMENT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
PERIOD DM_ID,
INPUT_DATE DM_DATE,
CODE DM_DOCUMENT_CODE,
CONTENT DM_CONTENT,
ACCOUNT DM_ID,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
OBJECT0 DM_ID,
OBJECT1 DM_ID,
OBJECT2 DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT1_CODE DM_CODE,
OBJECT2_CODE DM_CODE,
FOREIGN_CREDIT DM_DOUBLE,
FOREIGN_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
BEGIN

SELECT CODE
FROM ATOMS
WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
INTO :ACCOUNT_CODE;

FOR
    SELECT BEGINNING_DOCUMENTS.ID, NOTE, ORDINAL, PERIOD, INPUT_DATE, BEGINNING_DOCUMENTS.CODE, DOCUMENT_BASE_STRINGS.CONTENT, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, FOREIGN_CREDIT, FOREIGN_DEBIT, OFFICIAL_CREDIT, OFFICIAL_DEBIT
    FROM BEGINNING_DOCUMENTS
    JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = BEGINNING_DOCUMENTS.ID
    JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BEGINNING_DOCUMENTS.ACCOUNT AND ((:P_ACCOUNT IS NULL) OR (ATOMS.CODE STARTING WITH :ACCOUNT_CODE))
    WHERE BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD
    INTO :ID, :NOTE, :ORDINAL, :PERIOD, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT
DO
BEGIN
    IF(OBJECT0 IS NULL)THEN
        OBJECT0_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
        INTO :OBJECT0_CODE;

    IF(OBJECT1 IS NULL)THEN
        OBJECT1_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
        INTO :OBJECT1_CODE;

    IF(OBJECT2 IS NULL)THEN
        OBJECT2_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
        INTO :OBJECT2_CODE;

    SUSPEND;
END
END ^

