    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BEGINNING_ENTRIES.ACCOUNT AND ((:P_ACCOUNT IS NULL) OR (ATOMS.CODE STARTING WITH :ACCOUNT_CODE))
    WHERE BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD
