ALTER PROCEDURE CMD_ACTIVE_ALL_TRIGGERS AS 
DECLARE VARIABLE TRIGGER_NAME VARCHAR(31);
BEGIN
    FOR
        SELECT RDB$TRIGGERS.RDB$TRIGGER_NAME FROM RDB$TRIGGERS
        WHERE RDB$TRIGGERS.RDB$SYSTEM_FLAG = 0 AND RDB$TRIGGERS.RDB$TRIGGER_INACTIVE = 1
        INTO :TRIGGER_NAME
    DO
    BEGIN
        EXECUTE STATEMENT 'ALTER TRIGGER ' || :TRIGGER_NAME || ' ACTIVE';
    END
END ^

ALTER PROCEDURE CMD_ALTER_WAREHOUSE (P_COMPANY DM_ID,
P_FROM_DATE DM_DATE,
P_AMOUNT DM_DOUBLE,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TO_ACCOUNT DM_ID,
P_TO_OBJECT0 DM_ID,
P_TO_OBJECT1 DM_ID)
AS 
DECLARE VARIABLE HAS DM_BOOL;
DECLARE VARIABLE ENTRY DM_ID;
DECLARE VARIABLE CREDIT DM_ID;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OBJECT0_CODE DM_CODE;
DECLARE VARIABLE OBJECT1_CODE DM_CODE;
DECLARE VARIABLE TO_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE TO_OBJECT0_CODE DM_CODE;
DECLARE VARIABLE TO_OBJECT1_CODE DM_CODE;
DECLARE VARIABLE NEED DM_DOUBLE;
DECLARE VARIABLE TOTAL DM_DOUBLE;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
DECLARE VARIABLE VAT_PERCENT DM_DOUBLE;
DECLARE VARIABLE CONTENT DM_CONTENT;
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT2 DM_ID;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE NEW_FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE NEW_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    NEED = P_AMOUNT;
    HAS = 1;
    TOTAL = 0;
    WHILE(P_AMOUNT > 0 AND HAS = 1)DO
    BEGIN
        HAS = 0;
        FOR
            SELECT FIRST 1 DOCUMENTS.ID, ENTRIES.ID, CREDIT.ID, CREDIT.AMOUNT, CREDIT.PRICE, CREDIT.FOREIGN_SUM_OF_MONEY, CREDIT.OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND
                            CREDIT.ACCOUNT = :P_ACCOUNT AND CREDIT.OBJECT0 = :P_OBJECT0 AND
                            ((:P_OBJECT1 IS NULL AND CREDIT.OBJECT1 IS NULL) OR CREDIT.OBJECT1 = :P_OBJECT1)
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE >= :P_FROM_DATE
            ORDER BY DOCUMENTS.INPUT_DATE ASC
            INTO :DOCUMENT, :ENTRY, :CREDIT, :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY
        DO
        BEGIN
            HAS = 1;
            IF(P_AMOUNT >= AMOUNT)THEN
            BEGIN
                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.ACCOUNT = :P_TO_ACCOUNT,
                    CREDIT_DEBIT.OBJECT0 = :P_TO_OBJECT0,
                    CREDIT_DEBIT.OBJECT1 = :P_TO_OBJECT1
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ID = :CREDIT;

                P_AMOUNT = P_AMOUNT - AMOUNT;
                TOTAL = TOTAL + AMOUNT;
            END
            ELSE
            BEGIN
                
                SELECT CURRENCY, EXCHANGE_RATE, VAT_PERCENT, ENTRY_BASE_STRINGS.CONTENT,
                DEBIT.ACCOUNT, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.OBJECT2
                FROM ENTRIES
                JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = 0
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.ID = :ENTRY AND ENTRIES.DOCUMENT = :DOCUMENT
                INTO :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, :CONTENT,
                :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2;

                NEW_FOREIGN_SUM_OF_MONEY = ROUND(PRICE*P_AMOUNT, NUMBER_DECIMAL_DIGITS);
                NEW_OFFICIAL_SUM_OF_MONEY = ROUND(NEW_FOREIGN_SUM_OF_MONEY*EXCHANGE_RATE, 0);

                FOREIGN_SUM_OF_MONEY = FOREIGN_SUM_OF_MONEY - NEW_FOREIGN_SUM_OF_MONEY;
                OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - NEW_OFFICIAL_SUM_OF_MONEY;

                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.AMOUNT = CREDIT_DEBIT.AMOUNT - :P_AMOUNT,
                    CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = :FOREIGN_SUM_OF_MONEY,
                    CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :OFFICIAL_SUM_OF_MONEY
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY;

                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(0, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, CURRENCY, DOCUMENT, EXCHANGE_RATE, VAT_PERCENT, 0, NULL, NULL, CONTENT, GEN_ID(UNIVERSE, 1), DEBIT_ACCOUNT, DEBIT_OBJECT0, DEBIT_OBJECT1, DEBIT_OBJECT2, GEN_ID(UNIVERSE, 1), P_TO_ACCOUNT, P_TO_OBJECT0, P_TO_OBJECT1, NULL, P_AMOUNT, PRICE, NEW_FOREIGN_SUM_OF_MONEY, NEW_OFFICIAL_SUM_OF_MONEY);

                TOTAL = TOTAL + P_AMOUNT;
                P_AMOUNT = 0;
            END
        END
    END

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
    INTO :OBJECT0_CODE;
    IF(OBJECT0_CODE IS NULL)THEN OBJECT0_CODE = '';

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT1
    INTO :OBJECT1_CODE;
    IF(OBJECT1_CODE IS NULL)THEN OBJECT1_CODE = '';

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_TO_ACCOUNT
    INTO :TO_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_TO_OBJECT0
    INTO :TO_OBJECT0_CODE;
    IF(TO_OBJECT0_CODE IS NULL)THEN TO_OBJECT0_CODE = '';

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_TO_OBJECT1
    INTO :TO_OBJECT1_CODE;
    IF(TO_OBJECT1_CODE IS NULL)THEN TO_OBJECT1_CODE = '';

    EXECUTE PROCEDURE LOG_IU(:P_COMPANY, P_FROM_DATE, ACCOUNT_CODE || '(' || OBJECT0_CODE || ',' || OBJECT1_CODE || ')', TO_ACCOUNT_CODE || '(' || TO_OBJECT0_CODE || ',' || TO_OBJECT1_CODE || ')', NEED || ' > ' || TOTAL);
END ^

ALTER PROCEDURE CMD_APPORTIONMENT_ASSET (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ASSET DM_ID,
P_ASSET_ACCOUNT DM_ID,
P_REMAINING_DEPRECIATION_PERIOD DM_DOUBLE,
P_DEPRECIATION_PERCENT DM_DOUBLE,
P_DEPRECIATION_METHOD DM_DEPRECIATION_METHOD,
P_DEPRECIATION_ACCOUNT DM_ID,
P_CURRENCY DM_ID,
P_NOW_DATE DM_DATE,
P_DOCUMENT_CONTENT DM_CONTENT,
P_ENTRY_CONTENT DM_CONTENT,
P_APPORTIONMENT_DOCUMENT_TEAM DM_ID)
AS 
DECLARE VARIABLE DEPRECIATION_VALUE DM_DOUBLE;
DECLARE VARIABLE ORIGINAL_VALUE DM_DOUBLE;
DECLARE VARIABLE APPORTIONMENT_VALUE DM_DOUBLE;
DECLARE VARIABLE APPORTIONMENT_ACCOUNT DM_ID;
DECLARE VARIABLE APPORTIONMENT_PERCENT DM_DOUBLE;
DECLARE VARIABLE APPORTIONMENT_OBJECT0 DM_ID;
DECLARE VARIABLE APPORTIONMENT_OBJECT1 DM_ID;
DECLARE VARIABLE APPORTIONMENT_OBJECT2 DM_ID;
DECLARE VARIABLE ENTRY_VALUE DM_DOUBLE;
DECLARE VARIABLE SUM_PERCENT DM_DOUBLE;
DECLARE VARIABLE SUM_VALUE DM_DOUBLE;
BEGIN
    
    SELECT DEBIT
    FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :P_ASSET_ACCOUNT, :P_ASSET, :P_NOW_DATE)
    INTO :ORIGINAL_VALUE;

    SELECT CREDIT
    FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :P_DEPRECIATION_ACCOUNT, :P_ASSET, :P_NOW_DATE)
    INTO :APPORTIONMENT_VALUE;

    ORIGINAL_VALUE = ORIGINAL_VALUE - APPORTIONMENT_VALUE;

    
    IF(ORIGINAL_VALUE > 0)THEN
    BEGIN
        IF(P_DEPRECIATION_METHOD = 0 AND P_DEPRECIATION_PERCENT > 0)THEN 
            DEPRECIATION_VALUE = ROUND(ORIGINAL_VALUE * P_DEPRECIATION_PERCENT, 0);
        ELSE IF(P_DEPRECIATION_METHOD = 1 AND P_REMAINING_DEPRECIATION_PERIOD > 0)THEN 
        BEGIN
            
            IF(P_REMAINING_DEPRECIATION_PERIOD <= 1)THEN
                DEPRECIATION_VALUE = ORIGINAL_VALUE;
            ELSE
                DEPRECIATION_VALUE = ROUND(ORIGINAL_VALUE/P_REMAINING_DEPRECIATION_PERIOD, 0);
        END

        
        IF(DEPRECIATION_VALUE > 0)THEN
        BEGIN
            SUM_PERCENT = 0;
            SUM_VALUE = 0;

            FOR
                SELECT PERCENT, ACCOUNT, OBJECT0, OBJECT1, OBJECT2
                FROM APPORTIONMENT_ACCOUNTS
                WHERE COMPANY = :P_COMPANY AND ASSET = :P_ASSET AND PERIOD = :P_PERIOD
                INTO :APPORTIONMENT_PERCENT, :APPORTIONMENT_ACCOUNT, :APPORTIONMENT_OBJECT0, :APPORTIONMENT_OBJECT1, :APPORTIONMENT_OBJECT2
            DO
            BEGIN
                SUM_PERCENT = SUM_PERCENT + APPORTIONMENT_PERCENT;

                IF(SUM_PERCENT = 1)THEN ENTRY_VALUE = DEPRECIATION_VALUE - SUM_VALUE;
                ELSE ENTRY_VALUE = ROUND(DEPRECIATION_VALUE*APPORTIONMENT_PERCENT, 0);

                SUM_VALUE = SUM_VALUE + ENTRY_VALUE;

                IF(ENTRY_VALUE > 0)THEN
                BEGIN
                    EXECUTE PROCEDURE DOCUMENT_DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, NULL, 0, NULL, NULL, NULL, NULL, :P_CURRENCY, 1, :P_NOW_DATE, NULL, NULL, :P_PERIOD, :P_APPORTIONMENT_DOCUMENT_TEAM, :P_NOW_DATE, NULL, NULL, NULL, :P_DOCUMENT_CONTENT, :ENTRY_VALUE, NULL, 0, NULL, :P_ENTRY_CONTENT, :APPORTIONMENT_ACCOUNT, :APPORTIONMENT_OBJECT0, :APPORTIONMENT_OBJECT1, :APPORTIONMENT_OBJECT2, :P_DEPRECIATION_ACCOUNT, :P_ASSET, NULL, NULL, 0, 0, 0, :ENTRY_VALUE);
                END
            END
        END
    END
END ^

ALTER PROCEDURE CMD_APPORTIONMENT_ASSET_NEW (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ASSET DM_ID,
P_ASSET_ACCOUNT DM_ID,
P_REMAINING_DEPRECIATION_PERIOD DM_DOUBLE,
P_DEPRECIATION_PERCENT DM_DOUBLE,
P_DEPRECIATION_METHOD DM_DEPRECIATION_METHOD,
P_DEPRECIATION_ACCOUNT DM_ID,
P_CURRENCY DM_ID,
P_NOW_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_ENTRY_CONTENT DM_CONTENT)
AS 
DECLARE VARIABLE DEPRECIATION_VALUE DM_DOUBLE;
DECLARE VARIABLE ORIGINAL_VALUE DM_DOUBLE;
DECLARE VARIABLE APPORTIONMENT_VALUE DM_DOUBLE;
DECLARE VARIABLE APPORTIONMENT_ACCOUNT DM_ID;
DECLARE VARIABLE APPORTIONMENT_PERCENT DM_DOUBLE;
DECLARE VARIABLE APPORTIONMENT_OBJECT0 DM_ID;
DECLARE VARIABLE APPORTIONMENT_OBJECT1 DM_ID;
DECLARE VARIABLE APPORTIONMENT_OBJECT2 DM_ID;
DECLARE VARIABLE ENTRY_VALUE DM_DOUBLE;
DECLARE VARIABLE SUM_PERCENT DM_DOUBLE;
DECLARE VARIABLE SUM_VALUE DM_DOUBLE;
BEGIN
    
    SELECT DEBIT
    FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :P_ASSET_ACCOUNT, :P_ASSET, :P_NOW_DATE)
    INTO :ORIGINAL_VALUE;

    SELECT CREDIT
    FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :P_DEPRECIATION_ACCOUNT, :P_ASSET, :P_NOW_DATE)
    INTO :APPORTIONMENT_VALUE;

    ORIGINAL_VALUE = ORIGINAL_VALUE - APPORTIONMENT_VALUE;

    
    IF(ORIGINAL_VALUE > 0)THEN
    BEGIN
        IF(P_DEPRECIATION_METHOD = 0 AND P_DEPRECIATION_PERCENT > 0)THEN 
            DEPRECIATION_VALUE = ROUND(ORIGINAL_VALUE * P_DEPRECIATION_PERCENT, 0);
        ELSE IF(P_DEPRECIATION_METHOD = 1 AND P_REMAINING_DEPRECIATION_PERIOD > 0)THEN 
        BEGIN
            
            IF(P_REMAINING_DEPRECIATION_PERIOD <= 1)THEN
                DEPRECIATION_VALUE = ORIGINAL_VALUE;
            ELSE
                DEPRECIATION_VALUE = ROUND(ORIGINAL_VALUE/P_REMAINING_DEPRECIATION_PERIOD, 0);
        END

        
        IF(DEPRECIATION_VALUE > 0)THEN
        BEGIN
            SUM_PERCENT = 0;
            SUM_VALUE = 0;

            FOR
                SELECT PERCENT, ACCOUNT, OBJECT0, OBJECT1, OBJECT2
                FROM APPORTIONMENT_ACCOUNTS
                WHERE COMPANY = :P_COMPANY AND ASSET = :P_ASSET AND PERIOD = :P_PERIOD
                INTO :APPORTIONMENT_PERCENT, :APPORTIONMENT_ACCOUNT, :APPORTIONMENT_OBJECT0, :APPORTIONMENT_OBJECT1, :APPORTIONMENT_OBJECT2
            DO
            BEGIN
                SUM_PERCENT = SUM_PERCENT + APPORTIONMENT_PERCENT;

                IF(SUM_PERCENT = 1)THEN ENTRY_VALUE = DEPRECIATION_VALUE - SUM_VALUE;
                ELSE ENTRY_VALUE = ROUND(DEPRECIATION_VALUE*APPORTIONMENT_PERCENT, 0);

                SUM_VALUE = SUM_VALUE + ENTRY_VALUE;

                IF(ENTRY_VALUE > 0)THEN
                BEGIN
                    EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, 1, NULL, 0, NULL, NULL, :P_ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :APPORTIONMENT_ACCOUNT, :APPORTIONMENT_OBJECT0, :APPORTIONMENT_OBJECT1, :APPORTIONMENT_OBJECT2, GEN_ID(UNIVERSE, 1), :P_DEPRECIATION_ACCOUNT, :P_ASSET, NULL, NULL, 0, 0, 0, :ENTRY_VALUE);
                END
            END
        END
    END
END ^

