                    SUM_VALUE = SUM_VALUE + ENTRY_VALUE;
            
                    IF(ENTRY_VALUE > 0)THEN
                    BEGIN
                        EXECUTE PROCEDURE DOCUMENT_DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, NULL, 0, NULL, NULL, NULL, NULL, :P_CURRENCY, 1, :P_NOW_DATE, NULL, NULL, :P_PERIOD, :P_APPORTIONMENT_DOCUMENT_TEAM, :P_NOW_DATE, NULL, NULL, NULL, :P_DOCUMENT_CONTENT, :ENTRY_VALUE, NULL, 0, NULL, :P_ENTRY_CONTENT, :APPORTIONMENT_ACCOUNT, :APPORTIONMENT_OBJECT0, :APPORTIONMENT_OBJECT1, :APPORTIONMENT_OBJECT2, :P_EXPENSE_ACCOUNT, :P_PREPAID_EXPENSE, :OBJECT1, NULL, 0, 0, 0, :ENTRY_VALUE);
                    END
                END
            END
        END
    END
END ^

