ALTER PROCEDURE CMD_ASSET_TO_PREPAID_EXPENSE (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE DATE_OF_USING DM_DATE;
DECLARE VARIABLE TOTAL_DEPRECIATION_PERIOD DM_SMALLINT;
DECLARE VARIABLE DEPRECIATION_PERIOD DM_DOUBLE;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER;
DECLARE VARIABLE ASSET_ACCOUNT DM_ID;
DECLARE VARIABLE EXPENSE_ACCOUNT DM_ID;
BEGIN
    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE,
        BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2,
        ASSET_ACCOUNT, EXPENSE_ACCOUNT
        FROM ASSETS
        JOIN ASSET_STRINGS ON ASSET_STRINGS.COMPANY = :P_COMPANY AND ASSET_STRINGS.LANGUAGE = 0 AND ASSET_STRINGS.ID = ASSETS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSETS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = 0 AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = 0 AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = :P_ID
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE,
        :DATE_OF_USING, :TOTAL_DEPRECIATION_PERIOD, :DEPRECIATION_PERIOD, :DEPRECIATION_TIME_TYPE,
        :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2,
        :ASSET_ACCOUNT, :EXPENSE_ACCOUNT
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT PREPAID_EXPENSES.ID
            FROM PREPAID_EXPENSES
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PREPAID_EXPENSES.ID AND ATOMS.CODE = :CODE
            WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY
        ))THEN
        BEGIN
            EXECUTE PROCEDURE PREPAID_EXPENSE_IU(0, P_COMPANY, GEN_ID(UNIVERSE, 1), NOTE, ORDINAL, CODE, HIDE, NAME, NULL, NULL, NULL, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, BEGINNING_DEPRECIATION_VALUE1,BEGINNING_DEPRECIATION_VALUE2, ASSET_ACCOUNT, EXPENSE_ACCOUNT, DATE_OF_USING, 96);
        END
    END
END ^

ALTER PROCEDURE CMD_BATCH_PRICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAMS DM_NAME,
P_ACCOUNT DM_ID = NULL)
RETURNS (INPUT_DATE DM_DATE,
ACCOUNT_GOODS_WAREHOUSE DM_STRING,
REMAINING_AMOUNT DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT_TEAM_ID DM_ID;
BEGIN
    DELETE FROM TEMP_BATCH_PRICE;

    FOR
        SELECT ID
        FROM INT_SPLIT_STRING(:P_DOCUMENT_TEAMS, ',')
        INTO :DOCUMENT_TEAM_ID
    DO
    BEGIN
        EXECUTE PROCEDURE CMD_TEMP_BATCH_PRICE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :DOCUMENT_TEAM_ID, :P_ACCOUNT);
    END

    FOR
        SELECT INPUT_DATE, ACCOUNT_GOODS_WAREHOUSE, REMAINING_AMOUNT
        FROM CMD_CAL_BATCH_PRICE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD)
        INTO :INPUT_DATE, :ACCOUNT_GOODS_WAREHOUSE, :REMAINING_AMOUNT
    DO
    BEGIN
        SUSPEND;
    END
END ^

ALTER PROCEDURE CMD_CAL_BATCH_PRICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (INPUT_DATE DM_DATE,
ACCOUNT_GOODS_WAREHOUSE DM_STRING,
REMAINING_AMOUNT DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE ENTRY DM_ID;
DECLARE VARIABLE DEBIT DM_ID;
DECLARE VARIABLE CREDIT DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE GOODS DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    FOR
        SELECT DOCUMENT, INPUT_DATE, ENTRY, DEBIT, CREDIT, ACCOUNT, GOODS, WAREHOUSE, AMOUNT
        FROM TEMP_BATCH_PRICE
        ORDER BY TEMP_BATCH_PRICE.INPUT_DATE, TEMP_BATCH_PRICE.DOCUMENT, TEMP_BATCH_PRICE.ENTRY
        INTO :DOCUMENT, :INPUT_DATE, :ENTRY, :DEBIT, :CREDIT, :ACCOUNT, :GOODS, :WAREHOUSE, :AMOUNT
    DO
    BEGIN
        
        
        SELECT REMAINING_AMOUNT
        FROM INT_FILIFO_ENTRY(:P_COMPANY, :INPUT_DATE, :ACCOUNT, :GOODS, :WAREHOUSE, NULL, :AMOUNT, :CREDIT, 1, :NUMBER_DECIMAL_DIGITS)
        INTO :REMAINING_AMOUNT;

        IF(REMAINING_AMOUNT > 0 )THEN
        BEGIN
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER
            FROM DOCUMENTS
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :DOCUMENT
            INTO :ACCOUNT_GOODS_WAREHOUSE;
            
            SELECT :ACCOUNT_GOODS_WAREHOUSE || ', TK: ' || CODE
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :ACCOUNT
            WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :ACCOUNT
            INTO :ACCOUNT_GOODS_WAREHOUSE;

            SELECT :ACCOUNT_GOODS_WAREHOUSE || ', ' || CODE
            FROM GOODS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :GOODS
            WHERE GOODS.COMPANY = :P_COMPANY AND GOODS.ID = :GOODS
            INTO :ACCOUNT_GOODS_WAREHOUSE;

            SELECT :ACCOUNT_GOODS_WAREHOUSE || ', ' || CODE
            FROM WAREHOUSES
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :WAREHOUSE
            WHERE WAREHOUSES.COMPANY = :P_COMPANY AND WAREHOUSES.ID = :WAREHOUSE
            INTO :ACCOUNT_GOODS_WAREHOUSE;

            SUSPEND;
            EXIT;
        END
        ELSE
        BEGIN
            SELECT SUM(OFFICIAL_SUM_OF_MONEY)
            FROM DECREASE_ENTRIES
            WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.CREDIT_DEBIT = :CREDIT
            INTO :OFFICIAL_SUM_OF_MONEY;

            IF(OFFICIAL_SUM_OF_MONEY IS NULL)THEN OFFICIAL_SUM_OF_MONEY = 0;

            IF(AMOUNT = 0)THEN
                PRICE = 0;
            ELSE
                PRICE = ROUND(OFFICIAL_SUM_OF_MONEY/AMOUNT, :NUMBER_DECIMAL_DIGITS);

            SELECT ENTRIES.EXCHANGE_RATE
            FROM ENTRIES
            WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = :ENTRY
            INTO :EXCHANGE_RATE;

            UPDATE CREDIT_DEBIT
            SET CREDIT_DEBIT.PRICE = :PRICE,
                CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :OFFICIAL_SUM_OF_MONEY,
                CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = IIF(:EXCHANGE_RATE = 0, 0, ROUND(OFFICIAL_SUM_OF_MONEY/:EXCHANGE_RATE, :NUMBER_DECIMAL_DIGITS))
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY;
        END
    END
END ^

ALTER PROCEDURE CMD_CAL_ENDING_AVERAGE_PRICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ACCOUNT DM_ID,
P_DOCUMENT_TEAMS DM_NAME)
AS 
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE GOODS DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN

    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :BEGINNING_DATE, :ENDING_DATE;


    FOR
        SELECT ACCOUNT, GOODS, WAREHOUSE, SUM(AMOUNT), SUM(SUM_OF_MONEY)
        FROM
        (
            SELECT ACCOUNT, GOODS, WAREHOUSE, AMOUNT, SUM_OF_MONEY
            FROM INT_SD_TK_VT_KHO_DN(:P_COMPANY, 54, 98, :BEGINNING_DATE)
            WHERE :P_ACCOUNT IS NULL OR INT_SD_TK_VT_KHO_DN.ACCOUNT = :P_ACCOUNT

            UNION ALL

            SELECT ACCOUNT, GOODS, WAREHOUSE, INPUT_AMOUNT AMOUNT, INPUT_SUM_OF_MONEY SUM_OF_MONEY
            FROM INT_PS_TK_VT_KHO(:P_COMPANY, 54, 98, :BEGINNING_DATE, :ENDING_DATE)
            WHERE :P_ACCOUNT IS NULL OR INT_PS_TK_VT_KHO.ACCOUNT = :P_ACCOUNT
        )
        GROUP BY ACCOUNT, GOODS, WAREHOUSE
        INTO :ACCOUNT, :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY
    DO
    BEGIN
        
        SELECT SUM(CREDIT_DEBIT.AMOUNT), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM DOCUMENTS
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
        JOIN CREDIT_DEBIT ON
                CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND
                CREDIT_DEBIT.ENTRY = ENTRIES.ID AND
                CREDIT_DEBIT.ACCOUNT = :ACCOUNT AND
                CREDIT_DEBIT.OBJECT0 = :GOODS AND
                CREDIT_DEBIT.OBJECT1 = :WAREHOUSE
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE AND
            DOCUMENTS.TEAM NOT IN
            (
                SELECT ID
                FROM INT_SPLIT_STRING(:P_DOCUMENT_TEAMS, ',')
            )
        INTO :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY;

        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

        INPUT_AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;
        INPUT_SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(ROUND(INPUT_AMOUNT, 5) = 0)THEN
            PRICE = 0;
        ELSE
        BEGIN
            SELECT NUMBER_DECIMAL_DIGITS
            FROM SETTINGS
            WHERE SETTINGS.COMPANY = :P_COMPANY
            INTO :NUMBER_DECIMAL_DIGITS;

            PRICE = ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
        END

        INSERT INTO TEMP_AVERAGE_PRICE(ACCOUNT, GOODS, WAREHOUSE, PRICE, INPUT_AMOUNT, INPUT_SUM_OF_MONEY)
        VALUES(:ACCOUNT, :GOODS, :WAREHOUSE, :PRICE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY);
    END




END ^

ALTER PROCEDURE CMD_CAL_ENDING_AVERAGE_PRICE_1 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ACCOUNT DM_ID,
P_DOCUMENT_TEAMS DM_NAME)
RETURNS (PRICE DM_DOUBLE,
ACCOUNT DM_ID,
GOODS DM_ID,
WAREHOUSE DM_ID,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN

    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :BEGINNING_DATE, :ENDING_DATE;


    FOR
        SELECT ACCOUNT, GOODS, WAREHOUSE, SUM(AMOUNT), SUM(SUM_OF_MONEY)
        FROM
        (
            SELECT ACCOUNT, GOODS, WAREHOUSE, AMOUNT, SUM_OF_MONEY
            FROM INT_SD_TK_VT_KHO_DN(:P_COMPANY, 54, 98, :BEGINNING_DATE)
            WHERE :P_ACCOUNT IS NULL OR INT_SD_TK_VT_KHO_DN.ACCOUNT = :P_ACCOUNT

            UNION ALL

            SELECT ACCOUNT, GOODS, WAREHOUSE, INPUT_AMOUNT AMOUNT, INPUT_SUM_OF_MONEY SUM_OF_MONEY
            FROM INT_PS_TK_VT_KHO(:P_COMPANY, 54, 98, :BEGINNING_DATE, :ENDING_DATE)
            WHERE :P_ACCOUNT IS NULL OR INT_PS_TK_VT_KHO.ACCOUNT = :P_ACCOUNT
        )
        GROUP BY ACCOUNT, GOODS, WAREHOUSE
        INTO :ACCOUNT, :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY
    DO
    BEGIN
        
        SELECT SUM(CREDIT_DEBIT.AMOUNT), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM DOCUMENTS
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
        JOIN CREDIT_DEBIT ON
                CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND
                CREDIT_DEBIT.ENTRY = ENTRIES.ID AND
                CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
                CREDIT_DEBIT.OBJECT0 = :GOODS AND
                CREDIT_DEBIT.OBJECT1 = :WAREHOUSE
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE AND
            DOCUMENTS.TEAM NOT IN
            (
                SELECT ID
                FROM INT_SPLIT_STRING(:P_DOCUMENT_TEAMS, ',')
            )
        INTO :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY;

        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

        INPUT_AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;
        INPUT_SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(ROUND(INPUT_AMOUNT, 5) = 0)THEN
            PRICE = 0;
        ELSE
        BEGIN
            SELECT NUMBER_DECIMAL_DIGITS
            FROM SETTINGS
            WHERE SETTINGS.COMPANY = :P_COMPANY
            INTO :NUMBER_DECIMAL_DIGITS;

            PRICE = ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
        END

        INSERT INTO TEMP_AVERAGE_PRICE(ACCOUNT, GOODS, WAREHOUSE, PRICE, INPUT_AMOUNT, INPUT_SUM_OF_MONEY)
        VALUES(:ACCOUNT, :GOODS, :WAREHOUSE, :PRICE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY);

        SUSPEND;
    END




END ^

ALTER PROCEDURE CMD_CAL_IMMEDIATE_AVERAGE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE INPUT_DATE DM_DATE;
DECLARE VARIABLE ENTRY DM_ID;
DECLARE VARIABLE DEBIT DM_ID;
DECLARE VARIABLE CREDIT DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE GOODS DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    FOR
        SELECT DOCUMENT, INPUT_DATE, ENTRY, EXCHANGE_RATE, DEBIT, CREDIT, ACCOUNT, GOODS, WAREHOUSE, OUTPUT_AMOUNT
        FROM TEMP_IMMEDIATE_AVERAGE
        ORDER BY TEMP_IMMEDIATE_AVERAGE.INPUT_DATE, TEMP_IMMEDIATE_AVERAGE.DOCUMENT, TEMP_IMMEDIATE_AVERAGE.ENTRY
        INTO :DOCUMENT, :INPUT_DATE, :ENTRY, :EXCHANGE_RATE, :DEBIT, :CREDIT, :ACCOUNT, :GOODS, :WAREHOUSE, :OUTPUT_AMOUNT
    DO
    BEGIN
        SELECT AMOUNT, SUM_OF_MONEY
        FROM INT_SD_1_TK_1_VT_1_KHO_CN_PREV(:P_COMPANY, :ACCOUNT, :GOODS, :WAREHOUSE, :INPUT_DATE,  :DOCUMENT, :ENTRY)
        INTO :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY;

        PRICE = IIF(ROUND(INPUT_AMOUNT, 5) = 0, 0, ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, :NUMBER_DECIMAL_DIGITS));

        IF(PRICE IS NULL)THEN PRICE = 0;

        IF(INPUT_AMOUNT <= OUTPUT_AMOUNT)THEN
        BEGIN
            OUTPUT_SUM_OF_MONEY = INPUT_SUM_OF_MONEY;

            IF(ROUND(OUTPUT_AMOUNT, 5) = 0)THEN
                PRICE = 0;
            ELSE
                PRICE = ROUND(OUTPUT_SUM_OF_MONEY/OUTPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
        END
        ELSE
        BEGIN
            OUTPUT_SUM_OF_MONEY = ROUND(OUTPUT_AMOUNT*:PRICE, 0);
        END

        UPDATE CREDIT_DEBIT
        SET CREDIT_DEBIT.PRICE = :PRICE,
            CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :OUTPUT_SUM_OF_MONEY,
            CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = IIF(:EXCHANGE_RATE = 0, 0, ROUND(:OUTPUT_SUM_OF_MONEY/:EXCHANGE_RATE, :NUMBER_DECIMAL_DIGITS))
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY;
    END
END ^

ALTER PROCEDURE CMD_CHECK_ACCOUNT (P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (NOTE DM_NOTE)
AS 
DECLARE VARIABLE ATOM_TYPE_0 DM_ID;
DECLARE VARIABLE ATOM_TYPE_1 DM_ID;
BEGIN
    SELECT ATOM_TYPE_0, ATOM_TYPE_1
    FROM ACCOUNTS
    WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ID
    INTO :ATOM_TYPE_0, :ATOM_TYPE_1;

    FOR
        SELECT DISTINCT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER || ' NGAY ' ||
        EXTRACT(DAY FROM DOCUMENTS.INPUT_DATE) || '/' || EXTRACT(MONTH FROM DOCUMENTS.INPUT_DATE) || '/' || EXTRACT(YEAR FROM DOCUMENTS.INPUT_DATE) ||
        ': thua doi tuong 1'
        FROM CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ACCOUNT = :P_ID AND
            :ATOM_TYPE_0 IS NULL AND CREDIT_DEBIT.OBJECT0 IS NOT NULL
        INTO :NOTE
    DO
    BEGIN
        SUSPEND;
    END

    FOR
        SELECT DISTINCT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER || ' NGAY ' ||
        EXTRACT(DAY FROM DOCUMENTS.INPUT_DATE) || '/' || EXTRACT(MONTH FROM DOCUMENTS.INPUT_DATE) || '/' || EXTRACT(YEAR FROM DOCUMENTS.INPUT_DATE) ||
        ': thieu doi tuong 1'
        FROM CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ACCOUNT = :P_ID AND
            :ATOM_TYPE_0 IS NOT NULL AND CREDIT_DEBIT.OBJECT0 IS NULL
        INTO :NOTE
    DO
    BEGIN
        SUSPEND;
    END

    FOR
        SELECT DISTINCT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER || ' NGAY ' ||
        EXTRACT(DAY FROM DOCUMENTS.INPUT_DATE) || '/' || EXTRACT(MONTH FROM DOCUMENTS.INPUT_DATE) || '/' || EXTRACT(YEAR FROM DOCUMENTS.INPUT_DATE) ||
        ': doi tuong 1 khong dung loai'
        FROM CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CREDIT_DEBIT.OBJECT0
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ACCOUNT = :P_ID AND
            :ATOM_TYPE_0 IS NOT NULL AND CREDIT_DEBIT.OBJECT0 IS NOT NULL AND
            :ATOM_TYPE_0 <> ATOMS.OBJECT_TYPE
        INTO :NOTE
    DO
    BEGIN
        SUSPEND;
    END
END ^

ALTER PROCEDURE CMD_CHECK_ASSET_ACCOUNT (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_ASSET DM_ID)
RETURNS (IS_VALID DM_BOOL,
ACCOUNT_CODE DM_CODE)
AS 
DECLARE VARIABLE VALID_ACCOUNT DM_ID;
BEGIN
    IF(EXISTS(
        SELECT 1
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT AND ATOMS.CODE STARTING WITH '21'
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ACCOUNT
    ))THEN
    BEGIN
        SELECT ASSETS.ASSET_ACCOUNT, CODE
        FROM ASSETS
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
        WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = :P_ASSET
        INTO :VALID_ACCOUNT, :ACCOUNT_CODE;

        IF(VALID_ACCOUNT IS NULL OR VALID_ACCOUNT = P_ACCOUNT)THEN
            IS_VALID = 1;
        ELSE
        BEGIN
            SELECT ASSETS.DEPRECIATION_ACCOUNT, CODE
            FROM ASSETS
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.DEPRECIATION_ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
            WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = :P_ASSET
            INTO :VALID_ACCOUNT, :ACCOUNT_CODE;

            IF(VALID_ACCOUNT IS NULL OR VALID_ACCOUNT = P_ACCOUNT)THEN
                IS_VALID = 1;
            ELSE
                IS_VALID = 0;
        END
    END
    ELSE
        IS_VALID = 1;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_CHECK_PREPAID_ACCOUNT (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_PREPAID_EXPENSE DM_ID)
RETURNS (IS_VALID DM_BOOL,
ACCOUNT_CODE DM_CODE)
AS 
DECLARE VARIABLE VALID_ACCOUNT DM_ID;
BEGIN
    IF(EXISTS(
        SELECT 1
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT AND (ATOMS.CODE STARTING WITH '142' OR ATOMS.CODE STARTING WITH '242')
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ACCOUNT
    ))THEN
    BEGIN
        SELECT PREPAID_EXPENSES.ACCOUNT, CODE
        FROM PREPAID_EXPENSES
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = PREPAID_EXPENSES.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
        WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ID = :P_PREPAID_EXPENSE
        INTO :VALID_ACCOUNT, :ACCOUNT_CODE;

        IF(VALID_ACCOUNT IS NULL OR VALID_ACCOUNT = P_ACCOUNT)THEN
            IS_VALID = 1;
        ELSE
            IS_VALID = 0;
    END
    ELSE
        IS_VALID = 1;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_CHECK_RECORDED_DOCUMENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (DEBIT_ACCOUNT DM_ID,
DEBIT_ACCOUNT_CODE DM_CODE,
CREDIT_ACCOUNT DM_ID,
CREDIT_ACCOUNT_CODE DM_CODE)
AS 
BEGIN
    FOR
        SELECT DISTINCT DEBIT.ACCOUNT, CREDIT.ACCOUNT
        FROM ENTRIES
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.PERIOD = :P_PERIOD
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
            NOT EXISTS
            (
                SELECT DEBIT_ACCOUNT, CREDIT_ACCOUNT
                FROM RECORDED_DOCUMENT_ACCOUNTS
                JOIN ACCOUNTS RECORDED_DEBIT_ACCOUNT ON RECORDED_DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND RECORDED_DEBIT_ACCOUNT.ID = RECORDED_DOCUMENT_ACCOUNTS.DEBIT_ACCOUNT
                JOIN ATOMS RECORDED_DEBIT_ATOM ON RECORDED_DEBIT_ATOM.COMPANY = :P_COMPANY AND RECORDED_DEBIT_ATOM.ID = RECORDED_DEBIT_ACCOUNT.ID
                JOIN ACCOUNTS RECORDED_CREDIT_ACCOUNT ON RECORDED_CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND RECORDED_CREDIT_ACCOUNT.ID = RECORDED_DOCUMENT_ACCOUNTS.CREDIT_ACCOUNT
                JOIN ATOMS RECORDED_CREDIT_ATOM ON RECORDED_CREDIT_ATOM.COMPANY = :P_COMPANY AND RECORDED_CREDIT_ATOM.ID = RECORDED_CREDIT_ACCOUNT.ID
                WHERE RECORDED_DOCUMENT_ACCOUNTS.COMPANY = :P_COMPANY AND
                    DEBIT_ATOM.CODE STARTING WITH RECORDED_DEBIT_ATOM.CODE AND
                    CREDIT_ATOM.CODE STARTING WITH RECORDED_CREDIT_ATOM.CODE
            )
        INTO :DEBIT_ACCOUNT, :CREDIT_ACCOUNT
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_ACCOUNT
        INTO :DEBIT_ACCOUNT_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_ACCOUNT
        INTO :CREDIT_ACCOUNT_CODE;

        SUSPEND;
    END
END ^

ALTER PROCEDURE CMD_CHECK_WORKING_DATE_PERIOD (P_COMPANY DM_ID,
P_WORKING_DATE DM_DATE)
RETURNS (IS_VALID_DATE DM_BOOL,
IS_VALID_PERIOD DM_BOOL,
BEGINNING_DATE DM_DATE,
CORRECT_DATE DM_DATE)
AS 
DECLARE VARIABLE WITH_BEGINNING_DATE DM_DATE;
DECLARE VARIABLE WITH_ENDING_DATE DM_DATE;
DECLARE VARIABLE DATEDIFF_BEGINNING_DATE DM_BIGINT;
DECLARE VARIABLE DATEDIFF_ENDING_DATE DM_BIGINT;
BEGIN
    SELECT PERIODS.BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :BEGINNING_DATE;

    IF(BEGINNING_DATE IS NULL)THEN
        IS_VALID_DATE = 0;
    ELSE IF(P_WORKING_DATE >= BEGINNING_DATE)THEN
        IS_VALID_DATE = 1;
    ELSE
        IS_VALID_DATE = 0;

    IF(EXISTS
        (
            SELECT ID
            FROM PERIODS
            WHERE COMPANY = :P_COMPANY AND :P_WORKING_DATE BETWEEN BEGINNING_DATE AND ENDING_DATE
        )
      )THEN
        IS_VALID_PERIOD = 1;
    ELSE
        IS_VALID_PERIOD = 0;

    IF(IS_VALID_DATE = 0 OR IS_VALID_PERIOD = 0)THEN
    BEGIN
        SELECT FIRST 1 BEGINNING_DATE, ABS(DATEDIFF(DAY, :P_WORKING_DATE, PERIODS.BEGINNING_DATE))
        FROM PERIODS
        WHERE COMPANY = :P_COMPANY AND BEGINNING_DATE >= :BEGINNING_DATE
        ORDER BY ABS(DATEDIFF(DAY, :P_WORKING_DATE, PERIODS.BEGINNING_DATE))
        INTO :WITH_BEGINNING_DATE, :DATEDIFF_BEGINNING_DATE;

        SELECT FIRST 1 ENDING_DATE, ABS(DATEDIFF(DAY, :P_WORKING_DATE, PERIODS.ENDING_DATE))
        FROM PERIODS
        WHERE COMPANY = :P_COMPANY AND ENDING_DATE >= :BEGINNING_DATE
        ORDER BY ABS(DATEDIFF(DAY, :P_WORKING_DATE, PERIODS.ENDING_DATE))
        INTO :WITH_ENDING_DATE, :DATEDIFF_ENDING_DATE;

        IF(WITH_BEGINNING_DATE IS NOT NULL AND DATEDIFF_BEGINNING_DATE IS NOT NULL AND WITH_ENDING_DATE IS NOT NULL AND DATEDIFF_ENDING_DATE  IS NOT NULL)THEN
        BEGIN
            IF(DATEDIFF_BEGINNING_DATE < DATEDIFF_ENDING_DATE)THEN
                CORRECT_DATE = WITH_BEGINNING_DATE;
            ELSE
                CORRECT_DATE = WITH_ENDING_DATE;
        END
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_CLONE_DOCUMENT_TEAM (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
DECLARE VARIABLE ADDITION_INFO1 DM_CAPTION;
DECLARE VARIABLE ADDITION_INFO2 DM_CAPTION;
DECLARE VARIABLE ADDITION_INFO3 DM_CAPTION;
DECLARE VARIABLE ADDITION_INFO4 DM_CAPTION;
DECLARE VARIABLE ATOM_TYPE DM_ID;
DECLARE VARIABLE ATOM_NAME DM_NAME;
DECLARE VARIABLE ATOM_USE_OTHER_NAME DM_BOOL;
DECLARE VARIABLE DOUBLE_AUTO_CALCULATION DM_AUTO_CALCULATION;
DECLARE VARIABLE SINGLE_AUTO_CALCULATION DM_AUTO_CALCULATION;
DECLARE VARIABLE CREDIT_COPY_PROPERTIES DM_COPY_PROPERTIES;
DECLARE VARIABLE DEBIT_COPY_PROPERTIES DM_COPY_PROPERTIES;
DECLARE VARIABLE INVOICE_COPY_PROPERTIES DM_INVOICE_PROPERTIES;
DECLARE VARIABLE OTHER_COPY_PROPERTIES DM_OTHER_PROPERTIES;
DECLARE VARIABLE SINGLE_COPY_PROPERTIES DM_COPY_PROPERTIES;
DECLARE VARIABLE CREDIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT;
DECLARE VARIABLE CREDIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT;
DECLARE VARIABLE DEBIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT;
DECLARE VARIABLE DEBIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT;
DECLARE VARIABLE CREDIT_DEFAULT_ACCOUNT DM_ID;
DECLARE VARIABLE DEBIT_DEFAULT_ACCOUNT DM_ID;
DECLARE VARIABLE SINGLE_DEFAULT_ACCOUNT DM_ID;
DECLARE VARIABLE DEFAULT_INVOICE_TYPE DM_INTEGER;
DECLARE VARIABLE DEFAULT_CONTENT DM_CONTENT;
DECLARE VARIABLE DEFAULT_OBJECT DM_ID;
DECLARE VARIABLE IS_ACTIVE_OBJECT DM_BOOL;
DECLARE VARIABLE MUST_HAVE_OBJECT DM_BOOL;
DECLARE VARIABLE TYPES DM_DOCUMENT_TEAM_TYPES;
DECLARE VARIABLE DEFAULT_CODE DM_CODE;
DECLARE VARIABLE EMPLOYEE_CAPTION DM_CAPTION;
DECLARE VARIABLE PERSON_NAME_CAPTION DM_CAPTION;
DECLARE VARIABLE DEFAULT_GOODS_INPUT_INVOICE DM_GOODS;
DECLARE VARIABLE DEFAULT_GOODS_OUTPUT_INVOICE DM_GOODS;

DECLARE VARIABLE DOCUMENT_TEMPLATE DM_ID;
BEGIN
    SELECT
        ORDINAL,
        NOTE,
        CODE,
        NAME,
        HIDE,
        PARENT,
        TEAM,
        RELATED_OBJECT,
        ADDITION_INFO1,
        ADDITION_INFO2,
        ADDITION_INFO3,
        ADDITION_INFO4,
        ATOM_TYPE,
        ATOM_NAME,
        ATOM_USE_OTHER_NAME,
        DOUBLE_AUTO_CALCULATION,
        SINGLE_AUTO_CALCULATION,
        CREDIT_COPY_PROPERTIES,
        DEBIT_COPY_PROPERTIES,
        INVOICE_COPY_PROPERTIES,
        OTHER_COPY_PROPERTIES,
        SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS,
        CREDIT_STARTING_ACCOUNTS,
        DEBIT_NOT_STARTING_ACCOUNTS,
        DEBIT_STARTING_ACCOUNTS,
        CREDIT_DEFAULT_ACCOUNT,
        DEBIT_DEFAULT_ACCOUNT,
        SINGLE_DEFAULT_ACCOUNT,
        DEFAULT_INVOICE_TYPE,
        DEFAULT_CONTENT,
        DEFAULT_OBJECT,
        IS_ACTIVE_OBJECT,
        MUST_HAVE_OBJECT,
        TYPES,
        DEFAULT_CODE,
        EMPLOYEE_CAPTION,
        PERSON_NAME_CAPTION,
        DEFAULT_GOODS_INPUT_INVOICE,
        DEFAULT_GOODS_OUTPUT_INVOICE
    FROM DOCUMENT_TEAM_S_ER(0, :P_COMPANY)
    WHERE DOCUMENT_TEAM_S_ER.ID = :P_ID
    INTO ORDINAL,
        NOTE,
        CODE,
        NAME,
        HIDE,
        PARENT,
        TEAM,
        RELATED_OBJECT,
        ADDITION_INFO1,
        ADDITION_INFO2,
        ADDITION_INFO3,
        ADDITION_INFO4,
        ATOM_TYPE,
        ATOM_NAME,
        ATOM_USE_OTHER_NAME,
        DOUBLE_AUTO_CALCULATION,
        SINGLE_AUTO_CALCULATION,
        CREDIT_COPY_PROPERTIES,
        DEBIT_COPY_PROPERTIES,
        INVOICE_COPY_PROPERTIES,
        OTHER_COPY_PROPERTIES,
        SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS,
        CREDIT_STARTING_ACCOUNTS,
        DEBIT_NOT_STARTING_ACCOUNTS,
        DEBIT_STARTING_ACCOUNTS,
        CREDIT_DEFAULT_ACCOUNT,
        DEBIT_DEFAULT_ACCOUNT,
        SINGLE_DEFAULT_ACCOUNT,
        DEFAULT_INVOICE_TYPE,
        DEFAULT_CONTENT,
        DEFAULT_OBJECT,
        IS_ACTIVE_OBJECT,
        MUST_HAVE_OBJECT,
        TYPES,
        DEFAULT_CODE,
        EMPLOYEE_CAPTION,
        PERSON_NAME_CAPTION,
        DEFAULT_GOODS_INPUT_INVOICE,
        DEFAULT_GOODS_OUTPUT_INVOICE;

    ID = GEN_ID(UNIVERSE, 1);
    CODE = CODE || ' ' || ID;
    DEFAULT_CODE = DEFAULT_CODE || ' ' || ID;
    NAME = NAME || ' ' || ID;
    ORDINAL = ORDINAL + ID/10000;

    EXECUTE PROCEDURE DOCUMENT_TEAM_IU(0, :P_COMPANY, :ID,
        NOTE,
        ORDINAL,
        CODE,
        HIDE,
        NAME,
        PARENT,
        TEAM,
        RELATED_OBJECT,
        ADDITION_INFO1,
        ADDITION_INFO2,
        ADDITION_INFO3,
        ADDITION_INFO4,
        ATOM_TYPE,
        ATOM_NAME,
        ATOM_USE_OTHER_NAME,
        DOUBLE_AUTO_CALCULATION,
        SINGLE_AUTO_CALCULATION,
        CREDIT_COPY_PROPERTIES,
        DEBIT_COPY_PROPERTIES,
        INVOICE_COPY_PROPERTIES,
        OTHER_COPY_PROPERTIES,
        SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS,
        CREDIT_STARTING_ACCOUNTS,
        DEBIT_NOT_STARTING_ACCOUNTS,
        DEBIT_STARTING_ACCOUNTS,
        CREDIT_DEFAULT_ACCOUNT,
        DEBIT_DEFAULT_ACCOUNT,
        SINGLE_DEFAULT_ACCOUNT,
        DEFAULT_INVOICE_TYPE,
        DEFAULT_CONTENT,
        DEFAULT_OBJECT,
        IS_ACTIVE_OBJECT,
        MUST_HAVE_OBJECT,
        TYPES,
        DEFAULT_CODE,
        EMPLOYEE_CAPTION,
        PERSON_NAME_CAPTION,
        DEFAULT_GOODS_INPUT_INVOICE,
        DEFAULT_GOODS_OUTPUT_INVOICE,
        44);

    FOR
        SELECT NOTE, ORDINAL, DOCUMENT_TEMPLATE
        FROM DOCUMENT_TEAM_TEMPLATE_S_EC(0, :P_COMPANY, :P_ID)
        INTO NOTE, ORDINAL, DOCUMENT_TEMPLATE
    DO
    BEGIN
        EXECUTE PROCEDURE DOCUMENT_TEAM_TEMPLATE_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NOTE,  ORDINAL, ID, DOCUMENT_TEMPLATE);
    END
END ^

ALTER PROCEDURE CMD_CONVERT_PERIOD (P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_TO_PERIOD_TYPE DM_TIME_TYPE)
AS 
DECLARE VARIABLE PERIOD_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
BEGIN
    
    EXECUTE STATEMENT 'ALTER TABLE PERIODS DROP CONSTRAINT CHK_PERIODS;';

    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :BEGINNING_DATE, :ENDING_DATE;

    IF(DATEDIFF(DAY, BEGINNING_DATE, ENDING_DATE) + 1 >= 365)THEN
    BEGIN
        IF(P_TO_PERIOD_TYPE = 2)THEN 
        BEGIN
            SELECT EXTRACT(YEAR FROM BEGINNING_DATE)
            FROM PERIODS
            WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
            INTO :PERIOD_YEAR;

            EXECUTE PROCEDURE CMD_CONVERT_PERIOD_YEAR_2_MONTH(:P_COMPANY, :P_PERIOD, :PERIOD_YEAR);
        END
        ELSE IF(P_TO_PERIOD_TYPE = 3)THEN 
        BEGIN
        END
        ELSE IF(P_TO_PERIOD_TYPE = 4)THEN 
        BEGIN
        END
        ELSE IF(P_TO_PERIOD_TYPE = 5)THEN 
        BEGIN
        END
    END
    ELSE IF(DATEDIFF(DAY, BEGINNING_DATE, ENDING_DATE) + 1 >= 181)THEN
    BEGIN
    END
    ELSE IF(DATEDIFF(DAY, BEGINNING_DATE, ENDING_DATE) + 1 >= 90)THEN
    BEGIN
        IF(P_TO_PERIOD_TYPE = 2)THEN 
        BEGIN
            SELECT EXTRACT(YEAR FROM BEGINNING_DATE)
            FROM PERIODS
            WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
            INTO :PERIOD_YEAR;

            EXECUTE PROCEDURE CMD_CONVERT_QUARTER_2_MONTH(:P_COMPANY, :P_PERIOD, :PERIOD_YEAR);
        END
        ELSE IF(P_TO_PERIOD_TYPE = 3)THEN 
        BEGIN
        END
        ELSE IF(P_TO_PERIOD_TYPE = 4)THEN 
        BEGIN
        END
        ELSE IF(P_TO_PERIOD_TYPE = 5)THEN 
        BEGIN
        END
    END
    ELSE IF(DATEDIFF(DAY, BEGINNING_DATE, ENDING_DATE) + 1 >= 28)THEN
    BEGIN
    END

    
    EXECUTE STATEMENT 'ALTER TABLE PERIODS ADD CONSTRAINT CHK_PERIODS check (NOT EXISTS (
        SELECT B.ID
        FROM PERIODS B
        WHERE PERIODS.COMPANY = B.COMPANY AND PERIODS.ID <> B.ID AND
        (
            (PERIODS.BEGINNING_DATE BETWEEN B.BEGINNING_DATE AND B.ENDING_DATE)
            OR
            (PERIODS.ENDING_DATE BETWEEN B.BEGINNING_DATE AND B.ENDING_DATE)
        )
    ));';
END ^

ALTER PROCEDURE CMD_CONVERT_PERIOD_YEAR_2_MONTH (P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_PERIOD_YEAR DM_INTEGER)
AS 
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
