    UPDATE PERIODS
    SET PERIODS.BEGINNING_DATE = :P_PERIOD_YEAR || '.1.1',
    PERIODS.ENDING_DATE = :P_PERIOD_YEAR || '.1.31'
    WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

    
    P_PERIOD = GEN_ID(UNIVERSE, 1);
    BEGINNING_DATE = P_PERIOD_YEAR || '.2.1';
    IF(MOD(P_PERIOD_YEAR, 400) = 0 OR (MOD(P_PERIOD_YEAR, 4) = 0 AND (MOD(P_PERIOD_YEAR, 100) <> 0)))THEN
        ENDING_DATE = P_PERIOD_YEAR || '.2.29';
