ALTER PROCEDURE CMD_COPY_DEFINE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID)
AS 
declare variable from_source_id dm_id;
declare variable from_target_id dm_id;
declare variable to_source_id dm_id;
declare variable to_target_id dm_id;
declare variable note dm_note;
declare variable ordinal dm_integer;
declare variable transfer_all dm_bool;
declare variable document_content dm_content;
declare variable account dm_id;
declare variable object0 dm_id;
declare variable object1 dm_id;
declare variable object2 dm_id;
declare variable percent dm_double;
declare variable transfer_type dm_integer;
declare variable criteria_account dm_id;
declare variable code_targer_percent_old dm_code;
declare variable id_targer_percent_new dm_id;
BEGIN
    DELETE FROM PROTONS WHERE COMPANY = :P_COMPANY AND ID IN
    (
        SELECT ID
        FROM SOURCE_ACCOUNTS
        WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD
    );

    DELETE FROM SOURCE_ACCOUNTS
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD;

    FOR
        SELECT ID, NOTE, ORDINAL, TRANSFER_ALL, DOCUMENT_CONTENT, ACCOUNT, OBJECT0, OBJECT1, OBJECT2
        FROM SOURCE_ACCOUNT_S_ER(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD)
        INTO :FROM_SOURCE_ID, :NOTE, :ORDINAL, :TRANSFER_ALL, :DOCUMENT_CONTENT, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        TO_SOURCE_ID = GEN_ID(UNIVERSE, 1);

        EXECUTE PROCEDURE SOURCE_ACCOUNT_IU(:P_LANGUAGE, :P_COMPANY, :TO_SOURCE_ID, :NOTE, :ORDINAL, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :TRANSFER_ALL, :DOCUMENT_CONTENT, :P_TO_PERIOD);

        FOR
            SELECT TARGET_ACCOUNT_S_EC.ID, NOTE, ORDINAL, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, TARGET_ACCOUNT_S_EC.PERCENT, TARGET_PERCENTS_OLD.CODE, TRANSFER_TYPE
            FROM TARGET_ACCOUNT_S_EC(:P_LANGUAGE, :P_COMPANY, :FROM_SOURCE_ID)
            LEFT JOIN TARGET_PERCENTS TARGET_PERCENTS_OLD ON TARGET_PERCENTS_OLD.COMPANY = :P_COMPANY AND TARGET_PERCENTS_OLD.PERIOD = :P_FROM_PERIOD AND TARGET_PERCENTS_OLD.ID = TARGET_ACCOUNT_S_EC.TARGET_PERCENT
            INTO :FROM_TARGET_ID, :NOTE, :ORDINAL, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :PERCENT, :CODE_TARGER_PERCENT_OLD, :TRANSFER_TYPE
        DO
        BEGIN
            ID_TARGER_PERCENT_NEW = NULL;

            IF(CODE_TARGER_PERCENT_OLD IS NOT NULL)THEN
            BEGIN
                SELECT TARGET_PERCENTS.ID
                FROM TARGET_PERCENTS
                WHERE TARGET_PERCENTS.COMPANY = :P_COMPANY AND TARGET_PERCENTS.PERIOD = :P_TO_PERIOD AND TARGET_PERCENTS.CODE = :CODE_TARGER_PERCENT_OLD
                INTO ID_TARGER_PERCENT_NEW;
            END

            TO_TARGET_ID = GEN_ID(UNIVERSE, 1);
            EXECUTE PROCEDURE TARGET_ACCOUNT_IU(:P_LANGUAGE, :P_COMPANY, :TO_TARGET_ID, :NOTE, :ORDINAL, :TO_SOURCE_ID, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :PERCENT, :ID_TARGER_PERCENT_NEW, :TRANSFER_TYPE);

            FOR
                SELECT NOTE, ORDINAL, ACCOUNT
                FROM TARGET_ACCOUNT_CRITERIA_S_EC(:P_LANGUAGE, :P_COMPANY, :FROM_TARGET_ID)
                INTO :NOTE, :ORDINAL, :CRITERIA_ACCOUNT
            DO
                EXECUTE PROCEDURE TARGET_ACCOUNT_CRITERIA_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :TO_TARGET_ID, :CRITERIA_ACCOUNT);
        END
    END
END ^

ALTER PROCEDURE CMD_COPY_DEFINE_APPORTIONMENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID)
AS 
declare variable note dm_note;
declare variable ordinal dm_integer;
declare variable account dm_id;
declare variable asset dm_id;
declare variable object0 dm_id;
declare variable object1 dm_id;
declare variable object2 dm_id;
declare variable percent dm_double;
BEGIN
    DELETE FROM PROTONS WHERE COMPANY = :P_COMPANY AND ID IN
    (
        SELECT ID
        FROM APPORTIONMENT_ACCOUNTS
        WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD
    );

    DELETE FROM APPORTIONMENT_ACCOUNTS
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD;

    FOR
        SELECT NOTE, ORDINAL, ACCOUNT, ASSET, PERCENT, OBJECT0, OBJECT1, OBJECT2
        FROM APPORTIONMENT_ACCOUNTS
        JOIN ASSET_S_RS(:P_LANGUAGE, :P_COMPANY, :P_TO_PERIOD, 0) ON ASSET_S_RS.ID = ASSET
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = APPORTIONMENT_ACCOUNTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE APPORTIONMENT_ACCOUNTS.COMPANY = :P_COMPANY AND APPORTIONMENT_ACCOUNTS.PERIOD = :P_FROM_PERIOD
        INTO :NOTE, :ORDINAL, :ACCOUNT, :ASSET, :PERCENT, :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        EXECUTE PROCEDURE APPORTIONMENT_ACCOUNT_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :P_TO_PERIOD, :ASSET, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :PERCENT);
    END
END ^

ALTER PROCEDURE CMD_COPY_DEFINE_EXPENSE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID)
AS 
declare variable note dm_note;
declare variable ordinal dm_integer;
declare variable account dm_id;
declare variable prepaid_expense dm_id;
declare variable object0 dm_id;
declare variable object1 dm_id;
declare variable object2 dm_id;
declare variable percent dm_double;
BEGIN
    DELETE FROM PROTONS WHERE COMPANY = :P_COMPANY AND ID IN
    (
        SELECT ID
        FROM EXPENSE_ACCOUNTS
        WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD
    );

    DELETE FROM EXPENSE_ACCOUNTS
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD;

    FOR
        SELECT NOTE, ORDINAL, ACCOUNT, PREPAID_EXPENSE, PERCENT, OBJECT0, OBJECT1, OBJECT2
        FROM EXPENSE_ACCOUNTS
        JOIN PREPAID_EXPENSE_S_RS(:P_LANGUAGE, :P_COMPANY, :P_TO_PERIOD, 0) ON PREPAID_EXPENSE_S_RS.ID = PREPAID_EXPENSE
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = EXPENSE_ACCOUNTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE EXPENSE_ACCOUNTS.COMPANY = :P_COMPANY AND EXPENSE_ACCOUNTS.PERIOD = :P_FROM_PERIOD
        INTO :NOTE, :ORDINAL, :ACCOUNT, :PREPAID_EXPENSE, :PERCENT, :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        EXECUTE PROCEDURE EXPENSE_ACCOUNT_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :P_TO_PERIOD, :PREPAID_EXPENSE, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :PERCENT);
    END
END ^

ALTER PROCEDURE CMD_COPY_ENTRY_BALANCE (P_COMPANY DM_ID)
AS 
DECLARE VARIABLE BEGINNING_PERIOD DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_DEBIT DM_DOUBLE;
BEGIN
    FOR
        SELECT ACCOUNTING_SETTINGS.BEGINNING_PERIOD
        FROM ACCOUNTING_SETTINGS
        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
        INTO :BEGINNING_PERIOD
    DO
    BEGIN
        FOR
            SELECT BEGINNING_ENTRIES.ACCOUNT, CURRENCY, OBJECT0, OBJECT1, OBJECT2, SUM(AMOUNT), SUM(OFFICIAL_DEBIT)
            FROM BEGINNING_ENTRIES
            WHERE BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND BEGINNING_ENTRIES.PERIOD = :BEGINNING_PERIOD
            GROUP BY ACCOUNT, CURRENCY, OBJECT0, OBJECT1, OBJECT2
            INTO :ACCOUNT, :CURRENCY, :OBJECT0, :OBJECT1, :OBJECT2, :AMOUNT, :OFFICIAL_DEBIT
        DO
        BEGIN
            
            DELETE FROM BALANCES
                WHERE PERIOD = :BEGINNING_PERIOD AND ACCOUNT = :ACCOUNT AND
                (OBJECT0 = :OBJECT0 OR OBJECT0 IS NULL OR :OBJECT0 IS NULL) AND
                (OBJECT1 = :OBJECT1 OR OBJECT1 IS NULL OR :OBJECT1 IS NULL) AND
                (OBJECT2 = :OBJECT2 OR OBJECT2 IS NULL OR :OBJECT2 IS NULL) AND
                CURRENCY = :CURRENCY AND COMPANY = :P_COMPANY;

            EXECUTE PROCEDURE BALANCE_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :BEGINNING_PERIOD, :ACCOUNT, :CURRENCY, 1, :OBJECT0, :OBJECT1, :OBJECT2, :AMOUNT, IIF(AMOUNT = 0, 0, ROUND(OFFICIAL_DEBIT/AMOUNT, 0)), 0,:OFFICIAL_DEBIT, 0, :OFFICIAL_DEBIT);
        END
    END
END ^

ALTER PROCEDURE CMD_COPY_TARGET_PERCENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID)
AS 
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE PERCENT DM_DOUBLE;
BEGIN
    DELETE FROM PROTONS WHERE COMPANY = :P_COMPANY AND ID IN
    (
        SELECT ID
        FROM TARGET_PERCENTS
        WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD
    );

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, PERCENT
        FROM TARGET_PERCENT_S_ER(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD)
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :PERCENT
    DO
    BEGIN
        EXECUTE PROCEDURE TARGET_PERCENT_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :NAME, :P_TO_PERIOD, :PERCENT);
    END
END ^

ALTER PROCEDURE CMD_COST_PRICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_ALLOW_OUT_OF_WAREHOUSE DM_BOOL)
RETURNS (RESULT DM_NOTE)
AS 
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE REVENUE_DOCUMENT DM_ID;
DECLARE VARIABLE REVENUE_DOCUMENT_CODE DM_CODE;
DECLARE VARIABLE COST_PRICE_DOCUMENT DM_ID;
DECLARE VARIABLE COST_PRICE_DOCUMENT_CODE DM_CODE;
DECLARE VARIABLE COST_PRICE_DOCUMENT_NUMBER DM_CODE;
DECLARE VARIABLE DOCUMENT_INPUT_DATE DM_DATE;
DECLARE VARIABLE DOCUMENT_VOUCHER_DATE DM_DATE;
DECLARE VARIABLE REVENUE_ENTRY DM_ID;
DECLARE VARIABLE REVENUE_OBJECT0 DM_ID;
DECLARE VARIABLE REVENUE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE COST_PRICE_ENTRY DM_ID;
DECLARE VARIABLE COST_PRICE_DEBIT_ID DM_ID;
DECLARE VARIABLE COST_PRICE_CREDIT_ID DM_ID;
DECLARE VARIABLE WAREHOUSE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE WAREHOUSE_PRICE DM_DOUBLE;
DECLARE VARIABLE WAREHOUSE_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE REVENUE_ACCOUNT DM_ID;
DECLARE VARIABLE COST_PRICE_ACCOUNT DM_ID;
DECLARE VARIABLE GOODS_ACCOUNT DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE DEFAULT_CONTENT DM_CONTENT;
DECLARE VARIABLE DOCUMENT_TEAM DM_ID;
DECLARE VARIABLE SOURCE_DOCUMENT_CONTENT DM_CONTENT;
DECLARE VARIABLE SOURCE_ENTRY_CONTENT DM_CONTENT;
DECLARE VARIABLE MAIN_CURRENCY DM_ID;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT MAIN_CURRENCY
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :MAIN_CURRENCY;

    FOR
        SELECT DISTINCT REVENUE_ACCOUNT
        FROM COST_PRICE_DEFINES
        WHERE COMPANY = :P_COMPANY AND ENABLED = 1
        INTO :REVENUE_ACCOUNT
    DO
    BEGIN
        SELECT FIRST 1 COST_PRICE_ACCOUNT, DOCUMENT_TEAM, DEFAULT_CONTENT
        FROM COST_PRICE_DEFINES
        WHERE COMPANY = :P_COMPANY AND ENABLED = 1 AND COST_PRICE_DEFINES.REVENUE_ACCOUNT = :REVENUE_ACCOUNT
        INTO :COST_PRICE_ACCOUNT, :DOCUMENT_TEAM, :DEFAULT_CONTENT;

        FOR
            SELECT DOCUMENTS.ID, INPUT_DATE, VOUCHER_DATE, CODE || '-' || NUMBER, CONTENT
            FROM DOCUMENTS
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD AND
            EXISTS
            (
                SELECT 1
                FROM ENTRIES
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT = :REVENUE_ACCOUNT AND CREDIT.AMOUNT > 0
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            )
            INTO :REVENUE_DOCUMENT, :DOCUMENT_INPUT_DATE, :DOCUMENT_VOUCHER_DATE, :REVENUE_DOCUMENT_CODE, :SOURCE_DOCUMENT_CONTENT
        DO
        BEGIN
            HAS_VALUE = 0;
            COST_PRICE_DOCUMENT = NULL;

            SELECT FIRST 1 COST_PRICE_ENTRIES.DOCUMENT
            FROM ENTRIES COST_PRICE_ENTRIES
            
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = COST_PRICE_ENTRIES.DOCUMENT AND DOCUMENTS.TEAM = :DOCUMENT_TEAM
            JOIN ENTRIES REVENUE_ENTRIES ON REVENUE_ENTRIES.COMPANY = :P_COMPANY AND COST_PRICE_ENTRIES.REVENUE_ENTRY = REVENUE_ENTRIES.ID AND REVENUE_ENTRIES.DOCUMENT = :REVENUE_DOCUMENT
            WHERE COST_PRICE_ENTRIES.COMPANY = :P_COMPANY
            INTO :COST_PRICE_DOCUMENT;

            IF(SOURCE_DOCUMENT_CONTENT IS NULL)THEN SOURCE_DOCUMENT_CONTENT = '';
            IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
            BEGIN
                IF(SOURCE_DOCUMENT_CONTENT <> '')THEN
                    SOURCE_DOCUMENT_CONTENT = DEFAULT_CONTENT || ', ' || :SOURCE_DOCUMENT_CONTENT;
                ELSE
                    SOURCE_DOCUMENT_CONTENT = DEFAULT_CONTENT;
            END

            IF(COST_PRICE_DOCUMENT IS NULL)THEN
            BEGIN
                SELECT CODE, NUMBER
                FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :DOCUMENT_INPUT_DATE)
                INTO :COST_PRICE_DOCUMENT_CODE, :COST_PRICE_DOCUMENT_NUMBER;
            
                COST_PRICE_DOCUMENT = GEN_ID(UNIVERSE, 1);
                
                EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :COST_PRICE_DOCUMENT, NULL, 0, NULL, NULL, NULL, NULL, :COST_PRICE_DOCUMENT_CODE, :COST_PRICE_DOCUMENT_NUMBER, :MAIN_CURRENCY, 1, :DOCUMENT_INPUT_DATE, NULL, :REVENUE_DOCUMENT_CODE, :P_PERIOD, :DOCUMENT_TEAM, :DOCUMENT_VOUCHER_DATE, NULL, NULL, NULL, :SOURCE_DOCUMENT_CONTENT, 0, 0);
            END
            ELSE
            BEGIN
                SELECT FIRST 1 CODE, NUMBER 
                FROM DOCUMENTS
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :COST_PRICE_DOCUMENT
                INTO :COST_PRICE_DOCUMENT_CODE, :COST_PRICE_DOCUMENT_NUMBER;

                UPDATE DOCUMENTS
                SET DOCUMENTS.ORIGINAL_VOUCHERS = :REVENUE_DOCUMENT_CODE
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :COST_PRICE_DOCUMENT;
            END

            FOR
                SELECT ENTRIES.ID, CREDIT.OBJECT0, CREDIT.AMOUNT, ENTRY_BASE_STRINGS.CONTENT
                FROM ENTRIES
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = 0 AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT = :REVENUE_ACCOUNT AND CREDIT.OBJECT0 IS NOT NULL AND CREDIT.AMOUNT > 0
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :REVENUE_DOCUMENT
                INTO :REVENUE_ENTRY, :REVENUE_OBJECT0, :REVENUE_AMOUNT, :SOURCE_ENTRY_CONTENT
            DO
            BEGIN
                IF(EXISTS (SELECT 1 FROM ENTRIES WHERE COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :COST_PRICE_DOCUMENT AND ENTRIES.REVENUE_ENTRY = :REVENUE_ENTRY))THEN
                BEGIN
                    SELECT FIRST 1 ENTRIES.ID, DEBIT.ID, CREDIT.ID 
                    FROM ENTRIES
                    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
                    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :COST_PRICE_DOCUMENT AND ENTRIES.REVENUE_ENTRY = :REVENUE_ENTRY
                    INTO :COST_PRICE_ENTRY, :COST_PRICE_DEBIT_ID, :COST_PRICE_CREDIT_ID;

                    FOR
                        SELECT GOODS_ACCOUNT, WAREHOUSE
                        FROM COST_PRICE_DEFINES
                        WHERE COMPANY = :P_COMPANY AND ENABLED = 1 AND REVENUE_ACCOUNT = :REVENUE_ACCOUNT
                        INTO :GOODS_ACCOUNT, :WAREHOUSE
                    DO
                    BEGIN
                        SELECT CMD_GET_PRICE.AMOUNT, CMD_GET_PRICE.PRICE, CMD_GET_PRICE.SUM_OF_MONEY
                        FROM CMD_GET_PRICE(:P_COMPANY, :GOODS_ACCOUNT, :REVENUE_OBJECT0, :WAREHOUSE, :DOCUMENT_INPUT_DATE, :COST_PRICE_DOCUMENT, :COST_PRICE_ENTRY)
                        INTO :WAREHOUSE_AMOUNT, :WAREHOUSE_PRICE, :WAREHOUSE_SUM_OF_MONEY;

                        WAREHOUSE_AMOUNT = ROUND(WAREHOUSE_AMOUNT, NUMBER_DECIMAL_DIGITS);
                        REVENUE_AMOUNT = ROUND(REVENUE_AMOUNT, NUMBER_DECIMAL_DIGITS);

                        
                        IF(WAREHOUSE_AMOUNT < REVENUE_AMOUNT)THEN
                        BEGIN
                            WAREHOUSE_PRICE = 0;
                            WAREHOUSE_SUM_OF_MONEY = 0;

                            
                            SELECT FIRST 1 CONTENT || :REVENUE_DOCUMENT_CODE || '-' || :DOCUMENT_INPUT_DATE || ': ' || ATOMS.CODE || '(' || ROUND(:WAREHOUSE_AMOUNT, :NUMBER_DECIMAL_DIGITS) || ')'
                            FROM MESSAGES
                            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :REVENUE_OBJECT0
                            WHERE MESSAGES.ID = 9 AND MESSAGES.LANGUAGE = :P_LANGUAGE
                            INTO :RESULT;
                        END
                        ELSE
                        BEGIN
                            RESULT = REVENUE_DOCUMENT_CODE || '-' || :DOCUMENT_INPUT_DATE || ' --> ' || COST_PRICE_DOCUMENT_CODE || '-' || COST_PRICE_DOCUMENT_NUMBER;
                        END

                        IF(P_ALLOW_OUT_OF_WAREHOUSE = 1 OR WAREHOUSE_AMOUNT >= REVENUE_AMOUNT)THEN
                        BEGIN
                            HAS_VALUE = 1;

                            IF(WAREHOUSE_AMOUNT > REVENUE_AMOUNT)THEN
                                WAREHOUSE_SUM_OF_MONEY = ROUND(REVENUE_AMOUNT*WAREHOUSE_PRICE, 0);

                            IF(SOURCE_ENTRY_CONTENT IS NULL OR SOURCE_ENTRY_CONTENT = '')THEN
                                SOURCE_ENTRY_CONTENT = SOURCE_DOCUMENT_CONTENT;
                            ELSE IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
                            BEGIN
                                SOURCE_ENTRY_CONTENT = DEFAULT_CONTENT || ', ' || SOURCE_ENTRY_CONTENT;
                            END

                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, :COST_PRICE_ENTRY, NULL, 0, :MAIN_CURRENCY, :COST_PRICE_DOCUMENT, 1, NULL, 0, NULL, NULL, :SOURCE_ENTRY_CONTENT, :COST_PRICE_DEBIT_ID, :COST_PRICE_ACCOUNT, NULL, NULL, NULL, :COST_PRICE_CREDIT_ID, :GOODS_ACCOUNT, :REVENUE_OBJECT0, :WAREHOUSE, NULL, :REVENUE_AMOUNT, :WAREHOUSE_PRICE, 0, :WAREHOUSE_SUM_OF_MONEY);

                            SUSPEND;
                        END
                    END

                    IF(HAS_VALUE = 0)THEN
                    BEGIN
                        
                        SELECT FIRST 1 CONTENT || :REVENUE_DOCUMENT_CODE || '-' || :DOCUMENT_INPUT_DATE || ': ' || ATOMS.CODE || '(' || ROUND(:WAREHOUSE_AMOUNT, :NUMBER_DECIMAL_DIGITS) || ')'
                        FROM MESSAGES
                        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :REVENUE_OBJECT0
                        WHERE MESSAGES.ID = 9 AND MESSAGES.LANGUAGE = :P_LANGUAGE
                        INTO :RESULT;
                        SUSPEND;
                    END
                END
                ELSE
                BEGIN
                    FOR
                        SELECT GOODS_ACCOUNT, WAREHOUSE
                        FROM COST_PRICE_DEFINES
                        WHERE COMPANY = :P_COMPANY AND ENABLED = 1 AND REVENUE_ACCOUNT = :REVENUE_ACCOUNT
                        INTO :GOODS_ACCOUNT, :WAREHOUSE
                    DO
                    BEGIN
                        
                        SELECT FIRST 1 CMD_GET_PRICE.AMOUNT, CMD_GET_PRICE.PRICE, CMD_GET_PRICE.SUM_OF_MONEY
                        FROM CMD_GET_PRICE(:P_COMPANY, :GOODS_ACCOUNT, :REVENUE_OBJECT0, :WAREHOUSE, :DOCUMENT_INPUT_DATE, :COST_PRICE_DOCUMENT, :COST_PRICE_ENTRY)
                        INTO :WAREHOUSE_AMOUNT, :WAREHOUSE_PRICE, :WAREHOUSE_SUM_OF_MONEY;

                        WAREHOUSE_AMOUNT = ROUND(WAREHOUSE_AMOUNT, NUMBER_DECIMAL_DIGITS);
                        REVENUE_AMOUNT = ROUND(REVENUE_AMOUNT, NUMBER_DECIMAL_DIGITS);

                        
                        IF(WAREHOUSE_AMOUNT < REVENUE_AMOUNT)THEN
                        BEGIN
                            WAREHOUSE_PRICE = 0;
                            WAREHOUSE_SUM_OF_MONEY = 0;

                            
                            SELECT FIRST 1 CONTENT || :REVENUE_DOCUMENT_CODE || '-' || :DOCUMENT_INPUT_DATE || ': ' || ATOMS.CODE || '(' || ROUND(:WAREHOUSE_AMOUNT, :NUMBER_DECIMAL_DIGITS) || ')'
                            FROM MESSAGES
                            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :REVENUE_OBJECT0
                            WHERE MESSAGES.ID = 9 AND MESSAGES.LANGUAGE = :P_LANGUAGE
                            INTO :RESULT;
                        END
                        ELSE
                        BEGIN
                            RESULT = REVENUE_DOCUMENT_CODE || '-' || :DOCUMENT_INPUT_DATE || ' --> ' || COST_PRICE_DOCUMENT_CODE || '-' || COST_PRICE_DOCUMENT_NUMBER;
                        END

                        IF(P_ALLOW_OUT_OF_WAREHOUSE = 1 OR WAREHOUSE_AMOUNT >= REVENUE_AMOUNT)THEN
                        BEGIN
                            HAS_VALUE = 1;
                            COST_PRICE_ENTRY = GEN_ID(UNIVERSE, 1);
                            IF(WAREHOUSE_AMOUNT > REVENUE_AMOUNT)THEN
                                WAREHOUSE_SUM_OF_MONEY = ROUND(REVENUE_AMOUNT*WAREHOUSE_PRICE, 0);

                            IF(SOURCE_ENTRY_CONTENT IS NULL OR SOURCE_ENTRY_CONTENT = '')THEN
                                SOURCE_ENTRY_CONTENT = SOURCE_DOCUMENT_CONTENT;
                            ELSE IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
                            BEGIN
                                SOURCE_ENTRY_CONTENT = DEFAULT_CONTENT || ', ' || SOURCE_ENTRY_CONTENT;
                            END

                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, :COST_PRICE_ENTRY, NULL, 0, :MAIN_CURRENCY, :COST_PRICE_DOCUMENT, 1, NULL, 0, NULL, NULL, :SOURCE_ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :COST_PRICE_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :GOODS_ACCOUNT, :REVENUE_OBJECT0, :WAREHOUSE, NULL, :REVENUE_AMOUNT, :WAREHOUSE_PRICE, 0, :WAREHOUSE_SUM_OF_MONEY);
                            UPDATE ENTRIES
                            SET REVENUE_ENTRY = :REVENUE_ENTRY
                            WHERE COMPANY = :P_COMPANY AND ENTRIES.ID = :COST_PRICE_ENTRY;

                            SUSPEND;
                        END
                    END

                    IF(HAS_VALUE = 0)THEN
                    BEGIN
                        
                        SELECT FIRST 1 CONTENT || :REVENUE_DOCUMENT_CODE || '-' || :DOCUMENT_INPUT_DATE || ': ' || ATOMS.CODE || '(' || ROUND(:WAREHOUSE_AMOUNT, :NUMBER_DECIMAL_DIGITS) || ')'
                        FROM MESSAGES
                        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :REVENUE_OBJECT0
                        WHERE MESSAGES.ID = 9 AND MESSAGES.LANGUAGE = :P_LANGUAGE
                        INTO :RESULT;
                        SUSPEND;
                    END
                END
            END

            IF(HAS_VALUE = 0)THEN
            BEGIN
                DELETE FROM DOCUMENT_BASES WHERE DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = :COST_PRICE_DOCUMENT;
            END
        END
    END
END ^

ALTER PROCEDURE CMD_CRITERIA_ACCOUNT_OBJECTS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_BEGINNING_DATE DM_DATE,
P_ENDING_DATE DM_DATE)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE OBJECT DM_ID;
DECLARE VARIABLE RISING DM_DOUBLE;
DECLARE VARIABLE SUM_RISING DM_DOUBLE;
DECLARE VARIABLE COUNT_ROW DM_INTEGER;
DECLARE VARIABLE ROW_INDEX DM_INTEGER;
DECLARE VARIABLE SUM_PERCENT DM_DOUBLE;
DECLARE VARIABLE PERCENT DM_DOUBLE;
begin
    DELETE FROM TEMP_CRITERIA_ACCOUNT_OBJECTS;

    FOR
        SELECT ACCOUNT
        FROM TARGET_ACCOUNT_CRITERIA
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNT_CRITERIA.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
        WHERE TARGET_ACCOUNT_CRITERIA.COMPANY = :P_COMPANY AND TARGET_ACCOUNT_CRITERIA.TARGET_ACCOUNT = :P_TARGET_ACCOUNT
        INTO :ACCOUNT
    DO
    BEGIN
        FOR
            SELECT OBJECT0, MAXVALUE(DEBIT, CREDIT)
            FROM INT_PS_1_TK_DT0(:P_COMPANY, :ACCOUNT, :P_BEGINNING_DATE, :P_ENDING_DATE)
            WHERE DEBIT <> 0 OR CREDIT <> 0
            INTO OBJECT, :RISING
        DO
        BEGIN
            IF(EXISTS (SELECT OBJECT FROM TEMP_CRITERIA_ACCOUNT_OBJECTS WHERE OBJECT = :OBJECT))THEN
                UPDATE TEMP_CRITERIA_ACCOUNT_OBJECTS
                SET RISING = RISING + :RISING
                WHERE OBJECT = :OBJECT;
            ELSE
                INSERT INTO TEMP_CRITERIA_ACCOUNT_OBJECTS(OBJECT, RISING, PERCENT) VALUES(:OBJECT, :RISING, 0);
        END
    END

    SELECT COUNT(OBJECT), SUM(RISING)
    FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
    INTO :COUNT_ROW, :SUM_RISING;

    IF(SUM_RISING <> 0)THEN
    BEGIN
        ROW_INDEX = 1;
        SUM_PERCENT = 1;
    
        FOR
            SELECT OBJECT, RISING
            FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
            INTO :OBJECT, :RISING
        DO
        BEGIN
            IF(ROW_INDEX = COUNT_ROW)THEN
            BEGIN
                UPDATE TEMP_CRITERIA_ACCOUNT_OBJECTS
                SET PERCENT = :SUM_PERCENT
                WHERE OBJECT = :OBJECT;
            END
            ELSE
            BEGIN
                ROW_INDEX = ROW_INDEX + 1;
    
                PERCENT = RISING/SUM_RISING;
    
                UPDATE TEMP_CRITERIA_ACCOUNT_OBJECTS
                SET PERCENT = :PERCENT
                WHERE OBJECT = :OBJECT;
    
                SUM_PERCENT = SUM_PERCENT - PERCENT;
            END
        END
    END
END ^

ALTER PROCEDURE CMD_CRITERIA_ACCOUNT_OBJECTS_2 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_BEGINNING_DATE DM_DATE,
P_ENDING_DATE DM_DATE)
AS 
declare variable account dm_id;
declare variable object dm_id;
declare variable rising dm_double;
declare variable sum_rising dm_double;
declare variable count_row dm_integer;
declare variable row_index dm_integer;
declare variable sum_percent dm_double;
declare variable percent dm_double;
begin
    DELETE FROM TEMP_CRITERIA_ACCOUNT_OBJECTS;

    FOR
        SELECT ACCOUNT
        FROM TARGET_ACCOUNT_CRITERIA
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNT_CRITERIA.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
        WHERE TARGET_ACCOUNT_CRITERIA.COMPANY = :P_COMPANY AND TARGET_ACCOUNT_CRITERIA.TARGET_ACCOUNT = :P_TARGET_ACCOUNT
        INTO :ACCOUNT
    DO
    BEGIN
        FOR
            SELECT OBJECT1, MAXVALUE(DEBIT, CREDIT)
            FROM int_ps_1_tk_1_dt0_dt1(:P_COMPANY, :ACCOUNT, :p_object0, :P_BEGINNING_DATE, :P_ENDING_DATE)
            WHERE DEBIT <> 0 OR CREDIT <> 0
            INTO OBJECT, :RISING
        DO
        BEGIN
            IF(EXISTS (SELECT OBJECT FROM TEMP_CRITERIA_ACCOUNT_OBJECTS WHERE OBJECT = :OBJECT))THEN
                UPDATE TEMP_CRITERIA_ACCOUNT_OBJECTS
                SET RISING = RISING + :RISING
                WHERE OBJECT = :OBJECT;
            ELSE
                INSERT INTO TEMP_CRITERIA_ACCOUNT_OBJECTS(OBJECT, RISING, PERCENT) VALUES(:OBJECT, :RISING, 0);
        END
    END

    SELECT COUNT(OBJECT), SUM(RISING)
    FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
    INTO :COUNT_ROW, :SUM_RISING;

    IF(SUM_RISING <> 0)THEN
    BEGIN
        ROW_INDEX = 1;
        SUM_PERCENT = 1;
    
        FOR
            SELECT OBJECT, RISING
            FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
            INTO :OBJECT, :RISING
        DO
        BEGIN
            IF(ROW_INDEX = COUNT_ROW)THEN
            BEGIN
                UPDATE TEMP_CRITERIA_ACCOUNT_OBJECTS
                SET PERCENT = :SUM_PERCENT
                WHERE OBJECT = :OBJECT;
            END
            ELSE
            BEGIN
                ROW_INDEX = ROW_INDEX + 1;
    
                PERCENT = RISING/SUM_RISING;
    
                UPDATE TEMP_CRITERIA_ACCOUNT_OBJECTS
                SET PERCENT = :PERCENT
                WHERE OBJECT = :OBJECT;
    
                SUM_PERCENT = SUM_PERCENT - PERCENT;
            END
        END
    END
END ^

ALTER PROCEDURE CMD_DATES_OF_HALF_YEAR (HALF_YEAR_TO_CHECK DM_INTEGER,
YEAR_TO_CHECK DM_INTEGER)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
    IF(HALF_YEAR_TO_CHECK = 0)THEN
    BEGIN
        BEGINNING_DATE = YEAR_TO_CHECK || '.1.1';
        ENDING_DATE = YEAR_TO_CHECK || '.6.30';
    END
    ELSE IF(HALF_YEAR_TO_CHECK = 1)THEN
    BEGIN
        BEGINNING_DATE = YEAR_TO_CHECK || '.7.1';
        ENDING_DATE = YEAR_TO_CHECK || '.12.31';
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_DATES_OF_QUARTER_YEAR (QUARTER_TO_CHECK DM_INTEGER,
YEAR_TO_CHECK DM_INTEGER)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
    IF(QUARTER_TO_CHECK = 1)THEN
    BEGIN
        BEGINNING_DATE = YEAR_TO_CHECK || '.1.1';
        ENDING_DATE = YEAR_TO_CHECK || '.3.31';
    END
    ELSE IF(QUARTER_TO_CHECK = 2)THEN
    BEGIN
        BEGINNING_DATE = YEAR_TO_CHECK || '.4.1';
        ENDING_DATE = YEAR_TO_CHECK || '.6.30';
    END
    ELSE IF(QUARTER_TO_CHECK = 3)THEN
    BEGIN
        BEGINNING_DATE = YEAR_TO_CHECK || '.7.1';
        ENDING_DATE = YEAR_TO_CHECK || '.9.30';
    END
    ELSE IF(QUARTER_TO_CHECK = 4)THEN
    BEGIN
        BEGINNING_DATE = YEAR_TO_CHECK || '.10.1';
        ENDING_DATE = YEAR_TO_CHECK || '.12.31';
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_DELETE_COMPANY (P_COMPANY DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
BEGIN
    DELETE FROM DECREASE_ENTRIES
    WHERE COMPANY = :P_COMPANY;

    DELETE FROM DECREASE_DOCUMENTS
    WHERE COMPANY = :P_COMPANY;

    DELETE FROM ENTRY_BALANCES
    WHERE COMPANY = :P_COMPANY;

    DELETE FROM DOCUMENT_BALANCES
    WHERE COMPANY = :P_COMPANY;

    DELETE FROM ENTRY_BASES
    WHERE COMPANY = :P_COMPANY;

    DELETE FROM DOCUMENT_TEAM_NUMBER
    WHERE COMPANY = :P_COMPANY;

    DELETE FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY;

    WHILE(EXISTS (SELECT 1 FROM DOCUMENT_BASES WHERE COMPANY = :P_COMPANY))DO
    BEGIN
        FOR
            SELECT ID
            FROM DOCUMENT_BASES
            WHERE COMPANY = :P_COMPANY
            INTO :ID
        DO
        BEGIN
            DELETE FROM DOCUMENT_BASES
            WHERE ID = :ID;

            WHEN ANY DO
            BEGIN
            END
        END
    END

    WHILE(EXISTS (SELECT 1 FROM PROTONS WHERE COMPANY = :P_COMPANY))DO
    BEGIN
        FOR
            SELECT ID
            FROM PROTONS
            WHERE COMPANY = :P_COMPANY
            INTO :ID
        DO
        BEGIN
            DELETE FROM PROTONS
            WHERE ID = :ID;

            WHEN ANY DO
            BEGIN
            END
        END
    END

        DELETE FROM LOGS
        WHERE COMPANY = :P_COMPANY;

    IF(NOT EXISTS(
        SELECT 1
        FROM COMPANIES
    ))THEN
    BEGIN
        DELETE FROM CONFIGURATION;

        DELETE FROM DECREASE_ENTRIES;

        DELETE FROM DECREASE_DOCUMENTS;

        DELETE FROM ENTRY_BALANCES;

        DELETE FROM DOCUMENT_BALANCES;

        DELETE FROM DOCUMENT_BASES;

        DELETE FROM ENTRY_BASES;

        DELETE FROM DOCUMENT_TEAM_NUMBER;

        DELETE FROM ACCOUNTING_SETTINGS;

        WHILE(EXISTS (SELECT 1 FROM DOCUMENT_BASES))DO
        BEGIN
            FOR
                SELECT ID
                FROM DOCUMENT_BASES
                INTO :ID
            DO
            BEGIN
                DELETE FROM DOCUMENT_BASES
                WHERE ID = :ID;

                WHEN ANY DO
                BEGIN
                END
            END
        END

        WHILE(EXISTS (SELECT 1 FROM PROTONS))DO
        BEGIN
            FOR
                SELECT ID
                FROM PROTONS
                INTO :ID
            DO
            BEGIN
                DELETE FROM PROTONS
                WHERE ID = :ID;

                WHEN ANY DO
                BEGIN
                END
            END
        END

        DELETE FROM LOGS;
    END
END ^

