ALTER PROCEDURE CMD_DEPRECIATE_ASSET (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE ASSET_CODE DM_CODE;
DECLARE VARIABLE DEPRECIATION_PERCENT DM_DOUBLE;
DECLARE VARIABLE DEPRECIATION_METHOD DM_DEPRECIATION_METHOD;
DECLARE VARIABLE DEPRECIATION_ACCOUNT DM_ID;
DECLARE VARIABLE ASSET_ACCOUNT DM_ID;
DECLARE VARIABLE MAIN_CURRENCY DM_ID;
DECLARE VARIABLE TEXT_DEPRECIATE_ASSET DM_TEXT_CONTENT;
DECLARE VARIABLE DOCUMENT_TEAM DM_ID;
DECLARE VARIABLE DEPRECIATION_DATE DM_DATE;
DECLARE VARIABLE REMAINING_DEPRECIATION_PERIOD DM_DOUBLE;
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NUMBER DM_CODE;
DECLARE VARIABLE DEPRECIATION_DATE_PREV DM_DATE;
DECLARE VARIABLE ONE_DOCUMENT DM_OTHER_SETTINGS;
BEGIN
    SELECT MAIN_CURRENCY, APPORTIONMENT_DOCUMENT_TEAM, BIN_AND(OTHERS, 8192)
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :MAIN_CURRENCY, :DOCUMENT_TEAM, :ONE_DOCUMENT;

    DELETE FROM DOCUMENTS
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD AND TEAM = :DOCUMENT_TEAM;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 7 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_DEPRECIATE_ASSET;

    FOR
        SELECT ASSETS.ID, CODE, ASSETS.ASSET_ACCOUNT, DEPRECIATION_DATE, REMAINING_DEPRECIATION_PERIOD,
        DEPRECIATION_METHOD, DEPRECIATION_ACCOUNT, DEPRECIATION_PERCENT
        FROM ASSET_S_DEPRECIATION(:P_LANGUAGE, :P_COMPANY, :P_PERIOD)
        JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = ASSET_S_DEPRECIATION.ID
        JOIN ATOMS ASSET_ATOMS ON ASSET_ATOMS.COMPANY = :P_COMPANY AND ASSET_ATOMS.ID = ASSETS.ID
        ORDER BY DEPRECIATION_DATE
        INTO :ID, :ASSET_CODE, :ASSET_ACCOUNT, :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD,
        :DEPRECIATION_METHOD, :DEPRECIATION_ACCOUNT, :DEPRECIATION_PERCENT
    DO
    BEGIN
        IF(ONE_DOCUMENT = 0)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_APPORTIONMENT_ASSET(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :ID, :ASSET_ACCOUNT, :REMAINING_DEPRECIATION_PERIOD, :DEPRECIATION_PERCENT, :DEPRECIATION_METHOD, DEPRECIATION_ACCOUNT, :MAIN_CURRENCY, :DEPRECIATION_DATE, :TEXT_DEPRECIATE_ASSET, :TEXT_DEPRECIATE_ASSET || ' ' || :ASSET_CODE, :DOCUMENT_TEAM);
        END
        ELSE
        BEGIN
            IF(DEPRECIATION_DATE_PREV IS NULL OR DEPRECIATION_DATE <> DEPRECIATION_DATE_PREV)THEN
            BEGIN
                IF(
                    DOCUMENT IS NOT NULL AND
                    NOT EXISTS(
                        SELECT 1
                        FROM ENTRIES
                        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
                    )
                )THEN
                BEGIN
                    EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                END

                DEPRECIATION_DATE_PREV = DEPRECIATION_DATE;

                SELECT CODE, NUMBER
                FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :DEPRECIATION_DATE)
                INTO :CODE, :NUMBER;

                DOCUMENT = GEN_ID(UNIVERSE, 1);
                EXECUTE PROCEDURE DOCUMENT_IU(P_LANGUAGE, P_COMPANY, :DOCUMENT, NULL, 0, NULL, NULL, NULL, NULL, CODE, NUMBER, MAIN_CURRENCY, 1, DEPRECIATION_DATE, NULL, NULL, P_PERIOD, DOCUMENT_TEAM, DEPRECIATION_DATE, NULL, NULL, NULL, TEXT_DEPRECIATE_ASSET, 0, 0);
            END

            EXECUTE PROCEDURE CMD_APPORTIONMENT_ASSET_NEW(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :ID, :ASSET_ACCOUNT, :REMAINING_DEPRECIATION_PERIOD, :DEPRECIATION_PERCENT, :DEPRECIATION_METHOD, DEPRECIATION_ACCOUNT, :MAIN_CURRENCY, :DEPRECIATION_DATE, DOCUMENT, :TEXT_DEPRECIATE_ASSET || ' ' || :ASSET_CODE);
        END
    END

    
    IF(ONE_DOCUMENT > 0)THEN
    BEGIN
        IF(
            DOCUMENT IS NOT NULL AND
            NOT EXISTS(
                SELECT 1
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
            )
        )THEN
        BEGIN
            EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
        END
    END
END ^

ALTER PROCEDURE CMD_DEPRECIATE_EXPENSE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE PREPAID_EXPENSE_ID DM_ID;
DECLARE VARIABLE PREPAID_EXPENSE_CODE DM_CODE;
DECLARE VARIABLE DEPRECIATION_DATE DM_DATE;
DECLARE VARIABLE REMAINING_DEPRECIATION_PERIOD DM_DOUBLE;
DECLARE VARIABLE EXPENSE_ACCOUNT DM_ID;
DECLARE VARIABLE MAIN_CURRENCY DM_ID;
DECLARE VARIABLE DOCUMENT_TEAM DM_ID;
DECLARE VARIABLE TEXT_DEPRECIATE_EXPENSE DM_TEXT_CONTENT;
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NUMBER DM_CODE;
DECLARE VARIABLE DEPRECIATION_DATE_PREV DM_DATE;
DECLARE VARIABLE ONE_DOCUMENT DM_OTHER_SETTINGS;
BEGIN
    SELECT MAIN_CURRENCY, EXPENSE_DOCUMENT_TEAM, BIN_AND(OTHERS, 8192)
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :MAIN_CURRENCY, :DOCUMENT_TEAM, :ONE_DOCUMENT;

    DELETE FROM DOCUMENTS
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD AND TEAM = :DOCUMENT_TEAM;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 8 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_DEPRECIATE_EXPENSE;

    FOR
        SELECT PREPAID_EXPENSES.ID, CODE, ACCOUNT, DEPRECIATION_DATE, REMAINING_DEPRECIATION_PERIOD
        FROM PREPAID_EXPENSE_S_DEPRECIATION(:P_LANGUAGE, :P_COMPANY, :P_PERIOD)
        JOIN PREPAID_EXPENSES ON PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ID = PREPAID_EXPENSE_S_DEPRECIATION.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PREPAID_EXPENSES.ID
        ORDER BY DEPRECIATION_DATE
        INTO :PREPAID_EXPENSE_ID, :PREPAID_EXPENSE_CODE, :EXPENSE_ACCOUNT,
        :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
    DO
    BEGIN
        IF(ONE_DOCUMENT = 0)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_APPORTIONMENT_EXPENSE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :PREPAID_EXPENSE_ID, :EXPENSE_ACCOUNT, :REMAINING_DEPRECIATION_PERIOD, :MAIN_CURRENCY, :DEPRECIATION_DATE, :TEXT_DEPRECIATE_EXPENSE, :TEXT_DEPRECIATE_EXPENSE || ' ' || :PREPAID_EXPENSE_CODE, :DOCUMENT_TEAM);
        END
        ELSE
        BEGIN
            IF(DEPRECIATION_DATE_PREV IS NULL OR DEPRECIATION_DATE <> DEPRECIATION_DATE_PREV)THEN
            BEGIN
                
                IF(
                    DOCUMENT IS NOT NULL AND
                    NOT EXISTS(
                        SELECT 1
                        FROM ENTRIES
                        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
                    )
                )THEN
                BEGIN
                    EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                END

                DEPRECIATION_DATE_PREV = DEPRECIATION_DATE;

                SELECT CODE, NUMBER
                FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :DEPRECIATION_DATE)
                INTO :CODE, :NUMBER;

                DOCUMENT = GEN_ID(UNIVERSE, 1);
                EXECUTE PROCEDURE DOCUMENT_IU(P_LANGUAGE, P_COMPANY, :DOCUMENT, NULL, 0, NULL, NULL, NULL, NULL, CODE, NUMBER, MAIN_CURRENCY, 1, DEPRECIATION_DATE, NULL, NULL, P_PERIOD, DOCUMENT_TEAM, DEPRECIATION_DATE, NULL, NULL, NULL, TEXT_DEPRECIATE_EXPENSE, 0, 0);
            END

            EXECUTE PROCEDURE CMD_APPORTIONMENT_EXPENSE_NEW(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :PREPAID_EXPENSE_ID, :EXPENSE_ACCOUNT, :REMAINING_DEPRECIATION_PERIOD, :MAIN_CURRENCY, :DEPRECIATION_DATE, DOCUMENT, :TEXT_DEPRECIATE_EXPENSE || ' ' || :PREPAID_EXPENSE_CODE);
        END
    END

    IF(ONE_DOCUMENT > 0)THEN
    BEGIN
        IF(
            DOCUMENT IS NOT NULL AND
            NOT EXISTS(
                SELECT 1
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
            )
        )THEN
        BEGIN
            EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
        END
    END
END ^

ALTER PROCEDURE CMD_ENDING_AVERAGE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAMS DM_NAME,
P_ACCOUNT DM_ID = null)
AS 
DECLARE VARIABLE DOCUMENT_TEAM_ID DM_ID;
BEGIN
    DELETE FROM TEMP_AVERAGE_PRICE;

    EXECUTE PROCEDURE CMD_CAL_ENDING_AVERAGE_PRICE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :P_ACCOUNT, P_DOCUMENT_TEAMS);

    FOR
        SELECT ID
        FROM INT_SPLIT_STRING(:P_DOCUMENT_TEAMS, ',')
        INTO :DOCUMENT_TEAM_ID
    DO
    BEGIN
        EXECUTE PROCEDURE CMD_OUTPUT_ENDING_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :DOCUMENT_TEAM_ID, :P_ACCOUNT);
    END
END ^

ALTER PROCEDURE CMD_ENDING_DAY_OF_MONTH_YEAR (MONTH_TO_CHECK DM_INTEGER,
YEAR_TO_CHECK DM_INTEGER)
RETURNS (ENDING_DAY DM_INTEGER)
AS 
DECLARE VARIABLE IS_LEAP_YEAR DM_BOOL;
BEGIN
    SELECT CASE :MONTH_TO_CHECK
            WHEN 1 THEN 31
            WHEN 2 THEN 28
            WHEN 3 THEN 31
            WHEN 4 THEN 30
            WHEN 5 THEN 31
            WHEN 6 THEN 30
            WHEN 7 THEN 31
            WHEN 8 THEN 31
            WHEN 9 THEN 30
            WHEN 10 THEN 31
            WHEN 11 THEN 30
            ELSE 31
            END
    FROM RDB$DATABASE
    INTO :ENDING_DAY;

    IF(MONTH_TO_CHECK = 2)THEN
    BEGIN
        SELECT IS_LEAP_YEAR
        FROM CMD_IS_LEAP_YEAR(:YEAR_TO_CHECK)
        INTO :IS_LEAP_YEAR;

        IF(IS_LEAP_YEAR = 1)THEN ENDING_DAY = 29;
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_EXECUTE_PROCEDURES RETURNS (PROCEDURE_NAME DM_PROCEDURE_NAME)
AS 
BEGIN
    
    IF(PROCEDURE_NAME IS NOT NULL)THEN
        SUSPEND;
END ^

ALTER PROCEDURE CMD_FAST_ACCESS_BALANCE_ACCOUNT (P_COMPANY DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID)
RETURNS (BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE NOT154X2 DM_INTEGER;
DECLARE VARIABLE DOUBLE_VALUE DM_DOUBLE;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 4096)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :NOT154X2;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(NOT154X2 > 0 AND PARENT_ACCOUNT_CODE NOT STARTING WITH '154')THEN
        NOT154X2 = 0;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    IF(P_CURRENCY IS NULL)THEN
    BEGIN
        BEGINNING_FOREIGN_DEBIT = 0;
        BEGINNING_FOREIGN_CREDIT = 0;

        RISING_FOREIGN_DEBIT = 0;
        RISING_FOREIGN_CREDIT = 0;

        IF(P_OBJECT1 IS NULL)THEN
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE)
                INTO :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT DEBIT, CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;

                IF(NOT154X2 > 0)THEN
                BEGIN
                    SELECT SUM_OF_MONEY
                    FROM INT_PS_CAP_TK_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                    INTO :DOUBLE_VALUE;
                    RISING_OFFICIAL_DEBIT = RISING_OFFICIAL_DEBIT - DOUBLE_VALUE;
                    RISING_OFFICIAL_CREDIT = RISING_OFFICIAL_CREDIT - DOUBLE_VALUE;
                END
            END
            ELSE
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_FROM_DATE)
                INTO :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT DEBIT, CREDIT
                FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;

                IF(NOT154X2 > 0)THEN
                BEGIN
                    SELECT OFFICIAL_SUM_OF_MONEY
                    FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                    INTO :DOUBLE_VALUE;
                    RISING_OFFICIAL_DEBIT = RISING_OFFICIAL_DEBIT - DOUBLE_VALUE;
                    RISING_OFFICIAL_CREDIT = RISING_OFFICIAL_CREDIT - DOUBLE_VALUE;
                END
            END
        END
        ELSE
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE)
                INTO :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT DEBIT, CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;

                IF(NOT154X2 > 0)THEN
                BEGIN
                    SELECT SUM_OF_MONEY
                    FROM INT_PS_CAP_TK_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                    INTO :DOUBLE_VALUE;
                    RISING_OFFICIAL_DEBIT = RISING_OFFICIAL_DEBIT - DOUBLE_VALUE;
                    RISING_OFFICIAL_CREDIT = RISING_OFFICIAL_CREDIT - DOUBLE_VALUE;
                END
            END
            ELSE
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_FROM_DATE)
                INTO :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT DEBIT, CREDIT
                FROM INT_PS_1_TK_1_DT0_1_DT1_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;
            END
        END
    END
    ELSE
    BEGIN
        IF(P_OBJECT1 IS NULL)THEN
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE)
                INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_PS_1_TK_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;
            END
            ELSE
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_FROM_DATE)
                INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_PS_1_TK_1_DT0_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;
            END
        END
        ELSE
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE)
                INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_PS_1_TK_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;
            END
            ELSE
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_FROM_DATE)
                INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_PS_1_TK_1_DT0_1_DT1_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_FROM_DATE, :P_TO_DATE)
                INTO :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;
            END
        END
    END

    ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT + RISING_FOREIGN_DEBIT - RISING_FOREIGN_CREDIT;
    ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT + RISING_OFFICIAL_DEBIT - RISING_OFFICIAL_CREDIT;

    IF(ENDING_FOREIGN_DEBIT > 0)THEN
        ENDING_FOREIGN_CREDIT = 0;
    ELSE
    BEGIN
        ENDING_FOREIGN_CREDIT = ABS(ENDING_FOREIGN_DEBIT);
        ENDING_FOREIGN_DEBIT = 0;
    END

    IF(ENDING_OFFICIAL_DEBIT > 0)THEN
        ENDING_OFFICIAL_CREDIT = 0;
    ELSE
    BEGIN
        ENDING_OFFICIAL_CREDIT = ABS(ENDING_OFFICIAL_DEBIT);
        ENDING_OFFICIAL_DEBIT = 0;
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_FILIFO_DOCUMENT (P_COMPANY DM_ID,
P_DECREASE_DATE DM_DATE,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
P_CREDIT_DEBIT DM_ID,
P_SIDE DM_SIDE)
RETURNS (REMAINING_OFFICIAL_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    
    DELETE FROM DECREASE_DOCUMENTS
    WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.CREDIT_DEBIT = :P_CREDIT_DEBIT;

    
    FOR
        SELECT ID, OFFICIAL_SUM_OF_MONEY
        FROM DOCUMENT_BALANCE_S_RS(0, :P_COMPANY, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_DECREASE_DATE, :P_SIDE)
        INTO :ID, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        IF(OFFICIAL_SUM_OF_MONEY > P_OFFICIAL_SUM_OF_MONEY)THEN
        BEGIN
            EXECUTE PROCEDURE DECREASE_DOCUMENT_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :ID, :P_CREDIT_DEBIT, :P_OFFICIAL_SUM_OF_MONEY, 0);

            P_OFFICIAL_SUM_OF_MONEY = 0;

            LEAVE; 
        END
        ELSE
        BEGIN
            EXECUTE PROCEDURE DECREASE_DOCUMENT_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :ID, :P_CREDIT_DEBIT, :OFFICIAL_SUM_OF_MONEY, 0);

            P_OFFICIAL_SUM_OF_MONEY = P_OFFICIAL_SUM_OF_MONEY - OFFICIAL_SUM_OF_MONEY;

            IF(P_OFFICIAL_SUM_OF_MONEY = 0)THEN LEAVE;
        END
    END

    REMAINING_OFFICIAL_SUM_OF_MONEY = P_OFFICIAL_SUM_OF_MONEY;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_FILIFO_ENTRY (P_COMPANY DM_ID,
P_OUTPUT_DATE DM_DATE,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_OUTPUT_AMOUNT DM_DOUBLE,
P_CREDIT_DEBIT DM_ID,
P_SIDE DM_SIDE)
RETURNS (REMAINING_AMOUNT DM_DOUBLE)
AS 
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT REMAINING_AMOUNT
    FROM INT_FILIFO_ENTRY(:P_COMPANY, :P_OUTPUT_DATE, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_OUTPUT_AMOUNT, :P_CREDIT_DEBIT, :P_SIDE, :NUMBER_DECIMAL_DIGITS)
    INTO :REMAINING_AMOUNT;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GENERATE_RECORDED_DOCUMENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE CONTENT DM_CONTENT;
DECLARE VARIABLE RECORDED_DOCUMENT DM_ID;
DECLARE VARIABLE SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DATE_OF_PERIOD DM_DATE;
DECLARE VARIABLE ENDING_DATE_OF_PERIOD DM_DATE;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE RECORDED_DOCUMENT_CYCLE DM_TIME_TYPE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    EXECUTE PROCEDURE CMD_DELETE_RECORDED_DOCUMENT(:P_LANGUAGE, :P_COMPANY, :P_PERIOD);

    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD;

    SELECT RECORDED_DOCUMENT_CYCLE
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :RECORDED_DOCUMENT_CYCLE;

    FOR
        SELECT RECORDED_DOCUMENT_TEAMS.ID, ATOMS.CODE, ATOM_STRINGS.NAME
        FROM RECORDED_DOCUMENT_TEAMS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = RECORDED_DOCUMENT_TEAMS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        WHERE RECORDED_DOCUMENT_TEAMS.COMPANY = :P_COMPANY
        INTO :TEAM, :CODE, :NAME
    DO
    BEGIN
        FOR
            SELECT BEGINNING_DATE, ENDING_DATE
            FROM
            (
                SELECT :BEGINNING_DATE_OF_PERIOD BEGINNING_DATE, :ENDING_DATE_OF_PERIOD ENDING_DATE
                FROM RDB$DATABASE
                WHERE :RECORDED_DOCUMENT_CYCLE IS NULL

                UNION ALL

                SELECT BEGINNING_DATE_OF_MONTH BEGINNING_DATE, ENDING_DATE_OF_MONTH ENDING_DATE
                FROM INT_ENDING_DATES_OF_MONTH(:BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                WHERE :RECORDED_DOCUMENT_CYCLE = 2

                UNION ALL

                SELECT BEGINNING_DATE_OF_QUARTER BEGINNING_DATE, ENDING_DATE_OF_QUARTER ENDING_DATE
                FROM INT_ENDING_DATES_OF_QUARTER(:BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                WHERE :RECORDED_DOCUMENT_CYCLE = 3

                UNION ALL

                SELECT BEGINNING_DATE_OF_HALF_YEAR BEGINNING_DATE, ENDING_DATE_OF_HALF_YEAR ENDING_DATE
                FROM INT_ENDING_DATES_OF_HALF_YEAR(:BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                WHERE :RECORDED_DOCUMENT_CYCLE = 4

                UNION ALL

                SELECT BEGINNING_DATE_OF_YEAR, ENDING_DATE_OF_YEAR
                FROM INT_ENDING_DATES_OF_YEAR(:BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                WHERE :RECORDED_DOCUMENT_CYCLE = 5
            )
            INTO :BEGINNING_DATE, :ENDING_DATE
        DO
        BEGIN
            HAS_VALUE = 0;

            RECORDED_DOCUMENT = GEN_ID(UNIVERSE, 1);
            EXECUTE PROCEDURE RECORDED_DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :RECORDED_DOCUMENT, NULL, 0, :CODE, :NAME, :TEAM, :P_PERIOD, :ENDING_DATE);

            FOR
                SELECT DEBIT_ACCOUNT, CREDIT_ACCOUNT, CONTENT
                FROM RECORDED_DOCUMENT_ACCOUNTS
                WHERE RECORDED_DOCUMENT_ACCOUNTS.COMPANY = :P_COMPANY AND RECORDED_DOCUMENT_ACCOUNTS.RECORDED_DOCUMENT_TEAM = :TEAM
                INTO :DEBIT_ACCOUNT, :CREDIT_ACCOUNT, :CONTENT
            DO
            BEGIN
                SELECT SUM_OF_MONEY
                FROM INT_PS_CAP_TK_PERIOD(:P_COMPANY, :DEBIT_ACCOUNT, :CREDIT_ACCOUNT, :BEGINNING_DATE, :ENDING_DATE)
                INTO :SUM_OF_MONEY;

                IF(SUM_OF_MONEY <> 0)THEN
                BEGIN
                    EXECUTE PROCEDURE RECORDED_DOCUMENT_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL,  0, :DEBIT_ACCOUNT, :CREDIT_ACCOUNT, :RECORDED_DOCUMENT, :CONTENT, :SUM_OF_MONEY);

                    HAS_VALUE = 1;
                END
            END

            IF(HAS_VALUE = 0)THEN DELETE FROM PROTONS WHERE COMPANY = :P_COMPANY AND ID = :RECORDED_DOCUMENT;
        END
    END
END ^

ALTER PROCEDURE CMD_GET_BALANCE_ACCOUNT (P_COMPANY DM_ID,
P_DATE DM_DATE,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_DOCUMENT DM_ID,
P_ENTRY DM_ID)
RETURNS (FOREIGN_DEBIT DM_DOUBLE,
FOREIGN_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    IF(P_CURRENCY IS NULL)THEN
    BEGIN
        FOREIGN_DEBIT = 0;
        FOREIGN_CREDIT = 0;

        IF(P_OBJECT1 IS NULL)THEN
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_CN_C_EX(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
            ELSE
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_1_DT0_CN_C_EX(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
        END
        ELSE
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_CN_C_EX(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
            ELSE
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_1_DT0_1_DT1_CN_C_EX(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
        END
    END
    ELSE
    BEGIN
        IF(P_OBJECT1 IS NULL)THEN
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_CN_C_TT_EX(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
            ELSE
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_1_DT0_CN_C_TT_EX(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
        END
        ELSE
        BEGIN
            IF(P_OBJECT0 IS NULL)THEN
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_CN_C_TT_EX(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
            ELSE
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_1_DT0_1_DT1_CN_CTTE(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_DATE, :P_DOCUMENT, :P_ENTRY)
                INTO :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT;
            END
        END
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_BEGINNING_PERIOD (P_COMPANY DM_ID)
RETURNS (ID DM_ID,
BEGINNING_DATE DM_DATE,
