ALTER PROCEDURE CMD_GET_COST_PRICE_DOCUMENT (P_COMPANY DM_ID,
P_DOCUMENT DM_ID)
RETURNS (CODE DM_CODE,
INPUT_DATE DM_DATE)
AS 
BEGIN
    FOR
        SELECT DISTINCT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE
        FROM DOCUMENTS
        JOIN ENTRIES COST_PRICE_ENTRIES ON COST_PRICE_ENTRIES.COMPANY = :P_COMPANY AND COST_PRICE_ENTRIES.DOCUMENT = DOCUMENTS.ID
        JOIN ENTRIES REVENUE_ENTRIES ON REVENUE_ENTRIES.COMPANY = :P_COMPANY AND COST_PRICE_ENTRIES.REVENUE_ENTRY = REVENUE_ENTRIES.ID AND REVENUE_ENTRIES.DOCUMENT = :P_DOCUMENT
        WHERE COST_PRICE_ENTRIES.COMPANY = :P_COMPANY
        INTO :CODE, :INPUT_DATE
    DO
        SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_DATABASE_SIZE_MB RETURNS (DB_SIZE DM_BIGINT)
AS 
BEGIN
    SELECT  a.MON$PAGE_SIZE * a.MON$PAGES/1000000
    FROM MON$DATABASE a
    INTO :DB_SIZE;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_DEFAULTS_OF_ACCOUNT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_CODE DM_CODE)
RETURNS (NAME DM_NAME,
ENGLISH_NAME DM_NAME,
MUST_HAVE_OBJECT DM_MUST_HAVE_OBJECTS,
ATOM_TYPE_0 DM_ID,
ATOM_TYPE_1 DM_ID,
ATOM_TYPE_2 DM_ID,
DEFAULT_OBJECT_0 DM_ID,
DEFAULT_OBJECT_1 DM_ID,
DEFAULT_OBJECT_2 DM_ID,
RELATED_OBJECTS DM_RELATED_OBJECTS,
ACCOUNT_TYPES DM_ACCOUNT_TYPES,
CASH_ACTION_LEVEL DM_ACTION_LEVEL,
INVENTORY_ACTION_LEVEL DM_ACTION_LEVEL,
BALANCE_TYPE DM_BALANCE_TYPE)
AS 
BEGIN
    FOR
        SELECT LANGUAGE_ATOM_STRINGS.NAME, ENGLISH_ATOM_STRINGS.NAME, MUST_HAVE_OBJECT, ATOM_TYPE_0, ATOM_TYPE_1, ATOM_TYPE_2, DEFAULT_OBJECT_0, DEFAULT_OBJECT_1, DEFAULT_OBJECT_2, RELATED_OBJECTS, ACCOUNT_TYPES, CASH_ACTION_LEVEL, INVENTORY_ACTION_LEVEL, BALANCE_TYPE
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = LEFT(:P_CODE, CHAR_LENGTH(:P_CODE) -1)
        JOIN ATOM_STRINGS LANGUAGE_ATOM_STRINGS ON LANGUAGE_ATOM_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_ATOM_STRINGS.ID = ACCOUNTS.ID
        LEFT JOIN ATOM_STRINGS ENGLISH_ATOM_STRINGS ON ENGLISH_ATOM_STRINGS.COMPANY = :P_COMPANY AND ENGLISH_ATOM_STRINGS.LANGUAGE = 1 AND ENGLISH_ATOM_STRINGS.ID = ACCOUNTS.ID
        WHERE ACCOUNTS.COMPANY = :P_COMPANY
        INTO :NAME, :ENGLISH_NAME, :MUST_HAVE_OBJECT, :ATOM_TYPE_0, :ATOM_TYPE_1, :ATOM_TYPE_2, :DEFAULT_OBJECT_0, :DEFAULT_OBJECT_1, :DEFAULT_OBJECT_2, :RELATED_OBJECTS, :ACCOUNT_TYPES, :CASH_ACTION_LEVEL, :INVENTORY_ACTION_LEVEL, :BALANCE_TYPE
    DO
        SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_DEFAULT_CURRENCY (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (MAIN_CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE)
