  WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
  INTO :MAIN_CURRENCY, :EXCHANGE_RATE;

  SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_DOCUMENT_CYCLE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_INPUT_DATE DM_DATE)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
DECLARE VARIABLE TIME_1 DM_INTEGER;
DECLARE VARIABLE TIME_2 DM_INTEGER;
DECLARE VARIABLE DOCUMENT_CODE_CYCLE DM_TIME_TYPE;
DECLARE VARIABLE STARTING_DATE DM_DATE;
BEGIN
    SELECT FIRST 1 DOCUMENT_CODE_CYCLE
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :DOCUMENT_CODE_CYCLE;

    TIME_1 = EXTRACT(MONTH FROM P_INPUT_DATE);
    TIME_2 = EXTRACT(YEAR FROM P_INPUT_DATE);

    
    IF(DOCUMENT_CODE_CYCLE = 2)THEN
    BEGIN
        SELECT :TIME_2 || '.' || :TIME_1 || '.1', :TIME_2 || '.' || :TIME_1 || '.' || ENDING_DAY
        FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(DOCUMENT_CODE_CYCLE = 3)THEN
    BEGIN
        TIME_1 = (TIME_1 + 2)/3;
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_QUARTER_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(DOCUMENT_CODE_CYCLE = 4)THEN
    BEGIN
        TIME_1 = IIF(TIME_1 < 7, 0, 1);
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_HALF_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(DOCUMENT_CODE_CYCLE = 5)THEN
    BEGIN
        TIME_1 = TIME_2;
        BEGINNING_DATE = TIME_2 || '.1.1';
        ENDING_DATE = TIME_2 || '.12.31';
    END

    
    SELECT PERIODS.BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :STARTING_DATE;

    IF(STARTING_DATE > BEGINNING_DATE)THEN BEGINNING_DATE = STARTING_DATE;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_EXCHANGE_RATE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (EXCHANGE_RATE DM_DOUBLE)
AS 
BEGIN
  SELECT EXCHANGE_RATE
  FROM  CURRENCIES
  WHERE COMPANY = :P_COMPANY AND ID = :P_ID
  INTO :EXCHANGE_RATE;

  IF(EXCHANGE_RATE IS NULL)THEN EXCHANGE_RATE = 1;

  SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_FUNCTION_RIGHTS (P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
RIGHTS DM_RIGHTS)
AS 
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NEXT_ID DM_ID;
DECLARE VARIABLE NEXT_CODE DM_CODE;
DECLARE VARIABLE RIGHTS_TEMP DM_RIGHTS;
BEGIN
    RIGHTS = 0;
    
    FOR
        SELECT GRANTS.ATOM, IIF(ATOMS.OBJECT_TYPE = 52, ATOMS.CODE, NULL), RIGHTS
        FROM GRANTS
        JOIN MEMBERSHIPS ON MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT AND MEMBERSHIPS.ROLE_ID = GRANTS.ROLE_ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = GRANTS.ATOM AND ATOMS.OBJECT_TYPE <> 88 AND ATOMS.OBJECT_TYPE <> 90
        WHERE GRANTS.COMPANY = :P_COMPANY
        ORDER BY GRANTS.ATOM 
        INTO :NEXT_ID, :NEXT_CODE, :RIGHTS_TEMP
    DO
    BEGIN
        IF(ID IS NULL)THEN
        BEGIN
            ID = NEXT_ID;
            CODE = NEXT_CODE;
            RIGHTS = RIGHTS_TEMP;
        END
        ELSE IF(NEXT_ID = ID)THEN
        BEGIN
            RIGHTS = BIN_OR(RIGHTS, RIGHTS_TEMP);
        END
        ELSE
        BEGIN
            IF(CODE IS NOT NULL)THEN
                ID = CODE;

            SUSPEND;

            ID = NEXT_ID;
            CODE = NEXT_CODE;
            RIGHTS = RIGHTS_TEMP;
        END
    END

    IF(ID IS NOT NULL)THEN
    BEGIN
        IF(CODE IS NOT NULL)THEN
            ID = CODE;
        SUSPEND;
    END
END ^

ALTER PROCEDURE CMD_GET_GUID (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (GUID DM_GUID,
NAME DM_NAME,
TAX_CODE_1 DM_SMALLINT,
TAX_CODE_2 DM_SMALLINT,
TAX_CODE_3 DM_SMALLINT,
TAX_CODE_4 DM_SMALLINT,
TAX_CODE_5 DM_SMALLINT,
TAX_CODE_6 DM_SMALLINT,
TAX_CODE_7 DM_SMALLINT,
TAX_CODE_8 DM_SMALLINT,
TAX_CODE_9 DM_SMALLINT,
TAX_CODE_10 DM_SMALLINT,
TAX_CODE_11 DM_SMALLINT,
TAX_CODE_12 DM_SMALLINT,
TAX_CODE_13 DM_SMALLINT,
PHONE DM_PHONE,
FAX DM_FAX,
ADDRESS DM_ADDRESS,
WEBSITE DM_WEBSITE,
EMAIL DM_EMAIL,
DIRECTOR DM_PERSON_NAME,
CHIEF_ACCOUNTANT DM_PERSON_NAME)
AS 
BEGIN
    SELECT CONFIGURATION.GUID
    FROM CONFIGURATION
    INTO GUID;

    SELECT NAME,
        PHONE, FAX,
        ADDRESS,
        WEBSITE, EMAIL, DIRECTOR,
        CHIEF_ACCOUNTANT,
        TAX_CODE_1,
        TAX_CODE_2,
        TAX_CODE_3,
        TAX_CODE_4,
        TAX_CODE_5,
        TAX_CODE_6,
        TAX_CODE_7,
        TAX_CODE_8,
        TAX_CODE_9,
        TAX_CODE_10,
        TAX_CODE_11,
        TAX_CODE_12,
        TAX_CODE_13
    FROM COMPANIES
    JOIN COMPANY_STRINGS ON COMPANY_STRINGS.COMPANY = :P_COMPANY and COMPANY_STRINGS.LANGUAGE = :P_LANGUAGE AND COMPANY_STRINGS.ID = COMPANIES.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY and ATOMS.ID = COMPANIES.ID
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    WHERE COMPANIES.ID = :P_COMPANY AND COMPANIES.COMPANY = :P_COMPANY
    INTO :NAME, :PHONE, :FAX,
        :ADDRESS, :WEBSITE, :EMAIL, :DIRECTOR,
        :CHIEF_ACCOUNTANT,
        :TAX_CODE_1,
        :TAX_CODE_2,
        :TAX_CODE_3,
        :TAX_CODE_4,
        :TAX_CODE_5,
        :TAX_CODE_6,
        :TAX_CODE_7,
        :TAX_CODE_8,
        :TAX_CODE_9,
        :TAX_CODE_10,
        :TAX_CODE_11,
        :TAX_CODE_12,
        :TAX_CODE_13;

    SUSPEND;
END ^

