ALTER PROCEDURE CMD_GET_LASTEST_CONTENTS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (CONTENT DM_CONTENT)
AS 
BEGIN
    FOR
        SELECT FIRST 100 DISTINCT CONTENT
        FROM
        (
            SELECT FIRST 100 CONTENT, ID
            FROM DOCUMENT_BASE_STRINGS
            WHERE DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND
            DOCUMENT_BASE_STRINGS.CONTENT IS NOT NULL AND DOCUMENT_BASE_STRINGS.CONTENT <> ''

            UNION ALL

            SELECT FIRST 100 CONTENT, ID
            FROM ENTRY_BASE_STRINGS
            WHERE ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND
            ENTRY_BASE_STRINGS.CONTENT IS NOT NULL AND ENTRY_BASE_STRINGS.CONTENT <> ''

            ORDER BY 2 DESC
        )
        INTO :CONTENT
    DO
        SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_LASTEST_FORM_OF_PAYMENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT)
AS 
BEGIN
    FOR
        SELECT FIRST 4 DISTINCT INVOICE_STRINGS.FORMS_OF_PAYMENT
        FROM INVOICE_STRINGS
        WHERE INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND
        INVOICE_STRINGS.FORMS_OF_PAYMENT IS NOT NULL AND INVOICE_STRINGS.FORMS_OF_PAYMENT <> ''
        ORDER BY INVOICE_STRINGS.ID DESC
        INTO :FORMS_OF_PAYMENT
    DO
        SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_LASTEST_GOODS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (GOODS DM_GOODS,
UNIT DM_UNIT)
AS 
BEGIN
    FOR
        SELECT FIRST 50 DISTINCT INVOICE_STRINGS.GOODS, UNIT
        FROM INVOICE_STRINGS
        WHERE INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND
        INVOICE_STRINGS.GOODS IS NOT NULL AND INVOICE_STRINGS.GOODS <> ''
        ORDER BY INVOICE_STRINGS.ID DESC
        INTO :GOODS, :UNIT
    DO
        SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_LASTEST_OUTPUT_SERIAL (P_COMPANY DM_ID)
RETURNS (SERIAL_CODE DM_SERIAL_CODE,
INVOICE_CODE DM_INVOICE_CODE,
CODE_TEMPLATE DM_INVOICE_TEMPLATE,
INVOICE_TEMPLATE DM_INVOICE_TEMPLATE)
AS 
BEGIN
  SELECT FIRST 1 SERIAL_CODE, CODE_TEMPLATE, INVOICE_TEMPLATE
  FROM INVOICES
  WHERE COMPANY = :P_COMPANY AND
  (INVOICE_TYPE = 0 OR INVOICE_TYPE = 5 OR INVOICE_TYPE = 6)
  ORDER BY ID DESC
  INTO :SERIAL_CODE, :CODE_TEMPLATE, :INVOICE_TEMPLATE;

  SELECT MAX(CAST(INVOICE_CODE AS DM_INTEGER))
  FROM INVOICES
  WHERE COMPANY = :P_COMPANY AND
  (INVOICE_TYPE = 0 OR INVOICE_TYPE = 5 OR INVOICE_TYPE = 6) AND
  SERIAL_CODE = :SERIAL_CODE
  INTO :INVOICE_CODE;

  IF(SERIAL_CODE IS NOT NULL)THEN
      SUSPEND;

  WHEN ANY DO INVOICE_CODE = NULL;
END ^

ALTER PROCEDURE CMD_GET_LASTEST_PEOPLE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS)
AS 
BEGIN
    FOR
        SELECT FIRST 99 DISTINCT DOCUMENT_STRINGS.PERSON_NAME, DOCUMENT_STRINGS.PERSON_ADDRESS
        FROM DOCUMENT_STRINGS
        WHERE DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND
        DOCUMENT_STRINGS.PERSON_NAME IS NOT NULL AND DOCUMENT_STRINGS.PERSON_NAME <> ''
        ORDER BY DOCUMENT_STRINGS.ID DESC
        INTO :PERSON_NAME, :PERSON_ADDRESS
    DO
        SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_LASTEST_PERIOD (P_COMPANY DM_ID)
RETURNS (ID DM_ID,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
    SELECT FIRST 1 ID, BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE PERIODS.COMPANY = :P_COMPANY
    ORDER BY ENDING_DATE DESC
    INTO :ID, :BEGINNING_DATE, :ENDING_DATE;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_NEXT_PERIOD (P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (NEXT_PERIOD DM_ID,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
IS_BEGINNING DM_BOOL)
AS 
DECLARE VARIABLE FIRST_BEGINNING_DATE DM_DATE;
DECLARE VARIABLE FIRST_ENDING_DATE DM_DATE;
DECLARE VARIABLE FIRST_PERIOD DM_ID;
BEGIN
    SELECT ACCOUNTING_SETTINGS.BEGINNING_PERIOD, BEGINNING_DATE, ENDING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :FIRST_PERIOD, :FIRST_BEGINNING_DATE, :FIRST_ENDING_DATE;

    SELECT ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID
    INTO :ENDING_DATE;

    IF(ENDING_DATE < FIRST_BEGINNING_DATE)THEN
    BEGIN
        NEXT_PERIOD = FIRST_PERIOD;
        BEGINNING_DATE = FIRST_BEGINNING_DATE;
        ENDING_DATE = FIRST_ENDING_DATE;
        IS_BEGINNING = 1;
    END
    ELSE
    BEGIN
        SELECT ID, BEGINNING_DATE, ENDING_DATE
        FROM PERIODS
        WHERE COMPANY = :P_COMPANY AND BEGINNING_DATE = :ENDING_DATE + 1
        INTO :NEXT_PERIOD, :BEGINNING_DATE, :ENDING_DATE;

        IF(NEXT_PERIOD IS NOT NULL AND NEXT_PERIOD = FIRST_PERIOD)THEN
            IS_BEGINNING = 1;
        ELSE
            IS_BEGINNING = 0;
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_OBJECT1_BY_OBJECT0 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_OBJECT_TYPE DM_ID,
P_RELATED_OBJECT DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE)
AS 
BEGIN
    SELECT FIRST 1 ATOMS.ID, CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.RELATED_OBJECT = :P_RELATED_OBJECT
    INTO :ID, :CODE;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_PERIOD_FROM_DATE (P_COMPANY DM_ID,
P_WORKING_DATE DM_DATE)
RETURNS (ID DM_ID,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
IS_BEGINNING DM_BOOL,
LOCKED DM_BOOL)
AS 
begin
    SELECT ID, BEGINNING_DATE, ENDING_DATE, LOCKED
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND
        :P_WORKING_DATE BETWEEN BEGINNING_DATE AND ENDING_DATE
    INTO :ID, :BEGINNING_DATE, :ENDING_DATE, :LOCKED;

    IF(EXISTS(
        SELECT ID
        FROM ACCOUNTING_SETTINGS
        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY AND ACCOUNTING_SETTINGS.BEGINNING_PERIOD = :ID)
    )THEN
        IS_BEGINNING = 1;
    ELSE
        IS_BEGINNING = 0;

  suspend;
end ^

ALTER PROCEDURE CMD_GET_PERIOD_FROM_ID (P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
IS_BEGINNING DM_BOOL,
LOCKED DM_BOOL)
AS 
BEGIN
    SELECT BEGINNING_DATE, ENDING_DATE, LOCKED
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID
    INTO :BEGINNING_DATE, :ENDING_DATE, :LOCKED;

    IF(EXISTS(
        SELECT ID
        FROM ACCOUNTING_SETTINGS
        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY AND ACCOUNTING_SETTINGS.BEGINNING_PERIOD = :P_ID)
    )THEN
        IS_BEGINNING = 1;
    ELSE
        IS_BEGINNING = 0;

  SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_PREVIOUS_PERIOD (P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (PREVIOUS_PERIOD DM_ID,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
IS_BEGINNING DM_BOOL)
AS 
DECLARE VARIABLE FIRST_BEGINNING_DATE DM_DATE;
DECLARE VARIABLE FIRST_PERIOD DM_ID;
BEGIN
    SELECT ACCOUNTING_SETTINGS.BEGINNING_PERIOD, BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :FIRST_PERIOD, :FIRST_BEGINNING_DATE;

    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID
    INTO :BEGINNING_DATE, :ENDING_DATE;

    IS_BEGINNING = 0;

    IF(BEGINNING_DATE >= FIRST_BEGINNING_DATE)THEN
    BEGIN
        SELECT ID, BEGINNING_DATE, ENDING_DATE
        FROM PERIODS
        WHERE COMPANY = :P_COMPANY AND ENDING_DATE = :BEGINNING_DATE - 1
        INTO :PREVIOUS_PERIOD, :BEGINNING_DATE, :ENDING_DATE;

        IF(BEGINNING_DATE IS NOT NULL AND BEGINNING_DATE >= FIRST_BEGINNING_DATE)THEN
        BEGIN
            IF(FIRST_PERIOD = PREVIOUS_PERIOD)THEN
                IS_BEGINNING = 1;
            ELSE
                IS_BEGINNING = 0;
        END
        ELSE
            PREVIOUS_PERIOD = NULL;

    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_PRICE (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_GOODS DM_ID,
P_WAREHOUSE DM_ID,
P_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_ENTRY DM_ID)
RETURNS (AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT AMOUNT, SUM_OF_MONEY
    FROM INT_SD_1_TK_1_VT_1_KHO_CN_EX(:P_COMPANY, :P_ACCOUNT, :P_GOODS, :P_WAREHOUSE, :P_DATE, :P_DOCUMENT, :P_ENTRY)
    INTO :AMOUNT, :SUM_OF_MONEY;

    IF(ROUND(AMOUNT, 5) <> 0)THEN
    BEGIN
        SELECT NUMBER_DECIMAL_DIGITS
        FROM SETTINGS
        WHERE SETTINGS.COMPANY = :P_COMPANY
        INTO :NUMBER_DECIMAL_DIGITS;

        PRICE = ROUND(SUM_OF_MONEY/AMOUNT, NUMBER_DECIMAL_DIGITS);
    END
    ELSE PRICE = 0;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_RELATED_OBJECT_TYPE (P_OBJECT_TYPE DM_ID)
RETURNS (RELATED_OBJECT_TYPE DM_ID,
NAME DM_NAME)
AS 
BEGIN
    SELECT OBJECTS.RELATED_OBJECT_TYPE, RELATED_OBJECTS.NAME
    FROM OBJECT_TYPES OBJECTS
    JOIN OBJECT_TYPES RELATED_OBJECTS ON RELATED_OBJECTS.ID = OBJECTS.RELATED_OBJECT_TYPE
    WHERE OBJECTS.ID = :P_OBJECT_TYPE
    INTO :RELATED_OBJECT_TYPE, :NAME;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_GET_REPORT_PROCEDURES RETURNS (PROCEDURE_NAME DM_PROCEDURE_NAME)
AS 
BEGIN
    FOR
        SELECT RDB$PROCEDURE_NAME
        FROM RDB$PROCEDURES
        WHERE RDB$PROCEDURE_NAME STARTING WITH 'RPT_'
        INTO :PROCEDURE_NAME
    DO
    BEGIN
        PROCEDURE_NAME = TRIM(PROCEDURE_NAME);
        SUSPEND;
    END
END ^

ALTER PROCEDURE CMD_IMMEDIATE_AVERAGE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAMS DM_NAME,
P_ACCOUNT DM_ID = NULL)
AS 
DECLARE VARIABLE DOCUMENT_TEAM_ID DM_ID;
BEGIN
    DELETE FROM TEMP_IMMEDIATE_AVERAGE;

    FOR
        SELECT ID
        FROM INT_SPLIT_STRING(:P_DOCUMENT_TEAMS, ',')
        INTO :DOCUMENT_TEAM_ID
    DO
    BEGIN
        EXECUTE PROCEDURE CMD_TEMP_IMMEDIATE_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :DOCUMENT_TEAM_ID, :P_ACCOUNT);
    END

    EXECUTE PROCEDURE CMD_CAL_IMMEDIATE_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD);
END ^

ALTER PROCEDURE CMD_IMPORT_DOCUMENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_CURRENT_PERIOD DM_ID,
P_AUTO_TEAM DM_BOOL,
P_TEAM DM_ID,
P_DOCUMENT DM_ID,
P_LOAIHOADON DM_INVOICE_TYPE,
P_NGAYHOADON DM_DATE,
P_KYHIEUHOADON DM_INVOICE_CODE,
P_SOHOADON DM_SERIAL_CODE,
P_TENDONVIMUABAN DM_NAME,
P_DIACHI DM_ADDRESS,
P_MASOTHUE DM_TAX_CODE,
P_HANGHOA DM_GOODS,
P_PHANTRAMGTGT DM_DOUBLE,
P_NGOAITE DM_CODE,
P_TYGIA DM_DOUBLE,
P_SOLUONG DM_DOUBLE,
P_DONGIA DM_DOUBLE,
P_NGUYENTE DM_DOUBLE,
P_TIENTRUOCTHUE DM_DOUBLE,
P_TIENTHUEGTGT DM_DOUBLE,
P_TENNGUOINHANNOPTIEN DM_PERSON_NAME,
P_DIACHINGUOINHANNOPTIEN DM_ADDRESS,
P_NOIDUNG DM_CONTENT,
P_CHUNGTUGOC DM_ORIGINAL_VOUCHERS,
P_GHICHU1 DM_ADDITION_INFO,
P_GHICHU2 DM_ADDITION_INFO,
P_GHICHU3 DM_ADDITION_INFO,
P_GHICHU4 DM_ADDITION_INFO,
P_TAIKHOANNO DM_CODE,
P_DOITUONGNO1 DM_CODE,
P_DOITUONGNO2 DM_CODE,
P_TAIKHOANCO DM_CODE,
P_DOITUONGCO1 DM_CODE,
P_DOITUONGCO2 DM_CODE)
RETURNS (IS_SUCESS DM_BOOL,
ID DM_ID,
CODE DM_CODE,
INPUT_DATE DM_DATE,
ERROR DM_DESCRIPTION)
AS 
declare variable number dm_code;
declare variable main_currency dm_id;
declare variable currency dm_id;
declare variable period dm_id;
declare variable debit_account dm_id;
declare variable debit_atom_type_0 dm_id;
declare variable debit_atom_type_1 dm_id;
declare variable debit_object_0 dm_id;
declare variable debit_object_1 dm_id;
declare variable credit_account dm_id;
declare variable credit_object_0 dm_id;
declare variable credit_object_1 dm_id;
declare variable credit_atom_type_0 dm_id;
declare variable credit_atom_type_1 dm_id;
declare variable number_decimal_digits dm_integer;
declare variable hach_toan_thue_gtgt dm_bool = 0;
declare variable thue_gtgt_account dm_id;
declare variable credit_debit_id dm_id;
declare variable document_team dm_id;
BEGIN
    IS_SUCESS = 1;

    IF(P_NGAYHOADON IS NULL)THEN
    BEGIN
        IS_SUCESS = 0;
        ERROR = 'Thiếu ngày hóa đơn';
    END
    ELSE
    BEGIN
        SELECT NUMBER_DECIMAL_DIGITS
        FROM SETTINGS
        WHERE SETTINGS.COMPANY = :P_COMPANY
        INTO :NUMBER_DECIMAL_DIGITS;

        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY
        INTO :MAIN_CURRENCY;

        P_SOLUONG = TRUNC(P_SOLUONG, NUMBER_DECIMAL_DIGITS);
        P_DONGIA = TRUNC(P_DONGIA, NUMBER_DECIMAL_DIGITS);
        P_TIENTRUOCTHUE = TRUNC(P_TIENTRUOCTHUE, 0);
        P_TIENTHUEGTGT = TRUNC(P_TIENTHUEGTGT, 0);

        IF(P_NGOAITE IS NULL OR P_NGOAITE = '')THEN
        BEGIN
            CURRENCY = MAIN_CURRENCY;
            P_TYGIA = 1;
        END
        ELSE
        BEGIN
            SELECT CURRENCIES.ID
            FROM CURRENCIES
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CURRENCIES.ID AND ATOMS.CODE = :P_NGOAITE
            INTO :CURRENCY;

            IF(CURRENCY IS NULL)THEN
            BEGIN
                CURRENCY = MAIN_CURRENCY;
                P_TYGIA = 1;
            END
            ELSE IF(P_TYGIA IS NULL)THEN
                P_TYGIA = 1;
        END

        IF(P_DOCUMENT IS NULL)THEN
        BEGIN
            SELECT ID
            FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAYHOADON)
            INTO :PERIOD;

            IF(PERIOD IS NOT NULL AND PERIOD = p_current_period )THEN 
            BEGIN
                P_DOCUMENT = GEN_ID(UNIVERSE, 1);

                IF(P_AUTO_TEAM = 1)THEN
                BEGIN
                    SELECT DOCUMENT_TEAM
                    FROM INT_DOCUMENT_TEAM_BY_ACCOUNT(:P_COMPANY, :P_TAIKHOANNO, :P_TAIKHOANCO)
                    INTO :DOCUMENT_TEAM;
                END

                IF(DOCUMENT_TEAM IS NULL)THEN DOCUMENT_TEAM = P_TEAM;

                SELECT CODE, NUMBER
                FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM , :P_NGAYHOADON)
                INTO :CODE, :NUMBER;

                INPUT_DATE = P_NGAYHOADON;

                EXECUTE PROCEDURE DOCUMENT_IU(P_LANGUAGE, P_COMPANY, P_DOCUMENT, NULL,  0, p_ghichu1, p_ghichu2, p_ghichu3, p_ghichu4, CODE, NUMBER, CURRENCY, P_TYGIA, INPUT_DATE, NULL, P_CHUNGTUGOC, PERIOD, DOCUMENT_TEAM, P_NGAYHOADON, NULL, P_TENNGUOINHANNOPTIEN,  P_DIACHINGUOINHANNOPTIEN, P_NOIDUNG, 0, 0);

                SELECT ACCOUNTS.ID, ATOM_TYPE_0, ATOM_TYPE_1
                FROM ACCOUNTS
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :P_TAIKHOANNO
                WHERE NOT EXISTS (SELECT 1 FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ACCOUNTS.ID)
                INTO :DEBIT_ACCOUNT, :DEBIT_ATOM_TYPE_0, :DEBIT_ATOM_TYPE_1;

                IF(DEBIT_ATOM_TYPE_0 IS NOT NULL)THEN
                    SELECT ID
                    FROM ATOMS
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :DEBIT_ATOM_TYPE_0 AND ATOMS.CODE = :P_DOITUONGNO1
                    INTO :DEBIT_OBJECT_0;

                IF(DEBIT_ATOM_TYPE_1 IS NOT NULL)THEN
                    SELECT ID
                    FROM ATOMS
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :DEBIT_ATOM_TYPE_1 AND ATOMS.CODE = :P_DOITUONGNO2
                    INTO :DEBIT_OBJECT_1;

                SELECT ACCOUNTS.ID, ATOM_TYPE_0, ATOM_TYPE_1
                FROM ACCOUNTS
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :P_TAIKHOANCO
                WHERE NOT EXISTS (SELECT 1 FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ACCOUNTS.ID)
                INTO :CREDIT_ACCOUNT, :CREDIT_ATOM_TYPE_0, :CREDIT_ATOM_TYPE_1;

                IF(CREDIT_ATOM_TYPE_0 IS NOT NULL)THEN
                    SELECT ID
                    FROM ATOMS
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :CREDIT_ATOM_TYPE_0 AND ATOMS.CODE = :P_DOITUONGCO1
                    INTO :CREDIT_OBJECT_0;

                IF(CREDIT_ATOM_TYPE_1 IS NOT NULL)THEN
                    SELECT ID
                    FROM ATOMS
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :CREDIT_ATOM_TYPE_1 AND ATOMS.CODE = :P_DOITUONGCO2
                    INTO :CREDIT_OBJECT_1;

                IF(DEBIT_ACCOUNT IS NOT NULL AND (DEBIT_ATOM_TYPE_0 IS NULL OR DEBIT_OBJECT_0 IS NOT NULL) AND (DEBIT_ATOM_TYPE_1 IS NULL OR DEBIT_OBJECT_1 IS NOT NULL))THEN
                BEGIN
                    IF(CREDIT_ACCOUNT IS NOT NULL AND (CREDIT_ATOM_TYPE_0 IS NULL OR CREDIT_OBJECT_0 IS NOT NULL) AND (CREDIT_ATOM_TYPE_1 IS NULL OR CREDIT_OBJECT_1 IS NOT NULL))THEN
                    BEGIN
                        EXECUTE PROCEDURE DOUBLE_ENTRY_IU(P_LANGUAGE, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, CURRENCY, P_DOCUMENT, P_TYGIA, P_PHANTRAMGTGT, 0, NULL, NULL, P_NOIDUNG,
                            GEN_ID(UNIVERSE, 1), DEBIT_ACCOUNT, DEBIT_OBJECT_0, DEBIT_OBJECT_1, NULL, GEN_ID(UNIVERSE, 1), CREDIT_ACCOUNT, CREDIT_OBJECT_0, CREDIT_OBJECT_1, NULL, P_SOLUONG, P_DONGIA, P_NGUYENTE, P_TIENTRUOCTHUE);
                    END
                    ELSE
                    BEGIN
                        IS_SUCESS = 0;
                        ERROR = 'Số tài khoản hoặc mã đối tượng Bên Có không đúng';
                    END
                END
                ELSE
                BEGIN
                    IS_SUCESS = 0;
                    ERROR = 'Số tài khoản hoặc mã đối tượng Bên Nợ không đúng';
                END

                IF( IS_SUCESS = 1 AND
                    P_LOAIHOADON IS NOT NULL AND
                    P_KYHIEUHOADON IS NOT NULL AND
                    P_SOHOADON IS NOT NULL AND
                    P_TENDONVIMUABAN IS NOT NULL AND
                    P_HANGHOA IS NOT NULL AND
                    NOT EXISTS(
                        SELECT 1
                        FROM INVOICES
                        JOIN DOCUMENTS ON DOCUMENTS.ID = INVOICES.document AND DOCUMENTS.period = :period
                        WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_CODE = :P_SOHOADON AND INVOICES.SERIAL_CODE = :P_KYHIEUHOADON
                    )
                )THEN
                BEGIN
                    HACH_TOAN_THUE_GTGT = 1;
                    EXECUTE PROCEDURE INVOICE_IU(P_LANGUAGE, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, NULL, NULL, NULL, NULL, P_DIACHI, P_TENDONVIMUABAN, P_MASOTHUE, P_DOCUMENT, P_HANGHOA, NULL, INPUT_DATE, P_SOHOADON, P_NGAYHOADON, NULL, NULL, P_LOAIHOADON, P_KYHIEUHOADON, P_TIENTRUOCTHUE, P_TIENTHUEGTGT, P_PHANTRAMGTGT, NULL, 0);
                END

                IF(IS_SUCESS = 1 AND HACH_TOAN_THUE_GTGT = 1 AND P_TIENTHUEGTGT > 0)THEN 
                BEGIN
                    IF(P_LOAIHOADON = 5)THEN 
                    BEGIN
                        SELECT ACCOUNTS.ID
                        FROM ACCOUNTS
                        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '33311'
                        INTO :THUE_GTGT_ACCOUNT;

                        IF(THUE_GTGT_ACCOUNT IS NOT NULL AND 
                            DEBIT_ACCOUNT IS NOT NULL AND (DEBIT_ATOM_TYPE_0 IS NULL OR DEBIT_OBJECT_0 IS NOT NULL) AND (DEBIT_ATOM_TYPE_1 IS NULL OR DEBIT_OBJECT_1 IS NOT NULL))THEN
                        BEGIN
                            P_NOIDUNG = 'Thuế GTGT đầu ra của HHDV';
                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(P_LANGUAGE, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, CURRENCY, P_DOCUMENT, P_TYGIA, P_PHANTRAMGTGT, 0, NULL, NULL, P_NOIDUNG,
                                GEN_ID(UNIVERSE, 1), DEBIT_ACCOUNT, DEBIT_OBJECT_0, DEBIT_OBJECT_1, NULL, GEN_ID(UNIVERSE, 1), THUE_GTGT_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, P_TIENTHUEGTGT);
                        END
                    END
                    ELSE  
                    BEGIN
                        SELECT ACCOUNTS.ID
                        FROM ACCOUNTS
                        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '1331'
                        INTO :THUE_GTGT_ACCOUNT;

                        IF(THUE_GTGT_ACCOUNT IS NOT NULL AND 
                            CREDIT_ACCOUNT IS NOT NULL AND (CREDIT_ATOM_TYPE_0 IS NULL OR CREDIT_OBJECT_0 IS NOT NULL) AND (CREDIT_ATOM_TYPE_1 IS NULL OR CREDIT_OBJECT_1 IS NOT NULL))THEN
                        BEGIN
                            P_NOIDUNG = 'Thuế GTGT đầu vào của HHDV';
                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(P_LANGUAGE, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, CURRENCY, P_DOCUMENT, P_TYGIA, P_PHANTRAMGTGT, 0, NULL, NULL, P_NOIDUNG,
                                GEN_ID(UNIVERSE, 1), THUE_GTGT_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), CREDIT_ACCOUNT, CREDIT_OBJECT_0, CREDIT_OBJECT_1, NULL, 0, 0, 0, P_TIENTHUEGTGT);
                        END
                    END
                END

                ID = P_DOCUMENT;
                CODE = CODE || '-' || NUMBER;
            END
            ELSE
            BEGIN
                IS_SUCESS = 0;
                ERROR = 'Ngày hóa đơn không nằm trong các kỳ kế toán được mở(cần mở thêm kỳ kế toán)';
            END
        END
        ELSE
        BEGIN
            
            SELECT ACCOUNTS.ID, ATOM_TYPE_0, ATOM_TYPE_1
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :P_TAIKHOANNO
            WHERE NOT EXISTS (SELECT 1 FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ACCOUNTS.ID)
            INTO :DEBIT_ACCOUNT, :DEBIT_ATOM_TYPE_0, :DEBIT_ATOM_TYPE_1;

            IF(DEBIT_ATOM_TYPE_0 IS NOT NULL)THEN
                SELECT ID
                FROM ATOMS
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :DEBIT_ATOM_TYPE_0 AND ATOMS.CODE = :P_DOITUONGNO1
                INTO :DEBIT_OBJECT_0;

            IF(DEBIT_ATOM_TYPE_1 IS NOT NULL)THEN
                SELECT ID
                FROM ATOMS
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :DEBIT_ATOM_TYPE_1 AND ATOMS.CODE = :P_DOITUONGNO2
                INTO :DEBIT_OBJECT_1;

            SELECT ACCOUNTS.ID, ATOM_TYPE_0, ATOM_TYPE_1
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :P_TAIKHOANCO
            WHERE NOT EXISTS (SELECT 1 FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ACCOUNTS.ID)
            INTO :CREDIT_ACCOUNT, :CREDIT_ATOM_TYPE_0, :CREDIT_ATOM_TYPE_1;

            IF(CREDIT_ATOM_TYPE_0 IS NOT NULL)THEN
                SELECT ID
                FROM ATOMS
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :CREDIT_ATOM_TYPE_0 AND ATOMS.CODE = :P_DOITUONGCO1
                INTO :CREDIT_OBJECT_0;

            IF(CREDIT_ATOM_TYPE_1 IS NOT NULL)THEN
                SELECT ID
                FROM ATOMS
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :CREDIT_ATOM_TYPE_1 AND ATOMS.CODE = :P_DOITUONGCO2
                INTO :CREDIT_OBJECT_1;

            IF(DEBIT_ACCOUNT IS NOT NULL AND (DEBIT_ATOM_TYPE_0 IS NULL OR DEBIT_OBJECT_0 IS NOT NULL) AND (DEBIT_ATOM_TYPE_1 IS NULL OR DEBIT_OBJECT_1 IS NOT NULL))THEN
            BEGIN
                IF(CREDIT_ACCOUNT IS NOT NULL AND (CREDIT_ATOM_TYPE_0 IS NULL OR CREDIT_OBJECT_0 IS NOT NULL) AND (CREDIT_ATOM_TYPE_1 IS NULL OR CREDIT_OBJECT_1 IS NOT NULL))THEN
                BEGIN
                    EXECUTE PROCEDURE DOUBLE_ENTRY_IU(P_LANGUAGE, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, CURRENCY, P_DOCUMENT, P_TYGIA, P_PHANTRAMGTGT, 0, NULL, NULL, P_NOIDUNG,
                        GEN_ID(UNIVERSE, 1), DEBIT_ACCOUNT, DEBIT_OBJECT_0, DEBIT_OBJECT_1, NULL, GEN_ID(UNIVERSE, 1), CREDIT_ACCOUNT, CREDIT_OBJECT_0, CREDIT_OBJECT_1, NULL, P_SOLUONG, P_DONGIA, P_NGUYENTE, P_TIENTRUOCTHUE);
                END
                ELSE
                BEGIN
                    IS_SUCESS = 0;
                    ERROR = 'Số tài khoản hoặc mã đối tượng Bên Có không đúng';
                END
            END
            ELSE
            BEGIN
                IS_SUCESS = 0;
                ERROR = 'Số tài khoản hoặc mã đối tượng Bên Nợ không đúng';
            END
            
            FOR
                SELECT FIRST 1 ENTRIES.ID
                FROM ENTRIES
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID
                JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
                JOIN ATOMS CREDIT_ACCOUNT_ATOM ON CREDIT_ACCOUNT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT_ATOM.ID = CREDIT_ACCOUNT.ID
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID
                JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
                JOIN ATOMS DEBIT_ACCOUNT_ATOM ON DEBIT_ACCOUNT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT_ATOM.ID = DEBIT_ACCOUNT.ID
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_DOCUMENT AND
                (CREDIT_ACCOUNT_ATOM.CODE = '33311' OR DEBIT_ACCOUNT_ATOM.CODE = '1331')
                INTO :CREDIT_DEBIT_ID
            DO
            BEGIN
                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY + :P_TIENTHUEGTGT
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :CREDIT_DEBIT_ID;
            END

            IF(IS_SUCESS = 1)THEN
            BEGIN
                IF( P_LOAIHOADON IS NOT NULL AND
                    P_KYHIEUHOADON IS NOT NULL AND
                    P_SOHOADON IS NOT NULL AND
                    P_TENDONVIMUABAN IS NOT NULL AND
                    P_HANGHOA IS NOT NULL AND
                        NOT EXISTS(
                            SELECT 1
                            FROM INVOICES
                            JOIN DOCUMENTS ON DOCUMENTS.ID = INVOICES.document AND DOCUMENTS.period = :period
                            WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_CODE = :P_SOHOADON AND INVOICES.SERIAL_CODE = :P_KYHIEUHOADON
                        )
                )THEN
                BEGIN
                    HACH_TOAN_THUE_GTGT = 1;
                    EXECUTE PROCEDURE INVOICE_IU(P_LANGUAGE, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, NULL, NULL, NULL, NULL, P_DIACHI, P_TENDONVIMUABAN, P_MASOTHUE, P_DOCUMENT, P_HANGHOA, NULL, P_NGAYHOADON, P_SOHOADON, P_NGAYHOADON, NULL, NULL, P_LOAIHOADON, P_KYHIEUHOADON, P_TIENTRUOCTHUE, P_TIENTHUEGTGT, P_PHANTRAMGTGT, NULL, 0);
                END
                ELSE
                BEGIN
                    UPDATE INVOICES
                    SET INVOICES.SUM_OF_MONEY = INVOICES.SUM_OF_MONEY + :P_TIENTRUOCTHUE,
                        INVOICES.SUM_OF_TAX = INVOICES.SUM_OF_TAX + :P_TIENTHUEGTGT
                    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :P_DOCUMENT AND INVOICES.INVOICE_CODE = :P_SOHOADON AND INVOICES.SERIAL_CODE = :P_KYHIEUHOADON AND INVOICES.INVOICE_DATE = :P_NGAYHOADON;
                END
            END

            ID = P_DOCUMENT;
        END
    END

    SUSPEND;
END ^

ALTER PROCEDURE CMD_INACTIVE_ALL_TRIGGERS AS 
DECLARE VARIABLE TRIGGER_NAME VARCHAR(31);
BEGIN
    FOR
        SELECT RDB$TRIGGERS.RDB$TRIGGER_NAME FROM RDB$TRIGGERS
        WHERE RDB$TRIGGERS.RDB$SYSTEM_FLAG = 0 AND RDB$TRIGGERS.RDB$TRIGGER_INACTIVE = 0
        INTO :TRIGGER_NAME
    DO
    BEGIN
        EXECUTE STATEMENT 'ALTER TRIGGER ' || :TRIGGER_NAME || ' INACTIVE';
    END
END ^

ALTER PROCEDURE CMD_IS_FIRST_TIME RETURNS (IS_FIRST_TIME DM_BOOL)
AS 
BEGIN
  IF(EXISTS (SELECT ID FROM COMPANIES))THEN
    IS_FIRST_TIME = 0;
  ELSE
    IS_FIRST_TIME = 1;

  SUSPEND;
END ^

ALTER PROCEDURE CMD_IS_LEAP_YEAR (YEAR_TO_CHECK DM_INTEGER)
RETURNS (IS_LEAP_YEAR DM_BOOL)
AS 
BEGIN
  IF(MOD(YEAR_TO_CHECK, 400) = 0 OR (MOD(YEAR_TO_CHECK, 4) = 0 AND (MOD(YEAR_TO_CHECK, 100) <> 0)))THEN
    IS_LEAP_YEAR = 1;
  ELSE
    IS_LEAP_YEAR = 0;

  SUSPEND;
END ^

ALTER PROCEDURE CMD_IS_LOCKED (P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (LOCKED DM_BOOL)
AS 
begin
    SELECT LOCKED
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :LOCKED;

    suspend;
end ^

ALTER PROCEDURE CMD_IS_MONTH (P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (IS_MONTH DM_BOOL)
AS 
DECLARE VARIABLE IS_LEAP_YEAR DM_BOOL;
DECLARE VARIABLE FROM_DAY DM_INTEGER;
DECLARE VARIABLE FROM_MONTH DM_INTEGER;
DECLARE VARIABLE FROM_YEAR DM_INTEGER;
DECLARE VARIABLE TO_DAY DM_INTEGER;
DECLARE VARIABLE TO_MONTH DM_INTEGER;
DECLARE VARIABLE TO_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_DAY DM_INTEGER;
BEGIN
    FROM_DAY = EXTRACT(DAY FROM P_FROM_DATE);
    FROM_MONTH = EXTRACT(MONTH FROM P_FROM_DATE);
    FROM_YEAR = EXTRACT(YEAR FROM P_FROM_DATE);

    TO_DAY = EXTRACT(DAY FROM P_TO_DATE);
    TO_MONTH = EXTRACT(MONTH FROM P_TO_DATE);
    TO_YEAR = EXTRACT(YEAR FROM P_TO_DATE);

    IF(FROM_DAY = 1 AND FROM_YEAR = TO_YEAR AND FROM_MONTH = TO_MONTH)THEN
    BEGIN
        SELECT ENDING_DAY
        FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:FROM_MONTH, :FROM_YEAR)
        INTO :ENDING_DAY;

        IF(ENDING_DAY = TO_DAY)THEN IS_MONTH = 1;
    END
    ELSE
        IS_MONTH = 0;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_MADE_AUTO_ENTRY (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_VAT_DEDUCTION DM_BOOL,
P_TRANSFER_ACCOUNTS DM_BOOL,
P_CAL_OUTPUT_PRICE DM_BOOL,
P_PRODUCT_PRICE DM_BOOL,
P_DOCUMENT_TEAMS DM_NAME,
P_154_ONLY DM_BOOL)
AS 
declare variable beginning_year dm_date;
declare variable beginning_date dm_date;
declare variable ending_date dm_date;
declare variable source_id dm_id;
declare variable source_account dm_id;
declare variable source_object_type0 dm_id;
declare variable source_object_type1 dm_id;
declare variable source_object0 dm_id;
declare variable source_object1 dm_id;
declare variable transfer_all dm_bool;
declare variable target_id dm_id;
declare variable target_account dm_id;
declare variable target_object_type0 dm_id;
declare variable target_object_type1 dm_id;
declare variable target_object0 dm_id;
declare variable target_object1 dm_id;
declare variable transfer_type dm_transfer_type;
declare variable document_team dm_id;
declare variable percent_document_team dm_id;
declare variable percent dm_double;
declare variable object_percent dm_double;
declare variable source_debit dm_double;
declare variable source_credit dm_double;
declare variable target_debit dm_double;
declare variable target_credit dm_double;
declare variable transfered_debit dm_double;
declare variable transfered_credit dm_double;
declare variable row_number dm_integer;
declare variable row_number_object dm_integer;
declare variable current_row dm_integer;
declare variable current_row_object dm_integer;
declare variable code dm_code;
declare variable number dm_code;
declare variable document dm_id;
declare variable main_currency dm_id;
declare variable document_content dm_content;
declare variable entry_content dm_content;
declare variable has_entry dm_bool;
declare variable total_of_object dm_double;
declare variable remaining_of_object dm_double;
declare variable sum_of_money dm_double;
declare variable text_from_account dm_text_content;
declare variable text_to_account dm_text_content;
declare variable source_account_code dm_code;
declare variable target_account_code dm_code;
declare variable source_object0_code dm_code;
declare variable source_object1_code dm_code;
declare variable target_object0_code dm_code;
declare variable target_object1_code dm_code;
declare variable sum_prev_percent dm_double;
declare variable output_price_method dm_output_price_method;
BEGIN
    SELECT MAIN_CURRENCY, TRANSFER_DOCUMENT_TEAM, PERCENT_DOCUMENT_TEAM, OUTPUT_PRICE_METHOD
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :MAIN_CURRENCY, :DOCUMENT_TEAM, :PERCENT_DOCUMENT_TEAM, :OUTPUT_PRICE_METHOD;

    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE PERIODS.COMPANY =:P_COMPANY AND PERIODS.ID = :P_PERIOD
    INTO :BEGINNING_DATE, :ENDING_DATE;

    IF(P_154_ONLY = 0 AND (P_VAT_DEDUCTION = 1 OR P_TRANSFER_ACCOUNTS = 1))THEN
    BEGIN
        DELETE FROM DOCUMENTS
        WHERE COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD AND (TEAM = :DOCUMENT_TEAM OR TEAM = :PERCENT_DOCUMENT_TEAM);
    END

    
    IF(P_154_ONLY = 0 AND P_VAT_DEDUCTION = 1)THEN
    BEGIN
        EXECUTE PROCEDURE CMD_VAT_DEDUCTION(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :DOCUMENT_TEAM, :BEGINNING_DATE, :ENDING_DATE, :MAIN_CURRENCY);
    END

    
    IF(P_TRANSFER_ACCOUNTS = 1)THEN
    BEGIN
    FOR
        SELECT SOURCE_ACCOUNTS.ID, TRANSFER_ALL, DOCUMENT_CONTENT, ACCOUNT,
            ATOM_TYPE_0, ATOM_TYPE_1,
            SOURCE_ACCOUNTS.OBJECT0, SOURCE_ACCOUNTS.OBJECT1
        FROM SOURCE_ACCOUNTS
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = SOURCE_ACCOUNTS.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = SOURCE_ACCOUNTS.ACCOUNT AND
                    (
                        :P_154_ONLY = 0 OR
                        (
                            ATOMS.CODE STARTING WITH '621' OR
                            ATOMS.CODE STARTING WITH '622' OR
                            ATOMS.CODE STARTING WITH '623' OR
                            ATOMS.CODE STARTING WITH '627' OR
                            ATOMS.CODE STARTING WITH '154'
                        )
                    )
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = SOURCE_ACCOUNTS.ID
        WHERE SOURCE_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNTS.PERIOD = :P_PERIOD
        ORDER BY ORDINAL
        INTO :SOURCE_ID, :TRANSFER_ALL, :DOCUMENT_CONTENT, :SOURCE_ACCOUNT,
            :SOURCE_OBJECT_TYPE0, :SOURCE_OBJECT_TYPE1,
            :SOURCE_OBJECT0, :SOURCE_OBJECT1
    DO
    BEGIN
        IF(SOURCE_OBJECT0 IS NULL)THEN
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_CN(:P_COMPANY, :SOURCE_ACCOUNT, :ENDING_DATE)
            INTO :SOURCE_DEBIT, :SOURCE_CREDIT;

            SELECT COUNT(ID)
            FROM TARGET_ACCOUNTS
            WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNT = :SOURCE_ID AND TARGET_ACCOUNTS.TRANSFER_TYPE > 0
            INTO :ROW_NUMBER;

            IF((SOURCE_DEBIT <> 0 OR SOURCE_CREDIT <> 0) AND ROW_NUMBER > 0)THEN
            BEGIN
                CURRENT_ROW = 0;
                TRANSFERED_DEBIT = 0;
                TRANSFERED_CREDIT = 0;

                FOR
                    SELECT TARGET_ACCOUNTS.ID, ACCOUNT, TRANSFER_TYPE, IIF(TARGET_ACCOUNTS.TARGET_PERCENT IS NULL, TARGET_ACCOUNTS.PERCENT, TARGET_PERCENTS.PERCENT),
                            ATOM_TYPE_0, ATOM_TYPE_1,
                            OBJECT0, OBJECT1
                    FROM TARGET_ACCOUNTS
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNTS.ACCOUNT
                    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TARGET_ACCOUNTS.ID
                    LEFT JOIN TARGET_PERCENTS ON TARGET_PERCENTS.COMPANY = :P_COMPANY AND TARGET_PERCENTS.ID = TARGET_ACCOUNTS.TARGET_PERCENT
                    WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNT = :SOURCE_ID AND TARGET_ACCOUNTS.TRANSFER_TYPE > 0 AND
                        (:P_154_ONLY = 0 OR TRANSFER_TYPE <> 4) 
                    ORDER BY ORDINAL
                    INTO :TARGET_ID, :TARGET_ACCOUNT, :TRANSFER_TYPE, :PERCENT,
                    :TARGET_OBJECT_TYPE0, :TARGET_OBJECT_TYPE1,
                    :TARGET_OBJECT0, :TARGET_OBJECT1
                DO
                BEGIN
                    CURRENT_ROW = CURRENT_ROW + 1;

                    TARGET_DEBIT = ROUND(SOURCE_DEBIT * PERCENT, 0);
                    TARGET_CREDIT = ROUND(SOURCE_CREDIT * PERCENT, 0);

                    TRANSFERED_DEBIT = TRANSFERED_DEBIT + TARGET_DEBIT;
                    TRANSFERED_CREDIT = TRANSFERED_CREDIT + TARGET_CREDIT;

                    IF(CURRENT_ROW = ROW_NUMBER AND TRANSFER_ALL = 1)THEN
                    BEGIN
                        IF(TRANSFERED_DEBIT < SOURCE_DEBIT)THEN
                            TARGET_DEBIT = TARGET_DEBIT + SOURCE_DEBIT - TRANSFERED_DEBIT;

                        IF(TRANSFERED_CREDIT < SOURCE_CREDIT)THEN
                            TARGET_CREDIT = TARGET_CREDIT + SOURCE_CREDIT - TRANSFERED_CREDIT;
                    END

                    IF(TRANSFER_TYPE = 1)THEN
                    BEGIN
                        SELECT CODE, NUMBER
                        FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :ENDING_DATE)
                        INTO :CODE, :NUMBER;

                        DOCUMENT = GEN_ID(UNIVERSE, 1);
                        EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL,  0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :MAIN_CURRENCY, 1, :ENDING_DATE, NULL, NULL, :P_PERIOD, :DOCUMENT_TEAM, :ENDING_DATE, NULL, NULL, NULL, :DOCUMENT_CONTENT, 0, 0);

                        IF(
                            (SOURCE_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE0 IS NULL) AND
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_NORMAL(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NULL) AND
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NULL) AND
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S01(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE0 = TARGET_OBJECT_TYPE0) AND
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T0(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE0 = TARGET_OBJECT_TYPE0) AND
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S01_T0(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE1 = TARGET_OBJECT_TYPE0) AND
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S10_T0(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE0 = TARGET_OBJECT_TYPE0) AND
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE1 = TARGET_OBJECT_TYPE1)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S01_T01(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE1 = TARGET_OBJECT_TYPE0) AND
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE0 = TARGET_OBJECT_TYPE1)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S10_T10(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (TARGET_OBJECT0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_T0_PB(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (TARGET_OBJECT0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NOT NULL) AND
                            (TARGET_OBJECT1 IS NOT NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_T01_PB(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_OBJECT1, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE0 <> TARGET_OBJECT_TYPE0) AND
                            (TARGET_OBJECT0 IS NOT NULL) AND
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T0_PB(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :TARGET_OBJECT0, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END

                        IF(NOT EXISTS(
                            SELECT 1
                            FROM ENTRIES
                            WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
                        ))THEN
                        BEGIN
                            EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                        END
                    END
                    ELSE
                    IF(TRANSFER_TYPE = 2 OR TRANSFER_TYPE = 3)THEN
                    BEGIN
                        IF((SOURCE_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL))THEN
                        BEGIN
                            IF(TRANSFER_TYPE = 3)THEN 
                            BEGIN
                                BEGINNING_YEAR = EXTRACT(YEAR FROM ENDING_DATE) || '.1.1';
                                EXECUTE PROCEDURE CMD_CRITERIA_ACCOUNT_OBJECTS(:P_LANGUAGE, :P_COMPANY, :TARGET_ID, :BEGINNING_YEAR, :ENDING_DATE);
                            END
                            ELSE
                            BEGIN
                                
                                EXECUTE PROCEDURE CMD_CRITERIA_ACCOUNT_OBJECTS(:P_LANGUAGE, :P_COMPANY, :TARGET_ID, :BEGINNING_DATE, :ENDING_DATE);
                            END
    
                            SELECT COUNT(OBJECT)
                            FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
                            INTO :ROW_NUMBER_OBJECT;
    
                            IF(ROW_NUMBER_OBJECT > 0)THEN
                            BEGIN
                                SELECT CONTENT
                                FROM TEXTS
                                WHERE ID = 5 AND LANGUAGE = :P_LANGUAGE
                                INTO :TEXT_FROM_ACCOUNT;
    
                                SELECT CONTENT
                                FROM TEXTS
                                WHERE ID = 6 AND LANGUAGE = :P_LANGUAGE
                                INTO :TEXT_TO_ACCOUNT;
    
                                SELECT CODE
                                FROM ATOMS
                                WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :SOURCE_ACCOUNT
                                INTO :SOURCE_ACCOUNT_CODE;
    
                                SELECT CODE
                                FROM ATOMS
                                WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :TARGET_ACCOUNT
                                INTO :TARGET_ACCOUNT_CODE;
    
                                SELECT CODE, NUMBER
                                FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :PERCENT_DOCUMENT_TEAM, :ENDING_DATE)
                                INTO :CODE, :NUMBER;
    
                                DOCUMENT = GEN_ID(UNIVERSE, 1);
                                EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL,  0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :MAIN_CURRENCY, 1, :ENDING_DATE, NULL, NULL, :P_PERIOD, :PERCENT_DOCUMENT_TEAM, :ENDING_DATE, NULL, NULL, NULL, :DOCUMENT_CONTENT, 0, 0);
    
                                HAS_ENTRY = 0;
    
                                FOR
                                    SELECT OBJECT0, OBJECT1, DEBIT, CREDIT
                                    FROM INT_SD_1_TK_DT0_DT1_CN_G(:P_COMPANY, :SOURCE_ACCOUNT, :ENDING_DATE)
                                    INTO :SOURCE_OBJECT0, :SOURCE_OBJECT1, :SOURCE_DEBIT, :SOURCE_CREDIT
                                DO
                                BEGIN
                                    IF(SOURCE_OBJECT0 IS NOT NULL)THEN
                                        SELECT CODE
                                        FROM ATOMS
                                        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :SOURCE_OBJECT0
                                        INTO :SOURCE_OBJECT0_CODE;
                                    IF(SOURCE_OBJECT1 IS NOT NULL)THEN
                                        SELECT CODE
                                        FROM ATOMS
                                        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :SOURCE_OBJECT1
                                        INTO :SOURCE_OBJECT1_CODE;
    
                                    TOTAL_OF_OBJECT = ROUND((SOURCE_DEBIT - SOURCE_CREDIT)*PERCENT, 0);
                                    REMAINING_OF_OBJECT = TOTAL_OF_OBJECT;
    
                                    CURRENT_ROW_OBJECT = 1;
    
                                    FOR
                                        SELECT OBJECT, PERCENT
                                        FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
                                        INTO :TARGET_OBJECT0, :OBJECT_PERCENT
                                    DO
                                    BEGIN
                                        IF(TARGET_OBJECT0 IS NOT NULL)THEN
                                            SELECT CODE
                                            FROM ATOMS
                                            WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :TARGET_OBJECT0
                                            INTO :TARGET_OBJECT0_CODE;
    
                                        IF(CURRENT_ROW_OBJECT = ROW_NUMBER_OBJECT)THEN
                                        BEGIN
                                            SUM_OF_MONEY = REMAINING_OF_OBJECT;
                                        END
                                        ELSE
                                        BEGIN
                                            CURRENT_ROW_OBJECT = CURRENT_ROW_OBJECT + 1;
    
                                            SUM_OF_MONEY = ROUND(OBJECT_PERCENT*TOTAL_OF_OBJECT, 0);
    
                                            REMAINING_OF_OBJECT = REMAINING_OF_OBJECT - SUM_OF_MONEY;
                                        END
    
                                        ENTRY_CONTENT = TEXT_FROM_ACCOUNT || ' ' || SOURCE_ACCOUNT_CODE;
                                        IF(SOURCE_OBJECT1_CODE IS NULL)THEN
                                        BEGIN
                                            IF(SOURCE_OBJECT0_CODE IS NOT NULL)THEN
                                                ENTRY_CONTENT =  ENTRY_CONTENT || '(' || SOURCE_OBJECT0_CODE || ')';
                                        END
                                        ELSE
                                            ENTRY_CONTENT =  ENTRY_CONTENT || '(' || SOURCE_OBJECT0_CODE || ', ' || SOURCE_OBJECT1_CODE || ')';
                                        ENTRY_CONTENT = ENTRY_CONTENT || ' ' ||TEXT_TO_ACCOUNT || ' ' || TARGET_ACCOUNT_CODE || '(' || TARGET_OBJECT0_CODE || ')';
    
                                        IF(SUM_OF_MONEY > 0)THEN
                                        BEGIN
                                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :MAIN_CURRENCY, :DOCUMENT, 1, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :TARGET_ACCOUNT, :TARGET_OBJECT0, NULL, NULL, GEN_ID(UNIVERSE, 1), :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, NULL, 0, 0, :SUM_OF_MONEY, :SUM_OF_MONEY);
                                            HAS_ENTRY = 1;
                                        END
                                        ELSE IF(SUM_OF_MONEY < 0)THEN
                                        BEGIN
                                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :MAIN_CURRENCY, :DOCUMENT, 1, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, NULL, GEN_ID(UNIVERSE, 1), :TARGET_ACCOUNT, :TARGET_OBJECT0, NULL, NULL, 0, 0, ABS(:SUM_OF_MONEY), ABS(:SUM_OF_MONEY));
                                            HAS_ENTRY = 1;
                                        END
                                    END
                               END
    
                               IF(HAS_ENTRY = 0)THEN EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                            END
                        END
                        ELSE IF(target_object_type1 IS NOT NULL)THEN
                        BEGIN
                            SELECT CONTENT
                            FROM TEXTS
                            WHERE ID = 5 AND LANGUAGE = :P_LANGUAGE
                            INTO :TEXT_FROM_ACCOUNT;
    
                            SELECT CONTENT
                            FROM TEXTS
                            WHERE ID = 6 AND LANGUAGE = :P_LANGUAGE
                            INTO :TEXT_TO_ACCOUNT;

                            SELECT CODE
                            FROM ATOMS
                            WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :SOURCE_ACCOUNT
                            INTO :SOURCE_ACCOUNT_CODE;

                            SELECT CODE
                            FROM ATOMS
                            WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :TARGET_ACCOUNT
                            INTO :TARGET_ACCOUNT_CODE;

                            SELECT CODE, NUMBER
                            FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :PERCENT_DOCUMENT_TEAM, :ENDING_DATE)
                            INTO :CODE, :NUMBER;

                            DOCUMENT = GEN_ID(UNIVERSE, 1);
                            EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL,  0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :MAIN_CURRENCY, 1, :ENDING_DATE, NULL, NULL, :P_PERIOD, :PERCENT_DOCUMENT_TEAM, :ENDING_DATE, NULL, NULL, NULL, :DOCUMENT_CONTENT, 0, 0);

                            HAS_ENTRY = 0;
    
                            
                            FOR
                                SELECT OBJECT0, OBJECT1, DEBIT, CREDIT
                                FROM INT_SD_1_TK_DT0_DT1_CN_G(:P_COMPANY, :SOURCE_ACCOUNT, :ENDING_DATE)
                                INTO :SOURCE_OBJECT0, :SOURCE_OBJECT1, :SOURCE_DEBIT, :SOURCE_CREDIT
                            DO
                            BEGIN
                                
                                IF(TRANSFER_TYPE = 3)THEN 
                                BEGIN
                                    BEGINNING_YEAR = EXTRACT(YEAR FROM ENDING_DATE) || '.1.1';
                                    EXECUTE PROCEDURE CMD_CRITERIA_ACCOUNT_OBJECTS_2(:P_LANGUAGE, :P_COMPANY, :TARGET_ID, :source_object0, :BEGINNING_YEAR, :ENDING_DATE);
                                END
                                ELSE
                                BEGIN
                                    EXECUTE PROCEDURE CMD_CRITERIA_ACCOUNT_OBJECTS_2(:P_LANGUAGE, :P_COMPANY, :TARGET_ID, :source_object0, :BEGINNING_DATE, :ENDING_DATE);
                                END

                                SELECT COUNT(OBJECT)
                                FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
                                INTO :ROW_NUMBER_OBJECT;

                                IF(ROW_NUMBER_OBJECT > 0)THEN
                                BEGIN
                                    IF(SOURCE_OBJECT0 IS NOT NULL)THEN
                                        SELECT CODE
                                        FROM ATOMS
                                        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :SOURCE_OBJECT0
                                        INTO :SOURCE_OBJECT0_CODE;
                                    IF(SOURCE_OBJECT1 IS NOT NULL)THEN
                                        SELECT CODE
                                        FROM ATOMS
                                        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :SOURCE_OBJECT1
                                        INTO :SOURCE_OBJECT1_CODE;

                                    TOTAL_OF_OBJECT = ROUND((SOURCE_DEBIT - SOURCE_CREDIT)*PERCENT, 0);
                                    REMAINING_OF_OBJECT = TOTAL_OF_OBJECT;
    
                                    CURRENT_ROW_OBJECT = 1;
    
                                    FOR
                                        SELECT OBJECT, PERCENT
                                        FROM TEMP_CRITERIA_ACCOUNT_OBJECTS
                                        INTO :TARGET_OBJECT1, :OBJECT_PERCENT
                                    DO
                                    BEGIN
                                        IF(TARGET_OBJECT1 IS NOT NULL)THEN
                                            SELECT CODE
                                            FROM ATOMS
                                            WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :TARGET_OBJECT1
                                            INTO :TARGET_OBJECT1_CODE;
    
                                        IF(CURRENT_ROW_OBJECT = ROW_NUMBER_OBJECT)THEN
                                        BEGIN
                                            SUM_OF_MONEY = REMAINING_OF_OBJECT;
                                        END
                                        ELSE
                                        BEGIN
                                            CURRENT_ROW_OBJECT = CURRENT_ROW_OBJECT + 1;
    
                                            SUM_OF_MONEY = ROUND(OBJECT_PERCENT*TOTAL_OF_OBJECT, 0);
    
                                            REMAINING_OF_OBJECT = REMAINING_OF_OBJECT - SUM_OF_MONEY;
                                        END
    
                                        ENTRY_CONTENT = TEXT_FROM_ACCOUNT || ' ' || SOURCE_ACCOUNT_CODE;
                                        IF(SOURCE_OBJECT1_CODE IS NULL)THEN
                                        BEGIN
                                            IF(SOURCE_OBJECT0_CODE IS NOT NULL)THEN
                                                ENTRY_CONTENT =  ENTRY_CONTENT || '(' || SOURCE_OBJECT0_CODE || ')';
                                        END
                                        ELSE
                                            ENTRY_CONTENT =  ENTRY_CONTENT || '(' || SOURCE_OBJECT0_CODE || ', ' || SOURCE_OBJECT1_CODE || ')';
                                        ENTRY_CONTENT = ENTRY_CONTENT || ' ' ||TEXT_TO_ACCOUNT || ' ' || TARGET_ACCOUNT_CODE || '(' || SOURCE_OBJECT0_CODE || ',' || TARGET_OBJECT1_CODE || ')';
    
                                        IF(SUM_OF_MONEY > 0)THEN
                                        BEGIN
                                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :MAIN_CURRENCY, :DOCUMENT, 1, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :TARGET_ACCOUNT, :source_object0, :target_object1, NULL, GEN_ID(UNIVERSE, 1), :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, NULL, 0, 0, :SUM_OF_MONEY, :SUM_OF_MONEY);
                                            HAS_ENTRY = 1;
                                        END
                                        ELSE IF(SUM_OF_MONEY < 0)THEN
                                        BEGIN
                                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :MAIN_CURRENCY, :DOCUMENT, 1, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, NULL, GEN_ID(UNIVERSE, 1), :TARGET_ACCOUNT, source_object0, :target_object1, NULL, 0, 0, ABS(:SUM_OF_MONEY), ABS(:SUM_OF_MONEY));
                                            HAS_ENTRY = 1;
                                        END
                                    END
                                END
                            END

                            IF(HAS_ENTRY = 0)THEN EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                        END
                    END
                    IF(TRANSFER_TYPE = 4 AND P_PRODUCT_PRICE = 1)THEN 
                    BEGIN
                        EXECUTE PROCEDURE CMD_PRODUCT_PRICE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, :SOURCE_ACCOUNT, :TARGET_ACCOUNT, :PERCENT, :P_DOCUMENT_TEAMS, IIF(:P_CAL_OUTPUT_PRICE=1, :OUTPUT_PRICE_METHOD, 0));
                        
                        EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :P_VAT_DEDUCTION, :P_TRANSFER_ACCOUNTS, :P_CAL_OUTPUT_PRICE, :P_PRODUCT_PRICE, :P_DOCUMENT_TEAMS, 1);
                    END
                END
            END
        END
        ELSE IF(SOURCE_OBJECT1 IS NULL)THEN 
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :ENDING_DATE)
            INTO :SOURCE_DEBIT, :SOURCE_CREDIT;

            SELECT COUNT(ID)
            FROM TARGET_ACCOUNTS
            WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNT = :SOURCE_ID AND TARGET_ACCOUNTS.TRANSFER_TYPE > 0
            INTO :ROW_NUMBER;

            IF((SOURCE_DEBIT <> 0 OR SOURCE_CREDIT <> 0) AND ROW_NUMBER > 0)THEN
            BEGIN
                CURRENT_ROW = 0;
                TRANSFERED_DEBIT = 0;
                TRANSFERED_CREDIT = 0;

                
                SUM_PREV_PERCENT = 0;

                FOR
                    SELECT ACCOUNT, TRANSFER_TYPE, IIF(TARGET_ACCOUNTS.TARGET_PERCENT IS NULL, TARGET_ACCOUNTS.PERCENT, TARGET_PERCENTS.PERCENT),
                            ATOM_TYPE_0, ATOM_TYPE_1,
                            OBJECT0, OBJECT1
                    FROM TARGET_ACCOUNTS
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNTS.ACCOUNT
                    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TARGET_ACCOUNTS.ID
                    LEFT JOIN TARGET_PERCENTS ON TARGET_PERCENTS.COMPANY = :P_COMPANY AND TARGET_PERCENTS.ID = TARGET_ACCOUNTS.TARGET_PERCENT
                    WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNT = :SOURCE_ID AND TARGET_ACCOUNTS.TRANSFER_TYPE > 0
                    ORDER BY ORDINAL
                    INTO :TARGET_ACCOUNT, :TRANSFER_TYPE, :PERCENT,
                    :TARGET_OBJECT_TYPE0, :TARGET_OBJECT_TYPE1,
                    :TARGET_OBJECT0, :TARGET_OBJECT1
                DO
                BEGIN
                    IF(TRANSFER_TYPE = 4 AND P_PRODUCT_PRICE = 1)THEN 
                    BEGIN
                        EXECUTE PROCEDURE cmd_product_price_object0(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, :SOURCE_ACCOUNT, :source_object0, :TARGET_ACCOUNT, :PERCENT, :P_DOCUMENT_TEAMS, IIF(:P_CAL_OUTPUT_PRICE=1, :OUTPUT_PRICE_METHOD, 0));
                    END
                    ELSE
                    BEGIN
                        SELECT CODE, NUMBER
                        FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :ENDING_DATE)
                        INTO :CODE, :NUMBER;

                        DOCUMENT = GEN_ID(UNIVERSE, 1);
                        EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL,  0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :MAIN_CURRENCY, 1, :ENDING_DATE, NULL, NULL, :P_PERIOD, :DOCUMENT_TEAM, :ENDING_DATE, NULL, NULL, NULL, :DOCUMENT_CONTENT, 0, 0);

                        CURRENT_ROW = CURRENT_ROW + 1;

                        TARGET_DEBIT = ROUND(SOURCE_DEBIT * PERCENT, 0);
                        TARGET_CREDIT = ROUND(SOURCE_CREDIT * PERCENT, 0);

                        TRANSFERED_DEBIT = TRANSFERED_DEBIT + TARGET_DEBIT;
                        TRANSFERED_CREDIT = TRANSFERED_CREDIT + TARGET_CREDIT;

                        IF(CURRENT_ROW = ROW_NUMBER AND TRANSFER_ALL = 1)THEN
                        BEGIN
                            IF(TRANSFERED_DEBIT < SOURCE_DEBIT)THEN
                                TARGET_DEBIT = TARGET_DEBIT + SOURCE_DEBIT - TRANSFERED_DEBIT;

                            IF(TRANSFERED_CREDIT < SOURCE_CREDIT)THEN
                                TARGET_CREDIT = TARGET_CREDIT + SOURCE_CREDIT - TRANSFERED_CREDIT;
                        END

                        IF( 
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_OBJECT0(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF( 
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT0 IS NOT NULL) AND (TARGET_OBJECT1 IS NOT NULL)
                        )THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T01_PB(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_OBJECT1, TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF( 
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT0 IS NOT NULL) AND (TARGET_OBJECT1 IS NOT NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T01(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_OBJECT1, :PERCENT, :SUM_PREV_PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT0 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T01(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_OBJECT1, :PERCENT, :SUM_PREV_PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T01(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_OBJECT1, :PERCENT, :SUM_PREV_PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE1 IS NOT NULL) AND (TARGET_OBJECT0 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NOT NULL) AND (SOURCE_OBJECT_TYPE1 = TARGET_OBJECT_TYPE1)
                        )THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T0_ST1(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :TARGET_OBJECT0, :PERCENT, :SUM_PREV_PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END
                        ELSE IF(
                            (SOURCE_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT_TYPE0 IS NOT NULL) AND (TARGET_OBJECT_TYPE1 IS NULL) AND (TARGET_OBJECT0 IS NOT NULL)
                        )THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_ST0_OBJECT0(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :TARGET_ACCOUNT, :TARGET_OBJECT0, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END

                        
                        SUM_PREV_PERCENT = SUM_PREV_PERCENT + PERCENT;

                        IF(NOT EXISTS(
                                SELECT 1
                                FROM ENTRIES
                                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
                            ))THEN
                        BEGIN
                            EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                        END
                    END
                END
            END
        END
        ELSE 
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_1_DT1_CN(:P_COMPANY, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, :ENDING_DATE)
            INTO :SOURCE_DEBIT, :SOURCE_CREDIT;

            SELECT COUNT(ID)
            FROM TARGET_ACCOUNTS
            WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNT = :SOURCE_ID AND TARGET_ACCOUNTS.TRANSFER_TYPE > 0
            INTO :ROW_NUMBER;

            IF((SOURCE_DEBIT <> 0 OR SOURCE_CREDIT <> 0) AND ROW_NUMBER > 0)THEN
            BEGIN
                CURRENT_ROW = 0;
                TRANSFERED_DEBIT = 0;
                TRANSFERED_CREDIT = 0;

                SUM_PREV_PERCENT = 0;

                FOR
                    SELECT ACCOUNT, TRANSFER_TYPE, IIF(TARGET_ACCOUNTS.TARGET_PERCENT IS NULL, TARGET_ACCOUNTS.PERCENT, TARGET_PERCENTS.PERCENT),
                            ATOM_TYPE_0, ATOM_TYPE_1,
                            OBJECT0, OBJECT1
                    FROM TARGET_ACCOUNTS
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNTS.ACCOUNT
                    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TARGET_ACCOUNTS.ID
                    LEFT JOIN TARGET_PERCENTS ON TARGET_PERCENTS.COMPANY = :P_COMPANY AND TARGET_PERCENTS.ID = TARGET_ACCOUNTS.TARGET_PERCENT
                    WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNT = :SOURCE_ID AND TARGET_ACCOUNTS.TRANSFER_TYPE > 0
                    ORDER BY ORDINAL
                    INTO :TARGET_ACCOUNT, :TRANSFER_TYPE, :PERCENT,
                    :TARGET_OBJECT_TYPE0, :TARGET_OBJECT_TYPE1,
                    :TARGET_OBJECT0, :TARGET_OBJECT1
                DO
                BEGIN
                    IF(TRANSFER_TYPE = 4)THEN 
                    BEGIN
                    END
                    ELSE
                    BEGIN
                        SELECT CODE, NUMBER
                        FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :ENDING_DATE)
                        INTO :CODE, :NUMBER;

                        DOCUMENT = GEN_ID(UNIVERSE, 1);
                        EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL,  0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :MAIN_CURRENCY, 1, :ENDING_DATE, NULL, NULL, :P_PERIOD, :DOCUMENT_TEAM, :ENDING_DATE, NULL, NULL, NULL, :DOCUMENT_CONTENT, 0, 0);

                        CURRENT_ROW = CURRENT_ROW + 1;

                        TARGET_DEBIT = ROUND(SOURCE_DEBIT * PERCENT, 0);
                        TARGET_CREDIT = ROUND(SOURCE_CREDIT * PERCENT, 0);

                        TRANSFERED_DEBIT = TRANSFERED_DEBIT + TARGET_DEBIT;
                        TRANSFERED_CREDIT = TRANSFERED_CREDIT + TARGET_CREDIT;

                        IF(CURRENT_ROW = ROW_NUMBER AND TRANSFER_ALL = 1)THEN
                        BEGIN
                            IF(TRANSFERED_DEBIT < SOURCE_DEBIT)THEN
                                TARGET_DEBIT = TARGET_DEBIT + SOURCE_DEBIT - TRANSFERED_DEBIT;

                            IF(TRANSFERED_CREDIT < SOURCE_CREDIT)THEN
                                TARGET_CREDIT = TARGET_CREDIT + SOURCE_CREDIT - TRANSFERED_CREDIT;
                        END

                        IF( 
                            (TARGET_OBJECT_TYPE0 IS NULL) AND (TARGET_OBJECT_TYPE1 IS NULL)
                        )
                        THEN
                        BEGIN
                            EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY_S_S0_S1_T(:P_LANGUAGE, :P_COMPANY, :ENDING_DATE, :DOCUMENT, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, :TARGET_ACCOUNT, :PERCENT, :TARGET_DEBIT, :TARGET_CREDIT, :MAIN_CURRENCY, 1);
                        END

                        SUM_PREV_PERCENT = SUM_PREV_PERCENT + PERCENT;

                        IF(NOT EXISTS(
                                SELECT 1
                                FROM ENTRIES
                                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
                            ))THEN
                        BEGIN
                            EXECUTE PROCEDURE DOCUMENT_BASE_D(:P_LANGUAGE, :P_COMPANY, :DOCUMENT);
                        END
                    END
                END
            END
        END
    END
    END
END ^

ALTER PROCEDURE CMD_MADE_AUTO_ENTRY_NORMAL (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_SOURCE_ACCOUNT DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_DEBIT DM_DOUBLE,
P_CREDIT DM_DOUBLE,
P_CURRENCY DM_DOUBLE,
P_EXCHANGE_RATE DM_DOUBLE)
AS 
DECLARE VARIABLE SOURCE_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE TARGET_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ENTRY_CONTENT DM_CONTENT;
DECLARE VARIABLE TEXT_FROM_ACCOUNT DM_TEXT_CONTENT;
DECLARE VARIABLE TEXT_TO_ACCOUNT DM_TEXT_CONTENT;
BEGIN
    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 5 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_FROM_ACCOUNT;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 6 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_TO_ACCOUNT;

    SELECT CODE
    FROM ATOMS
    WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :P_SOURCE_ACCOUNT
    INTO :SOURCE_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :P_TARGET_ACCOUNT
    INTO :TARGET_ACCOUNT_CODE;

    ENTRY_CONTENT = TEXT_FROM_ACCOUNT || ' ' || SOURCE_ACCOUNT_CODE || ' ' ||  TEXT_TO_ACCOUNT || ' ' || TARGET_ACCOUNT_CODE;

    IF(P_DEBIT <> 0 OR P_CREDIT <> 0)THEN
    BEGIN
        IF(P_DEBIT > P_CREDIT)THEN
            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_TARGET_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :P_SOURCE_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, :P_DEBIT);
        ELSE
            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_SOURCE_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :P_TARGET_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, :P_CREDIT);
    END
END ^

ALTER PROCEDURE CMD_MADE_AUTO_ENTRY_S0 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_SOURCE_ACCOUNT DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_PERCENT DM_DOUBLE,
P_DEBIT DM_DOUBLE,
P_CREDIT DM_DOUBLE,
P_CURRENCY DM_DOUBLE,
P_EXCHANGE_RATE DM_DOUBLE)
AS 
DECLARE VARIABLE SOURCE_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE TARGET_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ENTRY_CONTENT DM_CONTENT;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT0_CODE DM_CODE;
DECLARE VARIABLE OBJECT_DEBIT DM_DOUBLE;
DECLARE VARIABLE OBJECT_CREDIT DM_DOUBLE;
DECLARE VARIABLE TEXT_FROM_ACCOUNT DM_TEXT_CONTENT;
DECLARE VARIABLE TEXT_TO_ACCOUNT DM_TEXT_CONTENT;
BEGIN
    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 5 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_FROM_ACCOUNT;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 6 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_TO_ACCOUNT;

    SELECT CODE
    FROM ATOMS
    WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :P_SOURCE_ACCOUNT
    INTO :SOURCE_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :P_TARGET_ACCOUNT
    INTO :TARGET_ACCOUNT_CODE;

    FOR
        SELECT OBJECT0, DEBIT, CREDIT
        FROM INT_SD_1_TK_DT0_CN(:P_COMPANY, :P_SOURCE_ACCOUNT, :P_DATE)
        INTO :OBJECT0, :OBJECT_DEBIT, :OBJECT_CREDIT
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
        INTO :OBJECT0_CODE;

        ENTRY_CONTENT = TEXT_FROM_ACCOUNT || ' ' || SOURCE_ACCOUNT_CODE || '(' || OBJECT0_CODE || ')' || ' ' || TEXT_TO_ACCOUNT || ' ' || TARGET_ACCOUNT_CODE;

        OBJECT_DEBIT = ROUND(OBJECT_DEBIT * P_PERCENT, 0);
        OBJECT_CREDIT = ROUND(OBJECT_CREDIT * P_PERCENT, 0);

        IF(OBJECT_DEBIT <> 0 OR OBJECT_CREDIT <> 0)THEN
        BEGIN
            IF(OBJECT_DEBIT > OBJECT_CREDIT)THEN
                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_TARGET_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :P_SOURCE_ACCOUNT, OBJECT0, NULL, NULL, 0, 0, 0, :OBJECT_DEBIT);
            ELSE
                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_SOURCE_ACCOUNT, OBJECT0, NULL, NULL, GEN_ID(UNIVERSE, 1), :P_TARGET_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, :OBJECT_CREDIT);
        END
    END
END ^

ALTER PROCEDURE CMD_MADE_AUTO_ENTRY_S01 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_SOURCE_ACCOUNT DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_PERCENT DM_DOUBLE,
P_DEBIT DM_DOUBLE,
P_CREDIT DM_DOUBLE,
P_CURRENCY DM_DOUBLE,
P_EXCHANGE_RATE DM_DOUBLE)
AS 
DECLARE VARIABLE SOURCE_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE TARGET_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ENTRY_CONTENT DM_CONTENT;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT0_CODE DM_CODE;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT1_CODE DM_CODE;
DECLARE VARIABLE OBJECT_DEBIT DM_DOUBLE;
DECLARE VARIABLE OBJECT_CREDIT DM_DOUBLE;
DECLARE VARIABLE TEXT_FROM_ACCOUNT DM_TEXT_CONTENT;
DECLARE VARIABLE TEXT_TO_ACCOUNT DM_TEXT_CONTENT;
BEGIN
    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 5 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_FROM_ACCOUNT;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = 6 AND LANGUAGE = :P_LANGUAGE
    INTO :TEXT_TO_ACCOUNT;

    SELECT CODE
    FROM ATOMS
    WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :P_SOURCE_ACCOUNT
    INTO :SOURCE_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :P_TARGET_ACCOUNT
    INTO :TARGET_ACCOUNT_CODE;

    FOR
        SELECT OBJECT0, OBJECT1, DEBIT, CREDIT
        FROM INT_SD_1_TK_DT0_DT1_CN(:P_COMPANY, :P_SOURCE_ACCOUNT, :P_DATE)
        INTO :OBJECT0, :OBJECT1, :OBJECT_DEBIT, :OBJECT_CREDIT
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
        INTO :OBJECT0_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
        INTO :OBJECT1_CODE;

        ENTRY_CONTENT = TEXT_FROM_ACCOUNT || ' ' || SOURCE_ACCOUNT_CODE || '(' || OBJECT0_CODE || ', ' || OBJECT1_CODE || ')' || ' ' || TEXT_TO_ACCOUNT || ' ' || TARGET_ACCOUNT_CODE;

        OBJECT_DEBIT = ROUND(OBJECT_DEBIT * P_PERCENT, 0);
        OBJECT_CREDIT = ROUND(OBJECT_CREDIT * P_PERCENT, 0);

        IF(OBJECT_DEBIT <> 0 OR OBJECT_CREDIT <> 0)THEN
        BEGIN
            IF(OBJECT_DEBIT > OBJECT_CREDIT)THEN
                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_TARGET_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :P_SOURCE_ACCOUNT, OBJECT0, OBJECT1, NULL, 0, 0, 0, :OBJECT_DEBIT);
            ELSE
                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_CURRENCY, :P_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_SOURCE_ACCOUNT, OBJECT0, OBJECT1, NULL, GEN_ID(UNIVERSE, 1), :P_TARGET_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, :OBJECT_CREDIT);
        END
    END
END ^

ALTER PROCEDURE CMD_MADE_AUTO_ENTRY_S01_T0 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE DM_DATE,
P_DOCUMENT DM_ID,
P_SOURCE_ACCOUNT DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_PERCENT DM_DOUBLE,
