ALTER PROCEDURE CMD_MADE_AUTO_ENTRY_S0_T01 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE DM_DATE,
P_DOCUMENT DM_ID,
