ALTER PROCEDURE CMD_MADE_DOCUMENT_CODE (P_COMPANY DM_ID,
P_TEAM DM_ID,
P_INPUT_DATE DM_DATE)
RETURNS (CODE DM_CODE,
NUMBER DM_CODE)
AS 
BEGIN
    SELECT DEFAULT_CODE
    FROM DOCUMENT_TEAMS
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = :P_TEAM
    INTO :CODE;

    SELECT CMD_MADE_DOCUMENT_NUMBER.NUMBER
    FROM CMD_MADE_DOCUMENT_NUMBER(:P_COMPANY, :CODE, :P_INPUT_DATE)
    INTO :NUMBER;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_MADE_DOCUMENT_NUMBER (P_COMPANY DM_ID,
P_CODE DM_CODE,
P_INPUT_DATE DM_DATE)
RETURNS (NUMBER DM_CODE)
AS 
DECLARE VARIABLE MAX_NUMBER DM_BIGINT;
DECLARE VARIABLE DOCUMENT_CODE_CYCLE DM_TIME_TYPE;
DECLARE VARIABLE TIME_1 DM_INTEGER;
DECLARE VARIABLE TIME_2 DM_INTEGER;
BEGIN
    SELECT FIRST 1 DOCUMENT_CODE_CYCLE
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :DOCUMENT_CODE_CYCLE;

    SELECT TIME_1, TIME_2
    FROM INT_DATE_TIME_TYPE_TO_TIMES(:DOCUMENT_CODE_CYCLE, :P_INPUT_DATE)
    INTO :TIME_1,  :TIME_2;

    SELECT CURRENT_NUMBER
    FROM DOCUMENT_TEAM_NUMBER
    WHERE DOCUMENT_TEAM_NUMBER.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_NUMBER.CODE = :P_CODE AND
    DOCUMENT_TEAM_NUMBER.DOCUMENT_CODE_CYCLE = :DOCUMENT_CODE_CYCLE AND DOCUMENT_TEAM_NUMBER.TIME_1 = :TIME_1 AND DOCUMENT_TEAM_NUMBER.TIME_2 = :TIME_2
    WITH LOCK
    INTO :MAX_NUMBER;

    IF(MAX_NUMBER IS NULL)THEN
    BEGIN
        INSERT INTO DOCUMENT_TEAM_NUMBER(COMPANY, CODE, DOCUMENT_CODE_CYCLE, TIME_1, TIME_2, CURRENT_NUMBER)
        VALUES(:P_COMPANY, :P_CODE, :DOCUMENT_CODE_CYCLE, :TIME_1, :TIME_2, 0);

        EXECUTE PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX(:P_COMPANY, :P_CODE, :P_INPUT_DATE);

        SELECT CURRENT_NUMBER
        FROM DOCUMENT_TEAM_NUMBER
        WHERE DOCUMENT_TEAM_NUMBER.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_NUMBER.CODE = :P_CODE AND
        DOCUMENT_TEAM_NUMBER.DOCUMENT_CODE_CYCLE = :DOCUMENT_CODE_CYCLE AND DOCUMENT_TEAM_NUMBER.TIME_1 = :TIME_1 AND DOCUMENT_TEAM_NUMBER.TIME_2 = :TIME_2
        WITH LOCK
        INTO :MAX_NUMBER;
    END

    MAX_NUMBER = MAX_NUMBER + 1;

    UPDATE DOCUMENT_TEAM_NUMBER
    SET CURRENT_NUMBER = :MAX_NUMBER
    WHERE DOCUMENT_TEAM_NUMBER.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_NUMBER.CODE = :P_CODE AND
    DOCUMENT_TEAM_NUMBER.DOCUMENT_CODE_CYCLE = :DOCUMENT_CODE_CYCLE AND DOCUMENT_TEAM_NUMBER.TIME_1 = :TIME_1 AND DOCUMENT_TEAM_NUMBER.TIME_2 = :TIME_2;

    IF(MAX_NUMBER < 10)THEN
        NUMBER = '0000' || MAX_NUMBER;
    ELSE IF(MAX_NUMBER < 100)THEN
        NUMBER = '000' || MAX_NUMBER;
    ELSE IF(MAX_NUMBER < 1000)THEN
        NUMBER = '00' || MAX_NUMBER;
    ELSE IF(MAX_NUMBER < 10000)THEN
        NUMBER = '0' || MAX_NUMBER;
    ELSE NUMBER = MAX_NUMBER;

    SUSPEND;
END ^

ALTER PROCEDURE CMD_MERGE_ACCOUNT (P_COMPANY DM_ID,
P_FROM_ACCOUNT_ID DM_ID,
P_TO_ACCOUNT_ID DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE TO_ID DM_ID;
BEGIN
    FOR
        SELECT ID, PERIOD, CURRENCY, OBJECT0, OBJECT1, OBJECT2,
        AMOUNT, OFFICIAL_DEBIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, FOREIGN_CREDIT
        FROM BALANCES
        WHERE BALANCES.COMPANY = :P_COMPANY AND BALANCES.ACCOUNT = :P_FROM_ACCOUNT_ID
        INTO :ID, :PERIOD, :CURRENCY, OBJECT0, :OBJECT1, :OBJECT2,
        :AMOUNT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT, :FOREIGN_DEBIT, :FOREIGN_CREDIT
    DO
    BEGIN
        TO_ID = NULL;

        SELECT ID
        FROM BALANCES
        WHERE BALANCES.COMPANY = :P_COMPANY AND BALANCES.ACCOUNT = :P_TO_ACCOUNT_ID AND
        PERIOD = :PERIOD AND CURRENCY = :CURRENCY AND
        ((OBJECT0 IS NULL AND :OBJECT0 IS NULL) OR (OBJECT0 = :OBJECT0)) AND
        ((OBJECT1 IS NULL AND :OBJECT1 IS NULL) OR (OBJECT1 = :OBJECT1)) AND
        ((OBJECT2 IS NULL AND :OBJECT2 IS NULL) OR (OBJECT2 = :OBJECT2))
        INTO :TO_ID;

        IF(TO_ID IS NULL)THEN
        BEGIN
            UPDATE BALANCES
            SET BALANCES.ACCOUNT = :P_TO_ACCOUNT_ID
            WHERE BALANCES.COMPANY = :P_COMPANY AND BALANCES.ID = :ID;
        END
        ELSE
        BEGIN
            UPDATE BALANCES
            SET BALANCES.AMOUNT = BALANCES.AMOUNT + :AMOUNT,
                BALANCES.OFFICIAL_DEBIT = BALANCES.OFFICIAL_DEBIT + :OFFICIAL_DEBIT,
                BALANCES.OFFICIAL_CREDIT = BALANCES.OFFICIAL_CREDIT + :OFFICIAL_CREDIT,
                BALANCES.FOREIGN_DEBIT = BALANCES.FOREIGN_DEBIT + :FOREIGN_DEBIT,
                BALANCES.FOREIGN_CREDIT = BALANCES.FOREIGN_CREDIT + :FOREIGN_CREDIT
            WHERE BALANCES.COMPANY = :P_COMPANY AND BALANCES.ID = :TO_ID;

            DELETE FROM BALANCES
            WHERE BALANCES.COMPANY = :P_COMPANY AND BALANCES.ID = :ID;
        END
    END

    UPDATE CREDIT_DEBIT
    SET CREDIT_DEBIT.ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE ASSETS
    SET ASSETS.DEPRECIATION_ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.DEPRECIATION_ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE ASSETS
    SET ASSETS.EXPENSE_ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.EXPENSE_ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE ASSETS
    SET ASSETS.ASSET_ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.ASSET_ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE PREPAID_EXPENSES
    SET PREPAID_EXPENSES.ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE PREPAID_EXPENSES
    SET PREPAID_EXPENSES.ACCOUNT_EXPENSE = :P_TO_ACCOUNT_ID
    WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ACCOUNT_EXPENSE = :P_FROM_ACCOUNT_ID;

    UPDATE DOCUMENT_TEAMS
    SET DOCUMENT_TEAMS.DEBIT_DEFAULT_ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.DEBIT_DEFAULT_ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE DOCUMENT_TEAMS
    SET DOCUMENT_TEAMS.CREDIT_DEFAULT_ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.CREDIT_DEFAULT_ACCOUNT = :P_FROM_ACCOUNT_ID;

    UPDATE DOCUMENT_TEAMS
    SET DOCUMENT_TEAMS.SINGLE_DEFAULT_ACCOUNT = :P_TO_ACCOUNT_ID
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.SINGLE_DEFAULT_ACCOUNT = :P_FROM_ACCOUNT_ID;
END ^

ALTER PROCEDURE CMD_MERGE_ACCOUNT_CHILDREN (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE CHILD_ACCOUNT_ID DM_ID;
BEGIN
    FOR
        SELECT ACCOUNTS.ID
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.PARENT = :P_ID
        WHERE ACCOUNTS.COMPANY = :P_COMPANY
        INTO :CHILD_ACCOUNT_ID
    DO
    BEGIN
        EXECUTE PROCEDURE CMD_MERGE_ACCOUNT(P_COMPANY, CHILD_ACCOUNT_ID, P_ID);
    END
END ^

