ALTER PROCEDURE CMD_OUTPUT_ENDING_AVERAGE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAM DM_ID,
P_ACCOUNT DM_ID)
AS 
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE GOODS DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE DEBIT_ID DM_ID;
DECLARE VARIABLE CREDIT_ID DM_ID;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;


    FOR
        SELECT EXCHANGE_RATE, DEBIT.ID, CREDIT.ID, CREDIT.ACCOUNT, CREDIT.OBJECT0, CREDIT.OBJECT1, DEBIT.AMOUNT
        FROM ENTRIES
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.TEAM = :P_DOCUMENT_TEAM AND DOCUMENTS.PERIOD = :P_PERIOD
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.ACCOUNT IS NOT NULL AND CREDIT.OBJECT0 IS NOT NULL AND CREDIT.OBJECT1 IS NOT NULL AND
                                (:P_ACCOUNT IS NULL OR CREDIT.ACCOUNT = :P_ACCOUNT)
        WHERE ENTRIES.COMPANY = :P_COMPANY
        ORDER BY DOCUMENTS.INPUT_DATE ASC, ENTRIES.ID ASC
        INTO :EXCHANGE_RATE, :DEBIT_ID, :CREDIT_ID, :ACCOUNT, :GOODS, :WAREHOUSE, :AMOUNT
    DO
    BEGIN
        SELECT PRICE, INPUT_AMOUNT, INPUT_SUM_OF_MONEY
        FROM TEMP_AVERAGE_PRICE
        WHERE ACCOUNT = :ACCOUNT AND GOODS = :GOODS AND WAREHOUSE = :WAREHOUSE
        INTO :PRICE, :INPUT_AMOUNT, INPUT_SUM_OF_MONEY;

        IF(PRICE IS NOT NULL)THEN
        BEGIN
            INPUT_AMOUNT = ROUND(INPUT_AMOUNT - AMOUNT, NUMBER_DECIMAL_DIGITS);

            IF(INPUT_AMOUNT <= 0)THEN
            BEGIN
                OFFICIAL_SUM_OF_MONEY = INPUT_SUM_OF_MONEY;

                IF(ROUND(AMOUNT, 5) = 0)THEN
                    PRICE = 0;
                ELSE
                    PRICE = ROUND(OFFICIAL_SUM_OF_MONEY/AMOUNT, NUMBER_DECIMAL_DIGITS);
            END
            ELSE
            BEGIN
                OFFICIAL_SUM_OF_MONEY = ROUND(:AMOUNT * :PRICE, 0);
            END

            INPUT_SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OFFICIAL_SUM_OF_MONEY;

            UPDATE TEMP_AVERAGE_PRICE
            SET INPUT_AMOUNT = :INPUT_AMOUNT, INPUT_SUM_OF_MONEY = :INPUT_SUM_OF_MONEY
            WHERE ACCOUNT = :ACCOUNT AND GOODS = :GOODS AND WAREHOUSE = :WAREHOUSE;

            FOREIGN_SUM_OF_MONEY = IIF(EXCHANGE_RATE = 0, 0, ROUND(OFFICIAL_SUM_OF_MONEY/EXCHANGE_RATE, :NUMBER_DECIMAL_DIGITS));

            UPDATE CREDIT_DEBIT
            SET PRICE = :PRICE, OFFICIAL_SUM_OF_MONEY = :OFFICIAL_SUM_OF_MONEY, FOREIGN_SUM_OF_MONEY= :FOREIGN_SUM_OF_MONEY
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ID = :DEBIT_ID;

            UPDATE CREDIT_DEBIT
            SET PRICE = :PRICE, OFFICIAL_SUM_OF_MONEY = :OFFICIAL_SUM_OF_MONEY, FOREIGN_SUM_OF_MONEY= :FOREIGN_SUM_OF_MONEY
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ID = :CREDIT_ID;
        END
    END
END ^

ALTER PROCEDURE CMD_PRODUCT_PRICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_BEGINNING_DATE_OF_PERIOD DM_DATE,
P_ENDING_DATE_OF_PERIOD DM_DATE,
P_SOURCE_ACCOUNT DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_PERCENT DM_DOUBLE,
P_DOCUMENT_TEAMS DM_NAME,
P_OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD)
AS 
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE PS_NO DM_DOUBLE;
DECLARE VARIABLE ENTRY DM_ID;
DECLARE VARIABLE DEBIT DM_ID;
DECLARE VARIABLE CREDIT DM_ID;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
DECLARE VARIABLE SUM_AMOUNT DM_DOUBLE;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE ROW_NUMBER DM_INTEGER;
DECLARE VARIABLE CURRENT_ROW DM_INTEGER;
DECLARE VARIABLE SOURCE_OBJECT_TYPE1 DM_ID;
DECLARE VARIABLE CUR0 CURSOR FOR
  (
    SELECT OBJECT0, SUM(DEBIT)
        FROM
        (
            SELECT OBJECT0, OFFICIAL_DEBIT - OFFICIAL_CREDIT AS DEBIT
            FROM BALANCES
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD AND ACCOUNT = :P_SOURCE_ACCOUNT AND BALANCES.OBJECT0 IS NOT NULL

            UNION ALL

            SELECT OBJECT0, DEBIT - CREDIT AS DEBIT
            FROM INT_PS_1_TK_DT0(:P_COMPANY, :P_SOURCE_ACCOUNT, :P_BEGINNING_DATE_OF_PERIOD, :P_ENDING_DATE_OF_PERIOD)
        )
        GROUP BY OBJECT0
  );

DECLARE VARIABLE CUR01 CURSOR FOR
  (
    SELECT OBJECT0, OBJECT1, SUM(DEBIT)
        FROM
        (
            SELECT OBJECT0, OBJECT1, OFFICIAL_DEBIT - OFFICIAL_CREDIT AS DEBIT
            FROM BALANCES
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD AND ACCOUNT = :P_SOURCE_ACCOUNT AND BALANCES.OBJECT0 IS NOT NULL

            UNION ALL

            SELECT OBJECT0, OBJECT1, DEBIT - CREDIT AS DEBIT
            FROM INT_PS_1_TK_DT0_DT1(:P_COMPANY, :P_SOURCE_ACCOUNT, :P_BEGINNING_DATE_OF_PERIOD, :P_ENDING_DATE_OF_PERIOD)
        )
        GROUP BY OBJECT0, OBJECT1
  );
DECLARE VARIABLE INPUT_DATE DM_DATE;
DECLARE VARIABLE ACCOUNT_GOODS_WAREHOUSE DM_STRING;
DECLARE VARIABLE REMAINING_AMOUNT DM_DOUBLE;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT ACCOUNTS.ATOM_TYPE_1
    FROM ACCOUNTS
    WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_SOURCE_ACCOUNT
    INTO :SOURCE_OBJECT_TYPE1;

    
    UPDATE CREDIT_DEBIT
    SET CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = 0
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
        CREDIT_DEBIT.ENTRY IN
        (
            SELECT ENTRIES.ID
            FROM ENTRIES
            JOIN DOCUMENTS ON   DOCUMENTS.COMPANY = :P_COMPANY AND
                                DOCUMENTS.PERIOD = :P_PERIOD AND
                                DOCUMENTS.ID = ENTRIES.DOCUMENT
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.ACCOUNT = :P_TARGET_ACCOUNT
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT = :P_SOURCE_ACCOUNT
            WHERE ENTRIES.COMPANY = :P_COMPANY
        );


    IF(SOURCE_OBJECT_TYPE1 IS NULL)THEN
        OPEN CUR0;
    ELSE
        OPEN CUR01;

    WHILE (1=1) DO
    BEGIN
        IF(SOURCE_OBJECT_TYPE1 IS NULL)THEN
            FETCH CUR0 INTO :OBJECT0, :PS_NO;
        ELSE
            FETCH CUR01 INTO :OBJECT0, :OBJECT1, :PS_NO;

        IF (ROW_COUNT = 0) THEN LEAVE;
        ELSE
        BEGIN
            PS_NO = ROUND(PS_NO*P_PERCENT, 0);

            SELECT SUM(DEBIT.AMOUNT), COUNT(*)
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND
                                    DEBIT.ACCOUNT = :P_TARGET_ACCOUNT AND 
                                    DEBIT.AMOUNT > 0
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND
                                    CREDIT.ACCOUNT = :P_SOURCE_ACCOUNT AND CREDIT.OBJECT0 = :OBJECT0 AND (:OBJECT1 IS NULL OR CREDIT.OBJECT1 = :OBJECT1)
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD
            INTO :SUM_AMOUNT, :ROW_NUMBER;

            IF(SUM_AMOUNT > 0)THEN
                PRICE = ROUND(PS_NO/SUM_AMOUNT, :NUMBER_DECIMAL_DIGITS);
            ELSE
                PRICE = 0;

            CURRENT_ROW = 0;

            FOR
                SELECT ENTRIES.ID, DEBIT.ID, CREDIT.ID, DEBIT.AMOUNT
                FROM DOCUMENTS
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND
                                        DEBIT.ACCOUNT = :P_TARGET_ACCOUNT AND 
                                        DEBIT.AMOUNT > 0
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND
                                        CREDIT.ACCOUNT = :P_SOURCE_ACCOUNT AND CREDIT.OBJECT0 = :OBJECT0 AND (:OBJECT1 IS NULL OR CREDIT.OBJECT1 = :OBJECT1)
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD
                INTO :ENTRY, :DEBIT, :CREDIT, :AMOUNT
            DO
            BEGIN
                CURRENT_ROW = CURRENT_ROW + 1;

                IF(CURRENT_ROW < ROW_NUMBER)THEN
                    SUM_OF_MONEY = ROUND(AMOUNT*PRICE, 0);
                ELSE
                    SUM_OF_MONEY = PS_NO;

                PS_NO = PS_NO - SUM_OF_MONEY;

                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.PRICE = :PRICE,
                    CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :SUM_OF_MONEY,
                    CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = :SUM_OF_MONEY
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY AND CREDIT_DEBIT.ID = :DEBIT;

                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.PRICE = :PRICE,
                    CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :SUM_OF_MONEY,
                    CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = :SUM_OF_MONEY
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY AND CREDIT_DEBIT.ID = :CREDIT;
            END
        END
    END

    IF(SOURCE_OBJECT_TYPE1 IS NULL)THEN
        CLOSE CUR0;
    ELSE
        CLOSE CUR01;

    
    IF(P_OUTPUT_PRICE_METHOD = 1)THEN
        EXECUTE PROCEDURE CMD_IMMEDIATE_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :P_DOCUMENT_TEAMS, :P_TARGET_ACCOUNT);
    ELSE IF(P_OUTPUT_PRICE_METHOD = 2)THEN
        EXECUTE PROCEDURE CMD_ENDING_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD,  :P_DOCUMENT_TEAMS, :P_TARGET_ACCOUNT);
    ELSE IF(P_OUTPUT_PRICE_METHOD = 3)THEN
        EXECUTE PROCEDURE CMD_BATCH_PRICE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD,  :P_DOCUMENT_TEAMS, :P_TARGET_ACCOUNT)
        RETURNING_VALUES :INPUT_DATE, :ACCOUNT_GOODS_WAREHOUSE, :REMAINING_AMOUNT;
END ^

ALTER PROCEDURE CMD_PRODUCT_PRICE_OBJECT0 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_BEGINNING_DATE_OF_PERIOD DM_DATE,
P_ENDING_DATE_OF_PERIOD DM_DATE,
P_SOURCE_ACCOUNT DM_ID,
P_SOURCE_OBJECT0 DM_ID,
P_TARGET_ACCOUNT DM_ID,
P_PERCENT DM_DOUBLE,
P_DOCUMENT_TEAMS DM_NAME,
P_OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD)
AS 
declare variable object0 dm_id;
declare variable object1 dm_id;
declare variable ps_no dm_double;
declare variable entry dm_id;
declare variable debit dm_id;
declare variable credit dm_id;
declare variable number_decimal_digits dm_integer;
declare variable sum_amount dm_double;
declare variable amount dm_double;
declare variable price dm_double;
declare variable sum_of_money dm_double;
declare variable row_number dm_integer;
declare variable current_row dm_integer;
declare variable source_object_type1 dm_id;
declare variable input_date dm_date;
declare variable account_goods_warehouse dm_string;
declare variable remaining_amount dm_double;
declare cur0 cursor for (select sum(debit)
        from
        (
            select official_debit - official_credit as debit
            from balances
            where balances.company = :p_company and period = :p_period and account = :p_source_account and balances.object0 is not null and
            (:p_source_object0 is null or balances.object0 = :p_source_object0)

            union all

            select debit - credit as debit
            from int_ps_1_tk_1_dt0(:p_company, :p_source_account, :p_source_object0, :p_beginning_date_of_period, :p_ending_date_of_period)
        )
  );
declare cur01 cursor for (select object1, sum(debit)
        from
        (
            select object1, official_debit - official_credit as debit
            from balances
            where balances.company = :p_company and period = :p_period and account = :p_source_account and balances.object0 is not null and
            (:p_source_object0 is null or balances.object0 = :p_source_object0)

            union all

            select object1, debit - credit as debit
            from int_ps_1_tk_1_dt0_dt1(:p_company, :p_source_account, :p_source_object0, :p_beginning_date_of_period, :p_ending_date_of_period)
        )
        group by object1
  );
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT ACCOUNTS.ATOM_TYPE_1
    FROM ACCOUNTS
    WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_SOURCE_ACCOUNT
    INTO :SOURCE_OBJECT_TYPE1;

    
    UPDATE CREDIT_DEBIT
    SET CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = 0
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
        CREDIT_DEBIT.ENTRY IN
        (
            SELECT ENTRIES.ID
            FROM ENTRIES
            JOIN DOCUMENTS ON   DOCUMENTS.COMPANY = :P_COMPANY AND
                                DOCUMENTS.PERIOD = :P_PERIOD AND
                                DOCUMENTS.ID = ENTRIES.DOCUMENT
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.ACCOUNT = :P_TARGET_ACCOUNT
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT = :P_SOURCE_ACCOUNT AND CREDIT.object0 = :p_source_object0
            WHERE ENTRIES.COMPANY = :P_COMPANY
        );


    IF(SOURCE_OBJECT_TYPE1 IS NULL)THEN
        OPEN CUR0;
    ELSE
        OPEN CUR01;

    WHILE (1=1) DO
    BEGIN
        IF(SOURCE_OBJECT_TYPE1 IS NULL)THEN
            FETCH CUR0 INTO :PS_NO;
        ELSE
            FETCH CUR01 INTO :OBJECT1, :PS_NO;

        IF (ROW_COUNT = 0) THEN LEAVE;
        ELSE
        BEGIN
            OBJECT0 = p_source_object0;

            PS_NO = ROUND(PS_NO*P_PERCENT, 0);

            SELECT SUM(DEBIT.AMOUNT), COUNT(*)
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND
                                    DEBIT.ACCOUNT = :P_TARGET_ACCOUNT AND 
                                    DEBIT.AMOUNT > 0
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND
                                    CREDIT.ACCOUNT = :P_SOURCE_ACCOUNT AND CREDIT.OBJECT0 = :OBJECT0 AND (:OBJECT1 IS NULL OR CREDIT.OBJECT1 = :OBJECT1)
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD
            INTO :SUM_AMOUNT, :ROW_NUMBER;

            IF(SUM_AMOUNT > 0)THEN
                PRICE = ROUND(PS_NO/SUM_AMOUNT, :NUMBER_DECIMAL_DIGITS);
            ELSE
                PRICE = 0;

            CURRENT_ROW = 0;

            FOR
                SELECT ENTRIES.ID, DEBIT.ID, CREDIT.ID, DEBIT.AMOUNT
                FROM DOCUMENTS
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND
                                        DEBIT.ACCOUNT = :P_TARGET_ACCOUNT AND 
                                        DEBIT.AMOUNT > 0
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND
                                        CREDIT.ACCOUNT = :P_SOURCE_ACCOUNT AND CREDIT.OBJECT0 = :OBJECT0 AND (:OBJECT1 IS NULL OR CREDIT.OBJECT1 = :OBJECT1)
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD
                INTO :ENTRY, :DEBIT, :CREDIT, :AMOUNT
            DO
            BEGIN
                CURRENT_ROW = CURRENT_ROW + 1;

                IF(CURRENT_ROW < ROW_NUMBER)THEN
                    SUM_OF_MONEY = ROUND(AMOUNT*PRICE, 0);
                ELSE
                    SUM_OF_MONEY = PS_NO;

                PS_NO = PS_NO - SUM_OF_MONEY;

                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.PRICE = :PRICE,
                    CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :SUM_OF_MONEY,
                    CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = :SUM_OF_MONEY
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY AND CREDIT_DEBIT.ID = :DEBIT;

                UPDATE CREDIT_DEBIT
                SET CREDIT_DEBIT.PRICE = :PRICE,
                    CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY = :SUM_OF_MONEY,
                    CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY = :SUM_OF_MONEY
                WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = :ENTRY AND CREDIT_DEBIT.ID = :CREDIT;
            END
        END
    END

    IF(SOURCE_OBJECT_TYPE1 IS NULL)THEN
        CLOSE CUR0;
    ELSE
        CLOSE CUR01;

    
    IF(P_OUTPUT_PRICE_METHOD = 1)THEN
        EXECUTE PROCEDURE CMD_IMMEDIATE_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, :P_DOCUMENT_TEAMS, :P_TARGET_ACCOUNT);
    ELSE IF(P_OUTPUT_PRICE_METHOD = 2)THEN
        EXECUTE PROCEDURE CMD_ENDING_AVERAGE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD,  :P_DOCUMENT_TEAMS, :P_TARGET_ACCOUNT);
    ELSE IF(P_OUTPUT_PRICE_METHOD = 3)THEN
        EXECUTE PROCEDURE CMD_BATCH_PRICE(:P_LANGUAGE, :P_COMPANY, :P_PERIOD,  :P_DOCUMENT_TEAMS, :P_TARGET_ACCOUNT)
        RETURNING_VALUES :INPUT_DATE, :ACCOUNT_GOODS_WAREHOUSE, :REMAINING_AMOUNT;
END ^

ALTER PROCEDURE CMD_RECREATE_DOCUMENT_NUMBER (P_COMPANY DM_ID,
P_TEAM DM_ID,
P_ID DM_ID,
P_INPUT_DATE DM_DATE)
AS 
DECLARE VARIABLE DOCUMENT_CODE_CYCLE DM_TIME_TYPE;
DECLARE VARIABLE TIME_1 DM_INTEGER;
DECLARE VARIABLE TIME_2 DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE DOCUMENT_CODE DM_CODE;
DECLARE VARIABLE DOCUMENT_NUMBER DM_CODE;
DECLARE VARIABLE NUMBER DM_INTEGER;
DECLARE VARIABLE STARTING_DATE DM_DATE;
BEGIN
    SELECT FIRST 1 DOCUMENT_CODE_CYCLE
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :DOCUMENT_CODE_CYCLE;

    TIME_1 = EXTRACT(MONTH FROM P_INPUT_DATE);
    TIME_2 = EXTRACT(YEAR FROM P_INPUT_DATE);

    
    IF(DOCUMENT_CODE_CYCLE = 2)THEN
    BEGIN
        SELECT :TIME_2 || '.' || :TIME_1 || '.1', :TIME_2 || '.' || :TIME_1 || '.' || ENDING_DAY
        FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(DOCUMENT_CODE_CYCLE = 3)THEN
    BEGIN
        TIME_1 = (TIME_1 + 2)/3;
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_QUARTER_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(DOCUMENT_CODE_CYCLE = 4)THEN
    BEGIN
        TIME_1 = IIF(TIME_1 < 7, 0, 1);
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_HALF_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(DOCUMENT_CODE_CYCLE = 5)THEN
    BEGIN
        TIME_1 = TIME_2;
        BEGINNING_DATE = TIME_2 || '.1.1';
        ENDING_DATE = TIME_2 || '.12.31';
    END

    
    SELECT PERIODS.BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :STARTING_DATE;

    IF(STARTING_DATE > BEGINNING_DATE)THEN BEGINNING_DATE = STARTING_DATE;

    IF(P_ID IS NULL)THEN
    BEGIN
        SELECT DEFAULT_CODE
        FROM DOCUMENT_TEAMS
        WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = :P_TEAM
        INTO :DOCUMENT_CODE;
    END
    ELSE
    BEGIN
        SELECT CODE
        FROM DOCUMENTS
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
        INTO :DOCUMENT_CODE;
    END

    NUMBER = 0;
    FOR
        SELECT DOCUMENTS.ID
        FROM DOCUMENTS
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.TEAM = :P_TEAM AND CODE = :DOCUMENT_CODE AND DOCUMENTS.INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE
        ORDER BY DOCUMENTS.INPUT_DATE, ID
        INTO :P_ID
    DO
    BEGIN
        NUMBER = NUMBER + 1;

        IF(NUMBER < 10)THEN
            DOCUMENT_NUMBER = '0000' || NUMBER;
        ELSE IF(NUMBER < 100)THEN
            DOCUMENT_NUMBER = '000' || NUMBER;
        ELSE IF(NUMBER < 1000)THEN
            DOCUMENT_NUMBER = '00' || NUMBER;
        ELSE IF(NUMBER < 10000)THEN
            DOCUMENT_NUMBER = '0' || NUMBER;
        ELSE DOCUMENT_NUMBER = NUMBER;

        UPDATE DOCUMENTS
        SET DOCUMENTS.NUMBER = :DOCUMENT_NUMBER
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.TEAM = :P_TEAM  AND DOCUMENTS.ID = :P_ID;
    END
END ^

ALTER PROCEDURE CMD_SET_DEFAULT_OBJECT_0 (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
declare variable object dm_id;
BEGIN
    select accounts.default_object_0
    from accounts
    where accounts.company = :p_company and accounts.id = :p_id
    into :object;

    if(object is not null)then
    begin
        UPDATE CREDIT_DEBIT
        SET CREDIT_DEBIT.OBJECT0 = :object
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ACCOUNT = :P_ID;
    
        UPDATE balances
        SET balances.object0 = :object
        WHERE balances.COMPANY = :P_COMPANY AND balances.account = :P_ID;
    end
END ^

ALTER PROCEDURE CMD_SET_DEFAULT_OBJECT_1 (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
declare variable object dm_id;
BEGIN
    select accounts.default_object_1
    from accounts
    where accounts.company = :p_company and accounts.id = :p_id
