    if(object is not null)then
    begin
        UPDATE CREDIT_DEBIT
        SET CREDIT_DEBIT.OBJECT1 = :object
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ACCOUNT = :P_ID;
    
        UPDATE balances
        SET balances.object1 = :object
        WHERE balances.COMPANY = :P_COMPANY AND balances.account = :P_ID;
    end
END ^

ALTER PROCEDURE CMD_SOURCE_TARGET_ACCOUNTS (P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE CONTENT_911 DM_CONTENT;
DECLARE VARIABLE CONTENT_154 DM_CONTENT;
DECLARE VARIABLE CONTENT_CPSX DM_CONTENT;
DECLARE VARIABLE ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM;
BEGIN
    DELETE FROM PROTONS WHERE COMPANY = :P_COMPANY AND ID IN
    (
        SELECT ID
        FROM SOURCE_ACCOUNTS
        WHERE COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD
    );

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :ACCOUNTING_SYSTEM;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = -15 AND LANGUAGE = 0
    INTO :CONTENT_CPSX;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = -20 AND LANGUAGE = 0
    INTO :CONTENT_911;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = -30 AND LANGUAGE = 0
    INTO :CONTENT_154;

    ORDINAL = 0;

    IF(ACCOUNTING_SYSTEM = 2)THEN 
    BEGIN
        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '1541', '1548', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '1542', '1548', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '1543', '1548', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '1547', '1548', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '1548', '155', '632', :ORDINAL, :CONTENT_154, 0, 1, 0, 4, 1)
        INTO :ORDINAL;
    END
    ELSE IF(ACCOUNTING_SYSTEM = 1)THEN 
    BEGIN
        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '621', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '622', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '623', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '627', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '154', '155', '632', :ORDINAL, :CONTENT_154, 0, 1, 0, 4, 1)
        INTO :ORDINAL;
    END
    ELSE
    BEGIN
        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '621', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '622', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '623', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '627', '154', NULL, :ORDINAL, :CONTENT_CPSX, 1, 1, 0, 1, 1)
        INTO :ORDINAL;

        
        SELECT ORDINAL
        FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '154', '155', '632', :ORDINAL, :CONTENT_154, 0, 1, 0, 4, 1)
        INTO :ORDINAL;
    END

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '521', '5111', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '531', '5111', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '532', '5111', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '511', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '512', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
