    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '635', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '641', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '642', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '711', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '811', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '821', '911', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;

    
    SELECT ORDINAL
    FROM INT_SOURCE_TARGET_ACCOUNTS(:P_COMPANY, :P_PERIOD, '911', '4212', NULL, :ORDINAL, :CONTENT_911, 1, 1, 0, 1, 1)
    INTO :ORDINAL;
END ^

ALTER PROCEDURE CMD_SUMMARIZATION (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID,
P_SUMMARIZATION_TYPE DM_SUMMARIZATION_TYPES,
P_DOCUMENT_TEAMS DM_NAME)
AS 
DECLARE VARIABLE PRODUCT_PRICE DM_BOOL;
DECLARE VARIABLE VAT_DEDUCTION DM_BOOL;
DECLARE VARIABLE TRANSFER_ACCOUNTS DM_BOOL;
DECLARE VARIABLE CAL_OUTPUT_PRICE DM_BOOL;
declare variable NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT SETTINGS.NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;
    
    IF(BIN_AND(P_SUMMARIZATION_TYPE, 1) = 1)THEN
    BEGIN
        CAL_OUTPUT_PRICE = 1;
    END
    ELSE CAL_OUTPUT_PRICE = 0;

    
    IF(BIN_AND(P_SUMMARIZATION_TYPE, 2) = 2)THEN
    BEGIN
    END

    IF(BIN_AND(P_SUMMARIZATION_TYPE, 4) = 4)THEN
    BEGIN
        EXECUTE PROCEDURE CMD_DEPRECIATE_ASSET(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD);
    END

    IF(BIN_AND(P_SUMMARIZATION_TYPE, 1024) = 1024)THEN
    BEGIN
        EXECUTE PROCEDURE CMD_DEPRECIATE_EXPENSE(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD);
    END

    TRANSFER_ACCOUNTS = IIF(BIN_AND(P_SUMMARIZATION_TYPE, 8) = 8, 1, 0);
    PRODUCT_PRICE = IIF(BIN_AND(P_SUMMARIZATION_TYPE, 2048) = 2048, 1, 0);
    VAT_DEDUCTION = IIF(BIN_AND(P_SUMMARIZATION_TYPE, 8192) = 8192, 1, 0);

    EXECUTE PROCEDURE CMD_MADE_AUTO_ENTRY(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, VAT_DEDUCTION, TRANSFER_ACCOUNTS, CAL_OUTPUT_PRICE, PRODUCT_PRICE, :P_DOCUMENT_TEAMS, 0);


    IF(BIN_AND(P_SUMMARIZATION_TYPE, 32) = 32)THEN
    BEGIN
        UPDATE PERIODS
        SET LOCKED = 1
        WHERE COMPANY = :P_COMPANY AND ID = :P_FROM_PERIOD;
    END

    IF(:P_TO_PERIOD IS NOT NULL)THEN
    BEGIN
        
        IF(BIN_AND(P_SUMMARIZATION_TYPE, 16) = 16)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_TRANSFER_BALANCE(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD, :NUMBER_DECIMAL_DIGITS);
            EXECUTE PROCEDURE CMD_TRANSFER_DOCUMENT_BALANCE(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD);
            EXECUTE PROCEDURE CMD_TRANSFER_ENTRY_BALANCE(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD);

            UPDATE PERIODS
            SET PERIODS.CHANGED = 0
            WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :P_FROM_PERIOD;
        END

        IF(BIN_AND(P_SUMMARIZATION_TYPE, 4096) = 4096)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_COPY_TARGET_PERCENT(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD);
        END
        
        IF(BIN_AND(P_SUMMARIZATION_TYPE, 64) = 64)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_COPY_DEFINE(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD);
        END

        
        IF(BIN_AND(P_SUMMARIZATION_TYPE, 128) = 128)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_COPY_DEFINE_APPORTIONMENT(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD);
        END

        
        IF(BIN_AND(P_SUMMARIZATION_TYPE, 256) = 256)THEN
        BEGIN
            EXECUTE PROCEDURE CMD_COPY_DEFINE_EXPENSE(:P_LANGUAGE, :P_COMPANY, :P_FROM_PERIOD, :P_TO_PERIOD);
        END
    END
END ^

ALTER PROCEDURE CMD_SWAP_OBJECT_01 (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
BEGIN
    UPDATE BALANCES
    SET OBJECT2 = OBJECT0
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE BALANCES
    SET OBJECT0 = OBJECT1
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE BALANCES
    SET OBJECT1 = OBJECT2
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE BALANCES
    SET OBJECT2 = NULL
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE CREDIT_DEBIT
    SET OBJECT2 = OBJECT0
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE CREDIT_DEBIT
    SET OBJECT0 = OBJECT1
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE CREDIT_DEBIT
    SET OBJECT1 = OBJECT2
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;

    UPDATE CREDIT_DEBIT
    SET OBJECT2 = NULL
    WHERE COMPANY = :P_COMPANY AND ACCOUNT = :P_ID;
END ^

ALTER PROCEDURE CMD_TEMP_BATCH_PRICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAM DM_ID,
P_ACCOUNT DM_ID)
AS 
BEGIN
    INSERT INTO TEMP_BATCH_PRICE(DOCUMENT, INPUT_DATE, ENTRY, DEBIT, CREDIT, ACCOUNT, GOODS, WAREHOUSE, AMOUNT)
    SELECT DOCUMENTS.ID, DOCUMENTS.INPUT_DATE, ENTRIES.ID, DEBIT.ID, CREDIT.ID, CREDIT.ACCOUNT, CREDIT.OBJECT0, CREDIT.OBJECT1, CREDIT.AMOUNT
    FROM DOCUMENTS
    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.ACCOUNT IS NOT NULL AND CREDIT.OBJECT0 IS NOT NULL AND CREDIT.OBJECT1 IS NOT NULL AND
                                (:P_ACCOUNT IS NULL OR CREDIT.ACCOUNT = :P_ACCOUNT)
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT.ACCOUNT AND (BIN_AND(ACCOUNTS.ACCOUNT_TYPES, 524288) = 524288)
    JOIN ATOMS OBJECT0S ON OBJECT0S.COMPANY = :P_COMPANY AND OBJECT0S.ID = CREDIT.OBJECT0 AND OBJECT0S.OBJECT_TYPE = 54
    JOIN ATOMS OBJECT1S ON OBJECT1S.COMPANY = :P_COMPANY AND OBJECT1S.ID = CREDIT.OBJECT1 AND OBJECT1S.OBJECT_TYPE = 98
    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD AND DOCUMENTS.TEAM = :P_DOCUMENT_TEAM;
END ^

ALTER PROCEDURE CMD_TEMP_IMMEDIATE_AVERAGE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAM DM_ID,
P_ACCOUNT DM_ID)
AS 
BEGIN
    INSERT INTO TEMP_IMMEDIATE_AVERAGE(DOCUMENT, INPUT_DATE, ENTRY, EXCHANGE_RATE, DEBIT, CREDIT, ACCOUNT, GOODS, WAREHOUSE, OUTPUT_AMOUNT)
    SELECT DOCUMENTS.ID, DOCUMENTS.INPUT_DATE, ENTRIES.ID, ENTRIES.EXCHANGE_RATE, DEBIT.ID, CREDIT.ID, CREDIT.ACCOUNT, CREDIT.OBJECT0, CREDIT.OBJECT1, CREDIT.AMOUNT
    FROM DOCUMENTS
    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.ACCOUNT IS NOT NULL AND CREDIT.OBJECT0 IS NOT NULL AND CREDIT.OBJECT1 IS NOT NULL AND
                                (CREDIT.ACCOUNT = :P_ACCOUNT OR :P_ACCOUNT IS NULL)
    JOIN ATOMS OBJECT0S ON OBJECT0S.COMPANY = :P_COMPANY AND OBJECT0S.ID = CREDIT.OBJECT0 AND OBJECT0S.OBJECT_TYPE = 54
    JOIN ATOMS OBJECT1S ON OBJECT1S.COMPANY = :P_COMPANY AND OBJECT1S.ID = CREDIT.OBJECT1 AND OBJECT1S.OBJECT_TYPE = 98
    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_PERIOD AND DOCUMENTS.TEAM = :P_DOCUMENT_TEAM;
END ^

ALTER PROCEDURE CMD_TRANSFER (P_COMPANY DM_ID,
P_DATE DM_DATE)
AS 
declare variable number_decimal_digits dm_integer;
declare variable beginning_date_period dm_date;
declare variable ending_date_period dm_date;
declare variable from_period dm_id;
declare variable to_period dm_id;
declare variable starting_time timestamp;
declare variable ending_time timestamp;
declare variable seconds dm_integer = 0;
declare variable need_transfer dm_bool;
BEGIN
    SELECT SETTINGS.NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT PERIODS.BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :BEGINNING_DATE_PERIOD;

    SELECT CAST('NOW' AS TIMESTAMP) FROM RDB$DATABASE INTO :STARTING_TIME;

    WHILE(SECONDS <= 11)DO
    BEGIN
        NEED_TRANSFER = 0;

        FOR
            SELECT FIRST 1 ID, BEGINNING_DATE, ENDING_DATE
            FROM PERIODS
            WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.BEGINNING_DATE >= :BEGINNING_DATE_PERIOD AND PERIODS.BEGINNING_DATE < :P_DATE AND PERIODS.CHANGED = 1
            ORDER BY PERIODS.BEGINNING_DATE
            INTO :FROM_PERIOD, :BEGINNING_DATE_PERIOD, :ending_date_period
        DO
        BEGIN
            NEED_TRANSFER = 1;

            FOR
                SELECT FIRST 1 ID 
                FROM PERIODS
                WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.BEGINNING_DATE = DATEADD(DAY, 1, :ending_date_period) AND PERIODS.BEGINNING_DATE <= :P_DATE
                ORDER BY PERIODS.BEGINNING_DATE
                INTO :TO_PERIOD
            DO
            BEGIN
                EXECUTE PROCEDURE CMD_TRANSFER_BALANCE(0, :P_COMPANY, :FROM_PERIOD, :TO_PERIOD, :NUMBER_DECIMAL_DIGITS);
                EXECUTE PROCEDURE CMD_TRANSFER_DOCUMENT_BALANCE(0, :P_COMPANY, :FROM_PERIOD, :TO_PERIOD);
                EXECUTE PROCEDURE CMD_TRANSFER_ENTRY_BALANCE(0, :P_COMPANY, :FROM_PERIOD, :TO_PERIOD);
    
                UPDATE PERIODS
                SET PERIODS.CHANGED = 0
                WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :FROM_PERIOD;
    
                FROM_PERIOD = TO_PERIOD;

                UPDATE PERIODS
                SET PERIODS.CHANGED = 1
                WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :TO_PERIOD;
            END
        END

        IF(NEED_TRANSFER = 0)THEN
            SECONDS = 13;
        ELSE
        BEGIN
            SELECT CAST('NOW' AS TIMESTAMP) FROM RDB$DATABASE INTO :ENDING_TIME;
            SECONDS = DATEDIFF(SECOND, STARTING_TIME, ENDING_TIME);
        END
    END
END ^

ALTER PROCEDURE CMD_TRANSFER_BALANCE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID,
P_NUMBER_DECIMAL_DIGITS DM_INTEGER)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE BEGINNING_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INCREASE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE DECREASE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE ENDING_AMOUNT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE RISING_FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE RISING_FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE RISING_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE RISING_OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE ENDING_FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE ENDING_FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE ENDING_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE ENDING_OFFICIAL_CREDIT DM_DOUBLE;
BEGIN






    
    DELETE FROM BALANCES
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD;


    FOR
        SELECT ACCOUNT, CURRENCY, OBJECT0, OBJECT1, OBJECT2,
            SUM(BEGINNING_AMOUNT), SUM(INCREASE_AMOUNT), SUM(DECREASE_AMOUNT),
            SUM(BEGINNING_FOREIGN_DEBIT), SUM(BEGINNING_FOREIGN_CREDIT), SUM(BEGINNING_OFFICIAL_DEBIT), SUM(BEGINNING_OFFICIAL_CREDIT),
            SUM(RISING_FOREIGN_DEBIT), SUM(RISING_FOREIGN_CREDIT),  SUM(RISING_OFFICIAL_DEBIT), SUM(RISING_OFFICIAL_CREDIT)
        FROM
            (
                SELECT ACCOUNT, CURRENCY, OBJECT0, OBJECT1, OBJECT2,
                AMOUNT BEGINNING_AMOUNT, 0 INCREASE_AMOUNT, 0 DECREASE_AMOUNT,
                FOREIGN_DEBIT BEGINNING_FOREIGN_DEBIT, FOREIGN_CREDIT BEGINNING_FOREIGN_CREDIT, OFFICIAL_DEBIT BEGINNING_OFFICIAL_DEBIT, OFFICIAL_CREDIT BEGINNING_OFFICIAL_CREDIT,
                0 RISING_FOREIGN_DEBIT, 0 RISING_FOREIGN_CREDIT, 0 RISING_OFFICIAL_DEBIT, 0 RISING_OFFICIAL_CREDIT
                FROM BALANCES
                WHERE COMPANY = :P_COMPANY AND PERIOD = :P_FROM_PERIOD

                UNION ALL

                SELECT ACCOUNT, ENTRIES.CURRENCY, OBJECT0, OBJECT1, OBJECT2,
                0 BEGINNING_AMOUNT, AMOUNT INCREASE_AMOUNT, 0 DECREASE_AMOUNT,
                0 BEGINNING_FOREIGN_DEBIT, 0 BEGINNING_FOREIGN_CREDIT, 0 BEGINNING_OFFICIAL_DEBIT, 0 BEGINNING_OFFICIAL_CREDIT,
                FOREIGN_SUM_OF_MONEY RISING_FOREIGN_DEBIT, 0 RISING_FOREIGN_CREDIT, OFFICIAL_SUM_OF_MONEY RISING_OFFICIAL_DEBIT, 0 RISING_OFFICIAL_CREDIT
                FROM DOCUMENTS
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY AND CREDIT_DEBIT.SIDE = 0
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD

                UNION ALL

                SELECT ACCOUNT, ENTRIES.CURRENCY, OBJECT0, OBJECT1, OBJECT2,
                0 BEGINNING_AMOUNT, 0 INCREASE_AMOUNT, AMOUNT DECREASE_AMOUNT,
                0 BEGINNING_FOREIGN_DEBIT, 0 BEGINNING_FOREIGN_CREDIT, 0 BEGINNING_OFFICIAL_DEBIT, 0 BEGINNING_OFFICIAL_CREDIT,
                0 RISING_FOREIGN_DEBIT, FOREIGN_SUM_OF_MONEY RISING_FOREIGN_CREDIT, 0 RISING_OFFICIAL_DEBIT, OFFICIAL_SUM_OF_MONEY RISING_OFFICIAL_CREDIT
                FROM DOCUMENTS
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY AND CREDIT_DEBIT.SIDE = 1
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
             )
       GROUP BY ACCOUNT, OBJECT0, OBJECT1, OBJECT2, CURRENCY
       INTO :ACCOUNT, :CURRENCY, :OBJECT0, :OBJECT1, :OBJECT2, :BEGINNING_AMOUNT, :INCREASE_AMOUNT, :DECREASE_AMOUNT, :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT, :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT
    DO
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT + RISING_FOREIGN_CREDIT - BEGINNING_FOREIGN_DEBIT - RISING_FOREIGN_DEBIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT + RISING_OFFICIAL_CREDIT - BEGINNING_OFFICIAL_DEBIT - RISING_OFFICIAL_DEBIT;

        ENDING_AMOUNT = ROUND(BEGINNING_AMOUNT + INCREASE_AMOUNT - DECREASE_AMOUNT, P_NUMBER_DECIMAL_DIGITS);

        IF(ENDING_FOREIGN_DEBIT > 0)THEN
            ENDING_FOREIGN_CREDIT = 0;
        ELSE
            ENDING_FOREIGN_DEBIT = 0;

        IF(ENDING_OFFICIAL_DEBIT > 0)THEN
            ENDING_OFFICIAL_CREDIT = 0;
        ELSE
            ENDING_OFFICIAL_DEBIT = 0;

        IF(ENDING_AMOUNT <> 0 OR ENDING_FOREIGN_CREDIT <> 0 OR ENDING_FOREIGN_DEBIT <> 0 OR ENDING_OFFICIAL_CREDIT <> 0 OR ENDING_OFFICIAL_DEBIT <> 0)THEN
            EXECUTE PROCEDURE BALANCE_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_TO_PERIOD,
            :ACCOUNT, :CURRENCY, 0, :OBJECT0, :OBJECT1, :OBJECT2, :ENDING_AMOUNT, 0, :ENDING_FOREIGN_CREDIT, :ENDING_FOREIGN_DEBIT, :ENDING_OFFICIAL_CREDIT, :ENDING_OFFICIAL_DEBIT);
    END
END ^

ALTER PROCEDURE CMD_TRANSFER_BALANCE_EXTERNAL (P_LANGUAGE DM_SMALLINT,
P_FROM_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_COMPANY DM_ID,
P_TO_PERIOD DM_ID,
CONNECTION DM_FILE_NAME)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE BEGINNING_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INCREASE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE DECREASE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE ENDING_AMOUNT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE RISING_FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE RISING_FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE RISING_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE RISING_OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE ENDING_FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE ENDING_FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE ENDING_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE ENDING_OFFICIAL_CREDIT DM_DOUBLE;
BEGIN
    
    EXECUTE STATEMENT ('DELETE FROM BALANCES WHERE COMPANY = :P_TO_COMPANY AND PERIOD = :P_TO_PERIOD')
    (P_TO_COMPANY:=:P_TO_COMPANY, P_TO_PERIOD:=:P_TO_PERIOD)
    ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey';

    FOR
        SELECT ACCOUNT, CURRENCY, OBJECT0, OBJECT1, OBJECT2,
            SUM(BEGINNING_AMOUNT), SUM(INCREASE_AMOUNT), SUM(DECREASE_AMOUNT),
            SUM(BEGINNING_FOREIGN_DEBIT), SUM(BEGINNING_FOREIGN_CREDIT), SUM(BEGINNING_OFFICIAL_DEBIT), SUM(BEGINNING_OFFICIAL_CREDIT),
            SUM(RISING_FOREIGN_DEBIT), SUM(RISING_FOREIGN_CREDIT),  SUM(RISING_OFFICIAL_DEBIT), SUM(RISING_OFFICIAL_CREDIT)
        FROM
            (
                SELECT ACCOUNT, CURRENCY, OBJECT0, OBJECT1, OBJECT2,
                AMOUNT BEGINNING_AMOUNT, 0 INCREASE_AMOUNT, 0 DECREASE_AMOUNT,
                FOREIGN_DEBIT BEGINNING_FOREIGN_DEBIT, FOREIGN_CREDIT BEGINNING_FOREIGN_CREDIT, OFFICIAL_DEBIT BEGINNING_OFFICIAL_DEBIT, OFFICIAL_CREDIT BEGINNING_OFFICIAL_CREDIT,
                0 RISING_FOREIGN_DEBIT, 0 RISING_FOREIGN_CREDIT, 0 RISING_OFFICIAL_DEBIT, 0 RISING_OFFICIAL_CREDIT
                FROM BALANCES
                WHERE COMPANY = :P_FROM_COMPANY AND PERIOD = :P_FROM_PERIOD

                UNION ALL

                SELECT ACCOUNT, ENTRIES.CURRENCY, OBJECT0, OBJECT1, OBJECT2,
                0 BEGINNING_AMOUNT, AMOUNT INCREASE_AMOUNT, 0 DECREASE_AMOUNT,
                0 BEGINNING_FOREIGN_DEBIT, 0 BEGINNING_FOREIGN_CREDIT, 0 BEGINNING_OFFICIAL_DEBIT, 0 BEGINNING_OFFICIAL_CREDIT,
                FOREIGN_SUM_OF_MONEY RISING_FOREIGN_DEBIT, 0 RISING_FOREIGN_CREDIT, OFFICIAL_SUM_OF_MONEY RISING_OFFICIAL_DEBIT, 0 RISING_OFFICIAL_CREDIT
                FROM ENTRIES
                JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_FROM_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY AND CREDIT_DEBIT.SIDE = 0
                WHERE ENTRIES.COMPANY = :P_FROM_COMPANY AND ENTRIES.DOCUMENT IN (SELECT ID FROM DOCUMENTS WHERE DOCUMENTS.COMPANY = :P_FROM_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD)

                UNION ALL

                SELECT ACCOUNT, ENTRIES.CURRENCY, OBJECT0, OBJECT1, OBJECT2,
                0 BEGINNING_AMOUNT, 0 INCREASE_AMOUNT, AMOUNT DECREASE_AMOUNT,
                0 BEGINNING_FOREIGN_DEBIT, 0 BEGINNING_FOREIGN_CREDIT, 0 BEGINNING_OFFICIAL_DEBIT, 0 BEGINNING_OFFICIAL_CREDIT,
                0 RISING_FOREIGN_DEBIT, FOREIGN_SUM_OF_MONEY RISING_FOREIGN_CREDIT, 0 RISING_OFFICIAL_DEBIT, OFFICIAL_SUM_OF_MONEY RISING_OFFICIAL_CREDIT
                FROM ENTRIES
                JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_FROM_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY AND CREDIT_DEBIT.SIDE = 1
                WHERE ENTRIES.COMPANY = :P_FROM_COMPANY AND ENTRIES.DOCUMENT IN (SELECT ID FROM DOCUMENTS WHERE DOCUMENTS.COMPANY = :P_FROM_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD)
             )
       GROUP BY ACCOUNT, OBJECT0, OBJECT1, OBJECT2, CURRENCY
       INTO :ACCOUNT, :CURRENCY, :OBJECT0, :OBJECT1, :OBJECT2, :BEGINNING_AMOUNT, :INCREASE_AMOUNT, :DECREASE_AMOUNT, :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT, :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT
    DO
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT + RISING_FOREIGN_CREDIT - BEGINNING_FOREIGN_DEBIT - RISING_FOREIGN_DEBIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT + RISING_OFFICIAL_CREDIT - BEGINNING_OFFICIAL_DEBIT - RISING_OFFICIAL_DEBIT;

        ENDING_AMOUNT = BEGINNING_AMOUNT + INCREASE_AMOUNT - DECREASE_AMOUNT;

        IF(ENDING_FOREIGN_DEBIT > 0)THEN
            ENDING_FOREIGN_CREDIT = 0;
        ELSE
            ENDING_FOREIGN_DEBIT = 0;

        IF(ENDING_OFFICIAL_DEBIT > 0)THEN
            ENDING_OFFICIAL_CREDIT = 0;
        ELSE
            ENDING_OFFICIAL_DEBIT = 0;

        IF(ENDING_AMOUNT <> 0 OR ENDING_FOREIGN_CREDIT <> 0 OR ENDING_FOREIGN_DEBIT <> 0 OR ENDING_OFFICIAL_CREDIT <> 0 OR ENDING_OFFICIAL_DEBIT <> 0)THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:P_FROM_COMPANY, :P_TO_COMPANY, :ACCOUNT, :CONNECTION)
            INTO :ACCOUNT;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:P_FROM_COMPANY, :P_TO_COMPANY, :OBJECT0, :CONNECTION)
            INTO :OBJECT0;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:P_FROM_COMPANY, :P_TO_COMPANY, :OBJECT1, :CONNECTION)
            INTO :OBJECT1;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:P_FROM_COMPANY, :P_TO_COMPANY, :OBJECT2, :CONNECTION)
            INTO :OBJECT2;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:P_FROM_COMPANY, :P_TO_COMPANY, :CURRENCY, :CONNECTION)
            INTO :CURRENCY;

            EXECUTE STATEMENT ('EXECUTE PROCEDURE BALANCE_IU(:P_LANGUAGE, :P_TO_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_TO_PERIOD, :ACCOUNT, :CURRENCY, 0, :OBJECT0, :OBJECT1, :OBJECT2, :ENDING_AMOUNT, 0, :ENDING_FOREIGN_CREDIT, :ENDING_FOREIGN_DEBIT, :ENDING_OFFICIAL_CREDIT, :ENDING_OFFICIAL_DEBIT)')
            (P_LANGUAGE:=:P_LANGUAGE, P_TO_COMPANY:=:P_TO_COMPANY, P_TO_PERIOD:=:P_TO_PERIOD, ACCOUNT:=:ACCOUNT, CURRENCY:=:CURRENCY, OBJECT0:=:OBJECT0, OBJECT1:=:OBJECT1, OBJECT2:=:OBJECT2, ENDING_AMOUNT:=:ENDING_AMOUNT, ENDING_FOREIGN_CREDIT:=:ENDING_FOREIGN_CREDIT, ENDING_FOREIGN_DEBIT:=:ENDING_FOREIGN_DEBIT, ENDING_OFFICIAL_CREDIT:=:ENDING_OFFICIAL_CREDIT, ENDING_OFFICIAL_DEBIT:=:ENDING_OFFICIAL_DEBIT)
            ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey';
        END
    END
END ^

ALTER PROCEDURE CMD_TRANSFER_DOCUMENT_BALANCE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE INCREASE_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE INCREASE_OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE DECREASE_OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE DECREASE_OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
BEGIN
    DELETE FROM DOCUMENT_BALANCES
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD;

    FOR
        SELECT ID, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
        FROM
        (
            
            SELECT INCREASE_DOCUMENT ID, ACCOUNT, OBJECT0, OBJECT1, OBJECT2,
            DOCUMENT_BALANCES.OFFICIAL_DEBIT, DOCUMENT_BALANCES.OFFICIAL_CREDIT
            FROM DOCUMENT_BALANCES
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :P_FROM_PERIOD

            UNION ALL

            
            SELECT DOCUMENTS.ID, ACCOUNT, OBJECT0, OBJECT1, OBJECT2,
            DEBIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_DEBIT, 0 OFFICIAL_CREDIT
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND EXISTS (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = DEBIT.ACCOUNT AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0) 
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD

            UNION ALL
            
            
            SELECT DOCUMENTS.ID, ACCOUNT, OBJECT0, OBJECT1, OBJECT2,
            0 OFFICIAL_DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_CREDIT
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND EXISTS (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT.ACCOUNT AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0) 
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
        )
        GROUP BY ID, ACCOUNT, OBJECT0, OBJECT1, OBJECT2
        INTO :ID, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :INCREASE_OFFICIAL_DEBIT, :INCREASE_OFFICIAL_CREDIT
    DO
    BEGIN
        
        
        SELECT SUM(DECREASE_DOCUMENTS.OFFICIAL_SUM_OF_MONEY)
        FROM DECREASE_DOCUMENTS
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ID = DECREASE_DOCUMENTS.CREDIT_DEBIT AND
        CREDIT_DEBIT.ACCOUNT = :ACCOUNT AND (:OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :OBJECT0) AND (:OBJECT1 IS NULL OR CREDIT_DEBIT.OBJECT1 = :OBJECT1) AND (:OBJECT2 IS NULL OR CREDIT_DEBIT.OBJECT2 = :OBJECT2)
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
        WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.INCREASE_DOCUMENT = :ID
        INTO :DECREASE_OFFICIAL_DEBIT;
        
        SELECT SUM(DECREASE_DOCUMENTS.OFFICIAL_SUM_OF_MONEY)
        FROM DECREASE_DOCUMENTS
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ID = DECREASE_DOCUMENTS.CREDIT_DEBIT AND
        CREDIT_DEBIT.ACCOUNT = :ACCOUNT AND (:OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :OBJECT0) AND (:OBJECT1 IS NULL OR CREDIT_DEBIT.OBJECT1 = :OBJECT1) AND (:OBJECT2 IS NULL OR CREDIT_DEBIT.OBJECT2 = :OBJECT2)
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
        WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.INCREASE_DOCUMENT = :ID
        INTO :DECREASE_OFFICIAL_CREDIT;

        IF(DECREASE_OFFICIAL_DEBIT IS NULL)THEN DECREASE_OFFICIAL_DEBIT = 0;
        IF(DECREASE_OFFICIAL_CREDIT IS NULL)THEN DECREASE_OFFICIAL_CREDIT = 0;

        
        INCREASE_OFFICIAL_DEBIT = INCREASE_OFFICIAL_DEBIT - DECREASE_OFFICIAL_DEBIT;
        INCREASE_OFFICIAL_CREDIT = INCREASE_OFFICIAL_CREDIT - DECREASE_OFFICIAL_CREDIT;

        
        IF(INCREASE_OFFICIAL_DEBIT <> 0 OR INCREASE_OFFICIAL_CREDIT <> 0) THEN
        BEGIN
            UPDATE OR INSERT INTO DOCUMENT_BALANCES(ID, COMPANY, INCREASE_DOCUMENT, PERIOD, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, OFFICIAL_DEBIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, FOREIGN_CREDIT)
            VALUES(GEN_ID(UNIVERSE, 1), :P_COMPANY, :ID, :P_TO_PERIOD, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2, :INCREASE_OFFICIAL_DEBIT, :INCREASE_OFFICIAL_CREDIT, 0, 0);
        END
    END
END ^

ALTER PROCEDURE CMD_TRANSFER_ENTRY_BALANCE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_PERIOD DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_OFFICIAL_SUM_OF_MONEY_DEBIT DM_DOUBLE;
DECLARE VARIABLE INPUT_OFFICIAL_SUM_OF_MONEY_CREDIT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_OFFICIAL_SUM_OF_MONEY_DEBIT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_OFFICIAL_SUM_OF_MONEY_CREDIT DM_DOUBLE;
BEGIN






    DELETE FROM ENTRY_BALANCES
    WHERE COMPANY = :P_COMPANY AND PERIOD = :P_TO_PERIOD;

    FOR
        SELECT ID, AMOUNT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
        FROM
        (
            
            SELECT ENTRY_BALANCES.INCREASE_ENTRY ID, ENTRY_BALANCES.AMOUNT, ENTRY_BALANCES.OFFICIAL_DEBIT, ENTRY_BALANCES.OFFICIAL_CREDIT
            FROM ENTRY_BALANCES
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :P_FROM_PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, DEBIT.AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_DEBIT, 0 OFFICIAL_CREDIT
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND EXISTS (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = DEBIT.ACCOUNT AND BIN_AND(ACCOUNT_TYPES, 1572864) <> 0) 
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, CREDIT.AMOUNT, 0 OFFICIAL_DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_CREDIT
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND EXISTS (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT.ACCOUNT AND BIN_AND(ACCOUNT_TYPES, 393216) <> 0) 
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
        )
        INTO :ID, :INPUT_AMOUNT, :INPUT_OFFICIAL_SUM_OF_MONEY_DEBIT, :INPUT_OFFICIAL_SUM_OF_MONEY_CREDIT
    DO
    BEGIN
        
        
        SELECT SUM(DECREASE_ENTRIES.AMOUNT), SUM(DECREASE_ENTRIES.OFFICIAL_SUM_OF_MONEY)
        FROM DECREASE_ENTRIES
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ID = DECREASE_ENTRIES.CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.INCREASE_ENTRY = :ID
        INTO :OUTPUT_AMOUNT, :OUTPUT_OFFICIAL_SUM_OF_MONEY_DEBIT;

        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        INPUT_AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

        IF(OUTPUT_OFFICIAL_SUM_OF_MONEY_DEBIT IS NULL)THEN OUTPUT_OFFICIAL_SUM_OF_MONEY_DEBIT = 0;
        INPUT_OFFICIAL_SUM_OF_MONEY_DEBIT = INPUT_OFFICIAL_SUM_OF_MONEY_DEBIT - OUTPUT_OFFICIAL_SUM_OF_MONEY_DEBIT;

        SELECT SUM(DECREASE_ENTRIES.AMOUNT), SUM(DECREASE_ENTRIES.OFFICIAL_SUM_OF_MONEY)
        FROM DECREASE_ENTRIES
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ID = DECREASE_ENTRIES.CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.PERIOD = :P_FROM_PERIOD
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.INCREASE_ENTRY = :ID
        INTO :OUTPUT_AMOUNT, :OUTPUT_OFFICIAL_SUM_OF_MONEY_CREDIT;

        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        INPUT_AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

        IF(OUTPUT_OFFICIAL_SUM_OF_MONEY_CREDIT IS NULL)THEN OUTPUT_OFFICIAL_SUM_OF_MONEY_CREDIT = 0;
        INPUT_OFFICIAL_SUM_OF_MONEY_CREDIT = INPUT_OFFICIAL_SUM_OF_MONEY_CREDIT - OUTPUT_OFFICIAL_SUM_OF_MONEY_CREDIT;

        
        IF(INPUT_AMOUNT <> 0 OR INPUT_OFFICIAL_SUM_OF_MONEY_DEBIT <> 0 OR INPUT_OFFICIAL_SUM_OF_MONEY_CREDIT <> 0)THEN
        BEGIN
            UPDATE OR INSERT INTO ENTRY_BALANCES(INCREASE_ENTRY, COMPANY, PERIOD, AMOUNT, OFFICIAL_DEBIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, FOREIGN_CREDIT)
            VALUES(:ID, :P_COMPANY, :P_TO_PERIOD, :INPUT_AMOUNT, :INPUT_OFFICIAL_SUM_OF_MONEY_DEBIT, :INPUT_OFFICIAL_SUM_OF_MONEY_CREDIT, 0, 0);
        END
    END
END ^

ALTER PROCEDURE CMD_UNLOCK (P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
begin
    UPDATE PERIODS
    SET LOCKED = 0
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD;
end ^

ALTER PROCEDURE CMD_UPDATE_PRINTED_COUNTER (P_COMPANY DM_ID,
P_ID DM_ID)
AS 
BEGIN
    UPDATE DOCUMENTS
    SET DOCUMENTS.PRINTED_COUNTER = DOCUMENTS.PRINTED_COUNTER + 1
    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID;
END ^

ALTER PROCEDURE CMD_VAT_DEDUCTION (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAM DM_ID,
P_BEGINNING_DATE_OF_PERIOD DM_DATE,
P_ENDING_DATE_OF_PERIOD DM_DATE,
P_MAIN_CURRENCY DM_ID)
AS 
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE NAME_BEGINNING_ENDING_DATE DM_NAME;
DECLARE VARIABLE VAT_DEDUCTION_CYCLE DM_TIME_TYPE;
DECLARE VARIABLE NAM DM_INTEGER;
DECLARE VARIABLE THANG DM_INTEGER;
BEGIN
    SELECT VAT_DEDUCTION_CYCLE
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :VAT_DEDUCTION_CYCLE;

    
    NAM = EXTRACT(YEAR FROM P_ENDING_DATE_OF_PERIOD);
    THANG = EXTRACT(MONTH FROM P_ENDING_DATE_OF_PERIOD);

    IF(VAT_DEDUCTION_CYCLE = 2 OR (NAM < 2013 OR (NAM = 2013 AND THANG < 7)))THEN
    BEGIN
        FOR
            SELECT BEGINNING_DATE_OF_MONTH, ENDING_DATE_OF_MONTH, NAME_OF_MONTH
            FROM INT_ENDING_DATES_OF_MONTH(:P_BEGINNING_DATE_OF_PERIOD, :P_ENDING_DATE_OF_PERIOD)
            INTO :BEGINNING_DATE, :ENDING_DATE, :NAME_BEGINNING_ENDING_DATE
        DO
        BEGIN
            EXECUTE PROCEDURE CMD_VAT_DEDUCTION_DETAIL(P_LANGUAGE, P_COMPANY, P_PERIOD, P_DOCUMENT_TEAM, BEGINNING_DATE, ENDING_DATE, NAME_BEGINNING_ENDING_DATE, P_MAIN_CURRENCY);
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT BEGINNING_DATE_OF_QUARTER, ENDING_DATE_OF_QUARTER, NAME_OF_QUARTER
            FROM INT_ENDING_DATES_OF_QUARTER(:P_BEGINNING_DATE_OF_PERIOD, :P_ENDING_DATE_OF_PERIOD)
            INTO :BEGINNING_DATE, :ENDING_DATE, :NAME_BEGINNING_ENDING_DATE
        DO
        BEGIN
            EXECUTE PROCEDURE CMD_VAT_DEDUCTION_DETAIL(P_LANGUAGE, P_COMPANY, P_PERIOD, P_DOCUMENT_TEAM, BEGINNING_DATE, ENDING_DATE, NAME_BEGINNING_ENDING_DATE, P_MAIN_CURRENCY);
        END
    END
END ^

ALTER PROCEDURE CMD_VAT_DEDUCTION_DETAIL (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_DOCUMENT_TEAM DM_ID,
P_BEGINNING_DATE DM_DATE,
P_ENDING_DATE DM_DATE,
P_NAME_BEGINNING_ENDING_DATE DM_NAME,
P_MAIN_CURRENCY DM_ID)
AS 
declare variable id_33311 dm_id;
declare variable id_1331 dm_id;
declare variable id_1332 dm_id;
declare variable code_33311 dm_code;
declare variable code_1331 dm_code;
declare variable code_1332 dm_code;
declare variable rising_33311 dm_double;
declare variable rising_debit_33311 dm_double;
declare variable rising_debit_811_33311 dm_double;
declare variable rising_debit_421_33311 dm_double;
declare variable rising_1331 dm_double;
declare variable rising_1332 dm_double;
declare variable document dm_id;
declare variable code dm_code;
declare variable number dm_code;
declare variable content dm_content;
declare variable content_1331 dm_content;
declare variable content_1332 dm_content;
declare variable default_content dm_content;
declare variable default_content_1331 dm_content;
declare variable default_content_1332 dm_content;
declare variable deduction dm_double;
BEGIN
    SELECT CONTENT
    FROM TEXTS
    WHERE ID = -1 AND LANGUAGE = :P_LANGUAGE
    INTO :DEFAULT_CONTENT;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = -5 AND LANGUAGE = :P_LANGUAGE
    INTO :DEFAULT_CONTENT_1331;

    SELECT CONTENT
    FROM TEXTS
    WHERE ID = -10 AND LANGUAGE = :P_LANGUAGE
    INTO :DEFAULT_CONTENT_1332;

    CODE_33311 = '33311';
    CODE_1331 = '1331';
    CODE_1332 = '1332';
    DOCUMENT = NULL;

    SELECT ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :CODE_33311
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    INTO :ID_33311;

    SELECT ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :CODE_1331
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    INTO :ID_1331;

    SELECT ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = :CODE_1332
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    INTO :ID_1332;

        CONTENT = DEFAULT_CONTENT || ' ' || P_NAME_BEGINNING_ENDING_DATE;
        CONTENT_1331 = DEFAULT_CONTENT_1331 || ' ' || P_NAME_BEGINNING_ENDING_DATE;
        CONTENT_1332 = DEFAULT_CONTENT_1332 || ' ' || P_NAME_BEGINNING_ENDING_DATE;

        
        
        SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM DOCUMENTS
        JOIN IS_DIEUCHINHGIAMTHUEGTGT ON IS_DIEUCHINHGIAMTHUEGTGT.DOCUMENT_TYPE = DOCUMENTS.DOCUMENT_TYPE
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT AND DEBIT_ACCOUNTS.ID = :ID_33311
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND (DOCUMENTS.INPUT_DATE BETWEEN :P_BEGINNING_DATE AND :P_ENDING_DATE)
        INTO :RISING_DEBIT_33311;

        IF(RISING_DEBIT_33311 IS NULL)THEN RISING_DEBIT_33311 = 0;

        SELECT sum_of_money
        FROM int_ps_cap_tk_c(:p_company, '811', '33311', :p_beginning_date, :p_ending_date)
        INTO :rising_debit_811_33311;

        SELECT sum_of_money
        FROM int_ps_cap_tk_c(:p_company, '421', '33311', :p_beginning_date, :p_ending_date)
        INTO :rising_debit_421_33311;

        SELECT CREDIT - :RISING_DEBIT_33311 - :rising_debit_811_33311 - :rising_debit_421_33311
        FROM INT_PS_1_TK(:P_COMPANY, :ID_33311, :P_BEGINNING_DATE, :P_ENDING_DATE)
        INTO :RISING_33311;

        IF(RISING_33311 > 0)THEN
        BEGIN
            SELECT DEBIT
            FROM INT_SD_1_TK_CN(:P_COMPANY, :ID_1331, :P_ENDING_DATE)
            INTO :RISING_1331;

            IF(RISING_1331 > 0)THEN
            BEGIN
                DEDUCTION = MINVALUE(RISING_33311, RISING_1331);

                SELECT CODE, NUMBER
                FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :P_DOCUMENT_TEAM, :P_ENDING_DATE)
                INTO :CODE, :NUMBER;

                DOCUMENT = GEN_ID(UNIVERSE, 1);
                EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL, 0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :P_MAIN_CURRENCY, 1, :P_ENDING_DATE, NULL, NULL, :P_PERIOD, :P_DOCUMENT_TEAM, :P_ENDING_DATE, NULL, NULL, NULL, :CONTENT, 0, 0);

                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_MAIN_CURRENCY, :DOCUMENT, 1, NULL, 0, NULL, NULL, :CONTENT_1331, GEN_ID(UNIVERSE, 1), :ID_33311, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :ID_1331, NULL, NULL, NULL, 0, 0, :DEDUCTION, :DEDUCTION);

                RISING_33311 = RISING_33311 - DEDUCTION;
            END
        END

        IF(RISING_33311 > 0)THEN
        BEGIN
            SELECT DEBIT
            FROM INT_SD_1_TK_CN(:P_COMPANY, :ID_1332, :P_ENDING_DATE)
            INTO :RISING_1332;

            IF(RISING_1332 > 0)THEN
            BEGIN
                DEDUCTION = MINVALUE(RISING_33311, RISING_1332);

                IF(DOCUMENT IS NULL)THEN
                BEGIN
                    SELECT CODE, NUMBER
                    FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :P_DOCUMENT_TEAM, :P_ENDING_DATE)
                    INTO :CODE, :NUMBER;

                    DOCUMENT = GEN_ID(UNIVERSE, 1);
                    EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, NULL, 0, NULL,  NULL, NULL, NULL, :CODE, :NUMBER, :P_MAIN_CURRENCY, 1, :P_ENDING_DATE, NULL, NULL, :P_PERIOD, :P_DOCUMENT_TEAM, :P_ENDING_DATE, NULL, NULL, NULL, :CONTENT, 0, 0);
                END
        
                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_MAIN_CURRENCY, :DOCUMENT, 1, NULL, 0, NULL, NULL, :CONTENT_1332, GEN_ID(UNIVERSE, 1), :ID_33311, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :ID_1332, NULL, NULL, NULL, 0, 0, :DEDUCTION, :DEDUCTION);

                RISING_33311 = RISING_33311 - DEDUCTION;
            END
        END
END ^

ALTER PROCEDURE COMPANY_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_ADDRESS DM_ADDRESS,
P_CASHIER DM_PERSON_NAME,
P_CHIEF_ACCOUNTANT DM_PERSON_NAME,
P_DIRECTOR DM_PERSON_NAME,
P_EMAIL DM_EMAIL,
P_FAX DM_FAX,
P_GENERAL_ACCOUNTANT DM_PERSON_NAME,
P_LOGO DM_IMAGE,
P_OWNER_NAME DM_NAME,
P_PAYMENT_ACCOUNTANT DM_PERSON_NAME,
P_PHONE DM_PHONE,
P_SHORT_NAME DM_NAME,
P_SLOGAN DM_SLOGAN,
P_STOREKEEPER DM_PERSON_NAME,
P_TAX_CODE_1 DM_SMALLINT,
P_TAX_CODE_2 DM_SMALLINT,
P_TAX_CODE_3 DM_SMALLINT,
P_TAX_CODE_4 DM_SMALLINT,
P_TAX_CODE_5 DM_SMALLINT,
P_TAX_CODE_6 DM_SMALLINT,
P_TAX_CODE_7 DM_SMALLINT,
P_TAX_CODE_8 DM_SMALLINT,
P_TAX_CODE_9 DM_SMALLINT,
P_TAX_CODE_10 DM_SMALLINT,
P_TAX_CODE_11 DM_SMALLINT,
P_TAX_CODE_12 DM_SMALLINT,
P_TAX_CODE_13 DM_SMALLINT,
P_TRADE_FIELD DM_TRADE_FIELD,
P_TRADE_TYPE DM_TRADE_TYPE,
P_WEBSITE DM_WEBSITE,
P_PREPARED_PERSON DM_PERSON_NAME,
P_DOCUMENT_PERSON DM_PERSON_NAME,
P_CASHIER_CAPTION DM_CAPTION,
P_CHIEF_ACCOUNTANT_CAPTION DM_CAPTION,
P_DIRECTOR_CAPTION DM_CAPTION,
P_GENERAL_ACCOUNTANT_CAPTION DM_CAPTION,
P_STOREKEEPER_CAPTION DM_CAPTION,
P_PAYMENT_ACCOUNTANT_CAPTION DM_CAPTION,
P_PREPARED_PERSON_CAPTION DM_CAPTION,
P_DOCUMENT_PERSON_CAPTION DM_CAPTION,
P_SHOW_NAMES_IN_REPORT DM_SHOW_NAME_IN_REPORT,
P_PREPARED_PERSON_IS_LOGIN_USER DM_BOOL,
P_DOCUMENT_PERSON_IS_LOGIN_USER DM_BOOL,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU_LANGUAGE(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO COMPANIES(ID, COMPANY, LOGO, SHOW_NAMES_IN_REPORT, PREPARED_PERSON_IS_LOGIN_USER, DOCUMENT_PERSON_IS_LOGIN_USER,
    TAX_CODE_1,
    TAX_CODE_2,
    TAX_CODE_3,
    TAX_CODE_4,
    TAX_CODE_5,
    TAX_CODE_6,
    TAX_CODE_7,
    TAX_CODE_8,
    TAX_CODE_9,
    TAX_CODE_10,
    TAX_CODE_11,
    TAX_CODE_12,
    TAX_CODE_13)
    VALUES(:P_ID, :P_COMPANY, :P_LOGO, :P_SHOW_NAMES_IN_REPORT, :P_PREPARED_PERSON_IS_LOGIN_USER, :P_DOCUMENT_PERSON_IS_LOGIN_USER,
    :P_TAX_CODE_1,
    :P_TAX_CODE_2,
    :P_TAX_CODE_3,
    :P_TAX_CODE_4,
    :P_TAX_CODE_5,
    :P_TAX_CODE_6,
    :P_TAX_CODE_7,
    :P_TAX_CODE_8,
    :P_TAX_CODE_9,
    :P_TAX_CODE_10,
    :P_TAX_CODE_11,
    :P_TAX_CODE_12,
    :P_TAX_CODE_13);

    UPDATE OR INSERT INTO COMPANY_STRINGS(ID, LANGUAGE, OWNER_NAME, SHORT_NAME, PHONE, FAX, ADDRESS, TRADE_TYPE, TRADE_FIELD, WEBSITE,
    EMAIL, DIRECTOR, CHIEF_ACCOUNTANT, CASHIER, STOREKEEPER, GENERAL_ACCOUNTANT, PAYMENT_ACCOUNTANT, COMPANY, SLOGAN,
    PREPARED_PERSON, DOCUMENT_PERSON, CASHIER_CAPTION, CHIEF_ACCOUNTANT_CAPTION, DIRECTOR_CAPTION, GENERAL_ACCOUNTANT_CAPTION, STOREKEEPER_CAPTION, PAYMENT_ACCOUNTANT_CAPTION, PREPARED_PERSON_CAPTION, DOCUMENT_PERSON_CAPTION)
    VALUES(:P_ID, :P_LANGUAGE, :P_OWNER_NAME, :P_SHORT_NAME, :P_PHONE, :P_FAX, :P_ADDRESS, :P_TRADE_TYPE, :P_TRADE_FIELD, :P_WEBSITE,
    :P_EMAIL, :P_DIRECTOR, :P_CHIEF_ACCOUNTANT, :P_CASHIER, :P_STOREKEEPER, :P_GENERAL_ACCOUNTANT, :P_PAYMENT_ACCOUNTANT, :P_COMPANY, :P_SLOGAN,
    :P_PREPARED_PERSON, :P_DOCUMENT_PERSON, :P_CASHIER_CAPTION, :P_CHIEF_ACCOUNTANT_CAPTION, :P_DIRECTOR_CAPTION, :P_GENERAL_ACCOUNTANT_CAPTION, :P_STOREKEEPER_CAPTION, :P_PAYMENT_ACCOUNTANT_CAPTION, :P_PREPARED_PERSON_CAPTION, :P_DOCUMENT_PERSON_CAPTION);

    IF(NOT EXISTS (SELECT ID FROM COMPANY_STRINGS WHERE COMPANY_STRINGS.COMPANY = :P_COMPANY AND COMPANY_STRINGS.LANGUAGE = (1 - :P_LANGUAGE) AND COMPANY_STRINGS.ID = :P_ID))THEN
    BEGIN
        UPDATE OR INSERT INTO COMPANY_STRINGS(ID, LANGUAGE, OWNER_NAME, SHORT_NAME, PHONE, FAX, ADDRESS, TRADE_TYPE, TRADE_FIELD, WEBSITE,
        EMAIL, DIRECTOR, CHIEF_ACCOUNTANT, CASHIER, STOREKEEPER, GENERAL_ACCOUNTANT, PAYMENT_ACCOUNTANT, COMPANY, SLOGAN,
        PREPARED_PERSON, DOCUMENT_PERSON, CASHIER_CAPTION, CHIEF_ACCOUNTANT_CAPTION, DIRECTOR_CAPTION, GENERAL_ACCOUNTANT_CAPTION, STOREKEEPER_CAPTION, PAYMENT_ACCOUNTANT_CAPTION, PREPARED_PERSON_CAPTION, DOCUMENT_PERSON_CAPTION)
        VALUES(:P_ID, 1-:P_LANGUAGE, :P_OWNER_NAME, :P_SHORT_NAME, :P_PHONE, :P_FAX, :P_ADDRESS, :P_TRADE_TYPE, :P_TRADE_FIELD, :P_WEBSITE,
        :P_EMAIL, :P_DIRECTOR, :P_CHIEF_ACCOUNTANT, :P_CASHIER, :P_STOREKEEPER, :P_GENERAL_ACCOUNTANT, :P_PAYMENT_ACCOUNTANT, :P_COMPANY, :P_SLOGAN,
        :P_PREPARED_PERSON, :P_DOCUMENT_PERSON, :P_CASHIER_CAPTION, :P_CHIEF_ACCOUNTANT_CAPTION, :P_DIRECTOR_CAPTION, :P_GENERAL_ACCOUNTANT_CAPTION, :P_STOREKEEPER_CAPTION, :P_PAYMENT_ACCOUNTANT_CAPTION, :P_PREPARED_PERSON_CAPTION, :P_DOCUMENT_PERSON_CAPTION);
    END

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE COMPANY_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
OWNER_NAME DM_NAME,
SHORT_NAME DM_NAME,
TAX_CODE_1 DM_SMALLINT,
TAX_CODE_2 DM_SMALLINT,
TAX_CODE_3 DM_SMALLINT,
TAX_CODE_4 DM_SMALLINT,
TAX_CODE_5 DM_SMALLINT,
TAX_CODE_6 DM_SMALLINT,
TAX_CODE_7 DM_SMALLINT,
TAX_CODE_8 DM_SMALLINT,
TAX_CODE_9 DM_SMALLINT,
TAX_CODE_10 DM_SMALLINT,
TAX_CODE_11 DM_SMALLINT,
TAX_CODE_12 DM_SMALLINT,
TAX_CODE_13 DM_SMALLINT,
PHONE DM_PHONE,
FAX DM_FAX,
ADDRESS DM_ADDRESS,
TRADE_TYPE DM_TRADE_TYPE,
TRADE_FIELD DM_TRADE_FIELD,
WEBSITE DM_WEBSITE,
EMAIL DM_EMAIL,
DIRECTOR DM_PERSON_NAME,
CHIEF_ACCOUNTANT DM_PERSON_NAME,
CASHIER DM_PERSON_NAME,
STOREKEEPER DM_PERSON_NAME,
GENERAL_ACCOUNTANT DM_PERSON_NAME,
PAYMENT_ACCOUNTANT DM_PERSON_NAME,
LOGO DM_IMAGE,
SLOGAN DM_SLOGAN,
PREPARED_PERSON DM_PERSON_NAME,
DOCUMENT_PERSON DM_PERSON_NAME,
CASHIER_CAPTION DM_CAPTION,
CHIEF_ACCOUNTANT_CAPTION DM_CAPTION,
DIRECTOR_CAPTION DM_CAPTION,
GENERAL_ACCOUNTANT_CAPTION DM_CAPTION,
STOREKEEPER_CAPTION DM_CAPTION,
PAYMENT_ACCOUNTANT_CAPTION DM_CAPTION,
PREPARED_PERSON_CAPTION DM_CAPTION,
DOCUMENT_PERSON_CAPTION DM_CAPTION,
SHOW_NAMES_IN_REPORT DM_SHOW_NAME_IN_REPORT,
PREPARED_PERSON_IS_LOGIN_USER DM_BOOL,
DOCUMENT_PERSON_IS_LOGIN_USER DM_BOOL)
AS 
BEGIN
    SELECT COMPANIES.ID, ORDINAL, NOTE,
        CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        OWNER_NAME, SHORT_NAME,
        PHONE, FAX,
        ADDRESS, TRADE_TYPE, TRADE_FIELD,
        WEBSITE, EMAIL, DIRECTOR,
        CHIEF_ACCOUNTANT, CASHIER, STOREKEEPER,
        GENERAL_ACCOUNTANT, PAYMENT_ACCOUNTANT, LOGO, SLOGAN,
        PREPARED_PERSON, DOCUMENT_PERSON, CASHIER_CAPTION, CHIEF_ACCOUNTANT_CAPTION, DIRECTOR_CAPTION, GENERAL_ACCOUNTANT_CAPTION, STOREKEEPER_CAPTION, PAYMENT_ACCOUNTANT_CAPTION, PREPARED_PERSON_CAPTION, DOCUMENT_PERSON_CAPTION,
        SHOW_NAMES_IN_REPORT, PREPARED_PERSON_IS_LOGIN_USER, DOCUMENT_PERSON_IS_LOGIN_USER,
        TAX_CODE_1,
        TAX_CODE_2,
        TAX_CODE_3,
        TAX_CODE_4,
        TAX_CODE_5,
        TAX_CODE_6,
        TAX_CODE_7,
        TAX_CODE_8,
        TAX_CODE_9,
        TAX_CODE_10,
        TAX_CODE_11,
        TAX_CODE_12,
        TAX_CODE_13
    FROM COMPANIES
    JOIN COMPANY_STRINGS ON COMPANY_STRINGS.COMPANY = :P_COMPANY and COMPANY_STRINGS.LANGUAGE = :P_LANGUAGE AND COMPANY_STRINGS.ID = COMPANIES.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY and ATOMS.ID = COMPANIES.ID
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE COMPANIES.ID = :P_COMPANY AND COMPANIES.COMPANY = :P_COMPANY
    INTO :ID, :ORDINAL, :NOTE,
        :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :OWNER_NAME, :SHORT_NAME, :PHONE, :FAX,
        :ADDRESS, :TRADE_TYPE, :TRADE_FIELD, :WEBSITE, :EMAIL, :DIRECTOR,
        :CHIEF_ACCOUNTANT, :CASHIER, :STOREKEEPER, :GENERAL_ACCOUNTANT,
        :PAYMENT_ACCOUNTANT, :LOGO, :SLOGAN,
        :PREPARED_PERSON, :DOCUMENT_PERSON, :CASHIER_CAPTION, :CHIEF_ACCOUNTANT_CAPTION, :DIRECTOR_CAPTION, :GENERAL_ACCOUNTANT_CAPTION, :STOREKEEPER_CAPTION, :PAYMENT_ACCOUNTANT_CAPTION, :PREPARED_PERSON_CAPTION, :DOCUMENT_PERSON_CAPTION,
        :SHOW_NAMES_IN_REPORT, :PREPARED_PERSON_IS_LOGIN_USER, :DOCUMENT_PERSON_IS_LOGIN_USER,
        :TAX_CODE_1,
        :TAX_CODE_2,
        :TAX_CODE_3,
        :TAX_CODE_4,
        :TAX_CODE_5,
        :TAX_CODE_6,
        :TAX_CODE_7,
        :TAX_CODE_8,
        :TAX_CODE_9,
        :TAX_CODE_10,
        :TAX_CODE_11,
        :TAX_CODE_12,
        :TAX_CODE_13;

    SUSPEND;
END ^

ALTER PROCEDURE CONTRACT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_SIGNING_CONTRACT_DATE DM_DATE,
P_CONTRACT_SIGNER DM_PERSON_NAME,
P_CONTRACT_SIGNER_TITLE DM_NAME,
P_CURRENCY DM_ID,
P_CONTRACT_VALUE DM_DOUBLE,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO CONTRACTS(COMPANY, ID, SIGNING_CONTRACT_DATE, CONTRACT_SIGNER, CONTRACT_SIGNER_TITLE, CURRENCY, CONTRACT_VALUE)
    VALUES(:P_COMPANY, :P_ID, :P_SIGNING_CONTRACT_DATE, :P_CONTRACT_SIGNER, :P_CONTRACT_SIGNER_TITLE, :P_CURRENCY, :P_CONTRACT_VALUE);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE CONTRACT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
SIGNING_CONTRACT_DATE DM_DATE,
CONTRACT_SIGNER DM_PERSON_NAME,
CONTRACT_SIGNER_TITLE DM_NAME,
CURRENCY DM_ID,
CONTRACT_VALUE DM_DOUBLE,
RELATED_OBJECT DM_ID)
AS 
BEGIN
    FOR
        SELECT CONTRACTS.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        SIGNING_CONTRACT_DATE, CONTRACT_SIGNER, CONTRACT_SIGNER_TITLE, CURRENCY, CONTRACT_VALUE
        FROM CONTRACTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CONTRACTS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE CONTRACTS.COMPANY = :P_COMPANY
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :SIGNING_CONTRACT_DATE, :CONTRACT_SIGNER, :CONTRACT_SIGNER_TITLE, :CURRENCY, :CONTRACT_VALUE
    DO
        SUSPEND;
END ^

ALTER PROCEDURE COPY (P_FROM_COMPANY DM_ID,
P_TO_COMPANY DM_ID,
P_FROM_COMPANY_CODE DM_CODE,
P_TO_COMPANY_CODE DM_CODE,
P_FROM_PERIOD DM_ID,
P_ONLY_DOCUMENTS DM_INTEGER)
AS 
DECLARE VARIABLE FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM;
DECLARE VARIABLE TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM;
DECLARE VARIABLE TO_PERIOD DM_ID;
BEGIN
    
    
    
    
    IF(P_FROM_COMPANY_CODE IS NOT NULL AND P_TO_COMPANY_CODE IS NOT NULL)THEN
    BEGIN
        SELECT COMPANIES.ID
        FROM COMPANIES
        JOIN ATOMS ON ATOMS.COMPANY = COMPANIES.COMPANY AND ATOMS.ID = COMPANIES.ID AND ATOMS.CODE = :P_FROM_COMPANY_CODE
        INTO :P_FROM_COMPANY;

        SELECT COMPANIES.ID
        FROM COMPANIES
        JOIN ATOMS ON ATOMS.COMPANY = COMPANIES.COMPANY AND ATOMS.ID = COMPANIES.ID AND ATOMS.CODE = :P_TO_COMPANY_CODE
        INTO :P_TO_COMPANY;
    END

    SELECT TO_PERIODS.ID
    FROM PERIODS TO_PERIODS
    WHERE TO_PERIODS.COMPANY = :P_TO_COMPANY AND TO_PERIODS.BEGINNING_DATE IN
    (
        SELECT FROM_PERIODS.BEGINNING_DATE
        FROM PERIODS FROM_PERIODS
        WHERE FROM_PERIODS.COMPANY = :P_FROM_COMPANY AND FROM_PERIODS.ID = :P_FROM_PERIOD
    )
    INTO :TO_PERIOD;

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_FROM_COMPANY
    INTO :FROM_ACCOUNTING_SYSTEM;

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_TO_COMPANY
    INTO :TO_ACCOUNTING_SYSTEM;

    IF(P_ONLY_DOCUMENTS = 2)THEN
    BEGIN
        IF(FROM_ACCOUNTING_SYSTEM = TO_ACCOUNTING_SYSTEM)THEN
        BEGIN
            EXECUTE PROCEDURE COPY_ACCOUNTS(:P_FROM_COMPANY, :P_TO_COMPANY);
        END
    END
    ELSE IF(P_ONLY_DOCUMENTS = 3)THEN
    BEGIN
        EXECUTE PROCEDURE COPY_CURRENCIES(:P_FROM_COMPANY, :P_TO_COMPANY);

        EXECUTE PROCEDURE COPY_CUSTOMER_TEAMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_CUSTOMERS(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        EXECUTE PROCEDURE COPY_GOOD_TEAMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_GOODS(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        EXECUTE PROCEDURE COPY_WAREHOUSE_TEAMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_WAREHOUSES(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        
        EXECUTE PROCEDURE COPY_DEPARTMENTS(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        EXECUTE PROCEDURE COPY_ASSET_TEAMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_ASSETS(:P_FROM_COMPANY, :P_TO_COMPANY, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM);
    
        EXECUTE PROCEDURE COPY_PREPAID_EXPENSES(:P_FROM_COMPANY, :P_TO_COMPANY, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM);
    
        EXECUTE PROCEDURE COPY_BANK_ACCOUNTS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_EMPLOYEES(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_PROJECTS(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        EXECUTE PROCEDURE COPY_SERVICE_TEAMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_SERVICES(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        EXECUTE PROCEDURE COPY_EXPENSE_TEAMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_EXPENSES(:P_FROM_COMPANY, :P_TO_COMPANY);
    
        EXECUTE PROCEDURE COPY_WORK_OF_PROJECTS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_LOAN_AGREEMENTS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_AFFAIRS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_WORKSHOPS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_PHASES(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_CONTRACTS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_SOURCE_OF_CAPITALS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_NORMS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_ORDERS(:P_FROM_COMPANY, :P_TO_COMPANY);
        EXECUTE PROCEDURE COPY_PORTFOLIOS(:P_FROM_COMPANY, :P_TO_COMPANY);
    END
    ELSE IF(P_ONLY_DOCUMENTS = 0)THEN
    BEGIN
        EXECUTE PROCEDURE COPY_BEGINNING_ENTRIES(:P_FROM_COMPANY, :P_TO_COMPANY, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM, :P_FROM_PERIOD, :TO_PERIOD);
        EXECUTE PROCEDURE COPY_BEGINNING_DOCUMENTS(:P_FROM_COMPANY, :P_TO_COMPANY, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM, :P_FROM_PERIOD, :TO_PERIOD);
        EXECUTE PROCEDURE COPY_BALANCES(:P_FROM_COMPANY, :P_TO_COMPANY, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM, :P_FROM_PERIOD, :TO_PERIOD);
    END
    ELSE IF(P_ONLY_DOCUMENTS = 1)THEN
        EXECUTE PROCEDURE COPY_DOCUMENTS(:P_FROM_COMPANY, :P_TO_COMPANY, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM, :P_FROM_PERIOD);
END ^

ALTER PROCEDURE COPY_ACCESSORIES (FROM_COMPANY DM_ID,
FROM_ASSET DM_ID,
TO_COMPANY DM_ID,
TO_ASSET DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE UNIT DM_UNIT;
BEGIN
    FOR
        SELECT ID, NOTE, ORDINAL, AMOUNT, SUM_OF_MONEY, NAME, UNIT
        FROM ACCESSORY_S_EC(0, :FROM_COMPANY, :FROM_ASSET)
        INTO :ID, :NOTE, :ORDINAL, :AMOUNT, :SUM_OF_MONEY, :NAME, :UNIT
    DO
    BEGIN
        EXECUTE PROCEDURE ACCESSORY_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :TO_ASSET, :AMOUNT, :SUM_OF_MONEY, :NAME, :UNIT);
    END
END ^

ALTER PROCEDURE COPY_ACCOUNTS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE ENGLISH_NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
DECLARE VARIABLE ATOM_TYPE_0 DM_ID;
DECLARE VARIABLE ATOM_TYPE_1 DM_ID;
DECLARE VARIABLE ATOM_TYPE_2 DM_ID;
DECLARE VARIABLE MUST_HAVE_OBJECT DM_MUST_HAVE_OBJECTS;
DECLARE VARIABLE DEFAULT_OBJECT_0 DM_ID;
DECLARE VARIABLE DEFAULT_OBJECT_1 DM_ID;
DECLARE VARIABLE DEFAULT_OBJECT_2 DM_ID;
DECLARE VARIABLE RELATED_OBJECTS DM_RELATED_OBJECTS;
DECLARE VARIABLE ACCOUNT_TYPES DM_ACCOUNT_TYPES;
DECLARE VARIABLE CASH_ACTION_LEVEL DM_ACTION_LEVEL;
DECLARE VARIABLE INVENTORY_ACTION_LEVEL DM_ACTION_LEVEL;
DECLARE VARIABLE BALANCE_TYPE DM_BALANCE_TYPE;
BEGIN
    OBJECT_TYPE = 10;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, ENGLISH_NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
            ATOM_TYPE_0, ATOM_TYPE_1, ATOM_TYPE_2, MUST_HAVE_OBJECT,
            DEFAULT_OBJECT_0, DEFAULT_OBJECT_1, DEFAULT_OBJECT_2, RELATED_OBJECTS, ACCOUNT_TYPES, CASH_ACTION_LEVEL, INVENTORY_ACTION_LEVEL, BALANCE_TYPE
        FROM ACCOUNT_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT, CODE
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :ENGLISH_NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :ATOM_TYPE_0, :ATOM_TYPE_1, :ATOM_TYPE_2, :MUST_HAVE_OBJECT,
        :DEFAULT_OBJECT_0, :DEFAULT_OBJECT_1, :DEFAULT_OBJECT_2, :RELATED_OBJECTS,
        :ACCOUNT_TYPES, :CASH_ACTION_LEVEL, :INVENTORY_ACTION_LEVEL, :BALANCE_TYPE
    DO
    BEGIN
        IF(EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            UPDATE ACCOUNTS
            SET ATOM_TYPE_0 = :ATOM_TYPE_0,
                ATOM_TYPE_1 = :ATOM_TYPE_1,
                ATOM_TYPE_2 = :ATOM_TYPE_2,
                MUST_HAVE_OBJECT = :MUST_HAVE_OBJECT,
                DEFAULT_OBJECT_0 = :DEFAULT_OBJECT_0,
                DEFAULT_OBJECT_1 = :DEFAULT_OBJECT_1,
                DEFAULT_OBJECT_2 = :DEFAULT_OBJECT_2,
                RELATED_OBJECTS = :RELATED_OBJECTS,
                ACCOUNT_TYPES = :ACCOUNT_TYPES,
                CASH_ACTION_LEVEL = :CASH_ACTION_LEVEL,
                INVENTORY_ACTION_LEVEL = :INVENTORY_ACTION_LEVEL,
                BALANCE_TYPE  = :BALANCE_TYPE
            WHERE ACCOUNTS.COMPANY = :TO_COMPANY AND ACCOUNTS.ID IN
            (
                SELECT ID
                FROM ATOMS
                WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
            );
        END
        ELSE
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            EXECUTE PROCEDURE ACCOUNT_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT,
            :ENGLISH_NAME,
            :ATOM_TYPE_0, :ATOM_TYPE_1, :ATOM_TYPE_2, :MUST_HAVE_OBJECT,
            :DEFAULT_OBJECT_0, :DEFAULT_OBJECT_1, :DEFAULT_OBJECT_2, :RELATED_OBJECTS,
            :ACCOUNT_TYPES, :CASH_ACTION_LEVEL, :INVENTORY_ACTION_LEVEL, :BALANCE_TYPE,
            :OBJECT_TYPE);
        END
    END
END ^

ALTER PROCEDURE COPY_AFFAIRS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
BEGIN
    OBJECT_TYPE = 94;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
        FROM AFFAIR_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            EXECUTE PROCEDURE AFFAIR_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, :OBJECT_TYPE);
        END
    END
END ^

