ALTER PROCEDURE COPY_ASSETS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;
DECLARE VARIABLE FROM_ASSET DM_ID;
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;

DECLARE VARIABLE PLACE_OF_MADE DM_ADDRESS;
DECLARE VARIABLE DEPARTMENT DM_ID;
DECLARE VARIABLE PURPOSE DM_PURPOSE;
DECLARE VARIABLE DATE_OF_RISING DM_DATE;
DECLARE VARIABLE DATE_OF_USING DM_DATE;
DECLARE VARIABLE TOTAL_DEPRECIATION_PERIOD DM_SMALLINT;
DECLARE VARIABLE DEPRECIATION_PERIOD DM_SMALLINT;
DECLARE VARIABLE DEPRECIATION_PERCENT DM_DOUBLE;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER;
DECLARE VARIABLE DEPRECIATION_METHOD DM_DEPRECIATION_METHOD;
DECLARE VARIABLE DEPRECIATION_ACCOUNT DM_ID;
DECLARE VARIABLE ASSET_ACCOUNT DM_ID;
DECLARE VARIABLE EXPENSE_ACCOUNT DM_ID;
DECLARE VARIABLE YEAR_OF_MADE DM_INTEGER;
DECLARE VARIABLE TRANSFER_REPORT DM_TRANSFER_REPORT;
DECLARE VARIABLE DATE_OF_TRANSFER DM_DATE;
DECLARE VARIABLE DATE_OF_SUSPENDED DM_DATE;
DECLARE VARIABLE CAPACITY DM_CAPACITY;
DECLARE VARIABLE SUSPENDED_REASON DM_SUSPENED_REASON;
DECLARE VARIABLE TO_ASSET DM_ID;
BEGIN
    OBJECT_TYPE = 20;

    FOR
        SELECT ID, ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        PLACE_OF_MADE, DEPARTMENT , PURPOSE , DATE_OF_RISING , DATE_OF_USING , TOTAL_DEPRECIATION_PERIOD , DEPRECIATION_PERIOD , DEPRECIATION_PERCENT ,
        DEPRECIATION_TIME_TYPE , BEGINNING_DEPRECIATION_VALUE1 , BEGINNING_DEPRECIATION_VALUE2 , DEPRECIATION_METHOD , DEPRECIATION_ACCOUNT ,
        ASSET_ACCOUNT , EXPENSE_ACCOUNT , YEAR_OF_MADE , TRANSFER_REPORT , DATE_OF_TRANSFER , DATE_OF_SUSPENDED , CAPACITY , SUSPENDED_REASON
        FROM ASSET_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :FROM_ASSET, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :PLACE_OF_MADE, :DEPARTMENT , :PURPOSE , :DATE_OF_RISING , :DATE_OF_USING , :TOTAL_DEPRECIATION_PERIOD , :DEPRECIATION_PERIOD , :DEPRECIATION_PERCENT ,
        :DEPRECIATION_TIME_TYPE , :BEGINNING_DEPRECIATION_VALUE1 , :BEGINNING_DEPRECIATION_VALUE2 , :DEPRECIATION_METHOD , :DEPRECIATION_ACCOUNT ,
        :ASSET_ACCOUNT , :EXPENSE_ACCOUNT , :YEAR_OF_MADE , :TRANSFER_REPORT , :DATE_OF_TRANSFER , :DATE_OF_SUSPENDED , :CAPACITY , :SUSPENDED_REASON
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEPARTMENT)
            INTO :DEPARTMENT;

            SELECT TO_ACCOUNT
            FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :ASSET_ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
            INTO :ASSET_ACCOUNT;

            SELECT TO_ACCOUNT
            FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :DEPRECIATION_ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
            INTO :DEPRECIATION_ACCOUNT;

            SELECT TO_ACCOUNT
            FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :EXPENSE_ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
            INTO :EXPENSE_ACCOUNT;

            TO_ASSET = GEN_ID(UNIVERSE, 1);

            EXECUTE PROCEDURE ASSET_IU(0, :TO_COMPANY, :TO_ASSET, :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT,
            PLACE_OF_MADE, DEPARTMENT , PURPOSE , DATE_OF_RISING , DATE_OF_USING , TOTAL_DEPRECIATION_PERIOD , DEPRECIATION_PERIOD , DEPRECIATION_PERCENT ,
            DEPRECIATION_TIME_TYPE , BEGINNING_DEPRECIATION_VALUE1 , BEGINNING_DEPRECIATION_VALUE2 , DEPRECIATION_METHOD , DEPRECIATION_ACCOUNT ,
            ASSET_ACCOUNT , EXPENSE_ACCOUNT , YEAR_OF_MADE , TRANSFER_REPORT , DATE_OF_TRANSFER , DATE_OF_SUSPENDED , CAPACITY , SUSPENDED_REASON,
            :OBJECT_TYPE);

            EXECUTE PROCEDURE COPY_ACCESSORIES(:FROM_COMPANY, :FROM_ASSET, :TO_COMPANY, :TO_ASSET);
            EXECUTE PROCEDURE COPY_ASSET_DEPRECIATION_PERIODS(:FROM_COMPANY, :FROM_ASSET, :TO_COMPANY, :TO_ASSET);
        END
    END
END ^

