ALTER PROCEDURE COPY_BALANCES (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
FROM_PERIOD DM_ID,
TO_PERIOD DM_ID)
AS 
declare variable note dm_note;
declare variable ordinal dm_integer;
declare variable account dm_id;
declare variable currency dm_id;
declare variable exchange_rate dm_double;
declare variable object0 dm_id;
declare variable object1 dm_id;
declare variable object2 dm_id;
declare variable amount dm_double;
declare variable price dm_double;
declare variable foreign_credit dm_double;
declare variable foreign_debit dm_double;
declare variable official_credit dm_double;
declare variable official_debit dm_double;
declare variable goodsaccount dm_integer;
BEGIN
    delete from balances
    where balances.COMPANY = :TO_COMPANY and balances.PERIOD = :TO_PERIOD;
    
    FOR
        SELECT
            BALANCE_S_ER.NOTE, BALANCE_S_ER.ORDINAL, BALANCE_S_ER.ACCOUNT, BALANCE_S_ER.CURRENCY, BALANCE_S_ER.EXCHANGE_RATE,
            BALANCE_S_ER.OBJECT0, BALANCE_S_ER.OBJECT1, BALANCE_S_ER.OBJECT2, BALANCE_S_ER.AMOUNT, BALANCE_S_ER.PRICE,
            BALANCE_S_ER.FOREIGN_CREDIT, BALANCE_S_ER.FOREIGN_DEBIT, BALANCE_S_ER.OFFICIAL_CREDIT, BALANCE_S_ER.OFFICIAL_DEBIT,
            BIN_AND(ACCOUNT_TYPES, 4096)
        FROM BALANCE_S_ER(0, :FROM_COMPANY, :FROM_PERIOD, NULL)
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :FROM_COMPANY AND ACCOUNTS.ID = BALANCE_S_ER.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :FROM_COMPANY AND ATOMS.ID = BALANCE_S_ER.ACCOUNT AND ATOMS.CODE NOT STARTING WITH '0'
        left join atoms object0 on object0.id = BALANCE_S_ER.OBJECT0 and object0.OBJECT_TYPE = ACCOUNTS.ATOM_TYPE_0
        where BALANCE_S_ER.OBJECT0 is null or object0.id is not null
        INTO
            :NOTE, :ORDINAL, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE,
            :OBJECT0, :OBJECT1, :OBJECT2, :AMOUNT, :PRICE,
            :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT,
            :goodsaccount
    DO
    BEGIN
        IF(goodsaccount = 0)THEN
        BEGIN
            AMOUNT = 0;
            PRICE = 0;
        END

        SELECT TO_ACCOUNT
        FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
        INTO :ACCOUNT;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CURRENCY)
        INTO :CURRENCY;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT0)
        INTO :OBJECT0;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT1)
        INTO :OBJECT1;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT2)
        INTO :OBJECT2;

        
        

        IF(NOT EXISTS(
            SELECT 1
            FROM BALANCES
            WHERE PERIOD = :TO_PERIOD AND
                ACCOUNT = :ACCOUNT AND
                (OBJECT0 =:OBJECT0 OR (OBJECT0 IS NULL AND :OBJECT0 IS NULL)) AND
                (OBJECT1 = :OBJECT1 OR (OBJECT1 IS NULL AND :OBJECT1 IS NULL)) AND
                (OBJECT2 = :OBJECT2 OR (OBJECT2 IS NULL AND :OBJECT2 IS NULL)) AND
                CURRENCY = :CURRENCY AND
                COMPANY = :TO_COMPANY
        ))THEN
            EXECUTE PROCEDURE BALANCE_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :TO_PERIOD, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :AMOUNT, :PRICE, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT);
    END
END ^

ALTER PROCEDURE COPY_BALANCE_TO_BEGINNING_ENTRY (P_COMPANY DM_ID)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE COMPANY DM_ID;
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE LOT_NUMBER DM_CODE;
DECLARE VARIABLE EXPIRY_DATE DM_DATE;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_DEBIT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE FOREIGN_CREDIT DM_DOUBLE;
BEGIN
    FOR
        SELECT GEN_ID(UNIVERSE, 1), BALANCES.COMPANY,  PERIOD, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, OFFICIAL_DEBIT, OFFICIAL_CREDIT, FOREIGN_DEBIT, FOREIGN_CREDIT
        FROM BALANCES
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BALANCES.ACCOUNT AND ATOMS.CODE STARTING WITH '152'
        WHERE BALANCES.COMPANY = :P_COMPANY
        INTO :ID, :COMPANY, :PERIOD, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :AMOUNT, :PRICE, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT, :FOREIGN_DEBIT, :FOREIGN_CREDIT
    DO
    BEGIN
        IF
        (
            NOT EXISTS(SELECT * FROM BEGINNING_ENTRIES WHERE BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND ACCOUNT = :ACCOUNT AND OBJECT0 =:OBJECT0 AND OBJECT1 = :OBJECT1)
        )THEN
        EXECUTE PROCEDURE BEGINNING_ENTRY_IU(0, :COMPANY, :ID, NULL, 0, :PERIOD, '1/1/2008', '1', NULL, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, NULL, NULL, :AMOUNT, :PRICE, :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT);
    END
END ^

ALTER PROCEDURE COPY_BANK_ACCOUNTS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
DECLARE VARIABLE BANK_NAME DM_NAME;
DECLARE VARIABLE BRANCH_NAME DM_NAME;
BEGIN
    OBJECT_TYPE = 40;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, BANK_NAME, BRANCH_NAME
        FROM BANK_ACCOUNT_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :BANK_NAME, :BRANCH_NAME
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            EXECUTE PROCEDURE BANK_ACCOUNT_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, :BANK_NAME, :BRANCH_NAME, :OBJECT_TYPE);
        END
    END
END ^

ALTER PROCEDURE COPY_BANK_ACCOUNTS_EXTERNAL (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
CONNECTION DM_FILE_NAME)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
DECLARE VARIABLE BANK_NAME DM_NAME;
DECLARE VARIABLE BRANCH_NAME DM_NAME;
BEGIN
    OBJECT_TYPE = 40;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, BANK_NAME, BRANCH_NAME
        FROM BANK_ACCOUNT_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :BANK_NAME, :BRANCH_NAME
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT ID
            FROM COPY_CHECK_EXISTS_EXTERNAL(:TO_COMPANY, :OBJECT_TYPE, :CODE, :CONNECTION)
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :PARENT, :CONNECTION)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :TEAM, :CONNECTION)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT, :CONNECTION)
            INTO :RELATED_OBJECT;

            EXECUTE STATEMENT ('EXECUTE PROCEDURE BANK_ACCOUNT_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, :BANK_NAME, :BRANCH_NAME, :OBJECT_TYPE)')
            (TO_COMPANY:=:TO_COMPANY, NOTE:=:NOTE, ORDINAL:=:ORDINAL, CODE:=:CODE, HIDE:=:HIDE, NAME:=:NAME, PARENT:=:PARENT, TEAM:=:TEAM, RELATED_OBJECT:=:RELATED_OBJECT, BANK_NAME:=:BANK_NAME, BRANCH_NAME:=:BRANCH_NAME, OBJECT_TYPE:=:OBJECT_TYPE)
            ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey';
        END
    END
END ^

ALTER PROCEDURE COPY_BEGINNING_DOCUMENTS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
FROM_PERIOD DM_ID,
TO_PERIOD DM_ID)
AS 
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE INPUT_DATE DM_DATE;
DECLARE VARIABLE CODE DM_DOCUMENT_CODE;
DECLARE VARIABLE CONTENT DM_CONTENT;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_DEBIT DM_DOUBLE;
BEGIN
    FOR
        SELECT
            BEGINNING_DOCUMENT_S_ER.NOTE, BEGINNING_DOCUMENT_S_ER.ORDINAL, BEGINNING_DOCUMENT_S_ER.INPUT_DATE, BEGINNING_DOCUMENT_S_ER.CODE, BEGINNING_DOCUMENT_S_ER.CONTENT, BEGINNING_DOCUMENT_S_ER.ACCOUNT, BEGINNING_DOCUMENT_S_ER.CURRENCY, BEGINNING_DOCUMENT_S_ER.EXCHANGE_RATE, BEGINNING_DOCUMENT_S_ER.OBJECT0, BEGINNING_DOCUMENT_S_ER.OBJECT1, BEGINNING_DOCUMENT_S_ER.OBJECT2,
            BEGINNING_DOCUMENT_S_ER.FOREIGN_CREDIT, BEGINNING_DOCUMENT_S_ER.FOREIGN_DEBIT, BEGINNING_DOCUMENT_S_ER.OFFICIAL_CREDIT, OFFICIAL_DEBIT
        FROM BEGINNING_DOCUMENT_S_ER(0, :FROM_COMPANY, :FROM_PERIOD, NULL)
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :FROM_COMPANY AND ACCOUNTS.ID = BEGINNING_DOCUMENT_S_ER.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :FROM_COMPANY AND ATOMS.ID = BEGINNING_DOCUMENT_S_ER.ACCOUNT AND ATOMS.CODE NOT STARTING WITH '0'
        INTO
            :NOTE, :ORDINAL, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2,
            :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT
    DO
    BEGIN
        SELECT TO_ACCOUNT
        FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
        INTO :ACCOUNT;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CURRENCY)
        INTO :CURRENCY;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT0)
        INTO :OBJECT0;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT1)
        INTO :OBJECT1;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT2)
        INTO :OBJECT2;

        IF(NOT EXISTS(
            SELECT 1
            FROM BEGINNING_DOCUMENTS
            WHERE
                INPUT_DATE = :INPUT_DATE AND
                CODE = :CODE AND
                PERIOD = :TO_PERIOD AND
                ACCOUNT = :ACCOUNT AND
                (OBJECT0 =:OBJECT0 OR OBJECT0 IS NULL) AND
                (OBJECT1 = :OBJECT1 OR OBJECT1 IS NULL) AND
                (OBJECT2 = :OBJECT2 OR OBJECT2 IS NULL) AND
                CURRENCY = :CURRENCY AND
                COMPANY = :TO_COMPANY
        ))THEN
            EXECUTE PROCEDURE BEGINNING_DOCUMENT_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :TO_PERIOD, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT);
    END
END ^

ALTER PROCEDURE COPY_BEGINNING_ENTRIES (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
FROM_PERIOD DM_ID,
TO_PERIOD DM_ID)
AS 
declare variable increase_entry dm_id;
declare variable note dm_note;
declare variable ordinal dm_integer;
declare variable input_date dm_date;
declare variable code dm_document_code;
declare variable content dm_content;
declare variable account dm_id;
declare variable currency dm_id;
declare variable exchange_rate dm_double;
declare variable object0 dm_id;
declare variable object1 dm_id;
declare variable object2 dm_id;
declare variable lot_number dm_code;
declare variable expiry_date dm_date;
declare variable amount dm_double;
declare variable price dm_double;
declare variable foreign_credit dm_double;
declare variable foreign_debit dm_double;
declare variable official_credit dm_double;
declare variable official_debit dm_double;
BEGIN
    FOR
        SELECT ENTRY_BALANCES.INCREASE_ENTRY, ENTRY_BALANCES.AMOUNT, ENTRY_BALANCES.FOREIGN_DEBIT, ENTRY_BALANCES.FOREIGN_CREDIT, ENTRY_BALANCES.OFFICIAL_DEBIT, ENTRY_BALANCES.OFFICIAL_CREDIT
        FROM ENTRY_BALANCES
        WHERE ENTRY_BALANCES.COMPANY = :FROM_COMPANY AND ENTRY_BALANCES.PERIOD = :FROM_PERIOD
        INTO :INCREASE_ENTRY, :AMOUNT, :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT
    DO
    BEGIN
        IF(EXISTS(
            SELECT ID
            FROM BEGINNING_ENTRIES
            WHERE BEGINNING_ENTRIES.COMPANY = :FROM_COMPANY AND BEGINNING_ENTRIES.ID = :INCREASE_ENTRY
        ))THEN
        BEGIN
            SELECT NOTE, ORDINAL, INPUT_DATE, BEGINNING_ENTRIES.CODE, ENTRY_BASE_STRINGS.CONTENT, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, LOT_NUMBER, EXPIRY_DATE,
            BEGINNING_ENTRIES.PRICE
            FROM BEGINNING_ENTRIES
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :FROM_COMPANY AND ENTRY_BASES.ID = BEGINNING_ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :FROM_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = 0
            JOIN ATOMS ON ATOMS.COMPANY = :FROM_COMPANY AND ATOMS.ID = BEGINNING_ENTRIES.ACCOUNT
            WHERE BEGINNING_ENTRIES.COMPANY = :FROM_COMPANY AND BEGINNING_ENTRIES.ID = :INCREASE_ENTRY
            INTO :NOTE, :ORDINAL, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :LOT_NUMBER, :EXPIRY_DATE,
                :PRICE;
        END
        ELSE
        BEGIN
            SELECT ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, ENTRY_BASE_STRINGS.CONTENT,
                DEBIT.ACCOUNT, ENTRIES.CURRENCY, ENTRIES.EXCHANGE_RATE, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.OBJECT2, LOT_NUMBER, EXPIRY_DATE,
                DEBIT.PRICE
            FROM ENTRIES
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :FROM_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :FROM_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = 0 AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :FROM_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :FROM_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
            WHERE ENTRIES.COMPANY = :FROM_COMPANY AND ENTRIES.ID = :INCREASE_ENTRY
            INTO :NOTE, :ORDINAL, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :LOT_NUMBER, :EXPIRY_DATE,
                :PRICE;
        END

        SELECT TO_ACCOUNT
        FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
        INTO :ACCOUNT;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CURRENCY)
        INTO :CURRENCY;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT0)
        INTO :OBJECT0;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT1)
        INTO :OBJECT1;

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :OBJECT2)
        INTO :OBJECT2;

        IF(NOT EXISTS(
            SELECT 1
            FROM BEGINNING_ENTRIES
            WHERE
                INPUT_DATE = :INPUT_DATE AND
                CODE = :CODE AND
                PERIOD = :TO_PERIOD AND
                ACCOUNT = :ACCOUNT AND
                (OBJECT0 =:OBJECT0 OR OBJECT0 IS NULL) AND
                (OBJECT1 = :OBJECT1 OR OBJECT1 IS NULL) AND
                (OBJECT2 = :OBJECT2 OR OBJECT2 IS NULL) AND
                CURRENCY = :CURRENCY AND
                COMPANY = :TO_COMPANY
        ))THEN
            EXECUTE PROCEDURE BEGINNING_ENTRY_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :TO_PERIOD, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :LOT_NUMBER, :EXPIRY_DATE, :AMOUNT, :PRICE, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT);
    END
END ^

ALTER PROCEDURE COPY_BEGINNING_ENTRIES_EX (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
P_CONNECTION DM_FILE_NAME)
AS 
DECLARE VARIABLE FROM_BEGINNING_PERIOD DM_ID;
DECLARE VARIABLE TO_BEGINNING_PERIOD DM_ID;

DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE INPUT_DATE DM_DATE;
DECLARE VARIABLE CODE DM_DOCUMENT_CODE;
DECLARE VARIABLE CONTENT DM_CONTENT;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE EXCHANGE_RATE DM_DOUBLE;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE LOT_NUMBER DM_CODE;
DECLARE VARIABLE EXPIRY_DATE DM_DATE;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE FOREIGN_CREDIT DM_DOUBLE;
DECLARE VARIABLE FOREIGN_DEBIT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_CREDIT DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_DEBIT DM_DOUBLE;
BEGIN
    P_CONNECTION = 'localhost:' || :P_CONNECTION;

    SELECT ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :FROM_COMPANY
    INTO :FROM_BEGINNING_PERIOD;

    EXECUTE STATEMENT (
        'SELECT ACCOUNTING_SETTINGS.BEGINNING_PERIOD
        FROM ACCOUNTING_SETTINGS
        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_TO_COMPANY_ID')
        (P_TO_COMPANY_ID:=:TO_COMPANY)
    ON EXTERNAL DATA SOURCE :P_CONNECTION AS USER 'sysdba' PASSWORD 'masterkey'
    INTO :TO_BEGINNING_PERIOD;

    FOR
        SELECT
            NOTE, ORDINAL, INPUT_DATE, CODE, CONTENT, ACCOUNT, CURRENCY, EXCHANGE_RATE, OBJECT0, OBJECT1, OBJECT2, LOT_NUMBER, EXPIRY_DATE,
            AMOUNT, PRICE, FOREIGN_CREDIT, FOREIGN_DEBIT, OFFICIAL_CREDIT, OFFICIAL_DEBIT
        FROM BEGINNING_ENTRY_S_ER(0, :FROM_COMPANY, :FROM_BEGINNING_PERIOD, NULL)
        INTO
            :NOTE, :ORDINAL, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :LOT_NUMBER, :EXPIRY_DATE,
            :AMOUNT, :PRICE, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT
    DO
    BEGIN
        SELECT TO_ID
        FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :ACCOUNT, :P_CONNECTION)
        INTO :ACCOUNT;

        SELECT TO_ID
        FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :CURRENCY, :P_CONNECTION)
        INTO :CURRENCY;

        SELECT TO_ID
        FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :OBJECT0, :P_CONNECTION)
        INTO :OBJECT0;

        SELECT TO_ID
        FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :OBJECT1, :P_CONNECTION)
        INTO :OBJECT1;

        SELECT TO_ID
        FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :OBJECT2, :P_CONNECTION)
        INTO :OBJECT2;

        EXECUTE STATEMENT
        ('EXECUTE PROCEDURE BEGINNING_ENTRY_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), null, 0, :TO_BEGINNING_PERIOD, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :LOT_NUMBER, :EXPIRY_DATE, :AMOUNT, :PRICE, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT);')
        (TO_COMPANY:=:TO_COMPANY,
        TO_BEGINNING_PERIOD:=:TO_BEGINNING_PERIOD,
        INPUT_DATE:=:INPUT_DATE,
        CODE:=:CODE,
        CONTENT:=:CONTENT,
        ACCOUNT:=:ACCOUNT,
        CURRENCY:=:CURRENCY,
        EXCHANGE_RATE:=:EXCHANGE_RATE,
        OBJECT0:=:OBJECT0,
        OBJECT1:=:OBJECT1,
        OBJECT2:=:OBJECT2,
        LOT_NUMBER:=:LOT_NUMBER,
        EXPIRY_DATE:=:EXPIRY_DATE,
        AMOUNT:=:AMOUNT,
        PRICE:=:PRICE,
        FOREIGN_CREDIT:=:FOREIGN_CREDIT,
        FOREIGN_DEBIT:=:FOREIGN_DEBIT,
        OFFICIAL_CREDIT:=:OFFICIAL_CREDIT,
        OFFICIAL_DEBIT:=:OFFICIAL_DEBIT
        )
        ON EXTERNAL DATA SOURCE :P_CONNECTION AS USER 'sysdba' PASSWORD 'masterkey';

        IF(NOT EXISTS(
            SELECT 1
            FROM BEGINNING_ENTRIES
            WHERE
                INPUT_DATE = :INPUT_DATE AND
                CODE = :CODE AND
                PERIOD = :TO_BEGINNING_PERIOD AND
                ACCOUNT = :ACCOUNT AND
                (OBJECT0 =:OBJECT0 OR OBJECT0 IS NULL) AND
                (OBJECT1 = :OBJECT1 OR OBJECT1 IS NULL) AND
                (OBJECT2 = :OBJECT2 OR OBJECT2 IS NULL) AND
                CURRENCY = :CURRENCY AND
                COMPANY = :TO_COMPANY
        ))THEN
            EXECUTE PROCEDURE BEGINNING_ENTRY_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :TO_BEGINNING_PERIOD, :INPUT_DATE, :CODE, :CONTENT, :ACCOUNT, :CURRENCY, :EXCHANGE_RATE, :OBJECT0, :OBJECT1, :OBJECT2, :LOT_NUMBER, :EXPIRY_DATE, :AMOUNT, :PRICE, :FOREIGN_CREDIT, :FOREIGN_DEBIT, :OFFICIAL_CREDIT, :OFFICIAL_DEBIT);
    END
END ^

ALTER PROCEDURE COPY_CHECK_EXISTS_EXTERNAL (COMPANY DM_ID,
OBJECT_TYPE DM_ID,
CODE DM_CODE,
CONNECTION DM_FILE_NAME)
RETURNS (ID DM_ID)
AS 
BEGIN
    FOR
        EXECUTE STATEMENT
            ('SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :COMPANY AND ATOMS.CODE = :CODE')
            (OBJECT_TYPE:=:OBJECT_TYPE, COMPANY:=:COMPANY, CODE:=:CODE)
        ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey'
        INTO :ID
    DO
    BEGIN
        SUSPEND;
    END
END ^

ALTER PROCEDURE COPY_CONTRACTS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;

DECLARE VARIABLE SIGNING_CONTRACT_DATE DM_DATE;
DECLARE VARIABLE CONTRACT_SIGNER DM_PERSON_NAME;
DECLARE VARIABLE CONTRACT_SIGNER_TITLE DM_NAME;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE CONTRACT_VALUE DM_DOUBLE;
BEGIN
    OBJECT_TYPE = 72;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        SIGNING_CONTRACT_DATE, CONTRACT_SIGNER, CONTRACT_SIGNER_TITLE, CURRENCY, CONTRACT_VALUE
        FROM CONTRACT_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :SIGNING_CONTRACT_DATE, :CONTRACT_SIGNER, :CONTRACT_SIGNER_TITLE, :CURRENCY, :CONTRACT_VALUE
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            EXECUTE PROCEDURE CONTRACT_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, SIGNING_CONTRACT_DATE, CONTRACT_SIGNER, CONTRACT_SIGNER_TITLE, CURRENCY, CONTRACT_VALUE, :OBJECT_TYPE);
        END
    END
END ^

ALTER PROCEDURE COPY_CONTRACTS_EXTERNAL (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
CONNECTION DM_FILE_NAME)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;

DECLARE VARIABLE SIGNING_CONTRACT_DATE DM_DATE;
DECLARE VARIABLE CONTRACT_SIGNER DM_PERSON_NAME;
DECLARE VARIABLE CONTRACT_SIGNER_TITLE DM_NAME;
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE CONTRACT_VALUE DM_DOUBLE;
BEGIN
    OBJECT_TYPE = 72;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        SIGNING_CONTRACT_DATE, CONTRACT_SIGNER, CONTRACT_SIGNER_TITLE, CURRENCY, CONTRACT_VALUE
        FROM CONTRACT_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :SIGNING_CONTRACT_DATE, :CONTRACT_SIGNER, :CONTRACT_SIGNER_TITLE, :CURRENCY, :CONTRACT_VALUE
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT ID
            FROM COPY_CHECK_EXISTS_EXTERNAL(:TO_COMPANY, :OBJECT_TYPE, :CODE, :CONNECTION)
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :PARENT, :CONNECTION)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :TEAM, :CONNECTION)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT, :CONNECTION)
            INTO :RELATED_OBJECT;

            SELECT TO_ID
            FROM COPY_SEARCH_EXTERNAL(:FROM_COMPANY, :TO_COMPANY, :CURRENCY, :CONNECTION)
            INTO :CURRENCY;

            EXECUTE STATEMENT ('EXECUTE PROCEDURE CONTRACT_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, :SIGNING_CONTRACT_DATE, :CONTRACT_SIGNER, :CONTRACT_SIGNER_TITLE, :CURRENCY, :CONTRACT_VALUE, :OBJECT_TYPE)')
            (TO_COMPANY:=:TO_COMPANY, NOTE:=:NOTE, ORDINAL:=:ORDINAL, CODE:=:CODE, HIDE:=:HIDE, NAME:=:NAME, PARENT:=:PARENT, TEAM:=:TEAM, RELATED_OBJECT:=:RELATED_OBJECT, SIGNING_CONTRACT_DATE:=:SIGNING_CONTRACT_DATE, CONTRACT_SIGNER:=:CONTRACT_SIGNER, CONTRACT_SIGNER_TITLE:=:CONTRACT_SIGNER_TITLE, CURRENCY:=:CURRENCY, CONTRACT_VALUE:=:CONTRACT_VALUE, OBJECT_TYPE:=:OBJECT_TYPE)
            ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey';
        END
    END
END ^

ALTER PROCEDURE COPY_CONVERT_ACCOUNT (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNT DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM)
RETURNS (TO_ACCOUNT DM_ID,
ATOM_TYPE_0 DM_ID,
ATOM_TYPE_1 DM_ID,
ATOM_TYPE_2 DM_ID)
AS 
BEGIN
    SELECT TO_ACCOUNT, ACCOUNTS.atom_type_0, ACCOUNTS.atom_type_1, ACCOUNTS.atom_type_2
    FROM ACCOUNT_TO_ACCOUNT
    JOIN ACCOUNTS ON ACCOUNTS.company = :to_company AND ACCOUNTS.ID = ACCOUNT_TO_ACCOUNT.TO_ACCOUNT
    WHERE ACCOUNT_TO_ACCOUNT.FROM_COMPANY = :FROM_COMPANY AND ACCOUNT_TO_ACCOUNT.FROM_ACCOUNT = :FROM_ACCOUNT AND
        ACCOUNT_TO_ACCOUNT.TO_COMPANY = :TO_COMPANY
    INTO :TO_ACCOUNT, :atom_type_0, :atom_type_1, :atom_type_2;

    SUSPEND;
END ^

ALTER PROCEDURE COPY_CONVERT_ACCOUNT15TO200 (FROM_CODE DM_CODE)
RETURNS (TO_CODE DM_CODE)
AS 
BEGIN
    IF(FROM_CODE STARTING WITH '000')THEN
        TO_CODE = '000';
    ELSE TO_CODE = FROM_CODE;

    SUSPEND;
END ^

ALTER PROCEDURE COPY_CONVERT_ACCOUNT15TO48 (FROM_CODE DM_CODE)
RETURNS (TO_CODE DM_CODE)
