        INTO :NOTE,
                :ORDINAL,
                :CODE ,
                :HIDE ,
                :NAME ,
                :PARENT ,
                :TEAM ,
                :RELATED_OBJECT,
                :ADDRESS ,
                :TAX_CODE,
