                :TEAM ,
                :RELATED_OBJECT ,
                :ADDRESS ,
                :TAX_CODE ,
                :PHONE ,
                :FAX ,
                :EMAIL ,
                :WEBSITE ,
                :DIRECTOR ,
                :CHIEF_ACCOUNTANT ,
                :BANK_ACCOUNT ,
                :BANK_NAME ,
                :BANK_PROVINCE ,
                :OBJECT_TYPE);
       END
    END
END ^

