DECLARE VARIABLE DOCUMENT_TYPE DM_DOCUMENT_TYPES;
DECLARE VARIABLE PRINTED_COUNTER DM_INTEGER;
DECLARE VARIABLE NEW_DOCUMENT_ID DM_ID;
DECLARE VARIABLE NEW_PERIOD DM_ID;
DECLARE VARIABLE VAT_PERCENT DM_DOUBLE;
DECLARE VARIABLE APPORTION DM_APPORTION;
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT2 DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT1 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT2 DM_ID;
DECLARE VARIABLE LOT_NUMBER DM_CODE;
DECLARE VARIABLE EXPIRY_DATE DM_DATE;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SIDE DM_SIDE;
DECLARE VARIABLE CUSTOMER_NAME DM_NAME;
DECLARE VARIABLE CUSTOMER_ADDRESS DM_ADDRESS;
DECLARE VARIABLE CUSTOMER_TAX_CODE DM_TAX_CODE;
DECLARE VARIABLE GOODS DM_GOODS;
DECLARE VARIABLE INVOICE_CODE DM_INVOICE_CODE;
DECLARE VARIABLE INVOICE_DATE DM_DATE;
DECLARE VARIABLE INVOICE_TEMPLATE DM_INVOICE_TEMPLATE;
DECLARE VARIABLE CODE_TEMPLATE DM_INVOICE_TEMPLATE;
DECLARE VARIABLE INVOICE_TYPE DM_INVOICE_TYPE;
DECLARE VARIABLE SERIAL_CODE DM_SERIAL_CODE;
DECLARE VARIABLE SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_OF_TAX DM_DOUBLE;
DECLARE VARIABLE FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT;
DECLARE VARIABLE BANK_ACCOUNT DM_NAME;
DECLARE VARIABLE BUYER_NAME DM_NAME;
DECLARE VARIABLE UNIT DM_UNIT;
DECLARE VARIABLE EXTRA_GOODS DM_DESCRIPTION;
DECLARE VARIABLE EXTRA_MONEY DM_DOUBLE;
DECLARE VARIABLE FROM_DATE DM_DATE;
BEGIN
    SELECT PERIODS.BEGINNING_DATE
    FROM PERIODS
    WHERE ID = :FROM_PERIOD
    INTO :FROM_DATE;

    delete from DOCUMENT_BASES where id in
    (
        select documents.ID
        from DOCUMENTS
        where DOCUMENTS.COMPANY = :TO_COMPANY and documents.INPUT_DATE >= :from_date
    );
    
    FOR
        SELECT ID
        FROM DOCUMENTS
        WHERE DOCUMENTS.COMPANY = :FROM_COMPANY AND DOCUMENTS.INPUT_DATE >= :FROM_DATE
        INTO :ID
    DO
    BEGIN
        SELECT DOCUMENT_S_ER_ID.ID, ORDINAL, NOTE, DOCUMENT_S_ER_ID.CODE, DOCUMENT_S_ER_ID.NUMBER, DOCUMENT_S_ER_ID.TEAM, ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, DOCUMENT_S_ER_ID.INPUT_DATE, OBJECT, DOCUMENT_S_ER_ID.EMPLOYEE, DOCUMENT_S_ER_ID.ORIGINAL_VOUCHERS, DOCUMENT_S_ER_ID.VOUCHER_DATE, CURRENCY, EXCHANGE_RATE, PERSON_NAME, PERSON_ADDRESS, CONTENT, DOCUMENT_S_ER_ID.DOCUMENT_SUM, DOCUMENT_TYPE, PRINTED_COUNTER
        FROM DOCUMENT_S_ER_ID(0, :FROM_COMPANY, :ID)
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NUMBER, :TEAM, :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :INPUT_DATE, :OBJECT, :EMPLOYEE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE, :CURRENCY, :EXCHANGE_RATE, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT, :DOCUMENT_SUM, :DOCUMENT_TYPE, :PRINTED_COUNTER;

        NEW_DOCUMENT_ID = GEN_ID(UNIVERSE, 1);

        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
        INTO :TEAM;
        
        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CURRENCY)
        INTO :CURRENCY;
        
        SELECT TO_ID
        FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :EMPLOYEE)
        INTO :EMPLOYEE;

        NEW_PERIOD = NULL;
        SELECT ID
        FROM PERIODS
        WHERE PERIODS.COMPANY = :TO_COMPANY AND :INPUT_DATE BETWEEN PERIODS.BEGINNING_DATE AND PERIODS.ENDING_DATE
        INTO :NEW_PERIOD;

        IF(NEW_PERIOD IS NOT NULL)THEN
        BEGIN
            EXECUTE PROCEDURE DOCUMENT_IU(0, :TO_COMPANY, :NEW_DOCUMENT_ID, :NOTE, :ORDINAL, :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :CODE, :NUMBER, :CURRENCY, :EXCHANGE_RATE, :INPUT_DATE, :OBJECT, :ORIGINAL_VOUCHERS, :NEW_PERIOD, :TEAM, :VOUCHER_DATE, :EMPLOYEE, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT, :DOCUMENT_SUM, :DOCUMENT_TYPE);

            
            UPDATE DOCUMENTS
            SET DOCUMENTS.PRINTED_COUNTER = :PRINTED_COUNTER
            WHERE DOCUMENTS.ID = :NEW_DOCUMENT_ID AND DOCUMENTS.COMPANY = :TO_COMPANY;


            FOR
                SELECT NOTE, ORDINAL, CURRENCY, EXCHANGE_RATE, VAT_PERCENT, APPORTION, CONTENT, DEBIT_ACCOUNT, DEBIT_OBJECT0, DEBIT_OBJECT1, DEBIT_OBJECT2, CREDIT_ACCOUNT, CREDIT_OBJECT0, CREDIT_OBJECT1, CREDIT_OBJECT2, LOT_NUMBER, EXPIRY_DATE, AMOUNT, PRICE, FOREIGN_SUM_OF_MONEY, OFFICIAL_SUM_OF_MONEY
                FROM DOUBLE_ENTRY_S_EC(0, :FROM_COMPANY, :ID)
                JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :FROM_COMPANY AND DEBIT_ATOMS.ID = DOUBLE_ENTRY_S_EC.DEBIT_ACCOUNT AND DEBIT_ATOMS.CODE NOT STARTING WITH '0'
                JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :FROM_COMPANY AND CREDIT_ATOMS.ID = DOUBLE_ENTRY_S_EC.CREDIT_ACCOUNT AND CREDIT_ATOMS.CODE NOT STARTING WITH '0'
                INTO :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, :APPORTION, :CONTENT, :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2, :CREDIT_ACCOUNT, :CREDIT_OBJECT0, :CREDIT_OBJECT1, :CREDIT_OBJECT2, :LOT_NUMBER, :EXPIRY_DATE, :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY
            DO
            BEGIN
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CURRENCY)
                INTO :CURRENCY;
    
                SELECT TO_ACCOUNT
                FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :DEBIT_ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
                INTO :DEBIT_ACCOUNT;
    
                SELECT TO_ACCOUNT
                FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :CREDIT_ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
                INTO :CREDIT_ACCOUNT;
    
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEBIT_OBJECT0)
                INTO :DEBIT_OBJECT0;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEBIT_OBJECT1)
                INTO :DEBIT_OBJECT1;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEBIT_OBJECT2)
                INTO :DEBIT_OBJECT2;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CREDIT_OBJECT0)
                INTO :CREDIT_OBJECT0;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CREDIT_OBJECT1)
                INTO :CREDIT_OBJECT1;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CREDIT_OBJECT2)
                INTO :CREDIT_OBJECT2;
    
                EXECUTE PROCEDURE DOUBLE_ENTRY_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CURRENCY, :NEW_DOCUMENT_ID, :EXCHANGE_RATE, :VAT_PERCENT, :APPORTION, :LOT_NUMBER, :EXPIRY_DATE, :CONTENT, GEN_ID(UNIVERSE, 1), :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2, GEN_ID(UNIVERSE, 1), :CREDIT_ACCOUNT, :CREDIT_OBJECT0, :CREDIT_OBJECT1, :CREDIT_OBJECT2, :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY);
            END
    
            FOR
                SELECT NOTE, ORDINAL, CURRENCY, EXCHANGE_RATE, CONTENT, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, FOREIGN_SUM_OF_MONEY, OFFICIAL_SUM_OF_MONEY, SIDE
                FROM SINGLE_ENTRY_S_EC(0, :FROM_COMPANY, :ID)
                JOIN ATOMS ON ATOMS.COMPANY = :FROM_COMPANY AND ATOMS.ID = SINGLE_ENTRY_S_EC.ACCOUNT AND ATOMS.CODE NOT STARTING WITH '0'
                INTO :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :CONTENT, :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2, :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY, :SIDE
            DO
            BEGIN
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :CURRENCY)
                INTO :CURRENCY;
    
                SELECT TO_ACCOUNT
                FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :DEBIT_ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
                INTO :DEBIT_ACCOUNT;
    
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEBIT_OBJECT0)
                INTO :DEBIT_OBJECT0;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEBIT_OBJECT1)
                INTO :DEBIT_OBJECT1;
                
                SELECT TO_ID
                FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :DEBIT_OBJECT2)
                INTO :DEBIT_OBJECT2;
                
                EXECUTE PROCEDURE SINGLE_ENTRY_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CURRENCY, :NEW_DOCUMENT_ID, :EXCHANGE_RATE, :CONTENT, GEN_ID(UNIVERSE, 1), :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2, :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY, :SIDE);
            END
    
            FOR
                SELECT NOTE, ORDINAL, CUSTOMER_NAME, CUSTOMER_ADDRESS, CUSTOMER_TAX_CODE, GOODS, INPUT_DATE, INVOICE_CODE, INVOICE_DATE, INVOICE_TEMPLATE, CODE_TEMPLATE, INVOICE_TYPE, SERIAL_CODE, SUM_OF_MONEY, SUM_OF_TAX, VAT_PERCENT,
                FORMS_OF_PAYMENT, BANK_ACCOUNT, BUYER_NAME, UNIT,
                EXTRA_GOODS, EXTRA_MONEY
                FROM INVOICE_S_EC(0, :FROM_COMPANY, :ID)
                INTO :NOTE, :ORDINAL, :CUSTOMER_NAME, :CUSTOMER_ADDRESS, :CUSTOMER_TAX_CODE, :GOODS, :INPUT_DATE, :INVOICE_CODE, :INVOICE_DATE, :INVOICE_TEMPLATE, :CODE_TEMPLATE, :INVOICE_TYPE, :SERIAL_CODE, :SUM_OF_MONEY, :SUM_OF_TAX, :VAT_PERCENT,
                :FORMS_OF_PAYMENT, :BANK_ACCOUNT, :BUYER_NAME, :UNIT,
                :EXTRA_GOODS, :EXTRA_MONEY
            DO
            BEGIN
                EXECUTE PROCEDURE INVOICE_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), NOTE, ORDINAL, :FORMS_OF_PAYMENT, :BANK_ACCOUNT, :BUYER_NAME, NULL, CUSTOMER_ADDRESS, CUSTOMER_NAME, CUSTOMER_TAX_CODE, NEW_DOCUMENT_ID, GOODS, :UNIT, INPUT_DATE, INVOICE_CODE, INVOICE_DATE, INVOICE_TEMPLATE, CODE_TEMPLATE, INVOICE_TYPE, SERIAL_CODE, SUM_OF_MONEY, SUM_OF_TAX, VAT_PERCENT, EXTRA_GOODS, EXTRA_MONEY);
            END
        END
    END
END ^

ALTER PROCEDURE COPY_EMPLOYEES (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
BEGIN
    OBJECT_TYPE = 42;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
        FROM EMPLOYEE_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            EXECUTE PROCEDURE EMPLOYEE_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, NULL, :OBJECT_TYPE);
        END
    END
END ^

ALTER PROCEDURE COPY_EMPLOYEES_EXTERNAL (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
CONNECTION DM_FILE_NAME)
AS 
