            EXECUTE STATEMENT ('EXECUTE PROCEDURE EMPLOYEE_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, NULL, :OBJECT_TYPE)')
            (TO_COMPANY:=:TO_COMPANY, NOTE:=:NOTE, ORDINAL:=:ORDINAL, CODE:=:CODE, HIDE:=:HIDE, NAME:=:NAME, PARENT:=:PARENT, TEAM:=:TEAM, RELATED_OBJECT:=:RELATED_OBJECT, OBJECT_TYPE:=:OBJECT_TYPE)
            ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey';
        END
    END
END ^

