ALTER PROCEDURE COPY_FIRST_BALANCES (P_FROM_COMPANY_ID DM_ID,
P_FROM_PERIOD DM_ID,
P_TO_COMPANY_ID DM_ID,
P_CONNECTION DM_FILE_NAME)
AS 
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE TO_PERIOD DM_ID;
BEGIN
    P_CONNECTION = 'localhost:' || :P_CONNECTION;

 
    SELECT ENDING_DATE
    FROM PERIODS
    WHERE PERIODS.COMPANY = :P_FROM_COMPANY_ID AND PERIODS.ID = :P_FROM_PERIOD
    INTO :ENDING_DATE;

    ENDING_DATE = DATEADD(DAY, 1, ENDING_DATE);

    EXECUTE STATEMENT (
        'SELECT ID
        FROM PERIODS
        WHERE PERIODS.COMPANY = :P_TO_COMPANY_ID AND :P_ENDING_DATE BETWEEN PERIODS.BEGINNING_DATE AND PERIODS.ENDING_DATE')
        (P_TO_COMPANY_ID:=:P_TO_COMPANY_ID, P_ENDING_DATE:=:ENDING_DATE)
    ON EXTERNAL DATA SOURCE :P_CONNECTION AS USER 'sysdba' PASSWORD 'masterkey'
    INTO :TO_PERIOD;

    IF(TO_PERIOD IS NOT NULL)THEN
    BEGIN
