        EXECUTE PROCEDURE COPY_WORK_OF_PROJECTS_EXTERNAL(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
        EXECUTE PROCEDURE COPY_LOAN_AGREEMENTS_EXTERNAL(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
        EXECUTE PROCEDURE COPY_AFFAIRS_EXTERNAL(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
        EXECUTE PROCEDURE COPY_WORKSHOPS_EXTERNAL(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
        EXECUTE PROCEDURE COPY_PHASES_EXTERNAL(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
        EXECUTE PROCEDURE COPY_CONTRACTS_EXTERNAL(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
        EXECUTE PROCEDURE COPY_SOURCE_OF_CAPITALS_EXTERNA(:P_FROM_COMPANY_ID, :P_TO_COMPANY_ID, :P_CONNECTION);
