ALTER PROCEDURE COPY_GOODS (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;

DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;
DECLARE VARIABLE UNIT DM_UNIT;
DECLARE VARIABLE WARRANTY_MONTHS DM_INTEGER;
BEGIN
    OBJECT_TYPE = 54;

    FOR
        SELECT ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, UNIT,
            WARRANTY_MONTHS
        FROM GOOD_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :UNIT,
            :WARRANTY_MONTHS
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;

            EXECUTE PROCEDURE GOOD_IU(0, :TO_COMPANY, GEN_ID(UNIVERSE, 1), :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT, :UNIT, :WARRANTY_MONTHS, :OBJECT_TYPE);
        END
    END
END ^

