ALTER PROCEDURE COPY_PREPAID_EXPENSES (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM,
TO_ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;
DECLARE VARIABLE FROM_PREPAID_EXPENSE DM_ID;
DECLARE VARIABLE ORDINAL DM_INTEGER;
DECLARE VARIABLE NOTE DM_NOTE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NAME DM_NAME;
DECLARE VARIABLE HIDE DM_BOOL;
DECLARE VARIABLE PARENT DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE RELATED_OBJECT DM_ID;

DECLARE VARIABLE TOTAL_DEPRECIATION_PERIOD DM_SMALLINT;
DECLARE VARIABLE DEPRECIATION_PERIOD DM_SMALLINT;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE ACCOUNT_EXPENSE DM_ID;
DECLARE VARIABLE DATE_OF_USING DM_DATE;
DECLARE VARIABLE TO_PREPAID_EXPENSE DM_ID;
BEGIN
    OBJECT_TYPE = 96;

    FOR
        SELECT ID, ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        TOTAL_DEPRECIATION_PERIOD , DEPRECIATION_PERIOD , DEPRECIATION_TIME_TYPE ,
        BEGINNING_DEPRECIATION_VALUE1 , BEGINNING_DEPRECIATION_VALUE2 , ACCOUNT , ACCOUNT_EXPENSE, DATE_OF_USING
        FROM PREPAID_EXPENSE_S_ER(0, :FROM_COMPANY)
        ORDER BY PARENT
        INTO :FROM_PREPAID_EXPENSE, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :TOTAL_DEPRECIATION_PERIOD , :DEPRECIATION_PERIOD , :DEPRECIATION_TIME_TYPE ,
        :BEGINNING_DEPRECIATION_VALUE1 , :BEGINNING_DEPRECIATION_VALUE2 , :ACCOUNT , :ACCOUNT_EXPENSE, :DATE_OF_USING
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM ATOMS
            WHERE ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.COMPANY = :TO_COMPANY AND ATOMS.CODE = :CODE
        ))THEN
        BEGIN
            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :PARENT)
            INTO :PARENT;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :TEAM)
            INTO :TEAM;

            SELECT TO_ID
            FROM COPY_SEARCH(:FROM_COMPANY, :TO_COMPANY, :RELATED_OBJECT)
            INTO :RELATED_OBJECT;
            
            SELECT TO_ACCOUNT
            FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :ACCOUNT, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
            INTO :ACCOUNT;
            
            SELECT TO_ACCOUNT
            FROM COPY_CONVERT_ACCOUNT(:FROM_COMPANY, :TO_COMPANY, :ACCOUNT_EXPENSE, :FROM_ACCOUNTING_SYSTEM, :TO_ACCOUNTING_SYSTEM)
            INTO :ACCOUNT_EXPENSE;

            TO_PREPAID_EXPENSE = GEN_ID(UNIVERSE, 1);
            EXECUTE PROCEDURE PREPAID_EXPENSE_IU(0, :TO_COMPANY, :TO_PREPAID_EXPENSE, :NOTE, :ORDINAL, :CODE, :HIDE, :NAME, :PARENT, :TEAM, :RELATED_OBJECT,
            TOTAL_DEPRECIATION_PERIOD , DEPRECIATION_PERIOD , DEPRECIATION_TIME_TYPE ,
            BEGINNING_DEPRECIATION_VALUE1 , BEGINNING_DEPRECIATION_VALUE2 , ACCOUNT , ACCOUNT_EXPENSE, :DATE_OF_USING,
            :OBJECT_TYPE);

            EXECUTE PROCEDURE COPY_PREPAID_EXPENSE_PERIODS(:FROM_COMPANY, :FROM_PREPAID_EXPENSE, :TO_COMPANY, :TO_PREPAID_EXPENSE);
        END
    END
END ^

