ALTER PROCEDURE COPY_SEARCH (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ID DM_ID)
RETURNS (TO_ID DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;
DECLARE VARIABLE FROM_CODE DM_CODE;
BEGIN
    IF(FROM_ID IS NOT NULL)THEN
    BEGIN
        SELECT OBJECT_TYPE, CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :FROM_COMPANY AND ATOMS.ID = :FROM_ID
        INTO :OBJECT_TYPE, :FROM_CODE;

        IF(FROM_CODE IS NOT NULL)THEN
        BEGIN
            SELECT ID
            FROM ATOMS
            WHERE ATOMS.COMPANY = :TO_COMPANY AND ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.CODE = :FROM_CODE
            INTO :TO_ID;
        END
    END

    SUSPEND;
END ^

ALTER PROCEDURE COPY_SEARCH_EXTERNAL (FROM_COMPANY DM_ID,
TO_COMPANY DM_ID,
FROM_ID DM_ID,
CONNECTION DM_FILE_NAME)
RETURNS (TO_ID DM_ID)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;
DECLARE VARIABLE FROM_CODE DM_CODE;
BEGIN
    IF(FROM_ID IS NOT NULL)THEN
    BEGIN
        SELECT OBJECT_TYPE, CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :FROM_COMPANY AND ATOMS.ID = :FROM_ID
        INTO :OBJECT_TYPE, :FROM_CODE;

        IF(FROM_CODE IS NOT NULL)THEN
        BEGIN
            EXECUTE STATEMENT(
            'SELECT ID
            FROM ATOMS
            WHERE ATOMS.COMPANY = :TO_COMPANY AND ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.CODE = :FROM_CODE')
            (TO_COMPANY:=:TO_COMPANY, OBJECT_TYPE:=:OBJECT_TYPE, FROM_CODE:=:FROM_CODE)
            ON EXTERNAL DATA SOURCE :CONNECTION AS USER 'sysdba' PASSWORD 'masterkey'
            INTO :TO_ID;
        END
    END

    SUSPEND;
END ^

