ALTER PROCEDURE COST_PRICE_DEFINE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_REVENUE_ACCOUNT DM_ID,
P_COST_PRICE_ACCOUNT DM_ID,
P_GOODS_ACCOUNT DM_ID,
P_WAREHOUSE DM_ID,
P_DOCUMENT_TEAM DM_ID,
P_ENABLED DM_BOOL,
P_DEFAULT_CONTENT DM_CONTENT)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO COST_PRICE_DEFINES(COMPANY, ID, REVENUE_ACCOUNT, COST_PRICE_ACCOUNT, GOODS_ACCOUNT, WAREHOUSE, DOCUMENT_TEAM, ENABLED, DEFAULT_CONTENT)
    VALUES(:P_COMPANY, :P_ID, :P_REVENUE_ACCOUNT, :P_COST_PRICE_ACCOUNT, :P_GOODS_ACCOUNT, :P_WAREHOUSE, :P_DOCUMENT_TEAM, :P_ENABLED, :P_DEFAULT_CONTENT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

