ALTER PROCEDURE DECREASE_DOCUMENT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_CREDIT_DEBIT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
INCREASE_DOCUMENT DM_ID,
CODE DM_CODE,
INPUT_DATE DM_DATE,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
FOR
   SELECT DECREASE_DOCUMENTS.ID, NOTE, ORDINAL,
    INCREASE_DOCUMENT, OFFICIAL_SUM_OF_MONEY, FOREIGN_SUM_OF_MONEY
   FROM DECREASE_DOCUMENTS
   JOIN DECREASE_DOCUMENT_STRINGS ON DECREASE_DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENT_STRINGS.ID = DECREASE_DOCUMENTS.ID AND DECREASE_DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE
   WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.CREDIT_DEBIT = :P_CREDIT_DEBIT
   INTO :ID, :NOTE, :ORDINAL,
    :INCREASE_DOCUMENT, :OFFICIAL_SUM_OF_MONEY, :FOREIGN_SUM_OF_MONEY
DO
BEGIN
    SELECT CODE, INPUT_DATE, CURRENCY, EXCHANGE_RATE
    FROM BEGINNING_DOCUMENTS
    WHERE BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND ID = :INCREASE_DOCUMENT
    INTO :CODE, :INPUT_DATE, :CURRENCY, :EXCHANGE_RATE;

    IF(CODE IS NULL)THEN
    BEGIN
        SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE
        FROM DOCUMENTS
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :INCREASE_DOCUMENT
        INTO :CODE, :INPUT_DATE;
    END

    SUSPEND;

    CODE = NULL;
END
END ^

