ALTER PROCEDURE DECREASE_ENTRY_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_CREDIT_DEBIT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
INCREASE_ENTRY DM_ID,
CODE DM_CODE,
INPUT_DATE DM_DATE,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE SIDE DM_SIDE;
BEGIN
FOR
   SELECT DECREASE_ENTRIES.ID, NOTE, ORDINAL, INCREASE_ENTRY, AMOUNT, OFFICIAL_SUM_OF_MONEY, FOREIGN_SUM_OF_MONEY
   FROM DECREASE_ENTRIES
   JOIN DECREASE_ENTRY_STRINGS ON DECREASE_ENTRY_STRINGS.COMPANY = :P_COMPANY AND DECREASE_ENTRY_STRINGS.ID = DECREASE_ENTRIES.ID AND DECREASE_ENTRY_STRINGS.LANGUAGE = :P_LANGUAGE
   WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.CREDIT_DEBIT = :P_CREDIT_DEBIT
   INTO :ID, :NOTE, :ORDINAL, :INCREASE_ENTRY, :AMOUNT, :OFFICIAL_SUM_OF_MONEY, :FOREIGN_SUM_OF_MONEY
DO
BEGIN
    SELECT CODE, INPUT_DATE, CURRENCY, EXCHANGE_RATE, PRICE
    FROM BEGINNING_ENTRIES
    WHERE BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND ID = :INCREASE_ENTRY
    INTO :CODE, :INPUT_DATE, :CURRENCY, :EXCHANGE_RATE, :PRICE;

    IF(CODE IS NULL)THEN
    BEGIN
        SELECT SIDE
        FROM CREDIT_DEBIT
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ID = :P_CREDIT_DEBIT
        INTO :SIDE;

        IF(SIDE = 0)THEN
        BEGIN
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE, CURRENCY, EXCHANGE_RATE, CREDIT.PRICE
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND ENTRIES.ID = :INCREASE_ENTRY
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
            WHERE DOCUMENTS.COMPANY = :P_COMPANY
            INTO :CODE, :INPUT_DATE, :CURRENCY, :EXCHANGE_RATE, :PRICE;
        END
        ELSE
        BEGIN
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE, CURRENCY, EXCHANGE_RATE, DEBIT.PRICE
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND ENTRIES.ID = :INCREASE_ENTRY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
            WHERE DOCUMENTS.COMPANY = :P_COMPANY
            INTO :CODE, :INPUT_DATE, :CURRENCY, :EXCHANGE_RATE, :PRICE;
        END
    END

    SUSPEND;

    CODE = NULL;
END
END ^

