ALTER PROCEDURE DOCUMENT_BALANCE_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_DECREASE_DATE DM_DATE,
P_SIDE DM_SIDE)
RETURNS (ID DM_ID,
CONTENT DM_CONTENT,
NOTE DM_NOTE,
INPUT_DATE DM_DATE,
CODE DM_DOCUMENT_CODE,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE; 
DECLARE VARIABLE DECREASE_FOREIGN_SUM_OF_MONEY DM_DOUBLE; 
DECLARE VARIABLE ACCOUNT_TYPES DM_ACCOUNT_TYPES;
BEGIN
    
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_DECREASE_DATE)
    INTO :PERIOD;

    SELECT ACCOUNT_TYPES
    FROM ACCOUNTS
    WHERE COMPANY = :P_COMPANY AND ID = :P_ACCOUNT
    INTO :ACCOUNT_TYPES;

    
    IF(P_SIDE = 0 AND BIN_AND(ACCOUNT_TYPES, 8192) <> 0)THEN
    BEGIN
        FOR
            SELECT ID, CONTENT, NOTE, INPUT_DATE, CODE, OFFICIAL_SUM_OF_MONEY, FOREIGN_SUM_OF_MONEY
            FROM
            (
                
                SELECT BEGINNING_DOCUMENTS.ID, CONTENT, NOTE, INPUT_DATE, CODE, DOCUMENT_BALANCES.OFFICIAL_CREDIT OFFICIAL_SUM_OF_MONEY, DOCUMENT_BALANCES.FOREIGN_CREDIT FOREIGN_SUM_OF_MONEY
                FROM DOCUMENT_BALANCES
                JOIN BEGINNING_DOCUMENTS ON BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND BEGINNING_DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND BEGINNING_DOCUMENTS.INPUT_DATE <= :P_DECREASE_DATE AND BEGINNING_DOCUMENTS.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR BEGINNING_DOCUMENTS.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR BEGINNING_DOCUMENTS.OBJECT1 = :P_OBJECT1) AND (:P_OBJECT2 IS NULL OR BEGINNING_DOCUMENTS.OBJECT2 = :P_OBJECT2)
                JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = BEGINNING_DOCUMENTS.ID
                JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
                WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND (DOCUMENT_BALANCES.OFFICIAL_CREDIT <> 0 OR DOCUMENT_BALANCES.FOREIGN_CREDIT <> 0)

                UNION ALL

                
