ALTER PROCEDURE DOCUMENT_BASE_D (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
BEGIN
    DELETE FROM DOCUMENT_BASES
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID;

    WHEN ANY DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = SQLCODE AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || SQLCODE || ')';
    END
END ^

ALTER PROCEDURE DOCUMENT_BASE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CONTENT DM_CONTENT,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER)
AS 
BEGIN
    UPDATE OR INSERT INTO DOCUMENT_BASES(COMPANY, ID, ORDINAL) VALUES(:P_COMPANY, :P_ID, :P_ORDINAL);

    UPDATE OR INSERT INTO DOCUMENT_BASE_STRINGS(COMPANY, ID, LANGUAGE, CONTENT, NOTE) VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_CONTENT, :P_NOTE);
END ^

ALTER PROCEDURE DOCUMENT_C_TEAM (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TEAM DM_ID)
AS 
DECLARE VARIABLE INPUT_DATE DM_DATE;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NUMBER DM_CODE;
BEGIN
    SELECT INPUT_DATE
    FROM DOCUMENTS
    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
    INTO :INPUT_DATE;

    SELECT CODE, NUMBER
    FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :P_TEAM, :INPUT_DATE)
    INTO :CODE, :NUMBER;

    UPDATE DOCUMENTS
    SET DOCUMENTS.TEAM = :P_TEAM,
    DOCUMENTS.CODE = :CODE, 
    DOCUMENTS.NUMBER = :NUMBER
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID;

    WHEN ANY DO
    BEGIN
        EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
    END
END ^

ALTER PROCEDURE DOCUMENT_DOUBLE_ENTRY_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_ADDITION_INFO_1 DM_ADDITION_INFO,
P_ADDITION_INFO_2 DM_ADDITION_INFO,
P_ADDITION_INFO_3 DM_ADDITION_INFO,
P_ADDITION_INFO_4 DM_ADDITION_INFO,
P_CURRENCY DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_INPUT_DATE DM_DATE,
P_OBJECT DM_ID,
P_ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
P_PERIOD DM_ID,
P_TEAM DM_ID,
P_VOUCHER_DATE DM_DATE,
P_EMPLOYEE DM_ID,
P_PERSON_NAME DM_PERSON_NAME,
P_PERSON_ADDRESS DM_ADDRESS,
P_CONTENT DM_CONTENT,
P_DOCUMENT_SUM DM_DOUBLE,
P_ENTRY_NOTE DM_NOTE,
P_ENTRY_ORDINAL DM_INTEGER,
P_VAT_PERCENT DM_DOUBLE,
P_ENTRY_CONTENT DM_CONTENT,
P_DEBIT_ACCOUNT DM_ID,
P_DEBIT_OBJECT0 DM_ID,
P_DEBIT_OBJECT1 DM_ID,
P_DEBIT_OBJECT2 DM_ID,
P_CREDIT_ACCOUNT DM_ID,
P_CREDIT_OBJECT0 DM_ID,
P_CREDIT_OBJECT1 DM_ID,
P_CREDIT_OBJECT2 DM_ID,
P_AMOUNT DM_DOUBLE,
P_PRICE DM_DOUBLE,
P_FOREIGN_SUM_OF_MONEY DM_DOUBLE,
P_OFFICIAL_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE CODE DM_CODE;
DECLARE VARIABLE NUMBER DM_CODE;
BEGIN
    
    SELECT CODE, NUMBER
    FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :P_TEAM, :P_INPUT_DATE)
    INTO :CODE, :NUMBER;

    DOCUMENT = GEN_ID(UNIVERSE, 1);
    EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :DOCUMENT, :P_NOTE,  :P_ORDINAL, :P_ADDITION_INFO_1,  :P_ADDITION_INFO_2, :P_ADDITION_INFO_3, :P_ADDITION_INFO_4, :CODE, :NUMBER, :P_CURRENCY, :P_EXCHANGE_RATE, :P_INPUT_DATE, :P_OBJECT, :P_ORIGINAL_VOUCHERS, :P_PERIOD, :P_TEAM, :P_VOUCHER_DATE, :P_EMPLOYEE, :P_PERSON_NAME, :P_PERSON_ADDRESS, :P_CONTENT, :P_DOCUMENT_SUM, 0);

    
    EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), :P_ENTRY_NOTE, :P_ENTRY_ORDINAL, :P_CURRENCY, :DOCUMENT, :P_EXCHANGE_RATE, :P_VAT_PERCENT, 0, NULL, NULL, :P_ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :P_DEBIT_ACCOUNT, :P_DEBIT_OBJECT0, :P_DEBIT_OBJECT1, :P_DEBIT_OBJECT2, GEN_ID(UNIVERSE, 1), :P_CREDIT_ACCOUNT, :P_CREDIT_OBJECT0, :P_CREDIT_OBJECT1, :P_CREDIT_OBJECT2, :P_AMOUNT, :P_PRICE, :P_FOREIGN_SUM_OF_MONEY, :P_OFFICIAL_SUM_OF_MONEY);
END ^

ALTER PROCEDURE DOCUMENT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_ADDITION_INFO_1 DM_ADDITION_INFO,
P_ADDITION_INFO_2 DM_ADDITION_INFO,
P_ADDITION_INFO_3 DM_ADDITION_INFO,
P_ADDITION_INFO_4 DM_ADDITION_INFO,
P_CODE DM_CODE,
P_NUMBER DM_CODE,
P_CURRENCY DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_INPUT_DATE DM_DATE,
P_OBJECT DM_ID,
P_ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
P_PERIOD DM_ID,
P_TEAM DM_ID,
P_VOUCHER_DATE DM_DATE,
P_EMPLOYEE DM_ID,
P_PERSON_NAME DM_PERSON_NAME,
P_PERSON_ADDRESS DM_ADDRESS,
P_CONTENT DM_CONTENT,
P_DOCUMENT_SUM DM_DOUBLE,
P_DOCUMENT_TYPE DM_DOCUMENT_TYPES)
AS 
DECLARE VARIABLE COST_PRICE_DOCUMENT DM_ID;
DECLARE VARIABLE DEFAULT_CONTENT DM_CONTENT;
BEGIN
    EXECUTE PROCEDURE DOCUMENT_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_CONTENT, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO DOCUMENTS(COMPANY, ID, INPUT_DATE, VOUCHER_DATE, ORIGINAL_VOUCHERS, CODE, NUMBER, TEAM, PERIOD, OBJECT, EMPLOYEE, DOCUMENT_SUM, DOCUMENT_TYPE)
    VALUES(:P_COMPANY, :P_ID, :P_INPUT_DATE, :P_VOUCHER_DATE, :P_ORIGINAL_VOUCHERS, :P_CODE, :P_NUMBER, :P_TEAM, :P_PERIOD, :P_OBJECT, :P_EMPLOYEE, :P_DOCUMENT_SUM, :P_DOCUMENT_TYPE);

    UPDATE OR INSERT INTO DOCUMENT_STRINGS(COMPANY, ID, LANGUAGE, ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, PERSON_NAME, PERSON_ADDRESS)
    VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_ADDITION_INFO_1, :P_ADDITION_INFO_2, :P_ADDITION_INFO_3, :P_ADDITION_INFO_4, :P_PERSON_NAME, :P_PERSON_ADDRESS);

    SELECT FIRST 1 COST_PRICE_ENTRIES.DOCUMENT, DEFAULT_CONTENT
    FROM ENTRIES COST_PRICE_ENTRIES
    JOIN ENTRIES REVENUE_ENTRIES ON REVENUE_ENTRIES.COMPANY = :P_COMPANY AND COST_PRICE_ENTRIES.REVENUE_ENTRY = REVENUE_ENTRIES.ID AND REVENUE_ENTRIES.DOCUMENT = :P_ID
    LEFT JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = REVENUE_ENTRIES.ID
    LEFT JOIN COST_PRICE_DEFINES ON COST_PRICE_DEFINES.COMPANY = :P_COMPANY AND COST_PRICE_DEFINES.REVENUE_ACCOUNT = CREDIT_DEBIT.ACCOUNT
    WHERE COST_PRICE_ENTRIES.COMPANY = :P_COMPANY
    INTO :COST_PRICE_DOCUMENT, :DEFAULT_CONTENT;

    IF(COST_PRICE_DOCUMENT IS NOT NULL)THEN
    BEGIN
        UPDATE DOCUMENTS
        SET DOCUMENTS.INPUT_DATE = :P_INPUT_DATE, DOCUMENTS.VOUCHER_DATE = :P_VOUCHER_DATE, DOCUMENTS.ORIGINAL_VOUCHERS = :P_CODE || '-' || :P_NUMBER
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :COST_PRICE_DOCUMENT;

        IF(P_CONTENT IS NULL)THEN P_CONTENT = '';
        IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
        BEGIN
            IF(P_CONTENT <> '')THEN
                P_CONTENT = DEFAULT_CONTENT || ', ' || :P_CONTENT;
            ELSE
                P_CONTENT = DEFAULT_CONTENT;
        END

        UPDATE DOCUMENT_BASE_STRINGS
        SET DOCUMENT_BASE_STRINGS.CONTENT = :P_CONTENT
        WHERE DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = :COST_PRICE_DOCUMENT;
    END

    UPDATE CURRENCIES
    SET EXCHANGE_RATE = :P_EXCHANGE_RATE
    WHERE COMPANY = :P_COMPANY AND ID = :P_CURRENCY;

    WHEN ANY DO
    BEGIN
        EXECUTE PROCEDURE THROW_EXCEPTION_INFO(SQLCODE, :P_LANGUAGE, :P_CODE || '-' || :P_NUMBER);
    END
END ^

ALTER PROCEDURE DOCUMENT_MODULE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE TEAM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO DOCUMENT_MODULES(COMPANY, ID) VALUES(:P_COMPANY, :P_ID);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE DOCUMENT_MODULE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID)
AS 
BEGIN
  FOR
  SELECT DOCUMENT_MODULES.ID, ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
  FROM DOCUMENT_MODULES
  JOIN TEAMS ON TEAMS.COMPANY = :P_COMPANY AND TEAMS.ID = DOCUMENT_MODULES.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = TEAMS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE DOCUMENT_MODULES.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
  DO
    SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_SUMS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
CAL_111 SMALLINT = 1)
RETURNS (SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE,
SUM_111 DM_DOUBLE,
SUM_11 DM_DOUBLE)
AS 
declare variable debit_111 dm_double;
declare variable credit_111 dm_double;
declare variable debit_112 dm_double;
declare variable credit_112 dm_double;
BEGIN
    IF(NOT EXISTS(
        SELECT 1
        FROM temp_vat_accounts_1
    ))THEN
        INSERT INTO temp_vat_accounts_1(ID)
        SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 1) = 1;

    IF(NOT EXISTS(
        SELECT 1
        FROM temp_vat_accounts_2
    ))THEN
        INSERT INTO temp_vat_accounts_2(ID)
        SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 2) = 2;

    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN CREDIT_DEBIT DEBIT ON
            DEBIT.COMPANY = :P_COMPANY AND
            DEBIT.SIDE = 0 AND
            DEBIT.ENTRY = ENTRIES.ID AND
            NOT EXISTS
            (
                SELECT 1 FROM temp_vat_accounts_1 WHERE ID = DEBIT.ACCOUNT
            )
    JOIN CREDIT_DEBIT CREDIT ON
            CREDIT.COMPANY = :P_COMPANY AND
            CREDIT.SIDE = 1 AND
            CREDIT.ENTRY = ENTRIES.ID AND
            NOT EXISTS
            (
                SELECT 1 FROM temp_vat_accounts_2 WHERE ID = CREDIT.ACCOUNT
            )
    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID
    INTO :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID AND
    (
        (DEBIT.ACCOUNT IN (SELECT ID FROM temp_vat_accounts_1))
        OR
        (CREDIT.ACCOUNT IN (SELECT ID FROM temp_vat_accounts_2))
    )
    INTO :SUM_OF_TAX;

    IF(SUM_OF_TAX IS NULL)THEN SUM_OF_TAX = 0;

    SUM_ALL = SUM_OF_MONEY + SUM_OF_TAX;

    IF(CAL_111 = 1)THEN
    BEGIN
        SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
        JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID AND DEBIT_ATOMS.CODE STARTING WITH '111'
        INTO :DEBIT_111;
    
        IF(DEBIT_111 IS NULL)THEN DEBIT_111 = 0;
    
        SELECT SUM(CREDIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID AND CREDIT_ATOMS.CODE STARTING WITH '111'
        INTO :CREDIT_111;
    
        IF(CREDIT_111 IS NULL)THEN CREDIT_111 = 0;

        sum_111 = ABS(DEBIT_111 - CREDIT_111);

        SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
        JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID AND DEBIT_ATOMS.CODE STARTING WITH '112'
        INTO :DEBIT_112;
    
        IF(DEBIT_112 IS NULL)THEN DEBIT_112 = 0;
    
        SELECT SUM(CREDIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID AND CREDIT_ATOMS.CODE STARTING WITH '112'
        INTO :CREDIT_112;
    
        IF(CREDIT_112 IS NULL)THEN CREDIT_112 = 0;
    
        SUM_11 = sum_111 + ABS(DEBIT_112 - CREDIT_112);
    END

    SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_SUMS_NV (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (SUM_OF_MONEY DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.ACCOUNT NOT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 1) = 1)
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT NOT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 2) = 2)
    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID
    INTO :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUM_ALL = SUM_OF_MONEY;

    SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_S_ER_ID (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NUMBER DM_CODE,
TEAM DM_ID,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
OBJECT DM_ID,
EMPLOYEE DM_ID,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
PERIOD DM_ID,
VOUCHER_DATE DM_DATE,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
CONTENT DM_CONTENT,
DOCUMENT_SUM DM_DOUBLE,
DOCUMENT_TYPE DM_DOCUMENT_TYPES,
PRINTED_COUNTER DM_INTEGER)
AS 
BEGIN
    FOR
        SELECT DOCUMENTS.ID, DOCUMENT_BASES.ORDINAL, DOCUMENT_BASE_STRINGS.NOTE,
        CODE, NUMBER, TEAM, ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, INPUT_DATE, OBJECT, ORIGINAL_VOUCHERS, VOUCHER_DATE, PERIOD, PERSON_NAME, PERSON_ADDRESS, DOCUMENT_BASE_STRINGS.CONTENT, EMPLOYEE, DOCUMENT_SUM,
        DOCUMENT_TYPE, PRINTED_COUNTER
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
        INTO :ID, :ORDINAL, :NOTE,
        :CODE, :NUMBER, :TEAM, :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :INPUT_DATE, :OBJECT, :ORIGINAL_VOUCHERS, :VOUCHER_DATE, :PERIOD, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT, :EMPLOYEE, :DOCUMENT_SUM,
        :DOCUMENT_TYPE, :PRINTED_COUNTER
    DO
    BEGIN
        SELECT FIRST 1 CURRENCY, EXCHANGE_RATE
        FROM ENTRIES
        WHERE COMPANY = :P_COMPANY AND DOCUMENT = :ID
        INTO :CURRENCY, :EXCHANGE_RATE;

        IF(CURRENCY IS NULL)THEN
        BEGIN
            SELECT MAIN_CURRENCY, EXCHANGE_RATE
            FROM CMD_GET_DEFAULT_CURRENCY(:P_LANGUAGE, :P_COMPANY)
            INTO :CURRENCY, :EXCHANGE_RATE;
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE DOCUMENT_S_PRINTED_COUNTER (P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (PRINTED_COUNTER DM_INTEGER)
AS 
BEGIN
    PRINTED_COUNTER = 0;

    SELECT PRINTED_COUNTER
    FROM DOCUMENTS
    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
    INTO :PRINTED_COUNTER;

    SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TEAM DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
EMPLOYEE_NAME DM_NAME,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
CONTENT DM_CONTENT,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE,
DOCUMENT_TYPE DM_DOCUMENT_TYPES,
PRINTED_COUNTER DM_INTEGER)
AS 
declare variable object dm_id;
BEGIN
    FOR
        SELECT DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.NOTE, DOCUMENTS.CODE || '-' || NUMBER, ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, INPUT_DATE, OBJECT, ORIGINAL_VOUCHERS, VOUCHER_DATE, PERSON_NAME, PERSON_ADDRESS, DOCUMENT_BASE_STRINGS.CONTENT, EMPLOYEE_STRINGS.NAME,
        DOCUMENT_TYPE, PRINTED_COUNTER
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        LEFT JOIN ATOM_STRINGS EMPLOYEE_STRINGS ON EMPLOYEE_STRINGS.COMPANY = :P_COMPANY AND EMPLOYEE_STRINGS.LANGUAGE = :P_LANGUAGE AND EMPLOYEE_STRINGS.ID = EMPLOYEE
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.TEAM = :P_TEAM AND DOCUMENTS.INPUT_DATE BETWEEN :P_FROM_DATE AND :P_TO_DATE
        INTO :ID, :NOTE, :CODE, :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :INPUT_DATE, :OBJECT, :ORIGINAL_VOUCHERS, :VOUCHER_DATE, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT, :EMPLOYEE_NAME,
        :DOCUMENT_TYPE, :PRINTED_COUNTER
    DO
    BEGIN
        SELECT SUM_OF_MONEY, SUM_OF_TAX,  SUM_ALL
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :ID)
        INTO :SUM_OF_MONEY, :SUM_OF_TAX, :SUM_ALL;

        IF(OBJECT IS NULL)THEN
        BEGIN
            OBJECT_CODE = NULL;
            OBJECT_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
            INTO :OBJECT_CODE, :OBJECT_NAME;

        SUSPEND;
    END
END ^

ALTER PROCEDURE DOCUMENT_S_RS_ACCOUNT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
EMPLOYEE_CODE DM_CODE,
EMPLOYEE_NAME DM_NAME,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
CONTENT DM_CONTENT,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE,
DOCUMENT_TYPE DM_DOCUMENT_TYPES)
AS 
DECLARE VARIABLE OBJECT DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.NOTE, DOCUMENTS.CODE || '-' || NUMBER, ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, INPUT_DATE, OBJECT, ORIGINAL_VOUCHERS, VOUCHER_DATE, PERSON_NAME, PERSON_ADDRESS, DOCUMENT_BASE_STRINGS.CONTENT, EMPLOYEES.CODE, EMPLOYEE_STRINGS.NAME,
        :DOCUMENT_TYPE
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        LEFT JOIN ATOMS EMPLOYEES ON EMPLOYEES.COMPANY = :P_COMPANY AND EMPLOYEES.ID = EMPLOYEE
        LEFT JOIN ATOM_STRINGS EMPLOYEE_STRINGS ON EMPLOYEE_STRINGS.COMPANY = :P_COMPANY AND EMPLOYEE_STRINGS.LANGUAGE = :P_LANGUAGE AND EMPLOYEE_STRINGS.ID = EMPLOYEE
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_FROM_DATE AND :P_TO_DATE AND
        EXISTS (
            SELECT DOCUMENTS.ID
            FROM ENTRIES
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND
            (DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE)
        )
        INTO :ID, :NOTE, :CODE, :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :INPUT_DATE, :OBJECT, :ORIGINAL_VOUCHERS, :VOUCHER_DATE, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT, :EMPLOYEE_CODE, :EMPLOYEE_NAME,
        :DOCUMENT_TYPE
    DO
    BEGIN
        SELECT SUM_OF_MONEY, SUM_OF_TAX,  SUM_ALL
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :ID)
        INTO :SUM_OF_MONEY, :SUM_OF_TAX, :SUM_ALL;

        IF(OBJECT IS NULL)THEN
        BEGIN
            OBJECT_CODE = NULL;
            OBJECT_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
            INTO :OBJECT_CODE, :OBJECT_NAME;

        SUSPEND;
    END
END ^

ALTER PROCEDURE DOCUMENT_S_SEARCH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_WHERE DM_STRING)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
EMPLOYEE_NAME DM_NAME,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
CONTENT DM_CONTENT,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE,
DOCUMENT_TYPE DM_DOCUMENT_TYPES,
PRINTED_COUNTER DM_INTEGER)
AS 
DECLARE VARIABLE OBJECT DM_ID;
DECLARE VARIABLE STRING DM_STRING;
BEGIN
    STRING = 'SELECT DISTINCT DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.NOTE, DOCUMENTS.CODE || ''-'' || DOCUMENTS.NUMBER , DOCUMENT_STRINGS.ADDITION_INFO_1, DOCUMENT_STRINGS.ADDITION_INFO_2, DOCUMENT_STRINGS.ADDITION_INFO_3, DOCUMENT_STRINGS.ADDITION_INFO_4, DOCUMENTS.INPUT_DATE, DOCUMENTS.OBJECT, DOCUMENTS.ORIGINAL_VOUCHERS, DOCUMENTS.VOUCHER_DATE, DOCUMENT_STRINGS.PERSON_NAME, DOCUMENT_STRINGS.PERSON_ADDRESS, DOCUMENT_BASE_STRINGS.CONTENT, EMPLOYEE_STRINGS.NAME, DOCUMENT_TYPE, PRINTED_COUNTER
    FROM DOCUMENTS
    JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = ' || :P_COMPANY || ' AND DOCUMENT_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
    JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = ' || :P_COMPANY || ' AND DOCUMENT_BASES.ID = DOCUMENTS.ID
    JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND DOCUMENT_BASE_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
    LEFT JOIN ATOM_STRINGS EMPLOYEE_STRINGS ON EMPLOYEE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND EMPLOYEE_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND EMPLOYEE_STRINGS.ID = DOCUMENTS.EMPLOYEE
    LEFT JOIN ENTRIES DOUBLE_ENTRIES ON DOUBLE_ENTRIES.COMPANY = ' || :P_COMPANY || ' AND DOUBLE_ENTRIES.ENTRY_TYPE = 1 AND DOUBLE_ENTRIES.DOCUMENT = DOCUMENTS.ID
    LEFT JOIN ENTRY_BASES DOUBLE_ENTRY_BASES ON DOUBLE_ENTRY_BASES.COMPANY = ' || :P_COMPANY || ' AND DOUBLE_ENTRY_BASES.ID = DOUBLE_ENTRIES.ID
    LEFT JOIN ENTRY_BASE_STRINGS DOUBLE_ENTRY_BASE_STRINGS ON DOUBLE_ENTRY_BASE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND DOUBLE_ENTRY_BASE_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND DOUBLE_ENTRY_BASE_STRINGS.ID = DOUBLE_ENTRY_BASES.ID
    LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.SIDE = 0 AND DEBIT.COMPANY = ' || :P_COMPANY || ' AND DEBIT.ENTRY = DOUBLE_ENTRIES.ID
    LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.SIDE = 1 AND CREDIT.COMPANY = ' || :P_COMPANY || ' AND CREDIT.ENTRY = DOUBLE_ENTRIES.ID
    LEFT JOIN ENTRIES SINGLE_ENTRIES ON SINGLE_ENTRIES.COMPANY = ' || :P_COMPANY || ' AND SINGLE_ENTRIES.ENTRY_TYPE = 0 AND SINGLE_ENTRIES.DOCUMENT = DOCUMENTS.ID
    LEFT JOIN ENTRY_BASES SINGLE_ENTRY_BASES ON SINGLE_ENTRY_BASES.COMPANY = ' || :P_COMPANY || ' AND SINGLE_ENTRY_BASES.ID = SINGLE_ENTRIES.ID
    LEFT JOIN ENTRY_BASE_STRINGS SINGLE_ENTRY_BASE_STRINGS ON SINGLE_ENTRY_BASE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND SINGLE_ENTRY_BASE_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND SINGLE_ENTRY_BASE_STRINGS.ID = SINGLE_ENTRY_BASES.ID
    LEFT JOIN CREDIT_DEBIT SINGLE ON SINGLE.COMPANY = ' || :P_COMPANY || ' AND SINGLE.ENTRY = SINGLE_ENTRIES.ID
    LEFT JOIN INVOICES ON INVOICES.COMPANY = ' || :P_COMPANY || ' AND INVOICES.DOCUMENT = DOCUMENTS.ID
    LEFT JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND INVOICE_STRINGS.ID = INVOICES.ID
    WHERE DOCUMENTS.COMPANY = ' || :P_COMPANY || ' AND ' || :P_WHERE;

    FOR
        EXECUTE STATEMENT STRING
        INTO :ID, :NOTE, :CODE, :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :INPUT_DATE, :OBJECT, :ORIGINAL_VOUCHERS, :VOUCHER_DATE, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT, :EMPLOYEE_NAME,
        :DOCUMENT_TYPE, :PRINTED_COUNTER
    DO
    BEGIN
        SELECT SUM_OF_MONEY, SUM_OF_TAX,  SUM_ALL
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :ID)
        INTO :SUM_OF_MONEY, :SUM_OF_TAX, :SUM_ALL;

        IF(OBJECT IS NULL)THEN
        BEGIN
            OBJECT_CODE = NULL;
            OBJECT_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
            INTO :OBJECT_CODE, :OBJECT_NAME;

        SUSPEND;
    END
END ^

ALTER PROCEDURE DOCUMENT_TEAM_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_ADDITION_INFO1 DM_CAPTION,
P_ADDITION_INFO2 DM_CAPTION,
P_ADDITION_INFO3 DM_CAPTION,
P_ADDITION_INFO4 DM_CAPTION,
P_ATOM_TYPE DM_ID,
P_ATOM_NAME DM_NAME,
P_ATOM_USE_OTHER_NAME DM_BOOL,
P_DOUBLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
P_SINGLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
P_CREDIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
P_DEBIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
P_INVOICE_COPY_PROPERTIES DM_INVOICE_PROPERTIES,
P_OTHER_COPY_PROPERTIES DM_OTHER_PROPERTIES,
P_SINGLE_COPY_PROPERTIES DM_COPY_PROPERTIES,
P_CREDIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
P_CREDIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
P_DEBIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
P_DEBIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
P_CREDIT_DEFAULT_ACCOUNT DM_ID,
P_DEBIT_DEFAULT_ACCOUNT DM_ID,
P_SINGLE_DEFAULT_ACCOUNT DM_ID,
P_DEFAULT_INVOICE_TYPE DM_INTEGER,
P_DEFAULT_CONTENT DM_CONTENT,
P_DEFAULT_OBJECT DM_ID,
P_IS_ACTIVE_OBJECT DM_BOOL,
P_MUST_HAVE_OBJECT DM_BOOL,
P_TYPES DM_DOCUMENT_TEAM_TYPES,
P_DEFAULT_CODE DM_CODE,
P_EMPLOYEE_CAPTION DM_CAPTION,
P_PERSON_NAME_CAPTION DM_CAPTION,
P_DEFAULT_GOODS_INPUT_INVOICE DM_GOODS,
P_DEFAULT_GOODS_OUTPUT_INVOICE DM_GOODS,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
  EXECUTE PROCEDURE TEAM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

  UPDATE OR INSERT INTO DOCUMENT_TEAMS(COMPANY, ID,
        ATOM_TYPE,
        ATOM_USE_OTHER_NAME,
        DOUBLE_AUTO_CALCULATION,
        SINGLE_AUTO_CALCULATION,
        CREDIT_COPY_PROPERTIES,
        DEBIT_COPY_PROPERTIES,
        INVOICE_COPY_PROPERTIES,
        OTHER_COPY_PROPERTIES,
        SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS,
        CREDIT_STARTING_ACCOUNTS,
        DEBIT_NOT_STARTING_ACCOUNTS,
        DEBIT_STARTING_ACCOUNTS,
        CREDIT_DEFAULT_ACCOUNT,
        DEBIT_DEFAULT_ACCOUNT,
        SINGLE_DEFAULT_ACCOUNT,
        DEFAULT_INVOICE_TYPE,
        DEFAULT_OBJECT,
        IS_ACTIVE_OBJECT,
        MUST_HAVE_OBJECT,
        TYPES,
        DEFAULT_CODE)
  VALUES(:P_COMPANY, :P_ID,
        :P_ATOM_TYPE,
        :P_ATOM_USE_OTHER_NAME,
        :P_DOUBLE_AUTO_CALCULATION,
        :P_SINGLE_AUTO_CALCULATION,
        :P_CREDIT_COPY_PROPERTIES,
        :P_DEBIT_COPY_PROPERTIES,
        :P_INVOICE_COPY_PROPERTIES,
        :P_OTHER_COPY_PROPERTIES,
        :P_SINGLE_COPY_PROPERTIES,
        :P_CREDIT_NOT_STARTING_ACCOUNTS,
        :P_CREDIT_STARTING_ACCOUNTS,
        :P_DEBIT_NOT_STARTING_ACCOUNTS,
        :P_DEBIT_STARTING_ACCOUNTS,
        :P_CREDIT_DEFAULT_ACCOUNT,
        :P_DEBIT_DEFAULT_ACCOUNT,
        :P_SINGLE_DEFAULT_ACCOUNT,
        :P_DEFAULT_INVOICE_TYPE,
        :P_DEFAULT_OBJECT,
        :P_IS_ACTIVE_OBJECT,
        :P_MUST_HAVE_OBJECT,
        :P_TYPES,
        :P_DEFAULT_CODE);

  UPDATE OR INSERT INTO DOCUMENT_TEAM_STRINGS(LANGUAGE, COMPANY, ID, ADDITION_INFO1, ADDITION_INFO2, ADDITION_INFO3, ADDITION_INFO4, ATOM_NAME, DEFAULT_CONTENT, EMPLOYEE_CAPTION, PERSON_NAME_CAPTION, DEFAULT_GOODS_INPUT_INVOICE, DEFAULT_GOODS_OUTPUT_INVOICE)
  VALUES(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_ADDITION_INFO1, :P_ADDITION_INFO2, :P_ADDITION_INFO3, :P_ADDITION_INFO4, :P_ATOM_NAME, :P_DEFAULT_CONTENT, :P_EMPLOYEE_CAPTION, :P_PERSON_NAME_CAPTION, :P_DEFAULT_GOODS_INPUT_INVOICE, :P_DEFAULT_GOODS_OUTPUT_INVOICE);

  WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX (P_COMPANY DM_ID,
P_CODE DM_CODE,
P_INPUT_DATE DM_DATE)
AS 
DECLARE VARIABLE MAX_NUMBER DM_BIGINT;
DECLARE VARIABLE CURRENT_NUMBER DM_BIGINT;
DECLARE VARIABLE DOCUMENT_CODE_CYCLE DM_TIME_TYPE;
DECLARE VARIABLE TIME_1 DM_INTEGER;
DECLARE VARIABLE TIME_2 DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
DECLARE VARIABLE STARTING_DATE DM_DATE;
BEGIN
    SELECT FIRST 1 DOCUMENT_CODE_CYCLE
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :DOCUMENT_CODE_CYCLE;

    IF(DOCUMENT_CODE_CYCLE IS NOT NULL)THEN
    BEGIN
        SELECT TIME_1, TIME_2, BEGINNING_DATE, ENDING_DATE
        FROM INT_DATE_TIME_TYPE_TO_TIMES(:DOCUMENT_CODE_CYCLE, :P_INPUT_DATE)
        INTO :TIME_1, :TIME_2, :BEGINNING_DATE, :ENDING_DATE;

        
        SELECT PERIODS.BEGINNING_DATE
        FROM ACCOUNTING_SETTINGS
        JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
        INTO :STARTING_DATE;

        IF(STARTING_DATE > BEGINNING_DATE)THEN BEGINNING_DATE = STARTING_DATE;

        SELECT MAX(CAST(LEFT(NUMBER, 5) AS DM_BIGINT))
        FROM DOCUMENTS
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.CODE = :P_CODE AND DOCUMENTS.INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE
        INTO :MAX_NUMBER;

        IF(MAX_NUMBER IS NULL)THEN MAX_NUMBER = 0;

        SELECT CURRENT_NUMBER
        FROM DOCUMENT_TEAM_NUMBER
        WHERE DOCUMENT_TEAM_NUMBER.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_NUMBER.CODE = :P_CODE AND
        DOCUMENT_TEAM_NUMBER.DOCUMENT_CODE_CYCLE = :DOCUMENT_CODE_CYCLE AND DOCUMENT_TEAM_NUMBER.TIME_1 = :TIME_1 AND DOCUMENT_TEAM_NUMBER.TIME_2 = :TIME_2
        WITH LOCK
        INTO :CURRENT_NUMBER;

        IF(CURRENT_NUMBER IS NULL OR CURRENT_NUMBER <> MAX_NUMBER)THEN
        BEGIN
            UPDATE OR INSERT INTO DOCUMENT_TEAM_NUMBER(COMPANY, CODE, DOCUMENT_CODE_CYCLE, TIME_1, TIME_2, CURRENT_NUMBER)
            VALUES(:P_COMPANY, :P_CODE, :DOCUMENT_CODE_CYCLE, :TIME_1, :TIME_2, :MAX_NUMBER);
        END
    END
END ^

ALTER PROCEDURE DOCUMENT_TEAM_S_DEFAULT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (DEFAULT_OBJECT DM_ID,
DEFAULT_CONTENT DM_CONTENT)
AS 
BEGIN
  SELECT DEFAULT_OBJECT, DEFAULT_CONTENT
  FROM DOCUMENT_TEAMS
  JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_TEAM_STRINGS.ID = :P_ID
  WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = :P_ID
  INTO :DEFAULT_OBJECT, :DEFAULT_CONTENT;

  SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_TEAM_S_DEFAULT_DOUBLE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (DEBIT_DEFAULT_ACCOUNT DM_ID,
CREDIT_DEFAULT_ACCOUNT DM_ID)
AS 
BEGIN
  SELECT DEBIT_DEFAULT_ACCOUNT, CREDIT_DEFAULT_ACCOUNT
  FROM DOCUMENT_TEAMS
  WHERE COMPANY = :P_COMPANY AND ID = :P_ID
  INTO :DEBIT_DEFAULT_ACCOUNT, :CREDIT_DEFAULT_ACCOUNT;

  IF(DEBIT_DEFAULT_ACCOUNT IS NOT NULL AND EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = :DEBIT_DEFAULT_ACCOUNT))THEN
    DEBIT_DEFAULT_ACCOUNT = NULL;

  IF(CREDIT_DEFAULT_ACCOUNT IS NOT NULL AND EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = :CREDIT_DEFAULT_ACCOUNT))THEN
    CREDIT_DEFAULT_ACCOUNT = NULL;

  SUSPEND;
END ^

