    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = :P_ID
    INTO :DEFAULT_INVOICE_TYPE, :DEFAULT_GOODS_INPUT_INVOICE, :DEFAULT_GOODS_OUTPUT_INVOICE ;

