ALTER PROCEDURE DOCUMENT_TEAM_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
ADDITION_INFO1 DM_CAPTION,
ADDITION_INFO2 DM_CAPTION,
ADDITION_INFO3 DM_CAPTION,
ADDITION_INFO4 DM_CAPTION,
ATOM_TYPE DM_ID,
ATOM_NAME DM_NAME,
ATOM_USE_OTHER_NAME DM_BOOL,
DOUBLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
SINGLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
CREDIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
DEBIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
INVOICE_COPY_PROPERTIES DM_INVOICE_PROPERTIES,
OTHER_COPY_PROPERTIES DM_OTHER_PROPERTIES,
SINGLE_COPY_PROPERTIES DM_COPY_PROPERTIES,
CREDIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
CREDIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
DEBIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
DEBIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
CREDIT_DEFAULT_ACCOUNT DM_ID,
DEBIT_DEFAULT_ACCOUNT DM_ID,
SINGLE_DEFAULT_ACCOUNT DM_ID,
DEFAULT_INVOICE_TYPE DM_INTEGER,
DEFAULT_CONTENT DM_CONTENT,
DEFAULT_OBJECT DM_ID,
IS_ACTIVE_OBJECT DM_BOOL,
MUST_HAVE_OBJECT DM_BOOL,
TYPES DM_DOCUMENT_TEAM_TYPES,
DEFAULT_CODE DM_CODE,
EMPLOYEE_CAPTION DM_CAPTION,
PERSON_NAME_CAPTION DM_CAPTION,
DEFAULT_GOODS_INPUT_INVOICE DM_GOODS,
DEFAULT_GOODS_OUTPUT_INVOICE DM_GOODS)
AS 
BEGIN
  FOR
    SELECT DOCUMENT_TEAMS.ID, ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        ADDITION_INFO1,
        ADDITION_INFO2,
        ADDITION_INFO3,
        ADDITION_INFO4,
        ATOM_TYPE,
        ATOM_NAME,
        ATOM_USE_OTHER_NAME,
        DOUBLE_AUTO_CALCULATION,
        SINGLE_AUTO_CALCULATION,
        CREDIT_COPY_PROPERTIES,
        DEBIT_COPY_PROPERTIES,
        INVOICE_COPY_PROPERTIES,
        OTHER_COPY_PROPERTIES,
        SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS,
        CREDIT_STARTING_ACCOUNTS,
        DEBIT_NOT_STARTING_ACCOUNTS,
        DEBIT_STARTING_ACCOUNTS,
        CREDIT_DEFAULT_ACCOUNT,
        DEBIT_DEFAULT_ACCOUNT,
        SINGLE_DEFAULT_ACCOUNT,
        DEFAULT_INVOICE_TYPE,
        DEFAULT_OBJECT,
        IS_ACTIVE_OBJECT,
        MUST_HAVE_OBJECT,
        DEFAULT_CONTENT,
        TYPES,
        DEFAULT_CODE,
        EMPLOYEE_CAPTION,
        PERSON_NAME_CAPTION,
        DEFAULT_GOODS_INPUT_INVOICE,
        DEFAULT_GOODS_OUTPUT_INVOICE
    FROM DOCUMENT_TEAMS
    JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_TEAM_STRINGS.ID = DOCUMENT_TEAMS.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEAMS.ID
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :ADDITION_INFO1,
        :ADDITION_INFO2,
        :ADDITION_INFO3,
        :ADDITION_INFO4,
        :ATOM_TYPE,
        :ATOM_NAME,
        :ATOM_USE_OTHER_NAME,
        :DOUBLE_AUTO_CALCULATION,
        :SINGLE_AUTO_CALCULATION,
        :CREDIT_COPY_PROPERTIES,
        :DEBIT_COPY_PROPERTIES,
        :INVOICE_COPY_PROPERTIES,
        :OTHER_COPY_PROPERTIES,
        :SINGLE_COPY_PROPERTIES,
        :CREDIT_NOT_STARTING_ACCOUNTS,
        :CREDIT_STARTING_ACCOUNTS,
        :DEBIT_NOT_STARTING_ACCOUNTS,
        :DEBIT_STARTING_ACCOUNTS,
        :CREDIT_DEFAULT_ACCOUNT,
        :DEBIT_DEFAULT_ACCOUNT,
        :SINGLE_DEFAULT_ACCOUNT,
        :DEFAULT_INVOICE_TYPE,
        :DEFAULT_OBJECT,
        :IS_ACTIVE_OBJECT,
        :MUST_HAVE_OBJECT,
        :DEFAULT_CONTENT,
        :TYPES,
        :DEFAULT_CODE,
        :EMPLOYEE_CAPTION,
        :PERSON_NAME_CAPTION,
        :DEFAULT_GOODS_INPUT_INVOICE,
        :DEFAULT_GOODS_OUTPUT_INVOICE
  DO
      SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_TEAM_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
TEAM_NAME DM_NAME,
DOUBLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
SINGLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
CREDIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
DEBIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
INVOICE_COPY_PROPERTIES DM_INVOICE_PROPERTIES,
OTHER_COPY_PROPERTIES DM_OTHER_PROPERTIES,
SINGLE_COPY_PROPERTIES DM_COPY_PROPERTIES,
CREDIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
CREDIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
DEBIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
DEBIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
IS_ACTIVE_OBJECT DM_BOOL,
MUST_HAVE_OBJECT DM_BOOL,
ATOM_TYPE DM_ID,
ATOM_NAME DM_NAME,
ADDITION_INFO1 DM_CAPTION,
ADDITION_INFO2 DM_CAPTION,
ADDITION_INFO3 DM_CAPTION,
ADDITION_INFO4 DM_CAPTION,
TYPES DM_DOCUMENT_TEAM_TYPES,
RIGHTS DM_RIGHTS,
EMPLOYEE_CAPTION DM_CAPTION,
PERSON_NAME_CAPTION DM_CAPTION)
AS 
DECLARE VARIABLE ATOM_USE_OTHER_NAME DM_BOOL;
DECLARE VARIABLE RIGHTS_TEMP DM_RIGHTS;
BEGIN
  FOR
    SELECT DOCUMENT_TEAMS.ID, ATOMS.CODE, ATOM_STRINGS.NAME, TEAM_ATOM_STRINGS.NAME,
        DOUBLE_AUTO_CALCULATION, SINGLE_AUTO_CALCULATION, CREDIT_COPY_PROPERTIES, DEBIT_COPY_PROPERTIES, INVOICE_COPY_PROPERTIES, OTHER_COPY_PROPERTIES, SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS, CREDIT_STARTING_ACCOUNTS, DEBIT_NOT_STARTING_ACCOUNTS, DEBIT_STARTING_ACCOUNTS,
        IS_ACTIVE_OBJECT, MUST_HAVE_OBJECT, ATOM_TYPE, ATOM_NAME, ATOM_USE_OTHER_NAME, ADDITION_INFO1, ADDITION_INFO2, ADDITION_INFO3, ADDITION_INFO4,
        TYPES, EMPLOYEE_CAPTION, PERSON_NAME_CAPTION
    FROM DOCUMENT_TEAMS
    JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.ID = DOCUMENT_TEAMS.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEAMS.ID AND ATOMS.HIDE = 0
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    LEFT JOIN ATOM_STRINGS TEAM_ATOM_STRINGS ON TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_ATOM_STRINGS.ID = ATOMS.TEAM
    LEFT JOIN PROTONS TEAM_PROTONS ON TEAM_PROTONS.COMPANY = :P_COMPANY AND TEAM_PROTONS.ID = ATOMS.TEAM
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND
        EXISTS
        (
            SELECT GRANTS.ID
            FROM MEMBERSHIPS
            JOIN GRANTS ON GRANTS.COMPANY = :P_COMPANY AND GRANTS.ROLE_ID = MEMBERSHIPS.ROLE_ID AND GRANTS.ATOM = DOCUMENT_TEAMS.ID
            WHERE MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT
        )
    ORDER BY TEAM_PROTONS.ORDINAL, PROTONS.ORDINAL
    INTO :ID, :CODE, :NAME, :TEAM_NAME,
    :DOUBLE_AUTO_CALCULATION, :SINGLE_AUTO_CALCULATION, :CREDIT_COPY_PROPERTIES, :DEBIT_COPY_PROPERTIES, :INVOICE_COPY_PROPERTIES, :OTHER_COPY_PROPERTIES, :SINGLE_COPY_PROPERTIES,
    :CREDIT_NOT_STARTING_ACCOUNTS, :CREDIT_STARTING_ACCOUNTS, :DEBIT_NOT_STARTING_ACCOUNTS, :DEBIT_STARTING_ACCOUNTS,
    :IS_ACTIVE_OBJECT, :MUST_HAVE_OBJECT, :ATOM_TYPE, :ATOM_NAME, :ATOM_USE_OTHER_NAME, :ADDITION_INFO1, :ADDITION_INFO2, :ADDITION_INFO3, :ADDITION_INFO4,
    :TYPES, :EMPLOYEE_CAPTION, :PERSON_NAME_CAPTION
  DO
  BEGIN
    RIGHTS = 0;

    FOR
        SELECT GRANTS.RIGHTS
        FROM GRANTS
        JOIN MEMBERSHIPS ON MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT AND GRANTS.ROLE_ID = MEMBERSHIPS.ROLE_ID
        WHERE GRANTS.COMPANY = :P_COMPANY AND GRANTS.ATOM = :ID
        INTO :RIGHTS_TEMP
    DO
        RIGHTS = BIN_OR(RIGHTS, RIGHTS_TEMP);

    IF(ATOM_TYPE IS NOT NULL)THEN
    BEGIN
        IF(ATOM_USE_OTHER_NAME = 0)THEN
            SELECT NAME
            FROM OBJECT_TYPES
            WHERE OBJECT_TYPES.ID = :ATOM_TYPE
            INTO :ATOM_NAME;
    END

    SUSPEND;
  END
END ^

ALTER PROCEDURE DOCUMENT_TEAM_S_RS_BY_DOCUMENT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID,
P_DOCUMENT DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
TEAM_NAME DM_NAME,
DOUBLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
SINGLE_AUTO_CALCULATION DM_AUTO_CALCULATION,
CREDIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
DEBIT_COPY_PROPERTIES DM_COPY_PROPERTIES,
INVOICE_COPY_PROPERTIES DM_INVOICE_PROPERTIES,
OTHER_COPY_PROPERTIES DM_OTHER_PROPERTIES,
SINGLE_COPY_PROPERTIES DM_COPY_PROPERTIES,
CREDIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
CREDIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
DEBIT_NOT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
DEBIT_STARTING_ACCOUNTS DM_STARTING_WITH_ACCOUNT,
IS_ACTIVE_OBJECT DM_BOOL,
MUST_HAVE_OBJECT DM_BOOL,
ATOM_TYPE DM_ID,
ATOM_NAME DM_NAME,
ADDITION_INFO1 DM_CAPTION,
ADDITION_INFO2 DM_CAPTION,
ADDITION_INFO3 DM_CAPTION,
ADDITION_INFO4 DM_CAPTION,
TYPES DM_DOCUMENT_TEAM_TYPES,
RIGHTS DM_RIGHTS,
EMPLOYEE_CAPTION DM_CAPTION,
PERSON_NAME_CAPTION DM_CAPTION)
AS 
DECLARE VARIABLE ATOM_USE_OTHER_NAME DM_BOOL;
DECLARE VARIABLE RIGHTS_TEMP DM_RIGHTS;
DECLARE VARIABLE DOCUMENT_TEAM DM_ID;
BEGIN
  SELECT DOCUMENTS.TEAM
  FROM DOCUMENTS
  WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_DOCUMENT
  INTO :DOCUMENT_TEAM;

  IF(DOCUMENT_TEAM IS NOT NULL)THEN
  BEGIN

  FOR
    SELECT DOCUMENT_TEAMS.ID, ATOMS.CODE, ATOM_STRINGS.NAME, TEAM_ATOM_STRINGS.NAME,
        DOUBLE_AUTO_CALCULATION, SINGLE_AUTO_CALCULATION, CREDIT_COPY_PROPERTIES, DEBIT_COPY_PROPERTIES, INVOICE_COPY_PROPERTIES, OTHER_COPY_PROPERTIES, SINGLE_COPY_PROPERTIES,
        CREDIT_NOT_STARTING_ACCOUNTS, CREDIT_STARTING_ACCOUNTS, DEBIT_NOT_STARTING_ACCOUNTS, DEBIT_STARTING_ACCOUNTS,
        IS_ACTIVE_OBJECT, MUST_HAVE_OBJECT, ATOM_TYPE, ATOM_NAME, ATOM_USE_OTHER_NAME, ADDITION_INFO1, ADDITION_INFO2, ADDITION_INFO3, ADDITION_INFO4,
        TYPES, EMPLOYEE_CAPTION, PERSON_NAME_CAPTION
    FROM DOCUMENT_TEAMS
    JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.ID = DOCUMENT_TEAMS.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEAMS.ID AND ATOMS.HIDE = 0
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    LEFT JOIN ATOM_STRINGS TEAM_ATOM_STRINGS ON TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_ATOM_STRINGS.ID = ATOMS.TEAM
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = :DOCUMENT_TEAM AND
        EXISTS
        (
            SELECT GRANTS.ID
            FROM MEMBERSHIPS
            JOIN GRANTS ON GRANTS.COMPANY = :P_COMPANY AND GRANTS.ROLE_ID = MEMBERSHIPS.ROLE_ID AND GRANTS.ATOM = DOCUMENT_TEAMS.ID
            WHERE MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT
        )
    ORDER BY ORDINAL
    INTO :ID, :CODE, :NAME, :TEAM_NAME,
    :DOUBLE_AUTO_CALCULATION, :SINGLE_AUTO_CALCULATION, :CREDIT_COPY_PROPERTIES, :DEBIT_COPY_PROPERTIES, :INVOICE_COPY_PROPERTIES, :OTHER_COPY_PROPERTIES, :SINGLE_COPY_PROPERTIES,
    :CREDIT_NOT_STARTING_ACCOUNTS, :CREDIT_STARTING_ACCOUNTS, :DEBIT_NOT_STARTING_ACCOUNTS, :DEBIT_STARTING_ACCOUNTS,
    :IS_ACTIVE_OBJECT, :MUST_HAVE_OBJECT, :ATOM_TYPE, :ATOM_NAME, :ATOM_USE_OTHER_NAME, :ADDITION_INFO1, :ADDITION_INFO2, :ADDITION_INFO3, :ADDITION_INFO4,
    :TYPES, :EMPLOYEE_CAPTION, :PERSON_NAME_CAPTION
  DO
  BEGIN
    RIGHTS = 0;

    FOR
        SELECT GRANTS.RIGHTS
        FROM GRANTS
        JOIN MEMBERSHIPS ON MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT AND GRANTS.ROLE_ID = MEMBERSHIPS.ROLE_ID
        WHERE GRANTS.COMPANY = :P_COMPANY AND GRANTS.ATOM = :ID
        INTO :RIGHTS_TEMP
    DO
        RIGHTS = BIN_OR(RIGHTS, RIGHTS_TEMP);

    IF(ATOM_TYPE IS NOT NULL)THEN
    BEGIN
        IF(ATOM_USE_OTHER_NAME = 0)THEN
            SELECT NAME
            FROM OBJECT_TYPES
            WHERE OBJECT_TYPES.ID = :ATOM_TYPE
            INTO :ATOM_NAME;
    END

    SUSPEND;
  END

  END
END ^

ALTER PROCEDURE DOCUMENT_TEAM_S_RS_TYPE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TYPES DM_DOCUMENT_TEAM_TYPES,
P_OBJECT_TYPE DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME)
AS 
BEGIN
    
    FOR
        SELECT ATOMS.ID, CODE, NAME
        FROM DOCUMENT_TEAMS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.ID = DOCUMENT_TEAMS.ID AND ATOMS.HIDE = 0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND BIN_AND(DOCUMENT_TEAMS.TYPES, :P_TYPES) <> 0
        ORDER BY CODE
        INTO :ID, :CODE, :NAME
    DO
        SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_TEAM_TEMPLATE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_DOCUMENT_TEAM DM_ID,
P_DOCUMENT_TEMPLATE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY,:P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO DOCUMENT_TEAM_TEMPLATE(COMPANY, ID, DOCUMENT_TEAM, DOCUMENT_TEMPLATE)
    VALUES(:P_COMPANY, :P_ID, :P_DOCUMENT_TEAM, :P_DOCUMENT_TEMPLATE);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE DOCUMENT_TEAM_TEMPLATE_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT_TEAM DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
DOCUMENT_TEMPLATE DM_ID)
AS 
begin
FOR
  SELECT DOCUMENT_TEAM_TEMPLATE.ID, NOTE, ORDINAL, DOCUMENT_TEAM_TEMPLATE.DOCUMENT_TEMPLATE
  FROM DOCUMENT_TEAM_TEMPLATE
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = DOCUMENT_TEAM_TEMPLATE.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE DOCUMENT_TEAM_TEMPLATE.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_TEMPLATE.DOCUMENT_TEAM = :P_DOCUMENT_TEAM
  INTO :ID, :NOTE, :ORDINAL, :DOCUMENT_TEMPLATE
DO
    SUSPEND;
end ^

ALTER PROCEDURE DOCUMENT_TEAM_TEMPLATE_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT_TEAM DM_ID)
RETURNS (ID DM_ID,
NAME DM_NAME)
AS 
BEGIN
FOR
    SELECT DOCUMENT_TEMPLATES.ID, NAME
    FROM DOCUMENT_TEAM_TEMPLATE
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = DOCUMENT_TEAM_TEMPLATE.ID
    JOIN DOCUMENT_TEMPLATES ON DOCUMENT_TEMPLATES.COMPANY = :P_COMPANY AND DOCUMENT_TEMPLATES.ID = DOCUMENT_TEAM_TEMPLATE.DOCUMENT_TEMPLATE AND DOCUMENT_TEMPLATES.LANGUAGE = :P_LANGUAGE
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = DOCUMENT_TEMPLATES.ID
    WHERE DOCUMENT_TEAM_TEMPLATE.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_TEMPLATE.DOCUMENT_TEAM = :P_DOCUMENT_TEAM
    ORDER BY PROTONS.ORDINAL DESC, DOCUMENT_TEAM_TEMPLATE.ID
    INTO :ID, :NAME
DO
    SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_TEMPLATE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_TEMPLATE_FILE DM_FILE_NAME,
P_TOP_MARGIN DM_INTEGER,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO DOCUMENT_TEMPLATES(COMPANY, ID, LANGUAGE, TEMPLATE_FILE, TOP_MARGIN) VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_TEMPLATE_FILE, :P_TOP_MARGIN);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE DOCUMENT_TEMPLATE_PROCEDURE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_DOCUMENT_TEMPLATE DM_ID,
P_PROCEDURE_NAME DM_PROCEDURE_NAME,
P_NUMBER_TO_TEXT_FIELD DM_FIELD_CODE)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO DOCUMENT_TEMPLATE_PROCEDURES(COMPANY, ID, CODE, PROCEDURE_NAME, DOCUMENT_TEMPLATE, NUMBER_TO_TEXT_FIELD)
    VALUES(:P_COMPANY, :P_ID, :P_CODE, :P_PROCEDURE_NAME, :P_DOCUMENT_TEMPLATE, :P_NUMBER_TO_TEXT_FIELD);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE DOCUMENT_TEMPLATE_PROCEDURE_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT_TEMPLATE DM_ID)
RETURNS (CODE DM_CODE,
PROCEDURE_NAME DM_PROCEDURE_NAME,
NUMBER_TO_TEXT_FIELD DM_FIELD_CODE)
