    INTO :CODE, :PROCEDURE_NAME, :NUMBER_TO_TEXT_FIELD
DO
    suspend;
END ^

ALTER PROCEDURE DOCUMENT_TEMPLATE_PROCEDURE_SEC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT_TEMPLATE DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
