ALTER PROCEDURE DOCUMENT_TEMPLATE_SIGNATURE_SEC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT_TEMPLATE DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
TITLE DM_NAME,
CODE DM_NAME)
AS 
BEGIN
FOR
  SELECT DOCUMENT_TEMPLATE_SIGNATURES.ID, NOTE, ORDINAL, TITLE, code
  FROM DOCUMENT_TEMPLATE_SIGNATURES
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = DOCUMENT_TEMPLATE_SIGNATURES.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE DOCUMENT_TEMPLATE_SIGNATURES.COMPANY = :P_COMPANY AND DOCUMENT_TEMPLATE_SIGNATURES.DOCUMENT_TEMPLATE = :P_DOCUMENT_TEMPLATE
  INTO :ID, :NOTE, :ORDINAL, :title, :code
DO
    SUSPEND;
END ^

ALTER PROCEDURE DOCUMENT_TEMPLATE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
TEMPLATE_FILE DM_FILE_NAME,
TOP_MARGIN DM_INTEGER)
AS 
BEGIN
    FOR
        SELECT DOCUMENT_TEMPLATES.ID,ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, TEMPLATE_FILE, TOP_MARGIN
        FROM DOCUMENT_TEMPLATES
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEMPLATES.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE DOCUMENT_TEMPLATES.COMPANY = :P_COMPANY
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :TEMPLATE_FILE, :TOP_MARGIN
    DO
    SUSPEND;
END ^

ALTER PROCEDURE DOUBLE_ENTRY_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CURRENCY DM_ID,
P_DOCUMENT DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_VAT_PERCENT DM_DOUBLE,
P_APPORTION DM_APPORTION,
P_LOT_NUMBER DM_CODE,
P_EXPIRY_DATE DM_DATE,
P_CONTENT DM_CONTENT,
P_DEBIT_ID DM_ID,
P_DEBIT_ACCOUNT DM_ID,
P_DEBIT_OBJECT0 DM_ID,
P_DEBIT_OBJECT1 DM_ID,
P_DEBIT_OBJECT2 DM_ID,
P_CREDIT_ID DM_ID,
P_CREDIT_ACCOUNT DM_ID,
P_CREDIT_OBJECT0 DM_ID,
P_CREDIT_OBJECT1 DM_ID,
P_CREDIT_OBJECT2 DM_ID,
P_AMOUNT DM_DOUBLE,
P_PRICE DM_DOUBLE,
P_FOREIGN_SUM_OF_MONEY DM_DOUBLE,
P_OFFICIAL_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
DECLARE VARIABLE COST_PRICE_ACCOUNT DM_ID;
DECLARE VARIABLE GOODS_ACCOUNT DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE SOURCE_DOCUMENT_CODE DM_CODE;
DECLARE VARIABLE SOURCE_DOCUMENT_CONTENT DM_CONTENT;
DECLARE VARIABLE DEFAULT_CONTENT DM_CONTENT;
DECLARE VARIABLE ENTRY_CONTENT DM_CONTENT;
DECLARE VARIABLE DOCUMENT_TEAM DM_ID;
DECLARE VARIABLE COST_PRICE_DOCUMENT DM_ID;
DECLARE VARIABLE EMPLOYEE DM_ID;
DECLARE VARIABLE PERSON_NAME DM_PERSON_NAME;
DECLARE VARIABLE PERSON_ADDRESS DM_ADDRESS;
DECLARE VARIABLE DOCUMENT_CODE DM_CODE;
DECLARE VARIABLE DOCUMENT_NUMBER DM_CODE;
DECLARE VARIABLE DOCUMENT_INPUT_DATE DM_DATE;
DECLARE VARIABLE DOCUMENT_VOUCHER_DATE DM_DATE;
DECLARE VARIABLE DOCUMENT_PERIOD DM_ID;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE ENTRY DM_ID;
DECLARE VARIABLE DEBIT_ID DM_ID;
DECLARE VARIABLE CREDIT_ID DM_ID;
DECLARE VARIABLE WAREHOUSE_AMOUNT DM_DOUBLE;
DECLARE VARIABLE WAREHOUSE_PRICE DM_DOUBLE;
DECLARE VARIABLE WAREHOUSE_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE DELETE_ENTRY DM_ID;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    IF(P_DEBIT_ACCOUNT IS NOT NULL AND P_DEBIT_OBJECT0 IS NOT NULL AND P_DEBIT_OBJECT1 IS NOT NULL AND EXISTS(
        SELECT DECREASE_ENTRIES.CREDIT_DEBIT
        FROM DECREASE_ENTRIES
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = DECREASE_ENTRIES.CREDIT_DEBIT AND (CREDIT.ACCOUNT <> :P_DEBIT_ACCOUNT OR CREDIT.OBJECT0 <> :P_DEBIT_OBJECT0 OR CREDIT.OBJECT1 <> :P_DEBIT_OBJECT1)
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.INCREASE_ENTRY = :P_ID
    ))THEN
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = 6 AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT;
    END
    ELSE
    BEGIN
        EXECUTE PROCEDURE ENTRY_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CONTENT);

        UPDATE OR INSERT INTO ENTRIES(COMPANY, ID, DOCUMENT, CURRENCY, EXCHANGE_RATE, VAT_PERCENT, ENTRY_TYPE, APPORTION, EXPIRY_DATE, LOT_NUMBER)
        VALUES(:P_COMPANY, :P_ID, :P_DOCUMENT, :P_CURRENCY, :P_EXCHANGE_RATE, :P_VAT_PERCENT, 1, :P_APPORTION, :P_EXPIRY_DATE, :P_LOT_NUMBER);

        UPDATE OR INSERT INTO CREDIT_DEBIT(COMPANY, ID, ENTRY, SIDE, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, FOREIGN_SUM_OF_MONEY, OFFICIAL_SUM_OF_MONEY)
        VALUES(:P_COMPANY, :P_DEBIT_ID, :P_ID, 0, :P_DEBIT_ACCOUNT, :P_DEBIT_OBJECT0, :P_DEBIT_OBJECT1, :P_DEBIT_OBJECT2, :P_AMOUNT, :P_PRICE, :P_FOREIGN_SUM_OF_MONEY, :P_OFFICIAL_SUM_OF_MONEY);

        UPDATE OR INSERT INTO CREDIT_DEBIT(COMPANY, ID, ENTRY, SIDE, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, FOREIGN_SUM_OF_MONEY, OFFICIAL_SUM_OF_MONEY)
        VALUES(:P_COMPANY, :P_CREDIT_ID, :P_ID, 1, :P_CREDIT_ACCOUNT, :P_CREDIT_OBJECT0, :P_CREDIT_OBJECT1, :P_CREDIT_OBJECT2, :P_AMOUNT, :P_PRICE, :P_FOREIGN_SUM_OF_MONEY, :P_OFFICIAL_SUM_OF_MONEY);

        IF(P_AMOUNT > 0)THEN
        BEGIN
            HAS_VALUE = 0;
            FOR
                SELECT FIRST 1 COST_PRICE_ACCOUNT, DOCUMENT_TEAM, DEFAULT_CONTENT
                FROM COST_PRICE_DEFINES
                WHERE COMPANY = :P_COMPANY AND ENABLED = 1 AND REVENUE_ACCOUNT = :P_CREDIT_ACCOUNT
                INTO :COST_PRICE_ACCOUNT, :DOCUMENT_TEAM, :DEFAULT_CONTENT
            DO
            BEGIN
                
                IF(DEFAULT_CONTENT IS NULL)THEN DEFAULT_CONTENT = '';

                SELECT FIRST 1 COST_PRICE_ENTRIES.DOCUMENT
                FROM ENTRIES COST_PRICE_ENTRIES
                
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = COST_PRICE_ENTRIES.DOCUMENT AND DOCUMENTS.TEAM = :DOCUMENT_TEAM
                JOIN ENTRIES REVENUE_ENTRIES ON REVENUE_ENTRIES.COMPANY = :P_COMPANY AND COST_PRICE_ENTRIES.REVENUE_ENTRY = REVENUE_ENTRIES.ID AND REVENUE_ENTRIES.DOCUMENT = :P_DOCUMENT
                WHERE COST_PRICE_ENTRIES.COMPANY = :P_COMPANY
                INTO :COST_PRICE_DOCUMENT;

                SELECT INPUT_DATE, VOUCHER_DATE, PERIOD
                FROM DOCUMENTS
                WHERE COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_DOCUMENT
                INTO :DOCUMENT_INPUT_DATE, :DOCUMENT_VOUCHER_DATE, :DOCUMENT_PERIOD;

                IF(COST_PRICE_DOCUMENT IS NULL)THEN
                BEGIN
                    SELECT CODE || '-' || NUMBER, CONTENT, DOCUMENTS.EMPLOYEE, DOCUMENT_STRINGS.PERSON_NAME, DOCUMENT_STRINGS.PERSON_ADDRESS
                    FROM DOCUMENTS
                    JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = :P_DOCUMENT
                    JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = :P_DOCUMENT
                    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_DOCUMENT
                    INTO :SOURCE_DOCUMENT_CODE, :SOURCE_DOCUMENT_CONTENT, :EMPLOYEE, :PERSON_NAME, :PERSON_ADDRESS;

                    IF(SOURCE_DOCUMENT_CONTENT IS NULL)THEN SOURCE_DOCUMENT_CONTENT = '';
                    IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
                    BEGIN
                        IF(SOURCE_DOCUMENT_CONTENT <> '')THEN
                            SOURCE_DOCUMENT_CONTENT = DEFAULT_CONTENT || ', ' || :SOURCE_DOCUMENT_CONTENT;
                        ELSE
                            SOURCE_DOCUMENT_CONTENT = DEFAULT_CONTENT;
                    END

                    SELECT CODE, NUMBER
                    FROM CMD_MADE_DOCUMENT_CODE(:P_COMPANY, :DOCUMENT_TEAM, :DOCUMENT_INPUT_DATE)
                    INTO :DOCUMENT_CODE, :DOCUMENT_NUMBER;

                    COST_PRICE_DOCUMENT = GEN_ID(UNIVERSE, 1);
                    EXECUTE PROCEDURE DOCUMENT_IU(:P_LANGUAGE, :P_COMPANY, :COST_PRICE_DOCUMENT, NULL, 0, NULL, NULL, NULL, NULL, :DOCUMENT_CODE, :DOCUMENT_NUMBER, :P_CURRENCY,  :P_EXCHANGE_RATE, :DOCUMENT_INPUT_DATE, NULL, :SOURCE_DOCUMENT_CODE, :DOCUMENT_PERIOD, :DOCUMENT_TEAM, :DOCUMENT_VOUCHER_DATE, :EMPLOYEE, :PERSON_NAME, :PERSON_ADDRESS, :SOURCE_DOCUMENT_CONTENT, 0, 0);
                END

                IF(EXISTS (SELECT 1 FROM ENTRIES WHERE COMPANY = :P_COMPANY AND ENTRIES.REVENUE_ENTRY = :P_ID))THEN
                BEGIN
                    SELECT ENTRIES.ID, DEBIT.ID, CREDIT.ID
                    FROM ENTRIES
                    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
                    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.REVENUE_ENTRY = :P_ID
                    INTO :ENTRY, :DEBIT_ID, :CREDIT_ID;

                    FOR
                        SELECT GOODS_ACCOUNT, WAREHOUSE
                        FROM COST_PRICE_DEFINES
                        WHERE COMPANY = :P_COMPANY AND ENABLED = 1 AND REVENUE_ACCOUNT = :P_CREDIT_ACCOUNT
                        INTO :GOODS_ACCOUNT, :WAREHOUSE
                    DO
                    BEGIN
                        SELECT CMD_GET_PRICE.AMOUNT, CMD_GET_PRICE.PRICE, CMD_GET_PRICE.SUM_OF_MONEY
                        FROM CMD_GET_PRICE(:P_COMPANY, :GOODS_ACCOUNT, :P_CREDIT_OBJECT0, :WAREHOUSE, :DOCUMENT_INPUT_DATE, :COST_PRICE_DOCUMENT, :ENTRY)
                        INTO :WAREHOUSE_AMOUNT, :WAREHOUSE_PRICE, :WAREHOUSE_SUM_OF_MONEY;

                        WAREHOUSE_AMOUNT = ROUND(WAREHOUSE_AMOUNT, NUMBER_DECIMAL_DIGITS);
                        P_AMOUNT = ROUND(P_AMOUNT, NUMBER_DECIMAL_DIGITS);

                        IF(WAREHOUSE_AMOUNT >= P_AMOUNT)THEN
                        BEGIN
                            IF(WAREHOUSE_AMOUNT > P_AMOUNT)THEN
                                WAREHOUSE_SUM_OF_MONEY = ROUND(P_AMOUNT*WAREHOUSE_PRICE, 0);

                            IF(P_CONTENT IS NULL OR P_CONTENT = '')THEN
                                ENTRY_CONTENT = SOURCE_DOCUMENT_CONTENT;
                            ELSE IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
                                ENTRY_CONTENT = DEFAULT_CONTENT || ', ' || P_CONTENT;
                            ELSE
                                ENTRY_CONTENT = P_CONTENT;

                            HAS_VALUE = 1;
                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, :ENTRY, NULL, 0, :P_CURRENCY, :COST_PRICE_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, :DEBIT_ID, :COST_PRICE_ACCOUNT, NULL, NULL, NULL, :CREDIT_ID, :GOODS_ACCOUNT, :P_CREDIT_OBJECT0, :WAREHOUSE, NULL, :P_AMOUNT, :WAREHOUSE_PRICE, 0, :WAREHOUSE_SUM_OF_MONEY);
                            BREAK;
                        END
                    END

                    IF(HAS_VALUE = 0)THEN
                    BEGIN
                        SELECT TITLE || '\$' || CONTENT || ATOMS.CODE || '(' || ROUND(:WAREHOUSE_AMOUNT, :NUMBER_DECIMAL_DIGITS) || ')'
                        FROM MESSAGES
                        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDIT_OBJECT0
                        WHERE MESSAGES.ID = 9 AND MESSAGES.LANGUAGE = :P_LANGUAGE
                        INTO :MESSAGE_CONTENT;

                        EXCEPTION EX_GENERAL MESSAGE_CONTENT;
                    END
                END
                ELSE
                BEGIN
                    FOR
                        SELECT GOODS_ACCOUNT, WAREHOUSE
                        FROM COST_PRICE_DEFINES
                        WHERE COMPANY = :P_COMPANY AND ENABLED = 1 AND REVENUE_ACCOUNT = :P_CREDIT_ACCOUNT
                        INTO :GOODS_ACCOUNT, :WAREHOUSE
                    DO
                    BEGIN
                        SELECT CMD_GET_PRICE.AMOUNT, CMD_GET_PRICE.PRICE, CMD_GET_PRICE.SUM_OF_MONEY
                        FROM CMD_GET_PRICE(:P_COMPANY, :GOODS_ACCOUNT, :P_CREDIT_OBJECT0, :WAREHOUSE, :DOCUMENT_INPUT_DATE, :COST_PRICE_DOCUMENT, :ENTRY)
                        INTO :WAREHOUSE_AMOUNT, :WAREHOUSE_PRICE, :WAREHOUSE_SUM_OF_MONEY;

                        WAREHOUSE_AMOUNT = ROUND(WAREHOUSE_AMOUNT, NUMBER_DECIMAL_DIGITS);
                        P_AMOUNT = ROUND(P_AMOUNT, NUMBER_DECIMAL_DIGITS);

                        IF(WAREHOUSE_AMOUNT >= P_AMOUNT)THEN
                        BEGIN
                            ENTRY = GEN_ID(UNIVERSE, 1);
                            IF(WAREHOUSE_AMOUNT > P_AMOUNT)THEN
                                WAREHOUSE_SUM_OF_MONEY = ROUND(P_AMOUNT*WAREHOUSE_PRICE, 0);

                            IF(P_CONTENT IS NULL OR P_CONTENT = '')THEN
                                ENTRY_CONTENT = SOURCE_DOCUMENT_CONTENT;
                            ELSE IF(DEFAULT_CONTENT IS NOT NULL AND DEFAULT_CONTENT <> '')THEN
                                ENTRY_CONTENT = DEFAULT_CONTENT || ', ' || P_CONTENT;
                            ELSE
                                ENTRY_CONTENT = P_CONTENT;
                        
                            HAS_VALUE = 1;
                            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(:P_LANGUAGE, :P_COMPANY, :ENTRY, NULL, 0, :P_CURRENCY, :COST_PRICE_DOCUMENT, :P_EXCHANGE_RATE, NULL, 0, NULL, NULL, :ENTRY_CONTENT, GEN_ID(UNIVERSE, 1), :COST_PRICE_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), :GOODS_ACCOUNT, :P_CREDIT_OBJECT0, :WAREHOUSE, NULL, :P_AMOUNT, :WAREHOUSE_PRICE, 0, :WAREHOUSE_SUM_OF_MONEY);
                            UPDATE ENTRIES
                            SET REVENUE_ENTRY = :P_ID
                            WHERE COMPANY = :P_COMPANY AND ENTRIES.ID = :ENTRY;
                            BREAK;
                        END
                    END

                    IF(HAS_VALUE = 0)THEN
                    BEGIN
                        SELECT TITLE || '\$' || CONTENT || ATOMS.CODE || '(' || ROUND(:WAREHOUSE_AMOUNT, :NUMBER_DECIMAL_DIGITS) || ')'
                        FROM MESSAGES
                        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDIT_OBJECT0
                        WHERE MESSAGES.ID = 9 AND MESSAGES.LANGUAGE = :P_LANGUAGE
                        INTO :MESSAGE_CONTENT;

                        EXCEPTION EX_GENERAL MESSAGE_CONTENT;
                    END
                END
            END
            IF(HAS_VALUE = 0)THEN
            BEGIN
                FOR
                    SELECT ID
                    FROM ENTRIES WHERE COMPANY = :P_COMPANY AND REVENUE_ENTRY = :P_ID
                    INTO :DELETE_ENTRY
                DO
                BEGIN
                    DELETE FROM ENTRIES WHERE COMPANY = :P_COMPANY AND ID = :DELETE_ENTRY;
                END
            END
        END
        ELSE
        BEGIN
            FOR
                SELECT ID
                FROM ENTRIES WHERE COMPANY = :P_COMPANY AND REVENUE_ENTRY = :P_ID
                INTO :DELETE_ENTRY
            DO
            BEGIN
                DELETE FROM ENTRIES WHERE COMPANY = :P_COMPANY AND ID = :DELETE_ENTRY;
            END
        END

        DELETE FROM DECREASE_DOCUMENTS
        WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.CREDIT_DEBIT = :P_DEBIT_ID AND
        (
            
            ID IN
            (
                SELECT DECREASE_DOCUMENTS.ID
                FROM DECREASE_DOCUMENTS
                JOIN DOCUMENT_BALANCES ON DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.INCREASE_DOCUMENT = DECREASE_DOCUMENTS.INCREASE_DOCUMENT AND
                (ACCOUNT <> :P_DEBIT_ACCOUNT OR OBJECT0 <> :P_DEBIT_OBJECT0 OR OBJECT1 <> :P_DEBIT_OBJECT1 OR OBJECT2 <> :P_DEBIT_OBJECT2)
                WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY
            )
            OR
            ID IN
            (
                SELECT DECREASE_DOCUMENTS.ID
                FROM DECREASE_DOCUMENTS
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DECREASE_DOCUMENTS.INCREASE_DOCUMENT AND
                (
                    NOT EXISTS
                    (
                        SELECT ENTRIES.ID
                        FROM ENTRIES
                        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND CREDIT_DEBIT.SIDE = 1 AND
                        ACCOUNT = :P_DEBIT_ACCOUNT AND (:P_DEBIT_OBJECT0 IS NULL OR OBJECT0 = :P_DEBIT_OBJECT0) AND (:P_DEBIT_OBJECT1 IS NULL OR OBJECT1 = :P_DEBIT_OBJECT1) AND (:P_DEBIT_OBJECT2 IS NULL OR OBJECT2 = :P_DEBIT_OBJECT2)
                        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                    )
                )
                WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY
            )
        );

        DELETE FROM DECREASE_DOCUMENTS
        WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.CREDIT_DEBIT = :P_CREDIT_ID AND
        (
            
            ID IN
            (
                SELECT DECREASE_DOCUMENTS.ID
                FROM DECREASE_DOCUMENTS
                JOIN DOCUMENT_BALANCES ON DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.INCREASE_DOCUMENT = DECREASE_DOCUMENTS.INCREASE_DOCUMENT AND
                (ACCOUNT <> :P_CREDIT_ACCOUNT OR OBJECT0 <> :P_CREDIT_OBJECT0 OR OBJECT1 <> :P_CREDIT_OBJECT1 OR OBJECT2 <> :P_CREDIT_OBJECT2)
                WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY
            )
            OR
            ID IN
            (
                SELECT DECREASE_DOCUMENTS.ID
                FROM DECREASE_DOCUMENTS
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DECREASE_DOCUMENTS.INCREASE_DOCUMENT AND
                    NOT EXISTS
                    (
                        SELECT ENTRIES.ID
                        FROM ENTRIES
                        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND CREDIT_DEBIT.SIDE = 0 AND
                        ACCOUNT = :P_CREDIT_ACCOUNT OR (:P_CREDIT_OBJECT0 IS NULL OR OBJECT0 = :P_CREDIT_OBJECT0) AND (:P_CREDIT_OBJECT1 IS NULL OR OBJECT1 = :P_CREDIT_OBJECT1) AND (:P_CREDIT_OBJECT2 IS NULL OR OBJECT2 = :P_CREDIT_OBJECT2)
                        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                    )
                WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY
            )
        );

        

        IF(P_CREDIT_ACCOUNT IS NOT NULL AND P_CREDIT_OBJECT0 IS NOT NULL AND P_CREDIT_OBJECT1 IS NOT NULL)THEN
            DELETE FROM DECREASE_ENTRIES
            WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND
            (ID IN
            (
                SELECT DECREASE_ENTRIES.ID
                FROM DECREASE_ENTRIES
                JOIN BEGINNING_ENTRIES ON BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND BEGINNING_ENTRIES.ID = DECREASE_ENTRIES.INCREASE_ENTRY AND (BEGINNING_ENTRIES.ACCOUNT <> :P_CREDIT_ACCOUNT OR BEGINNING_ENTRIES.OBJECT0 <> :P_CREDIT_OBJECT0 OR BEGINNING_ENTRIES.OBJECT1 <> :P_CREDIT_OBJECT1)
                WHERE  DECREASE_ENTRIES.COMPANY = :P_COMPANY AND (DECREASE_ENTRIES.CREDIT_DEBIT = :P_CREDIT_ID OR DECREASE_ENTRIES.CREDIT_DEBIT = :P_DEBIT_ID)
            )
            OR ID IN
            (
                SELECT DECREASE_ENTRIES.ID
                FROM DECREASE_ENTRIES
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = DECREASE_ENTRIES.INCREASE_ENTRY
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND (DEBIT.ACCOUNT <> :P_CREDIT_ACCOUNT OR DEBIT.OBJECT0 <> :P_CREDIT_OBJECT0 OR DEBIT.OBJECT1 <> :P_CREDIT_OBJECT1)
                WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND (DECREASE_ENTRIES.CREDIT_DEBIT = :P_CREDIT_ID OR DECREASE_ENTRIES.CREDIT_DEBIT = :P_DEBIT_ID)
            ));
            

        IF(MESSAGE_CONTENT IS NULL)THEN
        BEGIN
            MESSAGE_CONTENT = '';
            WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
        END
    END
END ^

ALTER PROCEDURE DOUBLE_ENTRY_S_DOCUMENT_CODES (P_COMPANY DM_ID,
P_CREDIT_DEBIT DM_ID)
RETURNS (DOCUMENT_CODES DM_NAME)
AS 
BEGIN
    SELECT LIST(CODE, ';')
    FROM
    (
        SELECT CODE || '(' ||
            EXTRACT(DAY FROM BEGINNING_DOCUMENTS.INPUT_DATE) || '/' ||
            EXTRACT(MONTH FROM BEGINNING_DOCUMENTS.INPUT_DATE) || '/' ||
            EXTRACT(YEAR FROM BEGINNING_DOCUMENTS.INPUT_DATE)
        || ')' AS CODE
        FROM DECREASE_DOCUMENTS
        JOIN BEGINNING_DOCUMENTS ON BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND BEGINNING_DOCUMENTS.ID = DECREASE_DOCUMENTS.INCREASE_DOCUMENT
        WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.CREDIT_DEBIT = :P_CREDIT_DEBIT

        UNION ALL

        SELECT CODE || '-' || NUMBER || '(' ||
            EXTRACT(DAY FROM DOCUMENTS.INPUT_DATE) || '/' ||
            EXTRACT(MONTH FROM DOCUMENTS.INPUT_DATE) || '/' ||
            EXTRACT(YEAR FROM DOCUMENTS.INPUT_DATE)
        || ')' AS CODE
        FROM DECREASE_DOCUMENTS
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DECREASE_DOCUMENTS.INCREASE_DOCUMENT
        WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.CREDIT_DEBIT = :P_CREDIT_DEBIT

        UNION ALL

        SELECT CODE || '(' ||
            EXTRACT(DAY FROM BEGINNING_ENTRIES.INPUT_DATE) || '/' ||
            EXTRACT(MONTH FROM BEGINNING_ENTRIES.INPUT_DATE) || '/' ||
            EXTRACT(YEAR FROM BEGINNING_ENTRIES.INPUT_DATE)
        || ')' AS CODE
        FROM DECREASE_ENTRIES
        JOIN BEGINNING_ENTRIES ON BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND BEGINNING_ENTRIES.ID = DECREASE_ENTRIES.INCREASE_ENTRY
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.CREDIT_DEBIT = :P_CREDIT_DEBIT

        UNION ALL

        SELECT CODE || '-' || NUMBER || '(' ||
            EXTRACT(DAY FROM DOCUMENTS.INPUT_DATE) || '/' ||
            EXTRACT(MONTH FROM DOCUMENTS.INPUT_DATE) || '/' ||
            EXTRACT(YEAR FROM DOCUMENTS.INPUT_DATE)
        || ')' AS CODE
        FROM DECREASE_ENTRIES
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = DECREASE_ENTRIES.INCREASE_ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.CREDIT_DEBIT = :P_CREDIT_DEBIT
    )
    INTO :DOCUMENT_CODES;

    SUSPEND;
END ^

ALTER PROCEDURE DOUBLE_ENTRY_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
APPORTION DM_APPORTION,
LOT_NUMBER DM_CODE,
EXPIRY_DATE DM_DATE,
CONTENT DM_CONTENT,
DEBIT_ID DM_ID,
DEBIT_ACCOUNT DM_ID,
DEBIT_OBJECT0 DM_ID,
DEBIT_OBJECT0_CODE DM_CODE,
DEBIT_OBJECT1 DM_ID,
DEBIT_OBJECT1_CODE DM_CODE,
DEBIT_OBJECT2 DM_ID,
DEBIT_OBJECT2_CODE DM_CODE,
CREDIT_ID DM_ID,
CREDIT_ACCOUNT DM_ID,
CREDIT_OBJECT0 DM_ID,
CREDIT_OBJECT0_CODE DM_CODE,
CREDIT_OBJECT1 DM_ID,
CREDIT_OBJECT1_CODE DM_CODE,
CREDIT_OBJECT2 DM_ID,
CREDIT_OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
DEBIT_DOCUMENTS DM_NAME,
CREDIT_DOCUMENTS DM_NAME)
AS 
BEGIN
FOR
   SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, VAT_PERCENT, APPORTION, LOT_NUMBER, EXPIRY_DATE, ENTRY_BASE_STRINGS.CONTENT,
    DEBIT.ID, DEBIT.ACCOUNT, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.OBJECT2,
    CREDIT.ID, CREDIT.ACCOUNT, CREDIT.OBJECT0, CREDIT.OBJECT1, CREDIT.OBJECT2,
    DEBIT.AMOUNT, DEBIT.PRICE, DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY
   FROM ENTRIES
   JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
   JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
   JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
   JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
   WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_DOCUMENT
   INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, :APPORTION, :LOT_NUMBER, :EXPIRY_DATE, :CONTENT,
    :DEBIT_ID, :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2,
    :CREDIT_ID, :CREDIT_ACCOUNT, :CREDIT_OBJECT0, :CREDIT_OBJECT1, :CREDIT_OBJECT2,
    :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY
DO
BEGIN
    IF(DEBIT_OBJECT0 IS NULL)THEN
        DEBIT_OBJECT0_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT0
        INTO :DEBIT_OBJECT0_CODE;

    IF(DEBIT_OBJECT1 IS NULL)THEN
        DEBIT_OBJECT1_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT1
        INTO :DEBIT_OBJECT1_CODE;

    IF(DEBIT_OBJECT2 IS NULL)THEN
        DEBIT_OBJECT2_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT2
        INTO :DEBIT_OBJECT2_CODE;

    IF(CREDIT_OBJECT0 IS NULL)THEN
        CREDIT_OBJECT0_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT0
        INTO :CREDIT_OBJECT0_CODE;

    IF(CREDIT_OBJECT1 IS NULL)THEN
        CREDIT_OBJECT1_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT1
        INTO :CREDIT_OBJECT1_CODE;

    IF(CREDIT_OBJECT2 IS NULL)THEN
        CREDIT_OBJECT2_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT2
        INTO :CREDIT_OBJECT2_CODE;

    SELECT DOCUMENT_CODES
    FROM DOUBLE_ENTRY_S_DOCUMENT_CODES(:P_COMPANY, :DEBIT_ID)
    INTO :DEBIT_DOCUMENTS;

    SELECT DOCUMENT_CODES
    FROM DOUBLE_ENTRY_S_DOCUMENT_CODES(:P_COMPANY, :CREDIT_ID)
    INTO :CREDIT_DOCUMENTS;

    SUSPEND;
END
END ^

ALTER PROCEDURE DOUBLE_ENTRY_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TEAM DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY_CODE DM_CODE,
DOCUMENT DM_ID,
EXCHANGE_RATE DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
DEBIT_OBJECT0_CODE DM_CODE,
DEBIT_OBJECT1_CODE DM_CODE,
DEBIT_OBJECT2_CODE DM_CODE,
CREDIT_ACCOUNT_CODE DM_CODE,
CREDIT_OBJECT0_CODE DM_CODE,
CREDIT_OBJECT1_CODE DM_CODE,
CREDIT_OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE,
DEBIT_DOCUMENTS DM_NAME,
CREDIT_DOCUMENTS DM_NAME)
AS 
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT2 DM_ID;
DECLARE VARIABLE DEBIT_ID DM_ID;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT1 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT2 DM_ID;
DECLARE VARIABLE CREDIT_ID DM_ID;
BEGIN
    FOR
        SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, VAT_PERCENT, ENTRY_BASE_STRINGS.CONTENT,
        DEBIT.ID, DEBIT.ACCOUNT, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.OBJECT2,
        CREDIT.ID, CREDIT.ACCOUNT, CREDIT.OBJECT0, CREDIT.OBJECT1, CREDIT.OBJECT2,
        DEBIT.AMOUNT, DEBIT.PRICE, DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DOCUMENTS.ID, DOCUMENTS.CODE || '-' || NUMBER, DOCUMENTS.INPUT_DATE, DOCUMENTS.ORIGINAL_VOUCHERS, DOCUMENTS.VOUCHER_DATE
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_FROM_DATE AND :P_TO_DATE AND DOCUMENTS.TEAM = :P_TEAM
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1
        INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, CONTENT,
        :DEBIT_ID, :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2,
        :CREDIT_ID, :CREDIT_ACCOUNT, :CREDIT_OBJECT0, :CREDIT_OBJECT1, :CREDIT_OBJECT2,
        :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DOCUMENT, :CODE, :INPUT_DATE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CURRENCY
        INTO :CURRENCY_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_ACCOUNT
        INTO :DEBIT_ACCOUNT_CODE;

        IF(DEBIT_OBJECT0 IS NULL)THEN
            DEBIT_OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_OBJECT0
            INTO :DEBIT_OBJECT0_CODE;

        IF(DEBIT_OBJECT1 IS NULL)THEN
            DEBIT_OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_OBJECT1
            INTO :DEBIT_OBJECT1_CODE;

        IF(DEBIT_OBJECT2 IS NULL)THEN
            DEBIT_OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_OBJECT2
            INTO :DEBIT_OBJECT2_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_ACCOUNT
        INTO :CREDIT_ACCOUNT_CODE;

        IF(CREDIT_OBJECT0 IS NULL)THEN
            CREDIT_OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_OBJECT0
            INTO :CREDIT_OBJECT0_CODE;

        IF(CREDIT_OBJECT1 IS NULL)THEN
            CREDIT_OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_OBJECT1
            INTO :CREDIT_OBJECT1_CODE;

        IF(CREDIT_OBJECT2 IS NULL)THEN
            CREDIT_OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_OBJECT2
            INTO :CREDIT_OBJECT2_CODE;

        SELECT DOCUMENT_CODES
        FROM DOUBLE_ENTRY_S_DOCUMENT_CODES(:P_COMPANY, :DEBIT_ID)
        INTO :DEBIT_DOCUMENTS;

        SELECT DOCUMENT_CODES
        FROM DOUBLE_ENTRY_S_DOCUMENT_CODES(:P_COMPANY, :CREDIT_ID)
        INTO :CREDIT_DOCUMENTS;

        SUSPEND;
    END
END ^

ALTER PROCEDURE DOUBLE_ENTRY_S_RS_ACCOUNT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY_CODE DM_CODE,
DOCUMENT DM_ID,
EXCHANGE_RATE DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
DEBIT_OBJECT0_CODE DM_CODE,
DEBIT_OBJECT1_CODE DM_CODE,
DEBIT_OBJECT2_CODE DM_CODE,
CREDIT_ACCOUNT_CODE DM_CODE,
CREDIT_OBJECT0_CODE DM_CODE,
CREDIT_OBJECT1_CODE DM_CODE,
CREDIT_OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE,
DEBIT_DOCUMENTS DM_NAME,
CREDIT_DOCUMENTS DM_NAME)
AS 
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE DEBIT_ID DM_ID;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT2 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT1 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT2 DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ID DM_ID;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, VAT_PERCENT, ENTRY_BASE_STRINGS.CONTENT,
        DEBIT.ID, DEBIT_ATOM.CODE, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.OBJECT2,
        CREDIT.ID, CREDIT_ATOM.CODE, CREDIT.OBJECT0, CREDIT.OBJECT1, CREDIT.OBJECT2,
        DEBIT.AMOUNT, DEBIT.PRICE, DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DOCUMENTS.ID, DOCUMENTS.CODE || '-' || NUMBER, DOCUMENTS.INPUT_DATE, DOCUMENTS.ORIGINAL_VOUCHERS, DOCUMENTS.VOUCHER_DATE
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_FROM_DATE AND :P_TO_DATE
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND
        (DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE)
        INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, CONTENT,
        :DEBIT_ID, :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2,
        :CREDIT_ID, :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0, :CREDIT_OBJECT1, :CREDIT_OBJECT2,
        :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DOCUMENT, :CODE, :INPUT_DATE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CURRENCY
        INTO :CURRENCY_CODE;

        IF(DEBIT_OBJECT0 IS NULL)THEN
            DEBIT_OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_OBJECT0
            INTO :DEBIT_OBJECT0_CODE;

        IF(DEBIT_OBJECT1 IS NULL)THEN
            DEBIT_OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_OBJECT1
            INTO :DEBIT_OBJECT1_CODE;

        IF(DEBIT_OBJECT2 IS NULL)THEN
            DEBIT_OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :DEBIT_OBJECT2
            INTO :DEBIT_OBJECT2_CODE;

        IF(CREDIT_OBJECT0 IS NULL)THEN
            CREDIT_OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_OBJECT0
            INTO :CREDIT_OBJECT0_CODE;

        IF(CREDIT_OBJECT1 IS NULL)THEN
            CREDIT_OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_OBJECT1
            INTO :CREDIT_OBJECT1_CODE;

        IF(CREDIT_OBJECT2 IS NULL)THEN
            CREDIT_OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :CREDIT_OBJECT2
            INTO :CREDIT_OBJECT2_CODE;

        SELECT DOCUMENT_CODES
        FROM DOUBLE_ENTRY_S_DOCUMENT_CODES(:P_COMPANY, :DEBIT_ID)
        INTO :DEBIT_DOCUMENTS;

        SELECT DOCUMENT_CODES
        FROM DOUBLE_ENTRY_S_DOCUMENT_CODES(:P_COMPANY, :CREDIT_ID)
        INTO :CREDIT_DOCUMENTS;

        SUSPEND;
    END
END ^

