P_V627 DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL);
    UPDATE OR INSERT INTO DU_TOAN(COMPANY, ID, OBJECT, THANG, NAM, V511, V621, V622, V623, V627)
    VALUES(:P_COMPANY, :P_ID, :P_OBJECT, :P_THANG, :P_NAM, :P_V511, :P_V621, :P_V622, :P_V623, :P_V627);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

