ALTER PROCEDURE EMPLOYEE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_USER_ACCOUNT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO EMPLOYEES(COMPANY, ID, USER_ACCOUNT) VALUES(:P_COMPANY, :P_ID, :P_USER_ACCOUNT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE EMPLOYEE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
USER_ACCOUNT DM_ID)
AS 
BEGIN
    FOR
        SELECT EMPLOYEES.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, USER_ACCOUNT
        FROM EMPLOYEES
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = EMPLOYEES.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE EMPLOYEES.COMPANY = :P_COMPANY
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :USER_ACCOUNT
    DO
        SUSPEND;
END ^

ALTER PROCEDURE ENTRY_BALANCE_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_DECREASE_DATE DM_DATE,
P_SIDE DM_SIDE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
INPUT_DATE DM_DATE,
CODE DM_DOCUMENT_CODE,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_TYPES DM_ACCOUNT_TYPES;
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE DECREASE_AMOUNT DM_DOUBLE; 
DECLARE VARIABLE DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE; 
DECLARE VARIABLE DECREASE_FOREIGN_SUM_OF_MONEY DM_DOUBLE; 
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT BEGINNING_DATE
    FROM CMD_GET_BEGINNING_PERIOD(:P_COMPANY)
    INTO :BEGINNING_DATE;

    
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_DECREASE_DATE)
    INTO :PERIOD;

    SELECT ACCOUNT_TYPES
    FROM ACCOUNTS
    WHERE COMPANY = :P_COMPANY AND ID = :P_ACCOUNT
    INTO :ACCOUNT_TYPES;

    
    IF(P_SIDE = 0 AND BIN_AND(ACCOUNT_TYPES, 131072) <> 0)THEN
    BEGIN
        FOR
        SELECT ID, NOTE, INPUT_DATE, CODE, AMOUNT, PRICE, OFFICIAL_SUM_OF_MONEY, FOREIGN_SUM_OF_MONEY
        FROM
        (
            
            SELECT BEGINNING_ENTRIES.ID, NOTE, INPUT_DATE, CODE, ENTRY_BALANCES.AMOUNT, PRICE, ENTRY_BALANCES.OFFICIAL_CREDIT OFFICIAL_SUM_OF_MONEY, ENTRY_BALANCES.FOREIGN_CREDIT FOREIGN_SUM_OF_MONEY
            FROM ENTRY_BALANCES
            JOIN BEGINNING_ENTRIES ON BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND BEGINNING_ENTRIES.ID = ENTRY_BALANCES.INCREASE_ENTRY AND BEGINNING_ENTRIES.INPUT_DATE <= :P_DECREASE_DATE AND BEGINNING_ENTRIES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR BEGINNING_ENTRIES.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR BEGINNING_ENTRIES.OBJECT1 = :P_OBJECT1) AND (:P_OBJECT2 IS NULL OR BEGINNING_ENTRIES.OBJECT2 = :P_OBJECT2)
            JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = BEGINNING_ENTRIES.PERIOD AND PERIODS.BEGINNING_DATE >= :BEGINNING_DATE
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = BEGINNING_ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE,
                ENTRY_BALANCES.AMOUNT, CREDIT.PRICE, ENTRY_BALANCES.OFFICIAL_CREDIT OFFICIAL_SUM_OF_MONEY, ENTRY_BALANCES.FOREIGN_CREDIT FOREIGN_SUM_OF_MONEY
            FROM ENTRY_BALANCES
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = ENTRY_BALANCES.INCREASE_ENTRY
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE >= :BEGINNING_DATE AND DOCUMENTS.INPUT_DATE <= :P_DECREASE_DATE
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR CREDIT.OBJECT1 = :P_OBJECT1) AND (:P_OBJECT2 IS NULL OR CREDIT.OBJECT2 = :P_OBJECT2)
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE,
                CREDIT.AMOUNT, CREDIT.PRICE, CREDIT.OFFICIAL_SUM_OF_MONEY, CREDIT.FOREIGN_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
