ALTER PROCEDURE ENTRY_BASE_D (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
BEGIN
    
    UPDATE ENTRIES
    SET ENTRIES.REVENUE_ENTRY = NULL
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID AND REVENUE_ENTRY IS NOT NULL;
    

    DELETE FROM ENTRY_BASES
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID;

    WHEN ANY DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = SQLCODE AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || SQLCODE || ')';
    END
END ^

ALTER PROCEDURE ENTRY_BASE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CONTENT DM_CONTENT)
AS 
BEGIN
    UPDATE OR INSERT INTO ENTRY_BASES(COMPANY, ID, ORDINAL) VALUES(:P_COMPANY, :P_ID, :P_ORDINAL);

    UPDATE OR INSERT INTO ENTRY_BASE_STRINGS(COMPANY, ID, LANGUAGE, CONTENT, NOTE) VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_CONTENT, :P_NOTE);
END ^

ALTER PROCEDURE EXPENSE_ACCOUNT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_PERIOD DM_ID,
P_PREPAID_EXPENSE DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_PERCENT DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO EXPENSE_ACCOUNTS(ID, COMPANY, PERIOD, PREPAID_EXPENSE, ACCOUNT, PERCENT, OBJECT0, OBJECT1, OBJECT2)
    VALUES(:P_ID, :P_COMPANY, :P_PERIOD, :P_PREPAID_EXPENSE, :P_ACCOUNT, :P_PERCENT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

