OBJECT2 DM_ID,
OBJECT2_CODE DM_CODE,
PERCENT DM_DOUBLE)
AS 
begin
    FOR
        SELECT EXPENSE_ACCOUNTS.ID, NOTE, ORDINAL, PREPAID_EXPENSE, ACCOUNT, PERCENT,
        OBJECT0, OBJECT1, OBJECT2
        FROM EXPENSE_ACCOUNTS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = EXPENSE_ACCOUNTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE EXPENSE_ACCOUNTS.COMPANY = :P_COMPANY AND EXPENSE_ACCOUNTS.PREPAID_EXPENSE = :P_PREPAID_EXPENSE AND EXPENSE_ACCOUNTS.PERIOD = :P_PERIOD
        INTO :ID, :NOTE, :ORDINAL, :PREPAID_EXPENSE, :ACCOUNT, :PERCENT, :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE;

        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE;

        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
            INTO :OBJECT2_CODE;

        SUSPEND;
    END
end ^

