ALTER PROCEDURE FINANCIAL_REPORT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_ENGLISH_NAME DM_NAME,
P_OTHER_NAME DM_NAME,
P_REPORT DM_ID,
P_ITEM_CODE DM_ITEM_CODE,
P_CAL_ORDER DM_SMALLINT,
P_COMMENTARY DM_COMMENTARY,
P_PREVIOUS_PERIOD DM_DOUBLE,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_GROUP_IN_REPORT DM_CODE,
P_DEFAULT_STRING DM_CONTENT,
P_OBJECT_TYPE DM_ID)
AS 
DECLARE VARIABLE OTHER_FINANCIAL_REPORT_ID DM_ID;
DECLARE VARIABLE OTHER_FINANCIAL_REPORT_COMPANY DM_ID;
DECLARE VARIABLE ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM;
BEGIN
    EXECUTE PROCEDURE ATOM_IU_ENGLISH_NAME(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_ENGLISH_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    IF(P_OTHER_NAME IS NOT NULL AND P_OTHER_NAME <> P_NAME)THEN
    BEGIN
        SELECT ACCOUNTING_SYSTEM
        FROM ACCOUNTING_SETTINGS
        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
        INTO :ACCOUNTING_SYSTEM;

        FOR
            SELECT FINANCIAL_REPORTS.ID, FINANCIAL_REPORTS.COMPANY
            FROM FINANCIAL_REPORTS
            JOIN ACCOUNTING_SETTINGS ON ACCOUNTING_SETTINGS.COMPANY = FINANCIAL_REPORTS.COMPANY AND ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM = :ACCOUNTING_SYSTEM
            JOIN ATOMS ON ATOMS.COMPANY = FINANCIAL_REPORTS.COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID AND
                            ATOMS.CODE = :P_CODE AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE
            INTO :OTHER_FINANCIAL_REPORT_ID, :OTHER_FINANCIAL_REPORT_COMPANY
        DO
        BEGIN
            UPDATE OR INSERT INTO ATOM_STRINGS(ID, NAME, LANGUAGE, COMPANY)
            VALUES(:OTHER_FINANCIAL_REPORT_ID, :P_OTHER_NAME, 2, :OTHER_FINANCIAL_REPORT_COMPANY);
        END
    END

    UPDATE OR INSERT INTO FINANCIAL_REPORTS(COMPANY, ID, REPORT, ITEM_CODE, CAL_ORDER, PREVIOUS_PERIOD, GROUP_IN_DESIGNER, GROUP_IN_REPORT, DEFAULT_STRING) VALUES(:P_COMPANY, :P_ID, :P_REPORT, :P_ITEM_CODE, :P_CAL_ORDER, :P_PREVIOUS_PERIOD, :P_GROUP_IN_DESIGNER, :P_GROUP_IN_REPORT, :P_DEFAULT_STRING);

    UPDATE OR INSERT INTO FINANCIAL_REPORT_STRINGS(COMPANY, ID, LANGUAGE, COMMENTARY) VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_COMMENTARY);

    UPDATE OR INSERT INTO FINANCIAL_REPORT_STRINGS(COMPANY, ID, LANGUAGE, COMMENTARY) VALUES(:P_COMPANY, :P_ID, 1, :P_COMMENTARY);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE FINANCIAL_REPORT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_REPORT DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
ENGLISH_NAME DM_NAME,
OTHER_NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
REPORT DM_ID,
ITEM_CODE DM_ITEM_CODE,
CAL_ORDER DM_SMALLINT,
COMMENTARY DM_COMMENTARY,
PREVIOUS_PERIOD DM_DOUBLE,
GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
GROUP_IN_REPORT DM_CODE,
DEFAULT_STRING DM_CONTENT)
AS 
BEGIN
    FOR
        SELECT FINANCIAL_REPORTS.ID,ORDINAL, NOTE,CODE, LANGUAGE_ATOM_STRINGS.NAME, ENGLISH_ATOM_STRINGS.NAME, OTHER_ATOM_STRINGS.NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, REPORT, ITEM_CODE, CAL_ORDER, COMMENTARY, PREVIOUS_PERIOD,
            GROUP_IN_DESIGNER, GROUP_IN_REPORT, DEFAULT_STRING
        FROM FINANCIAL_REPORTS
        JOIN FINANCIAL_REPORT_STRINGS ON FINANCIAL_REPORT_STRINGS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_STRINGS.LANGUAGE = :P_LANGUAGE AND FINANCIAL_REPORT_STRINGS.ID = FINANCIAL_REPORTS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
        JOIN ATOM_STRINGS LANGUAGE_ATOM_STRINGS ON LANGUAGE_ATOM_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_ATOM_STRINGS.ID = ATOMS.ID
        LEFT JOIN ATOM_STRINGS ENGLISH_ATOM_STRINGS ON ENGLISH_ATOM_STRINGS.COMPANY = :P_COMPANY AND ENGLISH_ATOM_STRINGS.LANGUAGE = 1 AND ENGLISH_ATOM_STRINGS.ID = ATOMS.ID
        LEFT JOIN ATOM_STRINGS OTHER_ATOM_STRINGS ON OTHER_ATOM_STRINGS.COMPANY = :P_COMPANY AND OTHER_ATOM_STRINGS.LANGUAGE = 2 AND OTHER_ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND REPORT = :P_REPORT
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :ENGLISH_NAME, :OTHER_NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :REPORT, :ITEM_CODE, :CAL_ORDER, :COMMENTARY, PREVIOUS_PERIOD,
            :GROUP_IN_DESIGNER, :GROUP_IN_REPORT, :DEFAULT_STRING
    DO
        SUSPEND;
END ^

