ALTER PROCEDURE GOODS_CONVERSION_RATE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_GOODS DM_ID,
P_CONVERSION_DATE DM_DATE,
P_RATE DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO GOODS_CONVERSION_RATES(ID, COMPANY, GOODS, CONVERSION_DATE, RATE)
    VALUES(:P_ID, :P_COMPANY, :P_GOODS, :P_CONVERSION_DATE, :P_RATE);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE GOODS_CONVERSION_RATE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_GOODS DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
GOODS DM_ID,
CONVERSION_DATE DM_DATE,
RATE DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT GOODS_CONVERSION_RATES.ID, NOTE, ORDINAL, GOODS, CONVERSION_DATE, RATE
        FROM GOODS_CONVERSION_RATES
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = GOODS_CONVERSION_RATES.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE GOODS_CONVERSION_RATES.COMPANY = :P_COMPANY AND GOODS_CONVERSION_RATES.GOODS = :P_GOODS
        INTO :ID, :NOTE, :ORDINAL, :GOODS, :CONVERSION_DATE, :RATE
    DO
        SUSPEND;
END ^

ALTER PROCEDURE GOOD_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_UNIT DM_UNIT,
P_WARRANTY_MONTHS DM_INTEGER,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO GOODS(COMPANY, ID, WARRANTY_MONTHS)
    VALUES(:P_COMPANY, :P_ID, :P_WARRANTY_MONTHS);

    UPDATE OR INSERT INTO GOODS_STRINGS(COMPANY, ID, LANGUAGE, UNIT)
    VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_UNIT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE GOOD_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
UNIT DM_UNIT,
WARRANTY_MONTHS DM_INTEGER)
AS 
BEGIN
  FOR
  SELECT GOODS.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, UNIT,
    WARRANTY_MONTHS
  FROM GOODS
  JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = GOODS.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = GOODS_STRINGS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE GOODS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :UNIT,
    :WARRANTY_MONTHS
  DO
    SUSPEND;
END ^

ALTER PROCEDURE GOOD_TEAM_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE TEAM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO GOOD_TEAMS(ID, COMPANY) VALUES(:P_ID, :P_COMPANY);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE GOOD_TEAM_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID)
AS 
BEGIN
  FOR
  SELECT GOOD_TEAMS.ID,ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
  FROM GOOD_TEAMS
  JOIN TEAMS ON TEAMS.COMPANY = :P_COMPANY AND TEAMS.ID = GOOD_TEAMS.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = TEAMS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE GOOD_TEAMS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
  DO
    SUSPEND;
END ^

ALTER PROCEDURE GRANT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_ATOM DM_ID,
P_RIGHTS DM_RIGHTS,
P_ROLE_ID DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY,:P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO GRANTS(COMPANY, ID, ROLE_ID, ATOM, RIGHTS)
    VALUES(:P_COMPANY, :P_ID, :P_ROLE_ID, :P_ATOM, :P_RIGHTS);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE GRANT_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ROLE_ID DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
ATOM DM_ID,
ATOM_NAME DM_NAME,
PARENT DM_ID,
RIGHTS DM_RIGHTS,
IS_NEW DM_BOOL,
DONT_SAVE DM_BOOL)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;
DECLARE VARIABLE TEAM DM_ID;
DECLARE VARIABLE PREV_TEAM DM_ID;
BEGIN
    FOR
        SELECT OBJECT_TYPES.ID, NAME, NOTE, ORDINAL
        FROM OBJECT_TYPES
        WHERE OBJECT_TYPES.RIGHTS <> 0
        INTO :OBJECT_TYPE, :ATOM_NAME, :NOTE, :ORDINAL
    DO
    BEGIN
        ID = OBJECT_TYPE;
        PARENT = NULL;
        ATOM = OBJECT_TYPE;
        RIGHTS = 0;
        IS_NEW = 0;
        TEAM = NULL;
        PREV_TEAM = NULL;
        DONT_SAVE = 1;

        SUSPEND;

        
        FOR
            SELECT ATOMS.ID, NAME, PARENT, TEAM
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND ATOMS.HIDE = 0
            ORDER BY TEAM
            INTO :ATOM, :ATOM_NAME, :PARENT, :TEAM
        DO
        BEGIN
            ID = NULL;

            SELECT GRANTS.ID, ORDINAL, NOTE, RIGHTS
            FROM GRANTS
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = GRANTS.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            WHERE GRANTS.COMPANY = :P_COMPANY AND GRANTS.ROLE_ID = :P_ROLE_ID AND GRANTS.ATOM = :ATOM
            INTO :ID, :ORDINAL, :NOTE, :RIGHTS;

            DONT_SAVE = 0;

            IF(ID IS NULL)THEN
            BEGIN
                ID = ATOM;
                ORDINAL = 0;
                RIGHTS = 0;
                IS_NEW = 1;
            END
            ELSE
                IS_NEW = 0;

            IF(PARENT IS NULL)THEN
            BEGIN
                IF(TEAM IS NULL)THEN
                BEGIN
                    PARENT = OBJECT_TYPE;
                    SUSPEND;
                END
                ELSE
                BEGIN
                    PARENT = TEAM;
                    SUSPEND;

                    IF(PREV_TEAM IS NULL OR PREV_TEAM <> TEAM)THEN
                    BEGIN
                        SELECT ATOMS.ID, NAME, :OBJECT_TYPE, NOTE, ORDINAL
                        FROM ATOMS
                        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :TEAM
                        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = :TEAM
                        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = :TEAM
                        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :TEAM AND ATOMS.HIDE = 0
                        INTO :ID, :ATOM_NAME, :PARENT, :NOTE, :ORDINAL;

                        PARENT = OBJECT_TYPE;
                        ATOM = ID;
                        RIGHTS = 0;
                        IS_NEW = 0;

                        PREV_TEAM = TEAM;

                        DONT_SAVE = 1;

                        SUSPEND;
                    END
                END
            END
            ELSE SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_BANG_CAN_DOI_TAI_KHOAN_C (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE,
P_PARENT_ACCOUNT DM_ID,
P_CAP DM_SMALLINT,
P_CURRENT_ID DM_INTEGER,
P_PARENT_ID DM_INTEGER,
P_RETURN_ACCOUNT_ZERO DM_BOOL)
RETURNS (VIRTUAL_ID DM_INTEGER,
PARENT_ID DM_INTEGER,
ID DM_ID,
IS_ACCOUNT DM_BOOL,
IS_GOODS_ACCOUNT DM_BOOL,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT_AMOUNT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT_AMOUNT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
CAP DM_SMALLINT,
CURRENT_ID DM_INTEGER)
AS 
DECLARE VARIABLE HAS_CHILD DM_BOOL;
DECLARE VARIABLE VIRTUAL_ID_PARENT DM_INTEGER;
DECLARE VARIABLE PARENT_ID_PARENT DM_INTEGER;
DECLARE VARIABLE ID_ACCOUNT_PARENT DM_ID;
DECLARE VARIABLE BEGINNING_AMOUNT_ANY DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_AMOUNT_ANY DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_AMOUNT_ANY DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT_ACCOUNT_PARENT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT_ACCOUNT_PARENT DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_ACCOUNT_PARENT DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_ACCOUNT_PARENT DM_DOUBLE;
DECLARE VARIABLE ENDING_DEBIT_ACCOUNT_PARENT DM_DOUBLE;
DECLARE VARIABLE ENDING_CREDIT_ACCOUNT_PARENT DM_DOUBLE;
DECLARE VARIABLE VIRTUAL_ID_CHILD DM_INTEGER;
DECLARE VARIABLE PARENT_ID_CHILD DM_INTEGER;
DECLARE VARIABLE ID_ACCOUNT_CHILD DM_ID;
DECLARE VARIABLE BEGINNING_AMOUNT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_AMOUNT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_AMOUNT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE ENDING_AMOUNT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE ENDING_DEBIT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE ENDING_CREDIT_ACCOUNT_CHILD DM_DOUBLE;
DECLARE VARIABLE VIRTUAL_ID_OBJECT0 DM_INTEGER;
DECLARE VARIABLE ID_OBJECT0 DM_ID;
DECLARE VARIABLE BEGINNING_AMOUNT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_AMOUNT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_AMOUNT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE ENDING_AMOUNT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE ENDING_DEBIT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE ENDING_CREDIT_OBJECT0 DM_DOUBLE;
DECLARE VARIABLE ID_OBJECT1 DM_ID;
DECLARE VARIABLE BEGINNING_AMOUNT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_AMOUNT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_AMOUNT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE ENDING_AMOUNT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE ENDING_DEBIT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE ENDING_CREDIT_OBJECT1 DM_DOUBLE;
DECLARE VARIABLE BALANCE_TYPE DM_BALANCE_TYPE;
BEGIN
    P_CAP = P_CAP + 1;
    CURRENT_ID = P_CURRENT_ID;

    FOR
        SELECT ACCOUNTS.ID, BALANCE_TYPE, IIF(BIN_AND(ACCOUNTS.ACCOUNT_TYPES, 4096) > 0, 1, 0)
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = ACCOUNTS.COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.PARENT = :P_PARENT_ACCOUNT
        WHERE ACCOUNTS.COMPANY = :P_COMPANY
        INTO :ID_ACCOUNT_PARENT, :BALANCE_TYPE, :IS_GOODS_ACCOUNT
    DO
    BEGIN
        HAS_CHILD = 0;

        VIRTUAL_ID_PARENT = CURRENT_ID;
        CURRENT_ID = CURRENT_ID + 1;

        PARENT_ID_PARENT = P_PARENT_ID;


        BEGINNING_DEBIT_ACCOUNT_PARENT = 0;
        BEGINNING_CREDIT_ACCOUNT_PARENT = 0;
  
        RISING_DEBIT_ACCOUNT_PARENT = 0;

        RISING_CREDIT_ACCOUNT_PARENT = 0;
  
        ENDING_DEBIT_ACCOUNT_PARENT = 0;
        ENDING_CREDIT_ACCOUNT_PARENT = 0;

        
        FOR
            SELECT VIRTUAL_ID, PARENT_ID, INT_BANG_CAN_DOI_TAI_KHOAN_C.ID, IS_ACCOUNT, BEGINNING_AMOUNT, BEGINNING_DEBIT, BEGINNING_CREDIT, RISING_DEBIT_AMOUNT, RISING_DEBIT, RISING_CREDIT_AMOUNT, RISING_CREDIT, ENDING_AMOUNT, ENDING_DEBIT, ENDING_CREDIT, CAP, CURRENT_ID
            FROM INT_BANG_CAN_DOI_TAI_KHOAN_C(:P_LANGUAGE, :P_COMPANY, :P_FROM_DATE, :P_TO_DATE, :ID_ACCOUNT_PARENT, :P_CAP, :CURRENT_ID, :VIRTUAL_ID_PARENT, :P_RETURN_ACCOUNT_ZERO)
            INTO :VIRTUAL_ID_CHILD, :PARENT_ID_CHILD, :ID_ACCOUNT_CHILD, :IS_ACCOUNT, :BEGINNING_AMOUNT_ACCOUNT_CHILD, :BEGINNING_DEBIT_ACCOUNT_CHILD, :BEGINNING_CREDIT_ACCOUNT_CHILD, :RISING_DEBIT_AMOUNT_ACCOUNT_CHILD, :RISING_DEBIT_ACCOUNT_CHILD, :RISING_CREDIT_AMOUNT_ACCOUNT_CHILD, :RISING_CREDIT_ACCOUNT_CHILD, :ENDING_AMOUNT_ACCOUNT_CHILD, :ENDING_DEBIT_ACCOUNT_CHILD, :ENDING_CREDIT_ACCOUNT_CHILD, :CAP, :CURRENT_ID
        DO
        BEGIN
            HAS_CHILD = 1;

            
            VIRTUAL_ID = VIRTUAL_ID_CHILD;
            PARENT_ID = PARENT_ID_CHILD;
            ID = ID_ACCOUNT_CHILD;
            BEGINNING_AMOUNT = BEGINNING_AMOUNT_ACCOUNT_CHILD;
            BEGINNING_DEBIT = BEGINNING_DEBIT_ACCOUNT_CHILD;
            BEGINNING_CREDIT = BEGINNING_CREDIT_ACCOUNT_CHILD;
            RISING_DEBIT_AMOUNT = RISING_DEBIT_AMOUNT_ACCOUNT_CHILD;
            RISING_DEBIT = RISING_DEBIT_ACCOUNT_CHILD;
            RISING_CREDIT_AMOUNT = RISING_CREDIT_AMOUNT_ACCOUNT_CHILD;
            RISING_CREDIT = RISING_CREDIT_ACCOUNT_CHILD;
            ENDING_AMOUNT = ENDING_AMOUNT_ACCOUNT_CHILD;
            ENDING_DEBIT = ENDING_DEBIT_ACCOUNT_CHILD;
            ENDING_CREDIT = ENDING_CREDIT_ACCOUNT_CHILD;

            SUSPEND;

            IF(CAP = P_CAP)THEN
            BEGIN
      
                BEGINNING_DEBIT_ACCOUNT_PARENT = BEGINNING_DEBIT_ACCOUNT_PARENT + BEGINNING_DEBIT;
                BEGINNING_CREDIT_ACCOUNT_PARENT = BEGINNING_CREDIT_ACCOUNT_PARENT + BEGINNING_CREDIT;

        
                RISING_DEBIT_ACCOUNT_PARENT = RISING_DEBIT_ACCOUNT_PARENT + RISING_DEBIT;
         
                RISING_CREDIT_ACCOUNT_PARENT = RISING_CREDIT_ACCOUNT_PARENT + RISING_CREDIT;

                IF(BALANCE_TYPE = 1)THEN
                BEGIN
           
                    ENDING_DEBIT_ACCOUNT_PARENT = ENDING_DEBIT_ACCOUNT_PARENT + ENDING_DEBIT;
                    ENDING_CREDIT_ACCOUNT_PARENT = ENDING_CREDIT_ACCOUNT_PARENT + ENDING_CREDIT;
                END
            END
        END

        IF(HAS_CHILD = 1)THEN
        BEGIN
            IF(BALANCE_TYPE = 0)THEN
            BEGIN
                IF(BEGINNING_DEBIT_ACCOUNT_PARENT > BEGINNING_CREDIT_ACCOUNT_PARENT)THEN
                BEGIN
                    BEGINNING_DEBIT_ACCOUNT_PARENT = BEGINNING_DEBIT_ACCOUNT_PARENT - BEGINNING_CREDIT_ACCOUNT_PARENT;
                    BEGINNING_CREDIT_ACCOUNT_PARENT = 0;
                END
                ELSE
                BEGIN
                    BEGINNING_CREDIT_ACCOUNT_PARENT = BEGINNING_CREDIT_ACCOUNT_PARENT - BEGINNING_DEBIT_ACCOUNT_PARENT;
                    BEGINNING_DEBIT_ACCOUNT_PARENT = 0;
                END
                

                ENDING_DEBIT_ACCOUNT_PARENT = BEGINNING_DEBIT_ACCOUNT_PARENT + RISING_DEBIT_ACCOUNT_PARENT - BEGINNING_CREDIT_ACCOUNT_PARENT - RISING_CREDIT_ACCOUNT_PARENT;

                IF(ENDING_DEBIT_ACCOUNT_PARENT > 0)THEN
                    ENDING_CREDIT_ACCOUNT_PARENT = 0;
                ELSE
                BEGIN
                    ENDING_CREDIT_ACCOUNT_PARENT = ABS(ENDING_DEBIT_ACCOUNT_PARENT);
                    ENDING_DEBIT_ACCOUNT_PARENT = 0;
                END
            END

            
            VIRTUAL_ID = VIRTUAL_ID_PARENT;
            PARENT_ID = PARENT_ID_PARENT;
            ID = ID_ACCOUNT_PARENT;
            BEGINNING_AMOUNT = NULL;
            BEGINNING_DEBIT = BEGINNING_DEBIT_ACCOUNT_PARENT;
            BEGINNING_CREDIT = BEGINNING_CREDIT_ACCOUNT_PARENT;

            RISING_DEBIT_AMOUNT = NULL;
            RISING_DEBIT = RISING_DEBIT_ACCOUNT_PARENT;
            RISING_CREDIT_AMOUNT = NULL;
            RISING_CREDIT = RISING_CREDIT_ACCOUNT_PARENT;
            ENDING_AMOUNT = NULL;
            ENDING_DEBIT = ENDING_DEBIT_ACCOUNT_PARENT;
            ENDING_CREDIT = ENDING_CREDIT_ACCOUNT_PARENT;
            CAP = :P_CAP-1;

            IS_ACCOUNT = 1;

            SUSPEND;
        END
        ELSE
        IF(HAS_CHILD = 0)THEN
        BEGIN
            IF(BALANCE_TYPE = 1)THEN
            BEGIN
                IS_ACCOUNT = 0;

                FOR
                    SELECT OBJECT0, SUM(BEGINNING_AMOUNT), SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(RISING_DEBIT_AMOUNT), SUM(RISING_DEBIT), SUM(RISING_CREDIT_AMOUNT), SUM(RISING_CREDIT)
                    FROM
                    (
                        SELECT OBJECT0, AMOUNT BEGINNING_AMOUNT, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 RISING_DEBIT_AMOUNT, 0 RISING_DEBIT, 0 RISING_CREDIT_AMOUNT, 0 RISING_CREDIT
                        FROM INT_SD_1_TK_DT0_DN(:P_COMPANY, :ID_ACCOUNT_PARENT, :IS_GOODS_ACCOUNT, :P_FROM_DATE)

                        UNION ALL

                        SELECT OBJECT0, 0 BEGINNING_AMOUNT, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT_AMOUNT RISING_DEBIT_AMOUNT, DEBIT RISING_DEBIT, CREDIT_AMOUNT RISING_CREDIT_AMOUNT, CREDIT RISING_CREDIT
                        FROM INT_PS_1_TK_DT0(:P_COMPANY, :ID_ACCOUNT_PARENT, :P_FROM_DATE, :P_TO_DATE)
                    )
                    GROUP BY OBJECT0
                    INTO :ID_OBJECT0, :BEGINNING_AMOUNT_OBJECT0, :BEGINNING_DEBIT_OBJECT0, :BEGINNING_CREDIT_OBJECT0, :RISING_DEBIT_AMOUNT_OBJECT0, :RISING_DEBIT_OBJECT0, :RISING_CREDIT_AMOUNT_OBJECT0, :RISING_CREDIT_OBJECT0
                DO
                BEGIN
                    ENDING_AMOUNT_OBJECT0 = BEGINNING_AMOUNT_OBJECT0 + RISING_DEBIT_AMOUNT_OBJECT0 - RISING_CREDIT_AMOUNT_OBJECT0;
                    ENDING_DEBIT_OBJECT0 = BEGINNING_DEBIT_OBJECT0 + RISING_DEBIT_OBJECT0 - BEGINNING_CREDIT_OBJECT0 - RISING_CREDIT_OBJECT0;

                    IF(ENDING_DEBIT_OBJECT0 > 0)THEN
                        ENDING_CREDIT_OBJECT0 = 0;
                    ELSE
                    BEGIN
                        ENDING_CREDIT_OBJECT0 = ABS(ENDING_DEBIT_OBJECT0);
                        ENDING_DEBIT_OBJECT0 = 0;
                    END

                    VIRTUAL_ID_OBJECT0 = CURRENT_ID;
                    CURRENT_ID = CURRENT_ID + 1;
                    
                    

                    VIRTUAL_ID = VIRTUAL_ID_OBJECT0;
                    PARENT_ID = VIRTUAL_ID_PARENT;
                    ID = ID_OBJECT0;
                    BEGINNING_AMOUNT = BEGINNING_AMOUNT_OBJECT0;
                    BEGINNING_DEBIT = BEGINNING_DEBIT_OBJECT0;
                    BEGINNING_CREDIT = BEGINNING_CREDIT_OBJECT0;
                    RISING_DEBIT_AMOUNT = RISING_DEBIT_AMOUNT_OBJECT0;
                    RISING_DEBIT = RISING_DEBIT_OBJECT0;
                    RISING_CREDIT_AMOUNT = RISING_CREDIT_AMOUNT_OBJECT0;
                    RISING_CREDIT = RISING_CREDIT_OBJECT0;
                    ENDING_AMOUNT = ENDING_AMOUNT_OBJECT0;
                    ENDING_DEBIT = ENDING_DEBIT_OBJECT0;
                    ENDING_CREDIT = ENDING_CREDIT_OBJECT0;
                    CAP = :P_CAP;

                    SUSPEND;

                    BEGINNING_DEBIT_ACCOUNT_PARENT = BEGINNING_DEBIT_ACCOUNT_PARENT + BEGINNING_DEBIT;
                    BEGINNING_CREDIT_ACCOUNT_PARENT = BEGINNING_CREDIT_ACCOUNT_PARENT + BEGINNING_CREDIT;
                    RISING_DEBIT_ACCOUNT_PARENT = RISING_DEBIT_ACCOUNT_PARENT + RISING_DEBIT;
                    RISING_CREDIT_ACCOUNT_PARENT = RISING_CREDIT_ACCOUNT_PARENT + RISING_CREDIT;
                    ENDING_DEBIT_ACCOUNT_PARENT = ENDING_DEBIT_ACCOUNT_PARENT + ENDING_DEBIT;
                    ENDING_CREDIT_ACCOUNT_PARENT = ENDING_CREDIT_ACCOUNT_PARENT + ENDING_CREDIT;

                    FOR
                        SELECT OBJECT1, SUM(BEGINNING_AMOUNT), SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(RISING_DEBIT_AMOUNT), SUM(RISING_DEBIT), SUM(RISING_CREDIT_AMOUNT), SUM(RISING_CREDIT)
                        FROM
                        (
                            SELECT OBJECT1, AMOUNT BEGINNING_AMOUNT, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 RISING_DEBIT_AMOUNT, 0 RISING_DEBIT, 0 RISING_CREDIT_AMOUNT, 0 RISING_CREDIT
                            FROM INT_SD_1_TK_1_DT0_DT1_DN(:P_COMPANY, :ID_ACCOUNT_PARENT, :IS_GOODS_ACCOUNT, :ID_OBJECT0, :P_FROM_DATE)

                            UNION ALL

                            SELECT OBJECT1, 0 BEGINNING_AMOUNT, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT_AMOUNT RISING_DEBIT_AMOUNT, DEBIT RISING_DEBIT, CREDIT_AMOUNT RISING_CREDIT_AMOUNT, CREDIT RISING_CREDIT
                            FROM INT_PS_1_TK_1_DT0_DT1(:P_COMPANY, :ID_ACCOUNT_PARENT, :ID_OBJECT0, :P_FROM_DATE, :P_TO_DATE)
                        )
                        GROUP BY OBJECT1
                        INTO :ID_OBJECT1, :BEGINNING_AMOUNT_OBJECT1, :BEGINNING_DEBIT_OBJECT1, :BEGINNING_CREDIT_OBJECT1, :RISING_DEBIT_AMOUNT_OBJECT1, :RISING_DEBIT_OBJECT1, :RISING_CREDIT_AMOUNT_OBJECT1, :RISING_CREDIT_OBJECT1
                    DO
                    BEGIN
                        ENDING_AMOUNT_OBJECT1 = BEGINNING_AMOUNT_OBJECT1 + RISING_DEBIT_AMOUNT_OBJECT1 - RISING_CREDIT_AMOUNT_OBJECT1;
                        ENDING_DEBIT_OBJECT1 = BEGINNING_DEBIT_OBJECT1 + RISING_DEBIT_OBJECT1 - BEGINNING_CREDIT_OBJECT1 - RISING_CREDIT_OBJECT1;

                        IF(ENDING_DEBIT_OBJECT1 > 0)THEN
                            ENDING_CREDIT_OBJECT1 = 0;
                        ELSE
                        BEGIN
                            ENDING_CREDIT_OBJECT1 = ABS(ENDING_DEBIT_OBJECT1);
                            ENDING_DEBIT_OBJECT1 = 0;
                        END

                        
                        
                        VIRTUAL_ID = CURRENT_ID;
                        CURRENT_ID = CURRENT_ID + 1;
                        PARENT_ID = VIRTUAL_ID_OBJECT0;

                        ID = ID_OBJECT1;
                        BEGINNING_AMOUNT = BEGINNING_AMOUNT_OBJECT1;
                        BEGINNING_DEBIT = BEGINNING_DEBIT_OBJECT1;
                        BEGINNING_CREDIT = BEGINNING_CREDIT_OBJECT1;
                        RISING_DEBIT_AMOUNT = RISING_DEBIT_AMOUNT_OBJECT1;
                        RISING_DEBIT = RISING_DEBIT_OBJECT1;
                        RISING_CREDIT_AMOUNT = RISING_CREDIT_AMOUNT_OBJECT1;
                        RISING_CREDIT = RISING_CREDIT_OBJECT1;
                        ENDING_AMOUNT = ENDING_AMOUNT_OBJECT1;
                        ENDING_DEBIT = ENDING_DEBIT_OBJECT1;
                        ENDING_CREDIT = ENDING_CREDIT_OBJECT1;
                        CAP = :P_CAP + 2;

                        SUSPEND;
                    END
                END

                IF(P_RETURN_ACCOUNT_ZERO = 1 OR BEGINNING_DEBIT_ACCOUNT_PARENT <> 0 OR BEGINNING_CREDIT_ACCOUNT_PARENT <> 0 OR RISING_DEBIT_ACCOUNT_PARENT <> 0 OR RISING_CREDIT_ACCOUNT_PARENT <> 0 OR ENDING_DEBIT_ACCOUNT_PARENT <> 0 OR ENDING_CREDIT_ACCOUNT_PARENT <> 0)THEN
                BEGIN
                    
                    VIRTUAL_ID = VIRTUAL_ID_PARENT;
                    PARENT_ID = PARENT_ID_PARENT;
                    ID = ID_ACCOUNT_PARENT;
                    BEGINNING_AMOUNT = NULL;
                    BEGINNING_DEBIT = BEGINNING_DEBIT_ACCOUNT_PARENT;
                    BEGINNING_CREDIT = BEGINNING_CREDIT_ACCOUNT_PARENT;
                    RISING_DEBIT_AMOUNT = NULL;
                    RISING_DEBIT = RISING_DEBIT_ACCOUNT_PARENT;
                    RISING_CREDIT_AMOUNT = NULL;
                    RISING_CREDIT = RISING_CREDIT_ACCOUNT_PARENT;
                    ENDING_AMOUNT = NULL;
                    ENDING_DEBIT = ENDING_DEBIT_ACCOUNT_PARENT;
                    ENDING_CREDIT = ENDING_CREDIT_ACCOUNT_PARENT;
                    CAP = :P_CAP-1;

                    IS_ACCOUNT = 1;

                    SUSPEND;
                END
            END
            ELSE
            BEGIN

            SELECT AMOUNT, DEBIT, CREDIT
            FROM INT_SD_1_TK_DN(:P_COMPANY, :ID_ACCOUNT_PARENT, :P_FROM_DATE)
            INTO :BEGINNING_AMOUNT_ANY, :BEGINNING_DEBIT_ACCOUNT_PARENT, :BEGINNING_CREDIT_ACCOUNT_PARENT;

            SELECT DEBIT_AMOUNT, DEBIT, CREDIT_AMOUNT, CREDIT
            FROM INT_PS_1_TK(:P_COMPANY, :ID_ACCOUNT_PARENT, :P_FROM_DATE, :P_TO_DATE)
            INTO :RISING_DEBIT_AMOUNT_ANY, :RISING_DEBIT_ACCOUNT_PARENT, :RISING_CREDIT_AMOUNT_ANY, :RISING_CREDIT_ACCOUNT_PARENT;

            ENDING_DEBIT_ACCOUNT_PARENT = BEGINNING_DEBIT_ACCOUNT_PARENT + RISING_DEBIT_ACCOUNT_PARENT - BEGINNING_CREDIT_ACCOUNT_PARENT - RISING_CREDIT_ACCOUNT_PARENT;

            IF(ENDING_DEBIT_ACCOUNT_PARENT > 0)THEN
                ENDING_CREDIT_ACCOUNT_PARENT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT_ACCOUNT_PARENT = ABS(ENDING_DEBIT_ACCOUNT_PARENT);
                ENDING_DEBIT_ACCOUNT_PARENT = 0;
            END

            IF(P_RETURN_ACCOUNT_ZERO = 1 OR (IS_GOODS_ACCOUNT = 1 AND (BEGINNING_AMOUNT_ANY <> 0 OR RISING_DEBIT_AMOUNT_ANY <> 0 OR RISING_CREDIT_AMOUNT_ANY <> 0)) OR BEGINNING_DEBIT_ACCOUNT_PARENT <> 0 OR BEGINNING_CREDIT_ACCOUNT_PARENT <> 0 OR RISING_DEBIT_ACCOUNT_PARENT <> 0 OR RISING_CREDIT_ACCOUNT_PARENT <> 0 OR ENDING_DEBIT_ACCOUNT_PARENT <> 0 OR ENDING_CREDIT_ACCOUNT_PARENT <> 0)THEN
            BEGIN
                
                VIRTUAL_ID = VIRTUAL_ID_PARENT;
                PARENT_ID = PARENT_ID_PARENT;
                ID = ID_ACCOUNT_PARENT;
                BEGINNING_AMOUNT = NULL;
                BEGINNING_DEBIT = BEGINNING_DEBIT_ACCOUNT_PARENT;
                BEGINNING_CREDIT = BEGINNING_CREDIT_ACCOUNT_PARENT;
                RISING_DEBIT_AMOUNT = NULL;
                RISING_DEBIT = RISING_DEBIT_ACCOUNT_PARENT;
                RISING_CREDIT_AMOUNT = NULL;
                RISING_CREDIT = RISING_CREDIT_ACCOUNT_PARENT;
                ENDING_AMOUNT = NULL;
                ENDING_DEBIT = ENDING_DEBIT_ACCOUNT_PARENT;
                ENDING_CREDIT = ENDING_CREDIT_ACCOUNT_PARENT;
                CAP = :P_CAP-1;

                IS_ACCOUNT = 1;

                SUSPEND;

                IS_ACCOUNT = 0;

                FOR
                    SELECT OBJECT0, SUM(BEGINNING_AMOUNT), SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(RISING_DEBIT_AMOUNT), SUM(RISING_DEBIT), SUM(RISING_CREDIT_AMOUNT), SUM(RISING_CREDIT)
                    FROM
                    (
                        SELECT OBJECT0, AMOUNT BEGINNING_AMOUNT, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 RISING_DEBIT_AMOUNT, 0 RISING_DEBIT, 0 RISING_CREDIT_AMOUNT, 0 RISING_CREDIT
                        FROM INT_SD_1_TK_DT0_DN(:P_COMPANY, :ID_ACCOUNT_PARENT, :IS_GOODS_ACCOUNT, :P_FROM_DATE)

                        UNION ALL

                        SELECT OBJECT0, 0 BEGINNING_AMOUNT, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT_AMOUNT RISING_DEBIT_AMOUNT, DEBIT RISING_DEBIT, CREDIT_AMOUNT RISING_CREDIT_AMOUNT, CREDIT RISING_CREDIT
                        FROM INT_PS_1_TK_DT0(:P_COMPANY, :ID_ACCOUNT_PARENT, :P_FROM_DATE, :P_TO_DATE)
                    )
                    GROUP BY OBJECT0
                    INTO :ID_OBJECT0, :BEGINNING_AMOUNT_OBJECT0, :BEGINNING_DEBIT_OBJECT0, :BEGINNING_CREDIT_OBJECT0, :RISING_DEBIT_AMOUNT_OBJECT0, :RISING_DEBIT_OBJECT0, :RISING_CREDIT_AMOUNT_OBJECT0, :RISING_CREDIT_OBJECT0
                DO
                BEGIN
                    ENDING_AMOUNT_OBJECT0 = BEGINNING_AMOUNT_OBJECT0 + RISING_DEBIT_AMOUNT_OBJECT0 - RISING_CREDIT_AMOUNT_OBJECT0;
                    ENDING_DEBIT_OBJECT0 = BEGINNING_DEBIT_OBJECT0 + RISING_DEBIT_OBJECT0 - BEGINNING_CREDIT_OBJECT0 - RISING_CREDIT_OBJECT0;

                    IF(ENDING_DEBIT_OBJECT0 > 0)THEN
                        ENDING_CREDIT_OBJECT0 = 0;
                    ELSE
                    BEGIN
                        ENDING_CREDIT_OBJECT0 = ABS(ENDING_DEBIT_OBJECT0);
                        ENDING_DEBIT_OBJECT0 = 0;
                    END

                    VIRTUAL_ID_OBJECT0 = CURRENT_ID;
                    CURRENT_ID = CURRENT_ID + 1;
                    
                    

                    VIRTUAL_ID = VIRTUAL_ID_OBJECT0;
                    PARENT_ID = VIRTUAL_ID_PARENT;
                    ID = ID_OBJECT0;
                    BEGINNING_AMOUNT = BEGINNING_AMOUNT_OBJECT0;
                    BEGINNING_DEBIT = BEGINNING_DEBIT_OBJECT0;
                    BEGINNING_CREDIT = BEGINNING_CREDIT_OBJECT0;
                    RISING_DEBIT_AMOUNT = RISING_DEBIT_AMOUNT_OBJECT0;
                    RISING_DEBIT = RISING_DEBIT_OBJECT0;
                    RISING_CREDIT_AMOUNT = RISING_CREDIT_AMOUNT_OBJECT0;
                    RISING_CREDIT = RISING_CREDIT_OBJECT0;
                    ENDING_AMOUNT = ENDING_AMOUNT_OBJECT0;
                    ENDING_DEBIT = ENDING_DEBIT_OBJECT0;
                    ENDING_CREDIT = ENDING_CREDIT_OBJECT0;
                    CAP = :P_CAP;

                    SUSPEND;

                    FOR
                        SELECT OBJECT1, SUM(BEGINNING_AMOUNT), SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(RISING_DEBIT_AMOUNT), SUM(RISING_DEBIT), SUM(RISING_CREDIT_AMOUNT), SUM(RISING_CREDIT)
                        FROM
                        (
                            SELECT OBJECT1, AMOUNT BEGINNING_AMOUNT, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 RISING_DEBIT_AMOUNT, 0 RISING_DEBIT, 0 RISING_CREDIT_AMOUNT, 0 RISING_CREDIT
                            FROM INT_SD_1_TK_1_DT0_DT1_DN(:P_COMPANY, :ID_ACCOUNT_PARENT, :IS_GOODS_ACCOUNT, :ID_OBJECT0, :P_FROM_DATE)

                            UNION ALL

                            SELECT OBJECT1, 0 BEGINNING_AMOUNT, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT_AMOUNT RISING_DEBIT_AMOUNT, DEBIT RISING_DEBIT, CREDIT_AMOUNT RISING_CREDIT_AMOUNT, CREDIT RISING_CREDIT
                            FROM INT_PS_1_TK_1_DT0_DT1(:P_COMPANY, :ID_ACCOUNT_PARENT, :ID_OBJECT0, :P_FROM_DATE, :P_TO_DATE)
                        )
                        GROUP BY OBJECT1
                        INTO :ID_OBJECT1, :BEGINNING_AMOUNT_OBJECT1, :BEGINNING_DEBIT_OBJECT1, :BEGINNING_CREDIT_OBJECT1, :RISING_DEBIT_AMOUNT_OBJECT1, :RISING_DEBIT_OBJECT1, :RISING_CREDIT_AMOUNT_OBJECT1, :RISING_CREDIT_OBJECT1
                    DO
                    BEGIN
                        ENDING_AMOUNT_OBJECT1 = BEGINNING_AMOUNT_OBJECT1 + RISING_DEBIT_AMOUNT_OBJECT1 - RISING_CREDIT_AMOUNT_OBJECT1;
                        ENDING_DEBIT_OBJECT1 = BEGINNING_DEBIT_OBJECT1 + RISING_DEBIT_OBJECT1 - BEGINNING_CREDIT_OBJECT1 - RISING_CREDIT_OBJECT1;

                        IF(ENDING_DEBIT_OBJECT1 > 0)THEN
                            ENDING_CREDIT_OBJECT1 = 0;
                        ELSE
                        BEGIN
                            ENDING_CREDIT_OBJECT1 = ABS(ENDING_DEBIT_OBJECT1);
                            ENDING_DEBIT_OBJECT1 = 0;
                        END

                        
                        
                        VIRTUAL_ID = CURRENT_ID;
                        CURRENT_ID = CURRENT_ID + 1;
                        PARENT_ID = VIRTUAL_ID_OBJECT0;

                        ID = ID_OBJECT1;
                        BEGINNING_AMOUNT = BEGINNING_AMOUNT_OBJECT1;
                        BEGINNING_DEBIT = BEGINNING_DEBIT_OBJECT1;
                        BEGINNING_CREDIT = BEGINNING_CREDIT_OBJECT1;
                        RISING_DEBIT_AMOUNT = RISING_DEBIT_AMOUNT_OBJECT1;
                        RISING_DEBIT = RISING_DEBIT_OBJECT1;
                        RISING_CREDIT_AMOUNT = RISING_CREDIT_AMOUNT_OBJECT1;
                        RISING_CREDIT = RISING_CREDIT_OBJECT1;
                        ENDING_AMOUNT = ENDING_AMOUNT_OBJECT1;
                        ENDING_DEBIT = ENDING_DEBIT_OBJECT1;
                        ENDING_CREDIT = ENDING_CREDIT_OBJECT1;
                        CAP = :P_CAP + 2;

                        SUSPEND;
                    END
                END
            END
            END
        END
    END
END ^

ALTER PROCEDURE INT_BANG_KE_MUA_VAO_KHONG_HD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (INPUT_DATE DM_DATE,
PERSON_NAME DM_NAME,
PERSON_ADDRESS DM_ADDRESS,
PERSON_INFO DM_ADDITION_INFO,
GOODS DM_NAME,
UNIT DM_UNIT,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
BEGIN
    SUM_ALL = 0;

    FOR
        SELECT DOCUMENTS.ID, INPUT_DATE, ADDITION_INFO_4, PERSON_NAME, PERSON_ADDRESS
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.LANGUAGE= :P_LANGUAGE AND DOCUMENT_TEAM_STRINGS.ID = DOCUMENTS.TEAM
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        INTO :ID, :INPUT_DATE, :PERSON_INFO, :PERSON_NAME, :PERSON_ADDRESS
    DO
    BEGIN
        IF(NOT EXISTS(
            SELECT 1
            FROM INVOICES
            WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :ID
        ))THEN
        BEGIN
            FOR
                SELECT DEBIT.OBJECT0,
                DEBIT.AMOUNT, DEBIT.PRICE, DEBIT.OFFICIAL_SUM_OF_MONEY
                FROM ENTRIES
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.OBJECT0 IS NOT NULL
                JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT.ACCOUNT AND
                    (DEBIT_ATOMS.CODE STARTING WITH '15' OR DEBIT_ATOMS.CODE STARTING WITH '621')
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
                JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT.ACCOUNT AND
                    (CREDIT_ATOMS.CODE STARTING WITH '11' OR CREDIT_ATOMS.CODE STARTING WITH '331')
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :ID
                INTO :DEBIT_OBJECT0, :AMOUNT, :PRICE, :SUM_OF_MONEY
            DO
            BEGIN
                SELECT NAME, UNIT
                FROM ATOMS
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_OBJECT0
                LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :DEBIT_OBJECT0
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT0
                INTO :GOODS, :UNIT;

                SUM_ALL = SUM_ALL + SUM_OF_MONEY;

                SUSPEND;
            END
        END
    END
END ^

ALTER PROCEDURE INT_BANG_KE_NXT_LO_HANG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GOODS_CODE DM_CODE,
GOODS_NAME DM_NAME,
GOODS_UNIT DM_UNIT,
WAREHOUSE_CODE DM_CODE,
WAREHOUSE_NAME DM_NAME,
INPUT_DATE DM_DATE,
CODE DM_DOCUMENT_CODE,
CONTENT DM_CONTENT,
LOT_NUMBER DM_CODE,
EXPIRY_DATE DM_DATE,
PRICE DM_DOUBLE,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE BATCH_ID DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT BEGINNING_DATE
    FROM CMD_GET_BEGINNING_PERIOD(:P_COMPANY)
    INTO :BEGINNING_DATE;

    
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_TU_NGAY)
    INTO :PERIOD;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT RESULTS.ID, INPUT_DATE, RESULTS.CODE, CONTENT, LOT_NUMBER, EXPIRY_DATE,
        GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME, 
        PRICE, BEGINNING_AMOUNT, BEGINNING_SUM_OF_MONEY, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
        FROM
        (
            
            SELECT BEGINNING_ENTRIES.ID, INPUT_DATE, BEGINNING_ENTRIES.CODE, ENTRY_BASE_STRINGS.CONTENT, LOT_NUMBER, EXPIRY_DATE, BEGINNING_ENTRIES.OBJECT0, BEGINNING_ENTRIES.OBJECT1, PRICE,
            ENTRY_BALANCES.AMOUNT BEGINNING_AMOUNT, ENTRY_BALANCES.OFFICIAL_DEBIT BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM ENTRY_BALANCES
            JOIN BEGINNING_ENTRIES ON BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND BEGINNING_ENTRIES.ID = ENTRY_BALANCES.INCREASE_ENTRY AND BEGINNING_ENTRIES.INPUT_DATE <= :P_TU_NGAY
            JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = BEGINNING_ENTRIES.PERIOD AND PERIODS.BEGINNING_DATE >= :BEGINNING_DATE
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BEGINNING_ENTRIES.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :ACCOUNT_CODE
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = BEGINNING_ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, ENTRY_BASE_STRINGS.CONTENT, LOT_NUMBER, EXPIRY_DATE, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.PRICE,
                ENTRY_BALANCES.AMOUNT BEGINNING_AMOUNT, ENTRY_BALANCES.OFFICIAL_DEBIT BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM ENTRY_BALANCES
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = ENTRY_BALANCES.INCREASE_ENTRY
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE >= :BEGINNING_DATE AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :ACCOUNT_CODE
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE,  ENTRY_BASE_STRINGS.CONTENT, LOT_NUMBER, EXPIRY_DATE, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.PRICE,
                0 BEGINNING_AMOUNT, 0 BEGINNING_SUM_OF_MONEY, DEBIT.AMOUNT INPUT_AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ) RESULTS
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = RESULTS.OBJECT0
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = RESULTS.OBJECT0
        JOIN ATOMS GOOD_ATOMS ON GOOD_ATOMS.COMPANY = :P_COMPANY AND GOOD_ATOMS.ID = RESULTS.OBJECT0
        JOIN ATOM_STRINGS GOOD_ATOM_STRINGS ON GOOD_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOOD_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOOD_ATOM_STRINGS.ID = RESULTS.OBJECT0
        JOIN ATOMS WAREHOUSE_ATOMS ON WAREHOUSE_ATOMS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOMS.ID = RESULTS.OBJECT1
        JOIN ATOM_STRINGS WAREHOUSE_ATOM_STRINGS ON WAREHOUSE_ATOM_STRINGS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND WAREHOUSE_ATOM_STRINGS.ID = RESULTS.OBJECT1
        ORDER BY GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, INPUT_DATE, RESULTS.CODE, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME
        INTO :BATCH_ID, :INPUT_DATE, :CODE, :CONTENT, :LOT_NUMBER, :EXPIRY_DATE,
        :GOODS_CODE, :GOODS_NAME, :GOODS_UNIT, :WAREHOUSE_CODE, :WAREHOUSE_NAME,
        :PRICE, :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        SELECT SUM(DECREASE_ENTRIES.AMOUNT), SUM(DECREASE_ENTRIES.OFFICIAL_SUM_OF_MONEY)
        FROM DECREASE_ENTRIES
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ID = DECREASE_ENTRIES.CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.INCREASE_ENTRY = :BATCH_ID
        INTO :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY;

        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

        ENDING_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(BEGINNING_AMOUNT <> 0 OR BEGINNING_SUM_OF_MONEY <> 0 OR INPUT_AMOUNT <> 0 OR INPUT_SUM_OF_MONEY <> 0 OR OUTPUT_AMOUNT <> 0 OR OUTPUT_SUM_OF_MONEY <> 0 OR ENDING_AMOUNT <> 0 OR ENDING_SUM_OF_MONEY <> 0)THEN
        BEGIN
            IF(LOT_NUMBER IS NOT NULL AND LOT_NUMBER <> '')THEN
            BEGIN
                IF(CONTENT IS NULL OR CONTENT = '')THEN CONTENT = 'Số lô: ' || LOT_NUMBER;
                ELSE CONTENT = CONTENT || ', số lô: ' || LOT_NUMBER;
            END

            IF(EXPIRY_DATE IS NOT NULL)THEN
            BEGIN
                IF(CONTENT IS NULL OR CONTENT = '')THEN CONTENT = 'Ngày hết hạn: ' || extract(day from EXPIRY_DATE)||'/'||extract(month from EXPIRY_DATE)||'/'||extract(year from EXPIRY_DATE);
                ELSE CONTENT = CONTENT || ', ngày hết hạn: ' || extract(day from EXPIRY_DATE)||'/'||extract(month from EXPIRY_DATE)||'/'||extract(year from EXPIRY_DATE);
            END

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_BANG_KE_NXT_LO_HANG_CT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GOODS_CODE DM_CODE,
GOODS_NAME DM_NAME,
GOODS_UNIT DM_UNIT,
WAREHOUSE_CODE DM_CODE,
WAREHOUSE_NAME DM_NAME,
INPUT_DATE DM_DATE,
CODE DM_DOCUMENT_CODE,
CONTENT DM_CONTENT,
LOT_NUMBER DM_CODE,
EXPIRY_DATE DM_DATE,
PRICE DM_DOUBLE,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_CODE DM_DOCUMENT_CODE,
OUTPUT_INPUT_DATE DM_DATE,
OUTPUT_CONTENT DM_CONTENT,
OUTPUT_OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_OUTPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE BATCH_ID DM_ID;
DECLARE VARIABLE HAS_OUTPUT DM_BOOL;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT BEGINNING_DATE
    FROM CMD_GET_BEGINNING_PERIOD(:P_COMPANY)
    INTO :BEGINNING_DATE;
    
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_TU_NGAY)
    INTO :PERIOD;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT RESULTS.ID, INPUT_DATE, RESULTS.CODE, CONTENT, LOT_NUMBER, EXPIRY_DATE,
        GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME, 
        PRICE, BEGINNING_AMOUNT, BEGINNING_SUM_OF_MONEY, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
        FROM
        (
            
            SELECT BEGINNING_ENTRIES.ID, INPUT_DATE, BEGINNING_ENTRIES.CODE, ENTRY_BASE_STRINGS.CONTENT, LOT_NUMBER, EXPIRY_DATE, BEGINNING_ENTRIES.OBJECT0, BEGINNING_ENTRIES.OBJECT1, PRICE,
            ENTRY_BALANCES.AMOUNT BEGINNING_AMOUNT, ENTRY_BALANCES.OFFICIAL_DEBIT BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM ENTRY_BALANCES
            JOIN BEGINNING_ENTRIES ON BEGINNING_ENTRIES.COMPANY = :P_COMPANY AND BEGINNING_ENTRIES.ID = ENTRY_BALANCES.INCREASE_ENTRY AND BEGINNING_ENTRIES.INPUT_DATE <= :P_TU_NGAY
            JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = BEGINNING_ENTRIES.PERIOD AND PERIODS.BEGINNING_DATE >= :BEGINNING_DATE
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BEGINNING_ENTRIES.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :ACCOUNT_CODE
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = BEGINNING_ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, ENTRY_BASE_STRINGS.CONTENT, LOT_NUMBER, EXPIRY_DATE, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.PRICE,
                ENTRY_BALANCES.AMOUNT BEGINNING_AMOUNT, ENTRY_BALANCES.OFFICIAL_DEBIT BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM ENTRY_BALANCES
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = ENTRY_BALANCES.INCREASE_ENTRY
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE >= :BEGINNING_DATE AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :ACCOUNT_CODE
            WHERE ENTRY_BALANCES.COMPANY = :P_COMPANY AND ENTRY_BALANCES.PERIOD = :PERIOD

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.INPUT_DATE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE,  ENTRY_BASE_STRINGS.CONTENT, LOT_NUMBER, EXPIRY_DATE, DEBIT.OBJECT0, DEBIT.OBJECT1, DEBIT.PRICE,
                0 BEGINNING_AMOUNT, 0 BEGINNING_SUM_OF_MONEY, DEBIT.AMOUNT INPUT_AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.AMOUNT > 0
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ) RESULTS
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = RESULTS.OBJECT0
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = RESULTS.OBJECT0
        JOIN ATOMS GOOD_ATOMS ON GOOD_ATOMS.COMPANY = :P_COMPANY AND GOOD_ATOMS.ID = RESULTS.OBJECT0
        JOIN ATOM_STRINGS GOOD_ATOM_STRINGS ON GOOD_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOOD_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOOD_ATOM_STRINGS.ID = RESULTS.OBJECT0
        JOIN ATOMS WAREHOUSE_ATOMS ON WAREHOUSE_ATOMS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOMS.ID = RESULTS.OBJECT1
        JOIN ATOM_STRINGS WAREHOUSE_ATOM_STRINGS ON WAREHOUSE_ATOM_STRINGS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND WAREHOUSE_ATOM_STRINGS.ID = RESULTS.OBJECT1
        ORDER BY GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, INPUT_DATE, RESULTS.CODE, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME
        INTO :BATCH_ID, :INPUT_DATE, :CODE, :CONTENT, :LOT_NUMBER, :EXPIRY_DATE,
        :GOODS_CODE, :GOODS_NAME, :GOODS_UNIT, :WAREHOUSE_CODE, :WAREHOUSE_NAME,
        :PRICE, :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        SELECT SUM(DECREASE_ENTRIES.AMOUNT), SUM(DECREASE_ENTRIES.OFFICIAL_SUM_OF_MONEY)
        FROM DECREASE_ENTRIES
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ID = DECREASE_ENTRIES.CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.INCREASE_ENTRY = :BATCH_ID
        INTO :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY;

        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

        ENDING_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(BEGINNING_AMOUNT <> 0 OR BEGINNING_SUM_OF_MONEY <> 0 OR INPUT_AMOUNT <> 0 OR INPUT_SUM_OF_MONEY <> 0 OR OUTPUT_AMOUNT <> 0 OR OUTPUT_SUM_OF_MONEY <> 0 OR ENDING_AMOUNT <> 0 OR ENDING_SUM_OF_MONEY <> 0)THEN
        BEGIN
            IF(LOT_NUMBER IS NOT NULL AND LOT_NUMBER <> '')THEN
            BEGIN
                IF(CONTENT IS NULL OR CONTENT = '')THEN CONTENT = 'Số lô: ' || LOT_NUMBER;
                ELSE CONTENT = CONTENT || ', số lô: ' || LOT_NUMBER;
            END

            IF(EXPIRY_DATE IS NOT NULL)THEN
            BEGIN
                IF(CONTENT IS NULL OR CONTENT = '')THEN CONTENT = 'Ngày hết hạn: ' || extract(day from EXPIRY_DATE)||'/'||extract(month from EXPIRY_DATE)||'/'||extract(year from EXPIRY_DATE);
                ELSE CONTENT = CONTENT || ', ngày hết hạn: ' || extract(day from EXPIRY_DATE)||'/'||extract(month from EXPIRY_DATE)||'/'||extract(year from EXPIRY_DATE);
            END

            HAS_OUTPUT = 0;

            FOR
                SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE,
                IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT = '', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT),
                DECREASE_ENTRIES.AMOUNT, DECREASE_ENTRIES.OFFICIAL_SUM_OF_MONEY
                FROM DECREASE_ENTRIES
                JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ID = DECREASE_ENTRIES.CREDIT_DEBIT
                JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
                WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.INCREASE_ENTRY = :BATCH_ID
                INTO :OUTPUT_CODE, :OUTPUT_INPUT_DATE, :OUTPUT_CONTENT,
                :OUTPUT_OUTPUT_AMOUNT, :OUTPUT_OUTPUT_SUM_OF_MONEY
            DO
            BEGIN
                HAS_OUTPUT = 1;

                SUSPEND;
            END

            IF(HAS_OUTPUT = 0)THEN
            BEGIN
                OUTPUT_CODE = NULL;
                OUTPUT_INPUT_DATE = NULL;
                OUTPUT_CONTENT = NULL;
                OUTPUT_OUTPUT_AMOUNT = NULL;
                OUTPUT_OUTPUT_SUM_OF_MONEY = NULL;

                SUSPEND;
            END
        END
    END
END ^

ALTER PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
AS 
DECLARE VARIABLE FINANCIAL_REPORT DM_ID;
DECLARE VARIABLE TU_NGAY_KY_TRUOC DM_DATE;
DECLARE VARIABLE DEN_NGAY_KY_TRUOC DM_DATE;
DECLARE VARIABLE SO_THANG DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE CURRENT_PERIOD DM_DOUBLE;
DECLARE VARIABLE PREVIOUS_PERIOD DM_DOUBLE;
BEGIN
    SELECT PERIODS.BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :BEGINNING_DATE;

    DEN_NGAY_KY_TRUOC = DATEADD(DAY, -1, P_TU_NGAY);
    SO_THANG = DATEDIFF(MONTH, P_TU_NGAY, P_DEN_NGAY);

    TU_NGAY_KY_TRUOC = EXTRACT(YEAR FROM DEN_NGAY_KY_TRUOC) || '.' || EXTRACT(MONTH FROM DEN_NGAY_KY_TRUOC) || '.1';
    TU_NGAY_KY_TRUOC = DATEADD(MONTH, -SO_THANG, TU_NGAY_KY_TRUOC);

    FOR
        SELECT FINANCIAL_REPORTS.ID, PREVIOUS_PERIOD
        FROM FINANCIAL_REPORTS
        
        
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = FINANCIAL_REPORTS.ID
        WHERE FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND
            FINANCIAL_REPORTS.REPORT = :P_ID AND
            (:P_GROUP_IN_DESIGNER IS NULL OR BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER)
        ORDER BY FINANCIAL_REPORTS.CAL_ORDER, PROTONS.ORDINAL
        INTO :FINANCIAL_REPORT ,:PREVIOUS_PERIOD
    DO
    BEGIN
        INSERT INTO TEMP_FINANCIAL_REPORT(ID, CURRENT_PERIOD, PREVIOUS_PERIOD)
        VALUES(:FINANCIAL_REPORT, 0, 0);

        IF(DEN_NGAY_KY_TRUOC < BEGINNING_DATE)THEN
        BEGIN
            SELECT SUM(CURRENT_PERIOD)
            FROM
            (
                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_BALANCE(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)

                UNION ALL

                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_RISING(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)

                UNION ALL

                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_DEBIT_CREDIT(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)

                UNION ALL

                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_CAL(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)
            )
            INTO :CURRENT_PERIOD;

            UPDATE TEMP_FINANCIAL_REPORT
            SET CURRENT_PERIOD = CURRENT_PERIOD + :CURRENT_PERIOD,
            PREVIOUS_PERIOD = PREVIOUS_PERIOD + :PREVIOUS_PERIOD
            WHERE ID = :FINANCIAL_REPORT;
        END
        ELSE
        BEGIN
            SELECT SUM(CURRENT_PERIOD), SUM(PREVIOUS_PERIOD)
            FROM
            (
                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_BALANCE(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)

                UNION ALL

                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_RISING(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)

                UNION ALL

                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_DEBIT_CREDIT(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)

                UNION ALL

                SELECT CURRENT_PERIOD, PREVIOUS_PERIOD
                FROM INT_CAL_FINANCIAL_CAL(:P_COMPANY, :FINANCIAL_REPORT, :P_TU_NGAY, :P_DEN_NGAY, :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)
            )
            INTO :CURRENT_PERIOD, :PREVIOUS_PERIOD;

            UPDATE TEMP_FINANCIAL_REPORT
            SET CURRENT_PERIOD = CURRENT_PERIOD + :CURRENT_PERIOD,
            PREVIOUS_PERIOD = PREVIOUS_PERIOD + :PREVIOUS_PERIOD
            WHERE ID = :FINANCIAL_REPORT;
        END
    END
END ^

ALTER PROCEDURE INT_CAL_FINANCIAL_BALANCE (P_COMPANY DM_ID,
P_FINANCIAL_REPORT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_TU_NGAY_KY_TRUOC DM_DATE,
P_DEN_NGAY_KY_TRUOC DM_DATE)
RETURNS (CURRENT_PERIOD DM_DOUBLE,
PREVIOUS_PERIOD DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE SIDE DM_SIDE_OBJECT;
DECLARE VARIABLE GREATER_ZERO DM_BOOL;
DECLARE VARIABLE RATE DM_DOUBLE;
DECLARE VARIABLE DEBIT DM_DOUBLE;
DECLARE VARIABLE CREDIT DM_DOUBLE;
DECLARE VARIABLE RESULT DM_DOUBLE;
BEGIN
    CURRENT_PERIOD = 0;
    PREVIOUS_PERIOD = 0;

    FOR
        SELECT ACCOUNT, SIDE, GREATER_ZERO, RATE
        FROM FINANCIAL_BALANCES
        WHERE FINANCIAL_BALANCES.COMPANY = :P_COMPANY AND FINANCIAL_BALANCES.FINANCIAL_REPORT = :P_FINANCIAL_REPORT
        INTO :ACCOUNT, :SIDE, :GREATER_ZERO, :RATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :ACCOUNT
        INTO :ACCOUNT_CODE;

        IF(SIDE = 0 OR SIDE = 1)THEN 
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
            INTO :DEBIT, :CREDIT;

            IF(SIDE = 0)THEN
                RESULT = DEBIT - CREDIT;
            ELSE
                RESULT = CREDIT - DEBIT;

            IF(GREATER_ZERO = 0 OR (GREATER_ZERO = 1 AND RESULT > 0))THEN
                PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);

            SELECT DEBIT, CREDIT                         
            FROM INT_SD_1_TK_CN_C(:P_COMPANY, :ACCOUNT_CODE, :P_DEN_NGAY)
            INTO :DEBIT, :CREDIT;

            IF(SIDE = 0)THEN
                RESULT = DEBIT - CREDIT;
            ELSE
                RESULT = CREDIT - DEBIT;

            IF(GREATER_ZERO = 0 OR (GREATER_ZERO = 1 AND RESULT > 0))THEN
                CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
        END
        ELSE IF(SIDE = 4 OR SIDE = 5)THEN 
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC)
            INTO :DEBIT, :CREDIT;

            IF(SIDE = 4)THEN
                RESULT = DEBIT - CREDIT;
            ELSE
                RESULT = CREDIT - DEBIT;

            IF(GREATER_ZERO = 0 OR (GREATER_ZERO = 1 AND RESULT > 0))THEN
                PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);

            SELECT DEBIT, CREDIT                         
            FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
            INTO :DEBIT, :CREDIT;

            IF(SIDE = 4)THEN
                RESULT = DEBIT - CREDIT;
            ELSE
                RESULT = CREDIT - DEBIT;

            IF(GREATER_ZERO = 0 OR (GREATER_ZERO = 1 AND RESULT > 0))THEN
                CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
        END
        ELSE
        BEGIN
            IF(SIDE = 2 AND GREATER_ZERO = 0)THEN
            BEGIN
                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);


                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_CN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_DEN_NGAY)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 2 AND GREATER_ZERO = 1)THEN
            BEGIN
                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                WHERE DEBIT > CREDIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);


                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_CN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_DEN_NGAY)
                WHERE DEBIT > CREDIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 3 AND GREATER_ZERO = 0)THEN
            BEGIN
                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);


                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_CN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_DEN_NGAY)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 3 AND GREATER_ZERO = 1)THEN
            BEGIN
                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                WHERE CREDIT > DEBIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
