                FROM INT_SD_1_TK_DT0_CN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_DEN_NGAY)
                WHERE CREDIT > DEBIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 6 AND GREATER_ZERO = 0)THEN
            BEGIN
                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);

                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 6 AND GREATER_ZERO = 1)THEN
            BEGIN
                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC)
                WHERE DEBIT > CREDIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);


                SELECT SUM(DEBIT - CREDIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                WHERE DEBIT > CREDIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 7 AND GREATER_ZERO = 0)THEN
            BEGIN
                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);


                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END

            IF(SIDE = 7 AND GREATER_ZERO = 1)THEN
            BEGIN
                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC)
                WHERE CREDIT > DEBIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(RESULT*RATE, 0);


                SELECT SUM(CREDIT - DEBIT)
                FROM INT_SD_1_TK_DT0_DN_C_NULL_DT0(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
                WHERE CREDIT > DEBIT
                INTO :RESULT;

                IF(RESULT IS NOT NULL)THEN
                    CURRENT_PERIOD = CURRENT_PERIOD + ROUND(RESULT*RATE, 0);
            END
        END
    END

    SUSPEND;
END ^

ALTER PROCEDURE INT_CAL_FINANCIAL_CAL (P_COMPANY DM_ID,
P_FINANCIAL_REPORT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_TU_NGAY_KY_TRUOC DM_DATE,
P_DEN_NGAY_KY_TRUOC DM_DATE)
RETURNS (CURRENT_PERIOD DM_DOUBLE,
PREVIOUS_PERIOD DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(ROUND(CURRENT_PERIOD*FINANCIAL_CALS.RATE, 0))
    FROM TEMP_FINANCIAL_REPORT
    JOIN FINANCIAL_CALS ON FINANCIAL_CALS.COMPANY = :P_COMPANY AND FINANCIAL_CALS.FINANCIAL_REPORT = :P_FINANCIAL_REPORT AND FINANCIAL_CALS.FINANCIAL = TEMP_FINANCIAL_REPORT.ID
    WHERE FINANCIAL_CALS.GREATER_ZERO = 0 OR CURRENT_PERIOD > 0
    INTO :CURRENT_PERIOD;

    SELECT SUM(ROUND(PREVIOUS_PERIOD*FINANCIAL_CALS.RATE, 0))
    FROM TEMP_FINANCIAL_REPORT
    JOIN FINANCIAL_CALS ON FINANCIAL_CALS.COMPANY = :P_COMPANY AND FINANCIAL_CALS.FINANCIAL_REPORT = :P_FINANCIAL_REPORT AND FINANCIAL_CALS.FINANCIAL = TEMP_FINANCIAL_REPORT.ID
    WHERE FINANCIAL_CALS.GREATER_ZERO = 0 OR PREVIOUS_PERIOD > 0
    INTO :PREVIOUS_PERIOD;

    IF(CURRENT_PERIOD IS NULL)THEN CURRENT_PERIOD = 0;
    IF(PREVIOUS_PERIOD IS NULL)THEN PREVIOUS_PERIOD = 0;

    SUSPEND;
END ^

ALTER PROCEDURE INT_CAL_FINANCIAL_DEBIT_CREDIT (P_COMPANY DM_ID,
P_FINANCIAL_REPORT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_TU_NGAY_KY_TRUOC DM_DATE,
P_DEN_NGAY_KY_TRUOC DM_DATE)
RETURNS (CURRENT_PERIOD DM_DOUBLE,
PREVIOUS_PERIOD DM_DOUBLE)
AS 
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE RATE DM_DOUBLE;
DECLARE VARIABLE SUM_OF_MONEY DM_DOUBLE;
BEGIN
    CURRENT_PERIOD = 0;
    PREVIOUS_PERIOD = 0;

    FOR
        SELECT DEBIT_ACCOUNT, CREDIT_ACCOUNT, RATE
        FROM FINANCIAL_DEBIT_CREDITS
        WHERE FINANCIAL_DEBIT_CREDITS.COMPANY = :P_COMPANY AND FINANCIAL_DEBIT_CREDITS.FINANCIAL_REPORT = :P_FINANCIAL_REPORT
        INTO :DEBIT_ACCOUNT, :CREDIT_ACCOUNT, :RATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_ACCOUNT
        INTO :DEBIT_ACCOUNT_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_ACCOUNT
        INTO :CREDIT_ACCOUNT_CODE;

        SELECT SUM_OF_MONEY
        FROM INT_PS_CAP_TK_C(:P_COMPANY, :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        INTO :SUM_OF_MONEY;

        CURRENT_PERIOD = CURRENT_PERIOD + ROUND(SUM_OF_MONEY*RATE, 0);

        SELECT SUM_OF_MONEY
        FROM INT_PS_CAP_TK_C(:P_COMPANY, :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC, :P_DEN_NGAY_KY_TRUOC)
        INTO :SUM_OF_MONEY;

        PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(SUM_OF_MONEY*RATE, 0);
    END

    SUSPEND;
END ^

ALTER PROCEDURE INT_CAL_FINANCIAL_RISING (P_COMPANY DM_ID,
P_FINANCIAL_REPORT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_TU_NGAY_KY_TRUOC DM_DATE,
P_DEN_NGAY_KY_TRUOC DM_DATE)
RETURNS (CURRENT_PERIOD DM_DOUBLE,
PREVIOUS_PERIOD DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE SIDE DM_SIDE;
DECLARE VARIABLE RATE DM_DOUBLE;
DECLARE VARIABLE DEBIT DM_DOUBLE;
DECLARE VARIABLE CREDIT DM_DOUBLE;
BEGIN
    CURRENT_PERIOD = 0;
    PREVIOUS_PERIOD = 0;

    FOR
        SELECT ACCOUNT, SIDE, RATE
        FROM FINANCIAL_RISINGS
        WHERE FINANCIAL_RISINGS.COMPANY = :P_COMPANY AND FINANCIAL_RISINGS.FINANCIAL_REPORT = :P_FINANCIAL_REPORT
        INTO :ACCOUNT, :SIDE, :RATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :ACCOUNT
        INTO :ACCOUNT_CODE;
        
        SELECT DEBIT, CREDIT
        FROM INT_PS_1_TK_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY_KY_TRUOC, :P_DEN_NGAY_KY_TRUOC)
        INTO :DEBIT, :CREDIT;

        IF(SIDE = 0)THEN
            PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(DEBIT*RATE, 0);
        ELSE
            PREVIOUS_PERIOD = PREVIOUS_PERIOD + ROUND(CREDIT*RATE, 0);

        SELECT DEBIT, CREDIT
        FROM INT_PS_1_TK_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        INTO :DEBIT, :CREDIT;

        IF(SIDE = 0)THEN
            CURRENT_PERIOD = CURRENT_PERIOD + ROUND(DEBIT*RATE, 0);
        ELSE
            CURRENT_PERIOD = CURRENT_PERIOD + ROUND(CREDIT*RATE, 0);
    END

    SUSPEND;
END ^

ALTER PROCEDURE INT_DATE_TIME_TYPE_TO_TIMES (P_TIME_TYPE DM_TIME_TYPE,
P_DATE DM_DATE)
RETURNS (TIME_1 DM_INTEGER,
TIME_2 DM_INTEGER,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
    TIME_1 = EXTRACT(MONTH FROM P_DATE);
    TIME_2 = EXTRACT(YEAR FROM P_DATE);

    IF(P_TIME_TYPE = 2)THEN
    BEGIN
        SELECT :TIME_2 || '.' || :TIME_1 || '.1', :TIME_2 || '.' || :TIME_1 || '.' || ENDING_DAY
        FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(P_TIME_TYPE = 3)THEN
    BEGIN
        TIME_1 = (TIME_1 + 2)/3;
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_QUARTER_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(P_TIME_TYPE = 4)THEN
    BEGIN
        TIME_1 = IIF(TIME_1 < 7, 0, 1);
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_HALF_YEAR(:TIME_1, :TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(P_TIME_TYPE = 5)THEN
    BEGIN
        TIME_1 = TIME_2;
        BEGINNING_DATE = TIME_2 || '.1.1';
        ENDING_DATE = TIME_2 || '.12.31';
    END

    SUSPEND;
END ^

ALTER PROCEDURE INT_DEMO_DOCUMENT (P_COMPANY DM_ID,
P_EMPLOYEE_1 DM_ID,
P_EMPLOYEE_2 DM_ID,
P_CUSTOMER_1 DM_ID,
