P_CUSTOMER_3 DM_ID,
P_WAREHOUSE DM_ID,
P_GOODS_1 DM_ID,
P_GOODS_2 DM_ID,
P_GOODS_3 DM_ID,
P_GOODS_4 DM_ID,
P_GOODS_5 DM_ID)
AS 
DECLARE VARIABLE DOCUMENT_TEAM_PC DM_ID;
DECLARE VARIABLE DOCUMENT_TEAM_PC_CODE DM_CODE;
DECLARE VARIABLE DOCUMENT_TEAM_PT DM_ID;
DECLARE VARIABLE DOCUMENT_TEAM_PT_CODE DM_CODE;
DECLARE VARIABLE DOCUMENT_TEAM_NUMBER DM_CODE;
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE MAIN_CURRENCY DM_ID;
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE CONTENT DM_CONTENT;
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE INVOICE_SERIAL DM_CODE;
DECLARE VARIABLE INVOICE_CODE DM_INTEGER;
DECLARE VARIABLE N DM_INTEGER;
BEGIN
    SELECT MAIN_CURRENCY
    FROM ACCOUNTING_SETTINGS
    WHERE COMPANY = :P_COMPANY
    INTO :MAIN_CURRENCY;

    
    SELECT DOCUMENT_TEAMS.ID, DOCUMENT_TEAMS.DEFAULT_CODE
    FROM DOCUMENT_TEAMS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEAMS.ID AND ATOMS.CODE = 'PC'
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY
    INTO :DOCUMENT_TEAM_PC, :DOCUMENT_TEAM_PC_CODE;

    
    SELECT DOCUMENT_TEAMS.ID, DOCUMENT_TEAMS.DEFAULT_CODE
    FROM DOCUMENT_TEAMS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEAMS.ID AND ATOMS.CODE = 'PT'
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY
    INTO :DOCUMENT_TEAM_PT, :DOCUMENT_TEAM_PT_CODE;

    
    N = -1;
    FOR
        SELECT PERIODS.ID, BEGINNING_DATE
        FROM PERIODS
        WHERE PERIODS.COMPANY = :P_COMPANY
        ORDER BY PERIODS.BEGINNING_DATE
        INTO :PERIOD, :BEGINNING_DATE
    DO
    BEGIN
        N = N + 1;
        N = MOD(N, 3);
        IF(N = 0)THEN
        BEGIN
            
            
            SELECT CMD_MADE_DOCUMENT_NUMBER.NUMBER
            FROM CMD_MADE_DOCUMENT_NUMBER(:P_COMPANY, :DOCUMENT_TEAM_PC_CODE, :BEGINNING_DATE)
            INTO :DOCUMENT_TEAM_NUMBER;

            DOCUMENT = GEN_ID(UNIVERSE, 1);
            INVOICE_SERIAL = 'AA/13P';
            INVOICE_CODE = TRUNC(1000000 + RAND()*99999);
            CONTENT = 'Chi phí theo hóa đơn ' || INVOICE_SERIAL || '-' || INVOICE_CODE;
            EXECUTE PROCEDURE DOCUMENT_IU(0, :P_COMPANY, DOCUMENT, '(Chứng từ mẫu do phần mềm tự động phát sinh)', 0, NULL, NULL, NULL, NULL,
                :DOCUMENT_TEAM_PC_CODE, :DOCUMENT_TEAM_NUMBER, :MAIN_CURRENCY, 1, :BEGINNING_DATE, NULL, NULL, :PERIOD, :DOCUMENT_TEAM_PC, :BEGINNING_DATE, P_EMPLOYEE_1, 'Phạm Trần Bi', 'Sài gòn', CONTENT, 0, 0);

            SELECT FIRST 1 ACCOUNTS.ID
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH '642' AND
            (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            INTO :DEBIT_ACCOUNT;

            SELECT FIRST 1 ACCOUNTS.ID
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH '111' AND
            (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            INTO :CREDIT_ACCOUNT;

            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(0, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, MAIN_CURRENCY, DOCUMENT, 1, 0.1, 0, NULL, NULL, CONTENT, GEN_ID(UNIVERSE, 1), :DEBIT_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), CREDIT_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, 100000);

            SELECT FIRST 1 ACCOUNTS.ID
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH '1331' AND
            (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            INTO :DEBIT_ACCOUNT;

            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(0, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, MAIN_CURRENCY, DOCUMENT, 1, 0.1, 0, NULL, NULL, 'Thuế GTGT đầu vào của HHDV', GEN_ID(UNIVERSE, 1), :DEBIT_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), CREDIT_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, 10000);

            EXECUTE PROCEDURE INVOICE_IU(0, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, 'Tiền mặt', NULL, NULL, NULL, 'Quận A, Thành phố B', 'Công ty Phần mềm TONY', '0400614124', DOCUMENT, 'Phần mềm kế toán', 'Bộ', BEGINNING_DATE, INVOICE_CODE, BEGINNING_DATE, '01GTKT2/003','01GTKT', 7, INVOICE_SERIAL, 100000, 10000, 0.1, NULL, 0);

            
            SELECT CMD_MADE_DOCUMENT_NUMBER.NUMBER
