            INTO :DOCUMENT_TEAM_NUMBER;

            DOCUMENT = GEN_ID(UNIVERSE, 1);
            CONTENT = 'Góp vốn của chủ sở hữu';
            EXECUTE PROCEDURE DOCUMENT_IU(0, :P_COMPANY, DOCUMENT, '(Chứng từ mẫu do phần mềm tự động phát sinh)', 0, NULL, NULL, NULL, NULL,
                :DOCUMENT_TEAM_PT_CODE, :DOCUMENT_TEAM_NUMBER, :MAIN_CURRENCY, 1, :BEGINNING_DATE, NULL, NULL, :PERIOD, :DOCUMENT_TEAM_PT, :BEGINNING_DATE, P_EMPLOYEE_2, 'Phạm Lê Vy', 'Đà Nẵng', CONTENT, 0, 0);

            SELECT FIRST 1 ACCOUNTS.ID
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH '111' AND
            (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            INTO :DEBIT_ACCOUNT;

            SELECT FIRST 1 ACCOUNTS.ID
            FROM ACCOUNTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH '411' AND
            (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
            WHERE ACCOUNTS.COMPANY = :P_COMPANY
            INTO :CREDIT_ACCOUNT;

            EXECUTE PROCEDURE DOUBLE_ENTRY_IU(0, P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, MAIN_CURRENCY, DOCUMENT, 1, 0.1, 0, NULL, NULL, CONTENT, GEN_ID(UNIVERSE, 1), :DEBIT_ACCOUNT, NULL, NULL, NULL, GEN_ID(UNIVERSE, 1), CREDIT_ACCOUNT, NULL, NULL, NULL, 0, 0, 0, 100000000);
        END
        ELSE IF(N = 1)THEN
        BEGIN
            
