ALTER PROCEDURE INT_DT0_1_TK_DN_C (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID)
AS 
declare variable period dm_id;
declare variable beginning_date dm_date;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_NGAY)THEN
    BEGIN
        FOR
            SELECT OBJECT0
            FROM BALANCES
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BALANCES.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT0 IS NOT NULL
            GROUP BY OBJECT0
            INTO :OBJECT0
        DO
        BEGIN
            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT OBJECT0
            FROM
            (
                SELECT OBJECT0
                FROM BALANCES
                JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BALANCES.ACCOUNT
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT0 IS NOT NULL

                UNION ALL

                SELECT OBJECT0
                FROM INT_dt0_PS_1_TK_C(:P_COMPANY, :P_ACCOUNT_CODE, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
            )
            GROUP BY OBJECT0
            INTO :OBJECT0
        DO
        BEGIN
            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_DT0_PS_1_TK_C (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID)
AS 
BEGIN
    FOR
        SELECT OBJECT0
        FROM
        (
            SELECT CREDIT_DEBIT.OBJECT0
            FROM CREDIT_DEBIT
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.OBJECT0 IS NOT NULL AND
            CREDIT_DEBIT.SIDE = 0 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.OBJECT0
        FROM CREDIT_DEBIT
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.OBJECT0 IS NOT NULL AND
            CREDIT_DEBIT.SIDE = 1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY OBJECT0
    INTO :OBJECT0
DO
    SUSPEND;
end ^

ALTER PROCEDURE INT_DU_1_TK_1_DT0_C (P_COMPANY DM_ID,
P_SIDE DM_SIDE,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_INCLUDE1 DM_CODE,
P_INCLUDE2 DM_CODE)
RETURNS (ACCOUNTS DM_STRING)
AS 
BEGIN
    SELECT LIST(CODE, ', ')
    FROM
    (
        SELECT DISTINCT ATOMS_A.CODE
        FROM CREDIT_DEBIT CREDIT_DEBIT_A
        JOIN ACCOUNTS ACCOUNTS_A ON ACCOUNTS_A.COMPANY = :P_COMPANY AND ACCOUNTS_A.ID = CREDIT_DEBIT_A.ACCOUNT
        JOIN ATOMS ATOMS_A ON ATOMS_A.COMPANY = :P_COMPANY AND ATOMS_A.ID = ACCOUNTS_A.ID AND (ATOMS_A.CODE STARTING WITH :P_INCLUDE1 OR ATOMS_A.CODE STARTING WITH :P_INCLUDE2)
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = CREDIT_DEBIT_A.ENTRY
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN CREDIT_DEBIT CREDIT_DEBIT_DU ON CREDIT_DEBIT_DU.COMPANY = :P_COMPANY AND CREDIT_DEBIT_DU.ENTRY = CREDIT_DEBIT_A.ENTRY AND CREDIT_DEBIT_DU.SIDE = :P_SIDE AND CREDIT_DEBIT_DU.OBJECT0 = :P_OBJECT0
        JOIN ACCOUNTS ACCOUNTS_DU ON ACCOUNTS_DU.COMPANY = :P_COMPANY AND ACCOUNTS_DU.ID = CREDIT_DEBIT_DU.ACCOUNT
        JOIN ATOMS ATOMS_DU ON ATOMS_DU.COMPANY = :P_COMPANY AND ATOMS_DU.ID = ACCOUNTS_DU.ID AND ATOMS_DU.CODE STARTING WITH :P_ACCOUNT_CODE
        WHERE CREDIT_DEBIT_A.COMPANY = :P_COMPANY AND CREDIT_DEBIT_A.SIDE = (1 - :P_SIDE)
        ORDER BY ATOMS_A.CODE
    )
    INTO :ACCOUNTS;
    SUSPEND;
END ^

ALTER PROCEDURE INT_ENDING_DATES_OF_HALF_YEAR (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
RETURNS (BEGINNING_DATE_OF_HALF_YEAR DM_DATE,
ENDING_DATE_OF_HALF_YEAR DM_DATE)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_MONTH DM_INTEGER;
BEGIN
    BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE);
    BEGINNING_MONTH = EXTRACT(MONTH FROM BEGINNING_DATE);

    ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE);
    ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE);

    WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH)))
    DO
    BEGIN
        IF(BEGINNING_MONTH = 6)THEN
        BEGIN
            BEGINNING_DATE_OF_HALF_YEAR = BEGINNING_YEAR || '.1.1';
            ENDING_DATE_OF_HALF_YEAR = BEGINNING_YEAR || '.6.30';
        END
        ELSE IF(BEGINNING_MONTH = 12)THEN
        BEGIN
            BEGINNING_DATE_OF_HALF_YEAR = BEGINNING_YEAR || '.7.1';
            ENDING_DATE_OF_HALF_YEAR = BEGINNING_YEAR || '.12.31';
        END
        ELSE
        BEGIN
            BEGINNING_DATE_OF_HALF_YEAR = NULL;
            ENDING_DATE_OF_HALF_YEAR = NULL;
        END

        IF(ENDING_DATE_OF_HALF_YEAR IS NOT NULL AND ENDING_DATE_OF_HALF_YEAR BETWEEN :BEGINNING_DATE AND :ENDING_DATE)THEN
            SUSPEND;

        IF(BEGINNING_MONTH < 12)THEN
            BEGINNING_MONTH = BEGINNING_MONTH + 1;
        ELSE
        BEGIN
            BEGINNING_MONTH = 1;
            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
END ^

ALTER PROCEDURE INT_ENDING_DATES_OF_MONTH (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
RETURNS (BEGINNING_DATE_OF_MONTH DM_DATE,
ENDING_DATE_OF_MONTH DM_DATE,
NAME_OF_MONTH DM_NAME)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_MONTH DM_INTEGER;
BEGIN
    BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE);
    BEGINNING_MONTH = EXTRACT(MONTH FROM BEGINNING_DATE);

    ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE);
    ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE);

    WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH)))
    DO
    BEGIN
        BEGINNING_DATE_OF_MONTH = BEGINNING_YEAR || '.' || BEGINNING_MONTH || '.1';
        NAME_OF_MONTH = 'T' || BEGINNING_MONTH || '/' || BEGINNING_YEAR;

        SELECT CASE :BEGINNING_MONTH
                    WHEN 1 THEN :BEGINNING_YEAR || '.1.31'
                    WHEN 2 THEN :BEGINNING_YEAR || '.2.28'
                    WHEN 3 THEN :BEGINNING_YEAR || '.3.31'
                    WHEN 4 THEN :BEGINNING_YEAR || '.4.30'
                    WHEN 5 THEN :BEGINNING_YEAR || '.5.31'
                    WHEN 6 THEN :BEGINNING_YEAR || '.6.30'
                    WHEN 7 THEN :BEGINNING_YEAR || '.7.31'
                    WHEN 8 THEN :BEGINNING_YEAR || '.8.31'
                    WHEN 9 THEN :BEGINNING_YEAR || '.9.30'
                    WHEN 10 THEN :BEGINNING_YEAR || '.10.31'
                    WHEN 11 THEN :BEGINNING_YEAR || '.11.30'
                    ELSE :BEGINNING_YEAR || '.12.31'
                   END
        FROM RDB$DATABASE
        INTO :ENDING_DATE_OF_MONTH;

        IF(BEGINNING_MONTH = 2)THEN
            IF(MOD(BEGINNING_YEAR, 400) = 0 OR (MOD(BEGINNING_YEAR, 4) = 0 AND (MOD(BEGINNING_YEAR, 100) <> 0)))THEN
                ENDING_DATE_OF_MONTH = BEGINNING_YEAR || '.2.29';
            ELSE
                ENDING_DATE_OF_MONTH = BEGINNING_YEAR || '.2.28';

        IF(ENDING_DATE_OF_MONTH BETWEEN :BEGINNING_DATE AND :ENDING_DATE)THEN
            SUSPEND;

        IF(BEGINNING_MONTH < 12)THEN
            BEGINNING_MONTH = BEGINNING_MONTH + 1;
        ELSE
        BEGIN
            BEGINNING_MONTH = 1;
            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
END ^

ALTER PROCEDURE INT_ENDING_DATES_OF_QUARTER (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
RETURNS (BEGINNING_DATE_OF_QUARTER DM_DATE,
ENDING_DATE_OF_QUARTER DM_DATE,
NAME_OF_QUARTER DM_NAME)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_MONTH DM_INTEGER;
BEGIN
    BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE);
    BEGINNING_MONTH = EXTRACT(MONTH FROM BEGINNING_DATE);

    ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE);
    ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE);

    WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH)))
    DO
    BEGIN
        IF(BEGINNING_MONTH = 3)THEN
        BEGIN
            BEGINNING_DATE_OF_QUARTER = BEGINNING_YEAR || '.1.1';
            ENDING_DATE_OF_QUARTER = BEGINNING_YEAR || '.3.31';
        END
        ELSE IF(BEGINNING_MONTH = 6)THEN
        BEGIN
            BEGINNING_DATE_OF_QUARTER = BEGINNING_YEAR || '.4.1';
            ENDING_DATE_OF_QUARTER = BEGINNING_YEAR || '.6.30';
        END
        ELSE IF(BEGINNING_MONTH = 9)THEN
        BEGIN
            BEGINNING_DATE_OF_QUARTER = BEGINNING_YEAR || '.7.1';
            ENDING_DATE_OF_QUARTER = BEGINNING_YEAR || '.9.30';
        END
        ELSE IF(BEGINNING_MONTH = 12)THEN
        BEGIN
            BEGINNING_DATE_OF_QUARTER = BEGINNING_YEAR || '.10.1';
            ENDING_DATE_OF_QUARTER = BEGINNING_YEAR || '.12.31';
        END
        ELSE
        BEGIN
            BEGINNING_DATE_OF_QUARTER = NULL;
            ENDING_DATE_OF_QUARTER = NULL;
        END

        IF(ENDING_DATE_OF_QUARTER IS NOT NULL AND ENDING_DATE_OF_QUARTER BETWEEN :BEGINNING_DATE AND :ENDING_DATE)THEN
        BEGIN
            NAME_OF_QUARTER = 'Quý ' || (BEGINNING_MONTH/3) || '/' || BEGINNING_YEAR;
            SUSPEND;
        END

        IF(BEGINNING_MONTH < 12)THEN
            BEGINNING_MONTH = BEGINNING_MONTH + 1;
        ELSE
        BEGIN
            BEGINNING_MONTH = 1;
            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
END ^

ALTER PROCEDURE INT_ENDING_DATES_OF_YEAR (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
RETURNS (BEGINNING_DATE_OF_YEAR DM_DATE,
ENDING_DATE_OF_YEAR DM_DATE)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_MONTH DM_INTEGER;
BEGIN
    BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE);
    BEGINNING_MONTH = EXTRACT(MONTH FROM BEGINNING_DATE);

    ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE);
    ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE);

    WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH)))
    DO
    BEGIN
        IF(BEGINNING_MONTH < 12)THEN
            BEGINNING_MONTH = BEGINNING_MONTH + 1;
        ELSE
        BEGIN
            BEGINNING_DATE_OF_YEAR = BEGINNING_YEAR || '.1.1';
            ENDING_DATE_OF_YEAR = BEGINNING_YEAR || '.12.31';

            IF(ENDING_DATE_OF_YEAR BETWEEN :BEGINNING_DATE AND :ENDING_DATE)THEN
                SUSPEND;

            BEGINNING_MONTH = 1;
            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
END ^

ALTER PROCEDURE INT_FILIFO_ENTRY (P_COMPANY DM_ID,
P_OUTPUT_DATE DM_DATE,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_OUTPUT_AMOUNT DM_DOUBLE,
P_CREDIT_DEBIT DM_ID,
P_SIDE DM_SIDE,
P_NUMBER_DECIMAL_DIGITS DM_INTEGER)
RETURNS (REMAINING_AMOUNT DM_DOUBLE)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRICE DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE DOCUMENT_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    
    DELETE FROM DECREASE_ENTRIES
    WHERE DECREASE_ENTRIES.COMPANY = :P_COMPANY AND DECREASE_ENTRIES.CREDIT_DEBIT = :P_CREDIT_DEBIT;

    
    FOR
        SELECT ID, AMOUNT,  PRICE, OFFICIAL_SUM_OF_MONEY
        FROM ENTRY_BALANCE_S_RS(0, :P_COMPANY, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_OUTPUT_DATE, :P_SIDE)
        INTO :ID, :AMOUNT, :PRICE, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        
        SELECT ENTRIES.DOCUMENT
        FROM ENTRIES
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ID = :ID
        INTO :DOCUMENT;

        
        SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR DEBIT.OBJECT1 = :P_OBJECT1) AND (:P_OBJECT2 IS NULL OR DEBIT.OBJECT2 = :P_OBJECT2) AND DEBIT.AMOUNT = 0
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :DOCUMENT
        INTO :DOCUMENT_OFFICIAL_SUM_OF_MONEY;

        IF(DOCUMENT_OFFICIAL_SUM_OF_MONEY IS NULL)THEN DOCUMENT_OFFICIAL_SUM_OF_MONEY = 0;

        
        
        IF(DOCUMENT_OFFICIAL_SUM_OF_MONEY > 0)THEN
        BEGIN
            
            OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY + DOCUMENT_OFFICIAL_SUM_OF_MONEY;
            PRICE = ROUND(OFFICIAL_SUM_OF_MONEY/AMOUNT, :P_NUMBER_DECIMAL_DIGITS);
        END

        IF(AMOUNT > P_OUTPUT_AMOUNT)THEN
        BEGIN
            EXECUTE PROCEDURE DECREASE_ENTRY_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :ID, :P_CREDIT_DEBIT, :P_OUTPUT_AMOUNT, ROUND(:PRICE*:P_OUTPUT_AMOUNT, 0), 0);

            P_OUTPUT_AMOUNT = 0;

            LEAVE; 
        END
        ELSE
        BEGIN
            EXECUTE PROCEDURE DECREASE_ENTRY_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :ID, :P_CREDIT_DEBIT, :AMOUNT, :OFFICIAL_SUM_OF_MONEY, 0);

            P_OUTPUT_AMOUNT = P_OUTPUT_AMOUNT - AMOUNT;

            IF(P_OUTPUT_AMOUNT = 0)THEN LEAVE;
        END
    END

    REMAINING_AMOUNT = P_OUTPUT_AMOUNT;

    SUSPEND;
END ^

ALTER PROCEDURE INT_HALF_YEAR_DIFF (COMPANY DM_ID,
PREPAID_EXPENSE DM_ID,
MAIN_FROM_HALF_YEAR DM_INTEGER,
MAIN_FROM_YEAR DM_INTEGER,
MAIN_HALF_YEARS DM_SMALLINT,
BEGINNING_DATE_OF_PERIOD DM_DATE,
ENDING_DATE_OF_PERIOD DM_DATE)
RETURNS (ENDING_DATE_OF_HALF_YEAR DM_DATE,
REMAINING_HALF_YEARS DM_SMALLINT)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_HALF_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_HALF_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_FROM_HALF_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_FROM_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_HALF_YEARS DM_SMALLINT;
BEGIN
    IF(EXISTS (SELECT * FROM PREPAID_EXPENSE_PERIODS WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE))THEN
    BEGIN
        BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE_OF_PERIOD);
        BEGINNING_HALF_YEAR = IIF(EXTRACT(MONTH FROM BEGINNING_DATE_OF_PERIOD) < 7, 0, 1);

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_HALF_YEAR = IIF(EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD) < 7, 0, 1);

        WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_HALF_YEAR <= ENDING_HALF_YEAR)))
        DO
        BEGIN
            NEW_FROM_HALF_YEAR = NULL;

            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, DEPRECIATION_PERIOD
            FROM PREPAID_EXPENSE_PERIODS
            WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND
            PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :BEGINNING_HALF_YEAR AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE2 <= :BEGINNING_YEAR
            ORDER BY BEGINNING_DEPRECIATION_VALUE2 DESC, BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :NEW_FROM_HALF_YEAR, :NEW_FROM_YEAR, :NEW_HALF_YEARS;

            IF(NEW_FROM_HALF_YEAR IS NULL)THEN
            BEGIN
                NEW_FROM_HALF_YEAR = MAIN_FROM_HALF_YEAR;
                NEW_FROM_YEAR = MAIN_FROM_YEAR;
                NEW_HALF_YEARS = MAIN_HALF_YEARS;
            END

            IF((NEW_FROM_YEAR < BEGINNING_YEAR) OR ((NEW_FROM_YEAR = BEGINNING_YEAR) AND (NEW_FROM_HALF_YEAR <= BEGINNING_HALF_YEAR)))THEN
            BEGIN
                REMAINING_HALF_YEARS = NEW_HALF_YEARS - (BEGINNING_YEAR - NEW_FROM_YEAR)*2 - (BEGINNING_HALF_YEAR - NEW_FROM_HALF_YEAR);
                IF(REMAINING_HALF_YEARS > 0)THEN
                BEGIN
                    SELECT CASE :BEGINNING_HALF_YEAR
                    WHEN 0 THEN :BEGINNING_YEAR || '.6.30'
                    WHEN 1 THEN :BEGINNING_YEAR || '.12.31'
                    ELSE NULL
                    END
                    FROM RDB$DATABASE
                    INTO :ENDING_DATE_OF_HALF_YEAR;

                    IF(ENDING_DATE_OF_HALF_YEAR BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            IF(BEGINNING_HALF_YEAR < 1)THEN
                BEGINNING_HALF_YEAR = BEGINNING_HALF_YEAR + 1;
            ELSE
            BEGIN
                BEGINNING_HALF_YEAR = 0;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;
        BEGINNING_HALF_YEAR = MAIN_FROM_HALF_YEAR;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_HALF_YEAR = IIF(EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD) < 7, 0, 1);

        WHILE(MAIN_HALF_YEARS > 0 AND( (BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_HALF_YEAR <= ENDING_HALF_YEAR))))
        DO
        BEGIN
            MAIN_HALF_YEARS = MAIN_HALF_YEARS - 1;
            SELECT CASE :BEGINNING_HALF_YEAR
                    WHEN 0 THEN :BEGINNING_YEAR || '.6.30'
                    WHEN 1 THEN :BEGINNING_YEAR || '.12.31'
                    ELSE NULL
                   END
            FROM RDB$DATABASE
            INTO :ENDING_DATE_OF_HALF_YEAR;

            IF(ENDING_DATE_OF_HALF_YEAR IS NOT NULL AND ENDING_DATE_OF_HALF_YEAR BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_HALF_YEARS = MAIN_HALF_YEARS + 1;
                SUSPEND;
            END

            IF(BEGINNING_HALF_YEAR < 1)THEN
                BEGINNING_HALF_YEAR = BEGINNING_HALF_YEAR + 1;
            ELSE
            BEGIN
                BEGINNING_HALF_YEAR = 0;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
END ^

