                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
END ^

ALTER PROCEDURE INT_MONTH_DIFF (COMPANY DM_ID,
PREPAID_EXPENSE DM_ID,
MAIN_FROM_MONTH DM_INTEGER,
MAIN_FROM_YEAR DM_INTEGER,
MAIN_MONTHS DM_DOUBLE,
BEGINNING_DATE_OF_PERIOD DM_DATE,
ENDING_DATE_OF_PERIOD DM_DATE)
RETURNS (ENDING_DATE_OF_MONTH_OF_PERIOD DM_DATE,
REMAINING_MONTHS DM_DOUBLE)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_MONTH DM_INTEGER;
DECLARE VARIABLE NEW_FROM_MONTH DM_INTEGER;
DECLARE VARIABLE NEW_FROM_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_MONTHS DM_SMALLINT;
BEGIN
    IF(EXISTS (SELECT * FROM PREPAID_EXPENSE_PERIODS WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE))THEN
    BEGIN
        BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE_OF_PERIOD);
        BEGINNING_MONTH = EXTRACT(MONTH FROM BEGINNING_DATE_OF_PERIOD);

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD);

        WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH)))
        DO
        BEGIN
            NEW_FROM_MONTH = NULL;

            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, DEPRECIATION_PERIOD
            FROM PREPAID_EXPENSE_PERIODS
            WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND
            PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :BEGINNING_MONTH AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE2 <= :BEGINNING_YEAR
            ORDER BY BEGINNING_DEPRECIATION_VALUE2 DESC, BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :NEW_FROM_MONTH, :NEW_FROM_YEAR, :NEW_MONTHS;

            IF(NEW_FROM_MONTH IS NULL)THEN
            BEGIN
                NEW_FROM_MONTH = MAIN_FROM_MONTH;
                NEW_FROM_YEAR = MAIN_FROM_YEAR;
                NEW_MONTHS = MAIN_MONTHS;
            END

            IF((NEW_FROM_YEAR < BEGINNING_YEAR) OR ((NEW_FROM_YEAR = BEGINNING_YEAR) AND (NEW_FROM_MONTH <= BEGINNING_MONTH)))THEN
            BEGIN
                REMAINING_MONTHS = NEW_MONTHS - (BEGINNING_YEAR - NEW_FROM_YEAR)*12 - (BEGINNING_MONTH - NEW_FROM_MONTH);
                IF(REMAINING_MONTHS > 0)THEN
                BEGIN
                    SELECT :BEGINNING_YEAR || '.' || :BEGINNING_MONTH || '.' || ENDING_DAY
                    FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:BEGINNING_MONTH, :BEGINNING_YEAR)
                    INTO :ENDING_DATE_OF_MONTH_OF_PERIOD;

                    IF(ENDING_DATE_OF_MONTH_OF_PERIOD BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            IF(BEGINNING_MONTH < 12)THEN
                BEGINNING_MONTH = BEGINNING_MONTH + 1;
            ELSE
            BEGIN
                BEGINNING_MONTH = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;
        BEGINNING_MONTH = MAIN_FROM_MONTH;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD);

        WHILE(MAIN_MONTHS > 0 AND ((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH))))
        DO
        BEGIN
            MAIN_MONTHS = MAIN_MONTHS - 1;
            SELECT :BEGINNING_YEAR || '.' || :BEGINNING_MONTH || '.' || ENDING_DAY
            FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:BEGINNING_MONTH, :BEGINNING_YEAR)
            INTO :ENDING_DATE_OF_MONTH_OF_PERIOD;

            IF(ENDING_DATE_OF_MONTH_OF_PERIOD BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_MONTHS = MAIN_MONTHS + 1;
                SUSPEND;
            END
            

            IF(BEGINNING_MONTH < 12)THEN
                BEGINNING_MONTH = BEGINNING_MONTH + 1;
            ELSE
            BEGIN
                BEGINNING_MONTH = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
END ^

ALTER PROCEDURE INT_MONTH_DIFF_ASSET (COMPANY DM_ID,
ASSET DM_ID,
MAIN_FROM_MONTH DM_INTEGER,
MAIN_FROM_YEAR DM_INTEGER,
MAIN_MONTHS DM_DOUBLE,
BEGINNING_DATE_OF_PERIOD DM_DATE,
ENDING_DATE_OF_PERIOD DM_DATE)
RETURNS (ENDING_DATE_OF_MONTH_OF_PERIOD DM_DATE,
REMAINING_MONTHS DM_DOUBLE)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_MONTH DM_INTEGER;
DECLARE VARIABLE NEW_FROM_MONTH DM_INTEGER;
DECLARE VARIABLE NEW_FROM_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_MONTHS DM_DOUBLE;
BEGIN
    IF(EXISTS (SELECT * FROM ASSET_DEPRECIATION_PERIODS WHERE ASSET_DEPRECIATION_PERIODS.COMPANY = :COMPANY AND ASSET_DEPRECIATION_PERIODS.ASSET = :ASSET))THEN
    BEGIN
        BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE_OF_PERIOD);
        BEGINNING_MONTH = EXTRACT(MONTH FROM BEGINNING_DATE_OF_PERIOD);

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD);

        WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH)))
        DO
        BEGIN
            NEW_FROM_MONTH = NULL;

            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, DEPRECIATION_PERIOD
            FROM ASSET_DEPRECIATION_PERIODS
            WHERE ASSET_DEPRECIATION_PERIODS.COMPANY = :COMPANY AND
            ASSET_DEPRECIATION_PERIODS.ASSET = :ASSET AND
            ASSET_DEPRECIATION_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :BEGINNING_MONTH AND
            ASSET_DEPRECIATION_PERIODS.BEGINNING_DEPRECIATION_VALUE2 <= :BEGINNING_YEAR
            ORDER BY BEGINNING_DEPRECIATION_VALUE2 DESC, BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :NEW_FROM_MONTH, :NEW_FROM_YEAR, :NEW_MONTHS;

            IF(NEW_FROM_MONTH IS NULL)THEN
            BEGIN
                NEW_FROM_MONTH = MAIN_FROM_MONTH;
                NEW_FROM_YEAR = MAIN_FROM_YEAR;
                NEW_MONTHS = MAIN_MONTHS;
            END

            IF((NEW_FROM_YEAR < BEGINNING_YEAR) OR ((NEW_FROM_YEAR = BEGINNING_YEAR) AND (NEW_FROM_MONTH <= BEGINNING_MONTH)))THEN
            BEGIN
                REMAINING_MONTHS = NEW_MONTHS - (BEGINNING_YEAR - NEW_FROM_YEAR)*12 - (BEGINNING_MONTH - NEW_FROM_MONTH);
                IF(REMAINING_MONTHS > 0)THEN
                BEGIN
                    SELECT :BEGINNING_YEAR || '.' || :BEGINNING_MONTH || '.' || ENDING_DAY
                    FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:BEGINNING_MONTH, :BEGINNING_YEAR)
                    INTO :ENDING_DATE_OF_MONTH_OF_PERIOD;

                    IF(ENDING_DATE_OF_MONTH_OF_PERIOD BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            IF(BEGINNING_MONTH < 12)THEN
                BEGINNING_MONTH = BEGINNING_MONTH + 1;
            ELSE
            BEGIN
                BEGINNING_MONTH = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;
        BEGINNING_MONTH = MAIN_FROM_MONTH;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_MONTH = EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD);

        WHILE(MAIN_MONTHS > 0 AND ((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_MONTH <= ENDING_MONTH))))
        DO
        BEGIN
            MAIN_MONTHS = MAIN_MONTHS - 1;
            SELECT :BEGINNING_YEAR || '.' || :BEGINNING_MONTH || '.' || ENDING_DAY
            FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:BEGINNING_MONTH, :BEGINNING_YEAR)
            INTO :ENDING_DATE_OF_MONTH_OF_PERIOD;

            IF(ENDING_DATE_OF_MONTH_OF_PERIOD BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_MONTHS = MAIN_MONTHS + 1;
                SUSPEND;
            END

            

            IF(BEGINNING_MONTH < 12)THEN
                BEGINNING_MONTH = BEGINNING_MONTH + 1;
            ELSE
            BEGIN
                BEGINNING_MONTH = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
END ^

ALTER PROCEDURE INT_PS_1_KHO_VT_TK (P_COMPANY DM_ID,
P_WAREHOUSE DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GOODS DM_ID,
ACCOUNT DM_ID,
INPUT_AMOUNT DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT GOODS, ACCOUNT, SUM(INPUT_AMOUNT), SUM(OUTPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT CREDIT_DEBIT.OBJECT0 GOODS, ACCOUNT, CREDIT_DEBIT.AMOUNT INPUT_AMOUNT, 0 OUTPUT_AMOUNT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY, 0 OUTPUT_SUM_OF_MONEY
            FROM CREDIT_DEBIT
            JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.OBJECT1 = :P_WAREHOUSE AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.OBJECT0 GOODS, ACCOUNT, 0 INPUT_AMOUNT, CREDIT_DEBIT.AMOUNT OUTPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY
        FROM CREDIT_DEBIT
        JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.OBJECT1 = :P_WAREHOUSE AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY GOODS, ACCOUNT
    INTO :GOODS, :ACCOUNT, :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
DO
    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_1_TK (P_COMPANY BIGINT,
P_ACCOUNT BIGINT,
P_TU_NGAY DATE,
P_DEN_NGAY DATE)
RETURNS (DEBIT_AMOUNT DECIMAL(18, 4),
DEBIT DECIMAL(18, 4),
CREDIT_AMOUNT DECIMAL(18, 4),
CREDIT DECIMAL(18, 4))
AS 
BEGIN
    IF (NOT EXISTS(SELECT 1 FROM DOCUMENTS WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)) THEN
    BEGIN
        DEBIT_AMOUNT = 0; DEBIT = 0; CREDIT_AMOUNT = 0; CREDIT = 0;
        SUSPEND;
    END
    ELSE
    BEGIN
        SELECT
            SUM(IIF(cd.SIDE=0, cd.AMOUNT, 0)),
            SUM(IIF(cd.SIDE=0, cd.OFFICIAL_SUM_OF_MONEY, 0)),
            SUM(IIF(cd.SIDE=1, cd.AMOUNT, 0)),
            SUM(IIF(cd.SIDE=1, cd.OFFICIAL_SUM_OF_MONEY, 0))
        FROM (
            SELECT e.ID AS ENTRY_ID
            FROM DOCUMENTS d
            JOIN ENTRIES e ON e.DOCUMENT = d.ID AND e.COMPANY = d.COMPANY
            WHERE d.COMPANY = :P_COMPANY AND d.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ) de
        JOIN CREDIT_DEBIT cd ON cd.ENTRY = de.ENTRY_ID
            AND cd.COMPANY = :P_COMPANY AND cd.ACCOUNT = :P_ACCOUNT
        INTO :DEBIT_AMOUNT, :DEBIT, :CREDIT_AMOUNT, :CREDIT;

        IF (DEBIT IS NULL)        THEN DEBIT = 0;
        IF (DEBIT_AMOUNT IS NULL) THEN DEBIT_AMOUNT = 0;
        IF (CREDIT IS NULL)       THEN CREDIT = 0;
        IF (CREDIT_AMOUNT IS NULL) THEN CREDIT_AMOUNT = 0;

        SUSPEND;
    END
END ^

ALTER PROCEDURE INT_PS_1_TK_1_DT0 (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
          CREDIT_DEBIT.SIDE = 0 AND
          CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
          CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
    EXISTS
    (
        SELECT ID
        FROM ENTRIES
        WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
        EXISTS
            (
                SELECT ID
                FROM DOCUMENTS
                WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                      DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            )
    )
    INTO :DEBIT;

    SELECT SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
          CREDIT_DEBIT.SIDE = 1 AND
          CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
          CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
          EXISTS
          (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                        SELECT ID
                        FROM DOCUMENTS
                        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                              DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                    )
          )
    INTO :CREDIT;

    IF(DEBIT IS NULL)THEN DEBIT = 0;
    IF(CREDIT IS NULL)THEN CREDIT = 0;

    SUSPEND;
end ^

