ALTER PROCEDURE INT_PS_1_TK_1_DT0_1_DT1_C_EX (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_DOCUMENT DM_ID,
P_ENTRY DM_ID)
RETURNS (DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
          CREDIT_DEBIT.SIDE = 0 AND
          CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
          CREDIT_DEBIT.OBJECT1 = :P_OBJECT1 AND
    ((DOCUMENTS.ID <> :P_DOCUMENT AND (ENTRIES.ID <> :P_ENTRY OR :P_ENTRY IS NULL)) OR :P_DOCUMENT IS NULL)
    INTO :DEBIT;

    SELECT SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
          CREDIT_DEBIT.SIDE = 1 AND
          CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
          CREDIT_DEBIT.OBJECT1 = :P_OBJECT1 AND
    ((DOCUMENTS.ID <> :P_DOCUMENT AND (ENTRIES.ID <> :P_ENTRY OR :P_ENTRY IS NULL)) OR :P_DOCUMENT IS NULL)
    INTO :CREDIT;

    IF(DEBIT IS NULL)THEN DEBIT = 0;
    IF(CREDIT IS NULL)THEN CREDIT = 0;

    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_1_TK_1_DT0_1_DT1_C_TT (P_COMPANY DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (FOREIGN_DEBIT DM_DOUBLE,
FOREIGN_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
          CREDIT_DEBIT.SIDE = 0 AND
          CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
          CREDIT_DEBIT.OBJECT1 = :P_OBJECT1 AND
    EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                (ENTRIES.CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
            )
    INTO :FOREIGN_DEBIT, :OFFICIAL_DEBIT;


    SELECT SUM(CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
