ALTER PROCEDURE INT_PS_1_TK_1_DT0_DT1 (P_COMPANY BIGINT,
P_ACCOUNT BIGINT,
P_OBJECT0 BIGINT,
P_TU_NGAY DATE,
P_DEN_NGAY DATE)
RETURNS (OBJECT1 BIGINT,
DEBIT_AMOUNT DECIMAL(18, 4),
DEBIT DECIMAL(18, 4),
CREDIT_AMOUNT DECIMAL(18, 4),
CREDIT DECIMAL(18, 4))
AS 
BEGIN
    IF (NOT EXISTS(SELECT 1 FROM DOCUMENTS WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)) THEN EXIT;
    FOR
        SELECT cd.OBJECT1,
            SUM(IIF(cd.SIDE=0,cd.AMOUNT,0)), SUM(IIF(cd.SIDE=0,cd.OFFICIAL_SUM_OF_MONEY,0)),
            SUM(IIF(cd.SIDE=1,cd.AMOUNT,0)), SUM(IIF(cd.SIDE=1,cd.OFFICIAL_SUM_OF_MONEY,0))
        FROM (
            SELECT e.ID AS ENTRY_ID
            FROM DOCUMENTS d
            JOIN ENTRIES e ON e.DOCUMENT = d.ID AND e.COMPANY = d.COMPANY
            WHERE d.COMPANY = :P_COMPANY AND d.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ) de
        JOIN CREDIT_DEBIT cd ON cd.ENTRY = de.ENTRY_ID
            AND cd.COMPANY = :P_COMPANY AND cd.ACCOUNT = :P_ACCOUNT AND cd.OBJECT0 = :P_OBJECT0
        GROUP BY cd.OBJECT1
        INTO :OBJECT1,:DEBIT_AMOUNT,:DEBIT,:CREDIT_AMOUNT,:CREDIT
    DO SUSPEND;
END ^

ALTER PROCEDURE INT_PS_1_TK_1_DT0_DT1_C (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT1 DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT OBJECT1, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT CREDIT_DEBIT.OBJECT1 OBJECT1, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
            FROM CREDIT_DEBIT
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.OBJECT1 OBJECT1, 0 DEBIT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY CREDIT
        FROM CREDIT_DEBIT
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.OBJECT0 = :P_OBJECT0 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY OBJECT1
    INTO :OBJECT1, :DEBIT, :CREDIT
DO
    SUSPEND;
end ^

