ALTER PROCEDURE INT_PS_1_TK_1_DT1_DT0_C (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT OBJECT0, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT CREDIT_DEBIT.OBJECT0 OBJECT0, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
            FROM CREDIT_DEBIT
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.OBJECT1 = :P_OBJECT1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.OBJECT0 OBJECT0, 0 DEBIT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY CREDIT
        FROM CREDIT_DEBIT
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.OBJECT1 = :P_OBJECT1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY OBJECT0
    INTO :OBJECT0, :DEBIT, :CREDIT
DO
    SUSPEND;
end ^

