    CREDIT_DEBIT.SIDE = 0 AND
    ((DOCUMENTS.ID <> :P_DOCUMENT AND (ENTRIES.ID <> :P_ENTRY OR :P_ENTRY IS NULL)) OR :P_DOCUMENT IS NULL)
    INTO :FOREIGN_DEBIT, :OFFICIAL_DEBIT;

    SELECT SUM(FOREIGN_SUM_OF_MONEY), SUM(OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (ENTRIES.CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL)
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
           CREDIT_DEBIT.SIDE = 1 AND
           ((DOCUMENTS.ID <> :P_DOCUMENT AND (ENTRIES.ID <> :P_ENTRY OR :P_ENTRY IS NULL)) OR :P_DOCUMENT IS NULL)
    INTO :FOREIGN_CREDIT, :OFFICIAL_CREDIT;

    IF(FOREIGN_DEBIT IS NULL)THEN FOREIGN_DEBIT = 0;
    IF(FOREIGN_CREDIT IS NULL)THEN FOREIGN_CREDIT = 0;
    IF(OFFICIAL_DEBIT IS NULL)THEN OFFICIAL_DEBIT = 0;
    IF(OFFICIAL_CREDIT IS NULL)THEN OFFICIAL_CREDIT = 0;

    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_1_TK_DT0 (P_COMPANY BIGINT,
P_ACCOUNT BIGINT,
P_TU_NGAY DATE,
P_DEN_NGAY DATE)
RETURNS (OBJECT0 BIGINT,
DEBIT_AMOUNT DECIMAL(18, 4),
DEBIT DECIMAL(18, 4),
CREDIT_AMOUNT DECIMAL(18, 4),
CREDIT DECIMAL(18, 4))
AS 
BEGIN
    IF (NOT EXISTS(SELECT 1 FROM DOCUMENTS WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)) THEN EXIT;
    FOR
        SELECT cd.OBJECT0,
            SUM(IIF(cd.SIDE=0,cd.AMOUNT,0)), SUM(IIF(cd.SIDE=0,cd.OFFICIAL_SUM_OF_MONEY,0)),
            SUM(IIF(cd.SIDE=1,cd.AMOUNT,0)), SUM(IIF(cd.SIDE=1,cd.OFFICIAL_SUM_OF_MONEY,0))
        FROM (
            SELECT e.ID AS ENTRY_ID
            FROM DOCUMENTS d
            JOIN ENTRIES e ON e.DOCUMENT = d.ID AND e.COMPANY = d.COMPANY
            WHERE d.COMPANY = :P_COMPANY AND d.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ) de
        JOIN CREDIT_DEBIT cd ON cd.ENTRY = de.ENTRY_ID
            AND cd.COMPANY = :P_COMPANY AND cd.ACCOUNT = :P_ACCOUNT AND cd.OBJECT0 IS NOT NULL
        GROUP BY cd.OBJECT0
        INTO :OBJECT0,:DEBIT_AMOUNT,:DEBIT,:CREDIT_AMOUNT,:CREDIT
    DO SUSPEND;
END ^

ALTER PROCEDURE INT_PS_1_TK_DT0_1_TK_C (P_COMPANY DM_ID,
P_ACCOUNT1_CODE DM_CODE,
P_ACCOUNT2_CODE DM_CODE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
BEGIN
FOR
    SELECT OBJECT0, SUM(DEBIT), SUM(CREDIT)
    FROM
    (
        SELECT DEBIT.OBJECT0 OBJECT0, DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
        FROM ENTRIES
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_ACCOUNT1_CODE
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_ACCOUNT2_CODE
        WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT.OBJECT0 IS NOT NULL

        UNION ALL

        SELECT CREDIT.OBJECT0 OBJECT0, 0 DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY CREDIT
        FROM ENTRIES
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_ACCOUNT2_CODE
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_ACCOUNT1_CODE
        WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT.OBJECT0 IS NOT NULL
    )
    GROUP BY OBJECT0
    INTO :OBJECT0, :DEBIT, :CREDIT
DO
BEGIN
    SUSPEND;
END
end ^

