                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY OBJECT0, OBJECT1
    INTO :OBJECT0, :OBJECT1, :DEBIT, :CREDIT
DO
    SUSPEND;
end ^

