ALTER PROCEDURE INT_PS_1_TK_N_TK (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ACCOUNT DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT ACCOUNT, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT CREDIT.ACCOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY

            UNION ALL

            SELECT DEBIT.ACCOUNT, 0 DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY CREDIT
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE ENTRIES.COMPANY = :P_COMPANY
        )
        GROUP BY ACCOUNT
        INTO :ACCOUNT, :DEBIT, :CREDIT
    DO
        SUSPEND;
end ^

ALTER PROCEDURE INT_PS_1_TK_N_TK_N_DT (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT DM_ID,
IS_ACCOUNT DM_BOOL,
LEVEL_DETAIL DM_INTEGER,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
BEGIN
    FOR
        SELECT ACCOUNT, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT CREDIT.ACCOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR DEBIT.OBJECT1 = :P_OBJECT1)
            JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY

            UNION ALL

            SELECT DEBIT.ACCOUNT, 0 DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY CREDIT
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND (:P_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR CREDIT.OBJECT1 = :P_OBJECT1)
            JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE ENTRIES.COMPANY = :P_COMPANY
        )
        GROUP BY ACCOUNT
        INTO :ACCOUNT, :DEBIT, :CREDIT
    DO
    BEGIN
        OBJECT = ACCOUNT;
        IS_ACCOUNT = 1;
        LEVEL_DETAIL = 0;

        SUSPEND;

        IS_ACCOUNT = 0;

        FOR
            SELECT OBJECT0, SUM(DEBIT), SUM(CREDIT)
            FROM
            (
                SELECT CREDIT.OBJECT0, DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
                FROM ENTRIES
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR DEBIT.OBJECT1 = :P_OBJECT1)
                JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
                JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.ACCOUNT = :ACCOUNT
                JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
                JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID
                WHERE ENTRIES.COMPANY = :P_COMPANY

                UNION ALL

                SELECT DEBIT.OBJECT0, 0 DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY CREDIT
                FROM ENTRIES
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND DEBIT.ACCOUNT = :ACCOUNT
                JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
                JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND (:P_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR CREDIT.OBJECT1 = :P_OBJECT1)
                JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
                JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
                WHERE ENTRIES.COMPANY = :P_COMPANY
            )
            GROUP BY OBJECT0
            INTO :OBJECT0, :DEBIT, :CREDIT
        DO
        BEGIN
            OBJECT = OBJECT0;
            LEVEL_DETAIL = 1;

            SUSPEND;

            LEVEL_DETAIL = 2;

            FOR
                SELECT OBJECT1, SUM(DEBIT), SUM(CREDIT)
                FROM
                (
                    SELECT CREDIT.OBJECT1, DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT, 0 CREDIT
                    FROM ENTRIES
                    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR DEBIT.OBJECT1 = :P_OBJECT1)
                    JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
                    JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
                    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.ACCOUNT = :ACCOUNT AND CREDIT.OBJECT0 = :OBJECT0
                    JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
                    JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID
                    WHERE ENTRIES.COMPANY = :P_COMPANY

                    UNION ALL

                    SELECT DEBIT.OBJECT1, 0 DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY CREDIT
                    FROM ENTRIES
                    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND DEBIT.ACCOUNT = :ACCOUNT AND DEBIT.OBJECT0 = :OBJECT0
                    JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
                    JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID
                    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND (:P_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_OBJECT0) AND (:P_OBJECT1 IS NULL OR CREDIT.OBJECT1 = :P_OBJECT1)
                    JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
                    JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
                    WHERE ENTRIES.COMPANY = :P_COMPANY
                )
                GROUP BY OBJECT1
                INTO :OBJECT, :DEBIT, :CREDIT
            DO
            BEGIN
                SUSPEND;
            END
        END
    END
END ^

ALTER PROCEDURE INT_PS_1_TK_TT (P_COMPANY DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (FOREIGN_DEBIT DM_DOUBLE,
FOREIGN_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(FOREIGN_SUM_OF_MONEY), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
    CREDIT_DEBIT.SIDE = 0 AND
    CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
    EXISTS
    (
        SELECT ID
        FROM ENTRIES
        WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
        (ENTRIES.CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
        EXISTS
        (
            SELECT ID
            FROM DOCUMENTS
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        )
    )
    INTO :FOREIGN_DEBIT, :OFFICIAL_DEBIT;

    SELECT SUM(FOREIGN_SUM_OF_MONEY), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM CREDIT_DEBIT
    WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
        CREDIT_DEBIT.SIDE = 1 AND
        CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                (ENTRIES.CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    INTO :FOREIGN_CREDIT, :OFFICIAL_CREDIT;

    IF(FOREIGN_DEBIT IS NULL)THEN FOREIGN_DEBIT = 0;
    IF(FOREIGN_CREDIT IS NULL)THEN FOREIGN_CREDIT = 0;
    IF(OFFICIAL_DEBIT IS NULL)THEN OFFICIAL_DEBIT = 0;
    IF(OFFICIAL_CREDIT IS NULL)THEN OFFICIAL_CREDIT = 0;

    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_1_TK_VT_C (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GOODS DM_ID,
INPUT_AMOUNT DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT GOODS, SUM(INPUT_AMOUNT), SUM(OUTPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT CREDIT_DEBIT.OBJECT0 GOODS, CREDIT_DEBIT.AMOUNT INPUT_AMOUNT, 0 OUTPUT_AMOUNT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY, 0 OUTPUT_SUM_OF_MONEY
            FROM CREDIT_DEBIT
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 0 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.OBJECT0 GOODS, 0 INPUT_AMOUNT, CREDIT_DEBIT.AMOUNT OUTPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY
        FROM CREDIT_DEBIT
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY GOODS
    INTO :GOODS, :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
DO
    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_1_TK_VT_KHO (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GOODS DM_ID,
WAREHOUSE DM_ID,
INPUT_AMOUNT DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT GOODS, WAREHOUSE, SUM(INPUT_AMOUNT), SUM(OUTPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT CREDIT_DEBIT.OBJECT0 GOODS, CREDIT_DEBIT.OBJECT1 WAREHOUSE, CREDIT_DEBIT.AMOUNT INPUT_AMOUNT, 0 OUTPUT_AMOUNT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY, 0 OUTPUT_SUM_OF_MONEY
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 0 AND
            CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.OBJECT0 GOODS, CREDIT_DEBIT.OBJECT1 WAREHOUSE, 0 INPUT_AMOUNT, CREDIT_DEBIT.AMOUNT OUTPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY
        FROM CREDIT_DEBIT
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND
            CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY GOODS, WAREHOUSE
    INTO :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
DO
    SUSPEND;
end ^

