ALTER PROCEDURE INT_PS_1_VT_1_KHO (P_COMPANY DM_ID,
P_GOODS DM_ID,
P_WAREHOUSE DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (INPUT_AMOUNT DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
            SELECT SUM(CREDIT_DEBIT.AMOUNT), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 0 AND
            CREDIT_DEBIT.OBJECT0 = :P_GOODS AND
            CREDIT_DEBIT.OBJECT1 = :P_WAREHOUSE AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
            )
            INTO :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY;

            SELECT SUM(CREDIT_DEBIT.AMOUNT), SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
                CREDIT_DEBIT.SIDE = 1 AND
                CREDIT_DEBIT.OBJECT0 = :P_GOODS AND
                CREDIT_DEBIT.OBJECT1 = :P_WAREHOUSE AND
                EXISTS
                (
                    SELECT ID
                    FROM ENTRIES
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                    EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                    )
                )
        INTO :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY;

        IF(INPUT_AMOUNT IS NULL)THEN INPUT_AMOUNT = 0;
        IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
        IF(INPUT_SUM_OF_MONEY IS NULL)THEN INPUT_SUM_OF_MONEY = 0;
        IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

        SUSPEND;
end ^

ALTER PROCEDURE INT_PS_CAP_TK (P_COMPANY DM_ID,
P_DEBIT_ACCOUNT DM_ID,
P_CREDIT_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
    WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT.ACCOUNT = :P_DEBIT_ACCOUNT AND CREDIT.ACCOUNT = :P_CREDIT_ACCOUNT
    INTO SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUSPEND;
end ^

