    FROM DOCUMENTS
    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
    JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT.ACCOUNT AND DEBIT_ATOMS.CODE STARTING WITH :P_DEBIT_ACCOUNT_CODE
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = DEBIT.ENTRY
    JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT.ACCOUNT AND CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE 
    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    INTO :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUSPEND;
end ^

