P_DEBIT_ACCOUNT_CODE3 DM_CODE,
P_CREDIT_ACCOUNT_CODE1 DM_CODE,
P_CREDIT_ACCOUNT_CODE2 DM_CODE,
P_CREDIT_ACCOUNT_CODE3 DM_CODE,
P_CREDIT_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(DEBIT.AMOUNT), SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
