    JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
    JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND (DEBIT_ATOMS.CODE STARTING WITH :P_DEBIT_ACCOUNT_CODE1 OR DEBIT_ATOMS.CODE STARTING WITH :P_DEBIT_ACCOUNT_CODE2 OR DEBIT_ATOMS.CODE STARTING WITH :P_DEBIT_ACCOUNT_CODE3)
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.OBJECT0 = :P_CREDIT_OBJECT0
    JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
    JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND (CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE1 OR CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE2 OR CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE3)
    WHERE ENTRIES.COMPANY = :P_COMPANY
    INTO :AMOUNT, :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUSPEND;
END ^

