        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND (:P_CREDIT_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_CREDIT_OBJECT0)
        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE
        WHERE ENTRIES.COMPANY = :P_COMPANY
        GROUP BY CREDIT.OBJECT1
        INTO :OBJECT1, :AMOUNT, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        IF(AMOUNT IS NULL)THEN AMOUNT = 0;
        IF(OFFICIAL_SUM_OF_MONEY IS NULL)THEN OFFICIAL_SUM_OF_MONEY = 0;

        SUSPEND;
    END
END ^

ALTER PROCEDURE INT_PS_CAP_TK_DT0_NO_C (P_COMPANY DM_ID,
P_DEBIT_ACCOUNT_CODE DM_CODE,
P_CREDIT_ACCOUNT_CODE DM_CODE,
