P_DEN_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
AMOUNT DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
FOR
    SELECT DEBIT.OBJECT0, SUM(DEBIT.AMOUNT), SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
    JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_DEBIT_ACCOUNT_CODE
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
    JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
    JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE
    WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT.OBJECT0 IS NOT NULL
    GROUP BY DEBIT.OBJECT0
    INTO :OBJECT0, :AMOUNT, :OFFICIAL_SUM_OF_MONEY
DO
BEGIN
    IF(AMOUNT IS NULL)THEN AMOUNT = 0;
    IF(OFFICIAL_SUM_OF_MONEY IS NULL)THEN OFFICIAL_SUM_OF_MONEY = 0;

    SUSPEND;
END
end ^

