ALTER PROCEDURE INT_PS_CAP_TK_NO_DT0_C (P_COMPANY DM_ID,
P_DEBIT_ACCOUNT_CODE DM_CODE,
P_DEBIT_OBJECT0 DM_ID,
P_CREDIT_ACCOUNT_CODE DM_CODE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    SELECT SUM(DEBIT.AMOUNT), SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND DEBIT.OBJECT0 = :P_DEBIT_OBJECT0
    JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = DEBIT.ACCOUNT
    JOIN ATOMS DEBIT_ATOMS ON DEBIT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ATOMS.ID = DEBIT_ACCOUNTS.ID AND DEBIT_ATOMS.CODE STARTING WITH :P_DEBIT_ACCOUNT_CODE
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
    JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
    JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT_ACCOUNTS.ID AND CREDIT_ATOMS.CODE STARTING WITH :P_CREDIT_ACCOUNT_CODE
    WHERE ENTRIES.COMPANY = :P_COMPANY
    INTO :AMOUNT, :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_CAP_TK_PERIOD (P_COMPANY DM_ID,
P_DEBIT_ACCOUNT DM_ID,
P_CREDIT_ACCOUNT DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_DEBIT_ACCOUNT
    INTO :DEBIT_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDIT_ACCOUNT
    INTO :CREDIT_ACCOUNT_CODE;

    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.INPUT_DATE BETWEEN :P_FROM_DATE AND :P_TO_DATE
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
    JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :DEBIT_ACCOUNT_CODE
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
    JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
    JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :CREDIT_ACCOUNT_CODE
    WHERE ENTRIES.COMPANY = :P_COMPANY
    INTO SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_CO_1_TK_DT0_C (P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
CREDIT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT CREDIT_DEBIT.OBJECT0, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM CREDIT_DEBIT
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.OBJECT0 IS NOT NULL AND
            CREDIT_DEBIT.SIDE = 1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
        GROUP BY OBJECT0
        INTO :OBJECT0, :CREDIT
    DO
        SUSPEND;
end ^

