ALTER PROCEDURE INT_PS_TK_TT (P_COMPANY DM_ID,
P_CURRENCY DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ACCOUNT DM_ID,
FOREIGN_DEBIT DM_DOUBLE,
FOREIGN_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT ACCOUNT, SUM(FOREIGN_DEBIT), SUM(FOREIGN_CREDIT), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
        FROM
        (
            SELECT ACCOUNT,
            CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY FOREIGN_DEBIT, 0 FOREIGN_CREDIT,
            CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_DEBIT, 0 OFFICIAL_CREDIT
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 0 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                (ENTRIES.CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT ACCOUNT,
        0 FOREIGN_DEBIT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY FOREIGN_CREDIT,
        0 OFFICIAL_DEBIT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_CREDIT
        FROM CREDIT_DEBIT
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                (ENTRIES.CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY ACCOUNT
    INTO :ACCOUNT, :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT
DO
    SUSPEND;
end ^

ALTER PROCEDURE INT_PS_TK_VT (P_COMPANY DM_ID,
P_OBJECT_TYPE DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ACCOUNT DM_ID,
GOODS DM_ID,
INPUT_AMOUNT DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT ACCOUNT, OBJECT0, SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT CREDIT_DEBIT.ACCOUNT, CREDIT_DEBIT.OBJECT0, CREDIT_DEBIT.AMOUNT INPUT_AMOUNT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM CREDIT_DEBIT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CREDIT_DEBIT.OBJECT0 AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE
            JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )

        UNION ALL

        SELECT CREDIT_DEBIT.ACCOUNT, CREDIT_DEBIT.OBJECT0, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, CREDIT_DEBIT.AMOUNT OUTPUT_AMOUNT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY
        FROM CREDIT_DEBIT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CREDIT_DEBIT.OBJECT0 AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE
        JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY ACCOUNT, OBJECT0
    INTO :ACCOUNT, :GOODS, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
DO
    SUSPEND;
end ^

