          )

        UNION ALL

        SELECT ACCOUNT, CREDIT_DEBIT.OBJECT0, CREDIT_DEBIT.OBJECT1, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, CREDIT_DEBIT.AMOUNT OUTPUT_AMOUNT, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY
        FROM CREDIT_DEBIT
        JOIN ATOMS ATOM_0 ON ATOM_0.COMPANY = :P_COMPANY AND ATOM_0.OBJECT_TYPE = :P_OBJECT_TYPE_0 AND ATOM_0.ID = CREDIT_DEBIT.OBJECT0
        JOIN ATOMS ATOM_1 ON ATOM_1.COMPANY = :P_COMPANY AND ATOM_1.OBJECT_TYPE = :P_OBJECT_TYPE_1 AND ATOM_1.ID = CREDIT_DEBIT.OBJECT1
        JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND
            CREDIT_DEBIT.SIDE = 1 AND
            EXISTS
            (
                SELECT ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ID AND
                EXISTS
                    (
                       SELECT ID
                       FROM DOCUMENTS
                       WHERE DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = ID AND
                             DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                   )
          )
    )
    GROUP BY ACCOUNT, OBJECT0, OBJECT1
    INTO :ACCOUNT, :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
DO
    SUSPEND;
end ^

