ALTER PROCEDURE INT_QUARTER_DIFF (COMPANY DM_ID,
PREPAID_EXPENSE DM_ID,
MAIN_FROM_QUARTER DM_INTEGER,
MAIN_FROM_YEAR DM_INTEGER,
MAIN_QUARTERS DM_SMALLINT,
BEGINNING_DATE_OF_PERIOD DM_DATE,
ENDING_DATE_OF_PERIOD DM_DATE)
RETURNS (ENDING_DATE_OF_QUARTER DM_DATE,
REMAINING_QUARTERS DM_SMALLINT)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_QUARTER DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_QUARTER DM_INTEGER;
DECLARE VARIABLE NEW_FROM_QUARTER DM_INTEGER;
DECLARE VARIABLE NEW_FROM_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_QUARTERS DM_SMALLINT;
BEGIN
    IF(EXISTS (SELECT * FROM PREPAID_EXPENSE_PERIODS WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE))THEN
    BEGIN
        BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE_OF_PERIOD);
        BEGINNING_QUARTER = (EXTRACT(MONTH FROM BEGINNING_DATE_OF_PERIOD) + 2)/3;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_QUARTER = (EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD) + 2)/3;

        WHILE((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_QUARTER <= ENDING_QUARTER)))
        DO
        BEGIN
            NEW_FROM_QUARTER = NULL;

            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, DEPRECIATION_PERIOD
            FROM PREPAID_EXPENSE_PERIODS
            WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND
            PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :BEGINNING_QUARTER AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE2 <= :BEGINNING_YEAR
            ORDER BY BEGINNING_DEPRECIATION_VALUE2 DESC, BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :NEW_FROM_QUARTER, :NEW_FROM_YEAR, :NEW_QUARTERS;

            IF(NEW_FROM_QUARTER IS NULL)THEN
            BEGIN
                NEW_FROM_QUARTER = MAIN_FROM_QUARTER;
                NEW_FROM_YEAR = MAIN_FROM_YEAR;
                NEW_QUARTERS = MAIN_QUARTERS;
            END

            IF((NEW_FROM_YEAR < BEGINNING_YEAR) OR ((NEW_FROM_YEAR = BEGINNING_YEAR) AND (NEW_FROM_QUARTER <= BEGINNING_QUARTER)))THEN
            BEGIN
                REMAINING_QUARTERS = NEW_QUARTERS - (BEGINNING_YEAR - NEW_FROM_YEAR)*4 - (BEGINNING_QUARTER - NEW_FROM_QUARTER);
                IF(REMAINING_QUARTERS > 0)THEN
                BEGIN
                    SELECT CASE :BEGINNING_QUARTER
                    WHEN 1 THEN :BEGINNING_YEAR || '.3.31'
                    WHEN 2 THEN :BEGINNING_YEAR || '.6.30'
                    WHEN 3 THEN :BEGINNING_YEAR || '.9.30'
                    WHEN 4 THEN :BEGINNING_YEAR || '.12.31'
                    ELSE NULL
                    END
                    FROM RDB$DATABASE
                    INTO :ENDING_DATE_OF_QUARTER;

                    IF(ENDING_DATE_OF_QUARTER BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            IF(BEGINNING_QUARTER < 4)THEN
                BEGINNING_QUARTER = BEGINNING_QUARTER + 1;
            ELSE
            BEGIN
                BEGINNING_QUARTER = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;
        BEGINNING_QUARTER = MAIN_FROM_QUARTER;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_QUARTER = (EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD) + 2)/3;

        WHILE(MAIN_QUARTERS > 0 AND ((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_QUARTER <= ENDING_QUARTER))))
        DO
        BEGIN
            MAIN_QUARTERS = MAIN_QUARTERS - 1;
              SELECT CASE :BEGINNING_QUARTER
                    WHEN 1 THEN :BEGINNING_YEAR || '.3.31'
                    WHEN 2 THEN :BEGINNING_YEAR || '.6.30'
                    WHEN 3 THEN :BEGINNING_YEAR || '.9.30'
                    WHEN 4 THEN :BEGINNING_YEAR || '.12.31'
                    ELSE NULL
                   END
            FROM RDB$DATABASE
            INTO :ENDING_DATE_OF_QUARTER;

            IF(ENDING_DATE_OF_QUARTER IS NOT NULL AND ENDING_DATE_OF_QUARTER BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_QUARTERS = MAIN_QUARTERS + 1;
                SUSPEND;
            END

            IF(BEGINNING_QUARTER < 4)THEN
                BEGINNING_QUARTER = BEGINNING_QUARTER + 1;
            ELSE
            BEGIN
                BEGINNING_QUARTER = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
END ^

