            END

            IF((NEW_FROM_YEAR < BEGINNING_YEAR) OR ((NEW_FROM_YEAR = BEGINNING_YEAR) AND (NEW_FROM_QUARTER <= BEGINNING_QUARTER)))THEN
            BEGIN
                REMAINING_QUARTERS = NEW_QUARTERS - (BEGINNING_YEAR - NEW_FROM_YEAR)*4 - (BEGINNING_QUARTER - NEW_FROM_QUARTER);
                IF(REMAINING_QUARTERS > 0)THEN
                BEGIN
