                    WHEN 4 THEN :BEGINNING_YEAR || '.12.31'
                    ELSE NULL
                    END
                    FROM RDB$DATABASE
                    INTO :ENDING_DATE_OF_QUARTER;

                    IF(ENDING_DATE_OF_QUARTER BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            IF(BEGINNING_QUARTER < 4)THEN
                BEGINNING_QUARTER = BEGINNING_QUARTER + 1;
            ELSE
            BEGIN
                BEGINNING_QUARTER = 1;
                BEGINNING_YEAR = BEGINNING_YEAR + 1;
            END
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;
        BEGINNING_QUARTER = MAIN_FROM_QUARTER;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
        ENDING_QUARTER = (EXTRACT(MONTH FROM ENDING_DATE_OF_PERIOD) + 2)/3;

        WHILE(MAIN_QUARTERS > 0 AND ((BEGINNING_YEAR < ENDING_YEAR) OR ((BEGINNING_YEAR = ENDING_YEAR) AND (BEGINNING_QUARTER <= ENDING_QUARTER))))
        DO
        BEGIN
            MAIN_QUARTERS = MAIN_QUARTERS - 1;
            SELECT CASE :BEGINNING_QUARTER
                    WHEN 1 THEN :BEGINNING_YEAR || '.3.31'
                    WHEN 2 THEN :BEGINNING_YEAR || '.6.30'
                    WHEN 3 THEN :BEGINNING_YEAR || '.9.30'
                    WHEN 4 THEN :BEGINNING_YEAR || '.12.31'
                    ELSE NULL
                    END
            FROM RDB$DATABASE
            INTO :ENDING_DATE_OF_QUARTER;
        
            IF(ENDING_DATE_OF_QUARTER IS NOT NULL AND ENDING_DATE_OF_QUARTER BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_QUARTERS = MAIN_QUARTERS + 1;
                SUSPEND;
            END

            IF(BEGINNING_QUARTER < 4)THEN
                BEGINNING_QUARTER = BEGINNING_QUARTER + 1;
