ALTER PROCEDURE INT_SD_1_KHO_VT_TK_DN (P_COMPANY DM_ID,
P_WAREHOUSE DM_ID,
P_NGAY DM_DATE)
RETURNS (GOODS DM_ID,
ACCOUNT DM_ID,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_NGAY)THEN
    BEGIN
        FOR
            SELECT OBJECT0, ACCOUNT, SUM(AMOUNT), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
            FROM BALANCES
            JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = BALANCES.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT1 = :P_WAREHOUSE
            GROUP BY OBJECT0, ACCOUNT
            INTO :GOODS, :ACCOUNT, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
            AMOUNT = INPUT_AMOUNT;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT GOODS, ACCOUNT, SUM(INPUT_AMOUNT), SUM(OUTPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_SUM_OF_MONEY)
            FROM
            (
                SELECT OBJECT0 GOODS, ACCOUNT, BALANCES.AMOUNT INPUT_AMOUNT, 0 OUTPUT_AMOUNT, OFFICIAL_DEBIT INPUT_SUM_OF_MONEY, OFFICIAL_CREDIT OUTPUT_SUM_OF_MONEY
                FROM BALANCES
                JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = BALANCES.ACCOUNT AND
                (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT1 = :P_WAREHOUSE

                UNION ALL

                SELECT GOODS, ACCOUNT, INPUT_AMOUNT, OUTPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_SUM_OF_MONEY
                FROM INT_PS_1_KHO_VT_TK(:P_COMPANY, :P_WAREHOUSE, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
            )
            GROUP BY GOODS, ACCOUNT
            INTO :GOODS, :ACCOUNT, :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_SD_1_TK_1_DT0_1_DT1_CN (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_NGAY DM_DATE)
RETURNS (DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE RISING_DEBIT DM_DOUBLE;
DECLARE VARIABLE RISING_CREDIT DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    SELECT SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
    FROM BALANCES
    WHERE COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND ACCOUNT = :P_ACCOUNT AND OBJECT0 = :P_OBJECT0 AND OBJECT1 = :P_OBJECT1
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    IF(BEGINNING_DEBIT IS NULL)THEN BEGINNING_DEBIT = 0;
    IF(BEGINNING_CREDIT IS NULL)THEN BEGINNING_CREDIT = 0;

    SELECT DEBIT, CREDIT
    FROM INT_PS_1_TK_1_DT0_1_DT1(:P_COMPANY, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :BEGINNING_DATE, :P_NGAY)
    INTO :RISING_DEBIT, :RISING_CREDIT;

    IF(RISING_DEBIT IS NULL)THEN RISING_DEBIT = 0;
    IF(RISING_CREDIT IS NULL)THEN RISING_CREDIT = 0;

    DEBIT = :BEGINNING_DEBIT + :RISING_DEBIT - :BEGINNING_CREDIT - :RISING_CREDIT;
    
    IF(DEBIT > 0)THEN
        CREDIT = 0;
    ELSE
    BEGIN
        CREDIT = ABS(DEBIT);
        DEBIT = 0;
    END

    SUSPEND;
END ^

