        FROM INT_PS_1_TK_1_DT0_1_DT1(:P_COMPANY, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
        INTO :RISING_DEBIT, :RISING_CREDIT;
