        FROM INT_PS_1_TK_1_DT0(:P_COMPANY, :P_ACCOUNT, :P_OBJECT0, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
        INTO :RISING_DEBIT, :RISING_CREDIT;
    END

    IF(RISING_DEBIT IS NULL)THEN RISING_DEBIT = 0;
    IF(RISING_CREDIT IS NULL)THEN RISING_CREDIT = 0;

    DEBIT = :BEGINNING_DEBIT + :RISING_DEBIT - :BEGINNING_CREDIT - :RISING_CREDIT;

    IF(DEBIT > 0)THEN
        CREDIT = 0;
    ELSE
    BEGIN
        CREDIT = ABS(DEBIT);
        DEBIT = 0;
    END

    SUSPEND;
END ^

