ALTER PROCEDURE INT_SD_1_TK_1_DT0_DN_C_TT (P_COMPANY DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_OBJECT0 DM_ID,
P_NGAY DM_DATE)
RETURNS (FOREIGN_DEBIT DM_DOUBLE,
FOREIGN_CREDIT DM_DOUBLE,
OFFICIAL_DEBIT DM_DOUBLE,
OFFICIAL_CREDIT DM_DOUBLE)
AS 
declare variable period dm_id;
declare variable beginning_date dm_date;
declare variable beginning_foreign_debit dm_double;
declare variable beginning_foreign_credit dm_double;
declare variable rising_foreign_debit dm_double;
declare variable rising_foreign_credit dm_double;
declare variable beginning_official_debit dm_double;
declare variable beginning_official_credit dm_double;
declare variable rising_official_debit dm_double;
declare variable rising_official_credit dm_double;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    SELECT SUM(IIF(CURRENCY = :P_CURRENCY, FOREIGN_DEBIT, 0)), SUM(IIF(CURRENCY = :P_CURRENCY, FOREIGN_CREDIT, 0)), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
    FROM BALANCES
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BALANCES.ACCOUNT
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
    WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT0 = :P_OBJECT0
    
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    IF(BEGINNING_FOREIGN_DEBIT IS NULL)THEN BEGINNING_FOREIGN_DEBIT = 0;
    IF(BEGINNING_FOREIGN_CREDIT IS NULL)THEN BEGINNING_FOREIGN_CREDIT = 0;
    IF(BEGINNING_OFFICIAL_DEBIT IS NULL)THEN BEGINNING_OFFICIAL_DEBIT = 0;
    IF(BEGINNING_OFFICIAL_CREDIT IS NULL)THEN BEGINNING_OFFICIAL_CREDIT = 0;

    IF(BEGINNING_DATE <> :P_NGAY)THEN
    BEGIN
        SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
        FROM INT_PS_1_TK_1_DT0_C_TT(:P_COMPANY, :P_CURRENCY, :P_ACCOUNT_CODE, :P_OBJECT0, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
        INTO :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT;
    END

    IF(RISING_FOREIGN_DEBIT IS NULL)THEN RISING_FOREIGN_DEBIT = 0;
    IF(RISING_FOREIGN_CREDIT IS NULL)THEN RISING_FOREIGN_CREDIT = 0;
    IF(RISING_OFFICIAL_DEBIT IS NULL)THEN RISING_OFFICIAL_DEBIT = 0;
    IF(RISING_OFFICIAL_CREDIT IS NULL)THEN RISING_OFFICIAL_CREDIT = 0;

    FOREIGN_DEBIT = :BEGINNING_FOREIGN_DEBIT + :RISING_FOREIGN_DEBIT - :BEGINNING_FOREIGN_CREDIT - :RISING_FOREIGN_CREDIT;
    OFFICIAL_DEBIT = :BEGINNING_OFFICIAL_DEBIT + :RISING_OFFICIAL_DEBIT - :BEGINNING_OFFICIAL_CREDIT - :RISING_OFFICIAL_CREDIT;
    
    IF(FOREIGN_DEBIT > 0)THEN
        FOREIGN_CREDIT = 0;
    ELSE
    BEGIN
        FOREIGN_CREDIT = ABS(FOREIGN_DEBIT);
        FOREIGN_DEBIT = 0;
    END

    IF(OFFICIAL_DEBIT > 0)THEN
        OFFICIAL_CREDIT = 0;
    ELSE
    BEGIN
        OFFICIAL_CREDIT = ABS(OFFICIAL_DEBIT);
        OFFICIAL_DEBIT = 0;
    END

    SUSPEND;
END ^

ALTER PROCEDURE INT_SD_1_TK_1_DT0_DN_TT (P_COMPANY DM_ID,
P_CURRENCY DM_ID,
