ALTER PROCEDURE INT_SD_1_TK_1_DT0_DT1_DN (P_COMPANY BIGINT,
P_ACCOUNT BIGINT,
P_IS_GOODS_ACCOUNT SMALLINT,
P_OBJECT0 BIGINT,
P_NGAY DATE)
RETURNS (OBJECT1 BIGINT,
AMOUNT NUMERIC(18, 4),
DEBIT NUMERIC(18, 4),
CREDIT NUMERIC(18, 4))
AS 
DECLARE VARIABLE PERIOD BIGINT;
DECLARE VARIABLE BEGINNING_DATE DATE;
BEGIN
    SELECT p.ID, p.BEGINNING_DATE
    FROM PERIODS p
    WHERE p.COMPANY = :P_COMPANY
      AND :P_NGAY BETWEEN p.BEGINNING_DATE AND p.ENDING_DATE
    INTO :PERIOD, :BEGINNING_DATE;

    IF (BEGINNING_DATE = P_NGAY) THEN
    BEGIN
        FOR
            SELECT b.OBJECT1, SUM(b.AMOUNT), SUM(b.OFFICIAL_DEBIT), SUM(b.OFFICIAL_CREDIT)
            FROM BALANCES b
            WHERE b.PERIOD = :PERIOD
              AND b.ACCOUNT = :P_ACCOUNT AND b.OBJECT0 = :P_OBJECT0 AND b.OBJECT1 IS NOT NULL
            GROUP BY b.OBJECT1
            PLAN (B INDEX (IDX_BAL_PERIOD_ACC_OBJ0))
            INTO :OBJECT1, :AMOUNT, :DEBIT, :CREDIT
        DO BEGIN
            DEBIT = DEBIT - CREDIT;
            IF (DEBIT > 0) THEN CREDIT = 0;
            ELSE BEGIN CREDIT = ABS(DEBIT); DEBIT = 0; END
            IF (DEBIT <> 0 OR CREDIT <> 0 OR (P_IS_GOODS_ACCOUNT = 1 AND AMOUNT <> 0)) THEN
                SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT OBJECT1, SUM(AMOUNT), SUM(DEBIT), SUM(CREDIT)
            FROM (
                SELECT b.OBJECT1, b.AMOUNT, b.OFFICIAL_DEBIT DEBIT, b.OFFICIAL_CREDIT CREDIT
                FROM BALANCES b
                WHERE b.PERIOD = :PERIOD
                  AND b.ACCOUNT = :P_ACCOUNT AND b.OBJECT0 = :P_OBJECT0 AND b.OBJECT1 IS NOT NULL
                UNION ALL
                SELECT OBJECT1, DEBIT_AMOUNT - CREDIT_AMOUNT, DEBIT, CREDIT
                FROM INT_PS_1_TK_1_DT0_DT1(:P_COMPANY, :P_ACCOUNT, :P_OBJECT0, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
            )
            GROUP BY OBJECT1
            INTO :OBJECT1, :AMOUNT, :DEBIT, :CREDIT
        DO BEGIN
            DEBIT = DEBIT - CREDIT;
            IF (DEBIT > 0) THEN CREDIT = 0;
            ELSE BEGIN CREDIT = ABS(DEBIT); DEBIT = 0; END
            IF (DEBIT <> 0 OR CREDIT <> 0 OR (P_IS_GOODS_ACCOUNT = 1 AND AMOUNT <> 0)) THEN
                SUSPEND;
        END
    END
END ^

