    SELECT SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
    FROM BALANCES
    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BALANCES.ACCOUNT
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
    WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    IF(BEGINNING_DEBIT IS NULL)THEN BEGINNING_DEBIT = 0;
    IF(BEGINNING_CREDIT IS NULL)THEN BEGINNING_CREDIT = 0;

    IF(BEGINNING_DATE <> P_NGAY)THEN
    BEGIN
        SELECT DEBIT, CREDIT
        FROM INT_PS_1_TK_C(:P_COMPANY, :P_ACCOUNT_CODE, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
