ALTER PROCEDURE INT_SD_1_TK_DT0_CN (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    FOR
        SELECT OBJECT0, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT OBJECT0, OFFICIAL_DEBIT DEBIT, OFFICIAL_CREDIT CREDIT
            FROM BALANCES
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND ACCOUNT = :P_ACCOUNT AND BALANCES.OBJECT0 IS NOT NULL

            UNION ALL

            SELECT OBJECT0, DEBIT, CREDIT
            FROM INT_PS_1_TK_DT0(:P_COMPANY, :P_ACCOUNT, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY OBJECT0
        INTO :OBJECT0, :DEBIT, :CREDIT
    DO
    BEGIN
        DEBIT = DEBIT - CREDIT;

        IF(DEBIT > 0)THEN
            CREDIT = 0;
        ELSE
        BEGIN
            CREDIT = ABS(DEBIT);
            DEBIT = 0;
        END

        IF(DEBIT <> 0 OR CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

