            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND BALANCES.OBJECT0 IS NOT NULL

            UNION ALL

            SELECT OBJECT0, DEBIT, CREDIT
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :P_ACCOUNT_CODE, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY OBJECT0
        INTO :OBJECT0, :DEBIT, :CREDIT
    DO
    BEGIN
        DEBIT = DEBIT - CREDIT;

        IF(DEBIT > 0)THEN
            CREDIT = 0;
        ELSE
        BEGIN
            CREDIT = ABS(DEBIT);
            DEBIT = 0;
        END

        IF(DEBIT <> 0 OR CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

