ALTER PROCEDURE INT_SD_1_TK_DT0_DT1_CN (P_COMPANY DM_ID,
P_ACCOUNT DM_ID,
P_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
OBJECT1 DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    FOR
        SELECT OBJECT0, OBJECT1, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT OBJECT0 OBJECT0, OBJECT1 OBJECT1, OFFICIAL_DEBIT DEBIT, OFFICIAL_CREDIT CREDIT
            FROM BALANCES
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND ACCOUNT = :P_ACCOUNT AND OBJECT0 IS NOT NULL AND OBJECT1 IS NOT NULL

            UNION ALL

            SELECT OBJECT0, OBJECT1, DEBIT, CREDIT
            FROM INT_PS_1_TK_DT0_DT1(:P_COMPANY, :P_ACCOUNT, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY OBJECT0, OBJECT1
        INTO :OBJECT0, :OBJECT1, :DEBIT, :CREDIT
