DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_NGAY)THEN
    BEGIN
        FOR
            SELECT OBJECT0, SUM(AMOUNT), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
            FROM BALANCES
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BALANCES.ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD
            GROUP BY OBJECT0
            INTO :GOODS, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
            AMOUNT = INPUT_AMOUNT;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT GOODS, SUM(INPUT_AMOUNT), SUM(OUTPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_SUM_OF_MONEY)
            FROM
            (
                SELECT OBJECT0 GOODS, BALANCES.AMOUNT INPUT_AMOUNT, 0 OUTPUT_AMOUNT, OFFICIAL_DEBIT INPUT_SUM_OF_MONEY, OFFICIAL_CREDIT OUTPUT_SUM_OF_MONEY
                FROM BALANCES
                JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = BALANCES.ACCOUNT
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_ACCOUNT_CODE
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD

                UNION ALL

                SELECT GOODS, INPUT_AMOUNT, OUTPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_SUM_OF_MONEY
                FROM INT_PS_1_TK_VT_KHO_C(:P_COMPANY, :P_ACCOUNT_CODE, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
            )
            GROUP BY GOODS
            INTO :GOODS, :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
END ^

