ALTER PROCEDURE INT_SD_1_VT_1_KHO_CN (P_COMPANY DM_ID,
P_GOODS DM_ID,
P_WAREHOUSE DM_ID,
P_NGAY DM_DATE)
RETURNS (AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE BEGINNING_AMOUNT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    SELECT SUM(AMOUNT), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
    FROM BALANCES
    WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT0 = :P_GOODS AND OBJECT1 = :P_WAREHOUSE
    INTO :BEGINNING_AMOUNT, :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    IF(BEGINNING_AMOUNT IS NULL)THEN BEGINNING_AMOUNT = 0;
    IF(BEGINNING_DEBIT IS NULL)THEN BEGINNING_DEBIT = 0;
    IF(BEGINNING_CREDIT IS NULL)THEN BEGINNING_CREDIT = 0;

    SELECT INPUT_AMOUNT, OUTPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_SUM_OF_MONEY
    FROM INT_PS_1_VT_1_KHO(:P_COMPANY, :P_GOODS, :P_WAREHOUSE, :BEGINNING_DATE, :P_NGAY)
    INTO :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY;

    IF(INPUT_AMOUNT IS NULL)THEN INPUT_AMOUNT = 0;
    IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
    IF(INPUT_SUM_OF_MONEY IS NULL)THEN INPUT_SUM_OF_MONEY = 0;
    IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

    AMOUNT = :BEGINNING_AMOUNT + :INPUT_AMOUNT - :OUTPUT_AMOUNT;
    SUM_OF_MONEY = :BEGINNING_DEBIT + :INPUT_SUM_OF_MONEY - :BEGINNING_CREDIT - :OUTPUT_SUM_OF_MONEY;

    SUSPEND;
END ^

ALTER PROCEDURE INT_SD_1_VT_1_KHO_DN (P_COMPANY DM_ID,
P_GOODS DM_ID,
P_WAREHOUSE DM_ID,
P_NGAY DM_DATE)
RETURNS (AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE BEGINNING_AMOUNT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    SELECT SUM(AMOUNT), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
    FROM BALANCES
    WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT0 = :P_GOODS AND OBJECT1 = :P_WAREHOUSE
    INTO :BEGINNING_AMOUNT, :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    IF(BEGINNING_AMOUNT IS NULL)THEN BEGINNING_AMOUNT = 0;
    IF(BEGINNING_DEBIT IS NULL)THEN BEGINNING_DEBIT = 0;
    IF(BEGINNING_CREDIT IS NULL)THEN BEGINNING_CREDIT = 0;

    IF(BEGINNING_DATE <> :P_NGAY)THEN
    BEGIN
        SELECT INPUT_AMOUNT, OUTPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_SUM_OF_MONEY
        FROM INT_PS_1_VT_1_KHO(:P_COMPANY, :P_GOODS, :P_WAREHOUSE, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
        INTO :INPUT_AMOUNT, :OUTPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY;
    END

    IF(INPUT_AMOUNT IS NULL)THEN INPUT_AMOUNT = 0;
    IF(OUTPUT_AMOUNT IS NULL)THEN OUTPUT_AMOUNT = 0;
    IF(INPUT_SUM_OF_MONEY IS NULL)THEN INPUT_SUM_OF_MONEY = 0;
    IF(OUTPUT_SUM_OF_MONEY IS NULL)THEN OUTPUT_SUM_OF_MONEY = 0;

    AMOUNT = :BEGINNING_AMOUNT + :INPUT_AMOUNT - :OUTPUT_AMOUNT;
    SUM_OF_MONEY = :BEGINNING_DEBIT + :INPUT_SUM_OF_MONEY - :BEGINNING_CREDIT - :OUTPUT_SUM_OF_MONEY;

    SUSPEND;
END ^

ALTER PROCEDURE INT_SD_DT0_CN (P_COMPANY DM_ID,
P_OBJECT_TYPE DM_ID,
P_NGAY DM_DATE)
RETURNS (OBJECT0 DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    FOR
        SELECT OBJECT0, SUM(DEBIT), SUM(CREDIT)
        FROM
        (
            SELECT OBJECT0, OFFICIAL_DEBIT DEBIT, OFFICIAL_CREDIT CREDIT
            FROM BALANCES
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BALANCES.OBJECT0 AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND OBJECT0 IS NOT NULL

            UNION ALL

            SELECT OBJECT0, DEBIT, CREDIT
            FROM INT_PS_DT0(:P_COMPANY, :P_OBJECT_TYPE, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY OBJECT0
        INTO :OBJECT0, :DEBIT, :CREDIT
    DO
    BEGIN
        DEBIT = DEBIT - CREDIT;

        IF(DEBIT > 0)THEN
            CREDIT = 0;
        ELSE
        BEGIN
            CREDIT = ABS(DEBIT);
            DEBIT = 0;
        END

        IF(DEBIT <> 0 OR CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

