BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    FOR
        SELECT ACCOUNT, SUM(FOREIGN_DEBIT), SUM(FOREIGN_CREDIT), SUM(OFFICIAL_DEBIT), SUM(OFFICIAL_CREDIT)
        FROM
        (
            SELECT ACCOUNT, FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
            FROM BALANCES
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD AND (CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) 

            UNION ALL

            SELECT ACCOUNT, FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
            FROM INT_PS_TK_TT(:P_COMPANY, :P_CURRENCY, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY ACCOUNT
        INTO :ACCOUNT, :FOREIGN_DEBIT, :FOREIGN_CREDIT, :OFFICIAL_DEBIT, :OFFICIAL_CREDIT
    DO
    BEGIN
        FOREIGN_DEBIT = FOREIGN_DEBIT - FOREIGN_CREDIT;
        OFFICIAL_DEBIT = OFFICIAL_DEBIT - OFFICIAL_CREDIT;

        IF(FOREIGN_DEBIT > 0)THEN
            FOREIGN_CREDIT = 0;
        ELSE
        BEGIN
            FOREIGN_CREDIT = ABS(FOREIGN_DEBIT);
            FOREIGN_DEBIT = 0;
        END

        IF(OFFICIAL_DEBIT > 0)THEN
            OFFICIAL_CREDIT = 0;
        ELSE
        BEGIN
            OFFICIAL_CREDIT = ABS(OFFICIAL_DEBIT);
            OFFICIAL_DEBIT = 0;
        END

        IF(FOREIGN_DEBIT <> 0 OR FOREIGN_CREDIT <> 0 OR OFFICIAL_DEBIT <> 0 OR OFFICIAL_CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE INT_SD_TK_DN (P_COMPANY DM_ID,
P_NGAY DM_DATE,
P_ENTRY_TYPE DM_ENTRY_TYPE)
RETURNS (ACCOUNT DM_ID,
DEBIT DM_DOUBLE,
CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_NGAY)THEN
    BEGIN
        FOR
            SELECT ACCOUNT, SUM(DEBIT), SUM(CREDIT)
            FROM
            (
                SELECT ACCOUNT, OFFICIAL_DEBIT DEBIT, OFFICIAL_CREDIT CREDIT
                FROM BALANCES
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = 10 AND ATOMS.ID = BALANCES.ACCOUNT AND ((ATOMS.CODE STARTING WITH '0' AND :P_ENTRY_TYPE = 0) OR (ATOMS.CODE NOT STARTING WITH '0' AND :P_ENTRY_TYPE > 0) )
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD
            )
            GROUP BY ACCOUNT
            INTO :ACCOUNT, :DEBIT, :CREDIT
        DO
        BEGIN
            DEBIT = DEBIT - CREDIT;

            IF(DEBIT > 0)THEN
                CREDIT = 0;
            ELSE
            BEGIN
                CREDIT = ABS(DEBIT);
                DEBIT = 0;
            END

            IF(DEBIT <> 0 OR CREDIT <> 0)THEN
                SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT ACCOUNT, SUM(DEBIT), SUM(CREDIT)
            FROM
            (
                SELECT ACCOUNT, OFFICIAL_DEBIT DEBIT, OFFICIAL_CREDIT CREDIT
                FROM BALANCES
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = 10 AND ATOMS.ID = BALANCES.ACCOUNT AND ((ATOMS.CODE STARTING WITH '0' AND :P_ENTRY_TYPE = 0) OR (ATOMS.CODE NOT STARTING WITH '0' AND :P_ENTRY_TYPE > 0) )
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD

                UNION ALL

                SELECT ACCOUNT, DEBIT, CREDIT
                FROM INT_PS_TK(:P_COMPANY, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY), :P_ENTRY_TYPE)
            )
            GROUP BY ACCOUNT
            INTO :ACCOUNT, :DEBIT, :CREDIT
        DO
        BEGIN
            DEBIT = DEBIT - CREDIT;

            IF(DEBIT > 0)THEN
                CREDIT = 0;
            ELSE
            BEGIN
                CREDIT = ABS(DEBIT);
                DEBIT = 0;
            END

            IF(DEBIT <> 0 OR CREDIT <> 0)THEN
                SUSPEND;
        END
    END
END ^

