ALTER PROCEDURE INT_SD_TK_VT_CN (P_COMPANY DM_ID,
P_OBJECT_TYPE DM_ID,
P_NGAY DM_DATE)
RETURNS (ACCOUNT DM_ID,
GOODS DM_ID,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    FOR
        SELECT ACCOUNT, GOODS, SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT ACCOUNT, OBJECT0 GOODS, BALANCES.AMOUNT INPUT_AMOUNT, OFFICIAL_DEBIT INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, OFFICIAL_CREDIT OUTPUT_SUM_OF_MONEY
            FROM BALANCES
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.ID = BALANCES.OBJECT0
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD

            UNION ALL

            SELECT ACCOUNT, GOODS, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
            FROM INT_PS_TK_VT(:P_COMPANY, :P_OBJECT_TYPE, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY ACCOUNT, GOODS
        INTO :ACCOUNT, :GOODS, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
        AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

        IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
            SUSPEND;
    END
END ^

