                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD
            GROUP BY OBJECT0
            INTO :GOODS, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
            AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT GOODS, SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
            FROM
            (
                SELECT OBJECT0 GOODS, BALANCES.AMOUNT INPUT_AMOUNT, OFFICIAL_DEBIT INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, OFFICIAL_CREDIT OUTPUT_SUM_OF_MONEY
                FROM BALANCES
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BALANCES.OBJECT0 AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE
                JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = BALANCES.ACCOUNT AND
                (
                    ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                    ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                    ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                    ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                    ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                    ATOM_ACCOUNTS.CODE STARTING WITH '158')
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD

                UNION ALL

                SELECT GOODS, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
                FROM INT_PS_VT(:P_COMPANY, :P_OBJECT_TYPE, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
            )
            GROUP BY GOODS
            INTO :GOODS, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
            AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_SD_VT_KHO_CN (P_COMPANY DM_ID,
P_OBJECT_TYPE_0 DM_ID,
P_OBJECT_TYPE_1 DM_ID,
P_NGAY DM_DATE)
RETURNS (GOODS DM_ID,
WAREHOUSE DM_ID,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    FOR
        SELECT GOODS, WAREHOUSE, SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT OBJECT0 GOODS, OBJECT1 WAREHOUSE, BALANCES.AMOUNT INPUT_AMOUNT, OFFICIAL_DEBIT INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, OFFICIAL_CREDIT OUTPUT_SUM_OF_MONEY
            FROM BALANCES
            JOIN ATOMS ATOM_0 ON ATOM_0.COMPANY = :P_COMPANY AND ATOM_0.OBJECT_TYPE = :P_OBJECT_TYPE_0 AND ATOM_0.ID = BALANCES.OBJECT0
            JOIN ATOMS ATOM_1 ON ATOM_1.COMPANY = :P_COMPANY AND ATOM_1.OBJECT_TYPE = :P_OBJECT_TYPE_1 AND ATOM_1.ID = BALANCES.OBJECT1
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD

            UNION ALL

            SELECT GOODS, WAREHOUSE, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
            FROM INT_PS_VT_KHO(:P_COMPANY, :P_OBJECT_TYPE_0, :P_OBJECT_TYPE_1, :BEGINNING_DATE, :P_NGAY)
        )
        GROUP BY GOODS, WAREHOUSE
        INTO :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
        AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

        IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE INT_SD_VT_KHO_DN (P_COMPANY DM_ID,
P_OBJECT_TYPE_0 DM_ID,
P_OBJECT_TYPE_1 DM_ID,
P_NGAY DM_DATE)
RETURNS (GOODS DM_ID,
WAREHOUSE DM_ID,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD DM_ID;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE INPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE OUTPUT_AMOUNT DM_DOUBLE;
DECLARE VARIABLE INPUT_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OUTPUT_SUM_OF_MONEY DM_DOUBLE;
BEGIN
    SELECT ID, BEGINNING_DATE
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_NGAY)
    INTO :PERIOD, :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_NGAY)THEN
    BEGIN
        FOR
            SELECT OBJECT0 GOODS, OBJECT1 WAREHOUSE, SUM(AMOUNT), SUM(OFFICIAL_DEBIT), 0, SUM(OFFICIAL_CREDIT)
            FROM BALANCES
            JOIN ATOMS ATOM_0 ON ATOM_0.COMPANY = :P_COMPANY AND ATOM_0.OBJECT_TYPE = :P_OBJECT_TYPE_0 AND ATOM_0.ID = BALANCES.OBJECT0
            JOIN ATOMS ATOM_1 ON ATOM_1.COMPANY = :P_COMPANY AND ATOM_1.OBJECT_TYPE = :P_OBJECT_TYPE_1 AND ATOM_1.ID = BALANCES.OBJECT1
            JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = BALANCES.ACCOUNT AND
            (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
            WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD
            GROUP BY OBJECT0, OBJECT1
            INTO :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
            AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT GOODS, WAREHOUSE, SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
            FROM
            (
                SELECT OBJECT0 GOODS, OBJECT1 WAREHOUSE, BALANCES.AMOUNT INPUT_AMOUNT, OFFICIAL_DEBIT INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, OFFICIAL_CREDIT OUTPUT_SUM_OF_MONEY
                FROM BALANCES
                JOIN ATOMS ATOM_0 ON ATOM_0.COMPANY = :P_COMPANY AND ATOM_0.OBJECT_TYPE = :P_OBJECT_TYPE_0 AND ATOM_0.ID = BALANCES.OBJECT0
                JOIN ATOMS ATOM_1 ON ATOM_1.COMPANY = :P_COMPANY AND ATOM_1.OBJECT_TYPE = :P_OBJECT_TYPE_1 AND ATOM_1.ID = BALANCES.OBJECT1
                JOIN ATOMS ATOM_ACCOUNTS ON ATOM_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_ACCOUNTS.ID = BALANCES.ACCOUNT AND
                (
                ATOM_ACCOUNTS.CODE STARTING WITH '152' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '153' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '155' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '156' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '157' OR
                ATOM_ACCOUNTS.CODE STARTING WITH '158')
                WHERE BALANCES.COMPANY = :P_COMPANY AND PERIOD = :PERIOD

                UNION ALL

                SELECT GOODS, WAREHOUSE, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
                FROM INT_PS_VT_KHO(:P_COMPANY, :P_OBJECT_TYPE_0, :P_OBJECT_TYPE_1, :BEGINNING_DATE, DATEADD(DAY, -1, :P_NGAY))
            )
            GROUP BY GOODS, WAREHOUSE
            INTO :GOODS, :WAREHOUSE, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
        DO
        BEGIN
            SUM_OF_MONEY = INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;
            AMOUNT = INPUT_AMOUNT - OUTPUT_AMOUNT;

            IF(AMOUNT <> 0 OR SUM_OF_MONEY <> 0)THEN
                SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_SOURCE_TARGET_ACCOUNTS (P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_SOURCE_ACCOUNT_CODE DM_CODE,
P_TARGET_ACCOUNT_CODE_1 DM_CODE,
P_TARGET_ACCOUNT_CODE_2 DM_CODE,
P_ORDINAL DM_INTEGER,
P_CONTENT DM_CONTENT,
P_TRANSFER_ALL DM_BOOL,
P_PERCENT_1 DM_DOUBLE,
P_PERCENT_2 DM_DOUBLE,
P_TRANSFER_TYPE_1 DM_TRANSFER_TYPE,
P_TRANSFER_TYPE_2 DM_TRANSFER_TYPE)
RETURNS (ORDINAL DM_INTEGER)
AS 
DECLARE VARIABLE SOURCE_ACCOUNT DM_ID;
DECLARE VARIABLE SOURCE_ACCOUNT_ID DM_ID;
DECLARE VARIABLE TARGET_ACCOUNT_ID_1 DM_ID;
DECLARE VARIABLE TARGET_ACCOUNT_ID_2 DM_ID;
BEGIN
    SELECT FIRST 1 ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_TARGET_ACCOUNT_CODE_1 AND (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    ORDER BY CODE
    INTO :TARGET_ACCOUNT_ID_1;

    SELECT FIRST 1 ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_TARGET_ACCOUNT_CODE_2 AND (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    ORDER BY CODE
    INTO :TARGET_ACCOUNT_ID_2;

    FOR
        SELECT ACCOUNTS.ID
        FROM ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :P_SOURCE_ACCOUNT_CODE AND (NOT EXISTS (SELECT ID FROM ATOMS CHILDREN WHERE CHILDREN.COMPANY = :P_COMPANY AND CHILDREN.PARENT = ATOMS.ID))
        WHERE ACCOUNTS.COMPANY = :P_COMPANY
        ORDER BY CODE
        INTO :SOURCE_ACCOUNT_ID
    DO
    BEGIN
        P_ORDINAL = P_ORDINAL + 5;

        SOURCE_ACCOUNT = GEN_ID(UNIVERSE, 1);
        EXECUTE PROCEDURE SOURCE_ACCOUNT_IU(0, :P_COMPANY, :SOURCE_ACCOUNT, NULL, :P_ORDINAL, :SOURCE_ACCOUNT_ID, NULL, NULL, NULL, :P_TRANSFER_ALL, :P_CONTENT, :P_PERIOD);

        IF(TARGET_ACCOUNT_ID_1 IS NOT NULL)THEN
        BEGIN
            EXECUTE PROCEDURE TARGET_ACCOUNT_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 1, :SOURCE_ACCOUNT, :TARGET_ACCOUNT_ID_1, NULL, NULL, NULL, :P_PERCENT_1, NULL, :P_TRANSFER_TYPE_1);
        END

        IF(TARGET_ACCOUNT_ID_2 IS NOT NULL)THEN
        BEGIN
            EXECUTE PROCEDURE TARGET_ACCOUNT_IU(0, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 5, :SOURCE_ACCOUNT, :TARGET_ACCOUNT_ID_2, NULL, NULL, NULL, :P_PERCENT_2, NULL, :P_TRANSFER_TYPE_2);
        END
    END

    ORDINAL = P_ORDINAL;

    SUSPEND;
END ^

ALTER PROCEDURE INT_SO_CHI_TIET_DOI_TUONG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
RECIPROCAL_ACCOUNT_CODE DM_CODE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE)
AS 
declare variable official_sum_of_money dm_double;
declare variable debit_object0 dm_id;
declare variable debit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable reciprocal_object0_name dm_name;
BEGIN
    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT),
        DEBIT.official_sum_of_money,
        DEBIT.OBJECT0, DEBIT_ATOM.CODE,
        CREDIT.OBJECT0, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
        LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
            (
                DEBIT.OBJECT0 = :P_OBJECT0 OR
                CREDIT.OBJECT0 = :P_OBJECT0
            )
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT,
        :official_sum_of_money,
        :debit_object0, :debit_account_code,
        :credit_object0, :credit_account_code
    DO
    BEGIN
        if(debit_object0 = P_OBJECT0)then
        begin
            account_code = debit_account_code;
            reciprocal_account_code = credit_account_code;
            rising_debit = official_sum_of_money;
            rising_credit = 0;

            if(credit_object0 is not null)then
            begin
                select atom_strings.name
                from atom_strings
                where atom_strings.company = :p_company and atom_strings.language = 0 and atom_strings.id = :credit_object0
                into :reciprocal_object0_name;

                content = content || '(' || reciprocal_object0_name || ')';
            end

            SUSPEND;
        end

        if(credit_object0 = P_OBJECT0)then
        begin
            account_code = credit_account_code;
            reciprocal_account_code = debit_account_code;
            rising_debit = 0;
            rising_credit = official_sum_of_money;

            if(debit_object0 is not null)then
            begin
                select atom_strings.name
                from atom_strings
                where atom_strings.company = :p_company and atom_strings.language = 0 and atom_strings.id = :debit_object0
                into :reciprocal_object0_name;

                content = content || '(' || reciprocal_object0_name || ')';
            end

            SUSPEND;
        end
    END
END ^

ALTER PROCEDURE INT_SO_CHI_TIET_TAI_KHOAN_1DT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
SUM_BEGINNING_DEBIT DM_DOUBLE,
SUM_BEGINNING_CREDIT DM_DOUBLE,
SUM_ENDING_DEBIT DM_DOUBLE,
SUM_ENDING_CREDIT DM_DOUBLE,
OBJECT_NAME DM_NAME,
STT DM_INTEGER)
AS 
declare variable parent_account_code dm_code;
declare variable has_value dm_bool;
declare variable prev_object dm_id;
declare variable object dm_id;
declare variable object_type dm_id;
BEGIN
    STT = 0;
    
    ENDING_DEBIT = 0;
    ENDING_CREDIT = 0;
    SUM_BEGINNING_DEBIT = 0;
    SUM_BEGINNING_CREDIT = 0;
    SUM_ENDING_DEBIT = 0;
    SUM_ENDING_CREDIT = 0;
    INSERT INTO TEMP_SUM_DEBIT_CREDIT(BEGINNING_DEBIT, BEGINNING_CREDIT, ENDING_DEBIT, ENDING_CREDIT)
    VALUES(0, 0, 0, 0);
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    PREV_OBJECT = NULL;

    FOR
        SELECT CODENUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
        RISING_DEBIT, RISING_CREDIT,
        OBJECT0, ATOM_STRINGS.NAME, ACCOUNT_CODE
        FROM
        (
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            DEBIT.OFFICIAL_SUM_OF_MONEY RISING_DEBIT, 0 RISING_CREDIT,
            DEBIT.OBJECT0, CREDIT_ATOM.CODE ACCOUNT_CODE,
            ATOM_DOCUMENT_TEAMS.CODE DOCUMENT_TEAM_CODE
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
            JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
            LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            (
                DEBIT.OBJECT0 = :P_OBJECT0 OR
                (:P_OBJECT0 IS NULL AND DEBIT.OBJECT0 IS NOT NULL)
            )

            UNION ALL

            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            0 RISING_DEBIT, CREDIT.OFFICIAL_SUM_OF_MONEY RISING_CREDIT,
            CREDIT.OBJECT0, DEBIT_ATOM.CODE ACCOUNT_CODE,
            ATOM_DOCUMENT_TEAMS.CODE DOCUMENT_TEAM_CODE
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
            JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
            LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            (
                CREDIT.OBJECT0 = :P_OBJECT0 OR
                (:P_OBJECT0 IS NULL AND CREDIT.OBJECT0 IS NOT NULL)
            )
        )ABC
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ABC.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ABC.OBJECT0
        ORDER BY OBJECT0, INPUT_DATE,
        IIF(DOCUMENT_TEAM_CODE STARTING WITH 'PT', 0,
            IIF(DOCUMENT_TEAM_CODE STARTING WITH 'PC', 5,
                IIF(DOCUMENT_TEAM_CODE STARTING WITH 'GBCO', 10,
                    IIF(DOCUMENT_TEAM_CODE STARTING WITH 'GBNO', 15,
                        IIF(DOCUMENT_TEAM_CODE STARTING WITH 'BTTH', 75,
                            IIF(DOCUMENT_TEAM_CODE = 'BTK', 80,
                                IIF(DOCUMENT_TEAM_CODE STARTING WITH 'TKHTS', 85,
                                    IIF(DOCUMENT_TEAM_CODE STARTING WITH 'CPTT', 90,
                                        IIF(DOCUMENT_TEAM_CODE STARTING WITH 'BTPB', 95,
                                            IIF(DOCUMENT_TEAM_CODE STARTING WITH 'BTKC', 100, 50)
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        CODENUMBER
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT,
        :RISING_DEBIT, :RISING_CREDIT,
        :OBJECT, :OBJECT_NAME, :ACCOUNT_CODE
    DO
    BEGIN
        IF(PREV_OBJECT IS NULL OR PREV_OBJECT <> OBJECT)THEN
        BEGIN
            PREV_OBJECT = OBJECT;

            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY)
            INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

            SUM_BEGINNING_DEBIT = SUM_BEGINNING_DEBIT + BEGINNING_DEBIT;
            SUM_BEGINNING_CREDIT = SUM_BEGINNING_CREDIT + BEGINNING_CREDIT;

            ENDING_DEBIT = 0;
            ENDING_CREDIT = 0;
        END

        BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

        IF(BALANCE_DEBIT > 0)THEN
            BALANCE_CREDIT = 0;
        ELSE
        BEGIN
            BALANCE_CREDIT = ABS(BALANCE_DEBIT);
            BALANCE_DEBIT = 0;
        END

        SUM_ENDING_DEBIT = SUM_ENDING_DEBIT - ENDING_DEBIT;
        SUM_ENDING_CREDIT = SUM_ENDING_CREDIT - ENDING_CREDIT;

        ENDING_DEBIT = BALANCE_DEBIT;
        ENDING_CREDIT = BALANCE_CREDIT;

        SUM_ENDING_DEBIT = SUM_ENDING_DEBIT + ENDING_DEBIT;
        SUM_ENDING_CREDIT = SUM_ENDING_CREDIT + ENDING_CREDIT;

        UPDATE TEMP_SUM_DEBIT_CREDIT
        SET BEGINNING_DEBIT = :SUM_BEGINNING_DEBIT, BEGINNING_CREDIT = :SUM_BEGINNING_CREDIT, ENDING_DEBIT = :SUM_ENDING_DEBIT, ENDING_CREDIT = :SUM_ENDING_CREDIT;

        HAS_VALUE = 1;
        STT = STT + 1;
        SUSPEND;

        UPDATE OR INSERT INTO TEMP_ATOMS(ID)
        VALUES(:OBJECT);

        BEGINNING_DEBIT = BALANCE_DEBIT;
        BEGINNING_CREDIT = BALANCE_CREDIT;

    END

    IF(P_OBJECT0 IS NULL)THEN
    BEGIN
        SELECT ACCOUNTS.ATOM_TYPE_0
        FROM ACCOUNTS
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ACCOUNT
        INTO :OBJECT_TYPE;

        IF(OBJECT_TYPE IS NOT NULL)THEN
        BEGIN
            CODE = NULL;
            INPUT_DATE = NULL;
            VOUCHER_DATE = NULL;

            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :CONTENT;

            ACCOUNT_CODE = NULL;
            RISING_DEBIT = 0;
            RISING_CREDIT = 0;
            BALANCE_DEBIT = 0;
            BALANCE_CREDIT = 0;

            FOR
                SELECT ATOMS.ID, ATOM_STRINGS.NAME
                FROM ATOMS
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND
                    NOT EXISTS(SELECT 1 FROM TEMP_ATOMS WHERE TEMP_ATOMS.ID = ATOMS.ID)
                INTO :OBJECT, :OBJECT_NAME
            DO
            BEGIN
                SELECT DEBIT, CREDIT
                FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY)
                INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

                SUM_BEGINNING_DEBIT = SUM_BEGINNING_DEBIT + BEGINNING_DEBIT;
                SUM_BEGINNING_CREDIT = SUM_BEGINNING_CREDIT + BEGINNING_CREDIT;

                IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0)THEN
                BEGIN
                    ENDING_DEBIT = BEGINNING_DEBIT;
                    ENDING_CREDIT = BEGINNING_CREDIT;

                    SUM_ENDING_DEBIT = SUM_ENDING_DEBIT + ENDING_DEBIT;
                    SUM_ENDING_CREDIT = SUM_ENDING_CREDIT + ENDING_CREDIT;

                    UPDATE TEMP_SUM_DEBIT_CREDIT
                    SET BEGINNING_DEBIT = :SUM_BEGINNING_DEBIT, BEGINNING_CREDIT = :SUM_BEGINNING_CREDIT, ENDING_DEBIT = :SUM_ENDING_DEBIT, ENDING_CREDIT = :SUM_ENDING_CREDIT;
                    
                    STT = STT + 1;
                    
                    SUSPEND;
                END
            END
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        IF(P_OBJECT0 IS NOT NULL)THEN
        BEGIN
            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)
            INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

            SUM_BEGINNING_DEBIT = SUM_BEGINNING_DEBIT + BEGINNING_DEBIT;
            SUM_BEGINNING_CREDIT = SUM_BEGINNING_CREDIT + BEGINNING_CREDIT;

            SELECT ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
            INTO :OBJECT_NAME;

            ENDING_DEBIT = BEGINNING_DEBIT;
            ENDING_CREDIT = BEGINNING_CREDIT;

            SUM_ENDING_DEBIT = SUM_ENDING_DEBIT + ENDING_DEBIT;
            SUM_ENDING_CREDIT = SUM_ENDING_CREDIT + ENDING_CREDIT;

            UPDATE TEMP_SUM_DEBIT_CREDIT
            SET BEGINNING_DEBIT = :SUM_BEGINNING_DEBIT, BEGINNING_CREDIT = :SUM_BEGINNING_CREDIT, ENDING_DEBIT = :SUM_ENDING_DEBIT, ENDING_CREDIT = :SUM_ENDING_CREDIT;

            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :CONTENT;
    
            STT = STT + 1;
            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE INT_SO_CT_THANH_TOAN_NB_SL_DG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_PRINT_REPORT_PERSON_NAME DM_INTEGER)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
declare variable debit_account_code dm_code;
declare variable debit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable debit_amount dm_double;
declare variable debit_price dm_double;
declare variable credit_amount dm_double;
declare variable credit_price dm_double;
declare variable official_sum_of_money dm_double;
declare variable object_name dm_name;
declare variable has_value dm_bool;
BEGIN
    HAS_VALUE = 0;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :P_ACCOUNT_CODE, :P_CUSTOMER, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:P_PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT.AMOUNT, DEBIT.PRICE, CREDIT.AMOUNT, CREDIT.PRICE,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :P_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_CUSTOMER) OR (CREDIT_ATOM.CODE STARTING WITH :P_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_CUSTOMER))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_AMOUNT, :DEBIT_PRICE, :CREDIT_AMOUNT, :CREDIT_PRICE,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :P_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            IF(CREDIT_OBJECT0 IS NOT NULL)THEN
            BEGIN
                SELECT ATOM_STRINGS.NAME
                FROM ATOM_STRINGS
                WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_OBJECT0
                INTO :OBJECT_NAME;

                IF(CONTENT IS NULL)THEN CONTENT = '';

                CONTENT = CONTENT || '(' || :OBJECT_NAME || ')';
            END

            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            AMOUNT = CREDIT_AMOUNT;
            PRICE = CREDIT_PRICE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :P_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            IF(DEBIT_OBJECT0 IS NOT NULL)THEN
            BEGIN
                SELECT ATOM_STRINGS.NAME
                FROM ATOM_STRINGS
                WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_OBJECT0
                INTO :OBJECT_NAME;

                IF(CONTENT IS NULL)THEN CONTENT = '';

                CONTENT = CONTENT || '(' || :OBJECT_NAME || ')';
            END

            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            AMOUNT = DEBIT_AMOUNT;
            PRICE = DEBIT_PRICE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE INT_SO_CT_THANH_TOAN_NM_SL_DG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ACCOUNT_CODE DM_CODE,
