CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
declare variable debit_account_code dm_code;
declare variable debit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable debit_amount dm_double;
declare variable debit_price dm_double;
declare variable credit_amount dm_double;
declare variable credit_price dm_double;
declare variable official_sum_of_money dm_double;
declare variable object_name dm_name;
declare variable has_value dm_bool;
BEGIN
    HAS_VALUE = 0;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :P_ACCOUNT_CODE, :P_CUSTOMER, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:P_PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
