                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :P_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            IF(DEBIT_OBJECT0 IS NOT NULL)THEN
            BEGIN
                SELECT ATOM_STRINGS.NAME
                FROM ATOM_STRINGS
                WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_OBJECT0
                INTO :OBJECT_NAME;

                IF(CONTENT IS NULL)THEN CONTENT = '';

                CONTENT = CONTENT || '(' || :OBJECT_NAME || ')';
            END

            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            AMOUNT = DEBIT_AMOUNT;
            PRICE = DEBIT_PRICE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE INT_SPLIT_STRING (P_STRING DM_NAME,
P_SEPARATOR CHAR(1) CHARACTER SET UNICODE_FSS)
RETURNS (ID DM_ID)
AS 
declare variable LASTPOS integer;
declare variable NEXTPOS integer;
begin
  P_STRING = :P_STRING || P_SEPARATOR;
  LASTPOS = 1;
  NEXTPOS = position(P_SEPARATOR, :P_STRING, LASTPOS);
  while (:NEXTPOS > 1) do
  begin
    id = substring(:P_STRING from :LASTPOS for :NEXTPOS - :LASTPOS);
     suspend;
    LASTPOS = :NEXTPOS + 1;
    NEXTPOS = position(P_SEPARATOR, :P_STRING, LASTPOS);
  end
end ^

ALTER PROCEDURE INT_THE_TINH_GIA_THANH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (DD_DK_TC DM_DOUBLE,
PS_TK_TC DM_DOUBLE,
PS_TK_NVL DM_DOUBLE,
PS_TK_NC DM_DOUBLE,
PS_TK_MTC DM_DOUBLE,
PS_TK_CPC DM_DOUBLE,
GT_TK_TC DM_DOUBLE,
DD_CK_TC DM_DOUBLE)
AS 
declare variable account_code dm_code;
declare variable account_code_621 dm_code;
declare variable account_code_622 dm_code;
declare variable account_code_623 dm_code;
declare variable account_code_627 dm_code;
declare variable account_code_khac dm_code;
declare variable accounting_system dm_accounting_system;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :ACCOUNTING_SYSTEM;

    IF(ACCOUNTING_SYSTEM = 1)THEN
    BEGIN
        ACCOUNT_CODE_621 = '621';
        ACCOUNT_CODE_622 = '622';
        ACCOUNT_CODE_623 = '623';
        ACCOUNT_CODE_627 = '627';
        ACCOUNT_CODE_KHAC = '154';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 2 or ACCOUNTING_SYSTEM = 4 )THEN
    BEGIN
        ACCOUNT_CODE_621 = '1541';
        ACCOUNT_CODE_622 = '1542';
        ACCOUNT_CODE_623 = '1543';
        ACCOUNT_CODE_627 = '1547';
        ACCOUNT_CODE_KHAC = '1548';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 3)THEN
    BEGIN
        ACCOUNT_CODE_621 = '621';
        ACCOUNT_CODE_622 = '622';
        ACCOUNT_CODE_623 = '623';
        ACCOUNT_CODE_627 = '627';
        ACCOUNT_CODE_KHAC = '154';
    END

    SELECT DEBIT - CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)
    INTO :DD_DK_TC;

    
    SELECT OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_621, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_NVL;
    IF(PS_TK_NVL IS NULL)THEN PS_TK_NVL = 0;

    SELECT :PS_TK_NVL - OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_621, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_NVL;

    
    SELECT OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_622, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_NC;
    IF(PS_TK_NC IS NULL)THEN PS_TK_NC = 0;

    SELECT :PS_TK_NC - OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_622, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_NC;

    
    SELECT OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_623, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_MTC;
    IF(PS_TK_MTC IS NULL)THEN PS_TK_MTC = 0;

    SELECT :PS_TK_MTC - OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_623, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_MTC;

    
    SELECT OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_627, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_CPC;
    IF(PS_TK_CPC IS NULL)THEN PS_TK_CPC = 0;

    SELECT :PS_TK_CPC - OFFICIAL_SUM_OF_MONEY
    FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_627, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :PS_TK_CPC;

    PS_TK_TC = PS_TK_NVL + PS_TK_NC + PS_TK_MTC + PS_TK_CPC;

    SELECT DEBIT - CREDIT
    FROM INT_SD_1_TK_1_DT0_CN_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :P_DEN_NGAY)
    INTO DD_CK_TC;

    GT_TK_TC = DD_DK_TC + PS_TK_TC - DD_CK_TC;

    SUSPEND;
END ^

ALTER PROCEDURE INT_THE_TINH_GIA_THANH_2 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT1 DM_ID,
DD_DK_TC DM_DOUBLE,
PS_TK_TC DM_DOUBLE,
PS_TK_NVL DM_DOUBLE,
PS_TK_NC DM_DOUBLE,
PS_TK_MTC DM_DOUBLE,
PS_TK_CPC DM_DOUBLE,
GT_TK_TC DM_DOUBLE,
DD_CK_TC DM_DOUBLE)
AS 
declare variable account_code dm_code;
declare variable account_code_621 dm_code;
declare variable account_code_622 dm_code;
declare variable account_code_623 dm_code;
declare variable account_code_627 dm_code;
declare variable account_code_khac dm_code;
declare variable accounting_system dm_accounting_system;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :ACCOUNTING_SYSTEM;

    IF(ACCOUNTING_SYSTEM = 1)THEN
    BEGIN
        ACCOUNT_CODE_621 = '621';
        ACCOUNT_CODE_622 = '622';
        ACCOUNT_CODE_623 = '623';
        ACCOUNT_CODE_627 = '627';
        ACCOUNT_CODE_KHAC = '154';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 2 or ACCOUNTING_SYSTEM = 4)THEN
    BEGIN
        ACCOUNT_CODE_621 = '1541';
        ACCOUNT_CODE_622 = '1542';
        ACCOUNT_CODE_623 = '1543';
        ACCOUNT_CODE_627 = '1547';
        ACCOUNT_CODE_KHAC = '1548';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 3)THEN
    BEGIN
        ACCOUNT_CODE_621 = '621';
        ACCOUNT_CODE_622 = '622';
        ACCOUNT_CODE_623 = '623';
        ACCOUNT_CODE_627 = '627';
        ACCOUNT_CODE_KHAC = '154';
    END

    FOR
        SELECT OBJECT1, SUM(DD_DK_TC),
                    SUM(PS_TK_NVL) - SUM(PS_TK_NVL_CO),
                    SUM(PS_TK_NC) - SUM(PS_TK_NC_CO),
                    SUM(PS_TK_MTC) - SUM(PS_TK_MTC_CO),
                    SUM(PS_TK_CPC) - SUM(PS_TK_CPC_CO),
                    SUM(DD_CK_TC)
        FROM
        (
            SELECT OBJECT1, DEBIT - CREDIT DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_SD_1_TK_1_DT0_DT1_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 DD_DK_TC,
                    OFFICIAL_SUM_OF_MONEY PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_621, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, OFFICIAL_SUM_OF_MONEY PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_CO_C(:P_COMPANY, :ACCOUNT_CODE_621, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    OFFICIAL_SUM_OF_MONEY PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_622, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, OFFICIAL_SUM_OF_MONEY PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_CO_C(:P_COMPANY, :ACCOUNT_CODE_622, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    OFFICIAL_SUM_OF_MONEY PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_623, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, OFFICIAL_SUM_OF_MONEY PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_CO_C(:P_COMPANY, :ACCOUNT_CODE_623, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    OFFICIAL_SUM_OF_MONEY PS_TK_CPC, 0 PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_627, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, OFFICIAL_SUM_OF_MONEY PS_TK_CPC_CO,
                    0 DD_CK_TC
            FROM INT_PS_CAP_TK_1_DT0_DT1_CO_C(:P_COMPANY, :ACCOUNT_CODE_627, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 DD_DK_TC,
                    0 PS_TK_NVL, 0 PS_TK_NVL_CO,
                    0 PS_TK_NC, 0 PS_TK_NC_CO,
                    0 PS_TK_MTC, 0 PS_TK_MTC_CO,
                    0 PS_TK_CPC, 0 PS_TK_CPC_CO,
                    DEBIT - CREDIT DD_CK_TC
            FROM INT_SD_1_TK_1_DT0_DT1_CN_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :P_DEN_NGAY)
        )
        GROUP BY OBJECT1
        INTO :OBJECT1, :DD_DK_TC, :PS_TK_NVL, :PS_TK_NC, :PS_TK_MTC, :PS_TK_CPC, :DD_CK_TC
    DO
    BEGIN
        PS_TK_TC = PS_TK_NVL + PS_TK_NC + PS_TK_MTC + PS_TK_CPC;
        GT_TK_TC = DD_DK_TC + PS_TK_TC - DD_CK_TC;
        SUSPEND;
    END
END ^

ALTER PROCEDURE INT_TIMES_TO_BEGIN_END_DATES (P_TIME_TYPE DM_TIME_TYPE,
P_TIME_1 DM_INTEGER,
P_TIME_2 DM_INTEGER)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
    IF(P_TIME_TYPE = 2)THEN
    BEGIN
        SELECT :P_TIME_2 || '.' || :P_TIME_1 || '.1', :P_TIME_2 || '.' || :P_TIME_1 || '.' || ENDING_DAY
        FROM CMD_ENDING_DAY_OF_MONTH_YEAR(:P_TIME_1, :P_TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(P_TIME_TYPE = 3)THEN
    BEGIN
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_QUARTER_YEAR(:P_TIME_1, :P_TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(P_TIME_TYPE = 4)THEN
    BEGIN
        SELECT BEGINNING_DATE, ENDING_DATE
        FROM CMD_DATES_OF_HALF_YEAR(:P_TIME_1, :P_TIME_2)
        INTO :BEGINNING_DATE, :ENDING_DATE;
    END
    ELSE IF(P_TIME_TYPE = 5)THEN
    BEGIN
        BEGINNING_DATE = P_TIME_2 || '.1.1';
        ENDING_DATE = P_TIME_2 || '.12.31';
    END

    SUSPEND;
END ^

ALTER PROCEDURE INT_TINH_HINH_NGHIA_VU_NHA_NUOC (P_COMPANY DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
ACCOUNT_CODE DM_CODE)
RETURNS (X_1 DM_DOUBLE,
X_2 DM_DOUBLE,
X_3 DM_DOUBLE,
X_4 DM_DOUBLE,
X_5 DM_DOUBLE,
X_6 DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE_11 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_131 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_421 DM_CODE;
DECLARE VARIABLE NGAY_DAU_NAM DM_DATE;
BEGIN
    NGAY_DAU_NAM = '01.01.' || EXTRACT(YEAR FROM P_TU_NGAY);
    ACCOUNT_CODE_11 = '11';
    ACCOUNT_CODE_131 = '131';
    ACCOUNT_CODE_421 = '421';

    
    SELECT CREDIT - DEBIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY,  :ACCOUNT_CODE, :P_TU_NGAY)
    INTO :X_1;
    IF(X_1 IS NULL) THEN X_1 = 0;

    
    SELECT CREDIT-DEBIT
    FROM INT_PS_1_TK_C(:P_COMPANY,  :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :X_2;
    IF(X_2 IS NULL) THEN X_2 = 0;

    
    SELECT CREDIT-DEBIT
    FROM INT_PS_1_TK_C(:P_COMPANY,  :ACCOUNT_CODE, :NGAY_DAU_NAM, :P_DEN_NGAY)
    INTO :X_4;
    IF(X_4 IS NULL) THEN X_4 = 0;

    
    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
    JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
    JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
    JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
    WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE AND
        (
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_11 OR
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_131 OR
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_421
        )
    INTO :X_3;
    IF(X_3 IS NULL) THEN X_3 = 0;

    
    SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
    FROM ENTRIES
    JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :NGAY_DAU_NAM AND :P_DEN_NGAY
    JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
    JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
    JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
    JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
    JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
    JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
    WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE AND
        (
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_11 OR
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_131 OR
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_421
        )
    INTO :X_5;
    IF(X_5 IS NULL) THEN X_5 = 0;

    X_2 = X_2 + X_3;
    X_4 = X_4 + X_5;
    
    X_6 = X_1 + X_2 - X_3;

    SUSPEND;
END ^

ALTER PROCEDURE INT_TO_KHAI_THUE_GTGT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (V10 DM_BOOL,
V11 DM_DOUBLE,
V12 DM_DOUBLE,
V13 DM_DOUBLE,
V14 DM_DOUBLE,
V15 DM_DOUBLE,
V16 DM_DOUBLE,
V17 DM_DOUBLE,
V18 DM_DOUBLE,
V19 DM_DOUBLE,
V20 DM_DOUBLE,
V21 DM_DOUBLE,
V22 DM_DOUBLE,
V23 DM_DOUBLE,
V24 DM_DOUBLE,
V25 DM_DOUBLE,
V26 DM_DOUBLE,
V27 DM_DOUBLE,
V28 DM_DOUBLE,
V29 DM_DOUBLE,
V30 DM_DOUBLE,
V31 DM_DOUBLE,
V32 DM_DOUBLE,
V33 DM_DOUBLE,
V34 DM_DOUBLE,
V35 DM_DOUBLE,
V36 DM_DOUBLE,
V37 DM_DOUBLE,
V38 DM_DOUBLE,
V39 DM_DOUBLE,
V40 DM_DOUBLE,
V41 DM_DOUBLE,
V42 DM_DOUBLE,
V43 DM_DOUBLE)
AS 
DECLARE VARIABLE TK133 DM_CODE;
DECLARE VARIABLE TK3331 DM_CODE;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    TK133 = '133';
    TK3331 = '3331';

    
    
    
    

    SELECT BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_TU_NGAY)THEN
    BEGIN
        SELECT DEBIT-CREDIT
        FROM INT_SD_1_TK_DN_C(:P_COMPANY, :TK133, :P_TU_NGAY)
        INTO :V11;
    END
    ELSE
    BEGIN
        SELECT FIRST 1 TO_KHAI_GTGT.V43
        FROM TO_KHAI_GTGT
        WHERE TO_KHAI_GTGT.COMPANY = :P_COMPANY AND TO_KHAI_GTGT.TO_DATE = DATEADD(DAY, -1, :P_TU_NGAY)
        INTO :V11;
    END

    IF(V11 IS NULL)THEN V11 = 0;

    
    SELECT SUM(INVOICES.SUM_OF_MONEY), SUM(INVOICES.SUM_OF_TAX)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_TYPE <> 0 AND INVOICES.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    INTO :V14, :V15;

    IF(V14 IS NULL)THEN V14 = 0;
    IF(V15 IS NULL)THEN V15 = 0;

    
    IF(V16 IS NULL)THEN V16 = 0;
    IF(V17 IS NULL)THEN V17 = 0;

    V12 = V14 + V16;
    V13 = V15 + V17;

    IF(V18 IS NULL)THEN V18 = 0;
    IF(V19 IS NULL)THEN V19 = 0;

    IF(V20 IS NULL)THEN V20 = 0;
    IF(V21 IS NULL)THEN V21 = 0;

    V22 = V13 + V19 - V21;

    V23 = V22;

    SELECT SUM(INVOICES.SUM_OF_MONEY)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_TYPE = 0 AND INVOICES.VAT_PERCENT IS NULL AND
    (INVOICES.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)
    INTO :V26;

    IF(V26 IS NULL)THEN V26 = 0;

    SELECT SUM(INVOICES.SUM_OF_MONEY)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_TYPE = 0 AND INVOICES.VAT_PERCENT = 0 AND
    (INVOICES.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)
    INTO :V29;
    IF(V29 IS NULL)THEN V29 = 0;

    SELECT SUM(INVOICES.SUM_OF_MONEY), SUM(INVOICES.SUM_OF_TAX)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_TYPE = 0 AND INVOICES.VAT_PERCENT = 0.05 AND
    (INVOICES.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)
    INTO :V30, :V31;

    IF(V30 IS NULL)THEN V30 = 0;
    IF(V31 IS NULL)THEN V31 = 0;

    SELECT SUM(INVOICES.SUM_OF_MONEY), SUM(INVOICES.SUM_OF_TAX)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.INVOICE_TYPE = 0 AND INVOICES.VAT_PERCENT = 0.1 AND
    (INVOICES.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY)
    INTO :V32, :V33;

    IF(V32 IS NULL)THEN V32 = 0;
    IF(V33 IS NULL)THEN V33 = 0;

    V27 = V29 + V30 +  V32;
    V28 = V31 + V33;

    V24 = V26 + V27;
    V25 = V28;

    IF(V34 IS NULL)THEN V34 = 0;

    
    

    IF(V35 IS NULL)THEN V35 = 0;

    IF(V36 IS NULL)THEN V36 = 0;

    
    

    IF(V37 IS NULL)THEN V37 = 0;

    V38 = V24 + V34 - V36;

    V39 = V25 + V35 - V37;

    V40 = V39 - V23 - V11;
    IF(V40 > 0)THEN
        V41 = 0;
    ELSE
    BEGIN
        V41 = ABS(V40);
        V40 = 0;
    END

    IF(V42 IS NULL)THEN V42 = 0;

    V43 = V41 - V42;

    IF(V14 <> 0 OR V15 <> 0 OR V16 <> 0 OR V17 <> 0 OR V26 <> 0 OR V29 <> 0 OR V30 <> 0 OR V31 <> 0 OR V32 <> 0 OR V33 <> 0)THEN
        V10 = 0;
    ELSE
        V10 = 1;

    SUSPEND;
END ^

ALTER PROCEDURE INT_TO_KHAI_THUE_GTGT_119 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (V21 DM_BOOL,
V22 DM_DOUBLE,
V23 DM_DOUBLE,
V24 DM_DOUBLE,
V25 DM_DOUBLE,
V26 DM_DOUBLE,
V27 DM_DOUBLE,
V28 DM_DOUBLE,
V29 DM_DOUBLE,
V30 DM_DOUBLE,
V31 DM_DOUBLE,
V32 DM_DOUBLE,
V33 DM_DOUBLE,
V34 DM_DOUBLE,
V35 DM_DOUBLE,
V36 DM_DOUBLE,
V37 DM_DOUBLE,
V38 DM_DOUBLE,
V39 DM_DOUBLE,
V40A DM_DOUBLE,
V40B DM_DOUBLE,
V40 DM_DOUBLE,
V41 DM_DOUBLE,
V42 DM_DOUBLE,
V43 DM_DOUBLE)
AS 
DECLARE VARIABLE TK133 DM_CODE;
DECLARE VARIABLE TK3331 DM_CODE;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
BEGIN
    TK133 = '133';
    TK3331 = '3331';

    SELECT BEGINNING_DATE
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :BEGINNING_DATE;

    IF(BEGINNING_DATE = P_TU_NGAY)THEN
    BEGIN
        SELECT DEBIT-CREDIT
        FROM INT_SD_1_TK_DN_C(:P_COMPANY, :TK133, :P_TU_NGAY)
        INTO :V22;
    END
    ELSE
    BEGIN
        SELECT FIRST 1 TO_KHAI_GTGT_119.V43
        FROM TO_KHAI_GTGT_119
        WHERE TO_KHAI_GTGT_119.COMPANY = :P_COMPANY AND TO_KHAI_GTGT_119.TO_DATE = DATEADD(DAY, -1, :P_TU_NGAY)
        INTO :V22;
    END

    IF(V22 IS NULL)THEN V22 = 0;

    SELECT SUM(SUM_OF_MONEY), SUM(SUM_OF_TAX)
    FROM
    (
        SELECT SUM(SUM_OF_MONEY) SUM_OF_MONEY, SUM(SUM_OF_TAX) SUM_OF_TAX
        FROM RPT_BANG_KE_HD_GTGT_MV_119_1(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_TU_NGAY, :P_DEN_NGAY)

        UNION ALL

        SELECT SUM(SUM_OF_MONEY) SUM_OF_MONEY, SUM(SUM_OF_TAX) SUM_OF_TAX
        FROM RPT_BANG_KE_HD_GTGT_MV_119_2(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_TU_NGAY, :P_DEN_NGAY)

        UNION ALL

