        FROM RPT_BANG_KE_HD_GTGT_MV_119_3(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_TU_NGAY, :P_DEN_NGAY)
    )
    INTO :V23,  :V24;

    IF(V23 IS NULL)THEN V23 = 0;
    IF(V24 IS NULL)THEN V24 = 0;

    
    SELECT SUM(SUM_OF_TAX)
    FROM
    (
        SELECT SUM_OF_TAX
