    INTO :V32, :V33;
    IF(V32 IS NULL)THEN V32 = 0;
    IF(V33 IS NULL)THEN V33 = 0;

    V27 = V29 + V30 +  V32;
    V28 = V31 + V33;

    V34 = V26 + V27;
    V35 = V28;

    V36 = V35-V25;
    
    
    

    IF(V37 IS NULL)THEN V37 = 0;

    
    

    IF(V38 IS NULL)THEN V38 = 0;

    V39 = 0;

    V40A = V36 - V22 + V37 - V38 - V39;
    V40B = 0;

    IF(V40A > 0)THEN
        V41 = 0;
    ELSE
    BEGIN
        V41 = ABS(V40A);
        V40A = 0;
    END

    V40 = V40A - V40B;
    V42 = 0;
    V43 = V41 - V42;

    IF(V23 <> 0 OR V24 <> 0 OR V25 <> 0 OR V26 <> 0 OR V27 <> 0 OR V28 <> 0 OR V29 <> 0 OR V30 <> 0 OR V31 <> 0 OR V32 <> 0 OR V33 <> 0 OR V34 <> 0 OR V35 <> 0)THEN
        V21 = 0;
