PREPAID_EXPENSE DM_ID,
MAIN_FROM_YEAR DM_INTEGER,
MAIN_YEARS DM_SMALLINT,
BEGINNING_DATE_OF_PERIOD DM_DATE,
ENDING_DATE_OF_PERIOD DM_DATE)
RETURNS (ENDING_DATE_OF_YEAR DM_DATE,
REMAINING_YEARS DM_SMALLINT)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_FROM_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_YEARS DM_SMALLINT;
BEGIN
    IF(EXISTS (SELECT * FROM PREPAID_EXPENSE_PERIODS WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE))THEN
    BEGIN
        BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE_OF_PERIOD);

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);

        WHILE(BEGINNING_YEAR <= ENDING_YEAR)
        DO
        BEGIN
            NEW_FROM_YEAR = NULL;

            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, DEPRECIATION_PERIOD
            FROM PREPAID_EXPENSE_PERIODS
            WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :COMPANY AND
            PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :PREPAID_EXPENSE AND
            PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :BEGINNING_YEAR
            ORDER BY BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :NEW_FROM_YEAR, :NEW_YEARS;

            IF(NEW_FROM_YEAR IS NULL)THEN
            BEGIN
                NEW_FROM_YEAR = MAIN_FROM_YEAR;
                NEW_YEARS = MAIN_YEARS;
            END

            IF(NEW_FROM_YEAR <= BEGINNING_YEAR)THEN
            BEGIN
                REMAINING_YEARS = NEW_YEARS - (BEGINNING_YEAR - NEW_FROM_YEAR);
                IF(REMAINING_YEARS > 0)THEN
                BEGIN
                    ENDING_DATE_OF_YEAR = :BEGINNING_YEAR || '.12.31';

                    IF(ENDING_DATE_OF_YEAR BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);
    
        WHILE(MAIN_YEARS > 0 AND BEGINNING_YEAR <= ENDING_YEAR)
        DO
        BEGIN
            MAIN_YEARS = MAIN_YEARS - 1;
            ENDING_DATE_OF_YEAR = :BEGINNING_YEAR || '.12.31';

            IF(ENDING_DATE_OF_YEAR BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_YEARS = MAIN_YEARS + 1;
                SUSPEND;
            END

            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
END ^

ALTER PROCEDURE INT_YEAR_DIFF_ASSET (COMPANY DM_ID,
ASSET DM_ID,
MAIN_FROM_YEAR DM_INTEGER,
MAIN_YEARS DM_DOUBLE,
BEGINNING_DATE_OF_PERIOD DM_DATE,
ENDING_DATE_OF_PERIOD DM_DATE)
RETURNS (ENDING_DATE_OF_YEAR DM_DATE,
REMAINING_YEARS DM_DOUBLE)
AS 
DECLARE VARIABLE BEGINNING_YEAR DM_INTEGER;
DECLARE VARIABLE ENDING_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_FROM_YEAR DM_INTEGER;
DECLARE VARIABLE NEW_YEARS DM_DOUBLE;
BEGIN
    IF(EXISTS (SELECT * FROM ASSET_DEPRECIATION_PERIODS WHERE ASSET_DEPRECIATION_PERIODS.COMPANY = :COMPANY AND ASSET_DEPRECIATION_PERIODS.ASSET = :ASSET))THEN
    BEGIN
        BEGINNING_YEAR = EXTRACT(YEAR FROM BEGINNING_DATE_OF_PERIOD);

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);

        WHILE(BEGINNING_YEAR <= ENDING_YEAR)
        DO
        BEGIN
            NEW_FROM_YEAR = NULL;

            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, DEPRECIATION_PERIOD
            FROM ASSET_DEPRECIATION_PERIODS
            WHERE ASSET_DEPRECIATION_PERIODS.COMPANY = :COMPANY AND
            ASSET_DEPRECIATION_PERIODS.ASSET = :ASSET AND
            ASSET_DEPRECIATION_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :BEGINNING_YEAR
            ORDER BY BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :NEW_FROM_YEAR, :NEW_YEARS;

            IF(NEW_FROM_YEAR IS NULL)THEN
            BEGIN
                NEW_FROM_YEAR = MAIN_FROM_YEAR;
                NEW_YEARS = MAIN_YEARS;
            END

            IF(NEW_FROM_YEAR <= BEGINNING_YEAR)THEN
            BEGIN
                REMAINING_YEARS = NEW_YEARS - (BEGINNING_YEAR - NEW_FROM_YEAR);
                IF(REMAINING_YEARS > 0)THEN
                BEGIN
                    ENDING_DATE_OF_YEAR = :BEGINNING_YEAR || '.12.31';

                    IF(ENDING_DATE_OF_YEAR BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
                        SUSPEND;
                END
            END

            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
    ELSE
    BEGIN
        BEGINNING_YEAR = MAIN_FROM_YEAR;

        ENDING_YEAR = EXTRACT(YEAR FROM ENDING_DATE_OF_PERIOD);

        WHILE(MAIN_YEARS > 0 AND BEGINNING_YEAR <= ENDING_YEAR)
        DO
        BEGIN
            MAIN_YEARS = MAIN_YEARS - 1;
            ENDING_DATE_OF_YEAR = :BEGINNING_YEAR || '.12.31';

            IF(ENDING_DATE_OF_YEAR BETWEEN :BEGINNING_DATE_OF_PERIOD AND :ENDING_DATE_OF_PERIOD)THEN
            BEGIN
                REMAINING_YEARS = MAIN_YEARS + 1;
                SUSPEND;
            END
        
            BEGINNING_YEAR = BEGINNING_YEAR + 1;
        END
    END
END ^

ALTER PROCEDURE INVOICE_D (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
BEGIN
    DELETE FROM INVOICES
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID;

    WHEN ANY DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = SQLCODE AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || SQLCODE || ')';
    END
END ^

ALTER PROCEDURE INVOICE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT,
P_BANK_ACCOUNT DM_NAME,
P_BUYER_NAME DM_NAME,
P_CUSTOMER DM_ID,
P_CUSTOMER_ADDRESS DM_ADDRESS,
P_CUSTOMER_NAME DM_NAME,
P_CUSTOMER_TAX_CODE DM_TAX_CODE,
P_DOCUMENT DM_ID,
P_GOODS DM_GOODS,
P_UNIT DM_UNIT,
P_INPUT_DATE DM_DATE,
P_INVOICE_CODE DM_INVOICE_CODE,
P_INVOICE_DATE DM_DATE,
P_INVOICE_TEMPLATE DM_INVOICE_TEMPLATE,
P_CODE_TEMPLATE DM_INVOICE_TEMPLATE,
P_INVOICE_TYPE DM_INVOICE_TYPE,
P_SERIAL_CODE DM_SERIAL_CODE,
P_SUM_OF_MONEY DM_DOUBLE,
P_SUM_OF_TAX DM_DOUBLE,
P_VAT_PERCENT DM_DOUBLE,
P_EXTRA_GOODS DM_DESCRIPTION,
P_EXTRA_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
DECLARE VARIABLE DOCUMENT_INPUT_DATE DM_DATE;
DECLARE VARIABLE DOCUMENT_CODE DM_DOCUMENT_CODE;
BEGIN
    UPDATE OR INSERT INTO INVOICES(COMPANY, ID, ORDINAL, DOCUMENT, VAT_PERCENT, INVOICE_DATE, SERIAL_CODE, INVOICE_CODE, SUM_OF_MONEY, SUM_OF_TAX, INPUT_DATE, CUSTOMER, CUSTOMER_TAX_CODE, INVOICE_TYPE, INVOICE_TEMPLATE, CODE_TEMPLATE, EXTRA_GOODS, EXTRA_MONEY)
    VALUES(:P_COMPANY, :P_ID, :P_ORDINAL, :P_DOCUMENT, :P_VAT_PERCENT, :P_INVOICE_DATE, :P_SERIAL_CODE, :P_INVOICE_CODE, :P_SUM_OF_MONEY, :P_SUM_OF_TAX, :P_INPUT_DATE, :P_CUSTOMER, :P_CUSTOMER_TAX_CODE, :P_INVOICE_TYPE, :P_INVOICE_TEMPLATE, :P_CODE_TEMPLATE, :P_EXTRA_GOODS, :P_EXTRA_MONEY);

    UPDATE OR INSERT INTO INVOICE_STRINGS(COMPANY, ID, LANGUAGE, NOTE, FORMS_OF_PAYMENT, BANK_ACCOUNT, BUYER_NAME, CUSTOMER_NAME, CUSTOMER_ADDRESS, GOODS, UNIT)
    VALUES(:P_COMPANY, :P_ID, :P_LANGUAGE, :P_NOTE, :P_FORMS_OF_PAYMENT, :P_BANK_ACCOUNT, :P_BUYER_NAME, :P_CUSTOMER_NAME, :P_CUSTOMER_ADDRESS, :P_GOODS, :P_UNIT);

    WHEN SQLCODE -803 DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = 7 AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        IF(:MESSAGE_CONTENT IS NULL)THEN
            EXCEPTION EX_GENERAL '(' || SQLCODE || ')';
        ELSE
        BEGIN
            SELECT FIRST 1 DOCUMENTS.INPUT_DATE, CODE || '-' || NUMBER
            FROM DOCUMENTS
            JOIN INVOICES ON INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = DOCUMENTS.ID AND
            INVOICES.INVOICE_DATE = :P_INPUT_DATE AND
            INVOICES.INVOICE_TYPE = :P_INVOICE_TYPE AND
            INVOICES.SERIAL_CODE = :P_SERIAL_CODE AND
            INVOICES.INVOICE_CODE = :P_INVOICE_CODE AND
            (
                (:P_CUSTOMER_TAX_CODE IS NULL AND INVOICES.CUSTOMER_TAX_CODE IS NULL) OR
                (INVOICES.CUSTOMER_TAX_CODE = :P_CUSTOMER_TAX_CODE)
             )
            WHERE DOCUMENTS.COMPANY = :P_COMPANY
            INTO :DOCUMENT_INPUT_DATE, :DOCUMENT_CODE;

            IF(DOCUMENT_INPUT_DATE IS NOT NULL AND DOCUMENT_CODE IS NOT NULL)THEN
            BEGIN
                EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || DOCUMENT_CODE || ', ' || EXTRACT(DAY FROM DOCUMENT_INPUT_DATE) || '/' || EXTRACT(MONTH FROM DOCUMENT_INPUT_DATE) || '/' || EXTRACT(YEAR FROM DOCUMENT_INPUT_DATE) || ')' || '(' || P_SERIAL_CODE || '-' || P_INVOICE_CODE || ')' || '(' || SQLCODE || ')';
            END
            ELSE
                EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || P_SERIAL_CODE || '-' || P_INVOICE_CODE || ')' || '(' || SQLCODE || ')';
        END
    END
    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE INVOICE_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT,
BANK_ACCOUNT DM_NAME,
BUYER_NAME DM_NAME,
CUSTOMER DM_ID,
CUSTOMER_NAME DM_NAME,
CUSTOMER_ADDRESS DM_ADDRESS,
CUSTOMER_TAX_CODE DM_TAX_CODE,
DOCUMENT DM_ID,
GOODS DM_GOODS,
UNIT DM_UNIT,
INPUT_DATE DM_DATE,
INVOICE_CODE DM_INVOICE_CODE,
INVOICE_DATE DM_DATE,
INVOICE_TEMPLATE DM_INVOICE_TEMPLATE,
CODE_TEMPLATE DM_INVOICE_TEMPLATE,
INVOICE_TYPE DM_INVOICE_TYPE,
SERIAL_CODE DM_SERIAL_CODE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
EXTRA_GOODS DM_DESCRIPTION,
EXTRA_MONEY DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT INVOICES.ID,ORDINAL, NOTE,
            FORMS_OF_PAYMENT, BANK_ACCOUNT, BUYER_NAME,
            CUSTOMER, CUSTOMER_NAME, CUSTOMER_ADDRESS, DOCUMENT, INPUT_DATE,
            INVOICE_CODE, INVOICE_DATE, SERIAL_CODE, SUM_OF_MONEY, SUM_OF_TAX, CUSTOMER_TAX_CODE, VAT_PERCENT,
            GOODS, UNIT, INVOICES.INVOICE_TEMPLATE, CODE_TEMPLATE, INVOICE_TYPE,
            EXTRA_GOODS, EXTRA_MONEY
        FROM INVOICES
        JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
        WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :P_DOCUMENT
        INTO :ID, :ORDINAL, :NOTE,
            :FORMS_OF_PAYMENT, :BANK_ACCOUNT, :BUYER_NAME,
            :CUSTOMER, :CUSTOMER_NAME, :CUSTOMER_ADDRESS, :DOCUMENT, :INPUT_DATE,
            :INVOICE_CODE, :INVOICE_DATE, :SERIAL_CODE, :SUM_OF_MONEY, :SUM_OF_TAX, :CUSTOMER_TAX_CODE, :VAT_PERCENT,
            :GOODS, :UNIT, :INVOICE_TEMPLATE, :CODE_TEMPLATE, :INVOICE_TYPE,
            :EXTRA_GOODS, :EXTRA_MONEY
    DO
        SUSPEND;
END ^

