ALTER PROCEDURE INVOICE_S_SEARCH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_WHERE DM_STRING)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT,
BANK_ACCOUNT DM_NAME,
BUYER_NAME DM_NAME,
CUSTOMER_NAME DM_NAME,
CUSTOMER_ADDRESS DM_ADDRESS,
CUSTOMER_TAX_CODE DM_TAX_CODE,
DOCUMENT DM_ID,
GOODS DM_GOODS,
UNIT DM_UNIT,
INPUT_DATE DM_DATE,
INVOICE_CODE DM_INVOICE_CODE,
INVOICE_DATE DM_DATE,
INVOICE_TYPE DM_INTEGER,
INVOICE_TEMPLATE DM_INVOICE_TEMPLATE,
CODE_TEMPLATE DM_INVOICE_TEMPLATE,
SERIAL_CODE DM_SERIAL_CODE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
CODE DM_DOCUMENT_CODE)
AS 
DECLARE VARIABLE STRING DM_STRING;
BEGIN
    STRING = 'SELECT INVOICES.ID, INVOICES.ORDINAL, NOTE,
            FORMS_OF_PAYMENT, BANK_ACCOUNT, BUYER_NAME,
            CUSTOMER_NAME, CUSTOMER_ADDRESS, DOCUMENT, INVOICES.INPUT_DATE,
            INVOICE_CODE, INVOICE_DATE, SERIAL_CODE, SUM_OF_MONEY, SUM_OF_TAX, CUSTOMER_TAX_CODE, VAT_PERCENT,
            GOODS, UNIT, INVOICES.INVOICE_TEMPLATE, CODE_TEMPLATE, INVOICE_TYPE, DOCUMENTS.CODE || ''-'' || NUMBER
        FROM DOCUMENTS
        JOIN INVOICES ON INVOICES.COMPANY = ' || :P_COMPANY || ' AND INVOICES.DOCUMENT = DOCUMENTS.ID
        JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND INVOICE_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND INVOICE_STRINGS.ID = INVOICES.ID
        WHERE DOCUMENTS.COMPANY = ' || :P_COMPANY || ' AND ' || :P_WHERE;

    FOR
        EXECUTE STATEMENT STRING
        INTO :ID, :ORDINAL, :NOTE,
            :FORMS_OF_PAYMENT, :BANK_ACCOUNT, :BUYER_NAME,
            :CUSTOMER_NAME, :CUSTOMER_ADDRESS, :DOCUMENT, :INPUT_DATE,
            :INVOICE_CODE, :INVOICE_DATE, :SERIAL_CODE, :SUM_OF_MONEY, :SUM_OF_TAX, :CUSTOMER_TAX_CODE, :VAT_PERCENT,
            :GOODS, :UNIT, :INVOICE_TEMPLATE, :CODE_TEMPLATE, :INVOICE_TYPE, :CODE
    DO
        SUSPEND;
END ^

