ALTER PROCEDURE INVOICE_TEMPLATE_PROCEDURE_SEC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_INVOICE_TEMPLATE DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CODE DM_CODE,
PROCEDURE_NAME DM_PROCEDURE_NAME,
NUMBER_TO_TEXT_FIELD DM_FIELD_CODE)
AS 
BEGIN
FOR
  SELECT INVOICE_TEMPLATE_PROCEDURES.ID, NOTE, ORDINAL, CODE, PROCEDURE_NAME, NUMBER_TO_TEXT_FIELD
  FROM INVOICE_TEMPLATE_PROCEDURES
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = INVOICE_TEMPLATE_PROCEDURES.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE INVOICE_TEMPLATE_PROCEDURES.COMPANY = :P_COMPANY AND INVOICE_TEMPLATE_PROCEDURES.INVOICE_TEMPLATE = :P_INVOICE_TEMPLATE
  INTO :ID, :NOTE, :ORDINAL, :CODE, :PROCEDURE_NAME, :NUMBER_TO_TEXT_FIELD
DO
    SUSPEND;
END ^

