ALTER PROCEDURE LOG_CLEAN_OUT (P_COMPANY DM_ID)
AS 
DECLARE VARIABLE NUMBER_OF_DAYS_STORED DM_INTEGER;
BEGIN
    FOR
        SELECT NUMBER_OF_DAYS_STORED
        FROM SETTINGS
        WHERE SETTINGS.COMPANY = :P_COMPANY AND ENABLE_LOG = 1 AND NUMBER_OF_DAYS_STORED > 0
        INTO :NUMBER_OF_DAYS_STORED
    DO
    BEGIN
        DELETE FROM LOGS
        WHERE LOGS.COMPANY = :P_COMPANY AND DATEDIFF(DAY, LOGS.DATETIME, CURRENT_TIMESTAMP) >= :NUMBER_OF_DAYS_STORED;
    END
END ^

ALTER PROCEDURE LOG_IU (P_COMPANY DM_ID,
P_USERNAME DM_CODE,
P_MODULE DM_NAME,
P_ACTION_NAME DM_NAME,
P_OBJECT DM_NAME)
AS 
BEGIN
    INSERT INTO LOGS(ID, COMPANY, DATETIME, USERNAME, MODULE, ACTION_NAME, OBJECT)
    VALUES(GEN_ID(LOG_GERERATOR, 1), :P_COMPANY, CURRENT_TIMESTAMP, :P_USERNAME, :P_MODULE, :P_ACTION_NAME, :P_OBJECT);
END ^

ALTER PROCEDURE LOG_RS (P_COMPANY DM_ID,
P_FROM_DATE DM_DATE_TIME,
P_TO_DATE DM_DATE_TIME)
RETURNS (ID DM_ID,
DATETIME DM_DATE_TIME,
USERNAME DM_CODE,
MODULE DM_NAME,
ACTION_NAME DM_NAME,
OBJECT DM_NAME)
AS 
BEGIN
    IF(P_FROM_DATE IS NULL)THEN
    BEGIN
        FOR
            SELECT FIRST 100 ID, DATETIME, USERNAME, MODULE, ACTION_NAME, OBJECT
            FROM LOGS
            WHERE LOGS.COMPANY = :P_COMPANY
            ORDER BY DATETIME DESC, ID DESC
            INTO :ID, :DATETIME, :USERNAME, :MODULE, :ACTION_NAME, :OBJECT
        DO
        BEGIN
            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT ID, DATETIME, USERNAME, MODULE, ACTION_NAME, OBJECT
            FROM LOGS
            WHERE LOGS.COMPANY = :P_COMPANY AND LOGS.DATETIME BETWEEN :P_FROM_DATE AND :P_TO_DATE
            ORDER BY DATETIME DESC, ID DESC
            INTO :ID, :DATETIME, :USERNAME, :MODULE, :ACTION_NAME, :OBJECT
        DO
        BEGIN
            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE MATERIAL_NORM_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_PERIOD DM_ID,
P_PRODUCT_ACCOUNT DM_ID,
P_PRODUCT_OBJECT0 DM_ID,
P_INPUT_ACCOUNT DM_ID,
P_INPUT_OBJECT0 DM_ID,
P_INPUT_OBJECT1 DM_ID,
P_AMOUNT DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO MATERIAL_NORMS(COMPANY, ID, PERIOD, PRODUCT_ACCOUNT, PRODUCT_OBJECT0, INPUT_ACCOUNT, INPUT_OBJECT0, INPUT_OBJECT1, AMOUNT)
    VALUES(:P_COMPANY, :P_ID, :P_PERIOD, :P_PRODUCT_ACCOUNT, :P_PRODUCT_OBJECT0, :P_INPUT_ACCOUNT, :P_INPUT_OBJECT0, :P_INPUT_OBJECT1, :P_AMOUNT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE MATERIAL_NORM_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
PERIOD DM_ID,
PRODUCT_ACCOUNT DM_ID,
PRODUCT_OBJECT0 DM_ID,
PRODUCT_OBJECT0_CODE DM_CODE,
INPUT_ACCOUNT DM_ID,
INPUT_OBJECT0 DM_ID,
INPUT_OBJECT0_CODE DM_CODE,
INPUT_OBJECT1 DM_ID,
INPUT_OBJECT1_CODE DM_CODE,
AMOUNT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT MATERIAL_NORMS.ID, NOTE, ORDINAL, PERIOD, PRODUCT_ACCOUNT,
            PRODUCT_OBJECT0, PRODUCT_OBJECT0S.CODE,
            INPUT_ACCOUNT,
            INPUT_OBJECT0, INPUT_OBJECT0S.CODE,
            INPUT_OBJECT1, INPUT_OBJECT1S.CODE,
            AMOUNT
        FROM MATERIAL_NORMS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = MATERIAL_NORMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        LEFT JOIN ATOMS PRODUCT_OBJECT0S ON PRODUCT_OBJECT0S.COMPANY = :P_COMPANY AND PRODUCT_OBJECT0S.ID = MATERIAL_NORMS.PRODUCT_OBJECT0
        LEFT JOIN ATOMS INPUT_OBJECT0S ON INPUT_OBJECT0S.COMPANY = :P_COMPANY AND INPUT_OBJECT0S.ID = MATERIAL_NORMS.INPUT_OBJECT0
        LEFT JOIN ATOMS INPUT_OBJECT1S ON INPUT_OBJECT1S.COMPANY = :P_COMPANY AND INPUT_OBJECT1S.ID = MATERIAL_NORMS.INPUT_OBJECT1
        WHERE MATERIAL_NORMS.COMPANY = :P_COMPANY AND MATERIAL_NORMS.PERIOD = :P_PERIOD
        INTO :ID, :NOTE, :ORDINAL, :PERIOD, :PRODUCT_ACCOUNT,
            :PRODUCT_OBJECT0, :PRODUCT_OBJECT0_CODE,
            :INPUT_ACCOUNT,
            :INPUT_OBJECT0, :INPUT_OBJECT0_CODE,
            :INPUT_OBJECT1, :INPUT_OBJECT1_CODE, 
            :AMOUNT
    DO
        SUSPEND;
END ^

ALTER PROCEDURE MEMBERSHIP_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_ROLE_ID DM_ID,
P_USER_ACCOUNT DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY,:P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO MEMBERSHIPS(COMPANY, ID, ROLE_ID, USER_ACCOUNT)
    VALUES(:P_COMPANY, :P_ID, :P_ROLE_ID, :P_USER_ACCOUNT);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE MEMBERSHIP_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
ROLE_ID DM_ID,
ROLE_CODE DM_CODE,
ROLE_NAME DM_NAME,
IS_NEW DM_BOOL)
AS 
BEGIN
        FOR
            SELECT ROLES.ID, CODE, NAME
            FROM ROLES
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ROLES.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE ROLES.COMPANY = :P_COMPANY
            INTO :ROLE_ID, :ROLE_CODE, :ROLE_NAME
        DO
        BEGIN
            ID = NULL;

            SELECT MEMBERSHIPS.ID, ORDINAL, NOTE
            FROM MEMBERSHIPS
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = MEMBERSHIPS.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            WHERE MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT AND MEMBERSHIPS.ROLE_ID = :ROLE_ID
            INTO :ID, :ORDINAL, :NOTE;

            IF(ID IS NULL)THEN
            BEGIN
                ID = ROLE_ID;
                ORDINAL = 0;
                IS_NEW = 1;
            END
            ELSE
                IS_NEW = 0;

            SUSPEND;
        END
END ^

ALTER PROCEDURE MESSAGE_IU (P_ID DM_ID,
P_CONTENT_VN DM_MESSAGE_CONTENT,
P_EXTRA_CONTENT_VN DM_MESSAGE_CONTENT,
P_TITLE_VN DM_MESSAGE_TITLE,
P_CONTENT_EN DM_MESSAGE_CONTENT,
P_EXTRA_CONTENT_EN DM_MESSAGE_CONTENT,
P_TITLE_EN DM_MESSAGE_TITLE,
P_CONTENT_OT DM_MESSAGE_CONTENT,
P_EXTRA_CONTENT_OT DM_MESSAGE_CONTENT,
P_TITLE_OT DM_MESSAGE_TITLE)
AS 
BEGIN
    UPDATE OR INSERT INTO MESSAGES(ID, CONTENT, EXTRA_CONTENT, TITLE, LANGUAGE)
    VALUES(:P_ID, :P_CONTENT_VN, :P_EXTRA_CONTENT_VN, :P_TITLE_VN, 0);

    UPDATE OR INSERT INTO MESSAGES(ID, CONTENT, EXTRA_CONTENT, TITLE, LANGUAGE)
    VALUES(:P_ID, :P_CONTENT_EN, :P_EXTRA_CONTENT_EN, :P_TITLE_EN, 1);

    UPDATE OR INSERT INTO MESSAGES(ID, CONTENT, EXTRA_CONTENT, TITLE, LANGUAGE)
    VALUES(:P_ID, :P_CONTENT_OT, :P_EXTRA_CONTENT_OT, :P_TITLE_OT, 2);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, 0);
END ^

