ALTER PROCEDURE NOTE_IU (P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID,
P_NOTE DM_STRING)
AS 
BEGIN
    UPDATE OR INSERT INTO NOTES(COMPANY, USER_ACCOUNT, NOTE, REMINDER)
    VALUES(:P_COMPANY, :P_USER_ACCOUNT, :P_NOTE, 3);
END ^

ALTER PROCEDURE NOTE_S_RS (P_COMPANY DM_ID,
P_USER_ACCOUNT DM_ID)
RETURNS (NOTE DM_STRING,
REMINDER DM_INTEGER)
AS 
BEGIN
    FOR
        SELECT NOTE, REMINDER
        FROM NOTES
        WHERE NOTES.COMPANY = :P_COMPANY AND NOTES.USER_ACCOUNT = :P_USER_ACCOUNT
        INTO :NOTE, :REMINDER
    DO
    BEGIN
        UPDATE NOTES
        SET NOTES.REMINDER = NOTES.REMINDER - 1
        WHERE NOTES.COMPANY = :P_COMPANY AND NOTES.USER_ACCOUNT = :P_USER_ACCOUNT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE OBJECT_TYPE_D (P_LANGUAGE TYPE OF DM_SMALLINT,
P_ID TYPE OF DM_ID)
AS 
DECLARE VARIABLE MESSAGE_CONTENT TYPE OF DM_MESSAGE_CONTENT;
BEGIN
    DELETE FROM OBJECT_TYPES
    WHERE ID = :P_ID AND ID > 1000; 

    WHEN ANY DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = SQLCODE AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || SQLCODE || ')';
    END
END ^

