ALTER PROCEDURE ORDER_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID)
AS 
BEGIN
  FOR
  SELECT ORDERS.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
  FROM ORDERS
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ORDERS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE ORDERS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
  DO
    SUSPEND;
END ^

ALTER PROCEDURE PERIOD_HALFYEAR2QUARTER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE PERIOD_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
BEGIN
    SELECT EXTRACT(YEAR FROM PERIODS.BEGINNING_DATE), EXTRACT(MONTH FROM PERIODS.BEGINNING_DATE)
    FROM PERIODS
    WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :P_PERIOD
    INTO :PERIOD_YEAR, BEGINNING_MONTH;

    IF(BEGINNING_MONTH = 1)THEN
    BEGIN
        UPDATE PERIODS
        SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.1.1',
            PERIODS.ENDING_DATE = :PERIOD_YEAR || '.3.31'
        WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.4.1';
        ENDING_DATE = PERIOD_YEAR || '.6.30';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
    END
    ELSE
    BEGIN
        UPDATE PERIODS
        SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.7.1',
            PERIODS.ENDING_DATE = :PERIOD_YEAR || '.9.30'
        WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.10.1';
        ENDING_DATE = PERIOD_YEAR || '.12.31';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
    END
END ^

ALTER PROCEDURE PERIOD_HALFYEAR2YEAR (P_LANGUAGE DM_SMALLINT,
