    WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :P_PERIOD
    INTO :PERIOD_YEAR;
        BEGINNING_DATE = PERIOD_YEAR || '.7.1';
        ENDING_DATE = PERIOD_YEAR || '.12.31';

        UPDATE PERIODS
        SET COMPANY = 0
        WHERE COMPANY = :P_COMPANY AND ID <> :P_PERIOD AND
        (
            (BEGINNING_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE)
