        );

        BEGINNING_DATE = PERIOD_YEAR || '.1.1';
        ENDING_DATE = PERIOD_YEAR || '.12.31';

        UPDATE PERIODS
        SET BEGINNING_DATE = :BEGINNING_DATE,
            ENDING_DATE = :ENDING_DATE
        WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD;

