        WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY AND ACCOUNTING_SETTINGS.BEGINNING_PERIOD IN
        (
            SELECT ID
            FROM PERIODS
            WHERE COMPANY = 0 AND ID <> :P_PERIOD AND
            (
                (BEGINNING_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE)
                OR
                (ENDING_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE)
            )
        );

        DELETE FROM PERIODS
        WHERE COMPANY = 0 AND ID <> :P_PERIOD AND
        (
            (BEGINNING_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE)
            OR
            (ENDING_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE)
        );
END ^

ALTER PROCEDURE PERIOD_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_BEGINNING_DATE DM_DATE,
P_ENDING_DATE DM_DATE,
P_LOCKED DM_BOOL)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
BEGIN
    IF(
        EXISTS (SELECT DOCUMENTS.ID FROM DOCUMENTS WHERE COMPANY = :P_COMPANY AND PERIOD <> :P_ID AND INPUT_DATE BETWEEN :P_BEGINNING_DATE AND :P_ENDING_DATE)
        OR
        EXISTS (SELECT DOCUMENTS.ID FROM DOCUMENTS WHERE COMPANY = :P_COMPANY AND PERIOD = :P_ID AND INPUT_DATE NOT BETWEEN :P_BEGINNING_DATE AND :P_ENDING_DATE)
    )THEN
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = 5 AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT;
    END
    BEGIN
        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED)
        VALUES(:P_COMPANY, :P_ID, :P_BEGINNING_DATE, :P_ENDING_DATE, :P_LOCKED);

        WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
    END
END ^

