ALTER PROCEDURE PERIOD_QUARTER2MONTH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE PERIOD_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_MONTH DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
BEGIN
    SELECT EXTRACT(YEAR FROM PERIODS.BEGINNING_DATE), EXTRACT(MONTH FROM PERIODS.BEGINNING_DATE)
    FROM PERIODS
    WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :P_PERIOD
    INTO :PERIOD_YEAR, BEGINNING_MONTH;

    IF(BEGINNING_MONTH = 1)THEN
    BEGIN
        UPDATE PERIODS
        SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.1.1',
            PERIODS.ENDING_DATE = :PERIOD_YEAR || '.1.31'
        WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.2.1';
        IF(EXISTS (SELECT 1 FROM CMD_IS_LEAP_YEAR(:PERIOD_YEAR) WHERE CMD_IS_LEAP_YEAR.IS_LEAP_YEAR = 1))THEN
            ENDING_DATE = PERIOD_YEAR || '.2.29';
        ELSE
            ENDING_DATE = PERIOD_YEAR || '.2.28';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.3.1';
        ENDING_DATE = PERIOD_YEAR || '.3.31';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
    END
    ELSE IF(BEGINNING_MONTH = 4)THEN
    BEGIN
        UPDATE PERIODS
        SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.4.1',
            PERIODS.ENDING_DATE = :PERIOD_YEAR || '.4.30'
        WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.5.1';
        ENDING_DATE = PERIOD_YEAR || '.5.31';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.6.1';
        ENDING_DATE = PERIOD_YEAR || '.6.30';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
    END
    ELSE IF(BEGINNING_MONTH = 7)THEN
    BEGIN
        UPDATE PERIODS
        SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.7.1',
            PERIODS.ENDING_DATE = :PERIOD_YEAR || '.7.31'
        WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.8.1';
        ENDING_DATE = PERIOD_YEAR || '.8.31';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.9.1';
        ENDING_DATE = PERIOD_YEAR || '.9.30';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
    END
    ELSE IF(BEGINNING_MONTH = 10)THEN
    BEGIN
        UPDATE PERIODS
        SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.10.1',
            PERIODS.ENDING_DATE = :PERIOD_YEAR || '.10.31'
        WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.11.1';
        ENDING_DATE = PERIOD_YEAR || '.11.30';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;

        P_PERIOD = GEN_ID(UNIVERSE, 1);
        BEGINNING_DATE = PERIOD_YEAR || '.12.1';
        ENDING_DATE = PERIOD_YEAR || '.12.31';

        EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
        UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
        VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

        UPDATE DOCUMENTS
        SET DOCUMENTS.PERIOD = :P_PERIOD
        WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
    END
END ^

ALTER PROCEDURE PERIOD_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
LOCKED DM_BOOL)
AS 
begin
FOR
  SELECT PERIODS.ID, NOTE, ORDINAL, BEGINNING_DATE, ENDING_DATE, LOCKED
  FROM PERIODS
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = PERIODS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE PERIODS.COMPANY = :P_COMPANY
  INTO :ID, :NOTE, :ORDINAL, :BEGINNING_DATE, :ENDING_DATE, :LOCKED
DO
    SUSPEND;
end ^

ALTER PROCEDURE PERIOD_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
FOR
  SELECT ID, BEGINNING_DATE, ENDING_DATE
  FROM PERIODS
  WHERE COMPANY = :P_COMPANY
  ORDER BY BEGINNING_DATE
  INTO :ID, :BEGINNING_DATE, :ENDING_DATE
DO
    SUSPEND;

END ^

ALTER PROCEDURE PERIOD_YEAR2HALFYEAR (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
AS 
DECLARE VARIABLE PERIOD_YEAR DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE ENDING_DATE DM_DATE;
BEGIN
    SELECT EXTRACT(YEAR FROM PERIODS.BEGINNING_DATE)
    FROM PERIODS
    WHERE PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = :P_PERIOD
    INTO :PERIOD_YEAR;

    UPDATE PERIODS
    SET PERIODS.BEGINNING_DATE = :PERIOD_YEAR || '.1.1',
        PERIODS.ENDING_DATE = :PERIOD_YEAR || '.6.30'
    WHERE PERIODS.COMPANY = :P_COMPANY AND ID = :P_PERIOD;

    P_PERIOD = GEN_ID(UNIVERSE, 1);
    BEGINNING_DATE = PERIOD_YEAR || '.7.1';
    ENDING_DATE = PERIOD_YEAR || '.12.31';

    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_PERIOD, NULL, 0);
    UPDATE OR INSERT INTO PERIODS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE, LOCKED, CHANGED)
    VALUES(:P_COMPANY, :P_PERIOD, :BEGINNING_DATE, :ENDING_DATE, 0, 1);

    UPDATE DOCUMENTS
    SET DOCUMENTS.PERIOD = :P_PERIOD
    WHERE COMPANY = :P_COMPANY AND INPUT_DATE BETWEEN :BEGINNING_DATE AND :ENDING_DATE;
END ^

