ALTER PROCEDURE PREPAID_EXPENSE_PERIOD_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PREPAID_EXPENSE DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
DEPRECIATION_PERIOD DM_SMALLINT,
TOTAL_DEPRECIATION_PERIOD DM_SMALLINT,
BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER,
BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER)
AS 
begin
    FOR
        SELECT PREPAID_EXPENSE_PERIODS.ID, NOTE, ORDINAL, DEPRECIATION_PERIOD, TOTAL_DEPRECIATION_PERIOD, BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2
        FROM PREPAID_EXPENSE_PERIODS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = PREPAID_EXPENSE_PERIODS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE PREPAID_EXPENSE_PERIODS.COMPANY = :P_COMPANY AND PREPAID_EXPENSE_PERIODS.PREPAID_EXPENSE = :P_PREPAID_EXPENSE
        INTO :ID, :NOTE, :ORDINAL, :DEPRECIATION_PERIOD, :TOTAL_DEPRECIATION_PERIOD, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2
    DO
        SUSPEND;
end ^

ALTER PROCEDURE PREPAID_EXPENSE_S_DEPRECIATION (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (ID DM_ID,
DEPRECIATION_DATE DM_DATE,
REMAINING_DEPRECIATION_PERIOD DM_DOUBLE)
AS 
DECLARE VARIABLE DEPRECIATION_PERIOD DM_SMALLINT;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE1 DM_SMALLINT;
DECLARE VARIABLE BEGINNING_DEPRECIATION_VALUE2 DM_SMALLINT;
DECLARE VARIABLE BEGINNING_DATE_OF_PERIOD DM_DATE;
DECLARE VARIABLE ENDING_DATE_OF_PERIOD DM_DATE;
BEGIN
    SELECT BEGINNING_DATE, ENDING_DATE
    FROM PERIODS
    WHERE COMPANY = :P_COMPANY AND ID = :P_PERIOD
    INTO :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD;

    FOR
        SELECT PREPAID_EXPENSES.ID, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE,
        BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2
        FROM PREPAID_EXPENSES
        WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY
        INTO :ID, :DEPRECIATION_PERIOD, :DEPRECIATION_TIME_TYPE, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2
    DO
    BEGIN
        IF(DEPRECIATION_TIME_TYPE = 2)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_MONTH_OF_PERIOD, REMAINING_MONTHS
                FROM INT_MONTH_DIFF(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                SUSPEND;
        END
        ELSE
        IF(DEPRECIATION_TIME_TYPE = 3)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_QUARTER, REMAINING_QUARTERS
                FROM INT_QUARTER_DIFF(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                SUSPEND;
        END
        ELSE IF(DEPRECIATION_TIME_TYPE = 4)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_HALF_YEAR, REMAINING_HALF_YEARS
                FROM INT_HALF_YEAR_DIFF(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                SUSPEND;
        END
        ELSE IF(DEPRECIATION_TIME_TYPE = 5)THEN
        BEGIN
            FOR
                SELECT ENDING_DATE_OF_YEAR, REMAINING_YEARS
                FROM INT_YEAR_DIFF(:P_COMPANY, :ID, :BEGINNING_DEPRECIATION_VALUE1, :DEPRECIATION_PERIOD, :BEGINNING_DATE_OF_PERIOD, :ENDING_DATE_OF_PERIOD)
                INTO :DEPRECIATION_DATE, :REMAINING_DEPRECIATION_PERIOD
            DO
                SUSPEND;
        END
    END
END ^

ALTER PROCEDURE PREPAID_EXPENSE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
TOTAL_DEPRECIATION_PERIOD DM_SMALLINT,
DEPRECIATION_PERIOD DM_SMALLINT,
DEPRECIATION_TIME_TYPE DM_TIME_TYPE,
BEGINNING_DEPRECIATION_VALUE1 DM_INTEGER,
BEGINNING_DEPRECIATION_VALUE2 DM_INTEGER,
ACCOUNT DM_ID,
ACCOUNT_EXPENSE DM_ID,
DATE_OF_USING DM_DATE)
AS 
BEGIN
    FOR
        SELECT PREPAID_EXPENSES.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
        TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE,
        BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, ACCOUNT, ACCOUNT_EXPENSE, DATE_OF_USING
        FROM PREPAID_EXPENSES
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PREPAID_EXPENSES.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
        :TOTAL_DEPRECIATION_PERIOD, :DEPRECIATION_PERIOD, :DEPRECIATION_TIME_TYPE,
        :BEGINNING_DEPRECIATION_VALUE1, :BEGINNING_DEPRECIATION_VALUE2, :ACCOUNT, :ACCOUNT_EXPENSE,
        :DATE_OF_USING
    DO
        SUSPEND;
END ^

ALTER PROCEDURE PREPAID_EXPENSE_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID,
P_GENERATE_ACCOUNT DM_BOOL = 1)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
ACCOUNT_CODE DM_CODE,
IS_DEFINED DM_BOOL)
AS 
DECLARE VARIABLE ACCOUNT_EXPENSE DM_ID;
BEGIN
    FOR
        SELECT PREPAID_EXPENSE_S_DEPRECIATION.ID, PREPAID_EXPENSE_ATOMS.CODE, NAME, ACCOUNT_ATOMS.CODE
        FROM PREPAID_EXPENSE_S_DEPRECIATION(:P_LANGUAGE, :P_COMPANY, :P_PERIOD)
        JOIN PREPAID_EXPENSES ON PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ID = PREPAID_EXPENSE_S_DEPRECIATION.ID
        JOIN ATOMS PREPAID_EXPENSE_ATOMS ON PREPAID_EXPENSE_ATOMS.COMPANY = :P_COMPANY AND PREPAID_EXPENSE_ATOMS.ID = PREPAID_EXPENSES.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = PREPAID_EXPENSE_ATOMS.ID
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = PREPAID_EXPENSES.ACCOUNT
        JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = ACCOUNTS.ID
        GROUP BY ID, PREPAID_EXPENSE_ATOMS.CODE, NAME, ACCOUNT_ATOMS.CODE
        INTO :ID, :CODE, :NAME, :ACCOUNT_CODE
    DO
    BEGIN
        IF(EXISTS (
            SELECT *
            FROM EXPENSE_ACCOUNTS
            WHERE EXPENSE_ACCOUNTS.COMPANY = :P_COMPANY AND EXPENSE_ACCOUNTS.PREPAID_EXPENSE = :ID AND EXPENSE_ACCOUNTS.PERIOD = :P_PERIOD)
        )
        THEN
            IS_DEFINED = 1;
        ELSE
        BEGIN
            IS_DEFINED = 0;

            
            IF(P_GENERATE_ACCOUNT = 1)THEN
            BEGIN
                SELECT ACCOUNT_EXPENSE
                FROM PREPAID_EXPENSES
                JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ACCOUNT_EXPENSE
                AND ACCOUNTS.ATOM_TYPE_0 IS NULL
                AND ACCOUNTS.ATOM_TYPE_1 IS NULL
                AND ACCOUNTS.ATOM_TYPE_2 IS NULL
                WHERE PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ID = :ID
                INTO :ACCOUNT_EXPENSE;

                IF(ACCOUNT_EXPENSE IS NOT NULL)THEN
                BEGIN
                    EXECUTE PROCEDURE EXPENSE_ACCOUNT_IU(:P_LANGUAGE, :P_COMPANY, GEN_ID(UNIVERSE, 1), NULL, 0, :P_PERIOD, :ID, :ACCOUNT_EXPENSE, NULL, NULL, NULL, 1);
                    IS_DEFINED = 1;
                END
            END
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE PROJECT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_BEGINNING_DATE DM_DATE,
P_ENDING_DATE DM_DATE,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO PROJECTS(COMPANY, ID, BEGINNING_DATE, ENDING_DATE) VALUES(:P_COMPANY, :P_ID, :P_BEGINNING_DATE, :P_ENDING_DATE);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE PROJECT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE)
AS 
BEGIN
  FOR
  SELECT PROJECTS.ID,ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT, BEGINNING_DATE, ENDING_DATE
  FROM PROJECTS
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PROJECTS.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE PROJECTS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT, :BEGINNING_DATE, :ENDING_DATE
  DO
    SUSPEND;
END ^

ALTER PROCEDURE PROTON_D (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
BEGIN
    DELETE FROM PROTONS
    WHERE COMPANY = :P_COMPANY AND ID = :P_ID;

    WHEN ANY DO
    BEGIN
        SELECT TITLE || '\$' || CONTENT
        FROM MESSAGES
        WHERE ID = SQLCODE AND LANGUAGE = :P_LANGUAGE
        INTO :MESSAGE_CONTENT;

        EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || SQLCODE || ')';
    END
END ^

ALTER PROCEDURE PROTON_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER)
AS 
BEGIN
    UPDATE OR INSERT INTO PROTONS(COMPANY, ID, ORDINAL)
    VALUES(:P_COMPANY, :P_ID, :P_ORDINAL);

    UPDATE OR INSERT INTO PROTON_STRINGS(COMPANY, ID, NOTE, LANGUAGE)
    VALUES(:P_COMPANY, :P_ID, :P_NOTE, :P_LANGUAGE);

    UPDATE OR INSERT INTO PROTON_STRINGS(COMPANY, ID, NOTE, LANGUAGE)
    VALUES(:P_COMPANY, :P_ID, :P_NOTE, 1);
END ^

