    UPDATE OR INSERT INTO RECORDED_DOCUMENTS(COMPANY, ID, CODE, CONTENT, TEAM, PERIOD, INPUT_DATE)
    VALUES(:P_COMPANY, :P_ID, :P_CODE, :P_CONTENT, :P_TEAM, :P_PERIOD, :P_INPUT_DATE);

