ALTER PROCEDURE RECORDED_DOCUMENT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
CONTENT DM_CONTENT,
TEAM DM_ID,
PERIOD DM_ID,
INPUT_DATE DM_DATE,
SUM_OF_MONEY DM_DOUBLE)
AS 
BEGIN
  FOR
    SELECT RECORDED_DOCUMENTS.ID,ORDINAL, NOTE, CODE, CONTENT, INPUT_DATE, TEAM, PERIOD
    FROM RECORDED_DOCUMENTS
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = RECORDED_DOCUMENTS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE RECORDED_DOCUMENTS.COMPANY = :P_COMPANY AND PERIOD = :P_PERIOD
    INTO :ID, :ORDINAL, :NOTE, :CODE, :CONTENT, :INPUT_DATE, :TEAM, :PERIOD
  DO
  BEGIN
    SELECT SUM(SUM_OF_MONEY)
    FROM RECORDED_DOCUMENT_ENTRIES
    WHERE RECORDED_DOCUMENT_ENTRIES.COMPANY = :P_COMPANY AND RECORDED_DOCUMENT_ENTRIES.RECORDED_DOCUMENT = :ID
    INTO :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL)THEN SUM_OF_MONEY = 0;

    SUSPEND;
  END
END ^

