  SELECT REPORT_PARAMETERS.ID, IIF(LANGUAGE_PROTON_STRINGS.ID IS NULL, VIETNAMESE_PROTON_STRINGS.NOTE, LANGUAGE_PROTON_STRINGS.NOTE), ORDINAL, CODE, IIF(LANGUAGE_REPORT_PARAMETER_STRINGS.NAME IS NULL, VIETNAMESE_REPORT_PARAMETER_STRINGS.NAME, LANGUAGE_REPORT_PARAMETER_STRINGS.NAME), NOT_NULL, DEFAULT_VALUE, HIDE,
  DEBIT_CREDIT_CODE, OBJECT0_PARAMETER_CODE, OBJECT1_PARAMETER_CODE, OBJECT2_PARAMETER_CODE, DEFAULT_OBJECT0, DEFAULT_OBJECT1, DEFAULT_OBJECT2
  FROM REPORT_ACCOUNT_PARAMETERS
  JOIN REPORT_PARAMETERS ON REPORT_PARAMETERS.COMPANY = :P_COMPANY AND REPORT_PARAMETERS.ID = REPORT_ACCOUNT_PARAMETERS.ID AND REPORT_PARAMETERS.REPORT = :P_REPORT
  LEFT JOIN REPORT_PARAMETER_STRINGS LANGUAGE_REPORT_PARAMETER_STRINGS ON LANGUAGE_REPORT_PARAMETER_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_REPORT_PARAMETER_STRINGS.ID = REPORT_PARAMETERS.ID AND LANGUAGE_REPORT_PARAMETER_STRINGS.LANGUAGE = :P_LANGUAGE
  JOIN REPORT_PARAMETER_STRINGS VIETNAMESE_REPORT_PARAMETER_STRINGS ON VIETNAMESE_REPORT_PARAMETER_STRINGS.COMPANY = :P_COMPANY AND VIETNAMESE_REPORT_PARAMETER_STRINGS.ID = REPORT_PARAMETERS.ID AND VIETNAMESE_REPORT_PARAMETER_STRINGS.LANGUAGE = 0
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = REPORT_PARAMETERS.ID
