ALTER PROCEDURE REPORT_INFO_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_REPORT DM_ID)
RETURNS (EXPORT_TYPE DM_EXPORT_TYPE,
HAS_TEMPLATE_FILE DM_BOOL,
TEMPLATE_FILE_NAME DM_NAME,
HAS_TEMPLATE_FILE_OTHER DM_BOOL,
TEMPLATE_FILE_OTHER_NAME DM_NAME)
AS 
DECLARE VARIABLE TEMPLATE_FILE DM_FILE_NAME;
DECLARE VARIABLE TEMPLATE_FILE_OTHER DM_FILE_NAME;
BEGIN
    SELECT EXPORT_TYPE
    FROM REPORTS
    WHERE COMPANY = :P_COMPANY AND ID = :P_REPORT
    INTO :EXPORT_TYPE;

    SELECT IIF(REPORT_STRINGS.TEMPLATE_FILE IS NULL OR REPORT_STRINGS.TEMPLATE_FILE = '', 0, 1), TEMPLATE_FILE_NAME,
    IIF(REPORT_STRINGS.TEMPLATE_FILE_OTHER IS NULL OR REPORT_STRINGS.TEMPLATE_FILE_OTHER = '', 0, 1),TEMPLATE_FILE_OTHER_NAME
    FROM REPORT_STRINGS
    WHERE REPORT_STRINGS.COMPANY = :P_COMPANY AND REPORT_STRINGS.LANGUAGE = :P_LANGUAGE AND REPORT_STRINGS.ID = :P_REPORT
    INTO :HAS_TEMPLATE_FILE, :TEMPLATE_FILE_NAME, :HAS_TEMPLATE_FILE_OTHER, :TEMPLATE_FILE_OTHER_NAME;

    IF(HAS_TEMPLATE_FILE IS NULL)THEN
    BEGIN
        SELECT REPORT_STRINGS.TEMPLATE_FILE, IIF(REPORT_STRINGS.TEMPLATE_FILE IS NULL OR REPORT_STRINGS.TEMPLATE_FILE = '', 0, 1), TEMPLATE_FILE_NAME
        FROM REPORT_STRINGS
        WHERE REPORT_STRINGS.COMPANY = :P_COMPANY AND REPORT_STRINGS.LANGUAGE = 0 AND REPORT_STRINGS.ID = :P_REPORT
        INTO :TEMPLATE_FILE, :HAS_TEMPLATE_FILE, :TEMPLATE_FILE_NAME;
    END

    IF(HAS_TEMPLATE_FILE_OTHER IS NULL)THEN
    BEGIN
        SELECT REPORT_STRINGS.TEMPLATE_FILE_OTHER, IIF(REPORT_STRINGS.TEMPLATE_FILE_OTHER IS NULL OR REPORT_STRINGS.TEMPLATE_FILE_OTHER = '', 0, 1),TEMPLATE_FILE_OTHER_NAME
        FROM REPORT_STRINGS
        WHERE REPORT_STRINGS.COMPANY = :P_COMPANY AND REPORT_STRINGS.LANGUAGE = 0 AND REPORT_STRINGS.ID = :P_REPORT
        INTO :TEMPLATE_FILE_OTHER, :HAS_TEMPLATE_FILE_OTHER, :TEMPLATE_FILE_OTHER_NAME;

    END

    SUSPEND;
END ^

