ALTER PROCEDURE REPORT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_ENGLISH_NAME DM_NAME,
P_TEMPLATE_FILE DM_FILE_NAME,
P_TEMPLATE_FILE_NAME DM_NAME,
P_TEMPLATE_FILE_OTHER DM_FILE_NAME,
P_TEMPLATE_FILE_OTHER_NAME DM_NAME,
P_ENGLISH_TEMPLATE_FILE DM_FILE_NAME,
P_ENGLISH_TEMPLATE_FILE_NAME DM_NAME,
P_ENGLISH_TEMPLATE_FILE_OTHER DM_FILE_NAME,
P_ENGLISH_TEMPLATE_FILE_OTHER_N DM_NAME,
P_REPORT_TYPE DM_REPORT_TYPE,
P_EXPORT_TYPE DM_EXPORT_TYPE,
P_KEY_FIELD_CODE DM_FIELD_CODE,
P_KEY_FIELD_NAME DM_FIELD_NAME,
P_OTHER_TEMPLATE_FILE_1 DM_FILE_NAME,
P_OTHER_TEMPLATE_FILE_1_NAME DM_NAME,
P_OTHER_TEMPLATE_FILE_2 DM_FILE_NAME,
P_OTHER_TEMPLATE_FILE_2_NAME DM_NAME,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU_ENGLISH_NAME(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_ENGLISH_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO REPORTS(COMPANY, ID, REPORT_TYPE, EXPORT_TYPE, KEY_FIELD_CODE, KEY_FIELD_NAME)
    VALUES(:P_COMPANY, :P_ID, :P_REPORT_TYPE, :P_EXPORT_TYPE, :P_KEY_FIELD_CODE, :P_KEY_FIELD_NAME);

    UPDATE OR INSERT INTO REPORT_STRINGS(LANGUAGE, COMPANY, ID, TEMPLATE_FILE, TEMPLATE_FILE_NAME, TEMPLATE_FILE_OTHER, TEMPLATE_FILE_OTHER_NAME)
    VALUES(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_TEMPLATE_FILE, :P_TEMPLATE_FILE_NAME, :P_TEMPLATE_FILE_OTHER, :P_TEMPLATE_FILE_OTHER_NAME);

    IF(P_ENGLISH_TEMPLATE_FILE IS NULL)THEN P_ENGLISH_TEMPLATE_FILE = P_TEMPLATE_FILE;
    IF(P_ENGLISH_TEMPLATE_FILE_OTHER IS NULL)THEN P_ENGLISH_TEMPLATE_FILE_OTHER = P_TEMPLATE_FILE_OTHER;

    UPDATE OR INSERT INTO REPORT_STRINGS(LANGUAGE, COMPANY, ID, TEMPLATE_FILE, TEMPLATE_FILE_NAME, TEMPLATE_FILE_OTHER, TEMPLATE_FILE_OTHER_NAME)
    VALUES(1, :P_COMPANY, :P_ID, :P_ENGLISH_TEMPLATE_FILE, :P_ENGLISH_TEMPLATE_FILE_NAME, :P_ENGLISH_TEMPLATE_FILE_OTHER, :P_ENGLISH_TEMPLATE_FILE_OTHER_N);

    IF(P_OTHER_TEMPLATE_FILE_1 IS NULL)THEN P_OTHER_TEMPLATE_FILE_1 = P_TEMPLATE_FILE;
    IF(P_OTHER_TEMPLATE_FILE_2 IS NULL)THEN P_OTHER_TEMPLATE_FILE_2 = P_TEMPLATE_FILE_OTHER;

    UPDATE OR INSERT INTO REPORT_STRINGS(LANGUAGE, COMPANY, ID, TEMPLATE_FILE, TEMPLATE_FILE_NAME, TEMPLATE_FILE_OTHER, TEMPLATE_FILE_OTHER_NAME)
    VALUES(2, :P_COMPANY, :P_ID, :P_OTHER_TEMPLATE_FILE_1, :P_OTHER_TEMPLATE_FILE_1_NAME, :P_OTHER_TEMPLATE_FILE_2, :P_OTHER_TEMPLATE_FILE_2_NAME);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

