ALTER PROCEDURE REPORT_STRING_PARAMETER_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_REPORT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CODE DM_CODE,
HIDE DM_BOOL,
NAME DM_NAME,
ENGLISH_NAME DM_NAME,
NOT_NULL DM_BOOL,
DEFAULT_VALUE DM_STRING)
AS 
begin
FOR
  SELECT REPORT_PARAMETERS.ID, NOTE, ORDINAL, CODE, LANGUAGE_REPORT_PARAMETER_STRINGS.NAME, ENGLISH_REPORT_PARAMETER_STRINGS.NAME, NOT_NULL, DEFAULT_VALUE, HIDE
  FROM REPORT_STRING_PARAMETERS
  JOIN REPORT_PARAMETERS ON REPORT_PARAMETERS.COMPANY = :P_COMPANY AND REPORT_PARAMETERS.ID = REPORT_STRING_PARAMETERS.ID AND REPORT_PARAMETERS.REPORT = :P_REPORT
  JOIN REPORT_PARAMETER_STRINGS LANGUAGE_REPORT_PARAMETER_STRINGS ON LANGUAGE_REPORT_PARAMETER_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_REPORT_PARAMETER_STRINGS.ID = REPORT_PARAMETERS.ID AND LANGUAGE_REPORT_PARAMETER_STRINGS.LANGUAGE = :P_LANGUAGE
  LEFT JOIN REPORT_PARAMETER_STRINGS ENGLISH_REPORT_PARAMETER_STRINGS ON ENGLISH_REPORT_PARAMETER_STRINGS.COMPANY = :P_COMPANY AND ENGLISH_REPORT_PARAMETER_STRINGS.ID = REPORT_PARAMETERS.ID AND ENGLISH_REPORT_PARAMETER_STRINGS.LANGUAGE = 1
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = REPORT_PARAMETERS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE REPORT_STRING_PARAMETERS.COMPANY = :P_COMPANY
  INTO :ID, :NOTE, :ORDINAL, :CODE, :NAME, :ENGLISH_NAME, :NOT_NULL, :DEFAULT_VALUE, :HIDE
DO
    SUSPEND;
end ^

