ALTER PROCEDURE REPORT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
ENGLISH_NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID,
TEMPLATE_FILE DM_FILE_NAME,
TEMPLATE_FILE_NAME DM_NAME,
TEMPLATE_FILE_OTHER DM_FILE_NAME,
TEMPLATE_FILE_OTHER_NAME DM_NAME,
ENGLISH_TEMPLATE_FILE DM_FILE_NAME,
ENGLISH_TEMPLATE_FILE_NAME DM_NAME,
ENGLISH_TEMPLATE_FILE_OTHER DM_FILE_NAME,
ENGLISH_TEMPLATE_FILE_OTHER_N DM_NAME,
REPORT_TYPE DM_REPORT_TYPE,
EXPORT_TYPE DM_EXPORT_TYPE,
KEY_FIELD_CODE DM_FIELD_CODE,
KEY_FIELD_NAME DM_FIELD_NAME,
OTHER_TEMPLATE_FILE_1 DM_FILE_NAME,
OTHER_TEMPLATE_FILE_1_NAME DM_NAME,
OTHER_TEMPLATE_FILE_2 DM_FILE_NAME,
OTHER_TEMPLATE_FILE_2_NAME DM_NAME)
AS 
BEGIN
  FOR
  SELECT REPORTS.ID, ORDINAL, NOTE,
         CODE, LANGUAGE_ATOM_STRINGS.NAME, ENGLISH_ATOM_STRINGS.NAME, HIDE, PARENT, TEAM, RELATED_OBJECT,
         LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE, ENGLISH_REPORT_STRINGS.TEMPLATE_FILE, OTHER_REPORT_STRINGS.TEMPLATE_FILE,
         LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE_NAME, ENGLISH_REPORT_STRINGS.TEMPLATE_FILE_NAME, OTHER_REPORT_STRINGS.TEMPLATE_FILE_NAME,
         LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE_OTHER, ENGLISH_REPORT_STRINGS.TEMPLATE_FILE_OTHER, OTHER_REPORT_STRINGS.TEMPLATE_FILE_OTHER,
         LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE_OTHER_NAME, ENGLISH_REPORT_STRINGS.TEMPLATE_FILE_OTHER_NAME, OTHER_REPORT_STRINGS.TEMPLATE_FILE_OTHER_NAME,
         REPORT_TYPE, EXPORT_TYPE, KEY_FIELD_CODE, KEY_FIELD_NAME
  FROM REPORTS
  JOIN REPORT_STRINGS LANGUAGE_REPORT_STRINGS ON LANGUAGE_REPORT_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_REPORT_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_REPORT_STRINGS.ID = REPORTS.ID
  LEFT JOIN REPORT_STRINGS ENGLISH_REPORT_STRINGS ON ENGLISH_REPORT_STRINGS.COMPANY = :P_COMPANY AND ENGLISH_REPORT_STRINGS.LANGUAGE = 1 AND ENGLISH_REPORT_STRINGS.ID = REPORTS.ID
  LEFT JOIN REPORT_STRINGS OTHER_REPORT_STRINGS ON OTHER_REPORT_STRINGS.COMPANY = :P_COMPANY AND OTHER_REPORT_STRINGS.LANGUAGE = 2 AND OTHER_REPORT_STRINGS.ID = REPORTS.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = REPORTS.ID
  JOIN ATOM_STRINGS LANGUAGE_ATOM_STRINGS ON LANGUAGE_ATOM_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_ATOM_STRINGS.ID = ATOMS.ID
  LEFT JOIN ATOM_STRINGS ENGLISH_ATOM_STRINGS ON ENGLISH_ATOM_STRINGS.COMPANY = :P_COMPANY AND ENGLISH_ATOM_STRINGS.LANGUAGE = 1 AND ENGLISH_ATOM_STRINGS.ID = ATOMS.ID
  LEFT JOIN ATOM_STRINGS OTHER_ATOM_STRINGS ON OTHER_ATOM_STRINGS.COMPANY = :P_COMPANY AND OTHER_ATOM_STRINGS.LANGUAGE = 2 AND OTHER_ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE REPORTS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE,
       :CODE, :NAME, :ENGLISH_NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT,
       :TEMPLATE_FILE, :ENGLISH_TEMPLATE_FILE, :OTHER_TEMPLATE_FILE_1,
       :TEMPLATE_FILE_NAME, :ENGLISH_TEMPLATE_FILE_NAME, :OTHER_TEMPLATE_FILE_1_NAME,
       :TEMPLATE_FILE_OTHER, :ENGLISH_TEMPLATE_FILE_OTHER, :OTHER_TEMPLATE_FILE_2,
       :TEMPLATE_FILE_OTHER_NAME, :ENGLISH_TEMPLATE_FILE_OTHER_N, :OTHER_TEMPLATE_FILE_2_NAME,
       :REPORT_TYPE, :EXPORT_TYPE, :KEY_FIELD_CODE, :KEY_FIELD_NAME
   DO
      SUSPEND;
END ^

ALTER PROCEDURE REPORT_S_INFO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_IS_TEMPLATE_OTHER DM_BOOL)
RETURNS (REPORT_TYPE DM_REPORT_TYPE,
KEY_FIELD_CODE DM_FIELD_CODE,
KEY_FIELD_NAME DM_FIELD_NAME,
TEMPLATE_FILE DM_FILE_NAME)
AS 
BEGIN
    SELECT REPORT_TYPE, KEY_FIELD_CODE, KEY_FIELD_NAME, IIF(:P_IS_TEMPLATE_OTHER = 0, IIF(LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE IS NULL, VIETNAMESE_REPORT_STRINGS.TEMPLATE_FILE, LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE), IIF(LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE_OTHER IS NULL, VIETNAMESE_REPORT_STRINGS.TEMPLATE_FILE_OTHER, LANGUAGE_REPORT_STRINGS.TEMPLATE_FILE_OTHER))
    FROM REPORTS
    LEFT JOIN REPORT_STRINGS LANGUAGE_REPORT_STRINGS ON LANGUAGE_REPORT_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_REPORT_STRINGS.ID = :P_ID AND LANGUAGE_REPORT_STRINGS.LANGUAGE = :P_LANGUAGE
    JOIN REPORT_STRINGS VIETNAMESE_REPORT_STRINGS ON VIETNAMESE_REPORT_STRINGS.COMPANY = :P_COMPANY AND VIETNAMESE_REPORT_STRINGS.ID = :P_ID AND VIETNAMESE_REPORT_STRINGS.LANGUAGE = 0
    WHERE REPORTS.COMPANY = :P_COMPANY AND REPORTS.ID = :P_ID
    INTO :REPORT_TYPE, :KEY_FIELD_CODE, :KEY_FIELD_NAME, :TEMPLATE_FILE;

    SUSPEND;
END ^

ALTER PROCEDURE REPORT_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_OBJECT_TYPE DM_ID,
P_USER_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
TEAM_NAME DM_NAME)
AS 
BEGIN
    FOR
        SELECT ATOMS.ID, ATOMS.CODE, IIF(LANGUAGE_ATOM_STRINGS.NAME IS NULL, VIETNAMESE_ATOM_STRINGS.NAME, LANGUAGE_ATOM_STRINGS.NAME), IIF(LANGUAGE_TEAM_ATOM_STRINGS.NAME IS NULL, VIETNAMESE_TEAM_ATOM_STRINGS.NAME, LANGUAGE_TEAM_ATOM_STRINGS.NAME)
        FROM REPORTS
        LEFT JOIN REPORT_STRINGS LANGUAGE_REPORT_STRINGS ON LANGUAGE_REPORT_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_REPORT_STRINGS.ID = REPORTS.ID AND LANGUAGE_REPORT_STRINGS.LANGUAGE = :P_LANGUAGE
        JOIN REPORT_STRINGS VIETNAMESE_REPORT_STRINGS ON VIETNAMESE_REPORT_STRINGS.COMPANY = :P_COMPANY AND VIETNAMESE_REPORT_STRINGS.ID = REPORTS.ID AND VIETNAMESE_REPORT_STRINGS.LANGUAGE = 0
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = REPORTS.ID AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.HIDE = 0
        LEFT JOIN ATOM_STRINGS LANGUAGE_ATOM_STRINGS ON LANGUAGE_ATOM_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_ATOM_STRINGS.ID = ATOMS.ID
        JOIN ATOM_STRINGS VIETNAMESE_ATOM_STRINGS ON VIETNAMESE_ATOM_STRINGS.COMPANY = :P_COMPANY AND VIETNAMESE_ATOM_STRINGS.LANGUAGE = 0 AND VIETNAMESE_ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        LEFT JOIN PROTON_STRINGS LANGUAGE_PROTON_STRINGS ON LANGUAGE_PROTON_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_PROTON_STRINGS.ID = ATOMS.ID
        JOIN PROTON_STRINGS VIETNAMESE_PROTON_STRINGS ON VIETNAMESE_PROTON_STRINGS.COMPANY = :P_COMPANY AND VIETNAMESE_PROTON_STRINGS.LANGUAGE = 0 AND VIETNAMESE_PROTON_STRINGS.ID = ATOMS.ID
        LEFT JOIN ATOM_STRINGS LANGUAGE_TEAM_ATOM_STRINGS ON LANGUAGE_TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND LANGUAGE_TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND LANGUAGE_TEAM_ATOM_STRINGS.ID = ATOMS.TEAM
        JOIN ATOM_STRINGS VIETNAMESE_TEAM_ATOM_STRINGS ON VIETNAMESE_TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND VIETNAMESE_TEAM_ATOM_STRINGS.LANGUAGE = 0 AND VIETNAMESE_TEAM_ATOM_STRINGS.ID = ATOMS.TEAM
        WHERE REPORTS.COMPANY = :P_COMPANY AND
        EXISTS
        (
            SELECT GRANTS.ID
            FROM MEMBERSHIPS
            JOIN GRANTS ON GRANTS.COMPANY = :P_COMPANY AND GRANTS.ROLE_ID = MEMBERSHIPS.ROLE_ID AND GRANTS.ATOM = REPORTS.ID
            WHERE MEMBERSHIPS.COMPANY = :P_COMPANY AND MEMBERSHIPS.USER_ACCOUNT = :P_USER_ACCOUNT
        )
        ORDER BY PROTONS.ORDINAL
        INTO :ID, :CODE, :NAME, :TEAM_NAME
    DO
        SUSPEND;
END ^

ALTER PROCEDURE REPORT_S_RS_BY_REPORT_TYPE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_OBJECT_TYPE DM_ID,
P_REPORT_TYPE DM_REPORT_TYPE)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME)
AS 
BEGIN
    FOR
        SELECT ATOMS.ID, ATOMS.CODE, ATOM_STRINGS.NAME
        FROM REPORTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = REPORTS.ID AND ATOMS.OBJECT_TYPE = :P_OBJECT_TYPE AND ATOMS.HIDE = 0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        WHERE REPORTS.COMPANY = :P_COMPANY AND REPORT_TYPE = :P_REPORT_TYPE
        INTO :ID, :CODE, :NAME
    DO
        SUSPEND;
END ^

