ALTER PROCEDURE RPT_BANG_CAN_DOI_TAI_KHOAN_C2 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE1 DM_CODE,
CODE2 DM_CODE,
NAME DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
SUM_BEGINNING_DEBIT DM_DOUBLE,
SUM_BEGINNING_CREDIT DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
SUM_ENDING_DEBIT DM_DOUBLE,
SUM_ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE CAP DM_SMALLINT;
DECLARE VARIABLE CODE DM_CODE;
BEGIN
    SUM_BEGINNING_DEBIT = 0;
    SUM_BEGINNING_CREDIT = 0;
    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;
    SUM_ENDING_DEBIT = 0;
    SUM_ENDING_CREDIT = 0;

    FOR
        SELECT CODE, NAME, BEGINNING_DEBIT, BEGINNING_CREDIT, RISING_DEBIT, RISING_CREDIT, ENDING_DEBIT, ENDING_CREDIT, CAP
        FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 0)
        WHERE RPT_BANG_CAN_DOI_TAI_KHOAN.CAP <= 2 AND RPT_BANG_CAN_DOI_TAI_KHOAN.IS_ACCOUNT = 1 AND
        (BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)
        ORDER BY CODE
        INTO :CODE, :NAME, :BEGINNING_DEBIT, :BEGINNING_CREDIT, :RISING_DEBIT, :RISING_CREDIT, :ENDING_DEBIT, :ENDING_CREDIT, :CAP
    DO
    BEGIN
        IF(CAP = 1)THEN
        BEGIN
            CODE1 = CODE;
            CODE2 = NULL;

            SUM_BEGINNING_DEBIT = SUM_BEGINNING_DEBIT + BEGINNING_DEBIT;
            SUM_BEGINNING_CREDIT = SUM_BEGINNING_CREDIT + BEGINNING_CREDIT;
            SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
            SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            SUM_ENDING_DEBIT = SUM_ENDING_DEBIT + ENDING_DEBIT;
            SUM_ENDING_CREDIT = SUM_ENDING_CREDIT + ENDING_CREDIT;
        END
        ELSE IF(CAP = 2)THEN
        BEGIN
            CODE1 = NULL;
            CODE2 = CODE;
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BANG_CAN_DOI_TAI_KHOAN_C2K (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
