BEGIN
    SUM_BEGINNING_DEBIT = 0;
    SUM_BEGINNING_CREDIT = 0;
    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;
    SUM_RISING_OF_YEAR_DEBIT = 0;
    SUM_RISING_OF_YEAR_CREDIT = 0;
    SUM_ENDING_DEBIT = 0;
    SUM_ENDING_CREDIT = 0;

    NGAY_DAU_NAM = '01.01.' || EXTRACT(YEAR FROM P_TU_NGAY);

    FOR
        SELECT CODE, NAME, BEGINNING_DEBIT, BEGINNING_CREDIT, RISING_DEBIT, RISING_CREDIT, ENDING_DEBIT, ENDING_CREDIT, CAP
        FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 1)
        WHERE RPT_BANG_CAN_DOI_TAI_KHOAN.CAP <= 2 AND RPT_BANG_CAN_DOI_TAI_KHOAN.IS_ACCOUNT = 1
        ORDER BY CODE
        INTO :CODE, :NAME, :BEGINNING_DEBIT, :BEGINNING_CREDIT, :RISING_DEBIT, :RISING_CREDIT, :ENDING_DEBIT, :ENDING_CREDIT, :CAP
    DO
    BEGIN
        SELECT DEBIT, CREDIT
        FROM INT_PS_1_TK_C(:P_COMPANY, :CODE, :NGAY_DAU_NAM, :P_DEN_NGAY)
        INTO :RISING_OF_YEAR_DEBIT, :RISING_OF_YEAR_CREDIT;

        IF(CAP = 1)THEN
        BEGIN
            CODE1 = CODE;
            CODE2 = NULL;

            SUM_BEGINNING_DEBIT = SUM_BEGINNING_DEBIT + BEGINNING_DEBIT;
            SUM_BEGINNING_CREDIT = SUM_BEGINNING_CREDIT + BEGINNING_CREDIT;
            SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
            SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            SUM_RISING_OF_YEAR_DEBIT = SUM_RISING_OF_YEAR_DEBIT + RISING_OF_YEAR_DEBIT;
            SUM_RISING_OF_YEAR_CREDIT = SUM_RISING_OF_YEAR_CREDIT + RISING_OF_YEAR_CREDIT;
            SUM_ENDING_DEBIT = SUM_ENDING_DEBIT + ENDING_DEBIT;
            SUM_ENDING_CREDIT = SUM_ENDING_CREDIT + ENDING_CREDIT;
        END
        ELSE IF(CAP = 2)THEN
        BEGIN
            CODE1 = NULL;
            CODE2 = CODE;
        END

        IF(
            BEGINNING_DEBIT <> 0 OR
            BEGINNING_CREDIT <> 0 OR
            RISING_DEBIT <> 0 OR
            RISING_CREDIT <> 0 OR
            RISING_OF_YEAR_DEBIT <> 0 OR
            RISING_OF_YEAR_CREDIT <> 0 OR
            ENDING_DEBIT <> 0 OR
            ENDING_CREDIT  <> 0
        )THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BANG_CAN_DOI_TAI_KHOAN_CON (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ID DM_INTEGER;
DECLARE VARIABLE PREV_PARENT_ID DM_SMALLINT;
DECLARE VARIABLE PREV_CODE DM_CODE;
DECLARE VARIABLE PREV_NAME DM_NAME;
DECLARE VARIABLE PREV_BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PREV_RISING_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_RISING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PREV_ENDING_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_ENDING_CREDIT DM_DOUBLE;
BEGIN
    PREV_PARENT_ID = 0;

    FOR
        SELECT PARENT_ID, CODE, NAME, BEGINNING_DEBIT, BEGINNING_CREDIT, RISING_DEBIT, RISING_CREDIT, ENDING_DEBIT, ENDING_CREDIT
        FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 0)
        WHERE IS_ACCOUNT = 1
        ORDER BY VIRTUAL_ID
        INTO :PARENT_ID, :PREV_CODE, :PREV_NAME, :PREV_BEGINNING_DEBIT, :PREV_BEGINNING_CREDIT, :PREV_RISING_DEBIT, :PREV_RISING_CREDIT, :PREV_ENDING_DEBIT, :PREV_ENDING_CREDIT
    DO
    BEGIN
        IF(PREV_PARENT_ID IS NULL AND PARENT_ID IS NULL)THEN
        BEGIN
            IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
                SUSPEND;
        END
        ELSE IF(PREV_PARENT_ID IS NOT NULL AND PARENT_ID IS NULL)THEN
        BEGIN
            IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
                SUSPEND;
        END
        ELSE IF(PARENT_ID < PREV_PARENT_ID)THEN
        BEGIN
            IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
                SUSPEND;
        END
        ELSE IF(PARENT_ID = PREV_PARENT_ID)THEN
        BEGIN
            IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
                SUSPEND;
        END

        PREV_PARENT_ID = PARENT_ID;

        CODE = PREV_CODE;
        NAME = PREV_NAME;
        BEGINNING_DEBIT = PREV_BEGINNING_DEBIT;
        BEGINNING_CREDIT = PREV_BEGINNING_CREDIT;
        RISING_DEBIT = PREV_RISING_DEBIT;
        RISING_CREDIT = PREV_RISING_CREDIT;
        ENDING_DEBIT = PREV_ENDING_DEBIT;
        ENDING_CREDIT = PREV_ENDING_CREDIT;
    END

    IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
        SUSPEND;
END ^

ALTER PROCEDURE RPT_BANG_CAN_DOI_TAI_KHOAN_CONK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
RISING_OF_YEAR_DEBIT DM_DOUBLE,
RISING_OF_YEAR_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE NGAY_DAU_NAM DM_DATE;
DECLARE VARIABLE PARENT_ID DM_INTEGER;
DECLARE VARIABLE PREV_PARENT_ID DM_SMALLINT;
DECLARE VARIABLE PREV_CODE DM_CODE;
DECLARE VARIABLE PREV_NAME DM_NAME;
DECLARE VARIABLE PREV_BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PREV_RISING_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_RISING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PREV_RISING_OF_YEAR_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_RISING_OF_YEAR_CREDIT DM_DOUBLE;
DECLARE VARIABLE PREV_ENDING_DEBIT DM_DOUBLE;
DECLARE VARIABLE PREV_ENDING_CREDIT DM_DOUBLE;
BEGIN
    NGAY_DAU_NAM = '01.01.' || EXTRACT(YEAR FROM P_TU_NGAY);
    PREV_PARENT_ID = 0;

    FOR
        SELECT PARENT_ID, CODE, NAME, BEGINNING_DEBIT, BEGINNING_CREDIT, RISING_DEBIT, RISING_CREDIT, ENDING_DEBIT, ENDING_CREDIT
        FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 1)
        WHERE IS_ACCOUNT = 1
        ORDER BY VIRTUAL_ID
        INTO :PARENT_ID, :PREV_CODE, :PREV_NAME, :PREV_BEGINNING_DEBIT, :PREV_BEGINNING_CREDIT, :PREV_RISING_DEBIT, :PREV_RISING_CREDIT, :PREV_ENDING_DEBIT, :PREV_ENDING_CREDIT
    DO
    BEGIN
        SELECT DEBIT, CREDIT
        FROM INT_PS_1_TK_C(:P_COMPANY, :PREV_CODE, :NGAY_DAU_NAM, :P_DEN_NGAY)
        INTO :PREV_RISING_OF_YEAR_DEBIT, :PREV_RISING_OF_YEAR_CREDIT;

        IF(PREV_PARENT_ID IS NULL AND PARENT_ID IS NULL)THEN
        BEGIN
            IF(
                BEGINNING_DEBIT <> 0 OR
                BEGINNING_CREDIT <> 0 OR
                RISING_DEBIT <> 0 OR
                RISING_CREDIT <> 0 OR
                RISING_OF_YEAR_DEBIT <> 0 OR
                RISING_OF_YEAR_CREDIT <> 0 OR
                ENDING_DEBIT <> 0 OR
                ENDING_CREDIT  <> 0
            )THEN
                SUSPEND;
        END
        ELSE IF(PREV_PARENT_ID IS NOT NULL AND PARENT_ID IS NULL)THEN
        BEGIN
            IF(
                BEGINNING_DEBIT <> 0 OR
                BEGINNING_CREDIT <> 0 OR
                RISING_DEBIT <> 0 OR
                RISING_CREDIT <> 0 OR
                RISING_OF_YEAR_DEBIT <> 0 OR
                RISING_OF_YEAR_CREDIT <> 0 OR
                ENDING_DEBIT <> 0 OR
                ENDING_CREDIT  <> 0
            )THEN
                SUSPEND;
        END
        ELSE IF(PARENT_ID < PREV_PARENT_ID)THEN
        BEGIN
            IF(
                BEGINNING_DEBIT <> 0 OR
                BEGINNING_CREDIT <> 0 OR
                RISING_DEBIT <> 0 OR
                RISING_CREDIT <> 0 OR
                RISING_OF_YEAR_DEBIT <> 0 OR
                RISING_OF_YEAR_CREDIT <> 0 OR
                ENDING_DEBIT <> 0 OR
                ENDING_CREDIT  <> 0
            )THEN
                SUSPEND;
        END
        ELSE IF(PARENT_ID = PREV_PARENT_ID)THEN
        BEGIN
            IF(
                BEGINNING_DEBIT <> 0 OR
                BEGINNING_CREDIT <> 0 OR
                RISING_DEBIT <> 0 OR
                RISING_CREDIT <> 0 OR
                RISING_OF_YEAR_DEBIT <> 0 OR
                RISING_OF_YEAR_CREDIT <> 0 OR
                ENDING_DEBIT <> 0 OR
                ENDING_CREDIT  <> 0
            )THEN
                SUSPEND;
        END

        PREV_PARENT_ID = PARENT_ID;

        CODE = PREV_CODE;
        NAME = PREV_NAME;
        BEGINNING_DEBIT = PREV_BEGINNING_DEBIT;
        BEGINNING_CREDIT = PREV_BEGINNING_CREDIT;
        RISING_DEBIT = PREV_RISING_DEBIT;
        RISING_CREDIT = PREV_RISING_CREDIT;
        RISING_OF_YEAR_DEBIT = PREV_RISING_OF_YEAR_DEBIT;
        RISING_OF_YEAR_CREDIT = PREV_RISING_OF_YEAR_CREDIT;
        ENDING_DEBIT = PREV_ENDING_DEBIT;
        ENDING_CREDIT = PREV_ENDING_CREDIT;
    END

    IF(
        BEGINNING_DEBIT <> 0 OR
        BEGINNING_CREDIT <> 0 OR
        RISING_DEBIT <> 0 OR
        RISING_CREDIT <> 0 OR
        RISING_OF_YEAR_DEBIT <> 0 OR
        RISING_OF_YEAR_CREDIT <> 0 OR
        ENDING_DEBIT <> 0 OR
        ENDING_CREDIT  <> 0
    )THEN
        SUSPEND;
END ^

ALTER PROCEDURE RPT_BANG_KE_CHI_TIET_CAP_TK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_DEBITACCOUNT DM_ID,
P_DEBIT_OBJECT0 DM_ID,
P_DEBIT_OBJECT1 DM_ID,
P_CREDITACCOUNT DM_ID,
P_CREDIT_OBJECT0 DM_ID,
P_CREDIT_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
CREDIT_ACCOUNT_CODE DM_CODE,
RISING DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT_CONTENT DM_CONTENT;
DECLARE VARIABLE PARENT_DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PARENT_CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_DEBITACCOUNT
    INTO :PARENT_DEBIT_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDITACCOUNT
    INTO :PARENT_CREDIT_ACCOUNT_CODE;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND
            (:P_DEBIT_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_DEBIT_OBJECT0) AND (:P_DEBIT_OBJECT1 IS NULL OR DEBIT.OBJECT1 = :P_DEBIT_OBJECT1)
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_DEBIT_ACCOUNT_CODE
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND
            (:P_CREDIT_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_CREDIT_OBJECT0) AND (:P_CREDIT_OBJECT1 IS NULL OR CREDIT.OBJECT1 = :P_CREDIT_OBJECT1)
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_CREDIT_ACCOUNT_CODE
        WHERE ENTRIES.COMPANY = :P_COMPANY
        GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
        DEBIT_ATOM.CODE,
        CREDIT_ATOM.CODE
        ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT, :RISING,
        :DEBIT_ACCOUNT_CODE,
        :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
        HAS_VALUE = 1;
        SUSPEND;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

