ALTER PROCEDURE RPT_BANG_KE_CHI_TIET_TK_1_BEN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_SIDE_TYPE DM_SIDE,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
RISING DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT_CONTENT DM_CONTENT;
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE HAS_AMOUNT DM_BOOL;
DECLARE VARIABLE ATOM_TYPE_0 DM_ID;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT ACCOUNTS.ATOM_TYPE_0
    FROM ACCOUNTS
    WHERE ACCOUNTS.ID = :P_ACCOUNT AND ACCOUNTS.COMPANY = :P_COMPANY
    INTO :ATOM_TYPE_0;

    IF(ATOM_TYPE_0 = 54)THEN
        HAS_AMOUNT = 1;
    ELSE
        HAS_AMOUNT = 0;

    
    IF(P_SIDE_TYPE = 0)THEN
    BEGIN
        IF(HAS_AMOUNT = 1)THEN
        BEGIN
            FOR
                SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
                DEBIT.AMOUNT,
                DEBIT.OFFICIAL_SUM_OF_MONEY,
                CREDIT_ATOM.CODE
                FROM ENTRIES
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
                JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
                JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
                LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
                LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
                LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
                WHERE ENTRIES.COMPANY = :P_COMPANY
                ORDER BY INPUT_DATE, ENTRIES.ID
                INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT,
                :AMOUNT, :RISING,
                :ACCOUNT_CODE
            DO
            BEGIN
                IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
    
                IF(AMOUNT > 0)THEN
                BEGIN
                    PRICE = ROUND(RISING/AMOUNT, 2);
                END
                ELSE
                BEGIN
                    AMOUNT = NULL;
                    PRICE = NULL;
                END
    
                HAS_VALUE = 1;
                SUSPEND;
            END
        END
        ELSE
        BEGIN
            AMOUNT = NULL;
            PRICE = NULL;

            FOR
                SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
                SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
                CREDIT_ATOM.CODE
                FROM ENTRIES
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
                JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
                JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
                JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
                LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
                LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
                LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
                WHERE ENTRIES.COMPANY = :P_COMPANY
                GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
                CREDIT_ATOM.CODE
                ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
                INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT,
                :RISING,
                :ACCOUNT_CODE
            DO
            BEGIN
                IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
    
                HAS_VALUE = 1;
                SUSPEND;
            END
        END
    END
    ELSE
    BEGIN
        IF(HAS_AMOUNT = 1)THEN
        BEGIN
            FOR
                SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
                DEBIT.AMOUNT,
                DEBIT.OFFICIAL_SUM_OF_MONEY,
                DEBIT_ATOM.CODE
                FROM ENTRIES
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
                LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
                LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
                LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
                JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
                JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
                WHERE ENTRIES.COMPANY = :P_COMPANY
                ORDER BY INPUT_DATE, ENTRIES.ID
                INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT,
                :AMOUNT, :RISING,
                :ACCOUNT_CODE
            DO
            BEGIN
                IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
    
                IF(AMOUNT > 0)THEN
                BEGIN
                    PRICE = ROUND(RISING/AMOUNT, 2);
                END
                ELSE
                BEGIN
                    AMOUNT = NULL;
                    PRICE = NULL;
                END
    
                HAS_VALUE = 1;
                SUSPEND;
            END
        END
        ELSE
        BEGIN
            AMOUNT = NULL;
            PRICE = NULL;

            FOR
                SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
                SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
                DEBIT_ATOM.CODE
                FROM ENTRIES
                JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
                JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
                LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
                LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
                LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
                JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
                JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
                JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
                WHERE ENTRIES.COMPANY = :P_COMPANY
                GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
                DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
                ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
                INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT,
                :RISING,
                :ACCOUNT_CODE
            DO
            BEGIN
                IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
    
                HAS_VALUE = 1;
                SUSPEND;
            END
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BANG_KE_CHI_TIET_TK_1_BEN_1 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_SIDE_TYPE DM_SIDE,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
OBJECT0 DM_NAME,
AMOUNT DM_DOUBLE,
RISING DM_DOUBLE)
AS 
declare variable document_content dm_content;
declare variable parent_account_code dm_code;
declare variable has_value dm_bool;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    
    IF(P_SIDE_TYPE = 0)THEN
    BEGIN
        FOR
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
            CREDIT_ATOM.CODE, object0.code || '-' || object0_STRINGS.name,
            sum(DEBIT.amount)
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND DEBIT.OBJECT0 = :P_OBJECT0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID

            LEFT JOIN ATOMS object0 ON object0.company = :P_COMPANY AND object0.id = CREDIT.object0
            LEFT JOIN ATOM_STRINGS object0_STRINGS ON object0_STRINGS.company = :P_COMPANY AND object0_STRINGS.id = CREDIT.object0 AND object0_STRINGS.language =  :P_LANGUAGE

            WHERE ENTRIES.COMPANY = :P_COMPANY
            GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT, CREDIT_ATOM.CODE,
                object0.code,
                object0_STRINGS.name
            ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT, :RISING,
            :ACCOUNT_CODE, :object0 ,
            :amount
        DO
        BEGIN
            IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
            HAS_VALUE = 1;
            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
            DEBIT_ATOM.CODE, object0.code || '-' || object0_STRINGS.name,
            sum(credit.amount)
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.OBJECT0 = :P_OBJECT0
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE

            LEFT JOIN ATOMS object0 ON object0.company = :P_COMPANY AND object0.id = DEBIT.object0
            LEFT JOIN ATOM_STRINGS object0_STRINGS ON object0_STRINGS.company = :P_COMPANY AND object0_STRINGS.id = DEBIT.object0 AND object0_STRINGS.language =  :P_LANGUAGE

            WHERE ENTRIES.COMPANY = :P_COMPANY
            GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,DEBIT_ATOM.CODE,
                object0.code,
                object0_STRINGS.name
            ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT, :RISING,
            :ACCOUNT_CODE, :object0,
            :amount
        DO
        BEGIN
            IF(CONTENT IS NULL OR CONTENT='')THEN CONTENT = DOCUMENT_CONTENT;
            HAS_VALUE = 1;
            SUSPEND;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BANG_KE_DOANH_SO_BAN_1_KH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_DEBIT_ACCOUNT DM_ID,
P_DEBIT_OBJECT0 DM_ID,
P_CREDIT_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CREDIT_OBJECT0_CODE DM_CODE,
CREDIT_OBJECT0_NAME DM_NAME,
UNIT DM_UNIT,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_VAT DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PARENT_CREDIT_ACCOUNT_CODE DM_CODE;
BEGIN

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_DEBIT_ACCOUNT
    INTO :PARENT_DEBIT_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDIT_ACCOUNT
    INTO :PARENT_CREDIT_ACCOUNT_CODE;

    FOR
        SELECT CODE, NAME, UNIT, SUM(AMOUNT), SUM(OFFICIAL_SUM_OF_MONEY), SUM(SUM_OF_VAT)
        FROM
        (
            SELECT DEBIT.AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY, ROUND(IIF(ENTRIES.VAT_PERCENT IS NULL, 0, ENTRIES.VAT_PERCENT)*DEBIT.OFFICIAL_SUM_OF_MONEY, 0) AS SUM_OF_VAT,
            CREDIT_OBJECT0.CODE, ATOM_STRINGS_CREDIT_OBJECT0.NAME, GOODS_STRINGS.UNIT
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND DEBIT.OBJECT0 = :P_DEBIT_OBJECT0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_DEBIT_ACCOUNT_CODE
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_CREDIT_ACCOUNT_CODE
            LEFT JOIN ATOMS CREDIT_OBJECT0 ON CREDIT_OBJECT0.COMPANY = :P_COMPANY AND CREDIT_OBJECT0.ID = CREDIT.OBJECT0
            LEFT JOIN ATOM_STRINGS ATOM_STRINGS_CREDIT_OBJECT0 ON ATOM_STRINGS_CREDIT_OBJECT0.COMPANY = :P_COMPANY AND ATOM_STRINGS_CREDIT_OBJECT0.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS_CREDIT_OBJECT0.ID = CREDIT_OBJECT0.ID
            LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = CREDIT_OBJECT0.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY
        )A
        GROUP BY CODE, NAME, UNIT
        ORDER BY CODE, NAME
        INTO :CREDIT_OBJECT0_CODE, :CREDIT_OBJECT0_NAME, :UNIT, :AMOUNT, :SUM_OF_MONEY, :SUM_OF_VAT
    DO
    BEGIN
        SUM_ALL = SUM_OF_MONEY + SUM_OF_VAT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BANG_KE_DOANH_SO_BAN_KH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_DEBIT_ACCOUNT DM_ID,
