    INTO :PARENT_DEBIT_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDIT_ACCOUNT
    INTO :PARENT_CREDIT_ACCOUNT_CODE;

    FOR
        SELECT DEBIT_OBJECT0_CODE, DEBIT_OBJECT0_NAME, CREDIT_OBJECT0_CODE, CREDIT_OBJECT0_NAME, UNIT, SUM(AMOUNT), SUM(OFFICIAL_SUM_OF_MONEY), SUM(SUM_OF_VAT)
        FROM
        (
            SELECT DEBIT.AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY, ROUND(IIF(ENTRIES.VAT_PERCENT IS NULL, 0, ENTRIES.VAT_PERCENT)*DEBIT.OFFICIAL_SUM_OF_MONEY, 0) AS SUM_OF_VAT,
            DEBIT_OBJECT0.CODE AS DEBIT_OBJECT0_CODE, ATOM_STRINGS_DEBIT_OBJECT0.NAME AS DEBIT_OBJECT0_NAME, CREDIT_OBJECT0.CODE AS CREDIT_OBJECT0_CODE, ATOM_STRINGS_CREDIT_OBJECT0.NAME AS CREDIT_OBJECT0_NAME, GOODS_STRINGS.UNIT
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_DEBIT_ACCOUNT_CODE
            LEFT JOIN ATOMS DEBIT_OBJECT0 ON DEBIT_OBJECT0.COMPANY = :P_COMPANY AND DEBIT_OBJECT0.ID = DEBIT.OBJECT0
            LEFT JOIN ATOM_STRINGS ATOM_STRINGS_DEBIT_OBJECT0 ON ATOM_STRINGS_DEBIT_OBJECT0.COMPANY = :P_COMPANY AND ATOM_STRINGS_DEBIT_OBJECT0.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS_DEBIT_OBJECT0.ID = DEBIT_OBJECT0.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_CREDIT_ACCOUNT_CODE
            LEFT JOIN ATOMS CREDIT_OBJECT0 ON CREDIT_OBJECT0.COMPANY = :P_COMPANY AND CREDIT_OBJECT0.ID = CREDIT.OBJECT0
            LEFT JOIN ATOM_STRINGS ATOM_STRINGS_CREDIT_OBJECT0 ON ATOM_STRINGS_CREDIT_OBJECT0.COMPANY = :P_COMPANY AND ATOM_STRINGS_CREDIT_OBJECT0.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS_CREDIT_OBJECT0.ID = CREDIT_OBJECT0.ID
            LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = CREDIT_OBJECT0.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY
        )A
        GROUP BY DEBIT_OBJECT0_CODE, DEBIT_OBJECT0_NAME, CREDIT_OBJECT0_CODE, CREDIT_OBJECT0_NAME, UNIT
        ORDER BY DEBIT_OBJECT0_CODE, DEBIT_OBJECT0_NAME, CREDIT_OBJECT0_CODE, CREDIT_OBJECT0_NAME
        INTO :DEBIT_OBJECT0_CODE, :DEBIT_OBJECT0_NAME, :CREDIT_OBJECT0_CODE, :CREDIT_OBJECT0_NAME, :UNIT, :AMOUNT, :SUM_OF_MONEY, :SUM_OF_VAT
    DO
    BEGIN
        SUM_ALL = SUM_OF_MONEY + SUM_OF_VAT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BANG_KE_HD_GTGT_BR_119_0 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
COMPANY DM_ID,
DOCUMENT DM_ID,
INPUT_DATE DM_DATE,
INVOICE_DATE DM_DATE,
SERIAL_CODE DM_SERIAL_CODE,
INVOICE_CODE DM_INVOICE_CODE,
CUSTOMER DM_ID,
CUSTOMER_TAX_CODE DM_TAX_CODE,
VAT_PERCENT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
CUSTOMER_NAME DM_NAME,
CUSTOMER_ADDRESS DM_ADDRESS,
GOODS DM_NAME,
INVOICE_TEMPLATE DM_INVOICE_TEMPLATE,
CODE_TEMPLATE DM_INVOICE_TEMPLATE,
DOCUMENT_CODE DM_DOCUMENT_CODE,
DOCUMENT_INPUT_DATE DM_DATE,
DOCUMENT_SUM_OF_MONEY DM_DOUBLE,
DOCUMENT_SUM_OF_TAX DM_DOUBLE)
AS 
DECLARE VARIABLE OUTPUT_INVOICE_SORT_OPTION DM_OUTPUT_INVOICE_SORT_OPTION;
DECLARE VARIABLE INVOICE_TYPE DM_INVOICE_TYPE;
begin
    INVOICE_TYPE = 5;

    SELECT OUTPUT_INVOICE_SORT_OPTION
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO OUTPUT_INVOICE_SORT_OPTION;

    IF(OUTPUT_INVOICE_SORT_OPTION = 0)THEN
    BEGIN
        FOR
            SELECT INVOICES.ID, NOTE, ORDINAL, INVOICES.COMPANY, DOCUMENT, INPUT_DATE, INVOICE_DATE, SERIAL_CODE, INVOICE_CODE,
                CUSTOMER, CUSTOMER_NAME, CUSTOMER_ADDRESS, CUSTOMER_TAX_CODE, VAT_PERCENT, SUM_OF_MONEY, SUM_OF_TAX, GOODS, INVOICES.INVOICE_TEMPLATE, CODE_TEMPLATE
            FROM INVOICES
            JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
            WHERE INVOICES.COMPANY = :P_COMPANY AND
                  INVOICE_TYPE = :INVOICE_TYPE AND
                  VAT_PERCENT = 0 AND
                  INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            ORDER BY INVOICE_DATE, SERIAL_CODE, INVOICE_CODE
            INTO :ID, :NOTE, :ORDINAL, :COMPANY, :DOCUMENT, :INPUT_DATE, :INVOICE_DATE, :SERIAL_CODE, :INVOICE_CODE,
                :CUSTOMER, :CUSTOMER_NAME, :CUSTOMER_ADDRESS, :CUSTOMER_TAX_CODE, :VAT_PERCENT, :SUM_OF_MONEY, :SUM_OF_TAX, :GOODS, :INVOICE_TEMPLATE, :CODE_TEMPLATE
        DO
        BEGIN
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE
            FROM DOCUMENTS
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :DOCUMENT
            INTO :DOCUMENT_CODE, :DOCUMENT_INPUT_DATE;

            SELECT SUM_OF_MONEY, SUM_OF_TAX
            FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :DOCUMENT)
            INTO :DOCUMENT_SUM_OF_MONEY, :DOCUMENT_SUM_OF_TAX;

            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT INVOICES.ID, NOTE, ORDINAL, INVOICES.COMPANY, DOCUMENT, INPUT_DATE, INVOICE_DATE, SERIAL_CODE, INVOICE_CODE,
                CUSTOMER, CUSTOMER_NAME, CUSTOMER_ADDRESS, CUSTOMER_TAX_CODE, VAT_PERCENT, SUM_OF_MONEY, SUM_OF_TAX, GOODS, INVOICES.INVOICE_TEMPLATE
            FROM INVOICES
            JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
            WHERE INVOICES.COMPANY = :P_COMPANY AND
                  INVOICE_TYPE = :INVOICE_TYPE AND
