ALTER PROCEDURE RPT_BANG_KE_HD_GTGT_BR_119_TC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SUM_OF_MONEY DM_DOUBLE,
SUM_OF_MONEY_TAX DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE)
AS 
DECLARE VARIABLE INVOICE_TYPE DM_INVOICE_TYPE;
begin
    INVOICE_TYPE = 5;

    SELECT SUM(SUM_OF_MONEY)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND
    INVOICE_TYPE = :INVOICE_TYPE AND
    INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    INTO :SUM_OF_MONEY;

    IF(SUM_OF_MONEY IS NULL) THEN SUM_OF_MONEY = 0;

    SELECT SUM(SUM_OF_MONEY), SUM(SUM_OF_TAX)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND
    INVOICE_TYPE = :INVOICE_TYPE AND
    VAT_PERCENT IS NOT NULL AND
    INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    INTO :SUM_OF_MONEY_TAX, :SUM_OF_TAX;

    IF(SUM_OF_MONEY_TAX IS NULL) THEN SUM_OF_MONEY_TAX = 0;
    IF(SUM_OF_TAX IS NULL) THEN SUM_OF_TAX = 0;

    SUSPEND;
end ^

