    INTO :SUM_OF_MONEY, :SUM_OF_TAX;

    IF(SUM_OF_MONEY IS NULL) THEN SUM_OF_MONEY = 0;
    IF(SUM_OF_TAX IS NULL) THEN SUM_OF_TAX = 0;

    SUSPEND;
end ^

