ALTER PROCEDURE RPT_BANG_KE_HD_GTGT_MV_28_TC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE)
AS 
begin
    SELECT SUM(SUM_OF_MONEY), SUM(SUM_OF_TAX)
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND
    (INVOICE_TYPE = 7 OR INVOICE_TYPE = 8 OR INVOICE_TYPE = 9 OR INVOICE_TYPE = 10) AND
    INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
    INTO :SUM_OF_MONEY, :SUM_OF_TAX;

    IF(SUM_OF_MONEY IS NULL) THEN SUM_OF_MONEY = 0;
    IF(SUM_OF_TAX IS NULL) THEN SUM_OF_TAX = 0;

    SUSPEND;
end ^

ALTER PROCEDURE RPT_BANG_KE_HD_GTGT_THIEU_HD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
CONTENT DM_CONTENT,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.NOTE, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE, DOCUMENT_BASE_STRINGS.CONTENT
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        WHERE DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY AND
            NOT EXISTS
            (
                SELECT 1
                FROM INVOICES
                WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = DOCUMENTS.ID
            )
        INTO :ID, :NOTE, :CODE, :INPUT_DATE, :CONTENT
    DO
    BEGIN
        SELECT SUM_OF_MONEY, SUM_OF_TAX
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :ID)
        INTO :SUM_OF_MONEY, :SUM_OF_TAX;

        IF(SUM_OF_TAX <> 0)THEN
            SUSPEND;
    END
END ^

