ALTER PROCEDURE RPT_BANG_KE_MUA_VAO_KHONG_HD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GROUPID DM_INTEGER,
INPUT_DATE DM_DATE,
PERSON_NAME DM_NAME,
PERSON_ADDRESS DM_ADDRESS,
PERSON_INFO DM_ADDITION_INFO,
GOODS DM_NAME,
UNIT DM_UNIT,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
DECLARE VARIABLE PREV_INPUT_DATE DM_DATE;
DECLARE VARIABLE PREV_PERSON_NAME DM_NAME;
DECLARE VARIABLE PREV_PERSON_ADDRESS DM_ADDRESS;
DECLARE VARIABLE PREV_PERSON_INFO DM_ADDITION_INFO;
BEGIN
    GROUPID = 0;

    FOR
        SELECT INPUT_DATE, PERSON_NAME, PERSON_ADDRESS, PERSON_INFO,
            GOODS, UNIT, AMOUNT, PRICE, SUM_OF_MONEY, SUM_ALL
        FROM INT_BANG_KE_MUA_VAO_KHONG_HD(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_TU_NGAY, :P_DEN_NGAY)
        ORDER BY INPUT_DATE, PERSON_NAME, PERSON_ADDRESS, PERSON_INFO
        INTO :INPUT_DATE, :PERSON_NAME, :PERSON_ADDRESS, :PERSON_INFO,
            :GOODS, :UNIT, :AMOUNT, :PRICE, :SUM_OF_MONEY, :SUM_ALL
    DO
    BEGIN
        IF(GROUPID = 0)THEN
        BEGIN
            PREV_INPUT_DATE = INPUT_DATE;
            PREV_PERSON_NAME = PERSON_NAME;
            PREV_PERSON_ADDRESS = PERSON_ADDRESS;
            PREV_PERSON_INFO = PERSON_INFO;

            GROUPID = GROUPID + 1;
        END
        ELSE IF(
            (
                (PREV_INPUT_DATE IS NULL AND INPUT_DATE IS NOT NULL) OR
                (PREV_INPUT_DATE <> INPUT_DATE) OR
                (PREV_INPUT_DATE IS NOT NULL AND INPUT_DATE IS NULL)
            )
            OR
            (
                (PREV_PERSON_NAME IS NULL AND PERSON_NAME IS NOT NULL) OR
                (PREV_PERSON_NAME <> PERSON_NAME) OR
                (PREV_PERSON_NAME IS NOT NULL AND PERSON_NAME IS NULL)
            )
            OR
            (
                (PREV_PERSON_ADDRESS IS NULL AND PERSON_ADDRESS IS NOT NULL) OR
                (PREV_PERSON_ADDRESS <> PERSON_ADDRESS) OR
                (PREV_PERSON_ADDRESS IS NOT NULL AND PERSON_ADDRESS IS NULL)
            )
            OR
            (
                (PREV_PERSON_INFO IS NULL AND PERSON_INFO IS NOT NULL) OR
                (PREV_PERSON_INFO <> PERSON_INFO) OR
                (PREV_PERSON_INFO IS NOT NULL AND PERSON_INFO IS NULL)
            )
        )THEN
        BEGIN
            PREV_INPUT_DATE = INPUT_DATE;
            PREV_PERSON_NAME = PERSON_NAME;
            PREV_PERSON_ADDRESS = PERSON_ADDRESS;
            PREV_PERSON_INFO = PERSON_INFO;

            GROUPID = GROUPID + 1;
        END
        ELSE
        BEGIN
            INPUT_DATE = NULL;
            PERSON_NAME = NULL;
            PERSON_ADDRESS = NULL;
            PERSON_INFO = NULL;
        END

        SUSPEND;
    END
END ^

