INPUT_PRICE DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_PRICE DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_PRICE DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    FOR
        SELECT CODE, NAME, UNIT, SUM(BEGINNING_AMOUNT), SUM(BEGINNING_SUM_OF_MONEY), SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT GOODS, AMOUNT BEGINNING_AMOUNT, SUM_OF_MONEY BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM INT_SD_VT_DN(:P_COMPANY, 54, :P_TU_NGAY)

            UNION ALL

            SELECT GOODS, 0 BEGINNING_AMOUNT, 0 BEGINNING_SUM_OF_MONEY, INPUT_AMOUNT INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
            FROM INT_PS_VT(:P_COMPANY, 54, :P_TU_NGAY, :P_DEN_NGAY)
        ) RESULTS
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = RESULTS.GOODS
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = RESULTS.GOODS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = RESULTS.GOODS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = RESULTS.GOODS
        GROUP BY GOODS, CODE, NAME, UNIT
        ORDER BY CODE, NAME
        INTO :CODE, :NAME, :UNIT, :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        ENDING_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(BEGINNING_AMOUNT <> 0 OR BEGINNING_SUM_OF_MONEY <> 0 OR INPUT_AMOUNT <> 0 OR INPUT_SUM_OF_MONEY <> 0 OR OUTPUT_AMOUNT <> 0 OR OUTPUT_SUM_OF_MONEY <> 0 OR ENDING_AMOUNT <> 0 OR ENDING_SUM_OF_MONEY <> 0)THEN
        BEGIN
            IF(ROUND(BEGINNING_AMOUNT, 5) <> 0)THEN
                BEGINNING_PRICE = ROUND(BEGINNING_SUM_OF_MONEY/BEGINNING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                BEGINNING_PRICE = NULL;

            IF(ROUND(INPUT_AMOUNT, 5) <> 0)THEN
                INPUT_PRICE = ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                INPUT_PRICE = NULL;

            IF(ROUND(OUTPUT_AMOUNT, 5) <> 0)THEN
                OUTPUT_PRICE = ROUND(OUTPUT_SUM_OF_MONEY/OUTPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                OUTPUT_PRICE = NULL;

            IF(ROUND(ENDING_AMOUNT, 5) <> 0)THEN
                ENDING_PRICE = ROUND(ENDING_SUM_OF_MONEY/ENDING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                ENDING_PRICE = NULL;

            IF(BEGINNING_AMOUNT = 0)THEN BEGINNING_AMOUNT = NULL;
            IF(INPUT_AMOUNT = 0)THEN INPUT_AMOUNT = NULL;
            IF(OUTPUT_AMOUNT = 0)THEN OUTPUT_AMOUNT = NULL;
            IF(ENDING_AMOUNT = 0)THEN ENDING_AMOUNT = NULL;

            SUSPEND;
        END
    END
END ^

