ALTER PROCEDURE RPT_BANG_KE_NXT_1_TK_KHO_NHOM (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_WAREHOUSE DM_ID,
P_TEAM DM_ID)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
UNIT DM_UNIT,
WAREHOUSE_CODE DM_CODE,
WAREHOUSE_NAME DM_NAME,
TEAM_CODE DM_CODE,
TEAM_NAME DM_NAME,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
BEGINNING_PRICE DM_DOUBLE,
INPUT_PRICE DM_DOUBLE,
OUTPUT_PRICE DM_DOUBLE,
ENDING_PRICE DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME,
            SUM(BEGINNING_AMOUNT), SUM(BEGINNING_SUM_OF_MONEY), SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT GOODS, WAREHOUSE, AMOUNT BEGINNING_AMOUNT, SUM_OF_MONEY BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM INT_SD_1_TK_VT_KHO_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
            WHERE :P_WAREHOUSE IS NULL OR INT_SD_1_TK_VT_KHO_DN_C.WAREHOUSE = :P_WAREHOUSE

            UNION ALL

            SELECT GOODS, WAREHOUSE, 0 BEGINNING_AMOUNT, 0 BEGINNING_SUM_OF_MONEY, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
            FROM INT_PS_1_TK_VT_KHO_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
            WHERE :P_WAREHOUSE IS NULL OR INT_PS_1_TK_VT_KHO_C.WAREHOUSE = :P_WAREHOUSE
        ) RESULTS
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = RESULTS.GOODS
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = RESULTS.GOODS
        JOIN ATOMS GOOD_ATOMS ON GOOD_ATOMS.COMPANY = :P_COMPANY AND GOOD_ATOMS.ID = RESULTS.GOODS AND (:P_TEAM IS NULL OR GOOD_ATOMS.TEAM = :P_TEAM)
        JOIN ATOM_STRINGS GOOD_ATOM_STRINGS ON GOOD_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOOD_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOOD_ATOM_STRINGS.ID = RESULTS.GOODS
        LEFT JOIN ATOMS WAREHOUSE_ATOMS ON WAREHOUSE_ATOMS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOMS.ID = RESULTS.WAREHOUSE
        LEFT JOIN ATOM_STRINGS WAREHOUSE_ATOM_STRINGS ON WAREHOUSE_ATOM_STRINGS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND WAREHOUSE_ATOM_STRINGS.ID = RESULTS.WAREHOUSE
        LEFT JOIN ATOMS TEAM_ATOMS ON TEAM_ATOMS.COMPANY = :P_COMPANY AND TEAM_ATOMS.ID = GOOD_ATOMS.TEAM
        LEFT JOIN ATOM_STRINGS TEAM_ATOM_STRINGS ON TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_ATOM_STRINGS.ID = GOOD_ATOMS.TEAM
        GROUP BY GOODS, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME
        ORDER BY TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT
        INTO :CODE, :NAME, :UNIT, :TEAM_CODE, :TEAM_NAME, :WAREHOUSE_CODE, :WAREHOUSE_NAME,
            :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        ENDING_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(BEGINNING_AMOUNT <> 0 OR BEGINNING_SUM_OF_MONEY <> 0 OR INPUT_AMOUNT <> 0 OR INPUT_SUM_OF_MONEY <> 0 OR OUTPUT_AMOUNT <> 0 OR OUTPUT_SUM_OF_MONEY <> 0 OR ENDING_AMOUNT <> 0 OR ENDING_SUM_OF_MONEY <> 0)THEN
        BEGIN
            IF(ROUND(BEGINNING_AMOUNT, 5) <> 0)THEN
                BEGINNING_PRICE = ROUND(BEGINNING_SUM_OF_MONEY/BEGINNING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                BEGINNING_PRICE = NULL;

            IF(ROUND(INPUT_AMOUNT, 5) <> 0)THEN
                INPUT_PRICE = ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                INPUT_PRICE = NULL;

            IF(ROUND(OUTPUT_AMOUNT, 5) <> 0)THEN
                OUTPUT_PRICE = ROUND(OUTPUT_SUM_OF_MONEY/OUTPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                OUTPUT_PRICE = NULL;

            IF(ROUND(ENDING_AMOUNT, 5) <> 0)THEN
                ENDING_PRICE = ROUND(ENDING_SUM_OF_MONEY/ENDING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                ENDING_PRICE = NULL;

            IF(BEGINNING_AMOUNT = 0)THEN BEGINNING_AMOUNT = NULL;
            IF(INPUT_AMOUNT = 0)THEN INPUT_AMOUNT = NULL;
            IF(OUTPUT_AMOUNT = 0)THEN OUTPUT_AMOUNT = NULL;
            IF(ENDING_AMOUNT = 0)THEN ENDING_AMOUNT = NULL;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_BANG_KE_NXT_1_TK_NHOM (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_TEAM DM_ID)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
UNIT DM_UNIT,
TEAM_CODE DM_CODE,
TEAM_NAME DM_NAME,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
BEGINNING_PRICE DM_DOUBLE,
INPUT_PRICE DM_DOUBLE,
OUTPUT_PRICE DM_DOUBLE,
ENDING_PRICE DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, SUM(BEGINNING_AMOUNT), SUM(BEGINNING_SUM_OF_MONEY), SUM(INPUT_AMOUNT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_AMOUNT), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT GOODS, AMOUNT BEGINNING_AMOUNT, SUM_OF_MONEY BEGINNING_SUM_OF_MONEY, 0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY
            FROM INT_SD_1_TK_VT_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT GOODS, 0 BEGINNING_AMOUNT, 0 BEGINNING_SUM_OF_MONEY, INPUT_AMOUNT, INPUT_SUM_OF_MONEY, OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY
            FROM INT_PS_1_TK_VT_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        ) RESULTS
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = RESULTS.GOODS
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = RESULTS.GOODS
        JOIN ATOMS GOOD_ATOMS ON GOOD_ATOMS.COMPANY = :P_COMPANY AND GOOD_ATOMS.ID = RESULTS.GOODS AND (:P_TEAM IS NULL OR GOOD_ATOMS.TEAM = :P_TEAM)
        JOIN ATOM_STRINGS GOOD_ATOM_STRINGS ON GOOD_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOOD_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOOD_ATOM_STRINGS.ID = RESULTS.GOODS
        LEFT JOIN ATOMS TEAM_ATOMS ON TEAM_ATOMS.COMPANY = :P_COMPANY AND TEAM_ATOMS.ID = GOOD_ATOMS.TEAM
        LEFT JOIN ATOM_STRINGS TEAM_ATOM_STRINGS ON TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_ATOM_STRINGS.ID = GOOD_ATOMS.TEAM
        GROUP BY GOODS, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME
        ORDER BY TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT
        INTO :CODE, :NAME, :UNIT, :TEAM_CODE, :TEAM_NAME, :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY, :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        ENDING_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(BEGINNING_AMOUNT <> 0 OR BEGINNING_SUM_OF_MONEY <> 0 OR INPUT_AMOUNT <> 0 OR INPUT_SUM_OF_MONEY <> 0 OR OUTPUT_AMOUNT <> 0 OR OUTPUT_SUM_OF_MONEY <> 0 OR ENDING_AMOUNT <> 0 OR ENDING_SUM_OF_MONEY <> 0)THEN
        BEGIN
            IF(ROUND(BEGINNING_AMOUNT, 5) <> 0)THEN
                BEGINNING_PRICE = ROUND(BEGINNING_SUM_OF_MONEY/BEGINNING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                BEGINNING_PRICE = NULL;

            IF(ROUND(INPUT_AMOUNT, 5) <> 0)THEN
                INPUT_PRICE = ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                INPUT_PRICE = NULL;

            IF(ROUND(OUTPUT_AMOUNT, 5) <> 0)THEN
                OUTPUT_PRICE = ROUND(OUTPUT_SUM_OF_MONEY/OUTPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                OUTPUT_PRICE = NULL;

            IF(ROUND(ENDING_AMOUNT, 5) <> 0)THEN
                ENDING_PRICE = ROUND(ENDING_SUM_OF_MONEY/ENDING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            ELSE
                ENDING_PRICE = NULL;

            IF(BEGINNING_AMOUNT = 0)THEN BEGINNING_AMOUNT = NULL;
            IF(INPUT_AMOUNT = 0)THEN INPUT_AMOUNT = NULL;
            IF(OUTPUT_AMOUNT = 0)THEN OUTPUT_AMOUNT = NULL;
            IF(ENDING_AMOUNT = 0)THEN ENDING_AMOUNT = NULL;

            SUSPEND;
        END
    END
END ^

