ALTER PROCEDURE RPT_BANG_KE_NXT_LO_HANG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (GOODS_CODE DM_CODE,
GOODS_NAME DM_NAME,
GOODS_UNIT DM_UNIT,
WAREHOUSE_CODE DM_CODE,
WAREHOUSE_NAME DM_NAME,
INPUT_DATE DM_DATE,
CODE DM_DOCUMENT_CODE,
CONTENT DM_CONTENT,
PRICE DM_DOUBLE,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE NUMBER DM_INTEGER;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    FOR
        SELECT
            GOODS_CODE,
            GOODS_NAME,
            GOODS_UNIT,
            WAREHOUSE_CODE,
            WAREHOUSE_NAME,
            INPUT_DATE,
            CODE,
            LIST(CONTENT),
            SUM(PRICE),
            SUM(BEGINNING_AMOUNT),
            SUM(BEGINNING_SUM_OF_MONEY),
            SUM(INPUT_AMOUNT),
            SUM(INPUT_SUM_OF_MONEY),
            SUM(OUTPUT_AMOUNT),
            SUM(OUTPUT_SUM_OF_MONEY),
            SUM(ENDING_AMOUNT),
            SUM(ENDING_SUM_OF_MONEY),
            COUNT(*)
        FROM INT_BANG_KE_NXT_LO_HANG(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_ACCOUNT, :P_TU_NGAY, :P_DEN_NGAY)
        GROUP BY
            GOODS_CODE,
            GOODS_NAME,
            GOODS_UNIT,
            WAREHOUSE_CODE,
            WAREHOUSE_NAME,
            INPUT_DATE,
            CODE
        INTO
            :GOODS_CODE,
            :GOODS_NAME,
            :GOODS_UNIT,
            :WAREHOUSE_CODE,
            :WAREHOUSE_NAME,
            :INPUT_DATE,
            :CODE,
            :CONTENT,
            :PRICE,
            :BEGINNING_AMOUNT,
            :BEGINNING_SUM_OF_MONEY,
            :INPUT_AMOUNT,
            :INPUT_SUM_OF_MONEY,
            :OUTPUT_AMOUNT,
            :OUTPUT_SUM_OF_MONEY,
            :ENDING_AMOUNT,
            :ENDING_SUM_OF_MONEY,
            :NUMBER
    DO
    BEGIN
        IF(NUMBER > 1)THEN
        BEGIN
            IF(BEGINNING_AMOUNT > 0)THEN
            BEGIN
                PRICE = ROUND(BEGINNING_SUM_OF_MONEY/BEGINNING_AMOUNT, NUMBER_DECIMAL_DIGITS);
            END
            ELSE IF(INPUT_AMOUNT > 0)THEN
            BEGIN
                PRICE = ROUND(INPUT_SUM_OF_MONEY/INPUT_AMOUNT, NUMBER_DECIMAL_DIGITS);
            END
        END

        SUSPEND;
    END
END ^

