WAREHOUSE_NAME DM_NAME,
TEAM_CODE DM_CODE,
TEAM_NAME DM_NAME,
PRICE DM_DOUBLE,
AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    FOR
        SELECT GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME,
            SUM(AMOUNT), SUM(SUM_OF_MONEY)
        FROM INT_SD_1_TK_VT_KHO_CN_C(:P_COMPANY, :ACCOUNT_CODE, :P_NGAY)
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = INT_SD_1_TK_VT_KHO_CN_C.GOODS
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = INT_SD_1_TK_VT_KHO_CN_C.GOODS
        JOIN ATOMS GOOD_ATOMS ON GOOD_ATOMS.COMPANY = :P_COMPANY AND GOOD_ATOMS.ID = INT_SD_1_TK_VT_KHO_CN_C.GOODS AND (:P_TEAM IS NULL OR GOOD_ATOMS.TEAM = :P_TEAM)
        JOIN ATOM_STRINGS GOOD_ATOM_STRINGS ON GOOD_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOOD_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOOD_ATOM_STRINGS.ID = INT_SD_1_TK_VT_KHO_CN_C.GOODS
        LEFT JOIN ATOMS TEAM_ATOMS ON TEAM_ATOMS.COMPANY = :P_COMPANY AND TEAM_ATOMS.ID = GOOD_ATOMS.TEAM
        LEFT JOIN ATOM_STRINGS TEAM_ATOM_STRINGS ON TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_ATOM_STRINGS.ID = GOOD_ATOMS.TEAM
        LEFT JOIN ATOMS WAREHOUSE_ATOMS ON WAREHOUSE_ATOMS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOMS.ID = INT_SD_1_TK_VT_KHO_CN_C.WAREHOUSE
        LEFT JOIN ATOM_STRINGS WAREHOUSE_ATOM_STRINGS ON WAREHOUSE_ATOM_STRINGS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND WAREHOUSE_ATOM_STRINGS.ID = INT_SD_1_TK_VT_KHO_CN_C.WAREHOUSE
        WHERE :P_WAREHOUSE IS NULL OR INT_SD_1_TK_VT_KHO_CN_C.WAREHOUSE = :P_WAREHOUSE
        GROUP BY GOODS, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, WAREHOUSE_ATOMS.CODE, WAREHOUSE_ATOM_STRINGS.NAME
        ORDER BY TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT
        INTO :CODE, :NAME, :UNIT, :TEAM_CODE, :TEAM_NAME, :WAREHOUSE_CODE, :WAREHOUSE_NAME, :AMOUNT, :SUM_OF_MONEY
    DO
    BEGIN
        IF(ROUND(AMOUNT, 5) <> 0)THEN
        BEGIN
            PRICE = ROUND(SUM_OF_MONEY/AMOUNT, NUMBER_DECIMAL_DIGITS);
            SUSPEND;
        END
        ELSE IF(SUM_OF_MONEY <> 0)THEN
        BEGIN
            PRICE = 0;
            SUSPEND;
        END
    END
END ^

