ALTER PROCEDURE RPT_BANG_TH_CHI_TIET_HANG_HOA (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
UNIT DM_UNIT,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE BEGINNING_DEBIT DM_ID;
DECLARE VARIABLE BEGINNING_CREDIT DM_ID;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT, SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(INPUT_SUM_OF_MONEY), SUM(OUTPUT_SUM_OF_MONEY)
        FROM
        (
            SELECT OBJECT0, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 INPUT_SUM_OF_MONEY, 0 OUTPUT_SUM_OF_MONEY
            FROM INT_SD_1_TK_DT0_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT INPUT_SUM_OF_MONEY, CREDIT OUTPUT_SUM_OF_MONEY
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        ) RESULTS
        JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = RESULTS.OBJECT0
        JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = RESULTS.OBJECT0
        JOIN ATOMS GOOD_ATOMS ON GOOD_ATOMS.COMPANY = :P_COMPANY AND GOOD_ATOMS.ID = RESULTS.OBJECT0
        JOIN ATOM_STRINGS GOOD_ATOM_STRINGS ON GOOD_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOOD_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOOD_ATOM_STRINGS.ID = RESULTS.OBJECT0
        GROUP BY OBJECT0, GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT
        ORDER BY GOOD_ATOMS.CODE, GOOD_ATOM_STRINGS.NAME, GOODS_STRINGS.UNIT
        INTO :CODE, :NAME, :UNIT, :BEGINNING_DEBIT, :BEGINNING_CREDIT, :INPUT_SUM_OF_MONEY, :OUTPUT_SUM_OF_MONEY
    DO
    BEGIN
        BEGINNING_SUM_OF_MONEY = BEGINNING_DEBIT - BEGINNING_CREDIT;

        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        IF(BEGINNING_SUM_OF_MONEY <> 0 OR INPUT_SUM_OF_MONEY <> 0 OR OUTPUT_SUM_OF_MONEY <> 0 OR ENDING_SUM_OF_MONEY <> 0)THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_BAO_CAO_TAI_CHINH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ID DM_ID,
NAME DM_NAME,
ITEM_CODE DM_ITEM_CODE,
COMMENTARY DM_COMMENTARY,
CURRENT_PERIOD DM_DOUBLE,
PREVIOUS_PERIOD DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_ID, 0, P_TU_NGAY, P_DEN_NGAY);

    FOR
        SELECT FINANCIAL_REPORTS.ID, NAME, ITEM_CODE, COMMENTARY, CURRENT_PERIOD, TEMP_FINANCIAL_REPORT.PREVIOUS_PERIOD
        FROM FINANCIAL_REPORTS
        LEFT JOIN FINANCIAL_REPORT_STRINGS ON FINANCIAL_REPORT_STRINGS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_STRINGS.LANGUAGE = :P_LANGUAGE AND FINANCIAL_REPORT_STRINGS.ID = FINANCIAL_REPORTS.ID
        JOIN TEMP_FINANCIAL_REPORT ON TEMP_FINANCIAL_REPORT.ID = FINANCIAL_REPORTS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        WHERE FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = :P_ID
        ORDER BY PROTONS.ORDINAL
        INTO :ID ,:NAME, :ITEM_CODE, :COMMENTARY, :CURRENT_PERIOD, :PREVIOUS_PERIOD
    DO
    BEGIN
        SUSPEND;
    END
END ^

