VI_CP_TC_TONG DM_DOUBLE,
VI_CP_TC_BACH_DAN DM_DOUBLE,
VI_CP_TC_KEO DM_DOUBLE,
VI_CP_TC_PHI_LAO DM_DOUBLE,
TONG_CONG_TONG DM_DOUBLE,
TONG_CONG_BACH_DAN DM_DOUBLE,
TONG_CONG_KEO DM_DOUBLE,
TONG_CONG_PHI_LAO DM_DOUBLE,
GIA_TONG_HOP_BACH_DAN DM_DOUBLE,
GIA_TONG_HOP_KEO DM_DOUBLE,
GIA_TONG_HOP_PHI_LAO DM_DOUBLE)
AS 
DECLARE VARIABLE BACH_DAN_ID DM_ID;
DECLARE VARIABLE KEO_ID DM_ID;
DECLARE VARIABLE PHI_LAO_ID DM_ID;
DECLARE VARIABLE PERCENT_DECIMAL_DIGITS DM_INTEGER;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
DECLARE VARIABLE AMOUNT_BACH_DAN DM_DOUBLE;
DECLARE VARIABLE AMOUNT_KEO DM_DOUBLE;
DECLARE VARIABLE AMOUNT_PHI_LAO DM_DOUBLE;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS, PERCENT_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS, :PERCENT_DECIMAL_DIGITS;

    
    SELECT GOODS.ID
    FROM GOODS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = GOODS.ID AND ATOMS.CODE = 'BD'
    WHERE GOODS.COMPANY = :P_COMPANY
    INTO :BACH_DAN_ID;

    SELECT GOODS.ID
    FROM GOODS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = GOODS.ID AND ATOMS.CODE = 'KEO'
    WHERE GOODS.COMPANY = :P_COMPANY
    INTO :KEO_ID;

    SELECT GOODS.ID
    FROM GOODS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = GOODS.ID AND ATOMS.CODE = 'PL'
    WHERE GOODS.COMPANY = :P_COMPANY
    INTO :PHI_LAO_ID;
    
    
    SELECT AMOUNT
    FROM INT_PS_CAP_TK_NO_DT0_C(:P_COMPANY, '155', :BACH_DAN_ID, '154', :P_TU_NGAY, :P_DEN_NGAY)
    INTO :AMOUNT_BACH_DAN;
    
    SELECT AMOUNT
    FROM INT_PS_CAP_TK_NO_DT0_C(:P_COMPANY, '155', :KEO_ID, '154', :P_TU_NGAY, :P_DEN_NGAY)
    INTO :AMOUNT_KEO;
    
    SELECT AMOUNT
    FROM INT_PS_CAP_TK_NO_DT0_C(:P_COMPANY, '155', :PHI_LAO_ID, '154', :P_TU_NGAY, :P_DEN_NGAY)
    INTO :AMOUNT_PHI_LAO;

    
    SELECT DEBIT
    FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, '621', :BACH_DAN_ID, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :I_CP_NL_TT_BACH_DAN;

    SELECT DEBIT
    FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, '621', :KEO_ID, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :I_CP_NL_TT_KEO;

    SELECT DEBIT
    FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, '621', :PHI_LAO_ID, :P_TU_NGAY, :P_DEN_NGAY)
    INTO :I_CP_NL_TT_PHI_LAO;

    I_CP_NL_TT_TONG = I_CP_NL_TT_BACH_DAN + I_CP_NL_TT_KEO + I_CP_NL_TT_PHI_LAO;

    IF(I_CP_NL_TT_TONG <> 0)THEN
    BEGIN
        IF(I_CP_NL_TT_BACH_DAN = 0)THEN
        BEGIN
            PERCENT_BACH_DAN = 0;

            IF(I_CP_NL_TT_KEO = 0)THEN
            BEGIN
                PERCENT_KEO = 0;

                IF(I_CP_NL_TT_PHI_LAO = 0)THEN
                BEGIN
                    PERCENT_PHI_LAO = 0;
                END
                ELSE
                BEGIN
                    PERCENT_PHI_LAO = 1;
                END
            END
            ELSE
            BEGIN
                IF(I_CP_NL_TT_PHI_LAO = 0)THEN
                BEGIN
                    PERCENT_KEO = 1;
                    PERCENT_PHI_LAO = 0;
                END
                ELSE
                BEGIN
                    PERCENT_KEO = ROUND(I_CP_NL_TT_KEO/I_CP_NL_TT_TONG, PERCENT_DECIMAL_DIGITS + 2);
                    PERCENT_PHI_LAO = 1 - PERCENT_KEO;
                END
            END
        END
        ELSE
        BEGIN
            IF(I_CP_NL_TT_KEO = 0)THEN
            BEGIN
                PERCENT_KEO = 0;

                IF(I_CP_NL_TT_PHI_LAO = 0)THEN
                BEGIN
                    PERCENT_BACH_DAN = 1;
                    PERCENT_PHI_LAO = 0;
                END
                ELSE
                BEGIN
                    PERCENT_BACH_DAN = ROUND(I_CP_NL_TT_BACH_DAN/I_CP_NL_TT_TONG, PERCENT_DECIMAL_DIGITS + 2);
                    PERCENT_PHI_LAO = 1 - PERCENT_BACH_DAN;
                END
            END
            ELSE
            BEGIN
                IF(I_CP_NL_TT_PHI_LAO = 0)THEN
                BEGIN
                    PERCENT_BACH_DAN = ROUND(I_CP_NL_TT_BACH_DAN/I_CP_NL_TT_TONG, PERCENT_DECIMAL_DIGITS + 2);
                    PERCENT_KEO = 1- PERCENT_BACH_DAN;
                    PERCENT_PHI_LAO = 0;
                END
                ELSE
                BEGIN
                    PERCENT_BACH_DAN = ROUND(I_CP_NL_TT_BACH_DAN/I_CP_NL_TT_TONG, PERCENT_DECIMAL_DIGITS + 2);
                    PERCENT_KEO = ROUND(I_CP_NL_TT_KEO/I_CP_NL_TT_TONG, PERCENT_DECIMAL_DIGITS + 2);
                    PERCENT_PHI_LAO = 1 - PERCENT_BACH_DAN - PERCENT_KEO;
                END
            END
        END
    END
    ELSE
    BEGIN
        PERCENT_BACH_DAN = 0;
        PERCENT_KEO = 0;
        PERCENT_PHI_LAO = 0;
    END

    
