    INTO :V_CP_QL_6428_TONG;

    V_CP_QL_6428_BACH_DAN = ROUND(V_CP_QL_6428_TONG*PERCENT_BACH_DAN, 0);
    V_CP_QL_6428_KEO = ROUND(V_CP_QL_6428_TONG*PERCENT_KEO, 0);
    V_CP_QL_6428_PHI_LAO = V_CP_QL_6428_TONG - V_CP_QL_6428_BACH_DAN - V_CP_QL_6428_KEO;

    
    V_CP_QL_TONG = V_CP_QL_6421_TONG + V_CP_QL_6422_TONG + V_CP_QL_6423_TONG + V_CP_QL_6424_TONG + V_CP_QL_6425_TONG + V_CP_QL_6426_TONG + V_CP_QL_6427_TONG + V_CP_QL_6428_TONG;
    V_CP_QL_TONG_BACH_DAN = V_CP_QL_6421_BACH_DAN + V_CP_QL_6422_BACH_DAN + V_CP_QL_6423_BACH_DAN + V_CP_QL_6424_BACH_DAN + V_CP_QL_6425_BACH_DAN + V_CP_QL_6426_BACH_DAN + V_CP_QL_6427_BACH_DAN + V_CP_QL_6428_BACH_DAN;
    V_CP_QL_TONG_KEO = V_CP_QL_6421_KEO + V_CP_QL_6422_KEO + V_CP_QL_6423_KEO + V_CP_QL_6424_KEO + V_CP_QL_6425_KEO + V_CP_QL_6426_KEO + V_CP_QL_6427_KEO + V_CP_QL_6428_KEO;
    V_CP_QL_TONG_PHI_LAO = V_CP_QL_6421_PHI_LAO + V_CP_QL_6422_PHI_LAO + V_CP_QL_6423_PHI_LAO + V_CP_QL_6424_PHI_LAO + V_CP_QL_6425_PHI_LAO + V_CP_QL_6426_PHI_LAO + V_CP_QL_6427_PHI_LAO + V_CP_QL_6428_PHI_LAO;
    
    
    SELECT DEBIT
    FROM INT_PS_1_TK_C(:P_COMPANY, '635', :P_TU_NGAY, :P_DEN_NGAY)
    INTO :VI_CP_TC_TONG;

    VI_CP_TC_BACH_DAN = ROUND(VI_CP_TC_TONG*PERCENT_BACH_DAN, 0);
    VI_CP_TC_KEO = ROUND(VI_CP_TC_TONG*PERCENT_KEO, 0);
    VI_CP_TC_PHI_LAO = VI_CP_TC_TONG - VI_CP_TC_BACH_DAN - VI_CP_TC_KEO;
    
    TONG_CONG_TONG = I_CP_NL_TT_TONG + II_CP_SXC_TONG + III_CP_NC_TT_TONG + IV_CP_BH_TONG + V_CP_QL_TONG + VI_CP_TC_TONG;
    TONG_CONG_BACH_DAN = I_CP_NL_TT_BACH_DAN + II_CP_SXC_TONG_BACH_DAN + III_CP_NC_TT_BACH_DAN + IV_CP_BH_TONG_BACH_DAN + V_CP_QL_TONG_BACH_DAN + VI_CP_TC_BACH_DAN;
    TONG_CONG_KEO = I_CP_NL_TT_KEO + II_CP_SXC_TONG_KEO + III_CP_NC_TT_KEO + IV_CP_BH_TONG_KEO + V_CP_QL_TONG_KEO + VI_CP_TC_KEO;
    TONG_CONG_PHI_LAO = I_CP_NL_TT_PHI_LAO + II_CP_SXC_TONG_PHI_LAO + III_CP_NC_TT_PHI_LAO + IV_CP_BH_TONG_PHI_LAO + V_CP_QL_TONG_PHI_LAO + VI_CP_TC_PHI_LAO;
    
    IF(AMOUNT_BACH_DAN <> 0)THEN GIA_TONG_HOP_BACH_DAN = ROUND(TONG_CONG_BACH_DAN/AMOUNT_BACH_DAN, :NUMBER_DECIMAL_DIGITS);
    IF(AMOUNT_KEO <> 0)THEN GIA_TONG_HOP_KEO = ROUND(TONG_CONG_KEO/AMOUNT_KEO, :NUMBER_DECIMAL_DIGITS);
    IF(AMOUNT_PHI_LAO <> 0)THEN GIA_TONG_HOP_PHI_LAO = ROUND(TONG_CONG_PHI_LAO/AMOUNT_PHI_LAO, :NUMBER_DECIMAL_DIGITS);

    SUSPEND;
END ^

ALTER PROCEDURE RPT_CAT_PHU_TONG_HOP_NXT_NL_TP (P_LANGUAGE DM_ID,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ID DM_ID,
CODE DM_CODE,
NAME DM_NAME,
UNIT DM_UNIT,
NL_TON_DAU_KY_SL DM_DOUBLE,
NL_TON_DAU_KY_GT DM_DOUBLE,
NL_NHAP_TRONG_KY_SL DM_DOUBLE,
NL_NHAP_TRONG_KY_GT DM_DOUBLE,
NL_XUAT_TRONG_KY_SL DM_DOUBLE,
NL_XUAT_TRONG_KY_GT DM_DOUBLE,
NL_TON_CUOI_KY_SL DM_DOUBLE,
NL_TON_CUOI_KY_GT DM_DOUBLE,
MT_TON_DAU_KY_SL DM_DOUBLE,
MT_TON_DAU_KY_GT DM_DOUBLE,
MT_NHAP_TRONG_KY_SL DM_DOUBLE,
MT_NHAP_TRONG_KY_GT DM_DOUBLE,
MT_XUAT_TRONG_KY_SL DM_DOUBLE,
MT_XUAT_TRONG_KY_GT DM_DOUBLE,
MT_TON_CUOI_KY_SL DM_DOUBLE,
MT_TON_CUOI_KY_GT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_ID_152 DM_ID;
DECLARE VARIABLE ACCOUNT_ID_155 DM_ID;
BEGIN
    SELECT ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '152'
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    INTO :ACCOUNT_ID_152;

    SELECT ACCOUNTS.ID
    FROM ACCOUNTS
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '155'
    WHERE ACCOUNTS.COMPANY = :P_COMPANY
    INTO :ACCOUNT_ID_155;

    FOR
        SELECT ID, CODE, NAME, UNIT,
            SUM(NL_TON_DAU_KY_SL), SUM(NL_TON_DAU_KY_GT),
            SUM(NL_NHAP_TRONG_KY_SL), SUM(NL_NHAP_TRONG_KY_GT),
            SUM(NL_XUAT_TRONG_KY_SL), SUM(NL_XUAT_TRONG_KY_GT),
            SUM(NL_TON_CUOI_KY_SL), SUM(NL_TON_CUOI_KY_GT),
            SUM(MT_TON_DAU_KY_SL), SUM(MT_TON_DAU_KY_GT),
            SUM(MT_NHAP_TRONG_KY_SL), SUM(MT_NHAP_TRONG_KY_GT),
            SUM(MT_XUAT_TRONG_KY_SL), SUM(MT_XUAT_TRONG_KY_GT),
            SUM(MT_TON_CUOI_KY_SL), SUM(MT_TON_CUOI_KY_GT)
        FROM
        (
            SELECT ID, CODE, NAME, UNIT,
            BEGINNING_AMOUNT NL_TON_DAU_KY_SL, BEGINNING_SUM_OF_MONEY NL_TON_DAU_KY_GT,
            INPUT_AMOUNT NL_NHAP_TRONG_KY_SL, INPUT_SUM_OF_MONEY NL_NHAP_TRONG_KY_GT,
            OUTPUT_AMOUNT NL_XUAT_TRONG_KY_SL, OUTPUT_SUM_OF_MONEY NL_XUAT_TRONG_KY_GT,
            ENDING_AMOUNT NL_TON_CUOI_KY_SL, ENDING_SUM_OF_MONEY NL_TON_CUOI_KY_GT,
            0 MT_TON_DAU_KY_SL, 0 MT_TON_DAU_KY_GT,
            0 MT_NHAP_TRONG_KY_SL, 0 MT_NHAP_TRONG_KY_GT,
            0 MT_XUAT_TRONG_KY_SL, 0 MT_XUAT_TRONG_KY_GT,
            0 MT_TON_CUOI_KY_SL, 0 MT_TON_CUOI_KY_GT
            FROM RPT_BANG_KE_NXT_1_TK(:P_LANGUAGE, :P_COMPANY, :P_ID, :ACCOUNT_ID_152, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL
            
            SELECT ID, CODE, NAME, UNIT,
            0 NL_TON_DAU_KY_SL, 0 NL_TON_DAU_KY_GT,
            0 NL_NHAP_TRONG_KY_SL, 0 NL_NHAP_TRONG_KY_GT,
            0 NL_XUAT_TRONG_KY_SL, 0 NL_XUAT_TRONG_KY_GT,
            0 NL_TON_CUOI_KY_SL, 0 NL_TON_CUOI_KY_GT,
            BEGINNING_AMOUNT MT_TON_DAU_KY_SL, BEGINNING_SUM_OF_MONEY MT_TON_DAU_KY_GT,
            INPUT_AMOUNT MT_NHAP_TRONG_KY_SL, INPUT_SUM_OF_MONEY MT_NHAP_TRONG_KY_GT,
            OUTPUT_AMOUNT MT_XUAT_TRONG_KY_SL, OUTPUT_SUM_OF_MONEY MT_XUAT_TRONG_KY_GT,
            ENDING_AMOUNT MT_TON_CUOI_KY_SL, ENDING_SUM_OF_MONEY MT_TON_CUOI_KY_GT
            FROM RPT_BANG_KE_NXT_1_TK(:P_LANGUAGE, :P_COMPANY, :P_ID, :ACCOUNT_ID_155, :P_TU_NGAY, :P_DEN_NGAY)
        )RESULTS
        WHERE (CODE = 'BD' OR CODE = 'KEO' OR CODE = 'PL')
        GROUP BY ID, CODE, NAME, UNIT
        INTO :ID, :CODE, :NAME, :UNIT,
        :NL_TON_DAU_KY_SL, :NL_TON_DAU_KY_GT,
        :NL_NHAP_TRONG_KY_SL, :NL_NHAP_TRONG_KY_GT,
        :NL_XUAT_TRONG_KY_SL, :NL_XUAT_TRONG_KY_GT,
        :NL_TON_CUOI_KY_SL, :NL_TON_CUOI_KY_GT,
        :MT_TON_DAU_KY_SL, :MT_TON_DAU_KY_GT,
        :MT_NHAP_TRONG_KY_SL, :MT_NHAP_TRONG_KY_GT,
        :MT_XUAT_TRONG_KY_SL, :MT_XUAT_TRONG_KY_GT,
        :MT_TON_CUOI_KY_SL, :MT_TON_CUOI_KY_GT
    DO
    BEGIN
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_CHENH_LECH_GIA_BAN_GIA_VON (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_TEAM DM_ID)
RETURNS (OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
TEAM_CODE DM_CODE,
TEAM_NAME DM_NAME,
AMOUNT DM_DOUBLE,
DON_GIA_BAN DM_DOUBLE,
DOANH_THU DM_DOUBLE,
DON_GIA_VON DM_DOUBLE,
GIA_VON DM_DOUBLE,
LAI_GOP DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE NUMBER_DECIMAL_DIGITS DM_INTEGER;
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    FOR
        SELECT ATOMS.CODE, ATOM_STRINGS.NAME, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME, SUM(AMOUNT), SUM(DOANH_THU), SUM(GIA_VON)
        FROM
        (
            SELECT CREDIT.OBJECT0 OBJECT, DEBIT.AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY DOANH_THU, 0 GIA_VON
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND (DEBIT_ATOM.CODE NOT STARTING '911')
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE ENTRIES.COMPANY = :P_COMPANY

            UNION ALL

            SELECT CREDIT.OBJECT0 OBJECT, 0 AMOUNT, 0 DOANH_THU, DEBIT.OFFICIAL_SUM_OF_MONEY GIA_VON
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH '632'
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY
        ) ABC
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ABC.OBJECT AND (:P_TEAM IS NULL OR ATOMS.TEAM = :P_TEAM)
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ABC.OBJECT
        LEFT JOIN ATOMS TEAM_ATOMS ON TEAM_ATOMS.COMPANY = :P_COMPANY AND TEAM_ATOMS.ID = ATOMS.TEAM
        LEFT JOIN ATOM_STRINGS TEAM_ATOM_STRINGS ON TEAM_ATOM_STRINGS.COMPANY = :P_COMPANY AND TEAM_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND TEAM_ATOM_STRINGS.ID = ATOMS.TEAM
        GROUP BY OBJECT, ATOMS.CODE, ATOM_STRINGS.NAME, TEAM_ATOMS.CODE, TEAM_ATOM_STRINGS.NAME
        HAVING SUM(AMOUNT) <> 0 OR SUM(DOANH_THU) <> 0
        ORDER BY ATOMS.CODE
        INTO :OBJECT_CODE, :OBJECT_NAME, :TEAM_CODE, :TEAM_NAME, :AMOUNT, :DOANH_THU, :GIA_VON
    DO
    BEGIN
        IF(AMOUNT = 0)THEN
        BEGIN
            DON_GIA_BAN = NULL;
            DON_GIA_VON = NULL;
        END
        ELSE
        BEGIN
            DON_GIA_BAN = ROUND(DOANH_THU/AMOUNT, NUMBER_DECIMAL_DIGITS);
            DON_GIA_VON = ROUND(GIA_VON/AMOUNT, NUMBER_DECIMAL_DIGITS);
        END

        LAI_GOP = DOANH_THU - GIA_VON;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_CHUNG_TU_GHI_SO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
CREDIT_ACCOUNT_CODE DM_CODE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
NOTE DM_NOTE)
AS 
BEGIN
    FOR
        SELECT RECORDED_DOCUMENTS.CODE, INPUT_DATE, RECORDED_DOCUMENT_ENTRIES.CONTENT, ATOMS_DEBIT.CODE, ATOMS_CREDIT.CODE, SUM_OF_MONEY, PROTON_STRINGS.NOTE
        FROM RECORDED_DOCUMENTS
        JOIN RECORDED_DOCUMENT_ENTRIES ON RECORDED_DOCUMENT_ENTRIES.COMPANY = :P_COMPANY AND RECORDED_DOCUMENT_ENTRIES.RECORDED_DOCUMENT = RECORDED_DOCUMENTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = RECORDED_DOCUMENT_ENTRIES.ID
        JOIN ATOMS ATOMS_DEBIT ON ATOMS_DEBIT.COMPANY = :P_COMPANY AND ATOMS_DEBIT.ID = DEBIT_ACCOUNT
        JOIN ATOMS ATOMS_CREDIT ON ATOMS_CREDIT.COMPANY = :P_COMPANY AND ATOMS_CREDIT.ID = CREDIT_ACCOUNT
        WHERE RECORDED_DOCUMENTS.COMPANY = :P_COMPANY AND RECORDED_DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ORDER BY INPUT_DATE, RECORDED_DOCUMENTS.CODE, ATOMS_DEBIT.CODE, ATOMS_CREDIT.CODE
        INTO :CODE, :INPUT_DATE, :CONTENT, :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE, :OFFICIAL_SUM_OF_MONEY, :NOTE
    DO
    BEGIN
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_COMPANY (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_USER_ID DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
OWNER_NAME DM_NAME,
SHORT_NAME DM_NAME,
TAX_CODE DM_TAX_CODE,
TAX_CODE_1 DM_SMALLINT,
TAX_CODE_2 DM_SMALLINT,
TAX_CODE_3 DM_SMALLINT,
TAX_CODE_4 DM_SMALLINT,
TAX_CODE_5 DM_SMALLINT,
TAX_CODE_6 DM_SMALLINT,
TAX_CODE_7 DM_SMALLINT,
TAX_CODE_8 DM_SMALLINT,
TAX_CODE_9 DM_SMALLINT,
TAX_CODE_10 DM_SMALLINT,
TAX_CODE_11 DM_SMALLINT,
TAX_CODE_12 DM_SMALLINT,
TAX_CODE_13 DM_SMALLINT,
PHONE DM_PHONE,
FAX DM_FAX,
ADDRESS DM_ADDRESS,
TRADE_TYPE DM_TRADE_TYPE,
TRADE_FIELD DM_TRADE_FIELD,
WEBSITE DM_WEBSITE,
EMAIL DM_EMAIL,
DIRECTOR DM_PERSON_NAME,
CHIEF_ACCOUNTANT DM_PERSON_NAME,
CASHIER DM_PERSON_NAME,
STOREKEEPER DM_PERSON_NAME,
GENERAL_ACCOUNTANT DM_PERSON_NAME,
PAYMENT_ACCOUNTANT DM_PERSON_NAME,
LOGO DM_IMAGE,
SLOGAN DM_SLOGAN,
PREPARED_PERSON DM_PERSON_NAME,
DOCUMENT_PERSON DM_PERSON_NAME,
CASHIER_CAPTION DM_CAPTION,
CHIEF_ACCOUNTANT_CAPTION DM_CAPTION,
DIRECTOR_CAPTION DM_CAPTION,
GENERAL_ACCOUNTANT_CAPTION DM_CAPTION,
STOREKEEPER_CAPTION DM_CAPTION,
PAYMENT_ACCOUNTANT_CAPTION DM_CAPTION,
PREPARED_PERSON_CAPTION DM_CAPTION,
DOCUMENT_PERSON_CAPTION DM_CAPTION)
AS 
DECLARE VARIABLE SHOW_NAMES_IN_REPORT DM_SHOW_NAME_IN_REPORT;
DECLARE VARIABLE PREPARED_PERSON_IS_LOGIN_USER DM_BOOL;
DECLARE VARIABLE DOCUMENT_PERSON_IS_LOGIN_USER DM_BOOL;
BEGIN
  SELECT COMPANIES.ID, ORDINAL, NOTE,
         CODE, NAME, HIDE, PARENT, TEAM,
         OWNER_NAME, SHORT_NAME,
         PHONE, FAX,
         ADDRESS, TRADE_TYPE, TRADE_FIELD,
         WEBSITE, EMAIL, DIRECTOR,
         CHIEF_ACCOUNTANT, CASHIER, STOREKEEPER,
         GENERAL_ACCOUNTANT, PAYMENT_ACCOUNTANT, LOGO, SLOGAN,
         PREPARED_PERSON, DOCUMENT_PERSON, CASHIER_CAPTION, CHIEF_ACCOUNTANT_CAPTION, DIRECTOR_CAPTION, GENERAL_ACCOUNTANT_CAPTION, STOREKEEPER_CAPTION, PAYMENT_ACCOUNTANT_CAPTION, PREPARED_PERSON_CAPTION, DOCUMENT_PERSON_CAPTION,
         SHOW_NAMES_IN_REPORT, PREPARED_PERSON_IS_LOGIN_USER, DOCUMENT_PERSON_IS_LOGIN_USER,
         TAX_CODE_1,
         TAX_CODE_2,
         TAX_CODE_3,
         TAX_CODE_4,
         TAX_CODE_5,
         TAX_CODE_6,
         TAX_CODE_7,
         TAX_CODE_8,
         TAX_CODE_9,
         TAX_CODE_10,
         TAX_CODE_11,
         TAX_CODE_12,
         TAX_CODE_13
  FROM COMPANIES
  JOIN COMPANY_STRINGS ON COMPANY_STRINGS.COMPANY = :P_COMPANY and COMPANY_STRINGS.LANGUAGE = :P_LANGUAGE AND COMPANY_STRINGS.ID = COMPANIES.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = COMPANIES.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE COMPANIES.ID = :P_COMPANY AND COMPANIES.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE,
       :CODE, :NAME, :HIDE, :PARENT, :TEAM,
       :OWNER_NAME, :SHORT_NAME,
       :PHONE, :FAX,
       :ADDRESS, :TRADE_TYPE, :TRADE_FIELD, :WEBSITE, :EMAIL, :DIRECTOR,
       :CHIEF_ACCOUNTANT, :CASHIER, :STOREKEEPER, :GENERAL_ACCOUNTANT,
       :PAYMENT_ACCOUNTANT, :LOGO, :SLOGAN,
       :PREPARED_PERSON, :DOCUMENT_PERSON, :CASHIER_CAPTION, :CHIEF_ACCOUNTANT_CAPTION, :DIRECTOR_CAPTION, :GENERAL_ACCOUNTANT_CAPTION, :STOREKEEPER_CAPTION, :PAYMENT_ACCOUNTANT_CAPTION, :PREPARED_PERSON_CAPTION, :DOCUMENT_PERSON_CAPTION,
       :SHOW_NAMES_IN_REPORT, :PREPARED_PERSON_IS_LOGIN_USER, :DOCUMENT_PERSON_IS_LOGIN_USER,
       :TAX_CODE_1,
       :TAX_CODE_2,
       :TAX_CODE_3,
       :TAX_CODE_4,
       :TAX_CODE_5,
       :TAX_CODE_6,
       :TAX_CODE_7,
       :TAX_CODE_8,
       :TAX_CODE_9,
       :TAX_CODE_10,
       :TAX_CODE_11,
       :TAX_CODE_12,
       :TAX_CODE_13;

   TAX_CODE = IIF(TAX_CODE_1 IS NULL, '', TAX_CODE_1) ||
       IIF(TAX_CODE_2 IS NULL, '', TAX_CODE_2) ||
       IIF(TAX_CODE_3 IS NULL, '', TAX_CODE_3) ||
       IIF(TAX_CODE_4 IS NULL, '', TAX_CODE_4) ||
       IIF(TAX_CODE_5 IS NULL, '', TAX_CODE_5) ||
       IIF(TAX_CODE_6 IS NULL, '', TAX_CODE_6) ||
       IIF(TAX_CODE_7 IS NULL, '', TAX_CODE_7) ||
       IIF(TAX_CODE_8 IS NULL, '', TAX_CODE_8) ||
       IIF(TAX_CODE_9 IS NULL, '', TAX_CODE_9) ||
       IIF(TAX_CODE_10 IS NULL, '', TAX_CODE_10) ||
       IIF(TAX_CODE_11 IS NULL, '', TAX_CODE_11) ||
       IIF(TAX_CODE_12 IS NULL, '', TAX_CODE_12) ||
       IIF(TAX_CODE_13 IS NULL, '', TAX_CODE_13);

   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 1) = 0)THEN DIRECTOR = NULL;
   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 2) = 0)THEN CHIEF_ACCOUNTANT = NULL;
   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 4) = 0)THEN GENERAL_ACCOUNTANT = NULL;
   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 8) = 0)THEN PAYMENT_ACCOUNTANT = NULL;
   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 16) = 0)THEN CASHIER = NULL;
   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 32) = 0)THEN STOREKEEPER = NULL;

   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 64) = 0)THEN
   BEGIN
    PREPARED_PERSON = NULL;
   END
   ELSE
   BEGIN
    IF(PREPARED_PERSON_IS_LOGIN_USER = 1)THEN
    BEGIN
        SELECT NAME
        FROM ATOM_STRINGS
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_USER_ID
        INTO :PREPARED_PERSON;
    END
   END

   IF(BIN_AND(SHOW_NAMES_IN_REPORT, 128) = 0)THEN
   BEGIN
    DOCUMENT_PERSON = NULL;
   END
   ELSE
   BEGIN
    IF(DOCUMENT_PERSON_IS_LOGIN_USER = 1)THEN
    BEGIN
        SELECT NAME
        FROM ATOM_STRINGS
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_USER_ID
        INTO :DOCUMENT_PERSON;
    END
   END

   suspend;
END ^

ALTER PROCEDURE RPT_COMPANY_FULL (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_USER_ID DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
OWNER_NAME DM_NAME,
SHORT_NAME DM_NAME,
TAX_CODE DM_TAX_CODE,
TAX_CODE_1 DM_SMALLINT,
TAX_CODE_2 DM_SMALLINT,
TAX_CODE_3 DM_SMALLINT,
TAX_CODE_4 DM_SMALLINT,
TAX_CODE_5 DM_SMALLINT,
TAX_CODE_6 DM_SMALLINT,
TAX_CODE_7 DM_SMALLINT,
TAX_CODE_8 DM_SMALLINT,
TAX_CODE_9 DM_SMALLINT,
TAX_CODE_10 DM_SMALLINT,
TAX_CODE_11 DM_SMALLINT,
TAX_CODE_12 DM_SMALLINT,
TAX_CODE_13 DM_SMALLINT,
PHONE DM_PHONE,
FAX DM_FAX,
ADDRESS DM_ADDRESS,
TRADE_TYPE DM_TRADE_TYPE,
TRADE_FIELD DM_TRADE_FIELD,
WEBSITE DM_WEBSITE,
EMAIL DM_EMAIL,
DIRECTOR DM_PERSON_NAME,
CHIEF_ACCOUNTANT DM_PERSON_NAME,
CASHIER DM_PERSON_NAME,
STOREKEEPER DM_PERSON_NAME,
GENERAL_ACCOUNTANT DM_PERSON_NAME,
PAYMENT_ACCOUNTANT DM_PERSON_NAME,
LOGO DM_IMAGE,
SLOGAN DM_SLOGAN,
PREPARED_PERSON DM_PERSON_NAME,
DOCUMENT_PERSON DM_PERSON_NAME,
CASHIER_CAPTION DM_CAPTION,
CHIEF_ACCOUNTANT_CAPTION DM_CAPTION,
DIRECTOR_CAPTION DM_CAPTION,
GENERAL_ACCOUNTANT_CAPTION DM_CAPTION,
STOREKEEPER_CAPTION DM_CAPTION,
PAYMENT_ACCOUNTANT_CAPTION DM_CAPTION,
PREPARED_PERSON_CAPTION DM_CAPTION,
DOCUMENT_PERSON_CAPTION DM_CAPTION)
AS 
DECLARE VARIABLE PREPARED_PERSON_IS_LOGIN_USER DM_BOOL;
DECLARE VARIABLE DOCUMENT_PERSON_IS_LOGIN_USER DM_BOOL;
BEGIN
  SELECT COMPANIES.ID, ORDINAL, NOTE,
         CODE, NAME, HIDE, PARENT, TEAM,
         OWNER_NAME, SHORT_NAME,
         PHONE, FAX,
         ADDRESS, TRADE_TYPE, TRADE_FIELD,
         WEBSITE, EMAIL, DIRECTOR,
         CHIEF_ACCOUNTANT, CASHIER, STOREKEEPER,
         GENERAL_ACCOUNTANT, PAYMENT_ACCOUNTANT, LOGO, SLOGAN,
         PREPARED_PERSON, DOCUMENT_PERSON, CASHIER_CAPTION, CHIEF_ACCOUNTANT_CAPTION, DIRECTOR_CAPTION, GENERAL_ACCOUNTANT_CAPTION, STOREKEEPER_CAPTION, PAYMENT_ACCOUNTANT_CAPTION, PREPARED_PERSON_CAPTION, DOCUMENT_PERSON_CAPTION,
         PREPARED_PERSON_IS_LOGIN_USER, DOCUMENT_PERSON_IS_LOGIN_USER,
         TAX_CODE_1,
         TAX_CODE_2,
         TAX_CODE_3,
         TAX_CODE_4,
         TAX_CODE_5,
         TAX_CODE_6,
         TAX_CODE_7,
         TAX_CODE_8,
         TAX_CODE_9,
         TAX_CODE_10,
         TAX_CODE_11,
         TAX_CODE_12,
         TAX_CODE_13
  FROM COMPANIES
  JOIN COMPANY_STRINGS ON COMPANY_STRINGS.COMPANY = :P_COMPANY and COMPANY_STRINGS.LANGUAGE = :P_LANGUAGE AND COMPANY_STRINGS.ID = COMPANIES.ID
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = COMPANIES.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE COMPANIES.ID = :P_COMPANY AND COMPANIES.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE,
       :CODE, :NAME, :HIDE, :PARENT, :TEAM,
       :OWNER_NAME, :SHORT_NAME, :PHONE, :FAX,
       :ADDRESS, :TRADE_TYPE, :TRADE_FIELD, :WEBSITE, :EMAIL, :DIRECTOR,
       :CHIEF_ACCOUNTANT, :CASHIER, :STOREKEEPER, :GENERAL_ACCOUNTANT,
       :PAYMENT_ACCOUNTANT, :LOGO, :SLOGAN,
       :PREPARED_PERSON, :DOCUMENT_PERSON, :CASHIER_CAPTION, :CHIEF_ACCOUNTANT_CAPTION, :DIRECTOR_CAPTION, :GENERAL_ACCOUNTANT_CAPTION, :STOREKEEPER_CAPTION, :PAYMENT_ACCOUNTANT_CAPTION, :PREPARED_PERSON_CAPTION, :DOCUMENT_PERSON_CAPTION,
       :PREPARED_PERSON_IS_LOGIN_USER, :DOCUMENT_PERSON_IS_LOGIN_USER,
       :TAX_CODE_1,
       :TAX_CODE_2,
       :TAX_CODE_3,
       :TAX_CODE_4,
       :TAX_CODE_5,
       :TAX_CODE_6,
       :TAX_CODE_7,
       :TAX_CODE_8,
       :TAX_CODE_9,
       :TAX_CODE_10,
       :TAX_CODE_11,
       :TAX_CODE_12,
       :TAX_CODE_13;

    TAX_CODE = IIF(TAX_CODE_1 IS NULL, '', TAX_CODE_1) ||
       IIF(TAX_CODE_2 IS NULL, '', TAX_CODE_2) ||
       IIF(TAX_CODE_3 IS NULL, '', TAX_CODE_3) ||
       IIF(TAX_CODE_4 IS NULL, '', TAX_CODE_4) ||
       IIF(TAX_CODE_5 IS NULL, '', TAX_CODE_5) ||
       IIF(TAX_CODE_6 IS NULL, '', TAX_CODE_6) ||
       IIF(TAX_CODE_7 IS NULL, '', TAX_CODE_7) ||
       IIF(TAX_CODE_8 IS NULL, '', TAX_CODE_8) ||
       IIF(TAX_CODE_9 IS NULL, '', TAX_CODE_9) ||
       IIF(TAX_CODE_10 IS NULL, '', TAX_CODE_10) ||
       IIF(TAX_CODE_11 IS NULL, '', TAX_CODE_11) ||
       IIF(TAX_CODE_12 IS NULL, '', TAX_CODE_12) ||
       IIF(TAX_CODE_13 IS NULL, '', TAX_CODE_13);

    IF(PREPARED_PERSON_IS_LOGIN_USER = 1)THEN
    BEGIN
        SELECT NAME
        FROM ATOM_STRINGS
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_USER_ID
        INTO :PREPARED_PERSON;
    END

    IF(DOCUMENT_PERSON_IS_LOGIN_USER = 1)THEN
    BEGIN
        SELECT NAME
        FROM ATOM_STRINGS
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_USER_ID
        INTO :DOCUMENT_PERSON;
    END

   suspend;
END ^

ALTER PROCEDURE RPT_CUSTOMER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_OBJECT0 DM_ID)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
TAX_CODE DM_TAX_CODE,
PHONE DM_PHONE,
FAX DM_FAX,
ADDRESS DM_ADDRESS,
WEBSITE DM_WEBSITE,
EMAIL DM_EMAIL,
DIRECTOR DM_PERSON_NAME,
CHIEF_ACCOUNTANT DM_PERSON_NAME,
BANK_NAME DM_NAME,
BANK_PROVINCE DM_NAME)
AS 
BEGIN
    SELECT CODE, NAME, TAX_CODE, PHONE, FAX, ADDRESS, WEBSITE, EMAIL, DIRECTOR, CHIEF_ACCOUNTANT, BANK_NAME, BANK_PROVINCE
    FROM CUSTOMERS
    JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY and CUSTOMER_STRINGS.LANGUAGE = :P_LANGUAGE AND CUSTOMER_STRINGS.ID = CUSTOMERS.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CUSTOMERS.ID
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    WHERE CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = :P_OBJECT0
    INTO :CODE, :NAME, :TAX_CODE, :PHONE, :FAX, :ADDRESS, :WEBSITE, :EMAIL, :DIRECTOR, :CHIEF_ACCOUNTANT, :BANK_NAME, :BANK_PROVINCE;

    SUSPEND;
END ^

ALTER PROCEDURE RPT_DANG_KY_CHUNG_TU_GHI_SO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
CONTENT DM_CONTENT,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
NOTE DM_NOTE)
AS 
DECLARE VARIABLE ID DM_ID;
BEGIN
    FOR
        SELECT RECORDED_DOCUMENTS.ID, CODE, INPUT_DATE, RECORDED_DOCUMENTS.CONTENT, PROTON_STRINGS.NOTE
        FROM RECORDED_DOCUMENTS
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = RECORDED_DOCUMENTS.ID
        WHERE RECORDED_DOCUMENTS.COMPANY = :P_COMPANY AND RECORDED_DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        ORDER BY INPUT_DATE, CODE
        INTO :ID, :CODE, :INPUT_DATE, :CONTENT, :NOTE
    DO
    BEGIN
        SELECT SUM(SUM_OF_MONEY)
        FROM RECORDED_DOCUMENT_ENTRIES
        WHERE RECORDED_DOCUMENT_ENTRIES.COMPANY = :P_COMPANY AND RECORDED_DOCUMENT_ENTRIES.RECORDED_DOCUMENT = :ID
        INTO :OFFICIAL_SUM_OF_MONEY;

        IF(OFFICIAL_SUM_OF_MONEY IS NULL)THEN OFFICIAL_SUM_OF_MONEY = 0;

        IF(OFFICIAL_SUM_OF_MONEY <> 0)THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DANH_MUC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_OBJECTTYPE DM_ID)
RETURNS (CODE DM_CODE,
NAME DM_NAME)
