        FROM RPT_DOCUMENT_DOUBLE_ENTRY_GOODS(:P_LANGUAGE, :P_COMPANY, :P_ID)
        GROUP BY DEBIT_ACCOUNT_CODE
        INTO :ACCOUNT_CODE, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        SUSPEND;
    END

    SIDE = 'Có:';
    FOR
        SELECT CREDIT_ACCOUNT_CODE, SUM(OFFICIAL_SUM_OF_MONEY)
        FROM RPT_DOCUMENT_DOUBLE_ENTRY_GOODS(:P_LANGUAGE, :P_COMPANY, :P_ID)
        GROUP BY CREDIT_ACCOUNT_CODE
        INTO :ACCOUNT_CODE, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
