    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_DATE_TO_DATE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_ACCOUNT DM_ID,
P_SIDE_TYPE DM_SIDE,
P_CODE DM_CODE,
P_CONTENT DM_CONTENT,
P_PERSON_NAME DM_PERSON_NAME,
P_PERSON_ADDRESS DM_ADDRESS)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
OBJECT DM_ID,
OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
VOUCHER_DATE DM_DATE,
EMPLOYEE DM_ID,
EMPLOYEE_CODE DM_CODE,
EMPLOYEE_NAME DM_NAME,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
PERSON_NAME_PRINT DM_PERSON_NAME,
CONTENT DM_CONTENT,
DEBIT_ACCOUNTS DM_NOTE,
CREDIT_ACCOUNTS DM_NOTE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
DECLARE VARIABLE OTHERS DM_OTHER_SETTINGS;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE NUMBER DM_INTEGER;
BEGIN
    SELECT ACCOUNTING_SETTINGS.OTHERS
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :OTHERS;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    NUMBER = 1;
    WHILE(P_TU_NGAY <= P_DEN_NGAY)
    DO
    BEGIN
        SELECT IIF(:P_SIDE_TYPE = 0, DEBIT, CREDIT)
        FROM INT_PS_1_TK_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_TU_NGAY)
        INTO :SUM_OF_MONEY;

        IF(SUM_OF_MONEY > 0)THEN
        BEGIN
            CODE = P_CODE || '-' || NUMBER;
            INPUT_DATE = P_TU_NGAY;
            VOUCHER_DATE = P_TU_NGAY;
            CONTENT = :P_CONTENT;
            PERSON_NAME = P_PERSON_NAME;
            PERSON_ADDRESS = P_PERSON_ADDRESS;



            IF(P_SIDE_TYPE = 0)THEN
            BEGIN
                DEBIT_ACCOUNTS = ACCOUNT_CODE;

                SELECT LIST(ACCOUNT_CODE, ',')
                FROM RPT_SO_TONG_HOP_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_ACCOUNT, NULL, NULL, 0, :P_TU_NGAY, :P_TU_NGAY)
                WHERE RPT_SO_TONG_HOP_TAI_KHOAN.RISING_DEBIT <> 0
                INTO :CREDIT_ACCOUNTS;
            END
            ELSE
            BEGIN
                SELECT LIST(ACCOUNT_CODE, ',')
                FROM RPT_SO_TONG_HOP_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_ACCOUNT, NULL, NULL, 0, :P_TU_NGAY, :P_TU_NGAY)
                WHERE RPT_SO_TONG_HOP_TAI_KHOAN.RISING_CREDIT <> 0
                INTO :DEBIT_ACCOUNTS;

                CREDIT_ACCOUNTS = ACCOUNT_CODE;
            END

            SUM_ALL = SUM_OF_MONEY;
            SUM_OF_TAX = 0;

            NUMBER = NUMBER + 1;

            SUSPEND;
        END

        P_TU_NGAY = DATEADD(DAY, 1, P_TU_NGAY);
    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_DOUBLE_ENTRY (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
DEBIT_ACCOUNT_NAME DM_NAME,
DEBIT_OBJECT0_CODE DM_CODE,
DEBIT_OBJECT0_NAME DM_NAME,
DEBIT_OBJECT1_CODE DM_CODE,
DEBIT_OBJECT1_NAME DM_NAME,
DEBIT_OBJECT2_CODE DM_CODE,
DEBIT_OBJECT2_NAME DM_NAME,
CREDIT_ACCOUNT_CODE DM_CODE,
