        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.ACCOUNT NOT IN (SELECT ID FROM ACCOUNTS WHERE BIN_AND(ACCOUNT_TYPES, 1) = 1)
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT NOT IN (SELECT ID FROM ACCOUNTS WHERE BIN_AND(ACCOUNT_TYPES, 2) = 2)
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID
        INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, CONTENT,
        :DEBIT_ACCOUNT, :DEBIT_OBJECT0, :DEBIT_OBJECT1, :DEBIT_OBJECT2,
        :CREDIT_ACCOUNT, :CREDIT_OBJECT0, :CREDIT_OBJECT1, :CREDIT_OBJECT2,
        :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY, :SUM_OF_TAX
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CURRENCY
        INTO :CURRENCY_CODE;

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_ACCOUNT
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_ACCOUNT
        INTO :DEBIT_ACCOUNT_CODE, :DEBIT_ACCOUNT_NAME;

        IF(DEBIT_OBJECT0 IS NULL)THEN
        BEGIN
            DEBIT_OBJECT0_CODE = NULL;
            DEBIT_OBJECT0_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME, UNIT
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_OBJECT0
            LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :DEBIT_OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT0
            INTO :DEBIT_OBJECT0_CODE, :DEBIT_OBJECT0_NAME, :DEBIT_OBJECT0_UNIT;

        IF(DEBIT_OBJECT1 IS NULL)THEN
        BEGIN
            DEBIT_OBJECT1_CODE = NULL;
            DEBIT_OBJECT1_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_OBJECT1
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT1
            INTO :DEBIT_OBJECT1_CODE, :DEBIT_OBJECT1_NAME;

        IF(DEBIT_OBJECT2 IS NULL)THEN
        BEGIN
            DEBIT_OBJECT2_CODE = NULL;
            DEBIT_OBJECT2_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_OBJECT2
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_OBJECT2
            INTO :DEBIT_OBJECT2_CODE, :DEBIT_OBJECT2_NAME;

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_ACCOUNT
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_ACCOUNT
        INTO :CREDIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_NAME;

        IF(CREDIT_OBJECT0 IS NULL)THEN
        BEGIN
            CREDIT_OBJECT0_CODE = NULL;
            CREDIT_OBJECT0_NAME = NULL;
            CREDIT_OBJECT0_WARRANTY = NULL;
        END
        ELSE
            SELECT CODE, NAME, UNIT, IIF(WARRANTY_MONTHS = 0, NULL, WARRANTY_MONTHS || ' tháng')
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_OBJECT0
            LEFT JOIN GOODS ON GOODS.COMPANY = :P_COMPANY AND GOODS.ID = :CREDIT_OBJECT0
            LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :CREDIT_OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT0
            INTO :CREDIT_OBJECT0_CODE, :CREDIT_OBJECT0_NAME, :CREDIT_OBJECT0_UNIT, :CREDIT_OBJECT0_WARRANTY;

        IF(CREDIT_OBJECT1 IS NULL)THEN
        BEGIN
            CREDIT_OBJECT1_CODE = NULL;
            CREDIT_OBJECT1_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_OBJECT1
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT1
            INTO :CREDIT_OBJECT1_CODE, :CREDIT_OBJECT1_NAME;

        IF(CREDIT_OBJECT2 IS NULL)THEN
        BEGIN
            CREDIT_OBJECT2_CODE = NULL;
            CREDIT_OBJECT2_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_OBJECT2
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT2
            INTO :CREDIT_OBJECT2_CODE, :CREDIT_OBJECT2_NAME;

        SUSPEND;
    END
END ^

