ALTER PROCEDURE RPT_DOCUMENT_DOUBLE_ENTRY_PKT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
DEBIT_ACCOUNT_NAME DM_NAME,
CREDIT_ACCOUNT_CODE DM_CODE,
CREDIT_ACCOUNT_NAME DM_NAME,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE)
AS 
DECLARE VARIABLE ENTRY_COUNT DM_INTEGER;
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
BEGIN
    FOR
        SELECT DEBIT.ACCOUNT, CREDIT.ACCOUNT,
        COUNT(*), SUM(DEBIT.FOREIGN_SUM_OF_MONEY), SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID
        GROUP BY DEBIT.ACCOUNT, CREDIT.ACCOUNT
        INTO :DEBIT_ACCOUNT, :CREDIT_ACCOUNT, :ENTRY_COUNT, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        IF(ENTRY_COUNT = 1)THEN
        BEGIN
            SELECT ENTRY_BASE_STRINGS.CONTENT
            FROM ENTRIES
            JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.ACCOUNT = :DEBIT_ACCOUNT
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.ACCOUNT = :CREDIT_ACCOUNT
            WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.DOCUMENT = :P_ID
            INTO :CONTENT;
        END
        ELSE
        BEGIN
            SELECT DOCUMENT_BASE_STRINGS.CONTENT
            FROM DOCUMENT_BASE_STRINGS
            WHERE DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = :P_ID
            INTO :CONTENT;
        END

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEBIT_ACCOUNT
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_ACCOUNT
        INTO :DEBIT_ACCOUNT_CODE, :DEBIT_ACCOUNT_NAME;

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_ACCOUNT
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_ACCOUNT
        INTO :CREDIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_NAME;

        SUSPEND;
    END
END ^

