            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :CREDIT_OBJECT2
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_OBJECT2
            INTO :CREDIT_OBJECT2_CODE, :CREDIT_OBJECT2_NAME;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_GIAY_BAO_CO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (FROM_NAME DM_NAME,
FROM_BANK_ACCOUNT DM_CODE,
FROM_BANK_ACCOUNT_SHORT DM_CODE,
FROM_BANK_NAME DM_NAME,
LP DM_ADDITION_INFO,
TO_BANK_ACCOUNT DM_CODE,
TO_BANK_ACCOUNT_FULL DM_CODE,
TO_BANK_NAME DM_NAME,
TO_BRANCH_NAME DM_NAME,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
SUM_ALL DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.ORIGINAL_VOUCHERS, DOCUMENTS.VOUCHER_DATE
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
        INTO :FROM_NAME, :FROM_BANK_ACCOUNT, :FROM_BANK_NAME, :LP, :CONTENT, :ORIGINAL_VOUCHERS, :VOUCHER_DATE
    DO
    BEGIN
        IF(FROM_BANK_ACCOUNT IS NULL OR FROM_BANK_ACCOUNT = '')THEN
        BEGIN
            
            SELECT FIRST 1 ATOM_STRINGS.NAME, CUSTOMERS.BANK_ACCOUNT, CUSTOMER_STRINGS.BANK_NAME
            FROM CREDIT_DEBIT
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
            JOIN CUSTOMERS ON CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = CREDIT_DEBIT.OBJECT0
            JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY AND CUSTOMER_STRINGS.ID = CUSTOMERS.ID
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CUSTOMERS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.OBJECT0 IS NOT NULL
            INTO :FROM_NAME, :FROM_BANK_ACCOUNT, :FROM_BANK_NAME;
        END

        FROM_BANK_ACCOUNT_SHORT = LEFT(FROM_BANK_ACCOUNT, 3);

        
        SELECT FIRST 1 ATOMS.CODE, UPPER(BANK_ACCOUNT_STRINGS.BANK_NAME), UPPER(BANK_ACCOUNT_STRINGS.BRANCH_NAME)
        FROM CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN BANK_ACCOUNTS ON BANK_ACCOUNTS.COMPANY = :P_COMPANY AND BANK_ACCOUNTS.ID = CREDIT_DEBIT.OBJECT0
        JOIN BANK_ACCOUNT_STRINGS ON BANK_ACCOUNT_STRINGS.COMPANY = :P_COMPANY AND BANK_ACCOUNT_STRINGS.ID = BANK_ACCOUNTS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BANK_ACCOUNTS.ID
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.OBJECT0 IS NOT NULL
        INTO :TO_BANK_ACCOUNT_FULL, :TO_BANK_NAME, :TO_BRANCH_NAME;

        TO_BANK_ACCOUNT = LEFT(TO_BANK_ACCOUNT_FULL, 12);

        SELECT SUM_ALL
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :P_ID)
        INTO :SUM_ALL;
    
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_HD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
OBJECT DM_ID,
OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
OBJECT_ADDRESS DM_ADDRESS,
OBJECT_TAX_CODE DM_TAX_CODE,
VOUCHER_DATE DM_DATE,
EMPLOYEE DM_ID,
EMPLOYEE_CODE DM_CODE,
EMPLOYEE_NAME DM_NAME,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
PERSON_NAME_PRINT DM_PERSON_NAME,
CONTENT DM_CONTENT,
DEBIT_ACCOUNTS DM_NOTE,
CREDIT_ACCOUNTS DM_NOTE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE,
INVOICES DM_NAME)
AS 
DECLARE VARIABLE OBJECT_TYPE DM_ID;
DECLARE VARIABLE OTHERS DM_OTHER_SETTINGS;
DECLARE VARIABLE UU_TIEN_TEN DM_BOOL = 0;
BEGIN
    SELECT ACCOUNTING_SETTINGS.OTHERS
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :OTHERS;

    IF(BIN_AND(OTHERS, 2048) <> 0)THEN
        UU_TIEN_TEN = 1;

    FOR
        SELECT DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.NOTE, DOCUMENTS.CODE || '-' || NUMBER,
        INPUT_DATE, ORIGINAL_VOUCHERS, VOUCHER_DATE,
        ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, PERSON_NAME, PERSON_ADDRESS, DOCUMENT_BASE_STRINGS.CONTENT,
        OBJECT, EMPLOYEE
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
        INTO :ID, :NOTE, :CODE,
        :INPUT_DATE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE,
        :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT,
        :OBJECT, :EMPLOYEE
    DO
    BEGIN
        
        IF(OBJECT IS NULL)THEN
        BEGIN
            SELECT FIRST 1 CREDIT_DEBIT.OBJECT0
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.OBJECT0 IS NOT NULL AND CREDIT_DEBIT.ENTRY IN
            (
                SELECT ENTRIES.ID
                FROM ENTRIES
                WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1
            )
            INTO :OBJECT;
        END

        IF(OBJECT IS NULL)THEN
        BEGIN
            IF(UU_TIEN_TEN = 1)THEN
            BEGIN
                OBJECT_NAME = PERSON_NAME;
                OBJECT_ADDRESS = PERSON_ADDRESS;

                IF(OBJECT_NAME IS NULL OR OBJECT_NAME = '')THEN
                BEGIN
                    SELECT INVOICE_STRINGS.CUSTOMER_NAME, INVOICE_STRINGS.CUSTOMER_ADDRESS, INVOICES.CUSTOMER_TAX_CODE
                    FROM INVOICES
                    JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
                    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :P_ID
                    INTO :OBJECT_NAME, :OBJECT_ADDRESS, :OBJECT_TAX_CODE;
                END
                ELSE
                    SELECT INVOICES.CUSTOMER_TAX_CODE
                    FROM INVOICES
                    JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
                    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :P_ID
                    INTO :OBJECT_TAX_CODE;
            END
            ELSE
            BEGIN
                SELECT INVOICE_STRINGS.CUSTOMER_NAME, INVOICE_STRINGS.CUSTOMER_ADDRESS, INVOICES.CUSTOMER_TAX_CODE
                FROM INVOICES
                JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
                WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :P_ID
                INTO :OBJECT_NAME, :OBJECT_ADDRESS, :OBJECT_TAX_CODE;

                IF(OBJECT_NAME IS NULL)THEN
                BEGIN
                    OBJECT_NAME = PERSON_NAME;
                    OBJECT_ADDRESS = PERSON_ADDRESS;
                END
            END
        END
        ELSE
        BEGIN
            IF(UU_TIEN_TEN = 1)THEN
            BEGIN
                OBJECT_NAME = PERSON_NAME;
                OBJECT_ADDRESS = PERSON_ADDRESS;

                IF(OBJECT_NAME IS NULL OR OBJECT_NAME = '')THEN
                BEGIN
                    SELECT CODE, NAME, OBJECT_TYPE
                    FROM ATOMS
                    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
                    INTO :OBJECT_CODE, :OBJECT_NAME, :OBJECT_TYPE;

                    
                    IF(OBJECT_TYPE = 36)THEN
                    BEGIN
                        SELECT CUSTOMERS.TAX_CODE, CUSTOMER_STRINGS.ADDRESS
                        FROM CUSTOMERS
                        JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY AND CUSTOMER_STRINGS.LANGUAGE = :P_LANGUAGE AND CUSTOMER_STRINGS.ID = :OBJECT
                        WHERE CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = :OBJECT
                        INTO :OBJECT_TAX_CODE, :OBJECT_ADDRESS;
                    END
                END
                ELSE IF(OBJECT_ADDRESS IS NULL OR OBJECT_ADDRESS = '')THEN
                BEGIN
                    SELECT OBJECT_TYPE
                    FROM ATOMS
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
                    INTO :OBJECT_TYPE;

                    
                    IF(OBJECT_TYPE = 36)THEN
                    BEGIN
                        SELECT CUSTOMERS.TAX_CODE, CUSTOMER_STRINGS.ADDRESS
                        FROM CUSTOMERS
                        JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY AND CUSTOMER_STRINGS.LANGUAGE = :P_LANGUAGE AND CUSTOMER_STRINGS.ID = :OBJECT
                        WHERE CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = :OBJECT
                        INTO :OBJECT_TAX_CODE, :OBJECT_ADDRESS;
                    END
                END
                ELSE
                BEGIN
                    SELECT OBJECT_TYPE
                    FROM ATOMS
                    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
                    INTO :OBJECT_TYPE;

                    
                    IF(OBJECT_TYPE = 36)THEN
                    BEGIN
                        SELECT CUSTOMERS.TAX_CODE
                        FROM CUSTOMERS
                        JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY AND CUSTOMER_STRINGS.LANGUAGE = :P_LANGUAGE AND CUSTOMER_STRINGS.ID = :OBJECT
                        WHERE CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = :OBJECT
                        INTO :OBJECT_TAX_CODE;
                    END
                END
            END
            ELSE
            BEGIN
                SELECT CODE, NAME, OBJECT_TYPE
                FROM ATOMS
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
                INTO :OBJECT_CODE, :OBJECT_NAME, :OBJECT_TYPE;

                
                IF(OBJECT_TYPE = 36)THEN
                BEGIN
                    SELECT CUSTOMERS.TAX_CODE, CUSTOMER_STRINGS.ADDRESS
                    FROM CUSTOMERS
                    JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY AND CUSTOMER_STRINGS.LANGUAGE = :P_LANGUAGE AND CUSTOMER_STRINGS.ID = :OBJECT
                    WHERE CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = :OBJECT
                    INTO :OBJECT_TAX_CODE, :OBJECT_ADDRESS;
                END
            END
        END

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = :EMPLOYEE
        INTO :EMPLOYEE_CODE, :EMPLOYEE_NAME;

        SELECT LIST(ATOMS.CODE, ',')
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID IN
        (
            SELECT CREDIT_DEBIT.ACCOUNT
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND
                CREDIT_DEBIT.ENTRY IN
                (
                    SELECT ENTRIES.ID
                    FROM ENTRIES
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1
                )
        )
        INTO :DEBIT_ACCOUNTS;

        SELECT LIST(ATOMS.CODE, ',')
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID IN
        (
            SELECT CREDIT_DEBIT.ACCOUNT
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND
                CREDIT_DEBIT.ENTRY IN
                (
                    SELECT ENTRIES.ID
                    FROM ENTRIES
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1
                )
        )
        INTO :CREDIT_ACCOUNTS;

        SELECT LIST(SERIAL_CODE || '-' || INVOICE_CODE, ',')
        FROM RPT_DOCUMENT_INVOICE(:P_LANGUAGE, :P_COMPANY, :P_ID)
        INTO :INVOICES;

        SELECT SUM_OF_MONEY, SUM_OF_TAX, SUM_ALL
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :P_ID)
        INTO :SUM_OF_MONEY, :SUM_OF_TAX, :SUM_ALL;

        IF(BIN_AND(OTHERS, 256) <> 0)THEN PERSON_NAME_PRINT = PERSON_NAME;
    
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_INVOICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT,
BANK_ACCOUNT DM_NAME,
BUYER_NAME DM_NAME,
CUSTOMER_NAME DM_NAME,
CUSTOMER_ADDRESS DM_ADDRESS,
CUSTOMER_TAX_CODE DM_TAX_CODE,
GOODS DM_GOODS,
UNIT DM_UNIT,
INPUT_DATE DM_DATE,
INVOICE_CODE DM_INVOICE_CODE,
INVOICE_DATE DM_DATE,
INVOICE_TYPE DM_INVOICE_TYPE,
INVOICE_TEMPLATE DM_INVOICE_TEMPLATE,
SERIAL_CODE DM_SERIAL_CODE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
VAT_PERCENT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT INVOICES.ID,ORDINAL, NOTE,
            FORMS_OF_PAYMENT, BANK_ACCOUNT, BUYER_NAME,
            CUSTOMER_NAME, CUSTOMER_ADDRESS, INVOICES.INPUT_DATE,
            INVOICE_CODE, INVOICE_DATE, SERIAL_CODE, SUM_OF_MONEY, SUM_OF_TAX, CUSTOMER_TAX_CODE, VAT_PERCENT,
            GOODS, UNIT, INVOICES.INVOICE_TEMPLATE, INVOICE_TYPE
        FROM INVOICES
        JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
        WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.DOCUMENT = :P_ID
        INTO :ID, :ORDINAL, :NOTE,
            :FORMS_OF_PAYMENT, :BANK_ACCOUNT, :BUYER_NAME,
            :CUSTOMER_NAME, :CUSTOMER_ADDRESS, :INPUT_DATE,
            :INVOICE_CODE, :INVOICE_DATE, :SERIAL_CODE, :SUM_OF_MONEY, :SUM_OF_TAX, :CUSTOMER_TAX_CODE, :VAT_PERCENT,
            :GOODS, :UNIT, :INVOICE_TEMPLATE, :INVOICE_TYPE
    DO
        SUSPEND;
END ^

ALTER PROCEDURE RPT_DOCUMENT_NV (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_DOCUMENT_CODE,
ADDITION_INFO_1 DM_ADDITION_INFO,
ADDITION_INFO_2 DM_ADDITION_INFO,
ADDITION_INFO_3 DM_ADDITION_INFO,
ADDITION_INFO_4 DM_ADDITION_INFO,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
OBJECT_TYPE_NAME DM_NAME,
OBJECT DM_ID,
OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
VOUCHER_DATE DM_DATE,
EMPLOYEE DM_ID,
EMPLOYEE_CODE DM_CODE,
EMPLOYEE_NAME DM_NAME,
PERSON_NAME DM_PERSON_NAME,
PERSON_ADDRESS DM_ADDRESS,
PERSON_NAME_PRINT DM_PERSON_NAME,
CONTENT DM_CONTENT,
DEBIT_ACCOUNTS DM_NOTE,
CREDIT_ACCOUNTS DM_NOTE,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
DECLARE VARIABLE OTHERS DM_OTHER_SETTINGS;
DECLARE VARIABLE ATOM_USE_OTHER_NAME DM_BOOL;
BEGIN
    SELECT ACCOUNTING_SETTINGS.OTHERS
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :OTHERS;

    FOR
        SELECT DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.NOTE, DOCUMENTS.CODE || '-' || NUMBER,
        INPUT_DATE, ORIGINAL_VOUCHERS, VOUCHER_DATE,
        ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, PERSON_NAME, PERSON_ADDRESS, DOCUMENT_BASE_STRINGS.CONTENT,
        OBJECT, EMPLOYEE,
        DOCUMENT_TEAMS.ATOM_USE_OTHER_NAME, DOCUMENT_TEAM_STRINGS.ATOM_NAME
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.LANGUAGE= :P_LANGUAGE AND DOCUMENT_TEAM_STRINGS.ID = DOCUMENTS.TEAM
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
        INTO :ID, :NOTE, :CODE,
        :INPUT_DATE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE,
        :ADDITION_INFO_1, :ADDITION_INFO_2, :ADDITION_INFO_3, :ADDITION_INFO_4, :PERSON_NAME, :PERSON_ADDRESS, :CONTENT,
        :OBJECT, :EMPLOYEE,
        :ATOM_USE_OTHER_NAME, :OBJECT_TYPE_NAME
    DO
    BEGIN
        SELECT CODE, ATOM_STRINGS.NAME, IIF(:ATOM_USE_OTHER_NAME = 0, OBJECT_TYPES.NAME, :OBJECT_TYPE_NAME) || ': ' || ATOM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
        JOIN OBJECT_TYPES ON OBJECT_TYPES.ID = ATOMS.OBJECT_TYPE
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT
        INTO :OBJECT_CODE, :OBJECT_NAME, :OBJECT_TYPE_NAME;

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = :EMPLOYEE
        INTO :EMPLOYEE_CODE, :EMPLOYEE_NAME;

        SELECT LIST(ATOMS.CODE, ',')
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID IN
        (
            SELECT CREDIT_DEBIT.ACCOUNT
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND
            CREDIT_DEBIT.ACCOUNT NOT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 1) = 1) AND
                CREDIT_DEBIT.ENTRY IN
                (
                    SELECT ENTRIES.ID
                    FROM ENTRIES
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1
                )
        )
        INTO :DEBIT_ACCOUNTS;

        SELECT LIST(ATOMS.CODE, ',')
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID IN
        (
            SELECT CREDIT_DEBIT.ACCOUNT
            FROM CREDIT_DEBIT
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND
            CREDIT_DEBIT.ACCOUNT NOT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 2) = 2) AND
                CREDIT_DEBIT.ENTRY IN
                (
                    SELECT ENTRIES.ID
                    FROM ENTRIES
                    WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1
                )
        )
        INTO :CREDIT_ACCOUNTS;

        SELECT SUM_OF_MONEY, SUM_ALL
        FROM DOCUMENT_SUMS_NV(:P_LANGUAGE, :P_COMPANY, :P_ID)
        INTO :SUM_OF_MONEY, :SUM_ALL;

        SUM_OF_TAX = 0;

        IF(BIN_AND(OTHERS, 256) <> 0)THEN PERSON_NAME_PRINT = PERSON_NAME;
    
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_SINGLE_ENTRY (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
VAT_PERCENT DM_DOUBLE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
ACCOUNT_NAME DM_NAME,
OBJECT0_CODE DM_CODE,
OBJECT0_NAME DM_NAME,
OBJECT1_CODE DM_CODE,
OBJECT1_NAME DM_NAME,
OBJECT2_CODE DM_CODE,
OBJECT2_NAME DM_NAME,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
BEGIN
    FOR
        SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, VAT_PERCENT, ENTRY_BASE_STRINGS.CONTENT,
        CREDIT_DEBIT.ACCOUNT, CREDIT_DEBIT.OBJECT0, CREDIT_DEBIT.OBJECT1, CREDIT_DEBIT.OBJECT2,
        CREDIT_DEBIT.AMOUNT, CREDIT_DEBIT.PRICE, CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 0 AND ENTRIES.DOCUMENT = :P_ID
        INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :VAT_PERCENT, CONTENT,
        :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2,
        :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CURRENCY
        INTO :CURRENCY_CODE;

        SELECT CODE, NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :ACCOUNT
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :ACCOUNT
        INTO :ACCOUNT_CODE, :ACCOUNT_NAME;

        IF(OBJECT0 IS NULL)THEN
        BEGIN
            OBJECT0_CODE = NULL;
            OBJECT0_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE, :OBJECT0_NAME;

        IF(OBJECT1 IS NULL)THEN
        BEGIN
            OBJECT1_CODE = NULL;
            OBJECT1_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT1
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE, :OBJECT1_NAME;

        IF(OBJECT2 IS NULL)THEN
        BEGIN
            OBJECT2_CODE = NULL;
            OBJECT2_NAME = NULL;
        END
        ELSE
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT2
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
            INTO :OBJECT2_CODE, :OBJECT2_NAME;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DOCUMENT_UNC_VIETINBANK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (CODE DM_CODE,
INPUT_DATE DM_DATE,
FROM_BANK_ACCOUNT DM_CODE,
FROM_BANK_NAME DM_NAME,
FROM_BRANCH_NAME DM_NAME,
TO_BENEFICIARY_NAME DM_NAME,
TO_BANK_ACCOUNT DM_CODE,
TO_BANK_NAME DM_NAME,
TO_BANK_PROVINCE DM_NAME,
CONTENT DM_CONTENT,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT CODE || '-' || NUMBER, INPUT_DATE, ADDITION_INFO_1, ADDITION_INFO_2, ADDITION_INFO_3, ADDITION_INFO_4, DOCUMENT_BASE_STRINGS.CONTENT
        FROM DOCUMENTS
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = :P_ID
        INTO :CODE, :INPUT_DATE, :TO_BENEFICIARY_NAME, :TO_BANK_ACCOUNT, :TO_BANK_NAME, TO_BANK_PROVINCE, :CONTENT
    DO
    BEGIN
        
        SELECT FIRST 1 ATOMS.CODE, BANK_ACCOUNT_STRINGS.BANK_NAME, BANK_ACCOUNT_STRINGS.BRANCH_NAME
        FROM CREDIT_DEBIT
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
        JOIN BANK_ACCOUNTS ON BANK_ACCOUNTS.COMPANY = :P_COMPANY AND BANK_ACCOUNTS.ID = CREDIT_DEBIT.OBJECT0
        JOIN BANK_ACCOUNT_STRINGS ON BANK_ACCOUNT_STRINGS.COMPANY = :P_COMPANY AND BANK_ACCOUNT_STRINGS.ID = BANK_ACCOUNTS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = BANK_ACCOUNTS.ID
        WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.OBJECT0 IS NOT NULL
        INTO :FROM_BANK_ACCOUNT, :FROM_BANK_NAME, :FROM_BRANCH_NAME;

        IF(TO_BANK_ACCOUNT IS NULL OR TO_BANK_ACCOUNT = '')THEN
        BEGIN
            
            SELECT FIRST 1 ATOM_STRINGS.NAME, CUSTOMERS.BANK_ACCOUNT, CUSTOMER_STRINGS.BANK_NAME, CUSTOMER_STRINGS.BANK_PROVINCE
            FROM CREDIT_DEBIT
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = :P_ID AND ENTRIES.ENTRY_TYPE = 1 AND ENTRIES.ID = CREDIT_DEBIT.ENTRY
            JOIN CUSTOMERS ON CUSTOMERS.COMPANY = :P_COMPANY AND CUSTOMERS.ID = CREDIT_DEBIT.OBJECT0
            JOIN CUSTOMER_STRINGS ON CUSTOMER_STRINGS.COMPANY = :P_COMPANY AND CUSTOMER_STRINGS.ID = CUSTOMERS.ID
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = CUSTOMERS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.OBJECT0 IS NOT NULL
            INTO :TO_BENEFICIARY_NAME, :TO_BANK_ACCOUNT, :TO_BANK_NAME, :TO_BANK_PROVINCE;
        END

        SELECT SUM_OF_MONEY, SUM_OF_TAX, SUM_ALL
        FROM DOCUMENT_SUMS(:P_LANGUAGE, :P_COMPANY, :P_ID)
        INTO :SUM_OF_MONEY, :SUM_OF_TAX, :SUM_ALL;
    
        SUSPEND;
    END
END ^

