ALTER PROCEDURE RPT_DT01_PS_TK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE_0 DM_CODE,
NAME_0 DM_NAME,
CODE_1 DM_CODE,
NAME_1 DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT ATOMS_0.CODE, ATOM_STRINGS_0.NAME, ATOMS_1.CODE, ATOM_STRINGS_1.NAME, SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(RISING_DEBIT), SUM(RISING_CREDIT)
        FROM
        (
            SELECT OBJECT0, OBJECT1, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 RISING_DEBIT, 0 RISING_CREDIT
            FROM INT_SD_1_TK_DT0_DT1_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT0, OBJECT1, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT RISING_DEBIT, CREDIT RISING_CREDIT
            FROM INT_PS_1_TK_DT0_DT1_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        ) RESULTS
        JOIN ATOMS ATOMS_0 ON ATOMS_0.COMPANY = :P_COMPANY AND ATOMS_0.ID = RESULTS.OBJECT0
        JOIN ATOM_STRINGS ATOM_STRINGS_0 ON ATOM_STRINGS_0.COMPANY = :P_COMPANY AND ATOM_STRINGS_0.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS_0.ID = RESULTS.OBJECT0
        JOIN ATOMS ATOMS_1 ON ATOMS_1.COMPANY = :P_COMPANY AND ATOMS_1.ID = RESULTS.OBJECT1
        JOIN ATOM_STRINGS ATOM_STRINGS_1 ON ATOM_STRINGS_1.COMPANY = :P_COMPANY AND ATOM_STRINGS_1.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS_1.ID = RESULTS.OBJECT1
        GROUP BY OBJECT0, ATOMS_0.CODE, ATOM_STRINGS_0.NAME, OBJECT1, ATOMS_1.CODE, ATOM_STRINGS_1.NAME
        ORDER BY ATOMS_0.CODE, ATOM_STRINGS_0.NAME, ATOMS_1.CODE, ATOM_STRINGS_1.NAME
        INTO :CODE_0, :NAME_0, :CODE_1, :NAME_1, :BEGINNING_DEBIT, :BEGINNING_CREDIT, :RISING_DEBIT, :RISING_CREDIT
    DO
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

        IF(ENDING_DEBIT > 0)THEN
            ENDING_CREDIT = 0;
        ELSE
        BEGIN
            ENDING_CREDIT = ABS(ENDING_DEBIT);
            ENDING_DEBIT = 0;
        END

        IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

