            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DT0_PS_TK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT DM_ID,
CODE DM_CODE,
NAME DM_NAME,
ACCOUNT_CODE DM_CODE,
ACCOUNT_NAME DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
declare variable not154x2 dm_integer;
declare variable double_value dm_double;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 4096)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :NOT154X2;

    SELECT CODE, ATOM_STRINGS.name
    FROM ATOMS
    JOIN ATOM_STRINGS ON ATOM_STRINGS.company = :P_COMPANY AND ATOM_STRINGS.ID = ATOMS.ID AND ATOM_STRINGS.language = :p_language
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE, :account_name;

    IF(NOT154X2 > 0 AND ACCOUNT_CODE NOT STARTING WITH '154')THEN
        NOT154X2 = 0;

    FOR
        SELECT OBJECT0, CODE, NAME, SUM(BEGINNING_DEBIT), SUM(BEGINNING_CREDIT), SUM(RISING_DEBIT), SUM(RISING_CREDIT)
        FROM
        (
            SELECT OBJECT0, DEBIT BEGINNING_DEBIT, CREDIT BEGINNING_CREDIT, 0 RISING_DEBIT, 0 RISING_CREDIT
            FROM INT_SD_1_TK_DT0_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 BEGINNING_DEBIT, 0 BEGINNING_CREDIT, DEBIT RISING_DEBIT, CREDIT RISING_CREDIT
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        ) RESULTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = RESULTS.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = RESULTS.OBJECT0
        GROUP BY OBJECT0, CODE,  NAME
        ORDER BY CODE, NAME
        INTO :OBJECT, :CODE, :NAME, :BEGINNING_DEBIT, :BEGINNING_CREDIT, :RISING_DEBIT, :RISING_CREDIT
    DO
    BEGIN
        IF(NOT154X2 > 0)THEN
        BEGIN
                SELECT OFFICIAL_SUM_OF_MONEY
                FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :OBJECT, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
                INTO :DOUBLE_VALUE;
                RISING_DEBIT = RISING_DEBIT - DOUBLE_VALUE;
                RISING_CREDIT = RISING_CREDIT - DOUBLE_VALUE;
            END

        ENDING_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

        IF(ENDING_DEBIT > 0)THEN
            ENDING_CREDIT = 0;
        ELSE
        BEGIN
            ENDING_CREDIT = ABS(ENDING_DEBIT);
            ENDING_DEBIT = 0;
        END

        IF(BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DT0_PS_TKS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT_1 DM_ID,
P_ACCOUNT_2 DM_ID,
P_ACCOUNT_3 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT DM_ID,
CODE DM_CODE,
NAME DM_NAME,
ACCOUNT_CODE DM_CODE,
ACCOUNT_NAME DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
BEGIN
    FOR
        SELECT object, code, name, account_code, account_name, beginning_debit, beginning_credit, rising_debit, rising_credit, ending_debit, ending_credit
        FROM
        (
            SELECT object, code, name, account_code, account_name, beginning_debit, beginning_credit, rising_debit, rising_credit, ending_debit, ending_credit
            FROM RPT_DT0_PS_TK(:p_language, :p_company, :P_ID, :p_account_1, :p_tu_ngay, :p_den_ngay)
            WHERE :p_account_1 IS NOT NULL

            UNION ALL
    
            SELECT object, code, name, account_code, account_name, beginning_debit, beginning_credit, rising_debit, rising_credit, ending_debit, ending_credit
            FROM RPT_DT0_PS_TK(:p_language, :p_company, :P_ID, :p_account_2, :p_tu_ngay, :p_den_ngay)
            WHERE :p_account_2 IS NOT NULL

            UNION ALL
    
            SELECT object, code, name, account_code, account_name, beginning_debit, beginning_credit, rising_debit, rising_credit, ending_debit, ending_credit
            FROM RPT_DT0_PS_TK(:p_language, :p_company, :P_ID, :p_account_3, :p_tu_ngay, :p_den_ngay)
            WHERE :p_account_3 IS NOT NULL
         )
         ORDER BY object, account_code
         INTO :object, :code, :name, :account_code, :account_name, :beginning_debit, :beginning_credit, :rising_debit, :rising_credit, :ending_debit, :ending_credit
    DO
    BEGIN
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_DT0_PS_TK_TT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    FOR
        SELECT CODE, NAME, SUM(BEGINNING_FOREIGN_DEBIT), SUM(BEGINNING_FOREIGN_CREDIT), SUM(RISING_FOREIGN_DEBIT), SUM(RISING_FOREIGN_CREDIT), SUM(BEGINNING_OFFICIAL_DEBIT), SUM(BEGINNING_OFFICIAL_CREDIT), SUM(RISING_OFFICIAL_DEBIT), SUM(RISING_OFFICIAL_CREDIT)
        FROM
        (
            SELECT OBJECT0, FOREIGN_DEBIT BEGINNING_FOREIGN_DEBIT, FOREIGN_CREDIT BEGINNING_FOREIGN_CREDIT, 0 RISING_FOREIGN_DEBIT, 0 RISING_FOREIGN_CREDIT, OFFICIAL_DEBIT BEGINNING_OFFICIAL_DEBIT, OFFICIAL_CREDIT BEGINNING_OFFICIAL_CREDIT, 0 RISING_OFFICIAL_DEBIT, 0 RISING_OFFICIAL_CREDIT
            FROM INT_SD_1_TK_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 BEGINNING_FOREIGN_DEBIT, 0 BEGINNING_FOREIGN_CREDIT, FOREIGN_DEBIT RISING_FOREIGN_DEBIT, FOREIGN_CREDIT RISING_FOREIGN_CREDIT,0 BEGINNING_OFFICIAL_DEBIT, 0 BEGINNING_OFFICIAL_CREDIT, OFFICIAL_DEBIT RISING_OFFICIAL_DEBIT, OFFICIAL_CREDIT RISING_OFFICIAL_CREDIT
            FROM INT_PS_1_TK_DT0_C_TT(:P_COMPANY, :P_CURRENCY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        ) RESULTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = RESULTS.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = RESULTS.OBJECT0
        GROUP BY OBJECT0, CODE,  NAME
        ORDER BY CODE, NAME
        INTO :CODE, :NAME, :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :RISING_FOREIGN_DEBIT, :RISING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT, :RISING_OFFICIAL_DEBIT, :RISING_OFFICIAL_CREDIT
    DO
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

        IF(ENDING_FOREIGN_DEBIT > 0)THEN
            ENDING_FOREIGN_CREDIT = 0;
        ELSE
        BEGIN
            ENDING_FOREIGN_CREDIT = ABS(ENDING_FOREIGN_DEBIT);
            ENDING_FOREIGN_DEBIT = 0;
        END

        IF(ENDING_OFFICIAL_DEBIT > 0)THEN
            ENDING_OFFICIAL_CREDIT = 0;
        ELSE
        BEGIN
            ENDING_OFFICIAL_CREDIT = ABS(ENDING_OFFICIAL_DEBIT);
            ENDING_OFFICIAL_DEBIT = 0;
        END

        IF(BEGINNING_FOREIGN_DEBIT <> 0 OR BEGINNING_FOREIGN_CREDIT <> 0 OR RISING_FOREIGN_DEBIT <> 0 OR RISING_FOREIGN_CREDIT <> 0 OR ENDING_OFFICIAL_DEBIT <> 0 OR ENDING_OFFICIAL_CREDIT <> 0 AND BEGINNING_OFFICIAL_DEBIT <> 0 OR BEGINNING_OFFICIAL_CREDIT <> 0 OR RISING_OFFICIAL_DEBIT <> 0 OR RISING_OFFICIAL_CREDIT <> 0 OR ENDING_OFFICIAL_DEBIT <> 0 OR ENDING_OFFICIAL_CREDIT <> 0)THEN
            SUSPEND;
    END
END ^

