ALTER PROCEDURE RPT_INVOICE (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (FORMS_OF_PAYMENT DM_FORMS_OF_PAYMENT,
BANK_ACCOUNT DM_NAME,
BUYER_NAME DM_NAME,
CUSTOMER_NAME DM_NAME,
CUSTOMER_ADDRESS DM_ADDRESS,
CUSTOMER_TAX_CODE DM_NAME,
CUSTOMER_TAX_CODE_SPACE_1 DM_NAME,
CUSTOMER_TAX_CODE_SPACE_2 DM_NAME,
CUSTOMER_TAX_CODE_SPACE_3 DM_NAME,
CUSTOMER_TAX_CODE_SPACE_4 DM_NAME,
GOODS DM_GOODS,
UNIT DM_UNIT,
INVOICE_DATE DM_DATE,
INVOICE_YEAR DM_INTEGER,
INVOICE_YEAR_4_SO DM_INTEGER,
SUM_OF_MONEY DM_DOUBLE,
SUM_OF_TAX DM_DOUBLE,
SUM_ALL DM_DOUBLE,
VAT_PERCENT DM_DOUBLE)
AS 
DECLARE VARIABLE LENGTH_TAX_CODE DM_INTEGER;
DECLARE VARIABLE N DM_INTEGER;
DECLARE VARIABLE TAX_CODE DM_NAME;
BEGIN
    SELECT CUSTOMER_NAME, CUSTOMER_ADDRESS, INVOICE_DATE, EXTRACT(YEAR FROM INVOICE_DATE), SUM_OF_MONEY, SUM_OF_TAX, CUSTOMER_TAX_CODE, VAT_PERCENT*100, GOODS, UNIT,
        FORMS_OF_PAYMENT, BANK_ACCOUNT, BUYER_NAME
    FROM INVOICES
    JOIN INVOICE_STRINGS ON INVOICE_STRINGS.COMPANY = :P_COMPANY AND INVOICE_STRINGS.LANGUAGE = :P_LANGUAGE AND INVOICE_STRINGS.ID = INVOICES.ID
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.ID = :P_ID
    INTO :CUSTOMER_NAME, :CUSTOMER_ADDRESS, :INVOICE_DATE, :INVOICE_YEAR_4_SO, :SUM_OF_MONEY, :SUM_OF_TAX, :CUSTOMER_TAX_CODE, :VAT_PERCENT, :GOODS, :UNIT,
        :FORMS_OF_PAYMENT, :BANK_ACCOUNT, :BUYER_NAME;

    INVOICE_YEAR = INVOICE_YEAR_4_SO - 2000;

    LENGTH_TAX_CODE = CHARACTER_LENGTH(CUSTOMER_TAX_CODE);

    CUSTOMER_TAX_CODE_SPACE_1 = '';
    CUSTOMER_TAX_CODE_SPACE_2 = '';
    CUSTOMER_TAX_CODE_SPACE_3 = '';
    CUSTOMER_TAX_CODE_SPACE_4 = '';

    N = 0;
    WHILE(N < LENGTH_TAX_CODE)DO
    BEGIN
        N = N + 1;
        TAX_CODE = SUBSTRING(CUSTOMER_TAX_CODE FROM N FOR 1);

        CUSTOMER_TAX_CODE_SPACE_1 = CUSTOMER_TAX_CODE_SPACE_1 || ' ' || TAX_CODE;
        CUSTOMER_TAX_CODE_SPACE_2 = CUSTOMER_TAX_CODE_SPACE_2 || '  ' || TAX_CODE;
        CUSTOMER_TAX_CODE_SPACE_3 = CUSTOMER_TAX_CODE_SPACE_3 || '   ' || TAX_CODE;
        CUSTOMER_TAX_CODE_SPACE_4 = CUSTOMER_TAX_CODE_SPACE_4 || '    ' || TAX_CODE;
    END

    SUM_ALL = SUM_OF_MONEY + SUM_OF_TAX;

    SUSPEND;
END ^

ALTER PROCEDURE RPT_INVOICE_DETAIL (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ORDINAL DM_INTEGER,
NAME DM_NAME,
UNIT DM_UNIT,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT DM_ID;
DECLARE VARIABLE EXTRA_GOODS DM_DESCRIPTION;
DECLARE VARIABLE EXTRA_MONEY DM_DOUBLE;
BEGIN
    SELECT INVOICES.DOCUMENT, EXTRA_GOODS, EXTRA_MONEY
    FROM INVOICES
    WHERE INVOICES.COMPANY = :P_COMPANY AND INVOICES.ID = :P_ID
    INTO :DOCUMENT, :EXTRA_GOODS, :EXTRA_MONEY;

    ORDINAL = 0;

    FOR
        SELECT CREDIT_OBJECT0_NAME NAME, CREDIT_OBJECT0_UNIT UNIT, AMOUNT, PRICE, OFFICIAL_SUM_OF_MONEY
        FROM RPT_DOCUMENT_DOUBLE_ENTRY_GOODS(:P_LANGUAGE, :P_COMPANY, :DOCUMENT)
        INTO :NAME, :UNIT, :AMOUNT, :PRICE, :SUM_OF_MONEY
    DO
    BEGIN
        ORDINAL = ORDINAL + 1;
        SUSPEND;
    END

    IF(EXTRA_GOODS IS NOT NULL AND EXTRA_GOODS <> '' AND EXTRA_MONEY <> 0)THEN
    BEGIN
        ORDINAL = NULL;
        NAME = EXTRA_GOODS;
        UNIT = NULL;
        AMOUNT = NULL;
        PRICE = NULL;
        SUM_OF_MONEY = EXTRA_MONEY;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_LAI_LO_CT_DA_TRAC_DIA (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_ACCOUNT_511 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
DT DM_DOUBLE,
DDDK DM_DOUBLE,
NC_6221 DM_DOUBLE,
NC_6222 DM_DOUBLE,
NC_6223 DM_DOUBLE,
CPC DM_DOUBLE,
TCPS DM_DOUBLE,
TCCP DM_DOUBLE,
LAI_LO DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_511 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_6221 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_6222 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_6223 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_627 DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT_511
    INTO :ACCOUNT_CODE_511;

    ACCOUNT_CODE_6221 = '6221';
    ACCOUNT_CODE_6222 = '6222';
    ACCOUNT_CODE_6223 = '6223';
    ACCOUNT_CODE_627 = '627';

    FOR
        SELECT CODE, NAME, SUM(DT), SUM(DDDK), SUM(DEBIT_NC_6221) - SUM(CREDIT_NC_6221), SUM(DEBIT_NC_6222) - SUM(CREDIT_NC_6222), SUM(DEBIT_NC_6223) - SUM(CREDIT_NC_6223), SUM(DEBIT_CPC) - SUM(CREDIT_CPC)
        FROM
        (
            SELECT OBJECT0, CREDIT DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :ACCOUNT_CODE_511, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, DEBIT - CREDIT DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_SD_1_TK_DT0_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, OFFICIAL_SUM_OF_MONEY DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_6221, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, OFFICIAL_SUM_OF_MONEY CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_6221, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, OFFICIAL_SUM_OF_MONEY DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_6222, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, OFFICIAL_SUM_OF_MONEY CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_6222, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, OFFICIAL_SUM_OF_MONEY DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_6223, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, OFFICIAL_SUM_OF_MONEY CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_6223, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, OFFICIAL_SUM_OF_MONEY DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_627, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, OFFICIAL_SUM_OF_MONEY CREDIT_CPC
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_627, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = A.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = A.OBJECT0
        GROUP BY OBJECT0, CODE, NAME
        INTO :CODE, :NAME, :DT, :DDDK, :NC_6221, :NC_6222, :NC_6223, :CPC
    DO
    BEGIN
        IF(DT <> 0 OR DDDK <> 0 OR NC_6221 <>0 OR NC_6222 <> 0 OR NC_6223 <>0 OR CPC <> 0)THEN
        BEGIN
            TCPS = NC_6221 + NC_6222 + NC_6223 + CPC;

            TCCP = DDDK + TCPS;

            LAI_LO = DT - TCCP;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_LAI_LO_CT_DA_TRAC_DIA_1_CT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_ACCOUNT_511 DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
DT DM_DOUBLE,
DDDK DM_DOUBLE,
NC_6221 DM_DOUBLE,
NC_6222 DM_DOUBLE,
NC_6223 DM_DOUBLE,
CPC DM_DOUBLE,
TCPS DM_DOUBLE,
TCCP DM_DOUBLE,
LAI_LO DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_511 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_6221 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_6222 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_6223 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_627 DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT_511
    INTO :ACCOUNT_CODE_511;

    ACCOUNT_CODE_6221 = '6221';
    ACCOUNT_CODE_6222 = '6222';
    ACCOUNT_CODE_6223 = '6223';
    ACCOUNT_CODE_627 = '627';

    FOR
        SELECT CODE, NAME, SUM(DT), SUM(DDDK), SUM(DEBIT_NC_6221) - SUM(CREDIT_NC_6221), SUM(DEBIT_NC_6222) - SUM(CREDIT_NC_6222), SUM(DEBIT_NC_6223) - SUM(CREDIT_NC_6223), SUM(DEBIT_CPC) - SUM(CREDIT_CPC)
        FROM
        (
            SELECT CREDIT DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, :ACCOUNT_CODE_511, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, DEBIT - CREDIT DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, OFFICIAL_SUM_OF_MONEY DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_6221, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, OFFICIAL_SUM_OF_MONEY CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_6221, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, OFFICIAL_SUM_OF_MONEY DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_6222, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, OFFICIAL_SUM_OF_MONEY CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_6222, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, OFFICIAL_SUM_OF_MONEY DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_6223, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, OFFICIAL_SUM_OF_MONEY CREDIT_NC_6223, 0 DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_6223, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, OFFICIAL_SUM_OF_MONEY DEBIT_CPC, 0 CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :P_OBJECT0, :ACCOUNT_CODE_627, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT 0 DT, 0 DDDK, 0 DEBIT_NC_6221, 0 CREDIT_NC_6221, 0 DEBIT_NC_6222, 0 CREDIT_NC_6222, 0 DEBIT_NC_6223, 0 CREDIT_NC_6223, 0 DEBIT_CPC, OFFICIAL_SUM_OF_MONEY CREDIT_CPC
            FROM INT_PS_CAP_TK_1_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_627, :ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
        GROUP BY CODE, NAME
        INTO :CODE, :NAME, :DT, :DDDK, :NC_6221, :NC_6222, :NC_6223, :CPC
    DO
    BEGIN
        IF(DT <> 0 OR DDDK <> 0 OR NC_6221 <>0 OR NC_6222 <> 0 OR NC_6223 <>0 OR CPC <> 0)THEN
        BEGIN
            TCPS = NC_6221 + NC_6222 + NC_6223 + CPC;

            TCCP = DDDK + TCPS;

            LAI_LO = DT - TCCP;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_PHAN_BO_CHI_PHI_TRA_TRUOC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
DATE_OF_USING DM_DATE,
PREVIOUS_VALUE DM_DOUBLE,
CURRENT_VALUE DM_DOUBLE,
ORIGINAL_VALUE DM_DOUBLE,
TOTAL_DEPRECIATION_PERIOD DM_SMALLINT,
DEPRECIATION_VALUE DM_DOUBLE,
REMAINING_VALUE DM_DOUBLE,
ACCOUNTS DM_STRING)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OBJECT DM_ID;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE TIME_1 DM_INTEGER;
DECLARE VARIABLE TIME_2 DM_INTEGER;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    FOR
        SELECT OBJECT0, CODE, NAME, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, SUM(PREVIOUS_VALUE), SUM(CURRENT_VALUE)
        FROM
        (
            SELECT OBJECT0, CODE, NAME, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, DEBIT PREVIOUS_VALUE, 0 CURRENT_VALUE
            FROM INT_SD_1_TK_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
            JOIN PREPAID_EXPENSES ON PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ID = OBJECT0
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PREPAID_EXPENSES.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = ATOMS.ID

            UNION ALL

            SELECT OBJECT0, CODE, NAME, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, 0 PREVIOUS_VALUE, DEBIT CURRENT_VALUE
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
            JOIN PREPAID_EXPENSES ON PREPAID_EXPENSES.COMPANY = :P_COMPANY AND PREPAID_EXPENSES.ID = OBJECT0
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PREPAID_EXPENSES.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE DEBIT > 0
        )
        GROUP BY OBJECT0, CODE, NAME, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE
        INTO :OBJECT, :CODE, :NAME, :DATE_OF_USING, :TOTAL_DEPRECIATION_PERIOD, :DEPRECIATION_TIME_TYPE, :PREVIOUS_VALUE, :CURRENT_VALUE
    DO
    BEGIN
        
        SELECT TIME_1, TIME_2
        FROM INT_DATE_TIME_TYPE_TO_TIMES(:DEPRECIATION_TIME_TYPE, :P_DEN_NGAY)
        INTO :TIME_1, :TIME_2;

        SELECT CREDIT
        FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY, :P_DEN_NGAY)
        INTO :DEPRECIATION_VALUE;

        CURRENT_VALUE = CURRENT_VALUE - DEPRECIATION_VALUE;

        
        FOR
            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, TOTAL_DEPRECIATION_PERIOD
            FROM PREPAID_EXPENSE_PERIODS
            WHERE COMPANY = :P_COMPANY AND PREPAID_EXPENSE = :OBJECT AND PREPAID_EXPENSE_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :TIME_1 AND BEGINNING_DEPRECIATION_VALUE2 <= :TIME_2
            ORDER BY BEGINNING_DEPRECIATION_VALUE2 DESC, BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :TIME_1, :TIME_2, TOTAL_DEPRECIATION_PERIOD
        DO
        BEGIN
        END

        SELECT INT_PS_CAP_TK_CO_DT0_C.SUM_OF_MONEY
        FROM INT_PS_CAP_TK_CO_DT0_C(:P_COMPANY, '6', '154', NULL, :PARENT_ACCOUNT_CODE, NULL, NULL, :OBJECT, :P_TU_NGAY, :P_DEN_NGAY)
        INTO :DEPRECIATION_VALUE;

        CURRENT_VALUE = CURRENT_VALUE + DEPRECIATION_VALUE;

        ORIGINAL_VALUE = PREVIOUS_VALUE + CURRENT_VALUE;

        REMAINING_VALUE = ORIGINAL_VALUE - DEPRECIATION_VALUE;

        SELECT ACCOUNTS
        FROM INT_DU_1_TK_1_DT0_C(:P_COMPANY, 1, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY, :P_DEN_NGAY, '6', '154')
        INTO :ACCOUNTS;

        IF(DEPRECIATION_TIME_TYPE = 3)THEN TOTAL_DEPRECIATION_PERIOD = TOTAL_DEPRECIATION_PERIOD*3;
        ELSE IF(DEPRECIATION_TIME_TYPE = 4)THEN TOTAL_DEPRECIATION_PERIOD = TOTAL_DEPRECIATION_PERIOD*6;
        ELSE IF(DEPRECIATION_TIME_TYPE = 5)THEN TOTAL_DEPRECIATION_PERIOD = TOTAL_DEPRECIATION_PERIOD*12;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_PHAN_BO_KHAU_HAO_TSCD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ASSET_ACCOUNT DM_ID,
P_DEPRECIATION_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_IS_ONLY_DEPRECIATION DM_BOOL)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
DATE_OF_USING DM_DATE,
PREVIOUS_VALUE DM_DOUBLE,
VALUE_FOR_DEPRECIATION DM_DOUBLE,
CURRENT_VALUE DM_DOUBLE,
ORIGINAL_VALUE DM_DOUBLE,
TOTAL_DEPRECIATION_PERIOD DM_SMALLINT,
DEPRECIATION_PERIOD DM_DOUBLE,
DEPRECIATION_VALUE_YEAR DM_DOUBLE,
DEPRECIATION_VALUE_MONTH DM_DOUBLE,
APPORTIONMENT_VALUE DM_DOUBLE,
ACCUMULATE_VALUE DM_DOUBLE,
REMAINING_VALUE DM_DOUBLE)
AS 
DECLARE VARIABLE ASSET_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEPRECIATION_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OBJECT DM_ID;
DECLARE VARIABLE DEPRECIATION_TIME_TYPE DM_TIME_TYPE;
DECLARE VARIABLE TIME_1 DM_INTEGER;
DECLARE VARIABLE TIME_2 DM_INTEGER;
DECLARE VARIABLE BEGINNING_DATE DM_DATE;
DECLARE VARIABLE DEPRECIATION_FOR_MONTH DM_SMALLINT;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ASSET_ACCOUNT
    INTO :ASSET_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_DEPRECIATION_ACCOUNT
    INTO :DEPRECIATION_ACCOUNT_CODE;

    FOR
        SELECT OBJECT0, CODE, NAME, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, SUM(PREVIOUS_VALUE), SUM(RISING_DEBIT) - SUM(RISING_CREDIT) CURRENT_VALUE
        FROM
        (
            SELECT OBJECT0, CODE, NAME, ASSETS.DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, DEBIT PREVIOUS_VALUE, 0 RISING_DEBIT, 0 RISING_CREDIT
            FROM INT_SD_1_TK_DT0_DN_C(:P_COMPANY, :ASSET_ACCOUNT_CODE, :P_TU_NGAY)
            JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSETS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = ATOMS.ID

            UNION ALL

            SELECT OBJECT0, CODE, NAME, ASSETS.DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE, 0 PREVIOUS_VALUE, DEBIT RISING_DEBIT, CREDIT RISING_CREDIT
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :ASSET_ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
            JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSETS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE (DEBIT <> 0 OR CREDIT <> 0)
        )
        GROUP BY OBJECT0, CODE, NAME, DATE_OF_USING, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD, DEPRECIATION_TIME_TYPE
        INTO :OBJECT, :CODE, :NAME, :DATE_OF_USING, :TOTAL_DEPRECIATION_PERIOD, :DEPRECIATION_PERIOD, :DEPRECIATION_TIME_TYPE, :PREVIOUS_VALUE, :CURRENT_VALUE
    DO
    BEGIN
        
        SELECT CREDIT
        FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, :DEPRECIATION_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY, :P_DEN_NGAY)
        INTO :APPORTIONMENT_VALUE;

        SELECT CREDIT
        FROM INT_SD_1_TK_1_DT0_CN_C(:P_COMPANY, :DEPRECIATION_ACCOUNT_CODE, :OBJECT, :P_DEN_NGAY)
        INTO :ACCUMULATE_VALUE;

        
        SELECT TIME_1, TIME_2
        FROM INT_DATE_TIME_TYPE_TO_TIMES(:DEPRECIATION_TIME_TYPE, :P_DEN_NGAY)
        INTO :TIME_1, :TIME_2;

        VALUE_FOR_DEPRECIATION = PREVIOUS_VALUE;
        ORIGINAL_VALUE = VALUE_FOR_DEPRECIATION + CURRENT_VALUE;
        
        IF(ORIGINAL_VALUE < 0)THEN ORIGINAL_VALUE = 0;

        DEPRECIATION_FOR_MONTH = TOTAL_DEPRECIATION_PERIOD;
        DEPRECIATION_PERIOD = NULL;

        FOR
            SELECT FIRST 1 BEGINNING_DEPRECIATION_VALUE1, BEGINNING_DEPRECIATION_VALUE2, TOTAL_DEPRECIATION_PERIOD, DEPRECIATION_PERIOD
            FROM ASSET_DEPRECIATION_PERIODS
            WHERE COMPANY = :P_COMPANY AND ASSET = :OBJECT AND ASSET_DEPRECIATION_PERIODS.BEGINNING_DEPRECIATION_VALUE1 <= :TIME_1 AND BEGINNING_DEPRECIATION_VALUE2 <= :TIME_2
            ORDER BY BEGINNING_DEPRECIATION_VALUE2 DESC, BEGINNING_DEPRECIATION_VALUE1 DESC
            INTO :TIME_1, :TIME_2, :TOTAL_DEPRECIATION_PERIOD, :DEPRECIATION_PERIOD
        DO
        BEGIN
            DEPRECIATION_FOR_MONTH = DEPRECIATION_PERIOD;

            SELECT BEGINNING_DATE
            FROM INT_TIMES_TO_BEGIN_END_DATES(:DEPRECIATION_TIME_TYPE, :TIME_1, :TIME_2)
            INTO :BEGINNING_DATE;

            SELECT INT_SD_1_TK_1_DT0_CN_C.DEBIT - CREDIT
            FROM INT_SD_1_TK_1_DT0_CN_C(:P_COMPANY, :ASSET_ACCOUNT_CODE, :OBJECT, :BEGINNING_DATE)
            INTO VALUE_FOR_DEPRECIATION;

            SELECT :VALUE_FOR_DEPRECIATION - CREDIT
            FROM INT_SD_1_TK_1_DT0_CN_C(:P_COMPANY, :DEPRECIATION_ACCOUNT_CODE, :OBJECT, :BEGINNING_DATE)
            INTO VALUE_FOR_DEPRECIATION;

            SELECT :VALUE_FOR_DEPRECIATION + DEBIT - CREDIT
            FROM INT_PS_1_TK_1_DT0_C(:P_COMPANY, :ASSET_ACCOUNT_CODE, :OBJECT, :BEGINNING_DATE, DATEADD(DAY, -1, :P_TU_NGAY))
            INTO :VALUE_FOR_DEPRECIATION;

            ORIGINAL_VALUE = VALUE_FOR_DEPRECIATION + CURRENT_VALUE;
            
            IF(ORIGINAL_VALUE < 0)THEN ORIGINAL_VALUE = 0;
        END

        
        IF(DEPRECIATION_TIME_TYPE = 3)THEN DEPRECIATION_FOR_MONTH = DEPRECIATION_FOR_MONTH*3;
        ELSE IF(DEPRECIATION_TIME_TYPE = 4)THEN DEPRECIATION_FOR_MONTH = DEPRECIATION_FOR_MONTH*6;
        ELSE IF(DEPRECIATION_TIME_TYPE = 5)THEN DEPRECIATION_FOR_MONTH = DEPRECIATION_FOR_MONTH*12;

        IF(DEPRECIATION_FOR_MONTH > 0 AND APPORTIONMENT_VALUE <> 0)THEN
            DEPRECIATION_VALUE_MONTH = ROUND(ORIGINAL_VALUE/DEPRECIATION_FOR_MONTH, 0);
        ELSE
            DEPRECIATION_VALUE_MONTH = 0;

        IF(DEPRECIATION_FOR_MONTH > 12)THEN
            DEPRECIATION_VALUE_YEAR = DEPRECIATION_VALUE_MONTH*12;
        ELSE
            DEPRECIATION_VALUE_YEAR = ORIGINAL_VALUE;

        REMAINING_VALUE = PREVIOUS_VALUE + CURRENT_VALUE - ACCUMULATE_VALUE;

        IF((P_IS_ONLY_DEPRECIATION = 0 AND ORIGINAL_VALUE > 0) OR APPORTIONMENT_VALUE > 0 OR REMAINING_VALUE > 0)THEN
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CAI_CHUNG_TU_GHI_SO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
NOTE DM_NOTE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_RISING_DEBIT DM_DOUBLE;
DECLARE VARIABLE SUM_RISING_CREDIT DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    FOR
        SELECT RECORDED_DOCUMENTS.CODE, INPUT_DATE, RECORDED_DOCUMENT_ENTRIES.CONTENT, DEBIT_ATOM.CODE, CREDIT_ATOM.CODE, SUM_OF_MONEY, PROTON_STRINGS.NOTE
        FROM RECORDED_DOCUMENTS
        JOIN RECORDED_DOCUMENT_ENTRIES ON RECORDED_DOCUMENT_ENTRIES.COMPANY = :P_COMPANY AND RECORDED_DOCUMENT_ENTRIES.RECORDED_DOCUMENT = RECORDED_DOCUMENTS.ID
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = RECORDED_DOCUMENT_ENTRIES.DEBIT_ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = RECORDED_DOCUMENT_ENTRIES.CREDIT_ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = RECORDED_DOCUMENT_ENTRIES.ID
        WHERE RECORDED_DOCUMENTS.COMPANY = :P_COMPANY AND RECORDED_DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        ORDER BY INPUT_DATE, DEBIT_ATOM.CODE, CREDIT_ATOM.CODE, RECORDED_DOCUMENTS.CODE
        INTO :CODE, :INPUT_DATE, :CONTENT, :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE, :OFFICIAL_SUM_OF_MONEY, :NOTE
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = NULL;

            SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;

            ENDING_DEBIT = BEGINNING_DEBIT - BEGINNING_CREDIT + SUM_RISING_DEBIT - SUM_RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END

            SUSPEND;

            HAS_VALUE = 1;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = NULL;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;

            ENDING_DEBIT = BEGINNING_DEBIT - BEGINNING_CREDIT + SUM_RISING_DEBIT - SUM_RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END

            SUSPEND;

            HAS_VALUE = 1;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CAI_NHAT_KY_CHUNG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
SUM_RISING_DEBIT_MONTH DM_DOUBLE,
SUM_RISING_CREDIT_MONTH DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
INPUT_MONTH DM_INTEGER,
INPUT_YEAR DM_INTEGER)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE NOT154X2 DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE NEW_INPUT_MONTH DM_INTEGER;
DECLARE VARIABLE NEW_INPUT_YEAR DM_INTEGER;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512), BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 4096)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME, :NOT154X2;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(NOT154X2 > 0 AND PARENT_ACCOUNT_CODE NOT STARTING WITH '154')THEN
        NOT154X2 = 0;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    SUM_RISING_DEBIT_MONTH = 0;
    SUM_RISING_CREDIT_MONTH = 0;
    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        ORDER BY INPUT_DATE,
        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PT', 0,
            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PC', 5,
                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBCO', 10,
                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBNO', 15,
                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTTH', 75,
                            IIF(ATOM_DOCUMENT_TEAMS.CODE = 'BTK', 80,
                                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'TKHTS', 85,
                                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'CPTT', 90,
                                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTPB', 95,
                                            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTKC', 100, 50)
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        CODENUMBER, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        NEW_INPUT_MONTH = EXTRACT(MONTH FROM INPUT_DATE);
        NEW_INPUT_YEAR = EXTRACT(YEAR FROM INPUT_DATE);
        IF(INPUT_MONTH IS NULL OR INPUT_YEAR IS NULL OR NEW_INPUT_MONTH <> INPUT_MONTH OR NEW_INPUT_YEAR <> INPUT_YEAR)THEN
        BEGIN
            INPUT_YEAR = NEW_INPUT_YEAR;
            INPUT_MONTH = NEW_INPUT_MONTH;

            SUM_RISING_CREDIT_MONTH = 0;
            SUM_RISING_DEBIT_MONTH = 0;
        END

        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            IF(NOT154X2 = 0 OR CREDIT_ACCOUNT_CODE NOT STARTING WITH PARENT_ACCOUNT_CODE)THEN
            BEGIN
                SUM_RISING_DEBIT_MONTH = SUM_RISING_DEBIT_MONTH + RISING_DEBIT;
                SUM_RISING_CREDIT_MONTH = SUM_RISING_CREDIT_MONTH + RISING_CREDIT;

                SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
                SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            END

            ENDING_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = ENDING_DEBIT;
            BEGINNING_CREDIT = ENDING_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            IF(NOT154X2 = 0 OR DEBIT_ACCOUNT_CODE NOT STARTING WITH PARENT_ACCOUNT_CODE)THEN
            BEGIN
                SUM_RISING_DEBIT_MONTH = SUM_RISING_DEBIT_MONTH + RISING_DEBIT;
                SUM_RISING_CREDIT_MONTH = SUM_RISING_CREDIT_MONTH + RISING_CREDIT;

                SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
                SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            END

            ENDING_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = ENDING_DEBIT;
            BEGINNING_CREDIT = ENDING_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CAI_NHAT_KY_CHUNG_ALL (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SOURCES DM_NOTE,
SOURCE_ACCOUNT_ID DM_ID,
SOURCE_ACCOUNT_CODE DM_CODE,
SOURCE_ACCOUNT_NAME DM_NAME,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
SUM_RISING_DEBIT_MONTH DM_DOUBLE,
SUM_RISING_CREDIT_MONTH DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
INPUT_MONTH DM_INTEGER,
INPUT_YEAR DM_INTEGER)
AS 
BEGIN
    SELECT LIST(CODE)
    FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 0)
    WHERE PARENT_ID IS NULL
    INTO :SOURCES;

    FOR
        SELECT ID, CODE, NAME
        FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 0)
        WHERE PARENT_ID IS NULL AND
        (BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)
        INTO :SOURCE_ACCOUNT_ID, :SOURCE_ACCOUNT_CODE, :SOURCE_ACCOUNT_NAME
    DO
    BEGIN
        FOR
            SELECT CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, ACCOUNT_CODE,
            BEGINNING_DEBIT, BEGINNING_CREDIT, RISING_DEBIT, RISING_CREDIT,
            SUM_RISING_DEBIT_MONTH, SUM_RISING_CREDIT_MONTH,
            SUM_RISING_DEBIT, SUM_RISING_CREDIT, ENDING_DEBIT, ENDING_CREDIT,
            INPUT_MONTH, INPUT_YEAR
            FROM RPT_SO_CAI_NHAT_KY_CHUNG(:P_LANGUAGE, :P_COMPANY, :P_ID, :SOURCE_ACCOUNT_ID, :P_TU_NGAY, :P_DEN_NGAY)
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :ACCOUNT_CODE,
            :BEGINNING_DEBIT, :BEGINNING_CREDIT, :RISING_DEBIT, :RISING_CREDIT,
            :SUM_RISING_DEBIT_MONTH, :SUM_RISING_CREDIT_MONTH,
            :SUM_RISING_DEBIT, :SUM_RISING_CREDIT, :ENDING_DEBIT, :ENDING_CREDIT,
            :INPUT_MONTH, :INPUT_YEAR
        DO
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_BAN_HANG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
OFFICIAL_511 DM_DOUBLE,
TAX DM_DOUBLE,
OTHER_521 DM_DOUBLE,
OTHER_531 DM_DOUBLE,
OTHER_532 DM_DOUBLE,
DOANH_THU DM_DOUBLE,
GIA_VON DM_DOUBLE,
LAI_GOP DM_DOUBLE,
TONG_DOANH_THU DM_DOUBLE,
TONG_GIA_VON DM_DOUBLE,
TONG_LAI_GOP DM_DOUBLE,
N DM_INTEGER)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM;
DECLARE VARIABLE ACCOUNT_CODE_521 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_531 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_532 DM_CODE;
DECLARE VARIABLE PREV_OBJECT DM_ID;
DECLARE VARIABLE OBJECT DM_ID;
DECLARE VARIABLE NEW_DOANH_THU DM_DOUBLE;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512), ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME, :ACCOUNTING_SYSTEM;

    IF(ACCOUNTING_SYSTEM = 1)THEN
    BEGIN
        ACCOUNT_CODE_521 = '521';
        ACCOUNT_CODE_531 = '531';
        ACCOUNT_CODE_532 = '532';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 2)THEN
    BEGIN
        ACCOUNT_CODE_521 = '5211';
        ACCOUNT_CODE_531 = '5212';
        ACCOUNT_CODE_532 = '5213';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 3)THEN
    BEGIN
        ACCOUNT_CODE_521 = '5211';
        ACCOUNT_CODE_531 = '5212';
        ACCOUNT_CODE_532 = '5213';
    END

    DOANH_THU = 0;
    GIA_VON = 0;
    LAI_GOP = 0;
    TONG_DOANH_THU = 0;
    TONG_GIA_VON = 0;
    TONG_LAI_GOP = 0;
    PREV_OBJECT = NULL;
    N = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    FOR
        SELECT OBJECT, ATOMS.CODE, ATOM_STRINGS.NAME, ABC.CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, ACCOUNT_CODE, SUM(AMOUNT), SUM(PRICE), SUM(OFFICIAL_511), SUM(TAX), SUM(OTHER_521), SUM(OTHER_531), SUM(OTHER_532)
        FROM
        (
            SELECT CREDIT.OBJECT0 OBJECT, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') CONTENT, DEBIT_ATOM.CODE ACCOUNT_CODE,
            DEBIT.AMOUNT, DEBIT.PRICE, DEBIT.OFFICIAL_SUM_OF_MONEY OFFICIAL_511, 0 TAX, 0 OTHER_521, 0 OTHER_531, 0 OTHER_532
            FROM ENTRIES
            
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND (DEBIT_ATOM.CODE NOT STARTING '911')
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND (:P_OBJECT0 IS NULL OR CREDIT.OBJECT0 = :P_OBJECT0)
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE ENTRIES.COMPANY = :P_COMPANY

            UNION ALL

            SELECT DEBIT.OBJECT0 OBJECT, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') CONTENT, CREDIT_ATOM.CODE ACCOUNT_CODE,
            DEBIT.AMOUNT, DEBIT.PRICE, 0 OFFICIAL_511, 0 TAX, DEBIT.OFFICIAL_SUM_OF_MONEY OTHER_521, 0 OTHER_531, 0 OTHER_532
            FROM ENTRIES
            
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0)
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_521
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY

            UNION ALL

            SELECT DEBIT.OBJECT0 OBJECT, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') CONTENT, CREDIT_ATOM.CODE ACCOUNT_CODE,
            DEBIT.AMOUNT, DEBIT.PRICE, 0 OFFICIAL_511, 0 TAX, 0 OTHER_521, DEBIT.OFFICIAL_SUM_OF_MONEY OTHER_531, 0 OTHER_532
            FROM ENTRIES
            
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0)
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_531
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY

            UNION ALL

            SELECT DEBIT.OBJECT0 OBJECT, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') CONTENT, CREDIT_ATOM.CODE ACCOUNT_CODE,
            DEBIT.AMOUNT, DEBIT.PRICE, 0 OFFICIAL_511, 0 TAX, 0 OTHER_521, 0 OTHER_531, DEBIT.OFFICIAL_SUM_OF_MONEY OTHER_532
            FROM ENTRIES
            
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND (:P_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_OBJECT0)
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_532
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY
        ) ABC
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ABC.OBJECT
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ABC.OBJECT
        GROUP BY OBJECT, ATOMS.CODE, ATOM_STRINGS.NAME, ABC.CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, ACCOUNT_CODE
        ORDER BY ATOMS.CODE, INPUT_DATE, ABC.CODE
        INTO :OBJECT, :OBJECT_CODE, :OBJECT_NAME, :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :ACCOUNT_CODE, :AMOUNT, :PRICE, :OFFICIAL_511, :TAX, :OTHER_521, :OTHER_531, :OTHER_532
    DO
    BEGIN
        IF(PREV_OBJECT IS NULL OR PREV_OBJECT <> OBJECT)THEN
        BEGIN
            N = N + 1;
            PREV_OBJECT = OBJECT;

            SELECT SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
            FROM ENTRIES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH '632'
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND (CREDIT.OBJECT0 = :P_OBJECT0 OR CREDIT.OBJECT0 = :OBJECT)
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY
            INTO :GIA_VON;

            IF(GIA_VON IS NULL)THEN GIA_VON = 0;

            TONG_GIA_VON = TONG_GIA_VON + GIA_VON;

            DOANH_THU = OFFICIAL_511 - TAX - OTHER_521 - OTHER_531 - OTHER_532;
            LAI_GOP = DOANH_THU - GIA_VON;

            TONG_DOANH_THU = TONG_DOANH_THU + DOANH_THU;
            TONG_LAI_GOP = TONG_LAI_GOP + LAI_GOP;
        END
        ELSE
        BEGIN
            NEW_DOANH_THU = OFFICIAL_511 - TAX - OTHER_521 - OTHER_531 - OTHER_532;

            DOANH_THU = DOANH_THU + NEW_DOANH_THU;
            LAI_GOP = LAI_GOP + NEW_DOANH_THU;

            TONG_DOANH_THU = TONG_DOANH_THU + NEW_DOANH_THU;
            TONG_LAI_GOP = TONG_LAI_GOP + NEW_DOANH_THU;
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_BAN_HANG_NXT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_GOODS DM_ID,
P_WAREHOUSE DM_ID,
P_ACCOUNT_511 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
PRICE DM_DOUBLE,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
INVENTORY_AMOUNT DM_DOUBLE,
INVENTORY_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
GOODS_NAME DM_NAME,
WAREHOUSE_NAME DM_NAME,
SO_LUONG_BAN DM_DOUBLE,
DON_GIA_BAN DM_DOUBLE,
DOANH_THU_BAN DM_DOUBLE,
TON_THUC_TE DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_511x DM_CODE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE GOODS DM_ID;
DECLARE VARIABLE PREV_GOODS DM_ID;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE PREV_WAREHOUSE DM_ID;
DECLARE VARIABLE INVENTORY_AMOUNT_TEMP DM_DOUBLE;
DECLARE VARIABLE INVENTORY_SUM_OF_MONEY_TEMP DM_DOUBLE;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT_511
    INTO :ACCOUNT_CODE_511X;

    PREV_GOODS = NULL;
    PREV_WAREHOUSE = NULL;

    FOR
        SELECT CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
        PRICE,
        INPUT_AMOUNT, INPUT_SUM_OF_MONEY,
        OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY,
        GOODS, GOODS_ATOM_STRINGS.NAME, WAREHOUSE, WAREHOUSE_ATOM_STRINGS.NAME, ACCOUNT_CODE
        ID,
        SO_LUONG_BAN,
        DON_GIA_BAN,
        DOANH_THU_BAN
        FROM
        (
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            DEBIT.PRICE,
            DEBIT.AMOUNT INPUT_AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY,
            0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY,
            DEBIT.OBJECT0 GOODS, DEBIT.OBJECT1 WAREHOUSE,
            CREDIT_ATOM.CODE ACCOUNT_CODE,
            ENTRIES.ID, 0 IS_OUTPUT,
            0 SO_LUONG_BAN,
            0 DON_GIA_BAN,
            0 DOANH_THU_BAN
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            ((DEBIT.OBJECT0 = :P_GOODS) OR (DEBIT.OBJECT0 IS NOT NULL AND :P_GOODS IS NULL)) AND
            ((DEBIT.OBJECT1 = :P_WAREHOUSE) OR (DEBIT.OBJECT1 IS NOT NULL AND :P_WAREHOUSE IS NULL))

            UNION ALL

            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            DEBIT.PRICE,
            0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY,
            DEBIT.AMOUNT OUTPUT_AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY,
            CREDIT.OBJECT0 GOODS, CREDIT.OBJECT1 WAREHOUSE, DEBIT_ATOM.CODE ACCOUNT_CODE,
            ENTRIES.ID, 2 IS_OUTPUT,
            0 SO_LUONG_BAN,
            0 DON_GIA_BAN,
            0 DOANH_THU_BAN
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            ((CREDIT.OBJECT0 = :P_GOODS) OR (CREDIT.OBJECT0 IS NOT NULL AND :P_GOODS IS NULL)) AND
            ((CREDIT.OBJECT1 = :P_WAREHOUSE) OR (CREDIT.OBJECT1 IS NOT NULL AND :P_WAREHOUSE IS NULL))

            UNION ALL

            
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            0 PRICE,
            0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY,
            0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY,
            CREDIT.OBJECT0 GOODS, :P_WAREHOUSE WAREHOUSE, DEBIT_ATOM.CODE ACCOUNT_CODE,
            ENTRIES.ID, 1 IS_OUTPUT,
            DEBIT.AMOUNT SO_LUONG_BAN,
            DEBIT.PRICE DON_GIA_BAN,
            DEBIT.OFFICIAL_SUM_OF_MONEY DOANH_THU_BAN
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_511X AND
            ((CREDIT.OBJECT0 = :P_GOODS) OR (CREDIT.OBJECT0 IS NOT NULL AND :P_GOODS IS NULL))
        ) ABC
        JOIN ATOM_STRINGS GOODS_ATOM_STRINGS ON GOODS_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOODS_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_ATOM_STRINGS.ID = ABC.GOODS
        JOIN ATOM_STRINGS WAREHOUSE_ATOM_STRINGS ON WAREHOUSE_ATOM_STRINGS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND WAREHOUSE_ATOM_STRINGS.ID = ABC.WAREHOUSE
        ORDER BY ABC.WAREHOUSE, ABC.GOODS, INPUT_DATE, IS_OUTPUT, ABC.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :PRICE,
        :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY,
        :GOODS, :GOODS_NAME, :WAREHOUSE, :WAREHOUSE_NAME, :ACCOUNT_CODE,
        :SO_LUONG_BAN,
        :DON_GIA_BAN,
        :DOANH_THU_BAN
    DO
    BEGIN
        IF(PREV_WAREHOUSE IS NULL OR PREV_WAREHOUSE <> WAREHOUSE OR PREV_GOODS IS NULL OR PREV_GOODS <> GOODS)THEN
        BEGIN
            PREV_WAREHOUSE = WAREHOUSE;
            PREV_GOODS = GOODS;

            SELECT AMOUNT, SUM_OF_MONEY
            FROM INT_SD_1_TK_1_VT_1_KHO_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :GOODS, :WAREHOUSE, :P_TU_NGAY)
            INTO :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY;

            TON_THUC_TE = BEGINNING_AMOUNT;
        END

        IF(PRICE = 0)THEN PRICE = NULL;
        IF(DON_GIA_BAN = 0)THEN DON_GIA_BAN = NULL;

        INVENTORY_AMOUNT_TEMP = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        INVENTORY_SUM_OF_MONEY_TEMP = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        INVENTORY_AMOUNT = INVENTORY_AMOUNT_TEMP;
        INVENTORY_SUM_OF_MONEY = INVENTORY_SUM_OF_MONEY_TEMP;

        ENDING_AMOUNT = INVENTORY_AMOUNT_TEMP;
        ENDING_SUM_OF_MONEY = INVENTORY_SUM_OF_MONEY_TEMP;

        
        TON_THUC_TE = TON_THUC_TE + INPUT_AMOUNT - SO_LUONG_BAN;

        HAS_VALUE = 1;

        IF(SO_LUONG_BAN = 0)THEN SO_LUONG_BAN = NULL;
        IF(INPUT_AMOUNT = 0)THEN INPUT_AMOUNT = NULL;
        IF(OUTPUT_AMOUNT = 0)THEN OUTPUT_AMOUNT = NULL;

        IF(INPUT_AMOUNT IS NULL AND OUTPUT_AMOUNT IS NULL)THEN
        BEGIN
            INVENTORY_AMOUNT = NULL;
            INVENTORY_SUM_OF_MONEY = NULL;
        END

        SUSPEND;

        BEGINNING_AMOUNT = INVENTORY_AMOUNT_TEMP;
        BEGINNING_SUM_OF_MONEY = INVENTORY_SUM_OF_MONEY_TEMP;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        IF(P_GOODS IS NOT NULL OR P_WAREHOUSE IS NOT NULL)THEN
        BEGIN
            SELECT AMOUNT, SUM_OF_MONEY
            FROM INT_SD_1_TK_1_VT_1_KHO_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_GOODS, :P_WAREHOUSE, :P_TU_NGAY)
            INTO :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY;

            SELECT ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_GOODS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_GOODS
            INTO :GOODS_NAME;

            SELECT ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_WAREHOUSE
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_WAREHOUSE
            INTO :WAREHOUSE_NAME;

            ENDING_AMOUNT = BEGINNING_AMOUNT;
            ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;
        END

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_CHI_PHI_SXKD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_CUNG_LOAI (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_SIDE_TYPE DM_SIDE,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ROW_CODE DM_CODE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
RISING DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE SUM_RISING DM_DOUBLE;
BEGIN
    SUM_RISING = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    
    IF(P_SIDE_TYPE = 0)THEN
    BEGIN
        FOR
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
            CREDIT_ATOM.CODE
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
            CREDIT_ATOM.CODE
            ORDER BY INPUT_DATE, CODE_NUMBER
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :RISING,
            :ACCOUNT_CODE
        DO
        BEGIN
            SUM_RISING = SUM_RISING + RISING;

            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT.OFFICIAL_SUM_OF_MONEY),
            DEBIT_ATOM.CODE
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
            DEBIT_ATOM.CODE
            ORDER BY INPUT_DATE, CODE_NUMBER
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :RISING,
            :ACCOUNT_CODE
        DO
        BEGIN
            SUM_RISING = SUM_RISING + RISING;

            SUSPEND;
        END
    END
    
    
    ROW_CODE = 'TC';
    CODE = NULL;
    INPUT_DATE = NULL;
    VOUCHER_DATE = NULL;
    ACCOUNT_CODE = NULL;
    RISING = SUM_RISING;

    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 4 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;

    SUSPEND;
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_DOI_TUONG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
ACCOUNT_NAME DM_NAME,
RECIPROCAL_ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
declare variable official_sum_of_money dm_double;
declare variable debit_object0 dm_id;
declare variable debit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable prev_account_code dm_code;
BEGIN
    FOR
        SELECT
            code, input_date, voucher_date, content,
            account_code, reciprocal_account_code,
            rising_debit, rising_credit
        FROM int_so_chi_tiet_doi_tuong(:p_language, :p_company, :P_ID, :p_object0, :p_tu_ngay, :p_den_ngay)
        ORDER BY account_code
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT,
        :account_code, :reciprocal_account_code,
        :rising_debit, :rising_credit
    DO
    BEGIN
        IF(prev_account_code IS NULL OR prev_account_code <> account_code)THEN
        BEGIN
            prev_account_code = account_code;

            select atom_strings.name
            from atom_strings
            join atoms on atoms.company = :p_company and atoms.id = atom_strings.id and atoms.object_type = 10 and atoms.code = :account_code
            where atom_strings.company = :p_company and atom_strings.language = 0
            into :account_name;

            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :account_code, :p_object0, :P_TU_NGAY)
            INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

            ENDING_DEBIT = 0;
            ENDING_CREDIT = 0;
        END

        BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

        IF(BALANCE_DEBIT > 0)THEN
            BALANCE_CREDIT = 0;
        ELSE
        BEGIN
            BALANCE_CREDIT = ABS(BALANCE_DEBIT);
            BALANCE_DEBIT = 0;
        END

        ENDING_DEBIT = BALANCE_DEBIT;
        ENDING_CREDIT = BALANCE_CREDIT;

        SUSPEND;

        BEGINNING_DEBIT = BALANCE_DEBIT;
        BEGINNING_CREDIT = BALANCE_CREDIT;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_HANG_HOA (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_WAREHOUSE DM_ID,
P_GOODS DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
PRICE DM_DOUBLE,
BEGINNING_AMOUNT DM_DOUBLE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
INPUT_SUM_OF_MONEY DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
OUTPUT_SUM_OF_MONEY DM_DOUBLE,
INVENTORY_AMOUNT DM_DOUBLE,
INVENTORY_SUM_OF_MONEY DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
GOODS_CODE DM_CODE,
GOODS_NAME DM_NAME,
GOODS_UNIT DM_UNIT,
WAREHOUSE_NAME DM_NAME)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE WAREHOUSE DM_ID;
DECLARE VARIABLE GOODS DM_ID;
DECLARE VARIABLE PREV_WAREHOUSE DM_ID;
DECLARE VARIABLE PREV_GOODS DM_ID;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    PREV_WAREHOUSE = NULL;
    PREV_GOODS = NULL;

    FOR
        SELECT CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
        PRICE,
        INPUT_AMOUNT, INPUT_SUM_OF_MONEY,
        OUTPUT_AMOUNT, OUTPUT_SUM_OF_MONEY,
        GOODS, GOODS_ATOMS.CODE, GOODS_ATOM_STRINGS.NAME, IIF(GOODS_STRINGS.UNIT IS NULL OR GOODS_STRINGS.UNIT = '',NULL,'(' || GOODS_STRINGS.UNIT || ')'), WAREHOUSE, WAREHOUSE_ATOM_STRINGS.NAME, ACCOUNT_CODE
        ID
        FROM
        (
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            DEBIT.PRICE,
            DEBIT.AMOUNT INPUT_AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY INPUT_SUM_OF_MONEY,
            0 OUTPUT_AMOUNT, 0 OUTPUT_SUM_OF_MONEY,
            DEBIT.OBJECT0 GOODS, DEBIT.OBJECT1 WAREHOUSE,
            CREDIT_ATOM.CODE ACCOUNT_CODE,
            ENTRIES.ID, 0 IS_OUTPUT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            ((DEBIT.OBJECT0 = :P_GOODS) OR (DEBIT.OBJECT0 IS NOT NULL AND :P_GOODS IS NULL)) AND
            ((DEBIT.OBJECT1 = :P_WAREHOUSE) OR (DEBIT.OBJECT1 IS NOT NULL AND :P_WAREHOUSE IS NULL))

            UNION ALL

            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            DEBIT.PRICE,
            0 INPUT_AMOUNT, 0 INPUT_SUM_OF_MONEY,
            DEBIT.AMOUNT OUTPUT_AMOUNT, DEBIT.OFFICIAL_SUM_OF_MONEY OUTPUT_SUM_OF_MONEY,
            CREDIT.OBJECT0 GOODS, CREDIT.OBJECT1 WAREHOUSE, DEBIT_ATOM.CODE ACCOUNT_CODE,
            ENTRIES.ID, 1 IS_OUTPUT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            ((CREDIT.OBJECT0 = :P_GOODS) OR (CREDIT.OBJECT0 IS NOT NULL AND :P_GOODS IS NULL)) AND
            ((CREDIT.OBJECT1 = :P_WAREHOUSE) OR (CREDIT.OBJECT1 IS NOT NULL AND :P_WAREHOUSE IS NULL))
        ) ABC
        LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = ABC.GOODS
        JOIN ATOMS GOODS_ATOMS ON GOODS_ATOMS.COMPANY = :P_COMPANY AND GOODS_ATOMS.ID = ABC.GOODS
        JOIN ATOM_STRINGS GOODS_ATOM_STRINGS ON GOODS_ATOM_STRINGS.COMPANY = :P_COMPANY AND GOODS_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_ATOM_STRINGS.ID = ABC.GOODS
        JOIN ATOM_STRINGS WAREHOUSE_ATOM_STRINGS ON WAREHOUSE_ATOM_STRINGS.COMPANY = :P_COMPANY AND WAREHOUSE_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND WAREHOUSE_ATOM_STRINGS.ID = ABC.WAREHOUSE
        ORDER BY ABC.WAREHOUSE, ABC.GOODS, INPUT_DATE, IS_OUTPUT, ABC.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :PRICE,
        :INPUT_AMOUNT, :INPUT_SUM_OF_MONEY, :OUTPUT_AMOUNT, :OUTPUT_SUM_OF_MONEY,
        :GOODS, :GOODS_CODE, :GOODS_NAME, :GOODS_UNIT, :WAREHOUSE, :WAREHOUSE_NAME, :ACCOUNT_CODE
    DO
    BEGIN
        IF(PREV_WAREHOUSE IS NULL OR PREV_WAREHOUSE <> WAREHOUSE OR PREV_GOODS IS NULL OR PREV_GOODS <> GOODS)THEN
        BEGIN
            PREV_WAREHOUSE = WAREHOUSE;
            PREV_GOODS = GOODS;

            SELECT AMOUNT, SUM_OF_MONEY
            FROM INT_SD_1_TK_1_VT_1_KHO_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :GOODS, :WAREHOUSE, :P_TU_NGAY)
            INTO :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY;
        END

        INVENTORY_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
        INVENTORY_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + INPUT_SUM_OF_MONEY - OUTPUT_SUM_OF_MONEY;

        ENDING_AMOUNT = INVENTORY_AMOUNT;
        ENDING_SUM_OF_MONEY = INVENTORY_SUM_OF_MONEY;

        HAS_VALUE = 1;
        SUSPEND;

        BEGINNING_AMOUNT = INVENTORY_AMOUNT;
        BEGINNING_SUM_OF_MONEY = INVENTORY_SUM_OF_MONEY;
    END

    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;

    IF(HAS_VALUE = 0 AND P_GOODS IS NOT NULL AND P_WAREHOUSE IS NOT NULL)THEN
    BEGIN
        SELECT AMOUNT, SUM_OF_MONEY
        FROM INT_SD_1_TK_1_VT_1_KHO_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_GOODS, :P_WAREHOUSE, :P_TU_NGAY)
        INTO :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY;

        SELECT ATOMS.CODE, ATOM_STRINGS.NAME, IIF(GOODS_STRINGS.UNIT IS NULL OR GOODS_STRINGS.UNIT = '',NULL,'(' || GOODS_STRINGS.UNIT || ')')
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_GOODS
        LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :P_GOODS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_GOODS
        INTO :GOODS_CODE, :GOODS_NAME, :GOODS_UNIT;

        SELECT ATOM_STRINGS.NAME
        FROM ATOM_STRINGS
        WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_WAREHOUSE
        INTO :WAREHOUSE_NAME;

        ENDING_AMOUNT = BEGINNING_AMOUNT;
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;

        SUSPEND;
    END
    ELSE
    BEGIN
        CODE = NULL;
        INPUT_DATE = NULL;
        VOUCHER_DATE = NULL;
        ACCOUNT_CODE = NULL;
        PRICE = NULL;
        INPUT_AMOUNT = NULL;
        INPUT_SUM_OF_MONEY = NULL;
        OUTPUT_AMOUNT = NULL;
        OUTPUT_SUM_OF_MONEY = NULL;
        INVENTORY_AMOUNT = NULL;
        INVENTORY_SUM_OF_MONEY = NULL;

        FOR
            SELECT GOODS, WAREHOUSE, AMOUNT, SUM_OF_MONEY
            FROM INT_SD_1_TK_VT_KHO_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
            WHERE
                NOT EXISTS (
                    SELECT 1
                    FROM DOCUMENTS
                    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                    JOIN CREDIT_DEBIT ON
                            CREDIT_DEBIT.COMPANY = :P_COMPANY AND
                            CREDIT_DEBIT.ENTRY = ENTRIES.ID AND
                            CREDIT_DEBIT.OBJECT0 = INT_SD_1_TK_VT_KHO_DN_C.GOODS AND
                            CREDIT_DEBIT.OBJECT1 = INT_SD_1_TK_VT_KHO_DN_C.WAREHOUSE
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
                    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                )
                AND
                ((INT_SD_1_TK_VT_KHO_DN_C.GOODS = :P_GOODS) OR (INT_SD_1_TK_VT_KHO_DN_C.GOODS IS NOT NULL AND :P_GOODS IS NULL)) AND
                ((INT_SD_1_TK_VT_KHO_DN_C.WAREHOUSE = :P_WAREHOUSE) OR (INT_SD_1_TK_VT_KHO_DN_C.WAREHOUSE IS NOT NULL AND :P_WAREHOUSE IS NULL))
            INTO :GOODS, :WAREHOUSE, :BEGINNING_AMOUNT, :BEGINNING_SUM_OF_MONEY
        DO
        BEGIN
            SELECT ATOMS.CODE, ATOM_STRINGS.NAME, IIF(GOODS_STRINGS.UNIT IS NULL OR GOODS_STRINGS.UNIT = '',NULL,'(' || GOODS_STRINGS.UNIT || ')')
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :GOODS
            LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :GOODS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :GOODS
            INTO :GOODS_CODE, :GOODS_NAME, :GOODS_UNIT;

            SELECT ATOM_STRINGS.NAME
            FROM ATOM_STRINGS
            WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :WAREHOUSE
            INTO :WAREHOUSE_NAME;

            ENDING_AMOUNT = BEGINNING_AMOUNT;
            ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_NGUON_VON (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_4111 DM_DOUBLE,
BEGINNING_4112 DM_DOUBLE,
BEGINNING_4118 DM_DOUBLE,
RISING_DEBIT_4111 DM_DOUBLE,
RISING_CREDIT_4111 DM_DOUBLE,
RISING_DEBIT_4112 DM_DOUBLE,
RISING_CREDIT_4112 DM_DOUBLE,
RISING_DEBIT_4118 DM_DOUBLE,
RISING_CREDIT_4118 DM_DOUBLE,
BALANCE_4111 DM_DOUBLE,
BALANCE_4112 DM_DOUBLE,
BALANCE_4118 DM_DOUBLE,
ENDING_4111 DM_DOUBLE,
ENDING_4112 DM_DOUBLE,
ENDING_4118 DM_DOUBLE)
AS 
DECLARE VARIABLE DOCUMENT_CONTENT DM_CONTENT;
DECLARE VARIABLE ACCOUNT_CODE_411 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_4111 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_4112 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_4118 DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    ACCOUNT_CODE_411 = '411';
    ACCOUNT_CODE_4111 = '4111';
    ACCOUNT_CODE_4112 = '4112';
    ACCOUNT_CODE_4118 = '4118';

    SELECT CREDIT - DEBIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE_4111, :P_TU_NGAY)
    INTO :BEGINNING_4111;

    SELECT CREDIT - DEBIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE_4112, :P_TU_NGAY)
    INTO :BEGINNING_4112;

    SELECT CREDIT - DEBIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE_4118, :P_TU_NGAY)
    INTO :BEGINNING_4118;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_411 OR CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_411)
        GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :DOCUMENT_CONTENT, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(CONTENT IS NULL OR CONTENT = '')THEN CONTENT = :DOCUMENT_CONTENT;

        
        IF(DEBIT_ACCOUNT_CODE STARTING WITH ACCOUNT_CODE_4111)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT_4111 = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT_4111 = 0;

            RISING_DEBIT_4112 = 0;
            RISING_CREDIT_4112 = 0;
            RISING_DEBIT_4118 = 0;
            RISING_CREDIT_4118 = 0;

            BALANCE_4111 = BEGINNING_4111 + RISING_CREDIT_4111 - RISING_DEBIT_4111;

            HAS_VALUE = 1;

            ENDING_4111 = BALANCE_4111;

            SUSPEND;

            BEGINNING_4111 = BALANCE_4111;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH ACCOUNT_CODE_4111)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT_4111 = 0;
            RISING_CREDIT_4111 = OFFICIAL_SUM_OF_MONEY;

            RISING_DEBIT_4112 = 0;
            RISING_CREDIT_4112 = 0;
            RISING_DEBIT_4118 = 0;
            RISING_CREDIT_4118 = 0;

            BALANCE_4111 = BEGINNING_4111 + RISING_CREDIT_4111 - RISING_DEBIT_4111;

            HAS_VALUE = 1;

            ENDING_4111 = BALANCE_4111;

            SUSPEND;

            BEGINNING_4111 = BALANCE_4111;
        END

        
        IF(DEBIT_ACCOUNT_CODE STARTING WITH ACCOUNT_CODE_4112)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT_4112 = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT_4112 = 0;

            RISING_DEBIT_4111 = 0;
            RISING_CREDIT_4111 = 0;
            RISING_DEBIT_4118 = 0;
            RISING_CREDIT_4118 = 0;

            BALANCE_4112 = BEGINNING_4112 + RISING_CREDIT_4112 - RISING_DEBIT_4112;

            HAS_VALUE = 1;

            ENDING_4112 = BALANCE_4112;

            SUSPEND;

            BEGINNING_4112 = BALANCE_4112;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH ACCOUNT_CODE_4112)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT_4112 = 0;
            RISING_CREDIT_4112 = OFFICIAL_SUM_OF_MONEY;

            RISING_DEBIT_4111 = 0;
            RISING_CREDIT_4111 = 0;
            RISING_DEBIT_4118 = 0;
            RISING_CREDIT_4118 = 0;

            BALANCE_4112 = BEGINNING_4112 + RISING_CREDIT_4112 - RISING_DEBIT_4112;

            HAS_VALUE = 1;

            ENDING_4112 = BALANCE_4112;

            SUSPEND;

            BEGINNING_4112 = BALANCE_4112;
        END

        
        IF(DEBIT_ACCOUNT_CODE STARTING WITH ACCOUNT_CODE_4118)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT_4118 = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT_4118 = 0;

            RISING_DEBIT_4111 = 0;
            RISING_CREDIT_4111 = 0;
            RISING_DEBIT_4112 = 0;
            RISING_CREDIT_4112 = 0;

            BALANCE_4118 = BEGINNING_4118 + RISING_CREDIT_4118 - RISING_DEBIT_4118;

            HAS_VALUE = 1;

            ENDING_4118 = BALANCE_4118;

            SUSPEND;

            BEGINNING_4118 = BALANCE_4118;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH ACCOUNT_CODE_4118)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT_4118 = 0;
            RISING_CREDIT_4118 = OFFICIAL_SUM_OF_MONEY;

            RISING_DEBIT_4111 = 0;
            RISING_CREDIT_4111 = 0;
            RISING_DEBIT_4112 = 0;
            RISING_CREDIT_4112 = 0;

            BALANCE_4118 = BEGINNING_4118 + RISING_CREDIT_4118 - RISING_DEBIT_4118;

            HAS_VALUE = 1;

            ENDING_4118 = BALANCE_4118;

            SUSPEND;

            BEGINNING_4118 = BALANCE_4118;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_4111 = BEGINNING_4111;
        ENDING_4112 = BEGINNING_4112;
        ENDING_4118 = BEGINNING_4118;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_SHOW_DETAIL DM_BOOL)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
SUM_RISING_DEBIT_MONTH DM_DOUBLE,
SUM_RISING_CREDIT_MONTH DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
INPUT_MONTH DM_INTEGER,
INPUT_YEAR DM_INTEGER)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE CREDIT_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE NOT154X2 DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE NEW_INPUT_MONTH DM_INTEGER;
DECLARE VARIABLE NEW_INPUT_YEAR DM_INTEGER;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512), BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 4096)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME, :NOT154X2;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(NOT154X2 > 0 AND PARENT_ACCOUNT_CODE NOT STARTING WITH '154')THEN
        NOT154X2 = 0;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    SUM_RISING_DEBIT_MONTH = 0;
    SUM_RISING_CREDIT_MONTH = 0;
    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(:P_SHOW_DETAIL = 0, DOCUMENT_BASE_STRINGS.CONTENT, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')')) CONTENT,
        SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
        SUM(CREDIT.OFFICIAL_SUM_OF_MONEY),
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
        LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE, ATOM_DOCUMENT_TEAMS.CODE
        ORDER BY INPUT_DATE,
        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PT', 0,
            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PC', 5,
                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBCO', 10,
                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBNO', 15,
                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTTH', 75,
                            IIF(ATOM_DOCUMENT_TEAMS.CODE = 'BTK', 80,
                                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'TKHTS', 85,
                                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'CPTT', 90,
                                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTPB', 95,
                                            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTKC', 100, 50)
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        
        CODE_NUMBER,
        AVG(ENTRIES.ID)
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :DEBIT_OFFICIAL_SUM_OF_MONEY, :CREDIT_OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        NEW_INPUT_MONTH = EXTRACT(MONTH FROM INPUT_DATE);
        NEW_INPUT_YEAR = EXTRACT(YEAR FROM INPUT_DATE);
        IF(INPUT_MONTH IS NULL OR INPUT_YEAR IS NULL OR NEW_INPUT_MONTH <> INPUT_MONTH OR NEW_INPUT_YEAR <> INPUT_YEAR)THEN
        BEGIN
            INPUT_YEAR = NEW_INPUT_YEAR;
            INPUT_MONTH = NEW_INPUT_MONTH;

            SUM_RISING_CREDIT_MONTH = 0;
            SUM_RISING_DEBIT_MONTH = 0;
        END

        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = DEBIT_OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            IF(NOT154X2 = 0 OR CREDIT_ACCOUNT_CODE NOT STARTING WITH PARENT_ACCOUNT_CODE)THEN
            BEGIN
                SUM_RISING_DEBIT_MONTH = SUM_RISING_DEBIT_MONTH + RISING_DEBIT;
                SUM_RISING_CREDIT_MONTH = SUM_RISING_CREDIT_MONTH + RISING_CREDIT;

                SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
                SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            END

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = CREDIT_OFFICIAL_SUM_OF_MONEY;

            IF(NOT154X2 = 0 OR DEBIT_ACCOUNT_CODE NOT STARTING WITH PARENT_ACCOUNT_CODE)THEN
            BEGIN
                SUM_RISING_DEBIT_MONTH = SUM_RISING_DEBIT_MONTH + RISING_DEBIT;
                SUM_RISING_CREDIT_MONTH = SUM_RISING_CREDIT_MONTH + RISING_CREDIT;

                SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
                SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            END

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_1DT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
SUM_BEGINNING_DEBIT DM_DOUBLE,
SUM_BEGINNING_CREDIT DM_DOUBLE,
SUM_ENDING_DEBIT DM_DOUBLE,
SUM_ENDING_CREDIT DM_DOUBLE,
OBJECT_NAME DM_NAME)
AS 
BEGIN
    FOR
        SELECT CODE ,
        INPUT_DATE ,
        VOUCHER_DATE ,
        CONTENT ,
        ACCOUNT_CODE ,
        BEGINNING_DEBIT ,
        BEGINNING_CREDIT ,
        RISING_DEBIT ,
        RISING_CREDIT ,
        BALANCE_DEBIT ,
        BALANCE_CREDIT ,
        ENDING_DEBIT ,
        ENDING_CREDIT ,
        OBJECT_NAME
        FROM INT_SO_CHI_TIET_TAI_KHOAN_1DT(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_ACCOUNT, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
        ORDER BY OBJECT_NAME, STT
        INTO
        :CODE ,
        :INPUT_DATE ,
        :VOUCHER_DATE ,
        :CONTENT ,
        :ACCOUNT_CODE ,
        :BEGINNING_DEBIT ,
        :BEGINNING_CREDIT ,
        :RISING_DEBIT ,
        :RISING_CREDIT ,
        :BALANCE_DEBIT ,
        :BALANCE_CREDIT ,
        :ENDING_DEBIT ,
        :ENDING_CREDIT ,
        :OBJECT_NAME
    DO
    BEGIN
        IF(SUM_ENDING_DEBIT IS NULL)THEN
        BEGIN
            SELECT BEGINNING_DEBIT, BEGINNING_CREDIT, ENDING_DEBIT, ENDING_CREDIT
            FROM TEMP_SUM_DEBIT_CREDIT
            INTO :SUM_BEGINNING_DEBIT, :SUM_BEGINNING_CREDIT, :SUM_ENDING_DEBIT, :SUM_ENDING_CREDIT;
        END
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_1_BEN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_SIDE_TYPE DM_SIDE,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ROW_CODE DM_CODE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
RISING DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE SUM_RISING DM_DOUBLE;
BEGIN
    SUM_RISING = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    
    IF(P_SIDE_TYPE = 0)THEN
    BEGIN
        FOR
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
            CREDIT_ATOM.CODE
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT,
            CREDIT_ATOM.CODE
            ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :RISING,
            :ACCOUNT_CODE
        DO
        BEGIN
            SUM_RISING = SUM_RISING + RISING;

            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT, SUM(CREDIT.OFFICIAL_SUM_OF_MONEY),
            DEBIT_ATOM.CODE
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT,
            DEBIT_ATOM.CODE
            ORDER BY INPUT_DATE, AVG(ENTRIES.ID)
            INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :RISING,
            :ACCOUNT_CODE
        DO
        BEGIN
            SUM_RISING = SUM_RISING + RISING;

            SUSPEND;
        END
    END
    
    
    ROW_CODE = 'TC';
    CODE = NULL;
    INPUT_DATE = NULL;
    VOUCHER_DATE = NULL;
    ACCOUNT_CODE = NULL;
    RISING = SUM_RISING;
    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 4 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;

    SUSPEND;
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_2DT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
OBJECT0_CODE DM_CODE,
OBJECT0_NAME DM_NAME,
OBJECT1_CODE DM_CODE,
OBJECT1_NAME DM_NAME)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE PREV_OBJECT0 DM_ID;
DECLARE VARIABLE PREV_OBJECT1 DM_ID;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    PREV_OBJECT0 = NULL;
    PREV_OBJECT1 = NULL;

    FOR
        SELECT CODENUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
            RISING_DEBIT, RISING_CREDIT,
            ACCOUNT_CODE,
            OBJECT0, OBJECT1,
            OBJECT0_ATOMS.CODE, OBJECT0_ATOM_STRINGS.NAME,
            OBJECT1_ATOMS.CODE, OBJECT1_ATOM_STRINGS.NAME
        FROM
        (
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) AS CONTENT,
            DEBIT.OFFICIAL_SUM_OF_MONEY RISING_DEBIT,
            0 RISING_CREDIT,
            CREDIT_ATOM.CODE ACCOUNT_CODE,
            DEBIT.OBJECT0, DEBIT.OBJECT1,
            ATOM_DOCUMENT_TEAMS.CODE DOCUMENT_TEAM_CODE,
            ENTRIES.ID ENTRY_ID
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
            JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
            LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            ((DEBIT.OBJECT0 = :P_OBJECT0) OR (DEBIT.OBJECT0 IS NOT NULL AND :P_OBJECT0 IS NULL)) AND
            ((DEBIT.OBJECT1 = :P_OBJECT1) OR (DEBIT.OBJECT1 IS NOT NULL AND :P_OBJECT1 IS NULL))

            UNION ALL

            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) AS CONTENT,
            0 RISING_DEBIT,
            CREDIT.OFFICIAL_SUM_OF_MONEY RISING_CREDIT,
            DEBIT_ATOM.CODE ACCOUNT_CODE,
            CREDIT.OBJECT0, CREDIT.OBJECT1,
            ATOM_DOCUMENT_TEAMS.CODE DOCUMENT_TEAM_CODE,
            ENTRIES.ID ENTRY_ID
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
            JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
            LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            ((CREDIT.OBJECT0 = :P_OBJECT0) OR (CREDIT.OBJECT0 IS NOT NULL AND :P_OBJECT0 IS NULL)) AND
            ((CREDIT.OBJECT1 = :P_OBJECT1) OR (CREDIT.OBJECT1 IS NOT NULL AND :P_OBJECT1 IS NULL))
        ) A
        JOIN ATOMS OBJECT0_ATOMS ON OBJECT0_ATOMS.COMPANY = :P_COMPANY AND OBJECT0_ATOMS.ID = A.OBJECT0
        JOIN ATOM_STRINGS OBJECT0_ATOM_STRINGS ON OBJECT0_ATOM_STRINGS.COMPANY = :P_COMPANY AND OBJECT0_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND OBJECT0_ATOM_STRINGS.ID = A.OBJECT0
        JOIN ATOMS OBJECT1_ATOMS ON OBJECT1_ATOMS.COMPANY = :P_COMPANY AND OBJECT1_ATOMS.ID = A.OBJECT1
        JOIN ATOM_STRINGS OBJECT1_ATOM_STRINGS ON OBJECT1_ATOM_STRINGS.COMPANY = :P_COMPANY AND OBJECT1_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND OBJECT1_ATOM_STRINGS.ID = A.OBJECT1
        ORDER BY OBJECT0, OBJECT1, INPUT_DATE,
        IIF(DOCUMENT_TEAM_CODE STARTING WITH 'PT', 0,
            IIF(DOCUMENT_TEAM_CODE STARTING WITH 'PC', 5,
                IIF(DOCUMENT_TEAM_CODE STARTING WITH 'GBCO', 10,
                    IIF(DOCUMENT_TEAM_CODE STARTING WITH 'GBNO', 15,
                        IIF(DOCUMENT_TEAM_CODE STARTING WITH 'BTTH', 75,
                            IIF(DOCUMENT_TEAM_CODE = 'BTK', 80,
                                IIF(DOCUMENT_TEAM_CODE STARTING WITH 'TKHTS', 85,
                                    IIF(DOCUMENT_TEAM_CODE STARTING WITH 'CPTT', 90,
                                        IIF(DOCUMENT_TEAM_CODE STARTING WITH 'BTPB', 95,
                                            IIF(DOCUMENT_TEAM_CODE STARTING WITH 'BTKC', 100, 50)
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        CODENUMBER,
        ENTRY_ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :RISING_DEBIT, :RISING_CREDIT,
        :ACCOUNT_CODE,
        :OBJECT0, :OBJECT1,
        :OBJECT0_CODE, :OBJECT0_NAME, :OBJECT1_CODE, :OBJECT1_NAME
    DO
    BEGIN
        IF(PREV_OBJECT0 IS NULL OR PREV_OBJECT0 <> OBJECT0 OR PREV_OBJECT1 IS NULL OR PREV_OBJECT1 <> OBJECT1)THEN
        BEGIN
            PREV_OBJECT0 = OBJECT0;
            PREV_OBJECT1 = OBJECT1;

            SELECT DEBIT, CREDIT
            FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT0, :OBJECT1, :P_TU_NGAY)
            INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;
        END

        BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

        IF(BALANCE_DEBIT > 0)THEN
            BALANCE_CREDIT = 0;
        ELSE
        BEGIN
            BALANCE_CREDIT = ABS(BALANCE_DEBIT);
            BALANCE_DEBIT = 0;
        END

        ENDING_DEBIT = BALANCE_DEBIT;
        ENDING_CREDIT = BALANCE_CREDIT;

        HAS_VALUE = 1;
        SUSPEND;

        BEGINNING_DEBIT = BALANCE_DEBIT;
        BEGINNING_CREDIT = BALANCE_CREDIT;
    END

    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;

    IF(HAS_VALUE = 0 AND P_OBJECT0 IS NOT NULL AND P_OBJECT1 IS NOT NULL)THEN
    BEGIN
        SELECT DEBIT, CREDIT
        FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT0, :OBJECT1, :P_TU_NGAY)
        INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

        SELECT ATOMS.CODE, ATOM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
        INTO :OBJECT0_CODE, :OBJECT0_NAME;

        SELECT ATOMS.CODE, ATOM_STRINGS.NAME
        FROM ATOMS
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT1
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT1
        INTO :OBJECT1_CODE, :OBJECT1_NAME;

        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SUSPEND;
    END
    ELSE
    BEGIN
        CODE = NULL;
        INPUT_DATE = NULL;
        VOUCHER_DATE = NULL;
        ACCOUNT_CODE = NULL;
        RISING_DEBIT = NULL;
        RISING_CREDIT = NULL;
        BALANCE_DEBIT = NULL;
        BALANCE_CREDIT = NULL;

        FOR
            SELECT OBJECT0, OBJECT1, DEBIT, CREDIT
            FROM INT_SD_1_TK_DT0_DT1_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
            WHERE
                NOT EXISTS (
                    SELECT 1
                    FROM DOCUMENTS
                    JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
                    JOIN CREDIT_DEBIT ON
                            CREDIT_DEBIT.COMPANY = :P_COMPANY AND
                            CREDIT_DEBIT.ENTRY = ENTRIES.ID AND
                            CREDIT_DEBIT.OBJECT0 = INT_SD_1_TK_DT0_DT1_DN_C.OBJECT0 AND
                            CREDIT_DEBIT.OBJECT1 = INT_SD_1_TK_DT0_DT1_DN_C.OBJECT1
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = CREDIT_DEBIT.ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
                    WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
                )
                AND
                ((INT_SD_1_TK_DT0_DT1_DN_C.OBJECT0 = :P_OBJECT0) OR (INT_SD_1_TK_DT0_DT1_DN_C.OBJECT0 IS NOT NULL AND :P_OBJECT0 IS NULL)) AND
                ((INT_SD_1_TK_DT0_DT1_DN_C.OBJECT1 = :P_OBJECT1) OR (INT_SD_1_TK_DT0_DT1_DN_C.OBJECT1 IS NOT NULL AND :P_OBJECT1 IS NULL))
            INTO :OBJECT0, :OBJECT1, :BEGINNING_DEBIT, :BEGINNING_CREDIT
        DO
        BEGIN
            SELECT ATOMS.CODE, ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE, :OBJECT0_NAME;

            SELECT ATOMS.CODE, ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT1
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE, :OBJECT1_NAME;

            ENDING_DEBIT = BEGINNING_DEBIT;
            ENDING_CREDIT = BEGINNING_CREDIT;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_ALL (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_SHOW_DETAIL DM_BOOL)
RETURNS (SOURCES DM_NOTE,
SOURCE_ACCOUNT_ID DM_ID,
SOURCE_ACCOUNT_CODE DM_CODE,
SOURCE_ACCOUNT_NAME DM_NAME,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
SUM_RISING_DEBIT_MONTH DM_DOUBLE,
SUM_RISING_CREDIT_MONTH DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
INPUT_MONTH DM_INTEGER,
INPUT_YEAR DM_INTEGER)
AS 
BEGIN
    SELECT LIST(CODE)
    FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 0)
    WHERE PARENT_ID IS NULL
    INTO :SOURCES;

    FOR
        SELECT ID, CODE, NAME
        FROM RPT_BANG_CAN_DOI_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_TU_NGAY, :P_DEN_NGAY, 0)
        WHERE PARENT_ID IS NULL AND
        (BEGINNING_DEBIT <> 0 OR BEGINNING_CREDIT <> 0 OR RISING_DEBIT <> 0 OR RISING_CREDIT <> 0 OR ENDING_DEBIT <> 0 OR ENDING_CREDIT <> 0)
        INTO :SOURCE_ACCOUNT_ID, :SOURCE_ACCOUNT_CODE, :SOURCE_ACCOUNT_NAME
    DO
    BEGIN
        FOR
            SELECT CODE,INPUT_DATE,VOUCHER_DATE,CONTENT,ACCOUNT_CODE,
            BEGINNING_DEBIT,BEGINNING_CREDIT,RISING_DEBIT,RISING_CREDIT,
            SUM_RISING_DEBIT_MONTH, SUM_RISING_CREDIT_MONTH,
            SUM_RISING_DEBIT,SUM_RISING_CREDIT,BALANCE_DEBIT,BALANCE_CREDIT,ENDING_DEBIT,ENDING_CREDIT,
            INPUT_MONTH,INPUT_YEAR
            FROM RPT_SO_CHI_TIET_TAI_KHOAN(:P_LANGUAGE, :P_COMPANY, :P_ID, :SOURCE_ACCOUNT_ID, :P_TU_NGAY, :P_DEN_NGAY, :P_SHOW_DETAIL)
            INTO :CODE,:INPUT_DATE,:VOUCHER_DATE,:CONTENT,:ACCOUNT_CODE,
            :BEGINNING_DEBIT,:BEGINNING_CREDIT,:RISING_DEBIT,:RISING_CREDIT,
            :SUM_RISING_DEBIT_MONTH, :SUM_RISING_CREDIT_MONTH,
            :SUM_RISING_DEBIT,:SUM_RISING_CREDIT,:BALANCE_DEBIT,:BALANCE_CREDIT,:ENDING_DEBIT,:ENDING_CREDIT,
            :INPUT_MONTH,:INPUT_YEAR
        DO
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_NGANG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ROW_CODE DM_CODE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE SUM_RISING_DEBIT DM_DOUBLE;
DECLARE VARIABLE SUM_RISING_CREDIT DM_DOUBLE;
DECLARE VARIABLE TEMP_BALANCE_DEBIT DM_DOUBLE;
DECLARE VARIABLE TEMP_BALANCE_CREDIT DM_DOUBLE;
BEGIN
    HAS_VALUE = 0;
    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    
    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 2 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;
    BALANCE_DEBIT = BEGINNING_DEBIT;
    BALANCE_CREDIT = BEGINNING_CREDIT;

    SUSPEND;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT, SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        GROUP BY CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,ENTRY_BASE_STRINGS.CONTENT,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        ORDER BY INPUT_DATE, IIF(:PARENT_ACCOUNT_CODE STARTING WITH '11' AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) DESC, AVG(ENTRIES.ID)
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;
            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END
    
    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END

    
    ROW_CODE = 'TC';
    CODE = NULL;
    INPUT_DATE = NULL;
    VOUCHER_DATE = NULL;
    ACCOUNT_CODE = NULL;
    BEGINNING_DEBIT = NULL;
    BEGINNING_CREDIT = NULL;
    RISING_DEBIT = SUM_RISING_DEBIT;
    RISING_CREDIT = SUM_RISING_CREDIT;
    ENDING_DEBIT = NULL;
    ENDING_CREDIT = NULL;
    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 4 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;

    
    TEMP_BALANCE_DEBIT = BALANCE_DEBIT;
    TEMP_BALANCE_CREDIT = BALANCE_CREDIT;
    BALANCE_DEBIT = NULL;
    BALANCE_CREDIT = NULL;

    SUSPEND;

    
    ROW_CODE = NULL;
    CODE = NULL;
    INPUT_DATE = NULL;
    VOUCHER_DATE = NULL;
    ACCOUNT_CODE = NULL;
    BEGINNING_DEBIT = NULL;
    BEGINNING_CREDIT = NULL;
    RISING_DEBIT = NULL;
    RISING_CREDIT = NULL;
    ENDING_DEBIT = NULL;
    ENDING_CREDIT = NULL;
    SELECT CONTENT
    FROM TEXTS
    WHERE TEXTS.ID = 3 AND TEXTS.LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;
    BALANCE_DEBIT = TEMP_BALANCE_DEBIT;
    BALANCE_CREDIT = TEMP_BALANCE_CREDIT;

    SUSPEND;
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_TT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE,
        IIF(DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, DEBIT.FOREIGN_SUM_OF_MONEY, CREDIT.FOREIGN_SUM_OF_MONEY),
        IIF(DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, DEBIT.OFFICIAL_SUM_OF_MONEY, CREDIT.OFFICIAL_SUM_OF_MONEY),
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND (CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        ORDER BY INPUT_DATE, IIF(:PARENT_ACCOUNT_CODE STARTING WITH '11' AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) DESC
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
            RISING_FOREIGN_CREDIT = 0;
            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = 0;
            RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_TT_1 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_ONLY_FOREIGN_CURRENCY DM_BOOL)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE,
SUM_BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
SUM_BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
SUM_ENDING_FOREIGN_DEBIT DM_DOUBLE,
SUM_ENDING_FOREIGN_CREDIT DM_DOUBLE,
SUM_BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
SUM_BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
SUM_ENDING_OFFICIAL_DEBIT DM_DOUBLE,
SUM_ENDING_OFFICIAL_CREDIT DM_DOUBLE,
OBJECT_NAME DM_NAME)
AS 
declare variable parent_account_code dm_code;
declare variable object dm_id;
declare variable has_value dm_bool;
declare variable entry_currency dm_id;
declare variable prev_object dm_id;
declare variable object_type dm_id;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    sum_beginning_foreign_debit = 0;
    sum_beginning_foreign_credit = 0;
    sum_ending_foreign_debit = 0;
    sum_ending_foreign_credit = 0;
    sum_beginning_official_debit = 0;
    sum_beginning_official_credit = 0;
    sum_ending_official_debit = 0;
    sum_ending_official_credit = 0;

    PREV_OBJECT = NULL;

    FOR
        SELECT CODENUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT, EXCHANGE_RATE,
        rising_foreign_debit, rising_official_debit,
        rising_foreign_credit, rising_official_credit,
        OBJECT0, ATOM_STRINGS.NAME, ACCOUNT_CODE, CURRENCY
        FROM
        (
            SELECT DOCUMENTS.CODE || '-' || NUMBER as CODENUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) as CONTENT, ENTRIES.EXCHANGE_RATE,
            DEBIT.FOREIGN_SUM_OF_MONEY rising_foreign_debit, DEBIT.OFFICIAL_SUM_OF_MONEY rising_official_debit,
            0 rising_foreign_credit, 0 rising_official_credit,
            DEBIT_ATOM.CODE ACCOUNT_CODE, DEBIT.OBJECT0,
            ENTRIES.CURRENCY
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
                DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
                (
                    DEBIT.OBJECT0 = :P_OBJECT0 OR
                    (:P_OBJECT0 IS NULL AND DEBIT.OBJECT0 IS NOT NULL)
                )

            UNION ALL

            SELECT DOCUMENTS.CODE || '-' || NUMBER as CODENUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) as CONTENT, ENTRIES.EXCHANGE_RATE,
            0 rising_foreign_debit, 0 rising_official_debit,
            CREDIT.FOREIGN_SUM_OF_MONEY rising_foreign_credit, CREDIT.OFFICIAL_SUM_OF_MONEY rising_official_credit,
            CREDIT_ATOM.CODE ACCOUNT_CODE, CREDIT.OBJECT0,
            ENTRIES.CURRENCY
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
                CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
                (
                    CREDIT.OBJECT0 = :P_OBJECT0 OR
                    (:P_OBJECT0 IS NULL AND CREDIT.OBJECT0 IS NOT NULL)
                )
        ) ABC
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ABC.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ABC.OBJECT0
        where :p_only_foreign_currency = 0 or (:p_only_foreign_currency = 1 and abc.CURRENCY = :p_currency)
        ORDER BY OBJECT0, INPUT_DATE, IIF(:PARENT_ACCOUNT_CODE STARTING WITH '11' AND ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) DESC
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE,
        :rising_foreign_debit, :rising_official_debit,
        :rising_foreign_credit, :rising_official_credit,
        :object, :object_name, :ACCOUNT_CODE,
        :ENTRY_CURRENCY
    DO
    BEGIN
        IF(PREV_OBJECT IS NULL OR PREV_OBJECT <> OBJECT)THEN
        BEGIN
            PREV_OBJECT = OBJECT;

            SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY)
            INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

            SUM_BEGINNING_FOREIGN_DEBIT = SUM_BEGINNING_FOREIGN_DEBIT + BEGINNING_FOREIGN_DEBIT;
            SUM_BEGINNING_FOREIGN_CREDIT = SUM_BEGINNING_FOREIGN_CREDIT + BEGINNING_FOREIGN_CREDIT;
            SUM_BEGINNING_OFFICIAL_DEBIT = SUM_BEGINNING_OFFICIAL_DEBIT + BEGINNING_OFFICIAL_DEBIT;
            SUM_BEGINNING_OFFICIAL_CREDIT = SUM_BEGINNING_OFFICIAL_CREDIT + BEGINNING_OFFICIAL_CREDIT;

            ENDING_FOREIGN_DEBIT = 0;
            ENDING_FOREIGN_CREDIT = 0;
            ENDING_OFFICIAL_DEBIT = 0;
            ENDING_OFFICIAL_CREDIT = 0;
        END

        IF(ENTRY_CURRENCY = P_CURRENCY)THEN
        BEGIN
            
            
        END
        ELSE
        BEGIN
            RISING_FOREIGN_DEBIT = 0;
            RISING_FOREIGN_CREDIT = 0;
        END

        IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
        ELSE
            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT;

        IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
        ELSE
        BEGIN
            BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
            BALANCE_FOREIGN_DEBIT = 0;
        END

        BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

        IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
            BALANCE_OFFICIAL_CREDIT = 0;
        ELSE
        BEGIN
            BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
            BALANCE_OFFICIAL_DEBIT = 0;
        END

        SUM_ENDING_FOREIGN_DEBIT = SUM_ENDING_FOREIGN_DEBIT - ENDING_FOREIGN_DEBIT;
        SUM_ENDING_FOREIGN_CREDIT = SUM_ENDING_FOREIGN_CREDIT - ENDING_FOREIGN_CREDIT;
        SUM_ENDING_OFFICIAL_DEBIT = SUM_ENDING_OFFICIAL_DEBIT - ENDING_OFFICIAL_DEBIT;
        SUM_ENDING_OFFICIAL_CREDIT = SUM_ENDING_OFFICIAL_CREDIT - ENDING_OFFICIAL_CREDIT;

        ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

        SUM_ENDING_FOREIGN_DEBIT = SUM_ENDING_FOREIGN_DEBIT + ENDING_FOREIGN_DEBIT;
        SUM_ENDING_FOREIGN_CREDIT = SUM_ENDING_FOREIGN_CREDIT + ENDING_FOREIGN_CREDIT;
        SUM_ENDING_OFFICIAL_DEBIT = SUM_ENDING_OFFICIAL_DEBIT + ENDING_OFFICIAL_DEBIT;
        SUM_ENDING_OFFICIAL_CREDIT = SUM_ENDING_OFFICIAL_CREDIT + ENDING_OFFICIAL_CREDIT;

        HAS_VALUE = 1;

        SUSPEND;

        BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
        BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
        BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
        BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

        UPDATE OR INSERT INTO TEMP_ATOMS(ID)
        VALUES(:OBJECT);
    END

    IF(P_OBJECT0 IS NULL)THEN
    BEGIN
        SELECT ACCOUNTS.ATOM_TYPE_0
        FROM ACCOUNTS
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ACCOUNT
        INTO :OBJECT_TYPE;

        IF(OBJECT_TYPE IS NOT NULL)THEN
        BEGIN
            CODE = NULL;
            INPUT_DATE = NULL;
            VOUCHER_DATE = NULL;
            
            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :CONTENT;
            ACCOUNT_CODE = NULL;
            exchange_rate = NULL;
            rising_foreign_debit = NULL;
            rising_foreign_credit = NULL;
            balance_foreign_debit = NULL;
            balance_foreign_credit = NULL;
            rising_official_debit = NULL;
            rising_official_credit = NULL;
            balance_official_debit = NULL;
            balance_official_credit = NULL;

            FOR
                SELECT ATOMS.ID, ATOM_STRINGS.NAME
                FROM ATOMS
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.OBJECT_TYPE = :OBJECT_TYPE AND
                    NOT EXISTS(SELECT 1 FROM TEMP_ATOMS WHERE TEMP_ATOMS.ID = ATOMS.ID)
                INTO :OBJECT, :OBJECT_NAME
            DO
            BEGIN
                SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
                FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY)
                INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

                IF(BEGINNING_FOREIGN_DEBIT <> 0 or BEGINNING_FOREIGN_CREDIT <> 0 or BEGINNING_OFFICIAL_DEBIT <> 0 or BEGINNING_OFFICIAL_CREDIT <> 0 )THEN
                BEGIN
                    SUM_BEGINNING_FOREIGN_DEBIT = SUM_BEGINNING_FOREIGN_DEBIT + BEGINNING_FOREIGN_DEBIT;
                    SUM_BEGINNING_FOREIGN_CREDIT = SUM_BEGINNING_FOREIGN_CREDIT + BEGINNING_FOREIGN_CREDIT;
                    SUM_BEGINNING_OFFICIAL_DEBIT = SUM_BEGINNING_OFFICIAL_DEBIT + BEGINNING_OFFICIAL_DEBIT;
                    SUM_BEGINNING_OFFICIAL_CREDIT = SUM_BEGINNING_OFFICIAL_CREDIT + BEGINNING_OFFICIAL_CREDIT;
        
                    ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
                    ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
                    ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
                    ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

                    SUM_ENDING_FOREIGN_DEBIT = SUM_ENDING_FOREIGN_DEBIT + ENDING_FOREIGN_DEBIT;
                    SUM_ENDING_FOREIGN_CREDIT = SUM_ENDING_FOREIGN_CREDIT + ENDING_FOREIGN_CREDIT;
                    SUM_ENDING_OFFICIAL_DEBIT = SUM_ENDING_OFFICIAL_DEBIT + ENDING_OFFICIAL_DEBIT;
                    SUM_ENDING_OFFICIAL_CREDIT = SUM_ENDING_OFFICIAL_CREDIT + ENDING_OFFICIAL_CREDIT;

                    SUSPEND;
                END
            END
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        IF(P_OBJECT0 IS NOT NULL)THEN
        BEGIN
            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :CONTENT;

            SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)
            INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

            SUM_BEGINNING_FOREIGN_DEBIT = SUM_BEGINNING_FOREIGN_DEBIT + BEGINNING_FOREIGN_DEBIT;
            SUM_BEGINNING_FOREIGN_CREDIT = SUM_BEGINNING_FOREIGN_CREDIT + BEGINNING_FOREIGN_CREDIT;
            SUM_BEGINNING_OFFICIAL_DEBIT = SUM_BEGINNING_OFFICIAL_DEBIT + BEGINNING_OFFICIAL_DEBIT;
            SUM_BEGINNING_OFFICIAL_CREDIT = SUM_BEGINNING_OFFICIAL_CREDIT + BEGINNING_OFFICIAL_CREDIT;

            SELECT ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
            INTO :OBJECT_NAME;

            ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

            SUM_ENDING_FOREIGN_DEBIT = SUM_ENDING_FOREIGN_DEBIT - ENDING_FOREIGN_DEBIT;
            SUM_ENDING_FOREIGN_CREDIT = SUM_ENDING_FOREIGN_CREDIT - ENDING_FOREIGN_CREDIT;
            SUM_ENDING_OFFICIAL_DEBIT = SUM_ENDING_OFFICIAL_DEBIT - ENDING_OFFICIAL_DEBIT;
            SUM_ENDING_OFFICIAL_CREDIT = SUM_ENDING_OFFICIAL_CREDIT - ENDING_OFFICIAL_CREDIT;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TAI_KHOAN_TT_2 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT1 DM_ID;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE,
        DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0, DEBIT.OBJECT1,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0, CREDIT.OBJECT1
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        LEFT JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        LEFT JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        LEFT JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        LEFT JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        LEFT JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        LEFT JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_OBJECT0 AND DEBIT.OBJECT1 = :P_OBJECT1) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_OBJECT0 AND CREDIT.OBJECT1 = :P_OBJECT1))
        ORDER BY INPUT_DATE, IIF(:PARENT_ACCOUNT_CODE STARTING WITH '11' AND DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) DESC, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE,
        :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0, :DEBIT_OBJECT1,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0, :CREDIT_OBJECT1
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_OBJECT0 AND DEBIT_OBJECT1 = :P_OBJECT1)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
            RISING_FOREIGN_CREDIT = 0;
            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_OBJECT0 AND CREDIT_OBJECT1 = :P_OBJECT1)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = 0;
            RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CHI_TIET_TIEN_VAY (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_LOAN_AGREEMENT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT1 DM_ID;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_CUSTOMER, :P_LOAN_AGREEMENT, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'), DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0, DEBIT.OBJECT1,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0, CREDIT.OBJECT1
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_CUSTOMER AND DEBIT.OBJECT1 = :P_LOAN_AGREEMENT) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_CUSTOMER AND CREDIT.OBJECT1 = :P_LOAN_AGREEMENT))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0, :DEBIT_OBJECT1,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0, :CREDIT_OBJECT1
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_CUSTOMER AND DEBIT_OBJECT1 = :P_LOAN_AGREEMENT)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            ENDING_DEBIT = BEGINNING_DEBIT - BEGINNING_CREDIT + RISING_DEBIT - RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = ENDING_DEBIT;
            BEGINNING_CREDIT = ENDING_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER AND CREDIT_OBJECT1 = :P_LOAN_AGREEMENT)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            ENDING_DEBIT = BEGINNING_DEBIT - BEGINNING_CREDIT + RISING_DEBIT - RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = ENDING_DEBIT;
            BEGINNING_CREDIT = ENDING_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_DD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
DECREASE_CODE DM_DOCUMENT_CODE,
DECREASE_INPUT_DATE DM_DATE,
DECREASE_VOUCHER_DATE DM_DATE,
DECREASE_CONTENT DM_CONTENT,
DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
REMAIN_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
REMAIN_OFFICIAL_SUM_OF_MONEY_R DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE SUM_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_TU_NGAY)
    INTO :PERIOD;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SUM_OFFICIAL_SUM_OF_MONEY = 0;
    SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = 0;

    FOR
        SELECT ID, CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, OFFICIAL_SUM_OF_MONEY
        FROM
        (
            
            SELECT BEGINNING_DOCUMENTS.ID, BEGINNING_DOCUMENTS.CODE, INPUT_DATE, INPUT_DATE VOUCHER_DATE, CONTENT, BEGINNING_DOCUMENTS.OFFICIAL_CREDIT OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN BEGINNING_DOCUMENTS ON BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND BEGINNING_DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND BEGINNING_DOCUMENTS.INPUT_DATE <= :P_TU_NGAY AND (:P_OBJECT0 IS NULL OR BEGINNING_DOCUMENTS.OBJECT0 = :P_OBJECT0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = BEGINNING_DOCUMENTS.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = BEGINNING_DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND (DOCUMENT_BALANCES.OFFICIAL_CREDIT <> 0 OR DOCUMENT_BALANCES.FOREIGN_CREDIT <> 0)

            UNION ALL

            
            SELECT DOCUMENT_BALANCES.INCREASE_DOCUMENT ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND
            DOCUMENT_BALANCES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DOCUMENT_BALANCES.OBJECT0 = :P_OBJECT0)
            GROUP BY DOCUMENT_BALANCES.INCREASE_DOCUMENT, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENTS.ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            GROUP BY DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENT_BALANCES.INCREASE_DOCUMENT ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND
            DOCUMENT_BALANCES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DOCUMENT_BALANCES.OBJECT0 = :P_OBJECT0)
            GROUP BY DOCUMENT_BALANCES.INCREASE_DOCUMENT, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENTS.ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            GROUP BY DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER
        )
        ORDER BY INPUT_DATE ASC, ID ASC
        INTO :ID, :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        SUM_OFFICIAL_SUM_OF_MONEY = SUM_OFFICIAL_SUM_OF_MONEY + OFFICIAL_SUM_OF_MONEY;
        
        SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = 0;

        HAS_VALUE = 0;

        FOR
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(DECREASE_DOCUMENTS.OFFICIAL_SUM_OF_MONEY)
            FROM DECREASE_DOCUMENTS
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ID = DECREASE_DOCUMENTS.CREDIT_DEBIT AND
            CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0)
            JOIN ENTRIES ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND  ENTRIES.ID = CREDIT_DEBIT.ENTRY
            JOIN DOCUMENTS ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND  DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_DEN_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.INCREASE_DOCUMENT = :ID
            GROUP BY DOCUMENTS.CODE, DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT
            ORDER BY INPUT_DATE ASC
            INTO :DECREASE_CODE, :DECREASE_INPUT_DATE, :DECREASE_VOUCHER_DATE, :DECREASE_CONTENT, :DECREASE_OFFICIAL_SUM_OF_MONEY
        DO
        BEGIN
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY + DECREASE_OFFICIAL_SUM_OF_MONEY;
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT + DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY_R = SUM_OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT;

            HAS_VALUE = 1;

            SUSPEND;
        END

        IF(HAS_VALUE = 0)THEN
        BEGIN
            DECREASE_CODE = NULL;
            DECREASE_INPUT_DATE = NULL;
            DECREASE_VOUCHER_DATE = NULL;
            DECREASE_OFFICIAL_SUM_OF_MONEY = 0;

            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :DECREASE_CONTENT;

            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY + DECREASE_OFFICIAL_SUM_OF_MONEY;
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT + DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY_R = SUM_OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NB (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_CUSTOMER, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_CUSTOMER) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_CUSTOMER))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NB_DD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
DECREASE_CODE DM_DOCUMENT_CODE,
DECREASE_INPUT_DATE DM_DATE,
DECREASE_VOUCHER_DATE DM_DATE,
DECREASE_CONTENT DM_CONTENT,
DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
REMAIN_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
REMAIN_OFFICIAL_SUM_OF_MONEY_R DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE SUM_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_TU_NGAY)
    INTO :PERIOD;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SUM_OFFICIAL_SUM_OF_MONEY = 0;
    SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = 0;

    FOR
        SELECT ID, CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, OFFICIAL_SUM_OF_MONEY
        FROM
        (
            
            SELECT BEGINNING_DOCUMENTS.ID, BEGINNING_DOCUMENTS.CODE, INPUT_DATE, INPUT_DATE VOUCHER_DATE, CONTENT, BEGINNING_DOCUMENTS.OFFICIAL_CREDIT OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN BEGINNING_DOCUMENTS ON BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND BEGINNING_DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND BEGINNING_DOCUMENTS.INPUT_DATE <= :P_TU_NGAY AND (:P_OBJECT0 IS NULL OR BEGINNING_DOCUMENTS.OBJECT0 = :P_OBJECT0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = BEGINNING_DOCUMENTS.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = BEGINNING_DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND (DOCUMENT_BALANCES.OFFICIAL_CREDIT <> 0 OR DOCUMENT_BALANCES.FOREIGN_CREDIT <> 0)

            UNION ALL

            
            SELECT DOCUMENT_BALANCES.INCREASE_DOCUMENT ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND
            DOCUMENT_BALANCES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DOCUMENT_BALANCES.OBJECT0 = :P_OBJECT0)
            GROUP BY DOCUMENT_BALANCES.INCREASE_DOCUMENT, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENTS.ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            GROUP BY DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENT_BALANCES.INCREASE_DOCUMENT ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND
            DOCUMENT_BALANCES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DOCUMENT_BALANCES.OBJECT0 = :P_OBJECT0)
            GROUP BY DOCUMENT_BALANCES.INCREASE_DOCUMENT, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENTS.ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            GROUP BY DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER
        )
        ORDER BY INPUT_DATE ASC, ID ASC
        INTO :ID, :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        SUM_OFFICIAL_SUM_OF_MONEY = SUM_OFFICIAL_SUM_OF_MONEY + OFFICIAL_SUM_OF_MONEY;
        
        SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = 0;

        HAS_VALUE = 0;

        FOR
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(DECREASE_DOCUMENTS.OFFICIAL_SUM_OF_MONEY)
            FROM DECREASE_DOCUMENTS
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ID = DECREASE_DOCUMENTS.CREDIT_DEBIT AND
            CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0)
            JOIN ENTRIES ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND  ENTRIES.ID = CREDIT_DEBIT.ENTRY
            JOIN DOCUMENTS ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND  DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_DEN_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.INCREASE_DOCUMENT = :ID
            GROUP BY DOCUMENTS.CODE, DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT
            ORDER BY INPUT_DATE ASC
            INTO :DECREASE_CODE, :DECREASE_INPUT_DATE, :DECREASE_VOUCHER_DATE, :DECREASE_CONTENT, :DECREASE_OFFICIAL_SUM_OF_MONEY
        DO
        BEGIN
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY + DECREASE_OFFICIAL_SUM_OF_MONEY;
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT + DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY_R = SUM_OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT;

            HAS_VALUE = 1;

            SUSPEND;
        END

        IF(HAS_VALUE = 0)THEN
        BEGIN
            DECREASE_CODE = NULL;
            DECREASE_INPUT_DATE = NULL;
            DECREASE_VOUCHER_DATE = NULL;
            DECREASE_OFFICIAL_SUM_OF_MONEY = 0;

            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :DECREASE_CONTENT;

            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY + DECREASE_OFFICIAL_SUM_OF_MONEY;
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT + DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY_R = SUM_OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NB_SL_DG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
declare variable object0 dm_id;
declare variable parent_account_code dm_code;
declare variable print_report_person_name dm_integer;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(p_customer IS NULL)THEN
    BEGIN
        FOR
            SELECT distinct(OBJECT0) as OBJECT0, atoms.code, atom_strings.name
            FROM
            (
                SELECT OBJECT0
                FROM int_dt0_1_tk_dn_c(:p_company, :parent_account_code, :p_tu_ngay)

                UNION ALL

                SELECT OBJECT0
                FROM int_dt0_ps_1_tk_c(:p_company, :parent_account_code, :p_tu_ngay, :p_den_ngay)
            ) a
            join atoms on atoms.company = :p_company and atoms.id = a.object0
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            INTO :object0, :object_code, :OBJECT_NAME
        DO
        BEGIN
            FOR
                select code, input_date, voucher_date, content, account_code,
                    beginning_debit, beginning_credit,amount,price,rising_debit,rising_credit,balance_debit,balance_credit,ending_debit,ending_credit
                FROM int_so_ct_thanh_toan_nb_sl_dg(:p_language, :p_company, :parent_account_code, :object0, :p_tu_ngay, :p_den_ngay, :print_report_person_name)
                INTO :code, :input_date, :voucher_date, :content, :account_code,
                    :beginning_debit, :beginning_credit,:amount,:price,:rising_debit,:rising_credit,
                    :balance_debit,:balance_credit,:ending_debit,:ending_credit
            DO
            BEGIN
                SUSPEND;
            END
        END
    END
    ELSE
    BEGIN
        select code, name
        from atoms
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        where atoms.company = :p_company and atoms.id = :p_customer
        into :object_code, :object_name;

        FOR
            select code, input_date, voucher_date, content, account_code,
                beginning_debit, beginning_credit,amount,price,rising_debit,rising_credit,balance_debit,balance_credit,ending_debit,ending_credit
            FROM int_so_ct_thanh_toan_nb_sl_dg(:p_language, :p_company, :parent_account_code, :p_customer, :p_tu_ngay, :p_den_ngay, :print_report_person_name)
            INTO :code, :input_date, :voucher_date, :content, :account_code,
                :beginning_debit, :beginning_credit,:amount,:price,:rising_debit,:rising_credit,
                :balance_debit,:balance_credit,:ending_debit,:ending_credit
        DO
        BEGIN
            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NB_TT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
declare variable entry_currency dm_id;
declare variable parent_account_code dm_code;
declare variable debit_account_code dm_code;
declare variable debit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable foreign_sum_of_money dm_double;
declare variable official_sum_of_money dm_double;
declare variable has_value dm_bool;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_CUSTOMER, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE,
        DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0,
        ENTRIES.currency
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_CUSTOMER) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_CUSTOMER))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE,
        :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0,
        :entry_currency
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BEGIN
               RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
            END
            ELSE
            BEGIN
                RISING_FOREIGN_DEBIT = 0;
            END

            RISING_FOREIGN_CREDIT = 0; 

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;

            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BEGIN
               RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            END
            ELSE
            BEGIN
                RISING_FOREIGN_CREDIT = 0;
            END

            RISING_FOREIGN_DEBIT = 0;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NM (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_CUSTOMER, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_CUSTOMER) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_CUSTOMER))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            RISING_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_CREDIT = 0;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_DEBIT = 0;
            RISING_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_DEBIT = BEGINNING_DEBIT + RISING_DEBIT - BEGINNING_CREDIT - RISING_CREDIT;

            IF(BALANCE_DEBIT > 0)THEN
                BALANCE_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_CREDIT = ABS(BALANCE_DEBIT);
                BALANCE_DEBIT = 0;
            END

            ENDING_DEBIT = BALANCE_DEBIT;
            ENDING_CREDIT = BALANCE_CREDIT;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_DEBIT = BALANCE_DEBIT;
            BEGINNING_CREDIT = BALANCE_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_DEBIT = BEGINNING_DEBIT;
        ENDING_CREDIT = BEGINNING_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NM_DD (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
DECREASE_CODE DM_DOCUMENT_CODE,
DECREASE_INPUT_DATE DM_DATE,
DECREASE_VOUCHER_DATE DM_DATE,
DECREASE_CONTENT DM_CONTENT,
DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
REMAIN_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
REMAIN_OFFICIAL_SUM_OF_MONEY_R DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PERIOD DM_ID; 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE SUM_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_DECREASE_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_TU_NGAY)
    INTO :PERIOD;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SUM_OFFICIAL_SUM_OF_MONEY = 0;
    SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = 0;

    FOR
        SELECT ID, CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, OFFICIAL_SUM_OF_MONEY
        FROM
        (
            
            SELECT BEGINNING_DOCUMENTS.ID, BEGINNING_DOCUMENTS.CODE, INPUT_DATE, INPUT_DATE VOUCHER_DATE, CONTENT, BEGINNING_DOCUMENTS.OFFICIAL_CREDIT OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN BEGINNING_DOCUMENTS ON BEGINNING_DOCUMENTS.COMPANY = :P_COMPANY AND BEGINNING_DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND BEGINNING_DOCUMENTS.INPUT_DATE <= :P_TU_NGAY AND (:P_OBJECT0 IS NULL OR BEGINNING_DOCUMENTS.OBJECT0 = :P_OBJECT0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = BEGINNING_DOCUMENTS.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = BEGINNING_DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND (DOCUMENT_BALANCES.OFFICIAL_CREDIT <> 0 OR DOCUMENT_BALANCES.FOREIGN_CREDIT <> 0)

            UNION ALL

            
            SELECT DOCUMENT_BALANCES.INCREASE_DOCUMENT ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND
            DOCUMENT_BALANCES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DOCUMENT_BALANCES.OBJECT0 = :P_OBJECT0)
            GROUP BY DOCUMENT_BALANCES.INCREASE_DOCUMENT, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENTS.ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 0 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 98304) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            GROUP BY DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENT_BALANCES.INCREASE_DOCUMENT ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENT_BALANCES
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = DOCUMENT_BALANCES.INCREASE_DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_TU_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENT_BALANCES.COMPANY = :P_COMPANY AND DOCUMENT_BALANCES.PERIOD = :PERIOD AND
            DOCUMENT_BALANCES.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR DOCUMENT_BALANCES.OBJECT0 = :P_OBJECT0)
            GROUP BY DOCUMENT_BALANCES.INCREASE_DOCUMENT, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER

            UNION ALL

            
            SELECT DOCUMENTS.ID, DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY) OFFICIAL_SUM_OF_MONEY
            FROM DOCUMENTS
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.SIDE = 1 AND CREDIT_DEBIT.ENTRY = ENTRIES.ID AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0) AND CREDIT_DEBIT.ACCOUNT IN (SELECT ID FROM ACCOUNTS WHERE ACCOUNTS.COMPANY = :P_COMPANY AND BIN_AND(ACCOUNT_TYPES, 24576) <> 0)
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = CREDIT_DEBIT.ACCOUNT AND ACCOUNT_ATOMS.CODE STARTING WITH :PARENT_ACCOUNT_CODE
            WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            GROUP BY DOCUMENTS.ID, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENTS.CODE, DOCUMENTS.NUMBER
        )
        ORDER BY INPUT_DATE ASC, ID ASC
        INTO :ID, :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY
    DO
    BEGIN
        SUM_OFFICIAL_SUM_OF_MONEY = SUM_OFFICIAL_SUM_OF_MONEY + OFFICIAL_SUM_OF_MONEY;
        
        SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = 0;

        HAS_VALUE = 0;

        FOR
            SELECT DOCUMENTS.CODE || '-' || DOCUMENTS.NUMBER CODE, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, SUM(DECREASE_DOCUMENTS.OFFICIAL_SUM_OF_MONEY)
            FROM DECREASE_DOCUMENTS
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ID = DECREASE_DOCUMENTS.CREDIT_DEBIT AND
            CREDIT_DEBIT.ACCOUNT = :P_ACCOUNT AND (:P_OBJECT0 IS NULL OR CREDIT_DEBIT.OBJECT0 = :P_OBJECT0)
            JOIN ENTRIES ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND  ENTRIES.ID = CREDIT_DEBIT.ENTRY
            JOIN DOCUMENTS ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND  DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE <= :P_DEN_NGAY
            JOIN DOCUMENT_BASES ON DOCUMENT_BASES.COMPANY = :P_COMPANY AND DOCUMENT_BASES.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENT_BASES.ID
            WHERE DECREASE_DOCUMENTS.COMPANY = :P_COMPANY AND DECREASE_DOCUMENTS.INCREASE_DOCUMENT = :ID
            GROUP BY DOCUMENTS.CODE, DOCUMENTS.NUMBER, DOCUMENTS.INPUT_DATE, DOCUMENTS.VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT
            ORDER BY INPUT_DATE ASC
            INTO :DECREASE_CODE, :DECREASE_INPUT_DATE, :DECREASE_VOUCHER_DATE, :DECREASE_CONTENT, :DECREASE_OFFICIAL_SUM_OF_MONEY
        DO
        BEGIN
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY + DECREASE_OFFICIAL_SUM_OF_MONEY;
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT + DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY_R = SUM_OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT;

            HAS_VALUE = 1;

            SUSPEND;
        END

        IF(HAS_VALUE = 0)THEN
        BEGIN
            DECREASE_CODE = NULL;
            DECREASE_INPUT_DATE = NULL;
            DECREASE_VOUCHER_DATE = NULL;
            DECREASE_OFFICIAL_SUM_OF_MONEY = 0;

            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :DECREASE_CONTENT;

            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY + DECREASE_OFFICIAL_SUM_OF_MONEY;
            SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT = SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT + DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY;

            
            REMAIN_OFFICIAL_SUM_OF_MONEY_R = SUM_OFFICIAL_SUM_OF_MONEY - SUM_DECREASE_OFFICIAL_SUM_OF_MONEY_REPORT;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NM_SL_DG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
BALANCE_DEBIT DM_DOUBLE,
BALANCE_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE)
AS 
declare variable object0 dm_id;
declare variable parent_account_code dm_code;
declare variable print_report_person_name dm_integer;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(p_customer IS NULL)THEN
    BEGIN
        FOR
            SELECT distinct(OBJECT0) as OBJECT0, atoms.code, atom_strings.name
            FROM
            (
                SELECT OBJECT0
                FROM int_dt0_1_tk_dn_c(:p_company, :parent_account_code, :p_tu_ngay)

                UNION ALL

                SELECT OBJECT0
                FROM int_dt0_ps_1_tk_c(:p_company, :parent_account_code, :p_tu_ngay, :p_den_ngay)
            ) a
            join atoms on atoms.company = :p_company and atoms.id = a.object0
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            INTO :object0, :object_code, :OBJECT_NAME
        DO
        BEGIN
            FOR
                select code, input_date, voucher_date, content, account_code,
                    beginning_debit, beginning_credit,amount,price,rising_debit,rising_credit,balance_debit,balance_credit,ending_debit,ending_credit
                FROM int_so_ct_thanh_toan_NM_sl_dg(:p_language, :p_company, :parent_account_code, :object0, :p_tu_ngay, :p_den_ngay, :print_report_person_name)
                INTO :code, :input_date, :voucher_date, :content, :account_code,
                    :beginning_debit, :beginning_credit,:amount,:price,:rising_debit,:rising_credit,
                    :balance_debit,:balance_credit,:ending_debit,:ending_credit
            DO
            BEGIN
                SUSPEND;
            END
        END
    END
    ELSE
    BEGIN
        select code, name
        from atoms
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        where atoms.company = :p_company and atoms.id = :p_customer
        into :object_code, :object_name;

        FOR
            select code, input_date, voucher_date, content, account_code,
                beginning_debit, beginning_credit,amount,price,rising_debit,rising_credit,balance_debit,balance_credit,ending_debit,ending_credit
            FROM int_so_ct_thanh_toan_NM_sl_dg(:p_language, :p_company, :parent_account_code, :p_customer, :p_tu_ngay, :p_den_ngay, :print_report_person_name)
            INTO :code, :input_date, :voucher_date, :content, :account_code,
                :beginning_debit, :beginning_credit,:amount,:price,:rising_debit,:rising_credit,
                :balance_debit,:balance_credit,:ending_debit,:ending_credit
        DO
        BEGIN
            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_CT_THANH_TOAN_NM_TT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_CUSTOMER DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
declare variable entry_currency dm_id;
declare variable parent_account_code dm_code;
declare variable debit_account_code dm_code;
declare variable debit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable foreign_sum_of_money dm_double;
declare variable official_sum_of_money dm_double;
declare variable has_value dm_bool;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_CUSTOMER, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE,
        DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0,
        ENTRIES.currency
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_CUSTOMER) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_CUSTOMER))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE,
        :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0,
        :entry_currency
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BEGIN
               RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
            END
            ELSE
            BEGIN
                RISING_FOREIGN_DEBIT = 0;
            END

            RISING_FOREIGN_CREDIT = 0;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_CUSTOMER)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = 0;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BEGIN
               RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            END
            ELSE
            BEGIN
                RISING_FOREIGN_CREDIT = 0;
            END

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_KT_CT_QUY_TIEN_MAT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (DEBIT_CODE DM_DOCUMENT_CODE,
CREDIT_CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
DEBIT_SUM_OF_MONEY DM_DOUBLE,
CREDIT_SUM_OF_MONEY DM_DOUBLE,
BALANCE_SUM_OF_MONEY DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE CODE DM_DOCUMENT_CODE;
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    BEGINNING_SUM_OF_MONEY = BEGINNING_DEBIT - BEGINNING_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        ORDER BY INPUT_DATE, IIF(DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) desc, CODE_NUMBER, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            DEBIT_CODE = CODE;
            CREDIT_CODE = NULL;
            DEBIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;
            CREDIT_SUM_OF_MONEY = 0;

            BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            DEBIT_CODE = NULL;
            CREDIT_CODE = CODE;
            DEBIT_SUM_OF_MONEY = 0;
            CREDIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;

            BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;
        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_NHAT_KY_BAN_HANG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
DEBIT_ACCOUNT_CODE DM_CODE,
CREDIT_ACCOUNT_CODE DM_CODE,
BEGIN_PAGE_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
END_PAGE_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    BEGIN_PAGE_SUM_OF_MONEY = 0;
    HAS_VALUE = 0;
    END_PAGE_SUM_OF_MONEY = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE
        WHERE ENTRIES.COMPANY = :P_COMPANY
        ORDER BY INPUT_DATE, CODENUMBER, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        END_PAGE_SUM_OF_MONEY = END_PAGE_SUM_OF_MONEY + :OFFICIAL_SUM_OF_MONEY;

        HAS_VALUE = 1;
        SUSPEND;

        BEGIN_PAGE_SUM_OF_MONEY = BEGIN_PAGE_SUM_OF_MONEY + :OFFICIAL_SUM_OF_MONEY;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

