        BEGIN_PAGE_SUM_OF_MONEY = BEGIN_PAGE_SUM_OF_MONEY + :OFFICIAL_SUM_OF_MONEY;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_NHAT_KY_CHUNG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGIN_PAGE_DEBIT_SUM_OF_MONEY DM_DOUBLE,
BEGIN_PAGE_CREDIT_SUM_OF_MONEY DM_DOUBLE,
END_PAGE_DEBIT_SUM_OF_MONEY DM_DOUBLE,
END_PAGE_CREDIT_SUM_OF_MONEY DM_DOUBLE,
DEBIT_SUM_OF_MONEY DM_DOUBLE,
CREDIT_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    BEGIN_PAGE_DEBIT_SUM_OF_MONEY = 0;
    BEGIN_PAGE_CREDIT_SUM_OF_MONEY = 0;

    END_PAGE_DEBIT_SUM_OF_MONEY = 0;
    END_PAGE_CREDIT_SUM_OF_MONEY = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT.ACCOUNT, CREDIT.ACCOUNT
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        WHERE ENTRIES.COMPANY = :P_COMPANY
        ORDER BY INPUT_DATE,
        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PT', 0,
            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PC', 5,
                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBCO', 10,
                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBNO', 15,
                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTTH', 75,
                            IIF(ATOM_DOCUMENT_TEAMS.CODE = 'BTK', 80,
                                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'TKHTS', 85,
                                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'CPTT', 90,
                                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTPB', 95,
                                            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTKC', 100, 50)
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        CODENUMBER, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT, :CREDIT_ACCOUNT
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_ACCOUNT
        INTO :ACCOUNT_CODE;

        DEBIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;
        CREDIT_SUM_OF_MONEY = 0;

        END_PAGE_DEBIT_SUM_OF_MONEY = END_PAGE_DEBIT_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY;

        SUSPEND;

        BEGIN_PAGE_DEBIT_SUM_OF_MONEY = BEGIN_PAGE_DEBIT_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY;

        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_ACCOUNT
        INTO :ACCOUNT_CODE;

        DEBIT_SUM_OF_MONEY = 0;
        CREDIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;

        END_PAGE_CREDIT_SUM_OF_MONEY = END_PAGE_CREDIT_SUM_OF_MONEY + CREDIT_SUM_OF_MONEY;

        SUSPEND;

        BEGIN_PAGE_CREDIT_SUM_OF_MONEY = BEGIN_PAGE_CREDIT_SUM_OF_MONEY + CREDIT_SUM_OF_MONEY;
    END
END ^

ALTER PROCEDURE RPT_SO_NHAT_KY_CHUNG_DT1 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
OBJECT0_CODE DM_CODE,
OBJECT0_NAME DM_NAME,
BEGIN_PAGE_DEBIT_SUM_OF_MONEY DM_DOUBLE,
BEGIN_PAGE_CREDIT_SUM_OF_MONEY DM_DOUBLE,
END_PAGE_DEBIT_SUM_OF_MONEY DM_DOUBLE,
END_PAGE_CREDIT_SUM_OF_MONEY DM_DOUBLE,
DEBIT_SUM_OF_MONEY DM_DOUBLE,
CREDIT_SUM_OF_MONEY DM_DOUBLE)
AS 
DECLARE VARIABLE DEBIT_ACCOUNT DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT DM_ID;
DECLARE VARIABLE DEBIT_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE CREDIT_OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE DEBIT_OBJECT0_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OBJECT0_NAME DM_NAME;
DECLARE VARIABLE CREDIT_OBJECT0_CODE DM_CODE;
DECLARE VARIABLE CREDIT_OBJECT0_NAME DM_NAME;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    BEGIN_PAGE_DEBIT_SUM_OF_MONEY = 0;
    BEGIN_PAGE_CREDIT_SUM_OF_MONEY = 0;

    END_PAGE_DEBIT_SUM_OF_MONEY = 0;
    END_PAGE_CREDIT_SUM_OF_MONEY = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODENUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY, CREDIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT.ACCOUNT, CREDIT.ACCOUNT,
        OBJECT_DEBIT_ATOM0.CODE, OBJECT_DEBIT_ATOM_STRING0.NAME,
        OBJECT_CREDIT_ATOM0.CODE, OBJECT_CREDIT_ATOM_STRING0.NAME
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
        JOIN ATOMS ATOM_DOCUMENT_TEAMS ON ATOM_DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND ATOM_DOCUMENT_TEAMS.ID = DOCUMENT_TEAMS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        LEFT JOIN ATOMS OBJECT_DEBIT_ATOM0 ON OBJECT_DEBIT_ATOM0.COMPANY = :P_COMPANY AND OBJECT_DEBIT_ATOM0.ID = DEBIT.OBJECT0
        LEFT JOIN ATOM_STRINGS OBJECT_DEBIT_ATOM_STRING0 ON OBJECT_DEBIT_ATOM_STRING0.COMPANY = :P_COMPANY AND OBJECT_DEBIT_ATOM_STRING0.LANGUAGE = :P_LANGUAGE AND OBJECT_DEBIT_ATOM_STRING0.ID = DEBIT.OBJECT0
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        LEFT JOIN ATOMS OBJECT_CREDIT_ATOM0 ON OBJECT_CREDIT_ATOM0.COMPANY = :P_COMPANY AND OBJECT_CREDIT_ATOM0.ID = CREDIT.OBJECT0
        LEFT JOIN ATOM_STRINGS OBJECT_CREDIT_ATOM_STRING0 ON OBJECT_CREDIT_ATOM_STRING0.COMPANY = :P_COMPANY AND OBJECT_CREDIT_ATOM_STRING0.LANGUAGE = :P_LANGUAGE AND OBJECT_CREDIT_ATOM_STRING0.ID = CREDIT.OBJECT0
        WHERE ENTRIES.COMPANY = :P_COMPANY
        ORDER BY INPUT_DATE,
        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PT', 0,
            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'PC', 5,
                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBCO', 10,
                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'GBNO', 15,
                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTTH', 75,
                            IIF(ATOM_DOCUMENT_TEAMS.CODE = 'BTK', 80,
                                IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'TKHTS', 85,
                                    IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'CPTT', 90,
                                        IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTPB', 95,
                                            IIF(ATOM_DOCUMENT_TEAMS.CODE STARTING WITH 'BTKC', 100, 50)
                                        )
                                    )
                                )
                            )
                        )
                    )
                )
            )
        ),
        CODENUMBER, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :DEBIT_OFFICIAL_SUM_OF_MONEY, :CREDIT_OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT, :CREDIT_ACCOUNT,
        :DEBIT_OBJECT0_CODE, :DEBIT_OBJECT0_NAME,
        :CREDIT_OBJECT0_CODE, :CREDIT_OBJECT0_NAME
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :DEBIT_ACCOUNT
        INTO :ACCOUNT_CODE;

        OBJECT0_CODE = DEBIT_OBJECT0_CODE;
        OBJECT0_NAME = DEBIT_OBJECT0_NAME;

        DEBIT_SUM_OF_MONEY = DEBIT_OFFICIAL_SUM_OF_MONEY;
        CREDIT_SUM_OF_MONEY = 0;

        IF(DEBIT_OFFICIAL_SUM_OF_MONEY <> CREDIT_OFFICIAL_SUM_OF_MONEY)THEN
            CREDIT_SUM_OF_MONEY = 0 - ABS(DEBIT_OFFICIAL_SUM_OF_MONEY-CREDIT_OFFICIAL_SUM_OF_MONEY);
        ELSE
            CREDIT_SUM_OF_MONEY = 0;

        END_PAGE_DEBIT_SUM_OF_MONEY = END_PAGE_DEBIT_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY;

        SUSPEND;

        BEGIN_PAGE_DEBIT_SUM_OF_MONEY = BEGIN_PAGE_DEBIT_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY;

        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :CREDIT_ACCOUNT
        INTO :ACCOUNT_CODE;

        OBJECT0_CODE = CREDIT_OBJECT0_CODE;
        OBJECT0_NAME = CREDIT_OBJECT0_NAME;

        DEBIT_SUM_OF_MONEY = 0;
        CREDIT_SUM_OF_MONEY = CREDIT_OFFICIAL_SUM_OF_MONEY;

        IF(DEBIT_OFFICIAL_SUM_OF_MONEY <> CREDIT_OFFICIAL_SUM_OF_MONEY)THEN
            DEBIT_SUM_OF_MONEY = 0 - ABS(DEBIT_OFFICIAL_SUM_OF_MONEY-CREDIT_OFFICIAL_SUM_OF_MONEY);
        ELSE
            DEBIT_SUM_OF_MONEY = 0;

        END_PAGE_CREDIT_SUM_OF_MONEY = END_PAGE_CREDIT_SUM_OF_MONEY + CREDIT_SUM_OF_MONEY;

        SUSPEND;

        BEGIN_PAGE_CREDIT_SUM_OF_MONEY = BEGIN_PAGE_CREDIT_SUM_OF_MONEY + CREDIT_SUM_OF_MONEY;
    END
END ^

