        JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOMS ON CREDIT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ATOMS.ID = CREDIT.ACCOUNT
        WHERE ENTRIES.COMPANY = :P_COMPANY
        ORDER BY INPUT_DATE,
