ALTER PROCEDURE RPT_SO_QUY_TIEN_MAT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (DEBIT_CODE DM_DOCUMENT_CODE,
CREDIT_CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
DEBIT_SUM_OF_MONEY DM_DOUBLE,
CREDIT_SUM_OF_MONEY DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
BALANCE_SUM_OF_MONEY DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
INPUT_MONTH DM_INTEGER,
INPUT_YEAR DM_INTEGER)
AS 
DECLARE VARIABLE CODE DM_DOCUMENT_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_BOOL;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_BOOL;
DECLARE VARIABLE BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    BEGINNING_SUM_OF_MONEY = BEGINNING_DEBIT - BEGINNING_CREDIT;

    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(DOCUMENT_BASE_STRINGS.CONTENT IS NULL OR DOCUMENT_BASE_STRINGS.CONTENT = '', ENTRY_BASE_STRINGS.CONTENT, DOCUMENT_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') CONTENT,
        SUM(DEBIT.OFFICIAL_SUM_OF_MONEY),
        IIF(DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) as de, IIF(CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) as ce
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        GROUP BY DOCUMENTS.ID, DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT, de, ce
        ORDER BY INPUT_DATE, de desc, CODE_NUMBER, DOCUMENTS.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        INPUT_MONTH = EXTRACT(MONTH FROM INPUT_DATE);
        INPUT_YEAR = EXTRACT(YEAR FROM INPUT_DATE);

        IF(DEBIT_ACCOUNT_CODE = 1)THEN
        BEGIN
            DEBIT_CODE = CODE;
            CREDIT_CODE = NULL;
            DEBIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;
            CREDIT_SUM_OF_MONEY = 0;

            SUM_RISING_DEBIT = SUM_RISING_DEBIT + DEBIT_SUM_OF_MONEY;
            SUM_RISING_CREDIT = SUM_RISING_CREDIT + CREDIT_SUM_OF_MONEY;

            BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_SUM_OF_MONEY = ENDING_SUM_OF_MONEY;
        END

        IF(CREDIT_ACCOUNT_CODE = 1)THEN
        BEGIN
            DEBIT_CODE = NULL;
            CREDIT_CODE = CODE;
            DEBIT_SUM_OF_MONEY = 0;
            CREDIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;

            SUM_RISING_DEBIT = SUM_RISING_DEBIT + DEBIT_SUM_OF_MONEY;
            SUM_RISING_CREDIT = SUM_RISING_CREDIT + CREDIT_SUM_OF_MONEY;

            BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_SUM_OF_MONEY = ENDING_SUM_OF_MONEY;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_TAI_SAN_CO_DINH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ORDINAL DM_INTEGER,
ASSET_CODE DM_CODE,
ASSET_NAME DM_NAME,
ENDING_ORIGINAL_VALUE DM_DOUBLE,
INCREASE_DOCUMENT_CODE DM_DOCUMENT_CODE,
INCREASE_VOUCHER_DATE DM_DATE,
INCREASE_NAME DM_CONTENT,
INCREASE_PLACE_OF_MADE DM_ADDRESS,
INCREASE_DATE_OF_USING DM_DATE,
INCREASE_ASSET_CODE DM_CODE,
INCREASE_ORIGINAL_VALUE DM_DOUBLE,
DEPRECIATION_PERCENT DM_DOUBLE,
DEPRECIATION_RATE DM_DOUBLE,
DEPRECIATION_VALUE DM_DOUBLE,
DECREASE_DOCUMENT_CODE DM_DOCUMENT_CODE,
DECREASE_VOUCHER_DATE DM_DATE,
DECREASE_CONTENT DM_CONTENT)
AS 
DECLARE VARIABLE ASSET_ID DM_ID;
DECLARE VARIABLE ASSET_ACCOUNT DM_ID;
DECLARE VARIABLE DEPRECIATION_ACCOUNT DM_ID;
DECLARE VARIABLE ORIGINAL_VALUE DM_DOUBLE;
DECLARE VARIABLE BEGINNING_ORIGINAL_VALUE DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN

ORDINAL = 1;

FOR
    SELECT ASSETS.ID, ATOMS.CODE, ATOM_STRINGS.NAME, ASSET_STRINGS.PLACE_OF_MADE, ASSETS.DATE_OF_USING, ASSETS.ASSET_ACCOUNT, ASSETS.DEPRECIATION_ACCOUNT
    FROM ASSETS
    JOIN ASSET_STRINGS ON ASSET_STRINGS.COMPANY = :P_COMPANY AND ASSET_STRINGS.ID = ASSETS.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSETS.ID
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.ID = ATOMS.ID
    WHERE ASSETS.COMPANY = :P_COMPANY
    ORDER BY ATOM_STRINGS.NAME
    INTO :ASSET_ID, :ASSET_CODE, :ASSET_NAME, :INCREASE_PLACE_OF_MADE, :INCREASE_DATE_OF_USING, :ASSET_ACCOUNT, :DEPRECIATION_ACCOUNT
DO
BEGIN
    HAS_VALUE = 0;

    SELECT DEBIT - CREDIT
    FROM INT_SD_1_TK_1_DT0_DN(:P_COMPANY, :ASSET_ACCOUNT, :ASSET_ID, :P_TU_NGAY)
    INTO :BEGINNING_ORIGINAL_VALUE;

    IF(BEGINNING_ORIGINAL_VALUE <> 0)THEN
        BEGIN
            SELECT CONTENT
            FROM TEXTS
            WHERE TEXTS.ID = 2 AND TEXTS.LANGUAGE = :P_LANGUAGE
            INTO :INCREASE_NAME;

            INCREASE_DOCUMENT_CODE = NULL;
            INCREASE_VOUCHER_DATE = NULL;
            INCREASE_ASSET_CODE = NULL;
            INCREASE_ORIGINAL_VALUE = BEGINNING_ORIGINAL_VALUE;
            DEPRECIATION_PERCENT = NULL;
            DEPRECIATION_RATE = NULL;
            DEPRECIATION_VALUE = NULL;
            DECREASE_DOCUMENT_CODE = NULL;
            DECREASE_VOUCHER_DATE = NULL;
            DECREASE_CONTENT = NULL;

            SUSPEND;

            HAS_VALUE = 1;
        END

    FOR
        SELECT
        INCREASE_DOCUMENT_CODE, INCREASE_VOUCHER_DATE, INCREASE_NAME, INCREASE_ORIGINAL_VALUE,
        DEPRECIATION_PERCENT, DEPRECIATION_RATE, DEPRECIATION_VALUE, DECREASE_DOCUMENT_CODE, DECREASE_VOUCHER_DATE, DECREASE_CONTENT
        FROM
        (
            
            SELECT ENTRIES.ID, VOUCHER_DATE,
            DOCUMENTS.CODE || '-' || NUMBER AS INCREASE_DOCUMENT_CODE, VOUCHER_DATE INCREASE_VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT INCREASE_NAME,
            IIF((DEBIT_ATOM.CODE STARTING WITH '211') OR (DEBIT_ATOM.CODE STARTING WITH '213'), DEBIT.OFFICIAL_SUM_OF_MONEY, 0 - DEBIT.OFFICIAL_SUM_OF_MONEY) INCREASE_ORIGINAL_VALUE,
            NULL DEPRECIATION_PERCENT, NULL DEPRECIATION_RATE, NULL DEPRECIATION_VALUE, NULL DECREASE_DOCUMENT_CODE, NULL DECREASE_VOUCHER_DATE, NULL DECREASE_CONTENT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.VOUCHER_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
            JOIN ATOMS DOCUMENT_TEAMS_ATOMS ON DOCUMENT_TEAMS_ATOMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS_ATOMS.ID = DOCUMENT_TEAMS.ID AND (DOCUMENT_TEAMS_ATOMS.CODE = 'TTSCD' OR DOCUMENT_TEAMS_ATOMS.CODE = 'DCTSCD')
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN ATOMS DEBIT_OBJECT0_ATOMS ON DEBIT_OBJECT0_ATOMS.COMPANY = :P_COMPANY AND DEBIT_OBJECT0_ATOMS.ID = DEBIT.OBJECT0
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            LEFT JOIN ATOMS CREDIT_OBJECT0_ATOMS ON CREDIT_OBJECT0_ATOMS.COMPANY = :P_COMPANY AND CREDIT_OBJECT0_ATOMS.ID = CREDIT.OBJECT0
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            (
                (
                    (
                        (DEBIT_ATOM.CODE STARTING WITH '211')
                        OR
                        (DEBIT_ATOM.CODE STARTING WITH '213')
                    )

                    AND DEBIT_OBJECT0_ATOMS.OBJECT_TYPE = 20 AND DEBIT.OBJECT0 = :ASSET_ID
                )
                OR
                (
                    (
                        (CREDIT_ATOM.CODE STARTING WITH '211')
                        OR
                        (CREDIT_ATOM.CODE STARTING WITH '213')
                    )

                    AND CREDIT_OBJECT0_ATOMS.OBJECT_TYPE = 20 AND CREDIT.OBJECT0 = :ASSET_ID
                )
            )

            UNION ALL

            
            SELECT DOCUMENTS.ID, VOUCHER_DATE,
            NULL INCREASE_DOCUMENT_CODE, NULL INCREASE_VOUCHER_DATE, NULL INCREASE_NAME, NULL INCREASE_ORIGINAL_VALUE,
            NULL DEPRECIATION_PERCENT, NULL DEPRECIATION_RATE, NULL DEPRECIATION_VALUE, DOCUMENTS.CODE || '-' || NUMBER DECREASE_DOCUMENT_CODE, VOUCHER_DATE DECREASE_VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT DECREASE_CONTENT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.VOUCHER_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_TEAMS ON DOCUMENT_TEAMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS.ID = DOCUMENTS.TEAM
            JOIN ATOMS DOCUMENT_TEAMS_ATOMS ON DOCUMENT_TEAMS_ATOMS.COMPANY = :P_COMPANY AND DOCUMENT_TEAMS_ATOMS.ID = DOCUMENT_TEAMS.ID AND DOCUMENT_TEAMS_ATOMS.CODE = 'GTSCD'
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN ATOMS DEBIT_OBJECT0_ATOMS ON DEBIT_OBJECT0_ATOMS.COMPANY = :P_COMPANY AND DEBIT_OBJECT0_ATOMS.ID = DEBIT.OBJECT0
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            LEFT JOIN ATOMS CREDIT_OBJECT0_ATOMS ON CREDIT_OBJECT0_ATOMS.COMPANY = :P_COMPANY AND CREDIT_OBJECT0_ATOMS.ID = CREDIT.OBJECT0
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
                (
                    (
                        (CREDIT_ATOM.CODE STARTING WITH '211')
                        OR
                        (CREDIT_ATOM.CODE STARTING WITH '213')
                    )

                    AND CREDIT_OBJECT0_ATOMS.OBJECT_TYPE = 20 AND CREDIT.OBJECT0 = :ASSET_ID
                )
            GROUP BY VOUCHER_DATE, CREDIT.OBJECT0,
            DECREASE_DOCUMENT_CODE, VOUCHER_DATE, DOCUMENT_BASE_STRINGS.CONTENT, DOCUMENTS.ID

            UNION ALL

            
            SELECT ENTRIES.ID, VOUCHER_DATE,
            DOCUMENTS.CODE || '-' || NUMBER AS INCREASE_DOCUMENT_CODE, VOUCHER_DATE INCREASE_VOUCHER_DATE, NULL INCREASE_NAME, NULL INCREASE_ORIGINAL_VALUE,
            NULL DEPRECIATION_PERCENT, CREDIT.OFFICIAL_SUM_OF_MONEY DEPRECIATION_RATE, NULL DEPRECIATION_VALUE, NULL DECREASE_DOCUMENT_CODE, NULL DECREASE_VOUCHER_DATE, NULL DECREASE_CONTENT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND DOCUMENTS.VOUCHER_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            LEFT JOIN ATOMS DEBIT_OBJECT0_ATOMS ON DEBIT_OBJECT0_ATOMS.COMPANY = :P_COMPANY AND DEBIT_OBJECT0_ATOMS.ID = DEBIT.OBJECT0
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            LEFT JOIN ATOMS CREDIT_OBJECT0_ATOMS ON CREDIT_OBJECT0_ATOMS.COMPANY = :P_COMPANY AND CREDIT_OBJECT0_ATOMS.ID = CREDIT.OBJECT0
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
                (
                    CREDIT_ATOM.CODE STARTING WITH '214'
                    AND CREDIT_OBJECT0_ATOMS.OBJECT_TYPE = 20 AND CREDIT.OBJECT0 = :ASSET_ID
                )
        ) A
        ORDER BY VOUCHER_DATE, A.ID
        INTO
        :INCREASE_DOCUMENT_CODE, :INCREASE_VOUCHER_DATE, :INCREASE_NAME, :INCREASE_ORIGINAL_VALUE,
        :DEPRECIATION_PERCENT, :DEPRECIATION_RATE, :DEPRECIATION_VALUE, :DECREASE_DOCUMENT_CODE, :DECREASE_VOUCHER_DATE, :DECREASE_CONTENT
    DO
    BEGIN
        
        IF(DEPRECIATION_RATE IS NOT NULL)THEN
        BEGIN
            SELECT DEBIT-CREDIT
            FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :ASSET_ACCOUNT, :ASSET_ID, :INCREASE_VOUCHER_DATE)
            INTO :ORIGINAL_VALUE;

            IF(ORIGINAL_VALUE IS NOT NULL AND ORIGINAL_VALUE > 0)THEN
                DEPRECIATION_PERCENT = ROUND(DEPRECIATION_RATE/ORIGINAL_VALUE, 2);

            SELECT CREDIT-DEBIT
            FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :DEPRECIATION_ACCOUNT, :ASSET_ID, :INCREASE_VOUCHER_DATE)
            INTO :DEPRECIATION_VALUE;
        END

        IF(DECREASE_DOCUMENT_CODE IS NULL)THEN
        BEGIN
            INCREASE_ASSET_CODE = ASSET_CODE;
        END
        ELSE
        BEGIN
            INCREASE_ASSET_CODE = NULL;
            INCREASE_NAME = NULL;
            INCREASE_PLACE_OF_MADE = NULL;
            INCREASE_DATE_OF_USING = NULL;
        END

        SUSPEND;

        HAS_VALUE = 1;
    END

    SELECT DEBIT - CREDIT
    FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :ASSET_ACCOUNT, :ASSET_ID, :P_DEN_NGAY)
    INTO :ENDING_ORIGINAL_VALUE;

    IF(ENDING_ORIGINAL_VALUE <> 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 3 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :INCREASE_NAME;

        INCREASE_DOCUMENT_CODE = NULL;
        INCREASE_VOUCHER_DATE = NULL;
        INCREASE_ASSET_CODE = NULL;
        INCREASE_ORIGINAL_VALUE = ENDING_ORIGINAL_VALUE;
        DEPRECIATION_PERCENT = NULL;
        DEPRECIATION_RATE = NULL;
        DEPRECIATION_VALUE = NULL;
        DECREASE_DOCUMENT_CODE = NULL;
        DECREASE_VOUCHER_DATE = NULL;
        DECREASE_CONTENT = NULL;

        SUSPEND;

        ENDING_ORIGINAL_VALUE = 0;

        HAS_VALUE = 1;
    END

    IF(HAS_VALUE = 1)THEN ORDINAL = ORDINAL + 1;
END
END ^

ALTER PROCEDURE RPT_SO_THEO_DOI_GTGT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
BEGINNING_1 DM_DOUBLE,
BEGINNING_2 DM_DOUBLE,
RISING_1 DM_DOUBLE,
RISING_2 DM_DOUBLE,
ENDING_1 DM_DOUBLE,
ENDING_2 DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_11 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_133 DM_CODE;
DECLARE VARIABLE DEBIT DM_DOUBLE;
DECLARE VARIABLE CREDIT DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    
    
    ACCOUNT_CODE = '3331';
    ACCOUNT_CODE_11 = '11';
    ACCOUNT_CODE_133 = '133';

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)
    INTO :DEBIT, :CREDIT;

    IF(DEBIT > CREDIT)THEN
    BEGIN
        BEGINNING_1 = DEBIT - CREDIT;
        BEGINNING_2 = 0;
    END
    ELSE
    BEGIN
        BEGINNING_1 = 0;
        BEGINNING_2 = CREDIT - DEBIT;
    END

    FOR
        SELECT CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, RISING_1, RISING_2
        FROM
        (
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT, DEBIT.OFFICIAL_SUM_OF_MONEY RISING_1, 0 RISING_2
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_11

            UNION ALL

            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT, 0 RISING_1, 0-DEBIT.OFFICIAL_SUM_OF_MONEY RISING_2
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_133

            UNION ALL

            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT, 0 RISING_1, CREDIT.OFFICIAL_SUM_OF_MONEY RISING_2
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE
        )
        ORDER BY INPUT_DATE, ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :RISING_1, :RISING_2
    DO
    BEGIN
        ENDING_1 = BEGINNING_1 - BEGINNING_2 + RISING_1 - RISING_2;
        IF(ENDING_1 > 0)THEN
            ENDING_2 = 0;
        ELSE
        BEGIN
            ENDING_2 = ABS(ENDING_1);
            ENDING_1 = 0;
        END

        HAS_VALUE = 1;

        SUSPEND;

        BEGINNING_1 = ENDING_1;
        BEGINNING_2 = ENDING_2;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_1 = BEGINNING_1;
        ENDING_2 = BEGINNING_2;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

