        HAS_VALUE = 1;

        SUSPEND;

        BEGINNING_1 = ENDING_1;
        BEGINNING_2 = ENDING_2;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_1 = BEGINNING_1;
        ENDING_2 = BEGINNING_2;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_THEO_DOI_GTGT_QUAN_TRI (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
DAU_VAO_DAU_KY DM_DOUBLE,
PHAI_NOP_DAU_KY DM_DOUBLE,
DAU_RA DM_DOUBLE,
DAU_VAO DM_DOUBLE,
NOP_TRONG_KY DM_DOUBLE,
KHAU_TRU DM_DOUBLE,
DAU_VAO_CUOI_KY DM_DOUBLE,
PHAI_NOP_CUOI_KY DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE_3331 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_11 DM_CODE;
DECLARE VARIABLE ACCOUNT_CODE_133 DM_CODE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    ACCOUNT_CODE_3331 = '3331';
    ACCOUNT_CODE_11 = '11';
    ACCOUNT_CODE_133 = '133';

    SELECT CREDIT - DEBIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE_3331, :P_TU_NGAY)
    INTO :PHAI_NOP_DAU_KY;

    SELECT CREDIT - DEBIT
    FROM INT_SD_1_TK_CN_C(:P_COMPANY, :ACCOUNT_CODE_3331, :P_DEN_NGAY)
    INTO :PHAI_NOP_CUOI_KY;

    SELECT DEBIT - CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :ACCOUNT_CODE_133, :P_TU_NGAY)
    INTO :DAU_VAO_DAU_KY;

    SELECT DEBIT - CREDIT
    FROM INT_SD_1_TK_CN_C(:P_COMPANY, :ACCOUNT_CODE_133, :P_DEN_NGAY)
    INTO :DAU_VAO_CUOI_KY;

    FOR
        SELECT CODE, INPUT_DATE, VOUCHER_DATE, CONTENT, DAU_RA, DAU_VAO, NOP_TRONG_KY, KHAU_TRU
        FROM
        (
            
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            CREDIT.OFFICIAL_SUM_OF_MONEY DAU_RA, 0 DAU_VAO, 0 NOP_TRONG_KY, 0 KHAU_TRU
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_3331

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            0-DEBIT.OFFICIAL_SUM_OF_MONEY DAU_RA, 0 DAU_VAO, 0 NOP_TRONG_KY, 0 KHAU_TRU
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_3331 AND CREDIT_ATOM.CODE NOT STARTING WITH :ACCOUNT_CODE_133 AND CREDIT_ATOM.CODE NOT STARTING WITH :ACCOUNT_CODE_11

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            0 DAU_RA, DEBIT.OFFICIAL_SUM_OF_MONEY DAU_VAO, 0 NOP_TRONG_KY, 0 KHAU_TRU
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_133

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            0 DAU_RA, 0-DEBIT.OFFICIAL_SUM_OF_MONEY DAU_VAO, 0 NOP_TRONG_KY, 0 KHAU_TRU
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_133 AND DEBIT_ATOM.CODE NOT STARTING WITH :ACCOUNT_CODE_3331

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            0 DAU_RA, 0 DAU_VAO, DEBIT.OFFICIAL_SUM_OF_MONEY NOP_TRONG_KY, 0 KHAU_TRU
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_3331 AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_11

            UNION ALL

            
            SELECT ENTRIES.ID, DOCUMENTS.CODE || '-' || NUMBER CODE, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) CONTENT,
            0 DAU_RA, 0 DAU_VAO, 0 NOP_TRONG_KY, DEBIT.OFFICIAL_SUM_OF_MONEY KHAU_TRU
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND DEBIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_3331 AND CREDIT_ATOM.CODE STARTING WITH :ACCOUNT_CODE_133
        )
        ORDER BY INPUT_DATE, ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT,
        :DAU_RA, :DAU_VAO, :NOP_TRONG_KY, :KHAU_TRU
    DO
    BEGIN
        HAS_VALUE = 1;

        IF(DAU_RA = 0)THEN DAU_RA = NULL;
        IF(DAU_VAO = 0)THEN DAU_VAO = NULL;
        IF(NOP_TRONG_KY = 0)THEN NOP_TRONG_KY = NULL;
        IF(KHAU_TRU = 0)THEN KHAU_TRU = NULL;

        SUSPEND;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_THEO_DOI_THANH_TOAN_NT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE, DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND (CURRENCY = :P_CURRENCY OR :P_CURRENCY IS NULL) AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        ORDER BY INPUT_DATE
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = CREDIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
            RISING_FOREIGN_CREDIT = 0;
            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = DEBIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = 0;
            RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            HAS_VALUE = 1;

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_THEO_DOI_THANH_TOAN_NT_1 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
declare variable parent_account_code dm_code;
declare variable debit_account_code dm_code;
declare variable debit_object0 dm_id;
declare variable credit_account_code dm_code;
declare variable credit_object0 dm_id;
declare variable foreign_sum_of_money dm_double;
declare variable official_sum_of_money dm_double;
declare variable has_value dm_bool;
declare variable entry_currency dm_id;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_1_DT0_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE,
        DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0,
        ENTRIES.CURRENCY
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_OBJECT0) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_OBJECT0))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE,
        :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0,
        :ENTRY_CURRENCY
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_OBJECT0)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BEGIN
                RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
                RISING_FOREIGN_CREDIT = 0;
            END
            ELSE
            BEGIN
                RISING_FOREIGN_DEBIT = 0;
                RISING_FOREIGN_CREDIT = 0;
            END

            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
                BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            
                

            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_OBJECT0)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
            BEGIN
                RISING_FOREIGN_DEBIT = 0;
                RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            END
            ELSE
            BEGIN
                RISING_FOREIGN_DEBIT = 0;
                RISING_FOREIGN_CREDIT = 0;
            END

            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;

            IF(ENTRY_CURRENCY = P_CURRENCY)THEN
                BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            
                

            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_THEO_DOI_THANH_TOAN_NT_2 (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_CURRENCY DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
EXCHANGE_RATE DM_DOUBLE,
BEGINNING_FOREIGN_DEBIT DM_DOUBLE,
BEGINNING_FOREIGN_CREDIT DM_DOUBLE,
RISING_FOREIGN_DEBIT DM_DOUBLE,
RISING_FOREIGN_CREDIT DM_DOUBLE,
BALANCE_FOREIGN_DEBIT DM_DOUBLE,
BALANCE_FOREIGN_CREDIT DM_DOUBLE,
ENDING_FOREIGN_DEBIT DM_DOUBLE,
ENDING_FOREIGN_CREDIT DM_DOUBLE,
BEGINNING_OFFICIAL_DEBIT DM_DOUBLE,
BEGINNING_OFFICIAL_CREDIT DM_DOUBLE,
RISING_OFFICIAL_DEBIT DM_DOUBLE,
RISING_OFFICIAL_CREDIT DM_DOUBLE,
BALANCE_OFFICIAL_DEBIT DM_DOUBLE,
BALANCE_OFFICIAL_CREDIT DM_DOUBLE,
ENDING_OFFICIAL_DEBIT DM_DOUBLE,
ENDING_OFFICIAL_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_OBJECT0 DM_ID;
DECLARE VARIABLE DEBIT_OBJECT1 DM_ID;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_OBJECT0 DM_ID;
DECLARE VARIABLE CREDIT_OBJECT1 DM_ID;
DECLARE VARIABLE FOREIGN_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(EXISTS (
        SELECT MAIN_CURRENCY
        FROM ACCOUNTING_SETTINGS
        WHERE COMPANY = :P_COMPANY AND MAIN_CURRENCY = :P_CURRENCY
    ))THEN
        P_CURRENCY = NULL;

    SELECT FOREIGN_DEBIT, FOREIGN_CREDIT, OFFICIAL_DEBIT, OFFICIAL_CREDIT
    FROM INT_SD_1_TK_1_DT0_1_DT1_DN_C_TT(:P_COMPANY, :P_CURRENCY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_TU_NGAY)
    INTO :BEGINNING_FOREIGN_DEBIT, :BEGINNING_FOREIGN_CREDIT, :BEGINNING_OFFICIAL_DEBIT, :BEGINNING_OFFICIAL_CREDIT;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE, IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT), ENTRIES.EXCHANGE_RATE,
        DEBIT.FOREIGN_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, DEBIT.OBJECT0, DEBIT.OBJECT1,
        CREDIT_ATOM.CODE, CREDIT.OBJECT0, CREDIT.OBJECT1
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        ((DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT.OBJECT0 = :P_OBJECT0 AND DEBIT.OBJECT1 = :P_OBJECT1) OR (CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT.OBJECT0 = :P_OBJECT0 AND CREDIT.OBJECT1 = :P_OBJECT1))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :EXCHANGE_RATE,
        :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :DEBIT_OBJECT0, :DEBIT_OBJECT1,
        :CREDIT_ACCOUNT_CODE, :CREDIT_OBJECT0, :CREDIT_OBJECT1
    DO
    BEGIN
        IF(DEBIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND DEBIT_OBJECT0 = :P_OBJECT0 AND DEBIT_OBJECT1 = :P_OBJECT1)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = FOREIGN_SUM_OF_MONEY;
            RISING_FOREIGN_CREDIT = 0;
            RISING_OFFICIAL_DEBIT = OFFICIAL_SUM_OF_MONEY;
            RISING_OFFICIAL_CREDIT = 0;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH :PARENT_ACCOUNT_CODE AND CREDIT_OBJECT0 = :P_OBJECT0 AND CREDIT_OBJECT1 = :P_OBJECT1)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            RISING_FOREIGN_DEBIT = 0;
            RISING_FOREIGN_CREDIT = FOREIGN_SUM_OF_MONEY;
            RISING_OFFICIAL_DEBIT = 0;
            RISING_OFFICIAL_CREDIT = OFFICIAL_SUM_OF_MONEY;

            BALANCE_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT + RISING_FOREIGN_DEBIT - BEGINNING_FOREIGN_CREDIT - RISING_FOREIGN_CREDIT;
            BALANCE_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT + RISING_OFFICIAL_DEBIT - BEGINNING_OFFICIAL_CREDIT - RISING_OFFICIAL_CREDIT;

            IF(BALANCE_FOREIGN_DEBIT > 0)THEN
                BALANCE_FOREIGN_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_FOREIGN_CREDIT = ABS(BALANCE_FOREIGN_DEBIT);
                BALANCE_FOREIGN_DEBIT = 0;
            END

            IF(BALANCE_OFFICIAL_DEBIT > 0)THEN
                BALANCE_OFFICIAL_CREDIT = 0;
            ELSE
            BEGIN
                BALANCE_OFFICIAL_CREDIT = ABS(BALANCE_OFFICIAL_DEBIT);
                BALANCE_OFFICIAL_DEBIT = 0;
            END

            ENDING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            ENDING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            ENDING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            ENDING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;

            HAS_VALUE = 1;

            SUSPEND;

            BEGINNING_FOREIGN_DEBIT = BALANCE_FOREIGN_DEBIT;
            BEGINNING_FOREIGN_CREDIT = BALANCE_FOREIGN_CREDIT;
            BEGINNING_OFFICIAL_DEBIT = BALANCE_OFFICIAL_DEBIT;
            BEGINNING_OFFICIAL_CREDIT = BALANCE_OFFICIAL_CREDIT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_FOREIGN_DEBIT = BEGINNING_FOREIGN_DEBIT;
        ENDING_FOREIGN_CREDIT = BEGINNING_FOREIGN_CREDIT;
        ENDING_OFFICIAL_DEBIT = BEGINNING_OFFICIAL_DEBIT;
        ENDING_OFFICIAL_CREDIT = BEGINNING_OFFICIAL_CREDIT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_TIEN_GUI_NGAN_HANG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
DEBIT_SUM_OF_MONEY DM_DOUBLE,
CREDIT_SUM_OF_MONEY DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE,
BALANCE_SUM_OF_MONEY DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
INPUT_MONTH DM_INTEGER,
INPUT_YEAR DM_INTEGER)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE OFFICIAL_SUM_OF_MONEY DM_DOUBLE;
DECLARE VARIABLE BEGINNING_DEBIT DM_DOUBLE;
DECLARE VARIABLE BEGINNING_CREDIT DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    BEGINNING_SUM_OF_MONEY = BEGINNING_DEBIT - BEGINNING_CREDIT;

    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.OFFICIAL_SUM_OF_MONEY,
        DEBIT_ATOM.CODE, CREDIT_ATOM.CODE
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY AND
        (DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE OR CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE)
        ORDER BY INPUT_DATE, IIF(DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE, 1, 0) DESC, CODE_NUMBER, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT, :OFFICIAL_SUM_OF_MONEY,
        :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE
    DO
    BEGIN
        INPUT_MONTH = EXTRACT(MONTH FROM INPUT_DATE);
        INPUT_YEAR = EXTRACT(YEAR FROM INPUT_DATE);

        IF(DEBIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = :CREDIT_ACCOUNT_CODE;
            DEBIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;
            CREDIT_SUM_OF_MONEY = 0;

            SUM_RISING_DEBIT = SUM_RISING_DEBIT + DEBIT_SUM_OF_MONEY;
            SUM_RISING_CREDIT = SUM_RISING_CREDIT + CREDIT_SUM_OF_MONEY;

            BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_SUM_OF_MONEY = ENDING_SUM_OF_MONEY;
        END

        IF(CREDIT_ACCOUNT_CODE STARTING WITH PARENT_ACCOUNT_CODE)THEN
        BEGIN
            ACCOUNT_CODE = :DEBIT_ACCOUNT_CODE;
            DEBIT_SUM_OF_MONEY = 0;
            CREDIT_SUM_OF_MONEY = OFFICIAL_SUM_OF_MONEY;

            SUM_RISING_DEBIT = SUM_RISING_DEBIT + DEBIT_SUM_OF_MONEY;
            SUM_RISING_CREDIT = SUM_RISING_CREDIT + CREDIT_SUM_OF_MONEY;

            BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

            HAS_VALUE = 1;
            SUSPEND;

            BEGINNING_SUM_OF_MONEY = ENDING_SUM_OF_MONEY;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_TIEN_GUI_NGAN_HANG_1_DT (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
ACCOUNT_CODE DM_CODE,
BEGINNING_SUM_OF_MONEY DM_DOUBLE,
DEBIT_SUM_OF_MONEY DM_DOUBLE,
CREDIT_SUM_OF_MONEY DM_DOUBLE,
BALANCE_SUM_OF_MONEY DM_DOUBLE,
ENDING_SUM_OF_MONEY DM_DOUBLE,
OBJECT_NAME DM_NAME)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
DECLARE VARIABLE PREV_OBJECT DM_ID;
DECLARE VARIABLE OBJECT DM_ID;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    
    PREV_OBJECT = NULL;

    FOR
        SELECT CODE_NUMBER, INPUT_DATE, VOUCHER_DATE, CONTENT,
            DEBIT_SUM_OF_MONEY, CREDIT_SUM_OF_MONEY,
            OBJECT0, ATOM_STRINGS.NAME, ACCOUNT_CODE
        FROM
        (
            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            DEBIT.OFFICIAL_SUM_OF_MONEY DEBIT_SUM_OF_MONEY, 0 CREDIT_SUM_OF_MONEY,
            DEBIT.OBJECT0, CREDIT_ATOM.CODE ACCOUNT_CODE,
            0 IS_DEBIT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            DEBIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            (
                DEBIT.OBJECT0 = :P_OBJECT0 OR
                (:P_OBJECT0 IS NULL AND DEBIT.OBJECT0 IS NOT NULL)
            )

            UNION ALL

            SELECT DOCUMENTS.CODE || '-' || NUMBER AS CODE_NUMBER, INPUT_DATE, VOUCHER_DATE,
            IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')') AS CONTENT,
            0 DEBIT_SUM_OF_MONEY, DEBIT.OFFICIAL_SUM_OF_MONEY CREDIT_SUM_OF_MONEY,
            CREDIT.OBJECT0, DEBIT_ATOM.CODE ACCOUNT_CODE,
            1 IS_DEBIT
            FROM ENTRIES
            JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
            JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
            JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
            JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
            JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
            JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
            JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID
            JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
            JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
            JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID
            WHERE ENTRIES.COMPANY = :P_COMPANY AND
            CREDIT_ATOM.CODE STARTING WITH :PARENT_ACCOUNT_CODE AND
            (
                CREDIT.OBJECT0 = :P_OBJECT0 OR
                (:P_OBJECT0 IS NULL AND CREDIT.OBJECT0 IS NOT NULL)
            )
        ) ABC
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ABC.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ABC.OBJECT0

        ORDER BY ABC.OBJECT0, INPUT_DATE, IS_DEBIT, CODE_NUMBER
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT,
            :DEBIT_SUM_OF_MONEY, :CREDIT_SUM_OF_MONEY,
            :OBJECT, :OBJECT_NAME, :ACCOUNT_CODE
    DO
    BEGIN
        IF(PREV_OBJECT IS NULL OR PREV_OBJECT <> OBJECT)THEN
        BEGIN
            PREV_OBJECT = OBJECT;

            
            SELECT DEBIT - CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT, :P_TU_NGAY)
            INTO :BEGINNING_SUM_OF_MONEY;
        END

        BALANCE_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY + DEBIT_SUM_OF_MONEY - CREDIT_SUM_OF_MONEY;

        ENDING_SUM_OF_MONEY = BALANCE_SUM_OF_MONEY;

        HAS_VALUE = 1;
        SUSPEND;

        BEGINNING_SUM_OF_MONEY = ENDING_SUM_OF_MONEY;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        IF(P_OBJECT0 IS NOT NULL)THEN
        BEGIN
            SELECT DEBIT - CREDIT
            FROM INT_SD_1_TK_1_DT0_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)
            INTO :BEGINNING_SUM_OF_MONEY;

            ENDING_SUM_OF_MONEY = BEGINNING_SUM_OF_MONEY;

            SELECT ATOM_STRINGS.NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
            INTO :OBJECT_NAME;
        END

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_SO_TONG_HOP_CHI_PHI_SX (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_ACCOUNT_511 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
DT DM_DOUBLE,
DDDK DM_DOUBLE,
TCPS DM_DOUBLE,
NVL DM_DOUBLE,
NC DM_DOUBLE,
MTC DM_DOUBLE,
CPC DM_DOUBLE,
KHAC DM_DOUBLE,
TCCP DM_DOUBLE,
GIA_VON DM_DOUBLE,
DDCK DM_DOUBLE,
LAI_LO DM_DOUBLE)
AS 
declare variable object dm_id;
declare variable account_code dm_code;
declare variable account_code_511 dm_code;
declare variable account_code_621 dm_code;
declare variable account_code_622 dm_code;
declare variable account_code_623 dm_code;
declare variable account_code_627 dm_code;
declare variable account_code_khac dm_code;
declare variable account_code_632 dm_code;
declare variable accounting_system dm_accounting_system;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT_511
    INTO :ACCOUNT_CODE_511;

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :ACCOUNTING_SYSTEM;

    IF(ACCOUNTING_SYSTEM = 1)THEN
    BEGIN
        ACCOUNT_CODE_621 = '621';
        ACCOUNT_CODE_622 = '622';
        ACCOUNT_CODE_623 = '623';
        ACCOUNT_CODE_627 = '627';
        ACCOUNT_CODE_KHAC = '154';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 2 OR ACCOUNTING_SYSTEM = 4)THEN
    BEGIN
        ACCOUNT_CODE_621 = '1541';
        ACCOUNT_CODE_622 = '1542';
        ACCOUNT_CODE_623 = '1543';
        ACCOUNT_CODE_627 = '1547';
        ACCOUNT_CODE_KHAC = '1548';
    END
    ELSE IF(ACCOUNTING_SYSTEM = 3)THEN
    BEGIN
        ACCOUNT_CODE_621 = '621';
        ACCOUNT_CODE_622 = '622';
        ACCOUNT_CODE_623 = '623';
        ACCOUNT_CODE_627 = '627';
        ACCOUNT_CODE_KHAC = '154';
    END

    ACCOUNT_CODE_632 = '632';

    FOR
        SELECT OBJECT0, CODE, NAME, SUM(DT), SUM(DDDK), SUM(DEBIT_NVL) - SUM(CREDIT_NVL), SUM(DEBIT_NC) - SUM(CREDIT_NC), SUM(DEBIT_MTC) - SUM(CREDIT_MTC), SUM(DEBIT_CPC) - SUM(CREDIT_CPC), SUM(DDCK), SUM(DEBIT_GIA_VON) - SUM(CREDIT_GIA_VON)
        FROM
        (
            SELECT OBJECT0, CREDIT-DEBIT DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :ACCOUNT_CODE_511, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT0, OFFICIAL_SUM_OF_MONEY DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE_511, '911', :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT0, -OFFICIAL_SUM_OF_MONEY DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, '911', :ACCOUNT_CODE_511, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, DEBIT - CREDIT DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_SD_1_TK_DT0_DN_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, OFFICIAL_SUM_OF_MONEY DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_621, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, OFFICIAL_SUM_OF_MONEY CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_621, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, OFFICIAL_SUM_OF_MONEY DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_622, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, OFFICIAL_SUM_OF_MONEY CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_622, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, OFFICIAL_SUM_OF_MONEY DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_623, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, OFFICIAL_SUM_OF_MONEY CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_623, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, OFFICIAL_SUM_OF_MONEY DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_627, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, OFFICIAL_SUM_OF_MONEY CREDIT_CPC, 0 DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_627, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, DEBIT - CREDIT AS DDCK, 0 DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, :ACCOUNT_CODE_KHAC, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC, 0 DDCK, OFFICIAL_SUM_OF_MONEY DEBIT_GIA_VON, 0 CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_CO_C(:P_COMPANY, :ACCOUNT_CODE_632, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT0, 0 DT, 0 DDDK, 0 DEBIT_NVL, 0 CREDIT_NVL, 0 DEBIT_NC, 0 CREDIT_NC, 0 DEBIT_MTC, 0 CREDIT_MTC, 0 DEBIT_CPC, 0 CREDIT_CPC0, 0 DDCK, 0 DEBIT_GIA_VON, OFFICIAL_SUM_OF_MONEY CREDIT_GIA_VON
            FROM INT_PS_CAP_TK_DT0_NO_C(:P_COMPANY, :ACCOUNT_CODE, :ACCOUNT_CODE_632, :P_TU_NGAY, :P_DEN_NGAY)
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = A.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = A.OBJECT0
        GROUP BY OBJECT0, CODE, NAME
        INTO :OBJECT, :CODE, :NAME, :DT, :DDDK, :NVL, :NC, :MTC, :CPC, :DDCK, :GIA_VON
    DO
    BEGIN
        IF(DT <> 0 OR DDDK <> 0 OR NVL <>0 OR NC <> 0 OR MTC <>0 OR CPC <> 0 OR GIA_VON <> 0 OR DDCK <> 0)THEN
        BEGIN
            TCPS = NVL + NC + MTC + CPC;
            KHAC = DDCK - TCPS - DDDK + GIA_VON;

            TCPS = TCPS + KHAC;
            TCCP = DDDK + TCPS;

            LAI_LO = DT - GIA_VON;

            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_SO_TONG_HOP_TAI_KHOAN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_DETAIL_OBJECTS DM_BOOL,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ACCOUNT_CODE DM_CODE,
ACCOUNT_NAME DM_NAME,
BEGINNING_DEBIT DM_DOUBLE,
BEGINNING_CREDIT DM_DOUBLE,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE,
ENDING_DEBIT DM_DOUBLE,
ENDING_CREDIT DM_DOUBLE,
SUM_RISING_DEBIT DM_DOUBLE,
SUM_RISING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE IS_ACCOUNT DM_BOOL;
DECLARE VARIABLE LEVEL_DETAIL DM_INTEGER;
DECLARE VARIABLE LEVEL_COUNT DM_INTEGER;
DECLARE VARIABLE NOT154X2 DM_INTEGER;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 4096)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :NOT154X2;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    IF(NOT154X2 > 0 AND PARENT_ACCOUNT_CODE NOT STARTING WITH '154')THEN
        NOT154X2 = 0;

    IF(P_OBJECT0 IS NULL)THEN P_OBJECT1 = NULL;

    SELECT DEBIT, CREDIT
    FROM INT_SD_1_TK_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY)
    INTO :BEGINNING_DEBIT, :BEGINNING_CREDIT;

    SUM_RISING_DEBIT = 0;
    SUM_RISING_CREDIT = 0;

    IF(P_DETAIL_OBJECTS = 1)THEN
    BEGIN
        FOR
            SELECT CODE, NAME, IS_ACCOUNT, LEVEL_DETAIL, DEBIT, CREDIT
            FROM INT_PS_1_TK_N_TK_N_DT(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_OBJECT1, :P_TU_NGAY, :P_DEN_NGAY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = OBJECT
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = OBJECT
            INTO :ACCOUNT_CODE, :ACCOUNT_NAME, :IS_ACCOUNT, :LEVEL_DETAIL, :RISING_DEBIT, :RISING_CREDIT
        DO
        BEGIN
            IF(IS_ACCOUNT = 1)THEN
            BEGIN
                IF(NOT154X2 = 0 OR ACCOUNT_CODE NOT STARTING WITH '154')THEN
                BEGIN
                    SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
                    SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
                END
            
                ENDING_DEBIT = BEGINNING_DEBIT + SUM_RISING_DEBIT - BEGINNING_CREDIT - SUM_RISING_CREDIT;
                IF(ENDING_DEBIT > 0)THEN
                    ENDING_CREDIT = 0;
                ELSE
                BEGIN
                    ENDING_CREDIT = ABS(ENDING_DEBIT);
                    ENDING_DEBIT = 0;
                END
            END

            LEVEL_COUNT = 0;
            WHILE(LEVEL_COUNT < LEVEL_DETAIL)DO
            BEGIN
                LEVEL_COUNT = LEVEL_COUNT + 1;
                ACCOUNT_CODE = '*' || ACCOUNT_CODE;
            END

            SUSPEND;
        END
    END
    ELSE
    BEGIN
        FOR
            SELECT CODE, NAME, DEBIT, CREDIT
            FROM INT_PS_1_TK_N_TK(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ACCOUNT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNT
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ACCOUNT
            ORDER BY CODE
            INTO :ACCOUNT_CODE, :ACCOUNT_NAME, :RISING_DEBIT, :RISING_CREDIT
        DO
        BEGIN
            IF(NOT154X2 = 0 OR ACCOUNT_CODE NOT STARTING WITH '154')THEN
            BEGIN
                SUM_RISING_DEBIT = SUM_RISING_DEBIT + RISING_DEBIT;
                SUM_RISING_CREDIT = SUM_RISING_CREDIT + RISING_CREDIT;
            END
            
            ENDING_DEBIT = BEGINNING_DEBIT + SUM_RISING_DEBIT - BEGINNING_CREDIT - SUM_RISING_CREDIT;
            IF(ENDING_DEBIT > 0)THEN
                ENDING_CREDIT = 0;
            ELSE
            BEGIN
                ENDING_CREDIT = ABS(ENDING_DEBIT);
                ENDING_DEBIT = 0;
            END
        
            SUSPEND;
        END
    END
END ^

ALTER PROCEDURE RPT_THE_KHO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_GOODS DM_ID,
P_WAREHOUSE DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (INPUT_CODE DM_DOCUMENT_CODE,
OUTPUT_CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
VOUCHER_DATE DM_DATE,
CONTENT DM_CONTENT,
PRICE DM_DOUBLE,
BEGINNING_AMOUNT DM_DOUBLE,
INPUT_AMOUNT DM_DOUBLE,
OUTPUT_AMOUNT DM_DOUBLE,
INVENTORY_AMOUNT DM_DOUBLE,
ENDING_AMOUNT DM_DOUBLE,
GOODS_NAME DM_NAME,
GOODS_UNIT DM_UNIT)
AS 
DECLARE VARIABLE CODE DM_DOCUMENT_CODE;
DECLARE VARIABLE DEBIT_GOODS DM_ID;
DECLARE VARIABLE DEBIT_WAREHOUSE DM_ID;
DECLARE VARIABLE CREDIT_GOODS DM_ID;
DECLARE VARIABLE CREDIT_WAREHOUSE DM_ID;
DECLARE VARIABLE AMOUNT DM_DOUBLE;
DECLARE VARIABLE PRINT_REPORT_PERSON_NAME DM_INTEGER;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    SELECT BIN_AND(ACCOUNTING_SETTINGS.OTHERS, 512)
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :PRINT_REPORT_PERSON_NAME;

    SELECT ATOM_STRINGS.NAME, IIF(GOODS_STRINGS.UNIT IS NULL OR GOODS_STRINGS.UNIT = '',NULL,'(' || GOODS_STRINGS.UNIT || ')')
    FROM ATOM_STRINGS
    LEFT JOIN GOODS_STRINGS ON GOODS_STRINGS.COMPANY = :P_COMPANY AND GOODS_STRINGS.LANGUAGE = :P_LANGUAGE AND GOODS_STRINGS.ID = :P_GOODS
    WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_GOODS
    INTO :GOODS_NAME, :GOODS_UNIT;

    HAS_VALUE = 0;

    SELECT AMOUNT
    FROM INT_SD_1_VT_1_KHO_DN(:P_COMPANY, :P_GOODS, :P_WAREHOUSE, :P_TU_NGAY)
    INTO :BEGINNING_AMOUNT;

    FOR
        SELECT CODE || '-' || NUMBER, INPUT_DATE, VOUCHER_DATE,
        IIF(ENTRY_BASE_STRINGS.CONTENT IS NULL OR ENTRY_BASE_STRINGS.CONTENT='', DOCUMENT_BASE_STRINGS.CONTENT, ENTRY_BASE_STRINGS.CONTENT) || IIF(:PRINT_REPORT_PERSON_NAME = 0 OR DOCUMENT_STRINGS.PERSON_NAME IS NULL OR DOCUMENT_STRINGS.PERSON_NAME = '', '', '(' || DOCUMENT_STRINGS.PERSON_NAME || ')'),
        DEBIT.PRICE, DEBIT.AMOUNT,
        DEBIT.OBJECT0, DEBIT.OBJECT1,
        CREDIT.OBJECT0, CREDIT.OBJECT1
        FROM ENTRIES
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN DOCUMENT_STRINGS ON DOCUMENT_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_STRINGS.ID = DOCUMENTS.ID
        JOIN DOCUMENT_BASE_STRINGS ON DOCUMENT_BASE_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_BASE_STRINGS.ID = DOCUMENTS.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ((DEBIT.OBJECT0 = :P_GOODS AND DEBIT.OBJECT1 = :P_WAREHOUSE) OR (CREDIT.OBJECT0 = :P_GOODS AND CREDIT.OBJECT1 = :P_WAREHOUSE))
        ORDER BY INPUT_DATE, ENTRIES.ID
        INTO :CODE, :INPUT_DATE, :VOUCHER_DATE, :CONTENT,
        :PRICE, :AMOUNT,
        :DEBIT_GOODS, :DEBIT_WAREHOUSE,
        :CREDIT_GOODS, :CREDIT_WAREHOUSE
    DO
    BEGIN
        IF(DEBIT_GOODS = P_GOODS AND DEBIT_WAREHOUSE = P_WAREHOUSE)THEN
        BEGIN
            INPUT_CODE = CODE;
            INPUT_AMOUNT = AMOUNT;

            OUTPUT_CODE = NULL;
            OUTPUT_AMOUNT = 0;

            INVENTORY_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
            HAS_VALUE = 1;
            ENDING_AMOUNT = INVENTORY_AMOUNT;
            SUSPEND;
            BEGINNING_AMOUNT = INVENTORY_AMOUNT;

            IF(CREDIT_GOODS = P_GOODS AND CREDIT_WAREHOUSE = P_WAREHOUSE) THEN
            BEGIN
                INPUT_CODE = NULL;
                INPUT_AMOUNT = 0;

                OUTPUT_CODE = CODE;
                OUTPUT_AMOUNT = AMOUNT;

                INVENTORY_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
                HAS_VALUE = 1;
                ENDING_AMOUNT = INVENTORY_AMOUNT;
                SUSPEND;
                BEGINNING_AMOUNT = INVENTORY_AMOUNT;
            END
        END
        ELSE
        BEGIN
            INPUT_CODE = NULL;
            INPUT_AMOUNT = 0;

            OUTPUT_CODE = CODE;
            OUTPUT_AMOUNT = AMOUNT;

            INVENTORY_AMOUNT = BEGINNING_AMOUNT + INPUT_AMOUNT - OUTPUT_AMOUNT;
            HAS_VALUE = 1;
            ENDING_AMOUNT = INVENTORY_AMOUNT;
            SUSPEND;
            BEGINNING_AMOUNT = INVENTORY_AMOUNT;
        END
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        ENDING_AMOUNT = BEGINNING_AMOUNT;

        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_THE_TAI_SAN_CO_DINH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ASSET DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PLACE_OF_MADE DM_ADDRESS,
DEPARTMENT_NAME DM_NAME,
PURPOSE DM_PURPOSE,
DATE_OF_RISING DM_DATE,
DATE_OF_USING DM_DATE,
YEAR_OF_MADE DM_INTEGER,
TRANSFER_REPORT DM_TRANSFER_REPORT,
DATE_OF_TRANSFER DM_DATE,
DATE_OF_SUSPENDED DM_DATE,
CAPACITY DM_CAPACITY,
SUSPENDED_REASON DM_SUSPENED_REASON,
DECREASE_DOCUMENT_CODE DM_DOCUMENT_CODE,
DECREASE_VOUCHER_DATE DM_DATE,
DECREASE_CONTENT DM_CONTENT)
AS 
DECLARE VARIABLE DEPARTMENT DM_ID;
DECLARE VARIABLE ASSET_ACCOUNT DM_ID;
BEGIN
    FOR
        SELECT ASSETS.ID,ORDINAL, NOTE,CODE, NAME, HIDE, PLACE_OF_MADE,
        DEPARTMENT, PURPOSE, DATE_OF_RISING, DATE_OF_USING,
        YEAR_OF_MADE, TRANSFER_REPORT, DATE_OF_TRANSFER, DATE_OF_SUSPENDED, CAPACITY, SUSPENDED_REASON,
        ASSETS.ASSET_ACCOUNT
        FROM ASSETS
        JOIN ASSET_STRINGS ON ASSET_STRINGS.COMPANY = :P_COMPANY AND ASSET_STRINGS.LANGUAGE = :P_LANGUAGE AND ASSET_STRINGS.ID = :P_ASSET
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ASSETS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = :P_ASSET
        INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PLACE_OF_MADE,
        :DEPARTMENT, :PURPOSE, :DATE_OF_RISING, :DATE_OF_USING,
        :YEAR_OF_MADE, :TRANSFER_REPORT, :DATE_OF_TRANSFER, :DATE_OF_SUSPENDED, :CAPACITY, :SUSPENDED_REASON,
        :ASSET_ACCOUNT
    DO
    BEGIN
        IF(DEPARTMENT IS NULL)THEN
            DEPARTMENT_NAME = NULL;
        ELSE
            SELECT NAME
            FROM ATOM_STRINGS
            WHERE ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :DEPARTMENT
            INTO :DEPARTMENT_NAME;

        SELECT FIRST 1 CODE || '-' || NUMBER, VOUCHER_DATE, ENTRY_BASE_STRINGS.CONTENT
        FROM DOCUMENTS
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1 AND CREDIT.ACCOUNT = :ASSET_ACCOUNT AND CREDIT.OBJECT0 = :ID
        WHERE DOCUMENTS.COMPANY = :P_COMPANY
        ORDER BY INPUT_DATE DESC
        INTO :DECREASE_DOCUMENT_CODE, :DECREASE_VOUCHER_DATE, :DECREASE_CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_THE_TAI_SAN_CO_DINH_DUNG_CU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ASSET DM_ID)
RETURNS (AMOUNT DM_DOUBLE,
SUM_OF_MONEY DM_DOUBLE,
NAME DM_NAME,
UNIT DM_UNIT)
AS 
BEGIN
    FOR
        SELECT AMOUNT, SUM_OF_MONEY, NAME, UNIT
        FROM ACCESSORIES
        JOIN ACCESSORY_STRINGS ON ACCESSORY_STRINGS.COMPANY = :P_COMPANY AND ACCESSORY_STRINGS.LANGUAGE = :P_LANGUAGE AND ACCESSORY_STRINGS.ID = ACCESSORIES.ID
        WHERE ACCESSORIES.COMPANY = :P_COMPANY AND ACCESSORIES.ASSET = :P_ASSET
        INTO :AMOUNT, :SUM_OF_MONEY, :NAME, :UNIT
    DO
        SUSPEND;
END ^

ALTER PROCEDURE RPT_THE_TAI_SAN_CO_DINH_GIA_TRI (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ASSET DM_ID,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_DOCUMENT_CODE,
ORIGINAL_PRICE_DATE DM_DATE,
ORIGINAL_PRICE_CONTENT DM_CONTENT,
DEBIT_CREDIT DM_DOUBLE,
ORIGINAL_PRICE DM_DOUBLE,
DEPRECIATION_YEAR DM_SMALLINT,
DEPRECIATION_VALUE DM_DOUBLE,
DEPRECIATION_SUM DM_DOUBLE)
AS 
declare variable asset_account dm_id;
declare variable debit_account dm_id;
declare variable debit_asset dm_id;
declare variable depreciation_account dm_id;
declare variable debit dm_double;
declare variable credit dm_double;
declare variable OFFICIAL_SUM_OF_MONEY dm_double;
BEGIN
    SELECT ASSET_ACCOUNT, DEPRECIATION_ACCOUNT
    FROM ASSETS
    WHERE ASSETS.ID = :P_ASSET
    INTO :ASSET_ACCOUNT, :DEPRECIATION_ACCOUNT;

    ORIGINAL_PRICE = 0;
    DEPRECIATION_SUM = 0;

    FOR
        SELECT DOCUMENTS.CODE || '-' || NUMBER, DOCUMENTS.INPUT_DATE, ENTRY_BASE_STRINGS.CONTENT, DEBIT.OFFICIAL_SUM_OF_MONEY,
                DEBIT.ACCOUNT, DEBIT.OBJECT0
        FROM DOCUMENTS
        JOIN ENTRIES ON ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE AND ENTRY_BASE_STRINGS.ID = ENTRIES.ID
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.SIDE = 0 AND DEBIT.ENTRY = ENTRIES.ID
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.SIDE = 1 AND CREDIT.ENTRY = ENTRIES.ID
        WHERE DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.INPUT_DATE <= :P_DEN_NGAY AND ((DEBIT.ACCOUNT = :ASSET_ACCOUNT AND DEBIT.OBJECT0 = :P_ASSET) OR (CREDIT.ACCOUNT = :ASSET_ACCOUNT AND CREDIT.OBJECT0 = :P_ASSET))
        ORDER BY DOCUMENTS.VOUCHER_DATE, DOCUMENTS.ID, ENTRIES.id
        INTO :CODE, :ORIGINAL_PRICE_DATE, :ORIGINAL_PRICE_CONTENT, :OFFICIAL_SUM_OF_MONEY,
                :DEBIT_ACCOUNT, :DEBIT_ASSET
    DO
    BEGIN
        IF(DEBIT_ACCOUNT = :ASSET_ACCOUNT AND DEBIT_ASSET = :P_ASSET)THEN
        BEGIN
            debit_credit = OFFICIAL_SUM_OF_MONEY;
            ORIGINAL_PRICE = ORIGINAL_PRICE + OFFICIAL_SUM_OF_MONEY;
        END
        ELSE
        BEGIN
            debit_credit = 0 - OFFICIAL_SUM_OF_MONEY;
            ORIGINAL_PRICE = ORIGINAL_PRICE - OFFICIAL_SUM_OF_MONEY;
        END

        DEPRECIATION_YEAR = EXTRACT(YEAR FROM ORIGINAL_PRICE_DATE);

        SELECT DEBIT, CREDIT
        FROM INT_SD_1_TK_1_DT0_CN(:P_COMPANY, :DEPRECIATION_ACCOUNT, :P_ASSET, :ORIGINAL_PRICE_DATE)
        INTO :DEBIT, :CREDIT;

        DEPRECIATION_VALUE = CREDIT - DEBIT;
        DEPRECIATION_SUM = DEPRECIATION_SUM + DEPRECIATION_VALUE;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_THE_TINH_GIA_THANH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT_CODE DM_CODE,
OBJECT_NAME DM_NAME,
OBJECT_CODE_1 DM_CODE,
OBJECT_NAME_1 DM_NAME,
DD_DK_TC DM_DOUBLE,
PS_TK_TC DM_DOUBLE,
PS_TK_NVL DM_DOUBLE,
PS_TK_NC DM_DOUBLE,
PS_TK_MTC DM_DOUBLE,
PS_TK_CPC DM_DOUBLE,
GT_TK_TC DM_DOUBLE,
DD_CK_TC DM_DOUBLE)
AS 
DECLARE VARIABLE OBJECT_TYPE1 DM_ID;
BEGIN
    IF(P_OBJECT0 IS NULL)THEN
    BEGIN
        FOR
            SELECT CODE, NAME, DDDK, TCPS, NVL, NC, MTC, CPC, GIA_VON, DDCK
            FROM RPT_SO_TONG_HOP_CHI_PHI_SX(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_ACCOUNT, NULL, :P_TU_NGAY, :P_DEN_NGAY)
            INTO :OBJECT_CODE, :OBJECT_NAME, DD_DK_TC, :PS_TK_TC, :PS_TK_NVL, :PS_TK_NC, :PS_TK_MTC, :PS_TK_CPC, :GT_TK_TC, :DD_CK_TC
        DO
        BEGIN
            SUSPEND;
        END
    END
    ELSE
    BEGIN
        SELECT ACCOUNTS.ATOM_TYPE_1
        FROM ACCOUNTS
        WHERE ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = :P_ACCOUNT
        INTO :OBJECT_TYPE1;

        IF(OBJECT_TYPE1 IS NULL)THEN
        BEGIN
            FOR
                SELECT DD_DK_TC, PS_TK_TC, PS_TK_NVL, PS_TK_NC, PS_TK_MTC, PS_TK_CPC, GT_TK_TC, DD_CK_TC
                FROM INT_THE_TINH_GIA_THANH(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_ACCOUNT, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
                INTO :DD_DK_TC, :PS_TK_TC, :PS_TK_NVL, :PS_TK_NC, :PS_TK_MTC, :PS_TK_CPC, :GT_TK_TC, :DD_CK_TC
            DO
            BEGIN
                SELECT CODE, NAME
                FROM ATOMS
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
                INTO :OBJECT_CODE, :OBJECT_NAME;

                SUSPEND;
            END
        END
        ELSE
        BEGIN
            SELECT CODE, NAME
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_OBJECT0
            INTO :OBJECT_CODE, :OBJECT_NAME;

            FOR
                SELECT ATOMS.CODE, ATOM_STRINGS.NAME, DD_DK_TC, PS_TK_TC, PS_TK_NVL, PS_TK_NC, PS_TK_MTC, PS_TK_CPC, GT_TK_TC, DD_CK_TC
                FROM INT_THE_TINH_GIA_THANH_2(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_ACCOUNT, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = OBJECT1
                JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = OBJECT1
                INTO :OBJECT_CODE_1, :OBJECT_NAME_1, :DD_DK_TC, :PS_TK_TC, :PS_TK_NVL, :PS_TK_NC, :PS_TK_MTC, :PS_TK_CPC, :GT_TK_TC, :DD_CK_TC
            DO
            BEGIN
                SUSPEND;
            END
        END
    END
END ^

ALTER PROCEDURE RPT_THONG_SO_BAO_CAO (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
TEAM_NAME DM_NAME,
TEMPLATE_FILE DM_FILE_NAME,
REPORT_TYPE DM_REPORT_TYPE,
KEY_FIELD_CODE DM_FIELD_CODE,
KEY_FIELD_NAME DM_FIELD_NAME,
FUNCTION_NAMES DM_NOTE,
PARAMETER_NAMES DM_NOTE,
VALUE_FIELD_NAMES DM_NOTE,
COLUMN_NAMES DM_NOTE)
AS 
BEGIN
    FOR
        SELECT REPORTS.ID, NOTE,
         ATOMS.CODE, ATOM_STRINGS.NAME, ATOMS.HIDE, ATOM_STRING_TEAMS.NAME, TEMPLATE_FILE, REPORT_TYPE, KEY_FIELD_CODE, KEY_FIELD_NAME
        FROM REPORTS
        JOIN REPORT_STRINGS ON REPORT_STRINGS.COMPANY = :P_COMPANY AND REPORT_STRINGS.LANGUAGE = :P_LANGUAGE AND REPORT_STRINGS.ID = REPORTS.ID
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = REPORTS.ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        LEFT JOIN ATOMS ATOM_TEAMS ON ATOM_TEAMS.COMPANY = :P_COMPANY AND ATOM_TEAMS.ID = ATOMS.TEAM
        LEFT JOIN ATOM_STRINGS ATOM_STRING_TEAMS ON ATOM_STRING_TEAMS.COMPANY = :P_COMPANY AND ATOM_STRING_TEAMS.LANGUAGE = :P_LANGUAGE AND ATOM_STRING_TEAMS.ID = ATOM_TEAMS.ID
        WHERE REPORTS.COMPANY = :P_COMPANY
        INTO :ID, :NOTE, :CODE, :NAME, :HIDE, :TEAM_NAME,
        :TEMPLATE_FILE, :REPORT_TYPE, :KEY_FIELD_CODE, :KEY_FIELD_NAME
    DO
    BEGIN
        SELECT LIST(REPORT_PROCEDURES.CODE || ':' || REPORT_PROCEDURES.PROCEDURE_NAME || ':' || REPORT_PROCEDURES.IS_MAIN, ',')
        FROM REPORT_PROCEDURES
        WHERE REPORT_PROCEDURES.COMPANY = :P_COMPANY AND REPORT_PROCEDURES.REPORT = :ID
        INTO :FUNCTION_NAMES;

        SELECT LIST(REPORT_VALUE_FIELDS.CODE || ':' || REPORT_VALUE_FIELDS.NAME, ',')
        FROM REPORT_VALUE_FIELDS
        WHERE REPORT_VALUE_FIELDS.COMPANY = :P_COMPANY AND REPORT_VALUE_FIELDS.REPORT = :ID
        INTO :VALUE_FIELD_NAMES;

        SELECT LIST(REPORT_COLUMNS.CODE || ':' || REPORT_COLUMNS.NAME, ',')
        FROM REPORT_COLUMNS
        WHERE REPORT_COLUMNS.COMPANY = :P_COMPANY AND REPORT_COLUMNS.REPORT = :ID
        INTO :COLUMN_NAMES;

        SELECT LIST(REPORT_PARAMETERS.CODE || ':' || REPORT_PARAMETERS.HIDE || ':' || PROTONS.ORDINAL || ':' || A.PARAMETERS, ',')
        FROM REPORT_PARAMETERS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = REPORT_PARAMETERS.ID
        LEFT JOIN
        (
                SELECT REPORT_ACCOUNT_PARAMETERS.ID,
                IIF(REPORT_ACCOUNT_PARAMETERS.OBJECT0_PARAMETER_CODE IS NULL, '', REPORT_ACCOUNT_PARAMETERS.OBJECT0_PARAMETER_CODE) || ':' ||
                IIF(REPORT_ACCOUNT_PARAMETERS.OBJECT1_PARAMETER_CODE IS NULL, '', REPORT_ACCOUNT_PARAMETERS.OBJECT1_PARAMETER_CODE) || ':' ||
                IIF(REPORT_ACCOUNT_PARAMETERS.OBJECT2_PARAMETER_CODE IS NULL, '', REPORT_ACCOUNT_PARAMETERS.OBJECT2_PARAMETER_CODE) || ':' ||
                IIF(REPORT_ACCOUNT_PARAMETERS.DEBIT_CREDIT_CODE IS NULL, '', REPORT_ACCOUNT_PARAMETERS.DEBIT_CREDIT_CODE) AS PARAMETERS
                FROM REPORT_ACCOUNT_PARAMETERS
                WHERE REPORT_ACCOUNT_PARAMETERS.COMPANY = :P_COMPANY

                UNION ALL

                SELECT REPORT_DATE_PARAMETERS.ID,
                IIF(REPORT_DATE_PARAMETERS.CODE_FIRST_FROM IS NULL, '', REPORT_DATE_PARAMETERS.CODE_FIRST_FROM) || ':' ||
                IIF(REPORT_DATE_PARAMETERS.CODE_SECOND_FROM IS NULL, '', REPORT_DATE_PARAMETERS.CODE_SECOND_FROM) || ':' ||
                IIF(REPORT_DATE_PARAMETERS.CODE_FIRST_TO IS NULL, '', REPORT_DATE_PARAMETERS.CODE_FIRST_TO) || ':' ||
                IIF(REPORT_DATE_PARAMETERS.CODE_SECOND_TO IS NULL, '', REPORT_DATE_PARAMETERS.CODE_SECOND_TO) || ':' ||
                REPORT_DATE_PARAMETERS.SELECTION_TYPES || ':' || REPORT_DATE_PARAMETERS.RETURN_TYPE
                AS PARAMETERS
                FROM REPORT_DATE_PARAMETERS
                WHERE REPORT_DATE_PARAMETERS.COMPANY = :P_COMPANY

                UNION ALL

                SELECT REPORT_OBJECT_PARAMETERS.ID, REPORT_OBJECT_PARAMETERS.OBJECT_TYPE PARAMETERS
                FROM REPORT_OBJECT_PARAMETERS
                WHERE REPORT_OBJECT_PARAMETERS.COMPANY = :P_COMPANY
        ) A ON A.ID = REPORT_PARAMETERS.ID
        WHERE REPORT_PARAMETERS.COMPANY = :P_COMPANY AND REPORT_PARAMETERS.REPORT = :ID
        INTO :PARAMETER_NAMES;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_THONG_SO_CHUNG_TU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
TEAM_NAME DM_NAME,
CREDIT_DEFAULT_ACCOUNT DM_CODE,
DEBIT_DEFAULT_ACCOUNT DM_CODE,
DEFAULT_CODE DM_CODE,
TYPES DM_DOCUMENT_TEAM_TYPES)
AS 
BEGIN
    FOR
    SELECT DOCUMENT_TEAMS.ID, ORDINAL, NOTE, ATOMS.CODE, ATOM_STRINGS.NAME, ATOMS.HIDE, ATOM_STRING_TEAMS.NAME,
    ATOM_DEBIT_ACCOUNTS.CODE,
    ATOM_CREDIT_ACCOUNTS.CODE,
    TYPES, DEFAULT_CODE
    FROM DOCUMENT_TEAMS
    JOIN DOCUMENT_TEAM_STRINGS ON DOCUMENT_TEAM_STRINGS.COMPANY = :P_COMPANY AND DOCUMENT_TEAM_STRINGS.LANGUAGE = :P_LANGUAGE AND DOCUMENT_TEAM_STRINGS.ID = DOCUMENT_TEAMS.ID
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = DOCUMENT_TEAMS.ID
    JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    LEFT JOIN ATOMS ATOM_TEAMS ON ATOM_TEAMS.COMPANY = :P_COMPANY AND ATOM_TEAMS.ID = ATOMS.TEAM
    LEFT JOIN ATOM_STRINGS ATOM_STRING_TEAMS ON ATOM_STRING_TEAMS.COMPANY = :P_COMPANY AND ATOM_STRING_TEAMS.LANGUAGE = :P_LANGUAGE AND ATOM_STRING_TEAMS.ID = ATOM_TEAMS.ID
    LEFT JOIN ATOMS ATOM_DEBIT_ACCOUNTS ON ATOM_DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_DEBIT_ACCOUNTS.ID = DOCUMENT_TEAMS.DEBIT_DEFAULT_ACCOUNT
    LEFT JOIN ATOMS ATOM_CREDIT_ACCOUNTS ON ATOM_CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND ATOM_CREDIT_ACCOUNTS.ID = DOCUMENT_TEAMS.CREDIT_DEFAULT_ACCOUNT
    WHERE DOCUMENT_TEAMS.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :TEAM_NAME,
        :DEBIT_DEFAULT_ACCOUNT,
        :CREDIT_DEFAULT_ACCOUNT,
        :TYPES, :DEFAULT_CODE
  DO
      SUSPEND;
END ^

ALTER PROCEDURE RPT_THONG_SO_KET_CHUYEN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_WORKING_DATE DM_DATE)
RETURNS (SOURCE_ORDINAL DM_INTEGER,
SOURCE_ACCOUNT DM_CODE,
SOURCE_OBJECT0 DM_CODE,
SOURCE_OBJECT1 DM_CODE,
DOCUMENT_CONTENT DM_CONTENT,
TRANSFER_ALL DM_BOOL,
TARGET_ORDINAL DM_INTEGER,
TARGET_ACCOUNT DM_CODE,
TARGET_OBJECT0 DM_CODE,
TARGET_OBJECT1 DM_CODE,
TRANSFER_TYPE DM_TRANSFER_TYPE,
PERCENT DM_DOUBLE)
AS 
DECLARE VARIABLE PERIOD_ID DM_ID;
DECLARE VARIABLE SOURCE_ID DM_ID;
BEGIN
    SELECT ID
    FROM CMD_GET_PERIOD_FROM_DATE(:P_COMPANY, :P_WORKING_DATE)
    INTO :PERIOD_ID;

    FOR
        SELECT SOURCE_ACCOUNTS.ID, SOURCE_ACCOUNTS_PROTONS.ORDINAL, ACCOUNT_ATOMS.CODE, OBJECT0_ATOMS.CODE, OBJECT1_ATOMS.CODE, DOCUMENT_CONTENT, TRANSFER_ALL
        FROM SOURCE_ACCOUNTS
        JOIN PROTONS SOURCE_ACCOUNTS_PROTONS ON SOURCE_ACCOUNTS_PROTONS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNTS_PROTONS.ID = SOURCE_ACCOUNTS.ID
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = SOURCE_ACCOUNTS.ACCOUNT
        JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = ACCOUNTS.ID
        LEFT JOIN ATOMS OBJECT0_ATOMS ON OBJECT0_ATOMS.COMPANY = :P_COMPANY AND OBJECT0_ATOMS.ID = SOURCE_ACCOUNTS.OBJECT0
        LEFT JOIN ATOMS OBJECT1_ATOMS ON OBJECT1_ATOMS.COMPANY = :P_COMPANY AND OBJECT1_ATOMS.ID = SOURCE_ACCOUNTS.OBJECT1
        WHERE SOURCE_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNTS.PERIOD = :PERIOD_ID
        ORDER BY SOURCE_ACCOUNTS_PROTONS.ORDINAL
        INTO :SOURCE_ID, :SOURCE_ORDINAL, :SOURCE_ACCOUNT, :SOURCE_OBJECT0, :SOURCE_OBJECT1, :DOCUMENT_CONTENT, :TRANSFER_ALL
    DO
    BEGIN
        FOR
            SELECT TARGET_ACCOUNTS_PROTONS.ORDINAL, ACCOUNT_ATOMS.CODE, OBJECT0_ATOMS.CODE, OBJECT1_ATOMS.CODE, TARGET_ACCOUNTS.TRANSFER_TYPE, TARGET_ACCOUNTS.PERCENT
            FROM TARGET_ACCOUNTS
            JOIN PROTONS TARGET_ACCOUNTS_PROTONS ON TARGET_ACCOUNTS_PROTONS.COMPANY = :P_COMPANY AND TARGET_ACCOUNTS_PROTONS.ID = TARGET_ACCOUNTS.ID
            JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNTS.ACCOUNT
            JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = ACCOUNTS.ID
            LEFT JOIN ATOMS OBJECT0_ATOMS ON OBJECT0_ATOMS.COMPANY = :P_COMPANY AND OBJECT0_ATOMS.ID = TARGET_ACCOUNTS.OBJECT0
            LEFT JOIN ATOMS OBJECT1_ATOMS ON OBJECT1_ATOMS.COMPANY = :P_COMPANY AND OBJECT1_ATOMS.ID = TARGET_ACCOUNTS.OBJECT1
            WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND TARGET_ACCOUNTS.SOURCE_ACCOUNT = :SOURCE_ID
            ORDER BY TARGET_ACCOUNTS_PROTONS.ORDINAL
            INTO :TARGET_ORDINAL, :TARGET_ACCOUNT, :TARGET_OBJECT0, :TARGET_OBJECT1, :TRANSFER_TYPE, :PERCENT
        DO
            SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_THONG_SO_KE_TOAN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
CURRENCY_CODE DM_CODE,
CURRENCY_NAME DM_NAME,
ON_NOT_EQUAL_VAT DM_ACTION_LEVEL,
ON_NOT_EQUAL_SUM DM_ACTION_LEVEL,
OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD,
OTHERS DM_OTHER_SETTINGS,
ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM)
AS 
BEGIN
    SELECT BEGINNING_DATE, ENDING_DATE, CURRENCY_ATOMS.CODE, CURRENCY_ATOM_STRINGS.NAME,
    ON_NOT_EQUAL_VAT, ON_NOT_EQUAL_SUM, OUTPUT_PRICE_METHOD, OTHERS, ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    JOIN PERIODS ON PERIODS.COMPANY = :P_COMPANY AND PERIODS.ID = ACCOUNTING_SETTINGS.BEGINNING_PERIOD
    JOIN CURRENCIES ON CURRENCIES.COMPANY = :P_COMPANY AND CURRENCIES.ID = ACCOUNTING_SETTINGS.MAIN_CURRENCY
    JOIN ATOMS CURRENCY_ATOMS ON CURRENCY_ATOMS.COMPANY = :P_COMPANY AND CURRENCY_ATOMS.ID = CURRENCIES.ID
    JOIN ATOM_STRINGS CURRENCY_ATOM_STRINGS ON CURRENCY_ATOM_STRINGS.COMPANY = :P_COMPANY AND CURRENCY_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND CURRENCY_ATOM_STRINGS.ID = CURRENCY_ATOMS.ID
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :BEGINNING_DATE, :ENDING_DATE, :CURRENCY_CODE, :CURRENCY_NAME,
    :ON_NOT_EQUAL_VAT, :ON_NOT_EQUAL_SUM, :OUTPUT_PRICE_METHOD, :OTHERS, :ACCOUNTING_SYSTEM;

    SUSPEND;
END ^

ALTER PROCEDURE RPT_THONG_SO_KY_KE_TOAN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (BEGINNING_DATE DM_DATE,
ENDING_DATE DM_DATE,
LOCKED DM_BOOL)
AS 
BEGIN
    FOR
        SELECT PERIODS.BEGINNING_DATE, PERIODS.ENDING_DATE, PERIODS.LOCKED
        FROM PERIODS
        WHERE PERIODS.COMPANY = :P_COMPANY
        ORDER BY BEGINNING_DATE
        INTO :BEGINNING_DATE, :ENDING_DATE, :LOCKED
    DO
        SUSPEND;
END ^

ALTER PROCEDURE RPT_THONG_SO_PHIEN_BAN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (CURRENT_VERSION DM_VERSION)
AS 
BEGIN
    FOR
        SELECT CURRENT_VERSION
        FROM TONY
        ORDER BY CURRENT_VERSION
        INTO :CURRENT_VERSION
    DO
        SUSPEND;
END ^

ALTER PROCEDURE RPT_THONG_SO_TAI_CHINH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (ORDINAL DM_INTEGER,
CODE DM_CODE,
NAME DM_NAME,
ITEM_CODE DM_CODE,
ITEM_NAME DM_NAME,
CAL_ORDER DM_SMALLINT,
INFO DM_NOTE)
AS 
DECLARE VARIABLE ID DM_ID;
DECLARE VARIABLE FINANCIAL_ID DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE SIDE DM_SIDE_OBJECT;
DECLARE VARIABLE GREATER_ZERO DM_BOOL;
DECLARE VARIABLE RATE DM_DOUBLE;
BEGIN
    FOR
        SELECT REPORTS.ID, REPORTS_ATOMS.CODE, REPORTS_ATOM_STRINGS.NAME
        FROM REPORTS
        JOIN ATOMS REPORTS_ATOMS ON REPORTS_ATOMS.COMPANY = :P_COMPANY AND REPORTS_ATOMS.ID = REPORTS.ID
        JOIN ATOM_STRINGS REPORTS_ATOM_STRINGS ON REPORTS_ATOM_STRINGS.COMPANY = :P_COMPANY AND REPORTS_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND REPORTS_ATOM_STRINGS.ID = REPORTS_ATOMS.ID
        WHERE REPORTS.COMPANY = :P_COMPANY AND REPORTS.REPORT_TYPE = 1 
        ORDER BY REPORTS_ATOMS.CODE
        INTO :ID, :CODE, :NAME
    DO
    BEGIN
        FOR
            SELECT FINANCIAL_REPORTS_PROTONS.ORDINAL, FINANCIAL_REPORTS.ID, FINANCIAL_REPORTS_ATOMS.CODE, FINANCIAL_REPORTS_ATOM_STRINGS.NAME, FINANCIAL_REPORTS.CAL_ORDER
            FROM FINANCIAL_REPORTS
            JOIN ATOMS FINANCIAL_REPORTS_ATOMS ON FINANCIAL_REPORTS_ATOMS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS_ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS FINANCIAL_REPORTS_ATOM_STRINGS ON FINANCIAL_REPORTS_ATOM_STRINGS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND FINANCIAL_REPORTS_ATOM_STRINGS.ID = FINANCIAL_REPORTS.ID
            JOIN PROTONS FINANCIAL_REPORTS_PROTONS ON FINANCIAL_REPORTS_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS_PROTONS.ID = FINANCIAL_REPORTS.ID
            WHERE FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = :ID
            ORDER BY FINANCIAL_REPORTS_PROTONS.ORDINAL
            INTO :ORDINAL, :FINANCIAL_ID, :ITEM_CODE, :ITEM_NAME, :CAL_ORDER
        DO
        BEGIN
            FOR
                SELECT ACCOUNT_ATOMS.CODE, FINANCIAL_BALANCES.SIDE, FINANCIAL_BALANCES.GREATER_ZERO, FINANCIAL_BALANCES.RATE
                FROM FINANCIAL_BALANCES
                JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = FINANCIAL_BALANCES.ACCOUNT
                JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = ACCOUNTS.ID
                WHERE FINANCIAL_BALANCES.COMPANY = :P_COMPANY AND FINANCIAL_BALANCES.FINANCIAL_REPORT = :FINANCIAL_ID
                INTO :ACCOUNT_CODE, :SIDE, :GREATER_ZERO, :RATE
            DO
            BEGIN
                INFO = '1. ' || SIDE || ' - ' || ACCOUNT_CODE || ' - ' || ROUND(RATE, 0) || ' - ' || GREATER_ZERO;
                SUSPEND;
            END

            FOR
                SELECT ACCOUNT_ATOMS.CODE, FINANCIAL_RISINGS.SIDE, FINANCIAL_RISINGS.RATE
                FROM FINANCIAL_RISINGS
                JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = FINANCIAL_RISINGS.ACCOUNT
                JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = ACCOUNTS.ID
                WHERE FINANCIAL_RISINGS.COMPANY = :P_COMPANY AND FINANCIAL_RISINGS.FINANCIAL_REPORT = :FINANCIAL_ID
                INTO :ACCOUNT_CODE, :SIDE, :RATE
            DO
            BEGIN
                INFO = '2. ' || SIDE || ' - ' || ACCOUNT_CODE || ' - ' || ROUND(RATE, 0);
                SUSPEND;
            END

            FOR
                SELECT DEBIT_ACCOUNT_ATOMS.CODE, CREDIT_ACCOUNT_ATOMS.CODE, FINANCIAL_DEBIT_CREDITS.RATE
                FROM FINANCIAL_DEBIT_CREDITS
                JOIN ACCOUNTS DEBIT_ACCOUNTS ON DEBIT_ACCOUNTS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNTS.ID = FINANCIAL_DEBIT_CREDITS.DEBIT_ACCOUNT
                JOIN ATOMS DEBIT_ACCOUNT_ATOMS ON DEBIT_ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT_ATOMS.ID = DEBIT_ACCOUNTS.ID
                JOIN ACCOUNTS CREDIT_ACCOUNTS ON CREDIT_ACCOUNTS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNTS.ID = FINANCIAL_DEBIT_CREDITS.CREDIT_ACCOUNT
                JOIN ATOMS CREDIT_ACCOUNT_ATOMS ON CREDIT_ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT_ATOMS.ID = CREDIT_ACCOUNTS.ID
                WHERE FINANCIAL_DEBIT_CREDITS.COMPANY = :P_COMPANY AND FINANCIAL_DEBIT_CREDITS.FINANCIAL_REPORT = :FINANCIAL_ID
                INTO :DEBIT_ACCOUNT_CODE, :CREDIT_ACCOUNT_CODE, :RATE
            DO
            BEGIN
                INFO = '3. ' || DEBIT_ACCOUNT_CODE || ' - ' || CREDIT_ACCOUNT_CODE || ' - ' || ROUND(RATE, 0);
                SUSPEND;
            END

            FOR
                SELECT ATOMS.CODE, FINANCIAL_CALS.RATE
                FROM FINANCIAL_CALS
                JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = FINANCIAL_CALS.FINANCIAL
                JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
                WHERE FINANCIAL_CALS.COMPANY = :P_COMPANY AND FINANCIAL_CALS.FINANCIAL_REPORT = :FINANCIAL_ID
                INTO :ACCOUNT_CODE, :RATE
            DO
            BEGIN
                INFO = '4. ' || ACCOUNT_CODE || ' - ' || ROUND(RATE, 0);
                SUSPEND;
            END
        END
    END
END ^

ALTER PROCEDURE RPT_THONG_SO_TAI_KHOAN (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
PARENT_CODE DM_CODE,
ATOM_TYPE_NAME_0 DM_NAME,
ATOM_TYPE_NAME_1 DM_NAME,
ATOM_TYPE_NAME_2 DM_NAME,
MUST_HAVE_OBJECT DM_MUST_HAVE_OBJECTS,
RELATED_OBJECTS DM_RELATED_OBJECTS,
ACCOUNT_TYPES DM_ACCOUNT_TYPES)
AS 
BEGIN
    FOR
        SELECT ACCOUNT_ATOMS.CODE, ACCOUNT_ATOM_STRINGS.NAME, PARENT_ATOMS.CODE,
        OBJECT_TYPES_0.NAME, OBJECT_TYPES_1.NAME, OBJECT_TYPES_2.NAME,
        MUST_HAVE_OBJECT, RELATED_OBJECTS, ACCOUNT_TYPES
        FROM ACCOUNTS
        JOIN ATOMS ACCOUNT_ATOMS ON ACCOUNT_ATOMS.COMPANY = :P_COMPANY AND ACCOUNT_ATOMS.ID = ACCOUNTS.ID
        JOIN ATOM_STRINGS ACCOUNT_ATOM_STRINGS ON ACCOUNT_ATOM_STRINGS.COMPANY = :P_COMPANY AND ACCOUNT_ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ACCOUNT_ATOM_STRINGS.ID = ACCOUNT_ATOMS.ID
        LEFT JOIN ATOMS PARENT_ATOMS ON PARENT_ATOMS.COMPANY = :P_COMPANY AND PARENT_ATOMS.ID = ACCOUNT_ATOMS.PARENT
        LEFT JOIN OBJECT_TYPES OBJECT_TYPES_0 ON OBJECT_TYPES_0.ID = ACCOUNTS.ATOM_TYPE_0
        LEFT JOIN OBJECT_TYPES OBJECT_TYPES_1 ON OBJECT_TYPES_1.ID = ACCOUNTS.ATOM_TYPE_1
        LEFT JOIN OBJECT_TYPES OBJECT_TYPES_2 ON OBJECT_TYPES_2.ID = ACCOUNTS.ATOM_TYPE_2
        WHERE ACCOUNTS.COMPANY = :P_COMPANY
        ORDER BY ACCOUNT_ATOMS.CODE
        INTO :CODE, :NAME, :PARENT_CODE,
        :ATOM_TYPE_NAME_0, :ATOM_TYPE_NAME_1, :ATOM_TYPE_NAME_2,
        :MUST_HAVE_OBJECT, :RELATED_OBJECTS, :ACCOUNT_TYPES
    DO
        SUSPEND;
END ^

ALTER PROCEDURE RPT_TH_PS_DT0_TK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_ACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (CODE DM_CODE,
NAME DM_NAME,
RISING_DEBIT DM_DOUBLE,
RISING_CREDIT DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :ACCOUNT_CODE;

    FOR
        SELECT CODE,  NAME, SUM(DEBIT), SUM(CREDIT)
        FROM INT_PS_1_TK_DT0_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = INT_PS_1_TK_DT0_C.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = INT_PS_1_TK_DT0_C.OBJECT0
        GROUP BY OBJECT0, CODE,  NAME
        ORDER BY CODE, NAME
        INTO :CODE, :NAME, :RISING_DEBIT, :RISING_CREDIT
    DO
    BEGIN
        IF(RISING_DEBIT <> 0 OR RISING_CREDIT <> 0)THEN SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_TINH_GIA_THANH_DET (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_SL_TON_DAU_KY DM_DOUBLE,
P_SL_PHAT_SINH_TRONG_KY DM_DOUBLE,
P_SL_XUAT_TRONG_KY DM_DOUBLE,
P_SL_XUAT_BAN DM_DOUBLE,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SL_TON_CUOI_KY DM_DOUBLE,
CODE DM_CODE,
NAME DM_NAME,
TON_DAU_KY DM_DOUBLE,
PHAT_SINH_TRONG_KY DM_DOUBLE,
TONG_CONG DM_DOUBLE,
XUAT DM_DOUBLE,
XUAT_BAN DM_DOUBLE,
TON_CUOI_KY DM_DOUBLE,
GIA_THANH_VND DM_DOUBLE,
GIA_THANH_USD DM_DOUBLE,
GIA_THANH_DAU_KY DM_DOUBLE,
GIA_THANH_PHAT_SINH DM_DOUBLE,
GIA_THANH_TONG_CONG DM_DOUBLE,
GIA_THANH_PHAT_SINH_USD DM_DOUBLE,
GIA_THANH_XUAT DM_DOUBLE,
GIA_THANH_XUAT_BAN DM_DOUBLE,
GIA_THANH_TONG_CONG_USD DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE TON_TRUOC DM_DOUBLE;
DECLARE VARIABLE SL_TONG_CONG_TON_PHAT_SINH DM_DOUBLE;
DECLARE VARIABLE SUM_TON_DAU_KY DM_DOUBLE;
DECLARE VARIABLE SUM_PHAT_SINH_TRONG_KY DM_DOUBLE;
DECLARE VARIABLE SUM_TONG_CONG DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT_BAN DM_DOUBLE;
DECLARE VARIABLE OBJECT_DET_SHIMA_GC DM_ID;
DECLARE VARIABLE OBJECT_DET_SHIMA DM_ID;
DECLARE VARIABLE OBJECT_DET_COTTON_GC DM_ID;
DECLARE VARIABLE OBJECT_DET_COTTON DM_ID;
BEGIN
    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ACCOUNT
    INTO :PARENT_ACCOUNT_CODE;

    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'DET SHIMA'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_DET_SHIMA;

    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'DET SHIMA GC'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_DET_SHIMA_GC;

    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'DET COTTON & PROTTI'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_DET_COTTON;

    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'DET COTTON & PROTTI GC'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_DET_COTTON_GC;

    IF(P_SL_TON_DAU_KY IS NULL)THEN P_SL_TON_DAU_KY = 0;
    IF(P_SL_PHAT_SINH_TRONG_KY IS NULL)THEN P_SL_PHAT_SINH_TRONG_KY = 0;
    IF(P_SL_XUAT_TRONG_KY IS NULL)THEN P_SL_XUAT_TRONG_KY = 0;
    IF(P_SL_XUAT_BAN IS NULL)THEN P_SL_XUAT_BAN = 0;

    SL_TONG_CONG_TON_PHAT_SINH = P_SL_TON_DAU_KY + P_SL_PHAT_SINH_TRONG_KY;
    SL_TON_CUOI_KY = SL_TONG_CONG_TON_PHAT_SINH - P_SL_XUAT_TRONG_KY - P_SL_XUAT_BAN;

    SUM_TON_DAU_KY = 0;
    SUM_PHAT_SINH_TRONG_KY = 0;
    SUM_TONG_CONG = 0;
    SUM_XUAT = 0;
    SUM_XUAT_BAN = 0;

    FOR
        SELECT CODE, NAME, SUM(TON_DAU_KY), SUM(TON_TRUOC), SUM(PHAT_SINH_TRONG_KY), SUM(XUAT), SUM(XUAT_BAN)
        FROM
        (
            SELECT OBJECT1, DEBIT-CREDIT TON_DAU_KY, 0 TON_TRUOC, 0 PHAT_SINH_TRONG_KY, 0 XUAT, 0 XUAT_BAN
            FROM INT_SD_1_TK_1_DT0_DT1_DN_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, OFFICIAL_SUM_OF_MONEY TON_TRUOC, 0 PHAT_SINH_TRONG_KY, 0 XUAT, 0 XUAT_BAN
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT_DET_SHIMA_GC, :PARENT_ACCOUNT_CODE, :OBJECT_DET_SHIMA, :P_TU_NGAY, :P_DEN_NGAY)
            WHERE :P_OBJECT0 = :OBJECT_DET_SHIMA_GC

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, OFFICIAL_SUM_OF_MONEY TON_TRUOC, 0 PHAT_SINH_TRONG_KY, 0 XUAT, 0 XUAT_BAN
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :OBJECT_DET_COTTON_GC, :PARENT_ACCOUNT_CODE, :OBJECT_DET_COTTON, :P_TU_NGAY, :P_DEN_NGAY)
            WHERE :P_OBJECT0 = :OBJECT_DET_COTTON_GC

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, 0 TON_TRUOC, DEBIT PHAT_SINH_TRONG_KY, 0 XUAT, 0 XUAT_BAN
            FROM INT_PS_1_TK_1_DT0_DT1_C(:P_COMPANY, :PARENT_ACCOUNT_CODE, :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 TON_DAU_KY, 0 TON_TRUOC, 0 PHAT_SINH_TRONG_KY, OFFICIAL_SUM_OF_MONEY XUAT, 0 XUAT_BAN
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '154', NULL, '154', :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 TON_DAU_KY, 0 TON_TRUOC, 0 PHAT_SINH_TRONG_KY, 0 XUAT, OFFICIAL_SUM_OF_MONEY XUAT_BAN
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '632', NULL, '154', :P_OBJECT0, :P_TU_NGAY, :P_DEN_NGAY)
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = A.OBJECT1
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        GROUP BY OBJECT1, CODE, NAME, PROTONS.ORDINAL
        ORDER BY PROTONS.ORDINAL
        INTO :CODE, :NAME, :TON_DAU_KY, :TON_TRUOC, :PHAT_SINH_TRONG_KY, :XUAT, :XUAT_BAN
    DO
    BEGIN
        TON_DAU_KY = TON_DAU_KY + TON_TRUOC;
        PHAT_SINH_TRONG_KY = PHAT_SINH_TRONG_KY - TON_TRUOC;

        TONG_CONG = TON_DAU_KY + PHAT_SINH_TRONG_KY;
        TON_CUOI_KY = TONG_CONG - XUAT - XUAT_BAN;

        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_VND = ROUND(TON_CUOI_KY/SL_TON_CUOI_KY);

        SUM_TON_DAU_KY = SUM_TON_DAU_KY + TON_DAU_KY;
        SUM_PHAT_SINH_TRONG_KY = SUM_PHAT_SINH_TRONG_KY + PHAT_SINH_TRONG_KY;
        SUM_TONG_CONG = SUM_TONG_CONG + TONG_CONG;
        SUM_XUAT = SUM_XUAT + XUAT;
        SUM_XUAT_BAN = SUM_XUAT_BAN + SUM_XUAT_BAN;

        IF(P_SL_TON_DAU_KY <> 0)THEN GIA_THANH_DAU_KY = ROUND(SUM_TON_DAU_KY/P_SL_TON_DAU_KY, 0);
        IF(P_SL_PHAT_SINH_TRONG_KY <> 0)THEN GIA_THANH_PHAT_SINH = ROUND(SUM_PHAT_SINH_TRONG_KY/P_SL_PHAT_SINH_TRONG_KY, 0);
        IF(SL_TONG_CONG_TON_PHAT_SINH <> 0)THEN GIA_THANH_TONG_CONG = ROUND(SUM_TONG_CONG/SL_TONG_CONG_TON_PHAT_SINH, 0);
        IF(P_SL_XUAT_TRONG_KY <> 0 AND SUM_XUAT <> 0)THEN GIA_THANH_XUAT = GIA_THANH_TONG_CONG;
        IF(P_SL_XUAT_BAN <> 0 AND SUM_XUAT_BAN <> 0)THEN GIA_THANH_XUAT_BAN = GIA_THANH_TONG_CONG;

        IF(P_EXCHANGE_RATE <> 0)THEN
        BEGIN
            GIA_THANH_USD = ROUND(GIA_THANH_VND/P_EXCHANGE_RATE, 2);
            GIA_THANH_PHAT_SINH_USD = ROUND(GIA_THANH_PHAT_SINH/P_EXCHANGE_RATE, 2);
            GIA_THANH_TONG_CONG_USD = ROUND(GIA_THANH_TONG_CONG/P_EXCHANGE_RATE, 2);
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_TINH_GIA_THANH_MAY_GIA_CONG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_SL_TON_DAU_KY DM_DOUBLE,
P_SL_NHAP_KHO_TRONG_KY DM_DOUBLE,
P_SL_XUAT_TRONG_KY_HOAN_THANH DM_DOUBLE,
P_SL_XUAT_TRONG_KY_THANH_PHAM DM_DOUBLE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SL_TON_CUOI_KY DM_DOUBLE,
CODE DM_CODE,
NAME DM_NAME,
TON_DAU_KY DM_DOUBLE,
NHAP DM_DOUBLE,
NHAP_GC DM_DOUBLE,
TONG_CONG DM_DOUBLE,
XUAT_HOAN_THANH DM_DOUBLE,
XUAT_THANH_PHAM DM_DOUBLE,
TON_CUOI_KY DM_DOUBLE,
GIA_THANH_VND DM_DOUBLE,
GIA_THANH_USD DM_DOUBLE,
GIA_THANH_DAU_KY DM_DOUBLE,
GIA_THANH_NHAP DM_DOUBLE,
GIA_THANH_NHAP_USD DM_DOUBLE,
GIA_THANH_NHAP_GC DM_DOUBLE,
GIA_THANH_NHAP_GC_USD DM_DOUBLE,
GIA_THANH_XUAT_HOAN_THANH DM_DOUBLE,
GIA_THANH_XUAT_HOAN_THANH_USD DM_DOUBLE,
GIA_THANH_XUAT_THANH_PHAM DM_DOUBLE,
GIA_THANH_XUAT_THANH_PHAM_USD DM_DOUBLE,
GIA_THANH_TONG_CONG DM_DOUBLE,
GIA_THANH_TONG_CONG_USD DM_DOUBLE,
GIA_THANH_TON_CUOI_KY DM_DOUBLE,
GIA_THANH_TON_CUOI_KY_USD DM_DOUBLE)
AS 
DECLARE VARIABLE SL_NHAP_GC DM_DOUBLE;
DECLARE VARIABLE SL_TONG_CONG_TON_NHAP DM_DOUBLE;
DECLARE VARIABLE SUM_TON_DAU_KY DM_DOUBLE;
DECLARE VARIABLE SUM_NHAP DM_DOUBLE;
DECLARE VARIABLE SUM_NHAP_GC DM_DOUBLE;
DECLARE VARIABLE SUM_TONG_CONG DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT_HOAN_THANH DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT_THANH_PHAM DM_DOUBLE;
DECLARE VARIABLE SUM_TON_CUOI_KY DM_DOUBLE;
DECLARE VARIABLE OBJECT_HOAN_THANH DM_ID;
DECLARE VARIABLE OBJECT_MAY DM_ID;
DECLARE VARIABLE OBJECT_MAY_GC DM_ID;
BEGIN
    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'HT-GC'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_HOAN_THANH;

    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'MAY'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_MAY;

    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'MAY GC'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_MAY_GC;

    IF(P_SL_TON_DAU_KY IS NULL)THEN P_SL_TON_DAU_KY = 0;
    IF(P_SL_NHAP_KHO_TRONG_KY IS NULL)THEN P_SL_NHAP_KHO_TRONG_KY = 0;
    IF(P_SL_XUAT_TRONG_KY_HOAN_THANH IS NULL)THEN P_SL_XUAT_TRONG_KY_HOAN_THANH = 0;
    IF(P_SL_XUAT_TRONG_KY_THANH_PHAM IS NULL)THEN P_SL_XUAT_TRONG_KY_THANH_PHAM = 0;

    SL_NHAP_GC =  P_SL_NHAP_KHO_TRONG_KY - P_SL_XUAT_TRONG_KY_HOAN_THANH;
    SL_TONG_CONG_TON_NHAP = P_SL_TON_DAU_KY + SL_NHAP_GC;

    SL_TON_CUOI_KY = SL_TONG_CONG_TON_NHAP - P_SL_XUAT_TRONG_KY_THANH_PHAM;

    SUM_TON_DAU_KY = 0;
    SUM_NHAP = 0;
    SUM_NHAP_GC = 0;
    SUM_TONG_CONG = 0;
    SUM_XUAT_HOAN_THANH = 0;
    SUM_XUAT_THANH_PHAM = 0;
    SUM_TON_CUOI_KY = 0;

    FOR
        SELECT CODE, NAME, SUM(TON_DAU_KY), SUM(PHAT_SINH_TRONG_KY), SUM(NHAP_GC), SUM(XUAT_HOAN_THANH), SUM(XUAT_THANH_PHAM)
        FROM
        (
            SELECT OBJECT1, DEBIT-CREDIT TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 NHAP_GC, 0 XUAT_HOAN_THANH, 0 XUAT_THANH_PHAM
            FROM INT_SD_1_TK_1_DT0_DT1_DN_C(:P_COMPANY, '155', :OBJECT_MAY_GC, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT1, OFFICIAL_SUM_OF_MONEY TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 NHAP_GC, 0 XUAT_HOAN_THANH, 0 XUAT_THANH_PHAM
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '155', :OBJECT_MAY_GC, '155', :OBJECT_MAY, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, DEBIT PHAT_SINH_TRONG_KY, 0 NHAP_GC, 0 XUAT_HOAN_THANH, 0 XUAT_THANH_PHAM
            FROM INT_PS_1_TK_1_DT0_DT1_C(:P_COMPANY, '154', :OBJECT_MAY_GC, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, OFFICIAL_SUM_OF_MONEY NHAP_GC, 0 XUAT_HOAN_THANH, 0 XUAT_THANH_PHAM
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '155', :OBJECT_MAY_GC, '154', :OBJECT_MAY_GC, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 NHAP_GC, OFFICIAL_SUM_OF_MONEY XUAT_HOAN_THANH, 0 XUAT_THANH_PHAM
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '154', :OBJECT_HOAN_THANH, '154', :OBJECT_MAY_GC, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 NHAP_GC, 0 XUAT_HOAN_THANH, OFFICIAL_SUM_OF_MONEY XUAT_THANH_PHAM
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '632', NULL, '155', :OBJECT_MAY_GC, :P_TU_NGAY, :P_DEN_NGAY)
            
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = A.OBJECT1
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        GROUP BY OBJECT1, CODE, NAME, PROTONS.ORDINAL
        ORDER BY PROTONS.ORDINAL
        INTO :CODE, :NAME, :TON_DAU_KY, :NHAP, :NHAP_GC, :XUAT_HOAN_THANH, :XUAT_THANH_PHAM
    DO
    BEGIN
        TONG_CONG = TON_DAU_KY + NHAP_GC;
        TON_CUOI_KY = TONG_CONG - XUAT_THANH_PHAM;

        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_VND = ROUND(TON_CUOI_KY/SL_TON_CUOI_KY);

        SUM_TON_DAU_KY = SUM_TON_DAU_KY + TON_DAU_KY;
        SUM_NHAP = SUM_NHAP + NHAP;
        SUM_NHAP_GC = SUM_NHAP_GC + NHAP_GC;
        SUM_TONG_CONG = SUM_TONG_CONG + TONG_CONG;
        SUM_XUAT_HOAN_THANH = SUM_XUAT_HOAN_THANH + XUAT_HOAN_THANH;
        SUM_XUAT_THANH_PHAM = SUM_XUAT_THANH_PHAM + XUAT_THANH_PHAM;
        SUM_TON_CUOI_KY = SUM_TON_CUOI_KY + TON_CUOI_KY;

        IF(P_SL_TON_DAU_KY <> 0)THEN GIA_THANH_DAU_KY = ROUND(SUM_TON_DAU_KY/P_SL_TON_DAU_KY, 0);
        IF(P_SL_NHAP_KHO_TRONG_KY <> 0)THEN GIA_THANH_NHAP = ROUND(SUM_NHAP/P_SL_NHAP_KHO_TRONG_KY, 0);
        IF(SL_NHAP_GC <> 0)THEN GIA_THANH_NHAP_GC = ROUND(SUM_NHAP_GC/SL_NHAP_GC, 0);
        IF(SL_TONG_CONG_TON_NHAP <> 0)THEN GIA_THANH_TONG_CONG = ROUND(SUM_TONG_CONG/SL_TONG_CONG_TON_NHAP, 0);
        IF(P_SL_XUAT_TRONG_KY_HOAN_THANH <> 0 AND SUM_XUAT_HOAN_THANH <> 0)THEN GIA_THANH_XUAT_HOAN_THANH = ROUND(SUM_XUAT_HOAN_THANH/P_SL_XUAT_TRONG_KY_HOAN_THANH, 0);
        IF(P_SL_XUAT_TRONG_KY_THANH_PHAM <> 0 AND SUM_XUAT_THANH_PHAM <> 0)THEN GIA_THANH_XUAT_THANH_PHAM = ROUND(SUM_XUAT_THANH_PHAM/P_SL_XUAT_TRONG_KY_THANH_PHAM, 0);
        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_TON_CUOI_KY = ROUND(SUM_TON_CUOI_KY/SL_TON_CUOI_KY, 0);

        IF(P_EXCHANGE_RATE <> 0)THEN
        BEGIN
            GIA_THANH_USD = ROUND(GIA_THANH_VND/P_EXCHANGE_RATE, 2);
            GIA_THANH_NHAP_USD = ROUND(GIA_THANH_NHAP/P_EXCHANGE_RATE, 2);
            GIA_THANH_NHAP_GC_USD = ROUND(GIA_THANH_NHAP_GC/P_EXCHANGE_RATE, 2);
            GIA_THANH_TONG_CONG_USD = ROUND(GIA_THANH_TONG_CONG/P_EXCHANGE_RATE, 2);
            GIA_THANH_XUAT_HOAN_THANH_USD = ROUND(GIA_THANH_XUAT_HOAN_THANH/P_EXCHANGE_RATE, 2);
            GIA_THANH_XUAT_THANH_PHAM_USD = ROUND(GIA_THANH_XUAT_THANH_PHAM/P_EXCHANGE_RATE, 2);
            GIA_THANH_TON_CUOI_KY_USD = ROUND(GIA_THANH_TON_CUOI_KY/P_EXCHANGE_RATE, 2);
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_TINH_GIA_THANH_MAY_KTG (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_SL_TON_DAU_KY DM_DOUBLE,
P_SL_NHAP_KHO_TRONG_KY DM_DOUBLE,
P_SL_XUAT_TRONG_KY_HOAN_THANH DM_DOUBLE,
P_SL_XUAT_155_MAY_KTG DM_DOUBLE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SL_TON_CUOI_KY DM_DOUBLE,
CODE DM_CODE,
NAME DM_NAME,
TON_DAU_KY DM_DOUBLE,
NHAP DM_DOUBLE,
TONG_CONG DM_DOUBLE,
XUAT DM_DOUBLE,
XUAT_155_MAY_KTG DM_DOUBLE,
TON_CUOI_KY DM_DOUBLE,
GIA_THANH_VND DM_DOUBLE,
GIA_THANH_USD DM_DOUBLE,
GIA_THANH_DAU_KY DM_DOUBLE,
GIA_THANH_NHAP DM_DOUBLE,
GIA_THANH_NHAP_USD DM_DOUBLE,
GIA_THANH_TONG_CONG DM_DOUBLE,
GIA_THANH_TONG_CONG_USD DM_DOUBLE,
GIA_THANH_XUAT DM_DOUBLE,
GIA_THANH_XUAT_USD DM_DOUBLE,
GIA_THANH_XUAT_155_MAY_KTG DM_DOUBLE,
GIA_THANH_XUAT_155_MAY_KTG_USD DM_DOUBLE,
GIA_THANH_TON_CUOI_KY DM_DOUBLE,
GIA_THANH_TON_CUOI_KY_USD DM_DOUBLE)
AS 
DECLARE VARIABLE OBJECT_MAY_KTG DM_ID;
DECLARE VARIABLE SL_TONG_CONG_TON_PHAT_SINH DM_DOUBLE;
DECLARE VARIABLE SUM_TON_DAU_KY DM_DOUBLE;
DECLARE VARIABLE SUM_PHAT_SINH_TRONG_KY DM_DOUBLE;
DECLARE VARIABLE SUM_TONG_CONG DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT_155_MAY_KTG DM_DOUBLE;
DECLARE VARIABLE SUM_TON_CUOI_KY DM_DOUBLE;
BEGIN
    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'MAY KTG'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_MAY_KTG;

    IF(P_SL_TON_DAU_KY IS NULL)THEN P_SL_TON_DAU_KY = 0;
    IF(P_SL_NHAP_KHO_TRONG_KY IS NULL)THEN P_SL_NHAP_KHO_TRONG_KY = 0;
    IF(P_SL_XUAT_TRONG_KY_HOAN_THANH IS NULL)THEN P_SL_XUAT_TRONG_KY_HOAN_THANH = 0;
    IF(P_SL_XUAT_155_MAY_KTG IS NULL)THEN P_SL_XUAT_155_MAY_KTG = 0;

    SL_TONG_CONG_TON_PHAT_SINH = P_SL_TON_DAU_KY + P_SL_NHAP_KHO_TRONG_KY;

    SL_TON_CUOI_KY = SL_TONG_CONG_TON_PHAT_SINH - P_SL_XUAT_TRONG_KY_HOAN_THANH - P_SL_XUAT_155_MAY_KTG;

    SUM_TON_DAU_KY = 0;
    SUM_PHAT_SINH_TRONG_KY = 0;
    SUM_TONG_CONG = 0;
    SUM_XUAT = 0;
    SUM_XUAT_155_MAY_KTG = 0;

    FOR
        SELECT CODE, NAME, SUM(TON_DAU_KY), SUM(PHAT_SINH_TRONG_KY), SUM(XUAT), SUM(XUAT_155_MAY_KTG)
        FROM
        (
            SELECT OBJECT1, DEBIT-CREDIT TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 XUAT, 0 XUAT_155_MAY_KTG
            FROM INT_SD_1_TK_1_DT0_DT1_DN_C(:P_COMPANY, '154', :OBJECT_MAY_KTG, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, DEBIT PHAT_SINH_TRONG_KY, 0 XUAT, 0 XUAT_155_MAY_KTG
            FROM INT_PS_1_TK_1_DT0_DT1_C(:P_COMPANY, '154', :OBJECT_MAY_KTG, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, OFFICIAL_SUM_OF_MONEY XUAT, 0 XUAT_155_MAY_KTG
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '154', NULL, '154', :OBJECT_MAY_KTG, :P_TU_NGAY, :P_DEN_NGAY)

            UNION ALL

            
            SELECT OBJECT1, 0 TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 XUAT, OFFICIAL_SUM_OF_MONEY XUAT_155_MAY_KTG
            FROM INT_PS_CAP_TK_DT0_CO_DT1_C(:P_COMPANY, '155', NULL, '154', :OBJECT_MAY_KTG, :P_TU_NGAY, :P_DEN_NGAY)
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = A.OBJECT1
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        GROUP BY OBJECT1, CODE, NAME, PROTONS.ORDINAL
        ORDER BY PROTONS.ORDINAL
        INTO :CODE, :NAME, :TON_DAU_KY, :NHAP, :XUAT, :XUAT_155_MAY_KTG
    DO
    BEGIN
        TONG_CONG = TON_DAU_KY + NHAP;
        TON_CUOI_KY = TONG_CONG - XUAT - XUAT_155_MAY_KTG;

        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_VND = ROUND(TON_CUOI_KY/SL_TON_CUOI_KY);

        SUM_TON_DAU_KY = SUM_TON_DAU_KY + TON_DAU_KY;
        SUM_PHAT_SINH_TRONG_KY = SUM_PHAT_SINH_TRONG_KY + NHAP;
        SUM_TONG_CONG = SUM_TONG_CONG + TONG_CONG;
        SUM_XUAT = SUM_XUAT + XUAT;
        SUM_XUAT_155_MAY_KTG = SUM_XUAT_155_MAY_KTG + XUAT_155_MAY_KTG;
        SUM_TON_CUOI_KY = SUM_TON_CUOI_KY + TON_CUOI_KY;

        IF(P_SL_TON_DAU_KY <> 0)THEN GIA_THANH_DAU_KY = ROUND(SUM_TON_DAU_KY/P_SL_TON_DAU_KY, 0);
        IF(P_SL_NHAP_KHO_TRONG_KY <> 0)THEN GIA_THANH_NHAP = ROUND(SUM_PHAT_SINH_TRONG_KY/P_SL_NHAP_KHO_TRONG_KY, 0);
        IF(SL_TONG_CONG_TON_PHAT_SINH <> 0)THEN GIA_THANH_TONG_CONG = ROUND(SUM_TONG_CONG/SL_TONG_CONG_TON_PHAT_SINH, 0);

        IF(P_SL_XUAT_TRONG_KY_HOAN_THANH <> 0 AND SUM_XUAT <> 0)THEN GIA_THANH_XUAT = ROUND(SUM_XUAT/P_SL_XUAT_TRONG_KY_HOAN_THANH, 0);
        IF(P_SL_XUAT_155_MAY_KTG <> 0 AND SUM_XUAT_155_MAY_KTG <> 0)THEN GIA_THANH_XUAT_155_MAY_KTG = ROUND(SUM_XUAT_155_MAY_KTG/P_SL_XUAT_155_MAY_KTG, 0);
        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_TON_CUOI_KY = ROUND(SUM_TON_CUOI_KY/SL_TON_CUOI_KY, 0);

        IF(P_EXCHANGE_RATE <> 0)THEN
        BEGIN
            GIA_THANH_USD = ROUND(GIA_THANH_VND/P_EXCHANGE_RATE, 2);
            GIA_THANH_NHAP_USD = ROUND(GIA_THANH_NHAP/P_EXCHANGE_RATE, 2);
            GIA_THANH_TONG_CONG_USD = ROUND(GIA_THANH_TONG_CONG/P_EXCHANGE_RATE, 2);
            GIA_THANH_XUAT_USD = ROUND(GIA_THANH_XUAT/P_EXCHANGE_RATE, 2);
            GIA_THANH_XUAT_155_MAY_KTG_USD = ROUND(GIA_THANH_XUAT_155_MAY_KTG/P_EXCHANGE_RATE, 2);
            GIA_THANH_TON_CUOI_KY_USD = ROUND(GIA_THANH_TON_CUOI_KY/P_EXCHANGE_RATE, 2);
        END

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_TINH_GIA_THANH_PHAM_GC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_SL_TON_DAU_KY DM_DOUBLE,
P_SL_NHAP DM_DOUBLE,
P_SL_XUAT DM_DOUBLE,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (SL_TON_CUOI_KY DM_DOUBLE,
CODE DM_CODE,
NAME DM_NAME,
TON_DAU_KY DM_DOUBLE,
NHAP DM_DOUBLE,
TONG_CONG DM_DOUBLE,
XUAT DM_DOUBLE,
TON_CUOI_KY DM_DOUBLE,
GIA_THANH_VND DM_DOUBLE,
GIA_THANH_USD DM_DOUBLE,
GIA_THANH_DAU_KY DM_DOUBLE,
GIA_THANH_NHAP DM_DOUBLE,
GIA_THANH_NHAP_USD DM_DOUBLE,
GIA_THANH_XUAT DM_DOUBLE,
GIA_THANH_XUAT_USD DM_DOUBLE,
GIA_THANH_TONG_CONG DM_DOUBLE,
GIA_THANH_TONG_CONG_USD DM_DOUBLE,
GIA_THANH_TON_CUOI_KY DM_DOUBLE,
GIA_THANH_TON_CUOI_KY_USD DM_DOUBLE)
AS 
DECLARE VARIABLE SL_TONG_CONG_TON_NHAP DM_DOUBLE;
DECLARE VARIABLE SUM_TON_DAU_KY DM_DOUBLE;
DECLARE VARIABLE SUM_NHAP DM_DOUBLE;
DECLARE VARIABLE SUM_TONG_CONG DM_DOUBLE;
DECLARE VARIABLE SUM_XUAT DM_DOUBLE;
DECLARE VARIABLE SUM_TON_CUOI_KY DM_DOUBLE;
DECLARE VARIABLE OBJECT_HT_GC DM_ID;
BEGIN
    SELECT PHASES.ID
    FROM PHASES
    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = PHASES.ID AND ATOMS.CODE = 'HT-GC'
    WHERE PHASES.COMPANY = :P_COMPANY
    INTO :OBJECT_HT_GC;

    IF(P_SL_TON_DAU_KY IS NULL)THEN P_SL_TON_DAU_KY = 0;
    IF(P_SL_NHAP IS NULL)THEN P_SL_NHAP = 0;
    IF(P_SL_XUAT IS NULL)THEN P_SL_XUAT = 0;

    SL_TONG_CONG_TON_NHAP = P_SL_TON_DAU_KY + P_SL_NHAP;

    SL_TON_CUOI_KY = SL_TONG_CONG_TON_NHAP - P_SL_XUAT;

    SUM_TON_DAU_KY = 0;
    SUM_NHAP = 0;
    SUM_TONG_CONG = 0;
    SUM_XUAT = 0;
    SUM_TON_CUOI_KY = 0;

    FOR
        SELECT CODE, NAME, SUM(TON_DAU_KY), SUM(PHAT_SINH_TRONG_KY), SUM(XUAT)
        FROM
        (
            SELECT OBJECT1, DEBIT-CREDIT TON_DAU_KY, 0 PHAT_SINH_TRONG_KY, 0 XUAT
            FROM INT_SD_1_TK_1_DT0_DT1_DN_C(:P_COMPANY, '155', :OBJECT_HT_GC, :P_TU_NGAY)

            UNION ALL

            SELECT OBJECT1, 0 TON_DAU_KY, DEBIT PHAT_SINH_TRONG_KY, CREDIT XUAT
            FROM INT_PS_1_TK_1_DT0_DT1_C(:P_COMPANY, '155', :OBJECT_HT_GC, :P_TU_NGAY, :P_DEN_NGAY)
        ) A
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = A.OBJECT1
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
        GROUP BY OBJECT1, CODE, NAME, PROTONS.ORDINAL
        ORDER BY PROTONS.ORDINAL
        INTO :CODE, :NAME, :TON_DAU_KY, :NHAP, :XUAT
    DO
    BEGIN
        TONG_CONG = TON_DAU_KY + NHAP;
        TON_CUOI_KY = TONG_CONG - XUAT;

        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_VND = ROUND(TON_CUOI_KY/SL_TON_CUOI_KY);

        SUM_TON_DAU_KY = SUM_TON_DAU_KY + TON_DAU_KY;
        SUM_NHAP = SUM_NHAP + NHAP;
        SUM_TONG_CONG = SUM_TONG_CONG + TONG_CONG;
        SUM_XUAT = SUM_XUAT + XUAT;
        SUM_TON_CUOI_KY = SUM_TON_CUOI_KY + TON_CUOI_KY;

        IF(P_SL_TON_DAU_KY <> 0)THEN GIA_THANH_DAU_KY = ROUND(SUM_TON_DAU_KY/P_SL_TON_DAU_KY, 0);
        IF(P_SL_NHAP <> 0)THEN GIA_THANH_NHAP = ROUND(SUM_NHAP/P_SL_NHAP, 0);
        IF(SL_TONG_CONG_TON_NHAP <> 0)THEN GIA_THANH_TONG_CONG = ROUND(SUM_TONG_CONG/SL_TONG_CONG_TON_NHAP, 0);
        IF(P_SL_XUAT <> 0 AND SUM_XUAT <> 0)THEN GIA_THANH_XUAT = ROUND(SUM_XUAT/P_SL_XUAT, 0);
        IF(SL_TON_CUOI_KY <> 0)THEN GIA_THANH_TON_CUOI_KY = ROUND(SUM_TON_CUOI_KY/SL_TON_CUOI_KY, 0);

        IF(P_EXCHANGE_RATE <> 0)THEN
        BEGIN
            GIA_THANH_USD = ROUND(GIA_THANH_VND/P_EXCHANGE_RATE, 2);
            GIA_THANH_NHAP_USD = ROUND(GIA_THANH_NHAP/P_EXCHANGE_RATE, 2);
            GIA_THANH_TONG_CONG_USD = ROUND(GIA_THANH_TONG_CONG/P_EXCHANGE_RATE, 2);
            GIA_THANH_XUAT_USD = ROUND(GIA_THANH_XUAT/P_EXCHANGE_RATE, 2);
            GIA_THANH_TON_CUOI_KY_USD = ROUND(GIA_THANH_TON_CUOI_KY/P_EXCHANGE_RATE, 2);
        END

        SUSPEND;
    END
END ^

