ALTER PROCEDURE RPT_TMBCTC133_I (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT,
NAME_CONTENT DM_CONTENT)
AS 
DECLARE VARIABLE TMBCTC DM_ID;
DECLARE VARIABLE GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER;
DECLARE VARIABLE GROUP_IN_REPORT DM_CODE;
BEGIN
    GROUP_IN_DESIGNER = 0;
    GROUP_IN_REPORT = 'I';

    SELECT FIRST 1 TMBCTC.ID
    FROM TMBCTC
    WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.FROM_DATE = :P_TU_NGAY AND TMBCTC.TO_DATE = :P_DEN_NGAY
    INTO :TMBCTC;
    
    

    FOR
        SELECT A.NAME, A.CONTENT
        FROM
        (
            SELECT FINANCIAL_REPORT_ITEM, NAME, CONTENT
            FROM TMBCTC_THONG_TIN_CHUNG
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_THONG_TIN_CHUNG.ID AND TMBCTC_BASE.TMBCTC = :TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND FINANCIAL_REPORTS.GROUP_IN_REPORT = :GROUP_IN_REPORT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_THONG_TIN_CHUNG.COMPANY = :P_COMPANY

            UNION ALL

            SELECT FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, NAME, DEFAULT_STRING CONTENT
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_THONG_TIN_CHUNG
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_THONG_TIN_CHUNG.ID AND TMBCTC_BASE.TMBCTC = :TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_THONG_TIN_CHUNG.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :TMBCTC AND FINANCIAL_REPORTS.GROUP_IN_REPORT = :GROUP_IN_REPORT
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :FINANCIAL_REPORT_ITEM_NAME, CONTENT
    DO
    BEGIN
        IF(CONTENT IS NULL)THEN
            NAME_CONTENT = FINANCIAL_REPORT_ITEM_NAME;
        ELSE
            NAME_CONTENT = FINANCIAL_REPORT_ITEM_NAME || ' ' || CONTENT;

        SUSPEND;
    END
END ^

