ALTER PROCEDURE RPT_TMBCTC48_I (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
