NAME_CONTENT DM_CONTENT,
QUYEN_SU_DUNG_DAT DM_DOUBLE,
QUYEN_PHAT_HANH DM_DOUBLE,
BAN_QUYEN_BANG_SANG_CHE DM_DOUBLE,
NHAN_HIEU_HANG_HOA DM_DOUBLE,
PHAN_MEM_MAY_TINH DM_DOUBLE,
GIAY_PHEP_NHUONG_QUYEN DM_DOUBLE,
TSCD_VO_HINH_KHAC DM_DOUBLE,
TONG_CONG DM_DOUBLE)
AS 
DECLARE VARIABLE TMBCTC DM_ID;
DECLARE VARIABLE GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER;
DECLARE VARIABLE GROUP_IN_REPORT DM_CODE;
BEGIN
    GROUP_IN_DESIGNER = 0;
    GROUP_IN_REPORT = 'III-4-1';

    SELECT FIRST 1 TMBCTC.ID
    FROM TMBCTC
    WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.FROM_DATE = :P_TU_NGAY AND TMBCTC.TO_DATE = :P_DEN_NGAY
    INTO :TMBCTC;
    
    

    FOR
        SELECT A.NAME, A.CONTENT,
            QUYEN_SU_DUNG_DAT, QUYEN_PHAT_HANH, BAN_QUYEN_BANG_SANG_CHE, NHAN_HIEU_HANG_HOA, PHAN_MEM_MAY_TINH, GIAY_PHEP_NHUONG_QUYEN, TSCD_VO_HINH_KHAC, TONG_CONG
        FROM
        (
            SELECT FINANCIAL_REPORT_ITEM, NAME, CONTENT,
                QUYEN_SU_DUNG_DAT, QUYEN_PHAT_HANH, BAN_QUYEN_BANG_SANG_CHE, NHAN_HIEU_HANG_HOA, PHAN_MEM_MAY_TINH, GIAY_PHEP_NHUONG_QUYEN, TSCD_VO_HINH_KHAC, TONG_CONG
            FROM TMBCTC_TSCD_VH
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_VH.ID AND TMBCTC_BASE.TMBCTC = :TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND FINANCIAL_REPORTS.GROUP_IN_REPORT = :GROUP_IN_REPORT
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_TSCD_VH.COMPANY = :P_COMPANY

            UNION ALL

            SELECT FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, NAME, NULL CONTENT,
                0 QUYEN_SU_DUNG_DAT, 0 QUYEN_PHAT_HANH, 0 BAN_QUYEN_BANG_SANG_CHE, 0 NHAN_HIEU_HANG_HOA, 0 PHAN_MEM_MAY_TINH, 0 GIAY_PHEP_NHUONG_QUYEN, 0 TSCD_VO_HINH_KHAC, 0 TONG_CONG
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT FINANCIAL_REPORT_ITEM
                FROM TMBCTC_TSCD_VH
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_VH.ID AND TMBCTC_BASE.TMBCTC = :TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_TSCD_VH.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :TMBCTC AND FINANCIAL_REPORTS.GROUP_IN_REPORT = :GROUP_IN_REPORT
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :FINANCIAL_REPORT_ITEM_NAME, CONTENT,
            :QUYEN_SU_DUNG_DAT, :QUYEN_PHAT_HANH, :BAN_QUYEN_BANG_SANG_CHE, :NHAN_HIEU_HANG_HOA, :PHAN_MEM_MAY_TINH, :GIAY_PHEP_NHUONG_QUYEN, :TSCD_VO_HINH_KHAC, :TONG_CONG
    DO
    BEGIN
        IF(QUYEN_SU_DUNG_DAT = 0)THEN QUYEN_SU_DUNG_DAT = NULL;
        IF(QUYEN_PHAT_HANH = 0)THEN QUYEN_PHAT_HANH = NULL;
        IF(BAN_QUYEN_BANG_SANG_CHE = 0)THEN BAN_QUYEN_BANG_SANG_CHE = NULL;
        IF(NHAN_HIEU_HANG_HOA = 0)THEN NHAN_HIEU_HANG_HOA = NULL;
        IF(PHAN_MEM_MAY_TINH = 0)THEN PHAN_MEM_MAY_TINH = NULL;
        IF(GIAY_PHEP_NHUONG_QUYEN = 0)THEN GIAY_PHEP_NHUONG_QUYEN = NULL;
        IF(TSCD_VO_HINH_KHAC = 0)THEN TSCD_VO_HINH_KHAC = NULL;
        IF(TONG_CONG = 0)THEN TONG_CONG = NULL;

        IF(CONTENT IS NULL)THEN
            NAME_CONTENT = FINANCIAL_REPORT_ITEM_NAME;
        ELSE
            NAME_CONTENT = FINANCIAL_REPORT_ITEM_NAME || ' ' || CONTENT;

        SUSPEND;
    END
END ^

