            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :TMBCTC AND FINANCIAL_REPORTS.GROUP_IN_REPORT = :GROUP_IN_REPORT
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :FINANCIAL_REPORT_ITEM_NAME, CONTENT, :CUOI_NAM, :DAU_NAM
    DO
    BEGIN
        IF(CUOI_NAM = 0)THEN CUOI_NAM = NULL;
        IF(DAU_NAM = 0)THEN DAU_NAM = NULL;

        IF(CONTENT IS NULL)THEN
            NAME_CONTENT = FINANCIAL_REPORT_ITEM_NAME;
        ELSE
            NAME_CONTENT = FINANCIAL_REPORT_ITEM_NAME || ' ' || CONTENT;

        SUSPEND;
    END
END ^

ALTER PROCEDURE RPT_TONG_HOP_DT0_CO_CAP_TK (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_DEBITACCOUNT DM_ID,
P_DEBIT_OBJECT0 DM_ID,
P_DEBIT_OBJECT1 DM_ID,
P_CREDITACCOUNT DM_ID,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (OBJECT0_ID DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT0_NAME DM_NAME,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
RISING DM_DOUBLE)
AS 
DECLARE VARIABLE PARENT_DEBIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE PARENT_CREDIT_ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE HAS_VALUE DM_BOOL;
BEGIN
    HAS_VALUE = 0;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_DEBITACCOUNT
    INTO :PARENT_DEBIT_ACCOUNT_CODE;

    SELECT CODE
    FROM ATOMS
    WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_CREDITACCOUNT
    INTO :PARENT_CREDIT_ACCOUNT_CODE;

    FOR
        SELECT CREDIT.OBJECT0, CREDIT_OBJECTS.CODE, ATOM_STRINGS.NAME,
            SUM(DEBIT.AMOUNT), SUM(DEBIT.OFFICIAL_SUM_OF_MONEY)
        FROM ENTRIES
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID AND INPUT_DATE BETWEEN :P_TU_NGAY AND :P_DEN_NGAY
        JOIN CREDIT_DEBIT DEBIT ON DEBIT.COMPANY = :P_COMPANY AND DEBIT.ENTRY = ENTRIES.ID AND DEBIT.SIDE = 0 AND
            (:P_DEBIT_OBJECT0 IS NULL OR DEBIT.OBJECT0 = :P_DEBIT_OBJECT0) AND (:P_DEBIT_OBJECT1 IS NULL OR DEBIT.OBJECT1 = :P_DEBIT_OBJECT1)
        JOIN ACCOUNTS DEBIT_ACCOUNT ON DEBIT_ACCOUNT.COMPANY = :P_COMPANY AND DEBIT_ACCOUNT.ID = DEBIT.ACCOUNT
        JOIN ATOMS DEBIT_ATOM ON DEBIT_ATOM.COMPANY = :P_COMPANY AND DEBIT_ATOM.ID = DEBIT_ACCOUNT.ID AND DEBIT_ATOM.CODE STARTING WITH :PARENT_DEBIT_ACCOUNT_CODE
        JOIN CREDIT_DEBIT CREDIT ON CREDIT.COMPANY = :P_COMPANY AND CREDIT.ENTRY = ENTRIES.ID AND CREDIT.SIDE = 1
        JOIN ACCOUNTS CREDIT_ACCOUNT ON CREDIT_ACCOUNT.COMPANY = :P_COMPANY AND CREDIT_ACCOUNT.ID = CREDIT.ACCOUNT
        JOIN ATOMS CREDIT_ATOM ON CREDIT_ATOM.COMPANY = :P_COMPANY AND CREDIT_ATOM.ID = CREDIT_ACCOUNT.ID AND CREDIT_ATOM.CODE STARTING WITH :PARENT_CREDIT_ACCOUNT_CODE
        JOIN ATOMS CREDIT_OBJECTS ON CREDIT_OBJECTS.COMPANY = :P_COMPANY AND CREDIT_OBJECTS.ID = CREDIT.OBJECT0
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = CREDIT_OBJECTS.ID
        WHERE ENTRIES.COMPANY = :P_COMPANY
        GROUP BY CREDIT.OBJECT0, CREDIT_OBJECTS.CODE, ATOM_STRINGS.NAME
        ORDER BY CREDIT_OBJECTS.CODE
        INTO :OBJECT0_ID, :OBJECT0_CODE, :OBJECT0_NAME,
        :AMOUNT, :RISING
    DO
    BEGIN
        IF(AMOUNT > 0)THEN
            PRICE = ROUND(RISING/AMOUNT);
        ELSE
            PRICE = 0;

        HAS_VALUE = 1;
        SUSPEND;
    END

    IF(HAS_VALUE = 0)THEN
    BEGIN
        SELECT CONTENT
        FROM TEXTS
        WHERE TEXTS.ID = 1 AND TEXTS.LANGUAGE = :P_LANGUAGE
        INTO :OBJECT0_NAME;

        SUSPEND;
    END
END ^

