ALTER PROCEDURE SERVICE_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID,  :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO SERVICES(COMPANY, ID) VALUES(:P_COMPANY, :P_ID);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE SERVICE_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
RELATED_OBJECT DM_ID)
AS 
BEGIN
  FOR
  SELECT SERVICES.ID,ORDINAL, NOTE, CODE, NAME, HIDE, PARENT, TEAM, RELATED_OBJECT
  FROM SERVICES
  JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = SERVICES.ID
  JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
  JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = ATOMS.ID
  JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
  WHERE SERVICES.COMPANY = :P_COMPANY
  INTO :ID, :ORDINAL, :NOTE, :CODE, :NAME, :HIDE, :PARENT, :TEAM, :RELATED_OBJECT
  DO
    SUSPEND;
END ^

ALTER PROCEDURE SERVICE_TEAM_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    EXECUTE PROCEDURE TEAM_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME, :P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO SERVICE_TEAMS(ID, COMPANY) VALUES(:P_ID, :P_COMPANY);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

ALTER PROCEDURE SERVICE_TEAM_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
ORDINAL DM_INTEGER,
NOTE DM_NOTE,
CODE DM_CODE,
NAME DM_NAME,
HIDE DM_BOOL,
PARENT DM_ID,
TEAM DM_ID,
