ALTER PROCEDURE SETTING_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_BACKUP_ACTION_OPTION DM_BACKUP_ACTION_OPTION,
P_BACKUP_DIRECTORY DM_DIRECTORY,
P_BACKUP_FILE_OPTION DM_BACKUP_FILE_OPTION,
P_NUMBER_DECIMAL_DIGITS DM_INTEGER,
P_PERCENT_DECIMAL_DIGITS DM_INTEGER,
P_OTHERS DM_SETTINGS,
P_ENABLE_LOG DM_BOOL,
P_NUMBER_OF_DAYS_STORED DM_INTEGER)
AS 
BEGIN
    EXECUTE PROCEDURE PROTON_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL);

    UPDATE OR INSERT INTO SETTINGS(ID, COMPANY, NUMBER_DECIMAL_DIGITS, PERCENT_DECIMAL_DIGITS, OTHERS, ENABLE_LOG, NUMBER_OF_DAYS_STORED)
    VALUES(:P_ID, :P_COMPANY, :P_NUMBER_DECIMAL_DIGITS, :P_PERCENT_DECIMAL_DIGITS, :P_OTHERS, :P_ENABLE_LOG, :P_NUMBER_OF_DAYS_STORED);

    UPDATE OR INSERT INTO CONFIGURATION(ID, BACKUP_ACTION_OPTION, BACKUP_DIRECTORY, BACKUP_FILE_OPTION)
    VALUES(0, :P_BACKUP_ACTION_OPTION, :P_BACKUP_DIRECTORY, :P_BACKUP_FILE_OPTION);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE SETTING_S_BACKUP_INFO RETURNS (BACKUP_DIRECTORY DM_DIRECTORY,
BACKUP_FILE_OPTION DM_BACKUP_FILE_OPTION,
SERVER_DATE DM_DATE)
AS 
BEGIN
    SELECT BACKUP_DIRECTORY, BACKUP_FILE_OPTION
    FROM CONFIGURATION
    INTO :BACKUP_DIRECTORY, :BACKUP_FILE_OPTION;

    SERVER_DATE = CURRENT_DATE;

    SUSPEND;
END ^

ALTER PROCEDURE SETTING_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
BACKUP_ACTION_OPTION DM_BACKUP_ACTION_OPTION,
BACKUP_DIRECTORY DM_DIRECTORY,
BACKUP_FILE_OPTION DM_BACKUP_FILE_OPTION,
NUMBER_DECIMAL_DIGITS DM_INTEGER,
PERCENT_DECIMAL_DIGITS DM_INTEGER,
OTHERS DM_SETTINGS,
ENABLE_LOG DM_BOOL,
NUMBER_OF_DAYS_STORED DM_INTEGER)
AS 
BEGIN
    SELECT SETTINGS.ID, NOTE, ORDINAL, NUMBER_DECIMAL_DIGITS, PERCENT_DECIMAL_DIGITS, OTHERS, ENABLE_LOG, NUMBER_OF_DAYS_STORED
    FROM SETTINGS
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = SETTINGS.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :ID, :NOTE, :ORDINAL, :NUMBER_DECIMAL_DIGITS, :PERCENT_DECIMAL_DIGITS, :OTHERS, :ENABLE_LOG, :NUMBER_OF_DAYS_STORED;

    SELECT BACKUP_ACTION_OPTION, BACKUP_DIRECTORY, BACKUP_FILE_OPTION
    FROM CONFIGURATION
    INTO :BACKUP_ACTION_OPTION, :BACKUP_DIRECTORY, :BACKUP_FILE_OPTION;

    SUSPEND;
END ^

ALTER PROCEDURE SETTING_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID)
RETURNS (NUMBER_DECIMAL_DIGITS DM_INTEGER,
PERCENT_DECIMAL_DIGITS DM_INTEGER,
OTHERS DM_SETTINGS,
ENABLE_LOG DM_BOOL,
BACKUP_ACTION_OPTION DM_BACKUP_ACTION_OPTION)
AS 
BEGIN
    SELECT NUMBER_DECIMAL_DIGITS, PERCENT_DECIMAL_DIGITS, OTHERS, ENABLE_LOG
    FROM SETTINGS
    WHERE SETTINGS.COMPANY = :P_COMPANY
    INTO :NUMBER_DECIMAL_DIGITS, :PERCENT_DECIMAL_DIGITS, :OTHERS, :ENABLE_LOG;

    SELECT BACKUP_ACTION_OPTION
    FROM CONFIGURATION
    INTO :BACKUP_ACTION_OPTION;

    IF(BACKUP_ACTION_OPTION IS NULL)THEN BACKUP_ACTION_OPTION = 1;

    SUSPEND;
END ^

ALTER PROCEDURE SINGLE_ENTRY_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CURRENCY DM_ID,
P_DOCUMENT DM_ID,
P_EXCHANGE_RATE DM_DOUBLE,
P_CONTENT DM_CONTENT,
P_CREDIT_DEBIT_ID DM_ID,
P_ACCOUNT DM_ID,
P_OBJECT0 DM_ID,
P_OBJECT1 DM_ID,
P_OBJECT2 DM_ID,
P_AMOUNT DM_DOUBLE,
P_PRICE DM_DOUBLE,
P_FOREIGN_SUM_OF_MONEY DM_DOUBLE,
P_OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
P_SIDE DM_SIDE)
AS 
BEGIN
    EXECUTE PROCEDURE ENTRY_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_CONTENT);

    UPDATE OR INSERT INTO ENTRIES(COMPANY, ID, DOCUMENT, CURRENCY, EXCHANGE_RATE, ENTRY_TYPE)
    VALUES(:P_COMPANY, :P_ID, :P_DOCUMENT, :P_CURRENCY, :P_EXCHANGE_RATE, 0);

    UPDATE OR INSERT INTO CREDIT_DEBIT(COMPANY, ID, ENTRY, SIDE, ACCOUNT, OBJECT0, OBJECT1, OBJECT2, AMOUNT, PRICE, FOREIGN_SUM_OF_MONEY, OFFICIAL_SUM_OF_MONEY)
    VALUES(:P_COMPANY, :P_CREDIT_DEBIT_ID, :P_ID, :P_SIDE, :P_ACCOUNT, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2, :P_AMOUNT, :P_PRICE, :P_FOREIGN_SUM_OF_MONEY, :P_OFFICIAL_SUM_OF_MONEY);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE SINGLE_ENTRY_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DOCUMENT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY DM_ID,
EXCHANGE_RATE DM_DOUBLE,
CONTENT DM_CONTENT,
CREDIT_DEBIT_ID DM_ID,
ACCOUNT DM_ID,
OBJECT0 DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT1 DM_ID,
OBJECT1_CODE DM_CODE,
OBJECT2 DM_ID,
OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
SIDE DM_SIDE)
AS 
BEGIN
FOR
   SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, ENTRY_BASE_STRINGS.CONTENT,
    CREDIT_DEBIT.ID, CREDIT_DEBIT.ACCOUNT, CREDIT_DEBIT.OBJECT0, CREDIT_DEBIT.OBJECT1, CREDIT_DEBIT.OBJECT2,
    CREDIT_DEBIT.AMOUNT, CREDIT_DEBIT.PRICE, CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY, CREDIT_DEBIT.SIDE
   FROM ENTRIES
   JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
   JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
   JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
   WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 0 AND ENTRIES.DOCUMENT = :P_DOCUMENT
   INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :CONTENT,
    :CREDIT_DEBIT_ID, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2,
    :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY, :SIDE
DO
BEGIN
    IF(OBJECT0 IS NULL)THEN
        OBJECT0_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
        INTO :OBJECT0_CODE;

    IF(OBJECT1 IS NULL)THEN
        OBJECT1_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
        INTO :OBJECT1_CODE;

    IF(OBJECT2 IS NULL)THEN
        OBJECT2_CODE = NULL;
    ELSE
        SELECT CODE
        FROM ATOMS
        WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
        INTO :OBJECT2_CODE;

    SUSPEND;
END
END ^

ALTER PROCEDURE SINGLE_ENTRY_S_RS (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TEAM DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY_CODE DM_CODE,
DOCUMENT DM_ID,
EXCHANGE_RATE DM_DOUBLE,
CONTENT DM_CONTENT,
SIDE DM_SIDE,
ACCOUNT_CODE DM_CODE,
OBJECT0_CODE DM_CODE,
OBJECT1_CODE DM_CODE,
OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE)
AS 
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
BEGIN
    FOR
        SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, ENTRY_BASE_STRINGS.CONTENT,
        CREDIT_DEBIT.SIDE, CREDIT_DEBIT.ACCOUNT, CREDIT_DEBIT.OBJECT0, CREDIT_DEBIT.OBJECT1, CREDIT_DEBIT.OBJECT2,
        CREDIT_DEBIT.AMOUNT, CREDIT_DEBIT.PRICE, CREDIT_DEBIT.FOREIGN_SUM_OF_MONEY, CREDIT_DEBIT.OFFICIAL_SUM_OF_MONEY,
        DOCUMENTS.ID, CODE || '-' || NUMBER, INPUT_DATE, ORIGINAL_VOUCHERS, VOUCHER_DATE
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = :P_COMPANY AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = :P_COMPANY AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID AND ENTRY_BASE_STRINGS.LANGUAGE = :P_LANGUAGE
        JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = :P_COMPANY AND DOCUMENTS.ID = ENTRIES.DOCUMENT AND DOCUMENTS.INPUT_DATE BETWEEN :P_FROM_DATE AND :P_TO_DATE AND DOCUMENTS.TEAM = :P_TEAM
        WHERE ENTRIES.COMPANY = :P_COMPANY AND ENTRIES.ENTRY_TYPE = 0
        INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :CONTENT,
        :SIDE, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2,
        :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DOCUMENT, :CODE, :INPUT_DATE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CURRENCY
        INTO :CURRENCY_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :ACCOUNT
        INTO :ACCOUNT_CODE;

        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :OBJECT0
            INTO :OBJECT0_CODE;

        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :OBJECT1
            INTO :OBJECT1_CODE;

        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :OBJECT2
            INTO :OBJECT2_CODE;

        SUSPEND;
    END
END ^

