ALTER PROCEDURE SINGLE_ENTRY_S_SEARCH (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_WHERE DM_STRING)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
CURRENCY_CODE DM_CODE,
DOCUMENT DM_ID,
EXCHANGE_RATE DM_DOUBLE,
CONTENT DM_CONTENT,
SIDE DM_SIDE,
ACCOUNT_CODE DM_CODE,
OBJECT0_CODE DM_CODE,
OBJECT1_CODE DM_CODE,
OBJECT2_CODE DM_CODE,
AMOUNT DM_DOUBLE,
PRICE DM_DOUBLE,
FOREIGN_SUM_OF_MONEY DM_DOUBLE,
OFFICIAL_SUM_OF_MONEY DM_DOUBLE,
CODE DM_DOCUMENT_CODE,
INPUT_DATE DM_DATE,
ORIGINAL_VOUCHERS DM_ORIGINAL_VOUCHERS,
VOUCHER_DATE DM_DATE)
AS 
DECLARE VARIABLE CURRENCY DM_ID;
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE OBJECT0 DM_ID;
DECLARE VARIABLE OBJECT1 DM_ID;
DECLARE VARIABLE OBJECT2 DM_ID;
DECLARE VARIABLE STRING DM_STRING;
BEGIN
    STRING = 'SELECT ENTRIES.ID, ENTRY_BASE_STRINGS.NOTE, ENTRY_BASES.ORDINAL, CURRENCY, EXCHANGE_RATE, CONTENT,
        SINGLE.SIDE, SINGLE.ACCOUNT, SINGLE.OBJECT0, SINGLE.OBJECT1, SINGLE.OBJECT2,
        SINGLE.AMOUNT, SINGLE.PRICE, SINGLE.FOREIGN_SUM_OF_MONEY, SINGLE.OFFICIAL_SUM_OF_MONEY,
        DOCUMENTS.ID, CODE || ''-'' || NUMBER, INPUT_DATE, ORIGINAL_VOUCHERS, VOUCHER_DATE
        FROM ENTRIES
        JOIN ENTRY_BASES ON ENTRY_BASES.COMPANY = ' || :P_COMPANY || ' AND ENTRY_BASES.ID = ENTRIES.ID
        JOIN ENTRY_BASE_STRINGS ON ENTRY_BASE_STRINGS.COMPANY = ' || :P_COMPANY || ' AND ENTRY_BASE_STRINGS.LANGUAGE = ' || :P_LANGUAGE || ' AND ENTRY_BASE_STRINGS.ID = ENTRY_BASES.ID
        JOIN CREDIT_DEBIT SINGLE ON SINGLE.COMPANY = ' || :P_COMPANY || ' AND SINGLE.ENTRY = ENTRIES.ID
        JOIN DOCUMENTS ON DOCUMENTS.COMPANY = ' || :P_COMPANY || ' AND DOCUMENTS.ID = ENTRIES.DOCUMENT
        WHERE ENTRIES.ENTRY_TYPE = 0 AND ENTRIES.COMPANY = ' || :P_COMPANY || ' AND ' || :P_WHERE;

    FOR
        EXECUTE STATEMENT STRING
        INTO :ID, :NOTE, :ORDINAL, :CURRENCY, :EXCHANGE_RATE, :CONTENT,
        :SIDE, :ACCOUNT, :OBJECT0, :OBJECT1, :OBJECT2,
        :AMOUNT, :PRICE, :FOREIGN_SUM_OF_MONEY, :OFFICIAL_SUM_OF_MONEY,
        :DOCUMENT, :CODE, :INPUT_DATE, :ORIGINAL_VOUCHERS, :VOUCHER_DATE
    DO
    BEGIN
        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :CURRENCY
        INTO :CURRENCY_CODE;

        SELECT CODE
        FROM ATOMS
        WHERE COMPANY = :P_COMPANY AND ID = :ACCOUNT
        INTO :ACCOUNT_CODE;

        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :OBJECT0
            INTO :OBJECT0_CODE;

        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :OBJECT1
            INTO :OBJECT1_CODE;

        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE COMPANY = :P_COMPANY AND ID = :OBJECT2
            INTO :OBJECT2_CODE;

        SUSPEND;
    END
END ^

