    UPDATE OR INSERT INTO SOURCE_ACCOUNTS(ID, COMPANY, ACCOUNT, TRANSFER_ALL, DOCUMENT_CONTENT, PERIOD, OBJECT0, OBJECT1, OBJECT2)
    VALUES(:P_ID, :P_COMPANY, :P_ACCOUNT, :P_TRANSFER_ALL, :P_DOCUMENT_CONTENT, :P_PERIOD, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
