ALTER PROCEDURE SOURCE_ACCOUNT_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_PERIOD DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
ACCOUNT DM_ID,
OBJECT0 DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT1 DM_ID,
OBJECT1_CODE DM_CODE,
OBJECT2 DM_ID,
OBJECT2_CODE DM_CODE,
TRANSFER_ALL DM_BOOL,
DOCUMENT_CONTENT DM_CONTENT)
AS 
BEGIN
    FOR
        SELECT SOURCE_ACCOUNTS.ID, NOTE, ORDINAL, ACCOUNT, TRANSFER_ALL, DOCUMENT_CONTENT,
        OBJECT0, OBJECT1, OBJECT2
        FROM SOURCE_ACCOUNTS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = SOURCE_ACCOUNTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        WHERE SOURCE_ACCOUNTS.COMPANY = :P_COMPANY AND SOURCE_ACCOUNTS.PERIOD = :P_PERIOD
        INTO :ID, :NOTE, :ORDINAL, :ACCOUNT, :TRANSFER_ALL, :DOCUMENT_CONTENT,
        :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT0
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE;

        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT1
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE;

        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :OBJECT2
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
            INTO :OBJECT2_CODE;

        SUSPEND;
    END
END ^

