    UPDATE OR INSERT INTO TARGET_ACCOUNTS(ID, COMPANY, SOURCE_ACCOUNT, ACCOUNT, PERCENT, TARGET_PERCENT, TRANSFER_TYPE, OBJECT0, OBJECT1, OBJECT2)
    VALUES(:P_ID, :P_COMPANY, :P_SOURCE_ACCOUNT, :P_ACCOUNT, :P_PERCENT, :P_TARGET_PERCENT, :P_TRANSFER_TYPE, :P_OBJECT0, :P_OBJECT1, :P_OBJECT2);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
