ALTER PROCEDURE TARGET_ACCOUNT_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_SOURCE_ACCOUNT DM_ID)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
ACCOUNT DM_ID,
OBJECT0 DM_ID,
OBJECT0_CODE DM_CODE,
OBJECT1 DM_ID,
OBJECT1_CODE DM_CODE,
OBJECT2 DM_ID,
OBJECT2_CODE DM_CODE,
PERCENT DM_DOUBLE,
TARGET_PERCENT DM_ID,
TRANSFER_TYPE DM_TRANSFER_TYPE,
CRITERIA_ACCOUNTS DM_NOTE)
AS 
BEGIN
    FOR
        SELECT TARGET_ACCOUNTS.ID, NOTE, ORDINAL, ACCOUNT, IIF(TARGET_ACCOUNTS.TARGET_PERCENT IS NULL, TARGET_ACCOUNTS.PERCENT, TARGET_PERCENTS.PERCENT), TARGET_PERCENT, TRANSFER_TYPE,
        OBJECT0, OBJECT1, OBJECT2
        FROM TARGET_ACCOUNTS
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TARGET_ACCOUNTS.ID
        JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
        LEFT JOIN TARGET_PERCENTS ON TARGET_PERCENTS.COMPANY = :P_COMPANY AND TARGET_PERCENTS.ID = TARGET_ACCOUNTS.TARGET_PERCENT
        WHERE TARGET_ACCOUNTS.COMPANY = :P_COMPANY AND TARGET_ACCOUNTS.SOURCE_ACCOUNT = :P_SOURCE_ACCOUNT
        INTO :ID, :NOTE, :ORDINAL, :ACCOUNT, :PERCENT, :TARGET_PERCENT, :TRANSFER_TYPE,
        :OBJECT0, :OBJECT1, :OBJECT2
    DO
    BEGIN
        IF(OBJECT0 IS NULL)THEN
            OBJECT0_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT0
            INTO :OBJECT0_CODE;

        IF(OBJECT1 IS NULL)THEN
            OBJECT1_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT1
            INTO :OBJECT1_CODE;

        IF(OBJECT2 IS NULL)THEN
            OBJECT2_CODE = NULL;
        ELSE
            SELECT CODE
            FROM ATOMS
            WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :OBJECT2
            INTO :OBJECT2_CODE;

        SELECT LIST(ATOMS.CODE, ',')
        FROM TARGET_ACCOUNT_CRITERIA
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = TARGET_ACCOUNT_CRITERIA.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID
        WHERE TARGET_ACCOUNT_CRITERIA.COMPANY = :P_COMPANY AND TARGET_ACCOUNT_CRITERIA.TARGET_ACCOUNT = :ID
        INTO :CRITERIA_ACCOUNTS;

        SUSPEND;
    END
END ^

