ALTER PROCEDURE TEST_CONVERT_ACCOUNT (P_FROM_COMPANY DM_ID,
P_TO_COMPANY DM_ID,
P_FROM_PERIOD DM_ID,
P_ONLY_DOCUMENTS DM_INTEGER)
RETURNS (OK DM_BOOL,
NOTE DM_NOTE)
AS 
declare variable from_date dm_date;
declare variable from_account dm_id;
declare variable from_account_code dm_code;
declare variable from_atom_type_0 dm_id;
declare variable from_atom_type_1 dm_id;
declare variable to_account dm_id;
declare variable to_account_code dm_code;
declare variable to_atom_type_0 dm_id;
declare variable to_atom_type_1 dm_id;
BEGIN
    SELECT PERIODS.BEGINNING_DATE
    FROM PERIODS
    WHERE PERIODS.COMPANY = :P_FROM_COMPANY AND ID = :P_FROM_PERIOD
    INTO :FROM_DATE;

    OK = 1;

    FOR
        SELECT ACCOUNT, ATOMS.CODE, ACCOUNTS.ATOM_TYPE_0, ACCOUNTS.ATOM_TYPE_1
        FROM
        (
            SELECT BALANCES.ACCOUNT
            FROM BALANCES
            WHERE BALANCES.COMPANY = :P_FROM_COMPANY AND BALANCES.PERIOD = :P_FROM_PERIOD

            UNION ALL

            SELECT CREDIT_DEBIT.ACCOUNT
            FROM DOCUMENTS
            JOIN ENTRIES ON ENTRIES.COMPANY = :P_FROM_COMPANY AND ENTRIES.DOCUMENT = DOCUMENTS.ID
            JOIN CREDIT_DEBIT ON CREDIT_DEBIT.COMPANY = :P_FROM_COMPANY AND CREDIT_DEBIT.ENTRY = ENTRIES.ID
            WHERE DOCUMENTS.COMPANY = :P_FROM_COMPANY AND DOCUMENTS.INPUT_DATE >= :FROM_DATE
            
            UNION ALL 
                
            SELECT ASSETS.ASSET_ACCOUNT AS ACCOUNT
            FROM ASSETS
            WHERE ASSETS.COMPANY = :P_FROM_COMPANY AND ASSETS.ASSET_ACCOUNT IS NOT NULL
                
            UNION ALL 
                
            SELECT ASSETS.DEPRECIATION_ACCOUNT AS ACCOUNT
            FROM ASSETS
            WHERE ASSETS.COMPANY = :P_FROM_COMPANY AND ASSETS.DEPRECIATION_ACCOUNT IS NOT NULL
                
            UNION ALL 
                
            SELECT PREPAID_EXPENSES.ACCOUNT
            FROM PREPAID_EXPENSES
            WHERE PREPAID_EXPENSES.COMPANY = :P_FROM_COMPANY AND PREPAID_EXPENSES.ACCOUNT IS NOT NULL
                
            UNION ALL 
                
            SELECT PREPAID_EXPENSES.ACCOUNT_EXPENSE AS ACCOUNT
            FROM PREPAID_EXPENSES
            WHERE PREPAID_EXPENSES.COMPANY = :P_FROM_COMPANY AND PREPAID_EXPENSES.ACCOUNT_EXPENSE IS NOT NULL
        ) A
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_FROM_COMPANY AND ACCOUNTS.ID = A.ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_FROM_COMPANY AND ATOMS.ID = A.ACCOUNT AND ATOMS.CODE NOT STARTING WITH '0'
        GROUP BY ACCOUNT, ATOMS.CODE, ACCOUNTS.ATOM_TYPE_0, ACCOUNTS.ATOM_TYPE_1
        INTO :FROM_ACCOUNT, :FROM_ACCOUNT_CODE, :FROM_ATOM_TYPE_0, :FROM_ATOM_TYPE_1
    DO
    BEGIN
        FOR
            SELECT TO_ACCOUNT
            FROM ACCOUNT_TO_ACCOUNT
            WHERE ACCOUNT_TO_ACCOUNT.FROM_COMPANY = :P_FROM_COMPANY AND
                ACCOUNT_TO_ACCOUNT.FROM_ACCOUNT = :FROM_ACCOUNT AND
                ACCOUNT_TO_ACCOUNT.TO_COMPANY = :P_TO_COMPANY AND
                ACCOUNT_TO_ACCOUNT.TO_ACCOUNT IS NOT NULL
            INTO :TO_ACCOUNT
        DO
        BEGIN
            if(p_only_documents = 2)then
            begin
                UPDATE ACCOUNTS
                SET ACCOUNTS.ATOM_TYPE_0 = (SELECT SOURCE.ATOM_TYPE_0 FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :FROM_ACCOUNT),
                ACCOUNTS.ATOM_TYPE_1 = (SELECT SOURCE.ATOM_TYPE_1 FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :FROM_ACCOUNT),
                ACCOUNTS.MUST_HAVE_OBJECT = (SELECT SOURCE.MUST_HAVE_OBJECT FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :FROM_ACCOUNT),
                ACCOUNTS.BALANCE_TYPE = (SELECT SOURCE.BALANCE_TYPE FROM ACCOUNTS SOURCE WHERE SOURCE.COMPANY = :P_FROM_COMPANY AND SOURCE.ID = :FROM_ACCOUNT)
                WHERE ACCOUNTS.COMPANY = :P_TO_COMPANY AND ACCOUNTS.ID = :TO_ACCOUNT;
            end
        END

        TO_ACCOUNT = NULL;

        SELECT TO_ACCOUNT, ATOMS.CODE, ACCOUNTS.ATOM_TYPE_0, ACCOUNTS.ATOM_TYPE_1
        FROM ACCOUNT_TO_ACCOUNT
        JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_TO_COMPANY AND ACCOUNTS.ID = ACCOUNT_TO_ACCOUNT.TO_ACCOUNT
        JOIN ATOMS ON ATOMS.COMPANY = :P_TO_COMPANY AND ATOMS.ID = ACCOUNT_TO_ACCOUNT.TO_ACCOUNT
        WHERE ACCOUNT_TO_ACCOUNT.FROM_COMPANY = :P_FROM_COMPANY AND ACCOUNT_TO_ACCOUNT.FROM_ACCOUNT = :FROM_ACCOUNT AND
            ACCOUNT_TO_ACCOUNT.TO_COMPANY = :P_TO_COMPANY
        INTO :TO_ACCOUNT, :TO_ACCOUNT_CODE, :TO_ATOM_TYPE_0, :TO_ATOM_TYPE_1;

        OK = 1;

        IF(TO_ACCOUNT IS NULL)THEN
        BEGIN
            NOTE = FROM_ACCOUNT_CODE || ' >>> chua co';
            OK = 0;
        END
        ELSE
        BEGIN
            NOTE = FROM_ACCOUNT_CODE || ' >>> ' || TO_ACCOUNT_CODE;

            IF(FROM_ATOM_TYPE_0 <> TO_ATOM_TYPE_0)THEN
            BEGIN
                NOTE = NOTE || ': Khong dung doi tuong 1';
                OK = 0;
            END
            ELSE IF(FROM_ATOM_TYPE_1 <> TO_ATOM_TYPE_1)THEN
            BEGIN
                NOTE = NOTE || ': Khong dung doi tuong 2';
                OK = 0;
            END
        END

        IF(OK = 0)THEN
        BEGIN
            SUSPEND;
            BREAK;
        END
    END

    IF(OK = 1)THEN  SUSPEND;
END ^

ALTER PROCEDURE TEXT_IU (P_ID DM_ID,
P_CONTENT_VN DM_MESSAGE_CONTENT,
P_CONTENT_EN DM_MESSAGE_CONTENT,
P_CONTENT_OT DM_MESSAGE_CONTENT)
AS 
BEGIN
    UPDATE OR INSERT INTO TEXTS(ID, CONTENT, LANGUAGE)
    VALUES(:P_ID, :P_CONTENT_VN, 0);

    UPDATE OR INSERT INTO TEXTS(ID, CONTENT, LANGUAGE)
    VALUES(:P_ID, :P_CONTENT_EN, 1);

    UPDATE OR INSERT INTO TEXTS(ID, CONTENT, LANGUAGE)
    VALUES(:P_ID, :P_CONTENT_OT, 2);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, 0);
END ^

ALTER PROCEDURE TEXT_S_ID (P_ID DM_ID,
P_LANGUAGE DM_SMALLINT)
RETURNS (CONTENT DM_MESSAGE_CONTENT)
AS 
BEGIN
    SELECT CONTENT
    FROM TEXTS
    WHERE ID = :P_ID AND LANGUAGE = :P_LANGUAGE
    INTO :CONTENT;

    SUSPEND;
END ^

ALTER PROCEDURE THROW_EXCEPTION (P_GDSCODE DM_INTEGER,
P_LANGUAGE DM_SMALLINT)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
begin
    SELECT TITLE || '\$' || CONTENT
    FROM MESSAGES
    WHERE ID = :P_GDSCODE AND LANGUAGE = :P_LANGUAGE
    INTO :MESSAGE_CONTENT;

    IF(:MESSAGE_CONTENT IS NULL)THEN
        MESSAGE_CONTENT = 'Phan mem TONY\$';

    EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || :P_GDSCODE || ')';
end ^

ALTER PROCEDURE THROW_EXCEPTION_ATOM (P_SQLCODE DM_INTEGER,
P_LANGUAGE DM_SMALLINT,
P_CODE DM_CODE,
P_OBJECT_TYPE DM_BIGINT)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
begin
    SELECT NAME || ' "' || :P_CODE || '" '
    FROM OBJECT_TYPES
    WHERE ID = :P_OBJECT_TYPE
    INTO :MESSAGE_CONTENT;

    SELECT TITLE || '\$' || :MESSAGE_CONTENT || CONTENT
    FROM MESSAGES
    WHERE ID = :P_SQLCODE AND LANGUAGE = :P_LANGUAGE
    INTO :MESSAGE_CONTENT;

    IF(MESSAGE_CONTENT IS NULL)THEN
        MESSAGE_CONTENT = 'Phan mem TONY\$';

    EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || :P_SQLCODE || ')';
end ^

ALTER PROCEDURE THROW_EXCEPTION_INFO (P_SQLCODE DM_INTEGER,
P_LANGUAGE DM_SMALLINT,
P_INFO DM_NAME)
AS 
DECLARE VARIABLE MESSAGE_CONTENT DM_MESSAGE_CONTENT;
begin
    SELECT TITLE || '\$' || :P_INFO || ' ' || CONTENT
    FROM MESSAGES
    WHERE ID = :P_SQLCODE AND LANGUAGE = :P_LANGUAGE
    INTO :MESSAGE_CONTENT;

    IF(MESSAGE_CONTENT IS NULL)THEN
        MESSAGE_CONTENT = 'Phan mem TONY\$' || :P_INFO;

    EXCEPTION EX_GENERAL MESSAGE_CONTENT || '(' || :P_SQLCODE || ')';
end ^

