P_ORDINAL DM_INTEGER,
P_FINANCIAL_REPORT_ITEM DM_ID,
P_TMBCTC DM_ID,
P_CONTENT DM_CONTENT,
P_CUOI_NAM_SO_LUONG DM_DOUBLE,
P_CUOI_NAM_GIA_TRI DM_DOUBLE,
P_DAU_NAM_SO_LUONG DM_DOUBLE,
P_DAU_NAM_GIA_TRI DM_DOUBLE)
AS 
