ALTER PROCEDURE TMBCTC_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_REPORT DM_ID,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER)
AS 
BEGIN
    SELECT TMBCTC.ID, NOTE, ORDINAL
    FROM TMBCTC
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.FROM_DATE = :P_FROM_DATE AND TMBCTC.TO_DATE = :P_TO_DATE AND TMBCTC.REPORT = :P_REPORT
    INTO :ID, :NOTE, :ORDINAL;

    IF(ID IS NULL)THEN
    BEGIN
        ID = GEN_ID(UNIVERSE, 1);
        ORDINAL = 0;
        EXECUTE PROCEDURE TMBCTC_IU(:P_LANGUAGE, :P_COMPANY, :ID, NULL, 0, :P_REPORT, :P_FROM_DATE, :P_TO_DATE);
    END

    SUSPEND;
END ^

