            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_THONG_TIN_BO_SUNG.COMPANY = :P_COMPANY

            UNION ALL

            SELECT NULL ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, NULL CONTENT,
                0 CUOI_NAM, 0 DAU_NAM
            FROM FINANCIAL_REPORTS
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = :P_REPORT
                AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER AND
                NOT EXISTS
                (
                    SELECT 1
                    FROM TMBCTC_THONG_TIN_BO_SUNG
                    JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_THONG_TIN_BO_SUNG.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                    WHERE TMBCTC_THONG_TIN_BO_SUNG.COMPANY = :P_COMPANY
                )
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT, :CUOI_NAM, :DAU_NAM
    DO
    BEGIN
        IF(ID IS NULL OR P_FORCE_CAL = 1)THEN
        BEGIN
            
            SELECT TEMP_FINANCIAL_REPORT.CURRENT_PERIOD, TEMP_FINANCIAL_REPORT.PREVIOUS_PERIOD
            FROM TEMP_FINANCIAL_REPORT
            WHERE TEMP_FINANCIAL_REPORT.ID = :FINANCIAL_REPORT_ITEM
            INTO :CUOI_NAM, :DAU_NAM;
        END

        IF(ID IS NULL)THEN ID = GEN_ID(UNIVERSE, 1);

        EXECUTE PROCEDURE TMBCTC_THONG_TIN_BO_SUNG_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT, DAU_NAM, CUOI_NAM);

        SUSPEND;
    END
END ^

ALTER PROCEDURE TMBCTC_THONG_TIN_CHUNG_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FINANCIAL_REPORT_ITEM DM_ID,
P_TMBCTC DM_ID,
P_CONTENT DM_CONTENT)
AS 
BEGIN
    EXECUTE PROCEDURE TMBCTC_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_FINANCIAL_REPORT_ITEM, :P_TMBCTC, :P_CONTENT);

    UPDATE OR INSERT INTO TMBCTC_THONG_TIN_CHUNG(ID, COMPANY)
    VALUES(:P_ID, :P_COMPANY);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE TMBCTC_THONG_TIN_CHUNG_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TMBCTC DM_ID,
P_REPORT DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FINANCIAL_REPORT_ITEM DM_ID,
FINANCIAL_REPORT_ITEM_CODE DM_CODE,
FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT)
AS 
DECLARE VARIABLE OUTPUT_PRICE_METHOD DM_OUTPUT_PRICE_METHOD;
BEGIN
    EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_REPORT, P_GROUP_IN_DESIGNER, P_TU_NGAY, P_DEN_NGAY);

    FOR
        SELECT A.ID, A.NOTE, A.ORDINAL, A.FINANCIAL_REPORT_ITEM, A.CODE, A.NAME, A.CONTENT
        FROM
        (
            SELECT TMBCTC_THONG_TIN_CHUNG.ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, CODE, NAME, CONTENT
            FROM TMBCTC_THONG_TIN_CHUNG
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_THONG_TIN_CHUNG.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_THONG_TIN_CHUNG.COMPANY = :P_COMPANY

            UNION ALL

            SELECT GEN_ID(UNIVERSE, 1) ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, DEFAULT_STRING CONTENT
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_THONG_TIN_CHUNG
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_THONG_TIN_CHUNG.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_THONG_TIN_CHUNG.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :P_TMBCTC AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT
    DO
    BEGIN
        IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-II-01' AND (CONTENT IS NULL OR CONTENT = ''))THEN
        BEGIN
            CONTENT = 'Bắt đầu từ ngày ' || EXTRACT(DAY FROM :P_TU_NGAY) || '/' || EXTRACT(MONTH FROM :P_TU_NGAY) || '/' || EXTRACT(YEAR FROM :P_TU_NGAY) || ' kết thúc vào ngày ' || EXTRACT(DAY FROM :P_DEN_NGAY) || '/' || EXTRACT(MONTH FROM :P_DEN_NGAY) || '/' || EXTRACT(YEAR FROM :P_DEN_NGAY);
        END

        IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-IV-02-2' OR FINANCIAL_REPORT_ITEM_CODE = 'TM-II-05-2')THEN
        BEGIN
            SELECT ACCOUNTING_SETTINGS.OUTPUT_PRICE_METHOD
            FROM ACCOUNTING_SETTINGS
            WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
            INTO :OUTPUT_PRICE_METHOD;

            IF(OUTPUT_PRICE_METHOD = 1)THEN
                CONTENT = 'Bình quân gia quyền';
            ELSE IF(OUTPUT_PRICE_METHOD = 2)THEN
                CONTENT = 'Bình quân cuối kỳ';
            ELSE IF(OUTPUT_PRICE_METHOD = 3)THEN
                CONTENT = 'Đích danh - Nhập trước xuất trước';
        END

        EXECUTE PROCEDURE TMBCTC_THONG_TIN_CHUNG_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT);

        SUSPEND;
    END
END ^

ALTER PROCEDURE TMBCTC_TSCD_HH_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FINANCIAL_REPORT_ITEM DM_ID,
P_TMBCTC DM_ID,
P_CONTENT DM_CONTENT,
P_NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE,
P_MAY_MOC_THIET_BI DM_DOUBLE,
P_PHUONG_TIEN_VAN_TAI DM_DOUBLE,
P_THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE,
P_TSCD_HUU_HINH_KHAC DM_DOUBLE,
P_TONG_CONG DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE TMBCTC_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_FINANCIAL_REPORT_ITEM, :P_TMBCTC, :P_CONTENT);

    UPDATE OR INSERT INTO TMBCTC_TSCD_HH(ID, COMPANY,
    NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH_KHAC, TONG_CONG)
    VALUES(:P_ID, :P_COMPANY,
    :P_NHA_CUA_VAT_KIEN_TRUC, :P_MAY_MOC_THIET_BI, :P_PHUONG_TIEN_VAN_TAI, :P_THIET_BI_DUNG_CU_QUAN_LY, :P_TSCD_HUU_HINH_KHAC, :P_TONG_CONG);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE TMBCTC_TSCD_HH_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TMBCTC DM_ID,
P_REPORT DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_FORCE_CAL DM_BOOL)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FINANCIAL_REPORT_ITEM DM_ID,
FINANCIAL_REPORT_ITEM_CODE DM_CODE,
FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT,
NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE,
MAY_MOC_THIET_BI DM_DOUBLE,
PHUONG_TIEN_VAN_TAI DM_DOUBLE,
THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE,
TSCD_HUU_HINH_KHAC DM_DOUBLE,
TONG_CONG DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNTING_SYSTEM DM_ACCOUNTING_SYSTEM;
DECLARE VARIABLE TSCD_HUU_HINH_KHAC_PREV DM_DOUBLE;
DECLARE VARIABLE TEMP DM_DOUBLE;
DECLARE VARIABLE TM48_TM_III_3_1_1 DM_DOUBLE;
DECLARE VARIABLE TM48_TM_III_3_1_4 DM_DOUBLE;
DECLARE VARIABLE TM48_TM_III_3_2_1 DM_DOUBLE;
DECLARE VARIABLE TM48_TM_III_3_2_4 DM_DOUBLE;
DECLARE VARIABLE NG_DAU_NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE;
DECLARE VARIABLE NG_DAU_MAY_MOC_THIET_BI DM_DOUBLE;
DECLARE VARIABLE NG_DAU_PHUONG_TIEN_VAN_TAI DM_DOUBLE;
DECLARE VARIABLE NG_DAU_THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE;
DECLARE VARIABLE NG_DAU_TSCD_HUU_HINH_KHAC DM_DOUBLE;
DECLARE VARIABLE NG_DAU_TONG_CONG DM_DOUBLE;

DECLARE VARIABLE NG_CUOI_NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE;
DECLARE VARIABLE NG_CUOI_MAY_MOC_THIET_BI DM_DOUBLE;
DECLARE VARIABLE NG_CUOI_PHUONG_TIEN_VAN_TAI DM_DOUBLE;
DECLARE VARIABLE NG_CUOI_THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE;
DECLARE VARIABLE NG_CUOI_TSCD_HUU_HINH_KHAC DM_DOUBLE;
DECLARE VARIABLE NG_CUOI_TONG_CONG DM_DOUBLE;

DECLARE VARIABLE KH_DAU_NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE;
DECLARE VARIABLE KH_DAU_MAY_MOC_THIET_BI DM_DOUBLE;
DECLARE VARIABLE KH_DAU_PHUONG_TIEN_VAN_TAI DM_DOUBLE;
DECLARE VARIABLE KH_DAU_THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE;
DECLARE VARIABLE KH_DAU_TSCD_HUU_HINH_KHAC DM_DOUBLE;
DECLARE VARIABLE KH_DAU_TONG_CONG DM_DOUBLE;

DECLARE VARIABLE KH_CUOI_NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE;
DECLARE VARIABLE KH_CUOI_MAY_MOC_THIET_BI DM_DOUBLE;
DECLARE VARIABLE KH_CUOI_PHUONG_TIEN_VAN_TAI DM_DOUBLE;
DECLARE VARIABLE KH_CUOI_THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE;
DECLARE VARIABLE KH_CUOI_TSCD_HUU_HINH_KHAC DM_DOUBLE;
DECLARE VARIABLE KH_CUOI_TONG_CONG DM_DOUBLE;
BEGIN
    IF(P_FORCE_CAL = 1 OR
        NOT EXISTS (
            SELECT 1
            FROM TMBCTC_TSCD_HH
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_HH.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            WHERE TMBCTC_TSCD_HH.COMPANY = :P_COMPANY
        )
    )THEN
    BEGIN
        EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_REPORT, P_GROUP_IN_DESIGNER, P_TU_NGAY, P_DEN_NGAY);
    END

    SELECT ACCOUNTING_SETTINGS.ACCOUNTING_SYSTEM
    FROM ACCOUNTING_SETTINGS
    WHERE ACCOUNTING_SETTINGS.COMPANY = :P_COMPANY
    INTO :ACCOUNTING_SYSTEM;

    FOR
        SELECT A.ID, A.NOTE, A.ORDINAL, A.FINANCIAL_REPORT_ITEM, A.CODE, A.NAME, A.CONTENT,
            NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH_KHAC, TONG_CONG
        FROM
        (
            SELECT TMBCTC_TSCD_HH.ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, CODE, NAME, CONTENT,
                NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH_KHAC, TONG_CONG
            FROM TMBCTC_TSCD_HH
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_HH.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_TSCD_HH.COMPANY = :P_COMPANY

            UNION ALL

            SELECT NULL ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, NULL CONTENT,
                0 NHA_CUA_VAT_KIEN_TRUC, 0 MAY_MOC_THIET_BI, 0 PHUONG_TIEN_VAN_TAI, 0 THIET_BI_DUNG_CU_QUAN_LY, 0 TSCD_HUU_HINH_KHAC, 0 TONG_CONG
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_TSCD_HH
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_HH.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_TSCD_HH.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :P_TMBCTC AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT,
            :NHA_CUA_VAT_KIEN_TRUC, :MAY_MOC_THIET_BI, :PHUONG_TIEN_VAN_TAI, :THIET_BI_DUNG_CU_QUAN_LY, :TSCD_HUU_HINH_KHAC, :TONG_CONG
    DO
    BEGIN
        IF(ID IS NULL OR P_FORCE_CAL = 1)THEN
        BEGIN
            IF(ACCOUNTING_SYSTEM = 1 OR ACCOUNTING_SYSTEM = 3)THEN 
            BEGIN
                 
                IF((FINANCIAL_REPORT_ITEM_CODE = 'TM-V-8-1-1' AND ACCOUNTING_SYSTEM = 1) OR (FINANCIAL_REPORT_ITEM_CODE = 'TM-V-9-1-1' AND ACCOUNTING_SYSTEM = 3))THEN
                BEGIN
                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2111', :P_TU_NGAY)
                    INTO :NHA_CUA_VAT_KIEN_TRUC;
                    IF(NHA_CUA_VAT_KIEN_TRUC IS NULL)THEN NHA_CUA_VAT_KIEN_TRUC = 0;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2112', :P_TU_NGAY)
                    INTO :MAY_MOC_THIET_BI;
                    IF(MAY_MOC_THIET_BI IS NULL)THEN MAY_MOC_THIET_BI = 0;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2113', :P_TU_NGAY)
                    INTO :PHUONG_TIEN_VAN_TAI;
                    IF(PHUONG_TIEN_VAN_TAI IS NULL)THEN PHUONG_TIEN_VAN_TAI = 0;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2114', :P_TU_NGAY)
                    INTO :THIET_BI_DUNG_CU_QUAN_LY;
                    IF(THIET_BI_DUNG_CU_QUAN_LY IS NULL)THEN THIET_BI_DUNG_CU_QUAN_LY = 0;

                    TSCD_HUU_HINH_KHAC = 0;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2115', :P_TU_NGAY)
                    INTO :TEMP;
                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2116', :P_TU_NGAY)
                    INTO :TEMP;
                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2117', :P_TU_NGAY)
                    INTO :TEMP;
                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2118', :P_TU_NGAY)
                    INTO :TEMP;
                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    
                    NG_DAU_NHA_CUA_VAT_KIEN_TRUC = NHA_CUA_VAT_KIEN_TRUC;
                    NG_DAU_MAY_MOC_THIET_BI = MAY_MOC_THIET_BI;
                    NG_DAU_PHUONG_TIEN_VAN_TAI = PHUONG_TIEN_VAN_TAI;
                    NG_DAU_THIET_BI_DUNG_CU_QUAN_LY = THIET_BI_DUNG_CU_QUAN_LY;
                    NG_DAU_TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC;
                    NG_DAU_TONG_CONG = NHA_CUA_VAT_KIEN_TRUC + MAY_MOC_THIET_BI + PHUONG_TIEN_VAN_TAI + THIET_BI_DUNG_CU_QUAN_LY + TSCD_HUU_HINH_KHAC;
                END
                
                ELSE IF((FINANCIAL_REPORT_ITEM_CODE = 'TM-V-8-1-6' AND ACCOUNTING_SYSTEM = 1) OR (FINANCIAL_REPORT_ITEM_CODE = 'TM-V-9-1-6' AND ACCOUNTING_SYSTEM = 3))THEN
                BEGIN
                    SELECT SUM_OF_MONEY
                    FROM INT_PS_CAP_TK_C(:p_COMPANY, '811', '2111', :P_TU_NGAY, :P_DEN_NGAY)
                    INTO :NHA_CUA_VAT_KIEN_TRUC;
                    IF(NHA_CUA_VAT_KIEN_TRUC IS NULL)THEN NHA_CUA_VAT_KIEN_TRUC = 0;

                    SELECT :NHA_CUA_VAT_KIEN_TRUC + SUM_OF_MONEY
                    FROM INT_PS_CAP_TK_C(:p_COMPANY, '214', '2111', :P_TU_NGAY, :P_DEN_NGAY)
                    INTO :NHA_CUA_VAT_KIEN_TRUC;
                    IF(NHA_CUA_VAT_KIEN_TRUC IS NULL)THEN NHA_CUA_VAT_KIEN_TRUC = 0;

                    SELECT SUM_OF_MONEY
                    FROM INT_PS_CAP_TK_C(:p_COMPANY, '811', '2112', :P_TU_NGAY, :P_DEN_NGAY)
                    INTO :MAY_MOC_THIET_BI;
