                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2112'
                    INTO :MAY_MOC_THIET_BI;

                    IF(MAY_MOC_THIET_BI IS NULL)THEN MAY_MOC_THIET_BI = 0;

                    SELECT SUM(CREDIT)
                    FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2113'
                    INTO :PHUONG_TIEN_VAN_TAI;

                    IF(PHUONG_TIEN_VAN_TAI IS NULL)THEN PHUONG_TIEN_VAN_TAI = 0;

                    SELECT SUM(CREDIT)
                    FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2114'
                    INTO :THIET_BI_DUNG_CU_QUAN_LY;

                    IF(THIET_BI_DUNG_CU_QUAN_LY IS NULL)THEN THIET_BI_DUNG_CU_QUAN_LY = 0;

                    TSCD_HUU_HINH_KHAC = 0;

                    SELECT SUM(CREDIT)
                    FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2115'
                    INTO :TEMP;

                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    SELECT SUM(CREDIT)
                    FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2116'
                    INTO :TEMP;

                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    SELECT SUM(CREDIT)
                    FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2117'
                    INTO :TEMP;

                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    SELECT SUM(CREDIT)
                    FROM INT_SD_1_TK_DT0_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    JOIN ACCOUNTS ON ACCOUNTS.COMPANY = :P_COMPANY AND ACCOUNTS.ID = ASSETS.ASSET_ACCOUNT
                    JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = ACCOUNTS.ID AND ATOMS.CODE = '2118'
                    INTO :TEMP;

                    IF(TEMP IS NULL)THEN TEMP = 0;
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC + TEMP;

                    
                    KH_CUOI_NHA_CUA_VAT_KIEN_TRUC = NHA_CUA_VAT_KIEN_TRUC;
                    KH_CUOI_MAY_MOC_THIET_BI = MAY_MOC_THIET_BI;
                    KH_CUOI_PHUONG_TIEN_VAN_TAI = PHUONG_TIEN_VAN_TAI;
                    KH_CUOI_THIET_BI_DUNG_CU_QUAN_LY = THIET_BI_DUNG_CU_QUAN_LY;
                    KH_CUOI_TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC;
                    KH_CUOI_TONG_CONG = NHA_CUA_VAT_KIEN_TRUC + MAY_MOC_THIET_BI + PHUONG_TIEN_VAN_TAI + THIET_BI_DUNG_CU_QUAN_LY + TSCD_HUU_HINH_KHAC;
                END
                 
                ELSE IF((FINANCIAL_REPORT_ITEM_CODE = 'TM-V-8-3-1' AND ACCOUNTING_SYSTEM = 1) OR (FINANCIAL_REPORT_ITEM_CODE = 'TM-V-9-3-1' AND ACCOUNTING_SYSTEM = 3))THEN
                BEGIN
                    NHA_CUA_VAT_KIEN_TRUC = NG_DAU_NHA_CUA_VAT_KIEN_TRUC - KH_DAU_NHA_CUA_VAT_KIEN_TRUC;
                    MAY_MOC_THIET_BI = NG_DAU_MAY_MOC_THIET_BI - KH_DAU_MAY_MOC_THIET_BI;
                    PHUONG_TIEN_VAN_TAI = NG_DAU_PHUONG_TIEN_VAN_TAI - KH_DAU_PHUONG_TIEN_VAN_TAI;
                    THIET_BI_DUNG_CU_QUAN_LY = NG_DAU_THIET_BI_DUNG_CU_QUAN_LY - KH_DAU_THIET_BI_DUNG_CU_QUAN_LY;
                    TSCD_HUU_HINH_KHAC = NG_DAU_TSCD_HUU_HINH_KHAC - KH_DAU_TSCD_HUU_HINH_KHAC;
                    TONG_CONG = NG_DAU_TONG_CONG - KH_DAU_TONG_CONG;
                END
                 
                ELSE IF((FINANCIAL_REPORT_ITEM_CODE = 'TM-V-8-3-2' AND ACCOUNTING_SYSTEM = 1) OR (FINANCIAL_REPORT_ITEM_CODE = 'TM-V-9-3-2' AND ACCOUNTING_SYSTEM = 3))THEN
                BEGIN
                    NHA_CUA_VAT_KIEN_TRUC = NG_CUOI_NHA_CUA_VAT_KIEN_TRUC - KH_CUOI_NHA_CUA_VAT_KIEN_TRUC;
                    MAY_MOC_THIET_BI = NG_CUOI_MAY_MOC_THIET_BI - KH_CUOI_MAY_MOC_THIET_BI;
                    PHUONG_TIEN_VAN_TAI = NG_CUOI_PHUONG_TIEN_VAN_TAI - KH_CUOI_PHUONG_TIEN_VAN_TAI;
                    THIET_BI_DUNG_CU_QUAN_LY = NG_CUOI_THIET_BI_DUNG_CU_QUAN_LY - KH_CUOI_THIET_BI_DUNG_CU_QUAN_LY;
                    TSCD_HUU_HINH_KHAC = NG_CUOI_TSCD_HUU_HINH_KHAC - KH_CUOI_TSCD_HUU_HINH_KHAC;
                    TONG_CONG = NG_CUOI_TONG_CONG - KH_CUOI_TONG_CONG;
                END
            END
            ELSE
            BEGIN
                IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-1-1')THEN
                BEGIN
                    SELECT DEBIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2111', :P_TU_NGAY)
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;

                    TM48_TM_III_3_1_1 = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-1-2')THEN
                BEGIN
                    SELECT SUM(DEBIT)
                    FROM INT_PS_1_TK_DT0_C(:P_COMPANY, '2111', :P_TU_NGAY, :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;
                    TSCD_HUU_HINH_KHAC_PREV = TSCD_HUU_HINH_KHAC;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-1-2-1' OR FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-1-3-1')THEN
                BEGIN
                    TSCD_HUU_HINH_KHAC = TSCD_HUU_HINH_KHAC_PREV;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-1-3')THEN
                BEGIN
                    SELECT SUM(CREDIT)
                    FROM INT_PS_1_TK_DT0_C(:P_COMPANY, '2111', :P_TU_NGAY, :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;
                    TSCD_HUU_HINH_KHAC_PREV = TSCD_HUU_HINH_KHAC;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-1-4')THEN
                BEGIN
                    SELECT DEBIT
                    FROM INT_SD_1_TK_CN_C(:P_COMPANY, '2111', :P_DEN_NGAY)
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;

                    TM48_TM_III_3_1_4 = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-2-1')THEN 
                BEGIN
                    SELECT CREDIT
                    FROM INT_SD_1_TK_DN_C(:P_COMPANY, '2141', :P_TU_NGAY)
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;

                    TM48_TM_III_3_2_1 = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-2-2')THEN 
                BEGIN
                    SELECT SUM(CREDIT)
                    FROM INT_PS_1_TK_DT0_C(:P_COMPANY, '2141', :P_TU_NGAY, :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-2-3')THEN 
                BEGIN
                    SELECT SUM(DEBIT)
                    FROM INT_PS_1_TK_DT0_C(:P_COMPANY, '2141', :P_TU_NGAY, :P_DEN_NGAY)
                    JOIN ASSETS ON ASSETS.COMPANY = :P_COMPANY AND ASSETS.ID = OBJECT0
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-2-4')THEN 
                BEGIN
                    SELECT CREDIT
                    FROM INT_SD_1_TK_CN_C(:P_COMPANY, '2141', :P_DEN_NGAY)
                    INTO :TSCD_HUU_HINH_KHAC;

                    IF(TSCD_HUU_HINH_KHAC IS NULL)THEN TSCD_HUU_HINH_KHAC = 0;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;

                    TM48_TM_III_3_2_4 = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-3-1')THEN
                BEGIN
                    TSCD_HUU_HINH_KHAC = TM48_TM_III_3_1_1 - TM48_TM_III_3_2_1;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;
                END
                ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-III-3-3-2')THEN
                BEGIN
                    TSCD_HUU_HINH_KHAC = TM48_TM_III_3_1_4 - TM48_TM_III_3_2_4;

                    TONG_CONG = TSCD_HUU_HINH_KHAC;
                END
            END

            TONG_CONG = NHA_CUA_VAT_KIEN_TRUC + MAY_MOC_THIET_BI + PHUONG_TIEN_VAN_TAI + THIET_BI_DUNG_CU_QUAN_LY + TSCD_HUU_HINH_KHAC;
        END

        IF(ID IS NULL)THEN ID = GEN_ID(UNIVERSE, 1);

        EXECUTE PROCEDURE TMBCTC_TSCD_HH_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT, NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH_KHAC, TONG_CONG);

        SUSPEND;
    END
END ^

ALTER PROCEDURE TMBCTC_TSCD_TTC_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FINANCIAL_REPORT_ITEM DM_ID,
P_TMBCTC DM_ID,
P_CONTENT DM_CONTENT,
P_NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE,
P_MAY_MOC_THIET_BI DM_DOUBLE,
P_PHUONG_TIEN_VAN_TAI DM_DOUBLE,
P_THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE,
P_TSCD_HUU_HINH DM_DOUBLE,
P_TSCD_VO_HINH DM_DOUBLE,
P_TONG_CONG DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE TMBCTC_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_FINANCIAL_REPORT_ITEM, :P_TMBCTC, :P_CONTENT);

    UPDATE OR INSERT INTO TMBCTC_TSCD_TTC(ID, COMPANY,
    NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH, TSCD_VO_HINH, TONG_CONG)
    VALUES(:P_ID, :P_COMPANY,
    :P_NHA_CUA_VAT_KIEN_TRUC, :P_MAY_MOC_THIET_BI, :P_PHUONG_TIEN_VAN_TAI, :P_THIET_BI_DUNG_CU_QUAN_LY, :P_TSCD_HUU_HINH, :P_TSCD_VO_HINH, :P_TONG_CONG);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE TMBCTC_TSCD_TTC_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TMBCTC DM_ID,
P_REPORT DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_FORCE_CAL DM_BOOL)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FINANCIAL_REPORT_ITEM DM_ID,
FINANCIAL_REPORT_ITEM_CODE DM_CODE,
FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT,
NHA_CUA_VAT_KIEN_TRUC DM_DOUBLE,
MAY_MOC_THIET_BI DM_DOUBLE,
PHUONG_TIEN_VAN_TAI DM_DOUBLE,
THIET_BI_DUNG_CU_QUAN_LY DM_DOUBLE,
TSCD_HUU_HINH DM_DOUBLE,
TSCD_VO_HINH DM_DOUBLE,
TONG_CONG DM_DOUBLE)
AS 
BEGIN
    IF(P_FORCE_CAL = 1 OR
        NOT EXISTS (
            SELECT 1
            FROM TMBCTC_TSCD_TTC
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_TTC.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            WHERE TMBCTC_TSCD_TTC.COMPANY = :P_COMPANY
        )
    )THEN
    BEGIN
        EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_REPORT, P_GROUP_IN_DESIGNER, P_TU_NGAY, P_DEN_NGAY);
    END

    FOR
        SELECT A.ID, A.NOTE, A.ORDINAL, A.FINANCIAL_REPORT_ITEM, A.CODE, A.NAME, A.CONTENT,
            NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH, TSCD_VO_HINH, TONG_CONG
        FROM
        (
            SELECT TMBCTC_TSCD_TTC.ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, CODE, NAME, CONTENT,
                NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH, TSCD_VO_HINH, TONG_CONG
            FROM TMBCTC_TSCD_TTC
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_TTC.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_TSCD_TTC.COMPANY = :P_COMPANY

            UNION ALL

            SELECT NULL ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, NULL CONTENT,
                0 NHA_CUA_VAT_KIEN_TRUC, 0 MAY_MOC_THIET_BI, 0 PHUONG_TIEN_VAN_TAI, 0 THIET_BI_DUNG_CU_QUAN_LY, 0 TSCD_HUU_HINH, 0 TSCD_VO_HINH, 0 TONG_CONG
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_TSCD_TTC
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_TTC.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_TSCD_TTC.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :P_TMBCTC AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT,
            :NHA_CUA_VAT_KIEN_TRUC, :MAY_MOC_THIET_BI, :PHUONG_TIEN_VAN_TAI, :THIET_BI_DUNG_CU_QUAN_LY, :TSCD_HUU_HINH, :TSCD_VO_HINH, :TONG_CONG
    DO
    BEGIN
        IF(ID IS NULL)THEN
        BEGIN
            


            ID = GEN_ID(UNIVERSE, 1);
        END

        EXECUTE PROCEDURE TMBCTC_TSCD_TTC_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT, NHA_CUA_VAT_KIEN_TRUC, MAY_MOC_THIET_BI, PHUONG_TIEN_VAN_TAI, THIET_BI_DUNG_CU_QUAN_LY, TSCD_HUU_HINH, TSCD_VO_HINH, TONG_CONG);

        SUSPEND;
    END
END ^

