    VALUES(:P_ID, :P_COMPANY,
    :P_QUYEN_SU_DUNG_DAT, :P_QUYEN_PHAT_HANH, :P_BAN_QUYEN_BANG_SANG_CHE, :P_NHAN_HIEU_HANG_HOA, :P_PHAN_MEM_MAY_TINH, :P_GIAY_PHEP_NHUONG_QUYEN, :P_TSCD_VO_HINH_KHAC, :P_TONG_CONG);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE TMBCTC_TSCD_VH_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TMBCTC DM_ID,
P_REPORT DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_FORCE_CAL DM_BOOL)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FINANCIAL_REPORT_ITEM DM_ID,
FINANCIAL_REPORT_ITEM_CODE DM_CODE,
FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT,
QUYEN_SU_DUNG_DAT DM_DOUBLE,
QUYEN_PHAT_HANH DM_DOUBLE,
BAN_QUYEN_BANG_SANG_CHE DM_DOUBLE,
NHAN_HIEU_HANG_HOA DM_DOUBLE,
PHAN_MEM_MAY_TINH DM_DOUBLE,
GIAY_PHEP_NHUONG_QUYEN DM_DOUBLE,
TSCD_VO_HINH_KHAC DM_DOUBLE,
TONG_CONG DM_DOUBLE)
AS 
BEGIN
    IF(P_FORCE_CAL = 1 OR
        NOT EXISTS (
            SELECT 1
            FROM TMBCTC_TSCD_VH
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_VH.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            WHERE TMBCTC_TSCD_VH.COMPANY = :P_COMPANY
        )
    )THEN
    BEGIN
        EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_REPORT, P_GROUP_IN_DESIGNER, P_TU_NGAY, P_DEN_NGAY);
    END

    FOR
        SELECT A.ID, A.NOTE, A.ORDINAL, A.FINANCIAL_REPORT_ITEM, A.CODE, A.NAME, A.CONTENT,
            QUYEN_SU_DUNG_DAT, QUYEN_PHAT_HANH, BAN_QUYEN_BANG_SANG_CHE, NHAN_HIEU_HANG_HOA, PHAN_MEM_MAY_TINH, GIAY_PHEP_NHUONG_QUYEN, TSCD_VO_HINH_KHAC, TONG_CONG
        FROM
        (
            SELECT TMBCTC_TSCD_VH.ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, CODE, NAME, CONTENT,
                QUYEN_SU_DUNG_DAT, QUYEN_PHAT_HANH, BAN_QUYEN_BANG_SANG_CHE, NHAN_HIEU_HANG_HOA, PHAN_MEM_MAY_TINH, GIAY_PHEP_NHUONG_QUYEN, TSCD_VO_HINH_KHAC, TONG_CONG
            FROM TMBCTC_TSCD_VH
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_VH.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_TSCD_VH.COMPANY = :P_COMPANY

            UNION ALL

            SELECT NULL ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, NULL CONTENT,
                0 QUYEN_SU_DUNG_DAT, 0 QUYEN_PHAT_HANH, 0 BAN_QUYEN_BANG_SANG_CHE, 0 NHAN_HIEU_HANG_HOA, 0 PHAN_MEM_MAY_TINH, 0 GIAY_PHEP_NHUONG_QUYEN, 0 TSCD_VO_HINH_KHAC, 0 TONG_CONG
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_TSCD_VH
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_TSCD_VH.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_TSCD_VH.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :P_TMBCTC AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT,
            :QUYEN_SU_DUNG_DAT, :QUYEN_PHAT_HANH, :BAN_QUYEN_BANG_SANG_CHE, :NHAN_HIEU_HANG_HOA, :PHAN_MEM_MAY_TINH, :GIAY_PHEP_NHUONG_QUYEN, :TSCD_VO_HINH_KHAC, :TONG_CONG
    DO
    BEGIN
        IF(ID IS NULL)THEN
        BEGIN
            


            ID = GEN_ID(UNIVERSE, 1);
        END

        EXECUTE PROCEDURE TMBCTC_TSCD_VH_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT, QUYEN_SU_DUNG_DAT, QUYEN_PHAT_HANH, BAN_QUYEN_BANG_SANG_CHE, NHAN_HIEU_HANG_HOA, PHAN_MEM_MAY_TINH, GIAY_PHEP_NHUONG_QUYEN, TSCD_VO_HINH_KHAC, TONG_CONG);

        SUSPEND;
    END
END ^

ALTER PROCEDURE TMBCTC_VON_CHU_SO_HUU_48_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FINANCIAL_REPORT_ITEM DM_ID,
P_TMBCTC DM_ID,
P_CONTENT DM_CONTENT,
P_DAU_KY DM_DOUBLE,
P_TANG_TRONG_KY DM_DOUBLE,
P_GIAM_TRONG_KY DM_DOUBLE,
P_CUOI_KY DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE TMBCTC_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_FINANCIAL_REPORT_ITEM, :P_TMBCTC, :P_CONTENT);

    UPDATE OR INSERT INTO TMBCTC_VON_CHU_SO_HUU_48(ID, COMPANY,
        DAU_KY, TANG_TRONG_KY, GIAM_TRONG_KY, CUOI_KY)
    VALUES(:P_ID, :P_COMPANY,
        :P_DAU_KY, :P_TANG_TRONG_KY, :P_GIAM_TRONG_KY, :P_CUOI_KY);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE TMBCTC_VON_CHU_SO_HUU_48_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TMBCTC DM_ID,
P_REPORT DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_FORCE_CAL DM_BOOL)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FINANCIAL_REPORT_ITEM DM_ID,
FINANCIAL_REPORT_ITEM_CODE DM_CODE,
FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT,
DAU_KY DM_DOUBLE,
TANG_TRONG_KY DM_DOUBLE,
GIAM_TRONG_KY DM_DOUBLE,
CUOI_KY DM_DOUBLE)
AS 
DECLARE VARIABLE ACCOUNT DM_ID;
DECLARE VARIABLE ACCOUNT_CODE DM_CODE;
DECLARE VARIABLE TANG_TRONG_KY_TEMP DM_DOUBLE;
DECLARE VARIABLE GIAM_TRONG_KY_TEMP DM_DOUBLE;
BEGIN
    IF(P_FORCE_CAL = 1 OR
        NOT EXISTS (
            SELECT 1
            FROM TMBCTC_VON_CHU_SO_HUU_48
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_VON_CHU_SO_HUU_48.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            WHERE TMBCTC_VON_CHU_SO_HUU_48.COMPANY = :P_COMPANY
        )
    )THEN
    BEGIN
        EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_REPORT, P_GROUP_IN_DESIGNER, P_TU_NGAY, P_DEN_NGAY);
    END

    FOR
        SELECT A.ID, A.NOTE, A.ORDINAL, A.FINANCIAL_REPORT_ITEM, A.CODE, A.NAME, A.CONTENT,
            DAU_KY, TANG_TRONG_KY, GIAM_TRONG_KY, CUOI_KY
        FROM
        (
            SELECT TMBCTC_VON_CHU_SO_HUU_48.ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, CODE, NAME, CONTENT,
                DAU_KY, TANG_TRONG_KY, GIAM_TRONG_KY, CUOI_KY
            FROM TMBCTC_VON_CHU_SO_HUU_48
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_VON_CHU_SO_HUU_48.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_VON_CHU_SO_HUU_48.COMPANY = :P_COMPANY

            UNION ALL

            SELECT NULL ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, NULL CONTENT,
                0 DAU_KY, 0 TANG_TRONG_KY, 0 GIAM_TRONG_KY, 0 CUOI_KY
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_VON_CHU_SO_HUU_48
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_VON_CHU_SO_HUU_48.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_VON_CHU_SO_HUU_48.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :P_TMBCTC AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT,
            :DAU_KY, :TANG_TRONG_KY, :GIAM_TRONG_KY, :CUOI_KY
    DO
    BEGIN
        IF(ID IS NULL OR P_FORCE_CAL = 1)THEN
        BEGIN
            
            SELECT TEMP_FINANCIAL_REPORT.CURRENT_PERIOD, TEMP_FINANCIAL_REPORT.PREVIOUS_PERIOD
            FROM TEMP_FINANCIAL_REPORT
            WHERE TEMP_FINANCIAL_REPORT.ID = :FINANCIAL_REPORT_ITEM
            INTO :CUOI_KY, :DAU_KY;

            GIAM_TRONG_KY = 0;
            TANG_TRONG_KY = 0;

            FOR
                SELECT ACCOUNT
                FROM FINANCIAL_BALANCES
                WHERE FINANCIAL_BALANCES.COMPANY = :P_COMPANY AND FINANCIAL_BALANCES.FINANCIAL_REPORT = :FINANCIAL_REPORT_ITEM
                INTO :ACCOUNT
            DO
            BEGIN
                SELECT CODE
                FROM ATOMS
                WHERE ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :ACCOUNT
                INTO :ACCOUNT_CODE;

                SELECT DEBIT, CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, :ACCOUNT_CODE, :P_TU_NGAY, :P_DEN_NGAY)
                INTO :GIAM_TRONG_KY_TEMP, :TANG_TRONG_KY_TEMP;

                GIAM_TRONG_KY = GIAM_TRONG_KY + GIAM_TRONG_KY_TEMP;
                TANG_TRONG_KY = TANG_TRONG_KY + TANG_TRONG_KY_TEMP;
            END
        END

        IF(ID IS NULL)THEN ID = GEN_ID(UNIVERSE, 1);

        EXECUTE PROCEDURE TMBCTC_VON_CHU_SO_HUU_48_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT, DAU_KY, TANG_TRONG_KY, GIAM_TRONG_KY, CUOI_KY);

        SUSPEND;
    END
END ^

ALTER PROCEDURE TMBCTC_VON_CHU_SO_HUU_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_FINANCIAL_REPORT_ITEM DM_ID,
P_TMBCTC DM_ID,
