P_VON_DAU_TU DM_DOUBLE,
P_THANG_DU_VON_CP DM_DOUBLE,
P_VON_KHAC DM_DOUBLE,
P_CO_PHIEU_QUY DM_DOUBLE,
P_CHENH_LECH_DANH_GIA_TS DM_DOUBLE,
P_CHENH_LECH_TY_GIA DM_DOUBLE,
P_NGUON_VON_DAU_TU_XDCB DM_DOUBLE,
P_TONG_CONG DM_DOUBLE)
AS 
BEGIN
    EXECUTE PROCEDURE TMBCTC_BASE_IU(:P_LANGUAGE, :P_COMPANY, :P_ID, :P_NOTE, :P_ORDINAL, :P_FINANCIAL_REPORT_ITEM, :P_TMBCTC, :P_CONTENT);

    UPDATE OR INSERT INTO TMBCTC_VON_CHU_SO_HUU(ID, COMPANY,
        VON_DAU_TU, THANG_DU_VON_CP, VON_KHAC, CO_PHIEU_QUY, CHENH_LECH_DANH_GIA_TS, CHENH_LECH_TY_GIA, NGUON_VON_DAU_TU_XDCB, TONG_CONG)
    VALUES(:P_ID, :P_COMPANY,
        :P_VON_DAU_TU, :P_THANG_DU_VON_CP, :P_VON_KHAC, :P_CO_PHIEU_QUY, :P_CHENH_LECH_DANH_GIA_TS, :P_CHENH_LECH_TY_GIA, :P_NGUON_VON_DAU_TU_XDCB, :P_TONG_CONG);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION(SQLCODE, :P_LANGUAGE);
END ^

ALTER PROCEDURE TMBCTC_VON_CHU_SO_HUU_S_EC (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_TMBCTC DM_ID,
P_REPORT DM_ID,
P_GROUP_IN_DESIGNER DM_GROUP_IN_DESIGNER,
P_TU_NGAY DM_DATE,
P_DEN_NGAY DM_DATE,
P_FORCE_CAL DM_BOOL)
RETURNS (ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
FINANCIAL_REPORT_ITEM DM_ID,
FINANCIAL_REPORT_ITEM_CODE DM_CODE,
FINANCIAL_REPORT_ITEM_NAME DM_NAME,
CONTENT DM_CONTENT,
VON_DAU_TU DM_DOUBLE,
THANG_DU_VON_CP DM_DOUBLE,
VON_KHAC DM_DOUBLE,
CO_PHIEU_QUY DM_DOUBLE,
CHENH_LECH_DANH_GIA_TS DM_DOUBLE,
CHENH_LECH_TY_GIA DM_DOUBLE,
NGUON_VON_DAU_TU_XDCB DM_DOUBLE,
TONG_CONG DM_DOUBLE)
AS 
DECLARE VARIABLE TU_NGAY_KY_TRUOC DM_DATE;
DECLARE VARIABLE DEN_NGAY_KY_TRUOC DM_DATE;
BEGIN
    DEN_NGAY_KY_TRUOC = DATEADD(DAY, -1, P_TU_NGAY);
    TU_NGAY_KY_TRUOC = EXTRACT(YEAR FROM DEN_NGAY_KY_TRUOC) || '.' || (EXTRACT(MONTH FROM DEN_NGAY_KY_TRUOC) - DATEDIFF(MONTH, P_TU_NGAY, P_DEN_NGAY)) || '.1';

    IF(P_FORCE_CAL = 1 OR
        NOT EXISTS (
            SELECT 1
            FROM TMBCTC_VON_CHU_SO_HUU
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_VON_CHU_SO_HUU.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            WHERE TMBCTC_VON_CHU_SO_HUU.COMPANY = :P_COMPANY
        )
    )THEN
    BEGIN
        EXECUTE PROCEDURE INT_CAL_BAO_CAO_TAI_CHINH(P_LANGUAGE, P_COMPANY, P_REPORT, P_GROUP_IN_DESIGNER, P_TU_NGAY, P_DEN_NGAY);
    END

    FOR
        SELECT A.ID, A.NOTE, A.ORDINAL, A.FINANCIAL_REPORT_ITEM, A.CODE, A.NAME, A.CONTENT,
            VON_DAU_TU, THANG_DU_VON_CP, VON_KHAC, CO_PHIEU_QUY, CHENH_LECH_DANH_GIA_TS, CHENH_LECH_TY_GIA, NGUON_VON_DAU_TU_XDCB, TONG_CONG
        FROM
        (
            SELECT TMBCTC_VON_CHU_SO_HUU.ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, CODE, NAME, CONTENT,
                VON_DAU_TU, THANG_DU_VON_CP, VON_KHAC, CO_PHIEU_QUY, CHENH_LECH_DANH_GIA_TS, CHENH_LECH_TY_GIA, NGUON_VON_DAU_TU_XDCB, TONG_CONG
            FROM TMBCTC_VON_CHU_SO_HUU
            JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_VON_CHU_SO_HUU.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC
            JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TMBCTC_BASE.ID
            JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.ID = TMBCTC_BASE.FINANCIAL_REPORT_ITEM AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC_VON_CHU_SO_HUU.COMPANY = :P_COMPANY

            UNION ALL

            SELECT NULL ID, NULL NOTE, 0 ORDINAL, FINANCIAL_REPORTS.ID FINANCIAL_REPORT_ITEM, CODE, NAME, NULL CONTENT,
                0 VON_DAU_TU, 0 THANG_DU_VON_CP, 0 VON_KHAC, 0 CO_PHIEU_QUY, 0 CHENH_LECH_DANH_GIA_TS, 0 CHENH_LECH_TY_GIA, 0 NGUON_VON_DAU_TU_XDCB, 0 TONG_CONG
            FROM TMBCTC
            JOIN FINANCIAL_REPORTS ON FINANCIAL_REPORTS.COMPANY = :P_COMPANY AND FINANCIAL_REPORTS.REPORT = TMBCTC.REPORT AND
            NOT EXISTS (
                SELECT 1
                FROM TMBCTC_VON_CHU_SO_HUU
                JOIN TMBCTC_BASE ON TMBCTC_BASE.COMPANY = :P_COMPANY AND TMBCTC_BASE.ID = TMBCTC_VON_CHU_SO_HUU.ID AND TMBCTC_BASE.TMBCTC = :P_TMBCTC AND TMBCTC_BASE.FINANCIAL_REPORT_ITEM = FINANCIAL_REPORTS.ID
                WHERE TMBCTC_VON_CHU_SO_HUU.COMPANY = :P_COMPANY)
            JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = FINANCIAL_REPORTS.ID
            JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = ATOMS.ID
            WHERE TMBCTC.COMPANY = :P_COMPANY AND TMBCTC.ID = :P_TMBCTC AND BIN_AND(FINANCIAL_REPORTS.GROUP_IN_DESIGNER, :P_GROUP_IN_DESIGNER) = :P_GROUP_IN_DESIGNER
        ) A
        JOIN PROTONS FINANCIAL_REPORT_ITEM_PROTONS ON FINANCIAL_REPORT_ITEM_PROTONS.COMPANY = :P_COMPANY AND FINANCIAL_REPORT_ITEM_PROTONS.ID = FINANCIAL_REPORT_ITEM
        ORDER BY FINANCIAL_REPORT_ITEM_PROTONS.ORDINAL
        INTO :ID, :NOTE, :ORDINAL, :FINANCIAL_REPORT_ITEM, :FINANCIAL_REPORT_ITEM_CODE, :FINANCIAL_REPORT_ITEM_NAME, CONTENT,
            :VON_DAU_TU, :THANG_DU_VON_CP, :VON_KHAC, :CO_PHIEU_QUY, :CHENH_LECH_DANH_GIA_TS, :CHENH_LECH_TY_GIA, :NGUON_VON_DAU_TU_XDCB, :TONG_CONG
    DO
    BEGIN
        IF(ID IS NULL OR P_FORCE_CAL = 1)THEN
        BEGIN
            VON_DAU_TU = 0;
            THANG_DU_VON_CP = 0;
            VON_KHAC = 0;
            CO_PHIEU_QUY = 0;
            CHENH_LECH_DANH_GIA_TS = 0;
            CHENH_LECH_TY_GIA = 0;
            NGUON_VON_DAU_TU_XDCB = 0;
            TONG_CONG = 0;

            
            IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-1')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_SD_1_TK_DN_C(:P_COMPANY, '4111', :TU_NGAY_KY_TRUOC)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-1-1')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4111', :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-1-2')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4212', :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-1-4')THEN
            BEGIN
                SELECT DEBIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4111', :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-1-5')THEN
            BEGIN
                SELECT DEBIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4212', :TU_NGAY_KY_TRUOC, :DEN_NGAY_KY_TRUOC)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-2')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_SD_1_TK_CN_C(:P_COMPANY, '4111', :DEN_NGAY_KY_TRUOC)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-3')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_SD_1_TK_DN_C(:P_COMPANY, '4111', :P_TU_NGAY)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-3-1')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4111', :P_TU_NGAY, :P_DEN_NGAY)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-3-2')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4212', :P_TU_NGAY, :P_DEN_NGAY)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-3-4')THEN
            BEGIN
                SELECT DEBIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4111', :P_TU_NGAY, :P_DEN_NGAY)
                INTO :VON_DAU_TU;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-3-5')THEN
            BEGIN
                SELECT DEBIT
                FROM INT_PS_1_TK_C(:P_COMPANY, '4212', :P_TU_NGAY, :P_DEN_NGAY)
                INTO :VON_DAU_TU;
                IF(VON_DAU_TU IS NULL)THEN VON_DAU_TU = 0;
            END
            
            ELSE IF(FINANCIAL_REPORT_ITEM_CODE = 'TM-V-22-a-4')THEN
            BEGIN
                SELECT CREDIT
                FROM INT_SD_1_TK_CN_C(:P_COMPANY, '4111', :P_DEN_NGAY)
                INTO :VON_DAU_TU;
            END

            TONG_CONG = VON_DAU_TU;
        END

        IF(ID IS NULL)THEN ID = GEN_ID(UNIVERSE, 1);

        EXECUTE PROCEDURE TMBCTC_VON_CHU_SO_HUU_IU(P_LANGUAGE, P_COMPANY, ID, NOTE, ORDINAL, FINANCIAL_REPORT_ITEM, P_TMBCTC, CONTENT, VON_DAU_TU, THANG_DU_VON_CP, VON_KHAC, CO_PHIEU_QUY, CHENH_LECH_DANH_GIA_TS, CHENH_LECH_TY_GIA, NGUON_VON_DAU_TU_XDCB, TONG_CONG);

        SUSPEND;
    END
END ^

ALTER PROCEDURE TONY_GET_CURRENT_VERSION RETURNS (CURRENT_VERSION DM_VERSION)
AS 
BEGIN
