ALTER PROCEDURE TO_KHAI_GTGT_119_S_ER (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_DATE_SELECTION_TYPE DM_SELECTION_TYPES,
P_FROM_DATE DM_DATE,
P_TO_DATE DM_DATE,
P_IS_STORED DM_BOOL)
RETURNS (TAX_CODE DM_TAX_CODE,
ID DM_ID,
NOTE DM_NOTE,
ORDINAL DM_INTEGER,
IS_FIRST_TIME DM_BOOL,
ADDITIONAL_TIME DM_SMALLINT,
V21 DM_BOOL,
V22 DM_DOUBLE,
V23 DM_DOUBLE,
V24 DM_DOUBLE,
V25 DM_DOUBLE,
