V43 DM_DOUBLE,
SIGNED_DATE DM_DATE,
DIRECTOR DM_PERSON_NAME,
TAX_AGENT_STAFF DM_PERSON_NAME,
PRACTICING_CERTIFICATE DM_NAME)
AS 
DECLARE VARIABLE COMPANY_DIRECTOR DM_PERSON_NAME;
BEGIN
    SELECT DIRECTOR,
        IIF(TAX_CODE_1 IS NULL, '', TAX_CODE_1) ||
        IIF(TAX_CODE_2 IS NULL, '', TAX_CODE_2) ||
        IIF(TAX_CODE_3 IS NULL, '', TAX_CODE_3) ||
        IIF(TAX_CODE_4 IS NULL, '', TAX_CODE_4) ||
        IIF(TAX_CODE_5 IS NULL, '', TAX_CODE_5) ||
        IIF(TAX_CODE_6 IS NULL, '', TAX_CODE_6) ||
        IIF(TAX_CODE_7 IS NULL, '', TAX_CODE_7) ||
        IIF(TAX_CODE_8 IS NULL, '', TAX_CODE_8) ||
        IIF(TAX_CODE_9 IS NULL, '', TAX_CODE_9) ||
        IIF(TAX_CODE_10 IS NULL, '', TAX_CODE_10) ||
        IIF(TAX_CODE_11 IS NULL, '', TAX_CODE_11) ||
        IIF(TAX_CODE_12 IS NULL, '', TAX_CODE_12) ||
        IIF(TAX_CODE_13 IS NULL, '', TAX_CODE_13)
    FROM COMPANIES
    JOIN COMPANY_STRINGS ON COMPANY_STRINGS.LANGUAGE = :P_LANGUAGE AND COMPANY_STRINGS.ID = :P_COMPANY
    WHERE COMPANIES.ID = :P_COMPANY
    INTO :COMPANY_DIRECTOR, :TAX_CODE;

    SELECT TO_KHAI_GTGT_119.ID, NOTE, ORDINAL,
    IS_FIRST_TIME,
    ADDITIONAL_TIME,
    V21,
    V22,
    V23,
    V24,
    V25,
    V26,
    V27,
    V28,
    V29,
    V30,
    V31,
    V32,
    V33,
    V34,
    V35,
    V36,
    V37,
    V38,
    V39,
    V40A,
    V40B,
    V40,
    V41,
    V42,
    V43,
    SIGNED_DATE,
    DIRECTOR,
    TAX_AGENT_STAFF,
    PRACTICING_CERTIFICATE
    FROM TO_KHAI_GTGT_119
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TO_KHAI_GTGT_119.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE TO_KHAI_GTGT_119.COMPANY = :P_COMPANY AND TO_KHAI_GTGT_119.DATE_SELECTION_TYPE = :P_DATE_SELECTION_TYPE AND TO_KHAI_GTGT_119.FROM_DATE = :P_FROM_DATE AND TO_KHAI_GTGT_119.TO_DATE = :P_TO_DATE
    INTO :ID, :NOTE, :ORDINAL,
    :IS_FIRST_TIME,
    :ADDITIONAL_TIME,
    :V21,
    :V22,
    :V23,
    :V24,
    :V25,
    :V26,
    :V27,
    :V28,
    :V29,
    :V30,
    :V31,
    :V32,
    :V33,
    :V34,
    :V35,
    :V36,
    :V37,
    :V38,
    :V39,
    :V40A,
    :V40B,
    :V40,
    :V41,
    :V42,
    :V43,
    :SIGNED_DATE,
    :DIRECTOR,
    :TAX_AGENT_STAFF,
    :PRACTICING_CERTIFICATE;

    IF(ID IS NULL OR P_IS_STORED = 0)THEN
    BEGIN
        IF(ID IS NULL)THEN
            ID = GEN_ID(UNIVERSE, 1);

        ORDINAL = 0;
        IS_FIRST_TIME = 1;
        ADDITIONAL_TIME = 0;
        SIGNED_DATE = CURRENT_DATE;
        DIRECTOR = COMPANY_DIRECTOR;

        
        SELECT
        V21,
        V22,
        V23,
        V24,
        V25,
        V26,
        V27,
        V28,
        V29,
        V30,
        V31,
        V32,
        V33,
        V34,
        V35,
        V36,
        V37,
        V38,
        V39,
        V40A,
        V40B,
        V40,
        V41,
        V42,
        V43
        FROM INT_TO_KHAI_THUE_GTGT_119(:P_LANGUAGE, :P_COMPANY, 0, :P_FROM_DATE, :P_TO_DATE)
        INTO
        :V21,
        :V22,
        :V23,
        :V24,
        :V25,
        :V26,
        :V27,
        :V28,
        :V29,
        :V30,
        :V31,
        :V32,
        :V33,
        :V34,
        :V35,
        :V36,
        :V37,
        :V38,
        :V39,
        :V40A,
        :V40B,
        :V40,
        :V41,
        :V42,
        :V43;
    END

    SUSPEND;
END ^

