    V18,
    V19,
    V20,
    V21,
    V22,
    V23,
    V24,
    V25,
    V26,
    V27,
    V28,
    V29,
    V30,
    V31,
    V32,
    V33,
    V34,
    V35,
    V36,
    V37,
    V38,
    V39,
    V40,
    V41,
    V42,
    V43,
    SIGNED_DATE,
    DIRECTOR
    FROM TO_KHAI_GTGT
    JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = TO_KHAI_GTGT.ID
    JOIN PROTON_STRINGS ON PROTON_STRINGS.COMPANY = :P_COMPANY AND PROTON_STRINGS.LANGUAGE = :P_LANGUAGE AND PROTON_STRINGS.ID = PROTONS.ID
    WHERE TO_KHAI_GTGT.COMPANY = :P_COMPANY AND TO_KHAI_GTGT.DATE_SELECTION_TYPE = :P_DATE_SELECTION_TYPE AND TO_KHAI_GTGT.FROM_DATE = :P_FROM_DATE AND TO_KHAI_GTGT.TO_DATE = :P_TO_DATE
    INTO :ID, :NOTE, :ORDINAL,
    :V10,
    :V11,
    :V12,
    :V13,
    :V14,
    :V15,
    :V16,
    :V17,
    :V18,
    :V19,
    :V20,
    :V21,
    :V22,
    :V23,
    :V24,
    :V25,
    :V26,
    :V27,
    :V28,
    :V29,
    :V30,
    :V31,
    :V32,
    :V33,
    :V34,
    :V35,
    :V36,
    :V37,
    :V38,
    :V39,
    :V40,
    :V41,
    :V42,
    :V43,
    :SIGNED_DATE,
    :DIRECTOR;

    IF(ID IS NULL OR P_IS_STORED = 0)THEN
    BEGIN
        IF(ID IS NULL)THEN
            ID = GEN_ID(UNIVERSE, 1);

        ORDINAL = 0;
        SIGNED_DATE = CURRENT_DATE;
        DIRECTOR = COMPANY_DIRECTOR;

        
        SELECT
        V10,
        V11,
        V12,
        V13,
        V14,
        V15,
        V16,
        V17,
        V18,
        V19,
        V20,
        V21,
        V22,
        V23,
        V24,
        V25,
        V26,
        V27,
        V28,
        V29,
        V30,
        V31,
        V32,
        V33,
        V34,
        V35,
        V36,
        V37,
        V38,
        V39,
        V40,
        V41,
        V42,
        V43
        FROM INT_TO_KHAI_THUE_GTGT(:P_LANGUAGE, :P_COMPANY, 0, :P_FROM_DATE, :P_TO_DATE)
        INTO
        :V10,
        :V11,
        :V12,
        :V13,
        :V14,
        :V15,
        :V16,
        :V17,
        :V18,
        :V19,
        :V20,
        :V21,
        :V22,
        :V23,
        :V24,
        :V25,
        :V26,
        :V27,
        :V28,
        :V29,
        :V30,
        :V31,
