        :V34,
        :V35,
        :V36,
        :V37,
        :V38,
        :V39,
        :V40,
        :V41,
        :V42,
        :V43;
    END

    SUSPEND;
END ^

ALTER PROCEDURE USER_ACCOUNT_CHECK (P_LANGUAGE DM_ID,
P_COMPANY DM_ID,
P_ID DM_ID,
P_PASS_WORD DM_PASSWORD)
RETURNS (NAME DM_NAME)
AS 
BEGIN
    FOR
        SELECT NAME
        FROM USER_ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = :P_ID
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = :P_COMPANY AND ATOM_STRINGS.LANGUAGE = :P_LANGUAGE AND ATOM_STRINGS.ID = :P_ID
        JOIN PROTONS ON PROTONS.COMPANY = :P_COMPANY AND PROTONS.ID = :P_ID
        WHERE USER_ACCOUNTS.COMPANY = :P_COMPANY AND USER_ACCOUNTS.ID = :P_ID AND USER_ACCOUNTS.PASS_WORD = :P_PASS_WORD
        INTO :NAME
    DO
        SUSPEND;
END ^

ALTER PROCEDURE USER_ACCOUNT_IU (P_LANGUAGE DM_SMALLINT,
P_COMPANY DM_ID,
P_ID DM_ID,
P_NOTE DM_NOTE,
P_ORDINAL DM_INTEGER,
P_CODE DM_CODE,
P_HIDE DM_BOOL,
P_NAME DM_NAME,
P_PARENT DM_ID,
P_TEAM DM_ID,
P_RELATED_OBJECT DM_ID,
P_OBJECT_TYPE DM_ID)
AS 
BEGIN
    IF(P_HIDE = 1 AND NOT EXISTS(
        SELECT USER_ACCOUNTS.ID
        FROM USER_ACCOUNTS
        JOIN ATOMS ON ATOMS.COMPANY = :P_COMPANY AND ATOMS.ID = USER_ACCOUNTS.ID AND ATOMS.HIDE = 0
        WHERE USER_ACCOUNTS.COMPANY = :P_COMPANY AND USER_ACCOUNTS.ID <> :P_ID)
    )THEN
        P_HIDE = 0;
    
    EXECUTE PROCEDURE ATOM_IU(:P_LANGUAGE, :P_COMPANY,:P_ID, :P_NOTE, :P_ORDINAL, :P_CODE, :P_HIDE, :P_NAME,:P_PARENT, :P_TEAM, :P_RELATED_OBJECT, :P_OBJECT_TYPE);

    UPDATE OR INSERT INTO USER_ACCOUNTS(COMPANY, ID)
    VALUES(:P_COMPANY, :P_ID);

    WHEN ANY DO EXECUTE PROCEDURE THROW_EXCEPTION_ATOM(SQLCODE, :P_LANGUAGE, :P_CODE, :P_OBJECT_TYPE);
END ^

