/* Triggers only will work for SQL triggers */
CREATE TRIGGER ACCESSORIES_AD0 FOR ACCESSORIES 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  DELETE FROM PROTONS
  WHERE COMPANY = OLD.COMPANY AND ID = OLD.ID;
end ^

CREATE TRIGGER ACCOUNTING_SETTINGS_AU0 FOR ACCOUNTING_SETTINGS 
ACTIVE AFTER UPDATE POSITION 0 
AS
BEGIN
    
    IF(
        (OLD.DOCUMENT_CODE_CYCLE <> NEW.DOCUMENT_CODE_CYCLE) OR
        (OLD.BEGINNING_PERIOD <> NEW.BEGINNING_PERIOD)
    )THEN
    BEGIN
        DELETE FROM DOCUMENT_TEAM_NUMBER
        WHERE DOCUMENT_TEAM_NUMBER.COMPANY = NEW.COMPANY;
    END
END ^

CREATE TRIGGER ACCOUNT_TO_ACCOUNT_AD0 FOR ACCOUNT_TO_ACCOUNT 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  DELETE FROM PROTONS
  WHERE COMPANY = OLD.TO_COMPANY AND ID = OLD.ID;
end ^

CREATE TRIGGER APPORTIONMENT_ACCOUNTS_AD0 FOR APPORTIONMENT_ACCOUNTS 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  DELETE FROM PROTONS
  WHERE COMPANY = OLD.COMPANY AND ID = OLD.ID;
end ^

CREATE TRIGGER ASSET_DEPRECIATION_PERIODS_AD0 FOR ASSET_DEPRECIATION_PERIODS 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  DELETE FROM PROTONS
  WHERE COMPANY = OLD.COMPANY AND ID = OLD.ID;
end ^

CREATE TRIGGER ATOMS_AIUD0 FOR ATOMS 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
BEGIN
    IF(INSERTING)THEN
    BEGIN
        UPDATE OBJECT_TYPES
        SET VERSION_INSERT = IIF(VERSION_INSERT > 32000, 0, VERSION_INSERT + 1)
        WHERE ID = NEW.OBJECT_TYPE;
    END
    ELSE IF(UPDATING)THEN
    BEGIN
        UPDATE OBJECT_TYPES
        SET VERSION_UPDATE = IIF(VERSION_UPDATE > 32000, 0, VERSION_UPDATE + 1)
        WHERE ID = NEW.OBJECT_TYPE;
    END
    ELSE IF(DELETING)THEN
    BEGIN
        UPDATE OBJECT_TYPES
        SET VERSION_DELETE = IIF(VERSION_DELETE > 32000, 0, VERSION_DELETE + 1)
        WHERE ID = OLD.OBJECT_TYPE;
    END
END ^

CREATE TRIGGER BALANCES_AIUD0 FOR BALANCES 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
BEGIN
    IF(INSERTING OR UPDATING)THEN
    BEGIN
        UPDATE PERIODS
        SET CHANGED = 1
        WHERE PERIODS.COMPANY = NEW.COMPANY AND PERIODS.ID = NEW.PERIOD;
    END
    ELSE
    BEGIN
        UPDATE PERIODS
        SET CHANGED = 1
        WHERE PERIODS.COMPANY = OLD.COMPANY AND PERIODS.ID = OLD.PERIOD;
    END
END ^

