CREATE TRIGGER COST_PRICE_DEFINES_BI0 FOR COST_PRICE_DEFINES 
ACTIVE BEFORE INSERT POSITION 0 
AS
begin
    IF(NEW.DEFAULT_CONTENT IS NULL OR NEW.DEFAULT_CONTENT = '')THEN
    BEGIN
        SELECT ATOM_STRINGS.NAME
        FROM DOCUMENT_TEAMS
        JOIN ATOMS ON ATOMS.COMPANY = NEW.COMPANY AND ATOMS.ID = NEW.DOCUMENT_TEAM
        JOIN ATOM_STRINGS ON ATOM_STRINGS.COMPANY = NEW.COMPANY AND ATOM_STRINGS.LANGUAGE = 0 AND ATOM_STRINGS.ID = NEW.DOCUMENT_TEAM
        WHERE DOCUMENT_TEAMS.COMPANY = NEW.COMPANY AND DOCUMENT_TEAMS.ID = NEW.DOCUMENT_TEAM
        INTO NEW.DEFAULT_CONTENT;
    END
end ^

CREATE TRIGGER COST_PRICE_DEFINES_AD0 FOR COST_PRICE_DEFINES 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  DELETE FROM PROTONS
  WHERE COMPANY = OLD.COMPANY AND ID = OLD.ID;
end ^

CREATE TRIGGER DOCUMENTS_AIUD0 FOR DOCUMENTS 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
BEGIN
    IF(INSERTING)THEN
    BEGIN
        EXECUTE PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX(NEW.COMPANY, NEW.CODE, NEW.INPUT_DATE);
    END
    ELSE IF(UPDATING)THEN
    BEGIN
        IF(NEW.CODE = OLD.CODE)THEN
        BEGIN
            IF(NEW.NUMBER <> OLD.NUMBER)THEN
            BEGIN
                EXECUTE PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX(NEW.COMPANY, NEW.CODE, NEW.INPUT_DATE);
            END
        END
        ELSE
        BEGIN
            EXECUTE PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX(NEW.COMPANY, NEW.CODE, NEW.INPUT_DATE);

            EXECUTE PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX(NEW.COMPANY, OLD.CODE, NEW.INPUT_DATE);
        END
    END
    ELSE IF(DELETING)THEN
    BEGIN
        EXECUTE PROCEDURE DOCUMENT_TEAM_NUMBER_GET_MAX(OLD.COMPANY, OLD.CODE, OLD.INPUT_DATE);
    END
  END ^

CREATE TRIGGER DOCUMENTS_PERIOD_AIUD0 FOR DOCUMENTS 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
BEGIN
    IF(INSERTING OR UPDATING)THEN
    BEGIN
        UPDATE PERIODS
        SET CHANGED = 1
        WHERE CHANGED <> 1 AND PERIODS.COMPANY = NEW.COMPANY AND PERIODS.ID = NEW.PERIOD;
    END
    ELSE
    BEGIN
        UPDATE PERIODS
        SET CHANGED = 1
        WHERE CHANGED <> 1 AND PERIODS.COMPANY = OLD.COMPANY AND PERIODS.ID = OLD.PERIOD;
    END
END ^

