CREATE TRIGGER ENTRIES_AU0 FOR ENTRIES 
ACTIVE AFTER UPDATE POSITION 0 
as
begin
   
   
   
   IF(OLD.REVENUE_ENTRY IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ENTRIES WHERE ENTRIES.COMPANY = OLD.COMPANY AND ENTRIES.DOCUMENT = OLD.DOCUMENT))THEN
        DELETE FROM DOCUMENT_BASES WHERE COMPANY = OLD.COMPANY AND DOCUMENT_BASES.ID = OLD.DOCUMENT;
end ^

CREATE TRIGGER ENTRIES_AD0 FOR ENTRIES 
ACTIVE AFTER DELETE POSITION 0 
AS
BEGIN
    
    DELETE FROM ENTRY_BASES WHERE COMPANY = OLD.COMPANY AND ID = OLD.ID;

    
    

    
    IF(OLD.REVENUE_ENTRY IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ENTRIES WHERE ENTRIES.COMPANY = OLD.COMPANY AND ENTRIES.DOCUMENT = OLD.DOCUMENT))THEN
        DELETE FROM DOCUMENT_BASES WHERE COMPANY = OLD.COMPANY AND DOCUMENT_BASES.ID = OLD.DOCUMENT;
END ^

